// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":6,"question":"نحن عندنا الوقت متوفر، ولكن العزيمة قليلة، بينما السلف عكسنا تمامًا؛ فالعزيمة موجودة عندهم، والوقت عندهم قليل، ولم تكن عندهم وسائل التَّنقل السريع، أو البحث السريع، فما السبب في ضعف العزيمة؟ وكيف نُعالج هذا الضعف؟ أثابكم الله.","title":"ما علاج ضعف العزيمة في هذا العصر؟","answer":"الجواب: الوقت هو الوقت، ولكن اختلاف الإيمان واختلاف القلوب وكثرة المشاغل اليوم، وأسباب الخطر عندنا اليوم مشاغل ما كانت عند الأولين، وشرور ما كانت عند الأولين، مهيأة للإنسان بالطرق الكثيرة، فلا بدّ من حزمٍ وتشميرٍ، ولا بدّ من نشاطٍ متواصلٍ، ولا بدّ من سؤال الله الهداية والتوفيق، فالعبد مسكينٌ ضعيفٌ إلا بتوفيق الله.\nوالرسول عليه السلام يقول: احرص على ما ينفعك، واستعن بالله رواه مسلم في \"صحيحه\"  ورحمه.\nوعن أبي هريرة رضي الله تعالى عنه، عن النبي ﷺ أنه قال: المؤمن القوي خيرٌ وأحبُّ إلى الله من المؤمن الضَّعيف، وفي كلٍّ خيرٌ، احرص على ما ينفعك، واستعن بالله ولا تعجزنَّ، فإن أصابك شيءٌ فلا تقلّ: لو أني فعلتُ لكان كذا وكذا، ولكن قل: قدر الله وما شاء فعل، فإن \"لو\" تفتح عمل الشيطان.\nفعليك بالجدِّ والنشاط ومُحاسبة النفس واستغلال الوقت، فالوقت هو ليلٌ ونهارٌ كما كان للأولين ليلٌ ونهارٌ، ولكن الشأن في وجود البركة والتوفيق، والبُعد عن المشاغل التي تشغل قلبه، وتشغل البدن، وتشغل الجوارح.\nفعليك بالبُعد عن أسباب الشرِّ، والحذر من أسباب الشرِّ، وحفظ الوقت في طاعة الله، مع سؤال الله التوفيق والهداية، لا تغفل، فالعبد مسكينٌ، إن خُلي بينه وبين شيطانه ونفسه الأمَّارة بالسوء هلك، فلا بدّ من سؤال الله، تضرَّع إلى الله، واستعن بالله أن يُعينك على طاعته وذكره، وأن يُعينك من شرِّ نفسك وهواك وشيطانك، وأن يحفظ عليك وقتك.\nفاستعن بالله، واصدق، وأبشر بالخير، فمتى صدقتَ مع الله واتَّقيته أعانك جلَّ وعلا، كما قال سبحانه: وَإِنْ تَصْبِرُوا وَتَتَّقُوا لَا يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا [آل عمران:120]، والشيطان من الأعداء، فمَن صبر على طاعة الله، وترك محارم الله، واتَّقى الله؛ لم يضرّه عدوه، كفاه الله شرَّ عدوه.\nرزق الله الجميع التوفيق والهداية، وحفظ علينا وعليكم ديننا، وتوفَّانا جميعًا مسلمين، وعمَّر هذه الجامعة بالخير، ووفَّق القائمين عليها بكل خيرٍ.\nوصلَّى الله وسلَّم على نبينا محمدٍ وعلى آله وأصحابه.","link":"https://binbaz.org.sa/fatwas/2751/ما-علاج-ضعف-العزيمة-في-هذا-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0256.mp3","categories":["نصائح وتوجيهات"]},{"id":56,"question":"السؤال الأول: سماحة الشيخ كثير من الشباب يشغل نفسه بدقائق الأمور وجزئيات المسائل وقد نجده مُفَرِّطًا في أمور أخرى، ما نصيحتكم لمثل هذا الشاب؟","title":"حكم الخوض في الجزئيات ودقائق المسائل","answer":"الجواب: نصيحتي للجميع: العناية بالمهمات؛ بل العناية بأهم الأمور قبل المهمات، وأن يكون هدف الطالب البصيرة في دينه، لاسيما ما يتعلق بالعقيدة والعناية بها، والحرص على أن يكون في غاية البصيرة في عقيدته من الكتاب والسنة، وأن يعرف ما عليه أهل السنة والجماعة؛ حتى يلزم ذلك ويستقيم عليه. ثم العناية بمعرفة ما أوجب الله عليه وما حرم الله عليه قبل المستحبات؛ حتى يكون على بينة فيما أوجب الله وفيما حرم الله. ونصيحتي أيضًا لكل طالب علم ألا يتشاغل بالمستحبات أو المكروهات والنزاع في ذلك عما أوجب الله عليه من الفقه فيما أوجب الله عليه وفيما حرم عليه، فليعتنِ بالمهمات وما هو أقرب وألصق بالعقيدة قبل ما دون ذلك، ثم يعتني بالواجبات والمحرمات قبل المستحبات والمكروهات. فالحاصل أنه ينبغي أن يعتني بالأهم فالأهم، وأن يحرص على التفقه في دينه من جميع الوجوه؛ حتى يؤدي الواجب على بصيرة وحتى يدع المُحَرَّم على بصيرة، ولا يكون شغله النزاع مع زملائه في بعض المستحبات أو في بعض المكروهات مع جهله بما أوجب الله عليه وجهله بما حرم الله عليه أو ببعض ذلك.","link":"https://binbaz.org.sa/fatwas/2967/حكم-الخوض-في-الجزىيات-ودقاىق-المساىل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0031.mp3","categories":["نصائح وتوجيهات"]},{"id":229,"question":"عندما أكون في مخيم أو في رحلةٍ مع إخواني في الله أُحافظ على الصلاة، وخصوصًا صلاة الفجر، وكذلك السّنن، ولكن عندما أعود من المخيم أتكاسل عن صلاة الفجر، وكثيرًا ما أنام عن أدائها، وكذلك السّنن، فهل هذا من النِّفاق؟","title":"ما حكم من ينشط للعبادة مع الرفقة فقط؟","answer":"الجواب: هذا مثلما سمعتم أنه من الجفاء، هذا من الجفاء، هذا من الطرف الثاني، وهو الجفاء، الواجب أن تكون هكذا دائمًا، لا في المخيم، ولا مع أصحابك، بل دائمًا دائمًا تكون على نشاطٍ وهمَّةٍ عاليةٍ في أداء الواجبات: الصلاة في جماعةٍ -صلاة الفجر- مع الجماعة في صلاة الرواتب، هكذا يكون المؤمنُ في الواجبات، يجب في المُستحبَّات، يُشرع لك النشاط، يجب في الواجبات، ويُستحب في المندوبات.\nوالتَّساهل بصلاة الفجر من صفات أهل النفاق -نعوذ بالله- وهكذا بقية الصلوات، التساهل بالجماعة هذا من صفات أهل النفاق -نعوذ بالله: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلَاةِ قَامُوا كُسَالَى [النساء:142]، فكيف ترضى لنفسك أن تُشابه أعداء الله؟! لا ينبغي لك أن ترضى أن تُشابه أعداء الله، ولا يجوز لك، بل يجب أن تُبادر لصلاة الفجر مع الناس كبقية الصلوات.\nوإذا لم يكن عندك مَن يُوقظك تجعل ساعةً تُعينك وتسأل ربك العون وتُبَكِّر في النوم، لا تصيف في النوم، لا تسهر، وإذا سهرت ما سمعت الساعة ولا قمتَ لمَن يُوقظك، لكن إذا تقدمت للنوم وبكَّرتَ في النوم كان هذا عونًا على القيام، فاتَّقِ الله.\nفعلينا أن نتَّقي الله في هذا الأمر، ولا نتساهل فنسهر على الفيديو أو على التلفاز أو على شيءٍ آخر، فإذا جاء الفجرُ فإذا الإنسان جيفة ما يستطيع أن يقوم، هذا منكرٌ عظيمٌ، وتشبّه بأعداء الله المُنافقين، فالحذر، الحذر.","link":"https://binbaz.org.sa/fatwas/4081/ما-حكم-من-ينشط-للعبادة-مع-الرفقة-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0236.mp3","categories":["نصائح وتوجيهات"]},{"id":269,"question":"سائلٌ يقول: يهتم كثيرٌ من الشباب -بل من الكهول أيضًا- بتشجيع الأندية الرياضية بحماسٍ زائدٍ، مما يُحدث بينهم مُشاجرات وخصومات، بل وعداوات أيضًا ومُهاترات شخصية، فما توجيه سماحتكم لمثل هؤلاء؟ جزاكم الله خيرًا.","title":"ما النصيحة للمتعصبين للأندية الرياضية؟","answer":"لا شكَّ أنَّ هذا الحماس لهذه الأندية، الذي يُفضي إلى النزاع الكثير والشَّحناء والعداوة والسِّباب، لا شكَّ أنه منكرٌ؛ لأنَّ المقصود من الرياضة قوةُ البدن، والرياضة على هذا الشيء الذي يطلب من هذه الرياضة، وصلابة الأعضاء، وقوة الأعضاء، وقوة الأعصاب، وتحمّل المشاق، وتحمّل الأثقال، فلا ينبغي لأهلها أن يتسابّوا، أو يتشاحنوا، أو يتعصَّبوا، لا، فالواجب أن يكونوا إخوةً، هكذا أوجب الله عليهم، سواء نجح هذا أو رسب هذا، سواء فاز فريقُ فلانٍ، أو فريق فلانٍ، فهم إخوة مطلقًا، الفائز والذي لم يفز، الواجب ألا يكون بينهم إلا الكلام الطيب، والمُخاطبة بالتي هي أحسن، وعلاج الموضوعات المُشكلة بالحكمة والأسلوب الحسن، لا بالسب والشَّحناء والتَّهاتر والكلام البذيء.\nولا ينبغي أيضًا أن يفعلوا ما يقع في الأسواق الآن من التباريات والصياح وإيذاء الناس في الطُّرقات، هذا نوعٌ من الجنون، ونوعٌ من السَّفه الذي لا يرضاه عاقلٌ.\nفالذي ينبغي لهؤلاء الذين في النَّوادي أن يكونوا عقلاء، فمَن نجح فليحمد الله، ولا يتكبَّر على أخيه، أو يسخر على أخيه، أو يُؤذي أخاه أو غيره من الناس.\nوالأمر سهلٌ: نجحتَ أو ما نجحتَ! قتلت أعداء الله؟! قتلت الروس حتى تنجح؟! ماذا فعلت؟ أدخلتَ هذا بهذا؟! أيش قيمة هذا النجاح؟!\nلو كان الناس يعقلون: فلا ينبغي للعاقل أن يكون هذا النجاح مُسبِّبًا لشحناء، أو مُهاترات، أو إيذاء لأحدٍ، لا في الأسواق، ولا في غير الأسواق، يأتون في الأسواق في سياراتهم كأنَّهم مهابيل، هذا غلطٌ عظيمٌ لا يليق بالعقلاء أبدًا، الواجب أن يكونوا عقلاء في سياراتهم، وفي كلماتهم، وفي جميع أساليبهم، لا المغلوب، ولا الغالب، أما المغلوب ماذا عليه، والغالب ماذا فعل؟! ماذا حصل؟! أخرج اليهود من فلسطين؟! نصر الأفغانيين وقضى على الروس؟! ماذا فعل؟!\nكلها أشياء لا قيمةَ لها، ولكن نسأل الله لنا ولهم الهداية، نسأل الله أن يُعطيهم العقول الطيبة، والرأي الطيب السديد، والهداية التامَّة.","link":"https://binbaz.org.sa/fatwas/4265/ما-النصيحة-للمتعصبين-للاندية-الرياضية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0314.mp3","categories":["نصائح وتوجيهات"]},{"id":412,"question":"أنا شابٌّ أسكن في مبنى يتكون من شققٍ، وقد تبتُ إلى الله من المعاصي، إلا أنَّ جاري هداه الله أحضر خادمةً مسلمةً فاتنةً، وقد اشتغل قلبي بهذه الخادمة، وهي مُتبرجة، وحاولت نصحه فاتَّهمني بالتَّقصير، بماذا تنصحني جزاك الله خيرًا؟ علمًا بأنني إذا عملتُ هذه المعصية تفسد عليَّ الدين والدنيا، ولم أترك وسيلةً إلا عملتها، ومنها سؤال الإمام في المسجد الذي أُصلي به، وأنا متزوج؟","title":"ما النصيحة لمن يجلب خادمة مسلمة متبرجة؟","answer":"الجواب: أولًا أنصح إخواني جميعًا بالحذر من استيراد الخادمات، والحذر من استيراد الشَّابات والجميلات، وأن يحرص كل مؤمنٍ أن يكتفي بزوجته وأهل بيته في خدمة بيته، وأن يحذر استقدام هؤلاء الخادمات اللاتي انتشر استقدامهنَّ وشرّهن، فالوصية مني لإخواني جميعًا عدم استقدام الخادمات إلا عند الضَّرورة، ولا سيما إذا كان وحده وزوجته؛ فإنَّ خطرها عظيم، فقد يخلو بها، وقد تغيب زوجته فيحضر الشيطان وتحصل الفتنة، وقد يفتن بها جاره كما يسأل السائل الآن، قد يفتن بها جارَه وولده وأخاه وخادمه -إن كان عنده خادم أو سائق- فتقع البليةُ.\nفنصيحتي للجميع عدم استيراد الخادمات بالكلية مهما أمكن، إلا للضَّرورة القصوى، وإذا استقدم يستقدم مسلمةً كبيرة السن، بعيدة عن الجمال، ليس فيها جمال يجذب الناس إليها، بل تكون من النساء البعيدات عن الفتنة، كبيرات السن، مع القوة والعمل، لكن كبيرة السن مسلمة معروفة بالخير، فيُوصي وكيله أن يعتني بهذا الأمر، ولا سيما إذا كان في بيته نساء، إذا كانت في بيته أم وأخوات، فإنهن قد يُعِنَّ على كفِّها عن الباطل ومُراقبتها، ويكون ذلك أيضًا مع العناية بتسترها وعدم تبرجها، يلزمها بذلك، وإلا فليُبعدها.\nولا يستقدم كافرة؛ لا نصرانية..... هذه الجزيرة لا يُستقدم لها إلا مسلمون، فالرسول أمر بإخراج الكفار منها.\nوأنت أيها السائل عليك غضّ البصر، إذا ابتُليت لا تنظر إلى زوجة جارك، ولا خادمته، ولا بنته، غضّ بصرك، وأرخِ رأسك في الأرض إذا خرجت وإذا دخلت، واحذر أن تنظر إلى النساء، أنت مأمورٌ بغضِّ البصر، يقول الله سبحانه: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ [النور:30]، والنظر سهمٌ من سهام إبليس مسموم خطير، فاحذر، وعليك بمُناصحة جارك، وعليك أن تُرسل غيرك ليُناصحوه؛ لعله يُبعد هذه الخادمة بالكلية، أو على الأقل يمنعها من أسباب الفتنة: من التبرج، والخروج إلى هنا أو هنا، حتى يفتح الله عليه بإبعادها.\nنسأل الله للجميع الهداية، ولا حول ولا قوة إلا بالله.","link":"https://binbaz.org.sa/fatwas/4829/ما-النصيحة-لمن-يجلب-خادمة-مسلمة-متبرجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0470.mp3","categories":["نصائح وتوجيهات"]},{"id":697,"question":"سماحة الشيخ، بعض الموظفين والعاملين لا يعطون عملهم الحماس اللازم، فتجد بعضَهم لو مرَّ عامٌ أو أكثر وهو لم يُؤْمَر بعملٍ لا يمكن أن يقوم من تلقاء نفسه، مع أنه يعرف أنه من واجبه، وتجد البعض يتأخَّر ويقول: أنا مأذونٌ من رئيسي، ولا عليَّ شيءٌ، فمَن كان هذا حاله فهل عليه شيءٌ في دينه ما دام على هذه الحال؟ أفتونا مأجورين.","title":"حكم الموظفين الذين لا يُؤدون أعمالهم","answer":"الجواب: أولًا: ينبغي لكل مؤمنٍ ولكل مؤمنةٍ أن يُبَلِّغ عن الله ما سمع من الخير، كما أشار الأخ في ذلك؛ لقوله ﷺ: نضَّر الله امرأً سمع مقالتي فوعاها، ثم أدَّاها كما سمعها، وقال عليه الصلاة والسلام: بَلِّغوا عني ولو آية، وكان إذا خطب الناسَ وذكَّرهم يقول: فليُبلّغ الشاهد الغائب، فرُبَّ مُبَلَّغٍ أوعى من سامعٍ.\nفأنا أُوصيكم جميعًا أن تُبلِّغوا ما سمعتُم من الخير عن بصيرةٍ وعن ضبطٍ، كل مَن ضبط خيرًا وحفظه يُبَلِّغ أهل بيته وإخوانه ومُجالسيه ما يرى من ذلك الخير الذي ينفعهم، مع العناية بضبط ذلك، وعدم التكلم بشيءٍ لم يحفظه، بل يُؤدِّي ما سمعه وحفظه، ولا يؤدي شيئًا لم يحفظه، حتى يكون في هذا من المتواصين بالحقِّ من الدعاة إلى الله جلَّ وعلا.\nأما الموظفون الذين لا يُؤدون أعمالهم: فقد سمعتُم أنَّ الإيمان من خصاله الأمانة: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58]، فالأمانة من أعظم خصال الإيمان، والخيانة من أعظم خصال النفاق، وقال الله  في وصف المؤمنين: وَالَّذِينَ هُمْ لِأَمَانَاتِهِمْ وَعَهْدِهِمْ رَاعُونَ [المؤمنون:8]، ويقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَخُونُوا اللَّهَ وَالرَّسُولَ وَتَخُونُوا أَمَانَاتِكُمْ وَأَنْتُمْ تَعْلَمُونَ [الأنفال:27].\nفالواجب على الموظف أن يُؤدي الأمانة بصدقٍ وإخلاصٍ وعنايةٍ وحفظٍ للوقت، حتى يُبرئ ذمته، ويُرضي ربَّه، وينصح لدولته وحكومته في هذا الأمر، أو للشركة التي هو فيها، أو لمَن وظَّفه، هذا هو الواجب على الموظف: أن يتَّقي الله، وأن يُؤدي الأمانة بغاية الإتقان، وغاية النصح، يرجو ثواب الله، ويخشى عقابه، ويعمل بقوله تعالى: إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا [النساء:58].\nومن خصال أهل النِّفاق: الخيانة في الأمانات، يقول عليه الصلاة والسلام: آية المنافق ثلاث: إذا حدَّث كذب، وإذا وعد أخلف، وإذا ائتُمِنَ خان، فلا يجوز للمسلم أن يرضى بالتَّشبه بأهل النِّفاق، وأن يُحافظ على أمانته، ويُؤدي عمله بغاية العناية، ويحفظ وقته، ولو تساهل رئيسه، ولو لم يأمره رئيسه، فلا يضعف إذا ضعف رئيسه، أو خان رئيسه، أو تساهل، فليكن هو خيرًا من رئيسه؛ ليُؤدي العمل، وليحرص على أداء العمل بالنصح، وأداء الأمانة، حتى يكون خيرًا من رئيسه، وأفضل عند الله من رئيسه، وحتى يسلم من التَّبعة، فإنَّ رئيسه يوم القيامة لا ينفعه ولا يُنجيه من عذاب الله الذي خان فيه.\nنسأل الله للجميع الهداية.","link":"https://binbaz.org.sa/fatwas/20553/حكم-الموظفين-الذين-لا-يودون-اعمالهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0513فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["نصائح وتوجيهات"]},{"id":819,"question":"ما توجيهاتكم للقائمين على المركز الصيفي لهذا المعهد؟ وما نصائحكم للشباب المُشاركين فيه؟","title":"ما النصيحة للشباب والطلاب تجاه المجتمع؟","answer":"الجواب: توجيهاتي لإخواني وأبنائي ونصيحتي لهم هو أن يكونوا حريصين على فهم الحقِّ من غير رياء، ومن غير عدوانٍ على أحدٍ، ومن غير تكبُّرٍ، بل يكون كلُّ واحدٍ حريصًا على أن يفهم ما قاله الله ورسوله، وأن يعلم إخوانه ويُرشدهم، وأن ينصحهم، وأن يتعاون على البر والتقوى، وأن يكونوا مُتواضعين فيما بينهم، ليس بينهم تكبُّرٌ من بعضهم على بعضٍ، لا لأنه كبير السن، أو لأنه أفهم، أو لأنه في الكلية وذاك ليس بالكلية، أو لأنه في الثانوي وذاك ليس في الثانوي، بل في المتوسط، لا، يكون عندهم من التواضع والتعاون على الخير والمحبة لكل ما ينفع إخوانهم، عندهم من هذا ما يجعلهم شيئًا واحدًا، مُتحابين في الله، متعاونين على البر والتقوى، مُتناصحين: إذا رأى من زميله ما يُخالف الشرع نصحه بالأسلوب الحسن، والكلام الطيب، لعله يرجع إلى الصواب، من غير تعنيفٍ، ولا تشهيرٍ، ولا غيبةٍ له في المجالس، هكذا يكون الإخوان.\nفنصيحتي للجميع وتوجيهي للجميع أن يتَّقوا الله، وأن يتعاونوا على الخير بكل ما يستطيعون، وأن يكون هدفُهم إصلاح شؤنهم، وإصلاح أوضاعهم، وأن يتعلَّموا العلم، وأن يتفقَّهوا في الدين، وأن يتعاونوا على الخير، وأن يحذروا أن يكون من أهدافهم ثلبُ بعضهم بعضًا، وغيبةُ بعضهم لبعضٍ، وتشهيرُ بعضهم للآخرين بزلَّةٍ يزلها، وكذلك يجب الحذر مما تقدَّم: من التَّكبر، والتَّعاظم، واحتقار الغير.\nونصيحتي لهم أيضًا: أن يتواضعوا مع المدرسين، وأن يسألوهم ما أشكل عليهم بكل أدبٍ، هكذا ينبغي لطالب العلم، مع ما تقدَّم من المسارعة إلى ما أوجب الله: من الصلاة في الجماعة، وبرّ الوالدين، وصلة الرحم، والعطف على الفقير والمسكين والجار، وبذل السلام، وردّ السلام، وتشميت العاطس، وعيادة المريض، واتِّباع الجنائز، إلى غير هذا من الأخلاق الفاضلة، لا يملّون، ولا يضعفون، هكذا أهل العلم، وهكذا طلاب العلم.","link":"https://binbaz.org.sa/fatwas/20851/ما-النصيحة-للشباب-والطلاب-تجاه-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0647كلمة توجيهية للشباب ؟ ابن باز رحمه الله فتاوى المحاضرات.mp3","categories":["نصائح وتوجيهات","العالم والمتعلم"]},{"id":863,"question":"هناك من الناس مَن يقع دائمًا في الأعراض، وخاصَّة العلماء، ويحرص على النَّفرة منهم، وعدم الإقبال عليهم والسماع منهم، فهل هذا تعطيلٌ لشرع الله تعالى؛ لأن الإنسان إذا أبغض العالمَ ولم يتعلم مات جاهلًا أو مُعْرِضًا، وقد قال : فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43]؟ ما نصيحة سماحتكم في هذا أثابكم الله؟","title":"حكم من يقع في أعراض المسلمين والعلماء","answer":"الجواب: هذا فيه تفصيل: فالذي يتعرض لعلماء السنة ويُحذِّر منهم إنما يصير منافقًا، خبيث القلب، خبيث العقيدة، فيجب الحذر منه، والأخذ على يديه، والتَّنبيه عليه حتى يُوقف عند حدِّه، وحتى يُعاقب بما يستحقّ؛ لأن  التحذير من أهل العلم والتَّنفير منهم حتى لا يُستفاد منهم، وحتى لا يتعلم منهم شرع الله؛ إنما يكون من أهل النفاق والكفر بالله، والعناد للحق، وكراهته للإسلام.\nأما التَّحذير من علماء السُّوء وعلماء البدعة: كونه يُحذِّر من علماء السوء والبدع حتى لا يغترَّ بهم الطالب؛ فهذا مشكورٌ على عمله وعلى جهاده بعد التَّبصر وبعد التَّيقن، وأن يكون على بينةٍ فيما يقول، وأن يكون المحذَّرُ منه معروفًا بالبدعة، معروفًا بالفساد، هذا له رأيه في تحذيره منه، وإذا كان صادقًا، وإذا كان مُتبصّرًا؛ فهو على أجرٍ عظيمٍ في التَّحذير من أهل البدع، والترهيب من الركون إليهم، والأخذ عنهم.\nفالحاصل أنَّ هذا المقام مقام تفصيل، يجب على طالب العلم أن يتَّقي الله، وأن ينتبه في ترغيبه وترهيبه مع أهل العلم والبصيرة، يجب أن يُرغِّب في الاتصال بهم، والأخذ عنهم، والله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43]، والعلماء هم ورثة الأنبياء، فالترغيب بالاتِّصال بهم ..، ولا يأبى ذلك ولا يُعاند فيه إلا فاسد الضمير، منحرف العقيدة.\nأما علماء السوء، علماء البدع، فالواجب التَّحذير منهم، والترهيب من الأخذ عنهم -نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/20908/حكم-من-يقع-في-اعراض-المسلمين-والعلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0703ما نصيحتكم فيمن يقع في أعراض المسلمين وخاصة العلماء ويحرض على النفرة منهم؟ ابن باز.mp3","categories":["نصائح وتوجيهات"]},{"id":1020,"question":"ما جزاء تارك السنة بعد الصلاة؟","title":"ما النصيحة لمن يترك السُّنَن بعد الصلاة؟","answer":"الجواب: السنة نافلة ما هي فريضة، فإذا صلَّى الفرائض فليس عليه شيءٌ، لو أنَّ إنسانًا يُصلي الظهر فقط، والعصر فقط، والمغرب فقط، والعشاء فقط، والفجر فقط، ولم يُصلِّ النوافلَ فلا شيء عليه، لكنه ترك خيرًا عظيمًا، وترك سُننًا عظيمةً، فيها خيرٌ عظيمٌ يُؤجره الله عليها، وتجبر ما قد يقع من نقصٍ في فرائضه، لكن ليس عليه إثمٌ.\nوالأفضل أن يُصلي مع هذه الفرائض اثنتي عشرة ركعة، كان يُحافظ عليها النبيُّ ﷺ نافلةً، وهي: أربعٌ قبل الظهر بتسليمتين، وثنتان بعد الظهر، وثنتان بعد المغرب، وثنتان بعد العشاء، وثنتان قبل صلاة الفجر، هذه يُقال لها: السنن الرَّواتب، اثنتا عشرة ركعة. والوتر أقلّه واحدة بعد العشاء، أو في آخر الليل، أو في وسط الليل، بعد العشاء إلى آخر الليل، واحدة، وإن زاد فهو أفضل، إن أوتر بثلاثٍ أو بخمسٍ أو بسبعٍ، وأفضل ذلك إحدى عشرة أو ثلاث عشرة، وإن زاد فأوتر بأكثر من ذلك ولو بمئةٍ فلا بأس عليه؛ لأن الليل كله محلُّ عبادةٍ، لكن يُصلي مثنى مثنى، ويُوتر بواحدةٍ كما قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى، فإذا خشي أحدُكم الصبحَ صلَّى ركعةً واحدةً تُوتر له ما قد صلَّى، فيُصلي ما تيسر: ثنتين، ثنتين، ثم يُوتر بواحدةٍ قبل الصُّبح.","link":"https://binbaz.org.sa/fatwas/21056/ما-النصيحة-لمن-يترك-السنن-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0852ما جزاء تارك السنة بعد الصلاة؟ ابن باز فتاوى المحاضرات.mp3","categories":["صلاة التطوع","نصائح وتوجيهات"]},{"id":1305,"question":"والدها لا يُصلي، ومُدمن على المُسكرات -والعياذ بالله- وقد حاولتْ نصيحته، ولكن بدون فائدةٍ، والآن يُريد تزويجها من شابٍّ لا يُصلي، فماذا تعمل؟","title":"حكم تزويج من لا يصلي وكيفية النُّصح للوالد","answer":"الجواب:\nإذا كان والدها لا يُصلي أو مُدمن الخمر أو عنده شيءٌ من المعاصي الأخرى لا تُقصر في نصيحته، تجتهد في نصيحته، والحرص على نجاته من النار بالأسلوب الحسن، والكلام الطيب؛ لأنَّ الله جل وعلا قال للولد في حقِّ الوالدين الكافِرَيْن: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، أمر الله الولدَ أن يُصاحب والديه الكافرين بالمعروف: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا، وأبو هريرة وسعد بن أبي وقاص رضي الله عنهما لم يزالا يجتهدان في إسلام والدتيهما بكل جدٍّ، وصبرا على ذلك؛ حتى أسلمتا بعد صبرٍ طويلٍ، فلا بد من الصبر.\nفعليها أن تجتهد في الإحسان إلى والدها، والمشورة عليه، والنصيحة، ولو كان كافرًا، ولو كان لا يُصلي، لا تسبُّه، ولا تُعَنِّف عليه، بل ترفق به، وتدعوه إلى الله، تدعو له في صلاتها، وفي أوقات الإجابة أن الله يهديه، وأن الله يُعيذه من الشيطان، ترفق به حتى يهديه الله أو يموت، وليس لها أن تعنف عليه، بل ترفق به، الوالد له حقٌّ، والوالدة لها حقٌّ عظيمٌ، فلا بدّ من الصبر.\nوإذا تيسر أن تستعين على ذلك بإخوانها الكبار، أو بأعمامها، أو بالناس الآخرين الطيبين يُساعدونها على دعوته، وعلى توجيهه إلى الخير، وعلى نصيحته؛ هذا طيبٌ، من التعاون على البر والتقوى، ولا تتركه، لا بد من النَّصيحة، والصبر على النَّصيحة، والكلام الطيب مع والدها، والدعاء له بظهر الغيب أن الله يهديه.\nس: الزواج بالذي ما يُصلي؟\nج: ولا تقبل الزواجَ على مَن لا يُصلي، كونه يقول...  أُزوجها على مَن لا يُصلي، لا تُطيعه في هذا: إنما الطاعة في المعروف، لكن لا تتزوج إلا على إنسانٍ مسلمٍ يُصلي، ولو قال أبوها: لا، تزوجيه؛ لا تُطيعه في ذلك.","link":"https://binbaz.org.sa/fatwas/21364/حكم-تزويج-من-لا-يصلي-وكيفية-النصح-للوالد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1107أمراءة والدها لايصلي ومدمن مخدرات ويريد تزويجها من رجل لايصلي فهل تطيعه..mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":1492,"question":"أُتي برجلٍ شرب الخمر (كيف التعامل معه)؟","title":"كيف يكون التعامل مع شارب الخمر؟","answer":"الجواب:\nكذلك حديث شرب الخمر: إذا شرب يُنصح ويُوضّح ويُوجّه للخير، وألا يعود.  ولا يُلْعَن، ولا يُسبّ، لا يُعان عليه الشيطان، وليقال: هداه الله، اللهم أصلحه، اللهم اهده، اللهم مُنَّ عليه بالتوبة، المسلم أخو المسلم يُحب له الخير، ولما قيل: يا رسول الله، إنَّ دوسًا قد عصت وأبت أن تُسْلِم، قال: اللهم اهدِ دوسًا وائتِ بهم، فالإنسان يدعو لأخيه بالخير، ويدعو له بالتوبة النصوح، ولا يفضحه، ولا يسبه. وإنما سبَّ النبيُّ ﷺ أناسًا أعلنوا شرَّهم على المسلمين: كأبي جهلٍ وجماعةٍ، وكان يقنت في الدعاء عليهم، فإذا ظهر شرُّهم على المسلمين دُعِيَ عليهم.","link":"https://binbaz.org.sa/fatwas/21590/كيف-يكون-التعامل-مع-شارب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التعامل مع شارب الخمر.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":2325,"question":"سؤال من اليمن يقول: سماحة الوالد العلامة عبدالعزيز بن باز، السلام عليكم ورحمة الله وبركاته، نحن من أبناء اليمن، محافظة شبوة، ظهرت في مناطق اليمن عامَّة ومنطقتنا خاصَّة بعضُ الخلافات والانقسامات بين الشباب الملتزم، حيث أصبح الانقسامُ في البيت الواحد، وبين الأخ وأخيه، فهذا سلفيٌّ، وهذا إخوانيٌّ، وهذا تبليغيٌّ، وهذا جهاديٌّ، وانتشرت البغضاء والحقد والكراهية والهجر والتَّباعد، حيث استغلَّ هذا الخلافَ الصُّوفيُّ والشيوعيُّ وغيرُهم من أهل الأهواء، علمًا بأنَّ كل طرفٍ لا يقبل الفتوى إلا من أئمَّة جماعته، ويرى أن الطرف الآخر مُخطئٌ، فالسَّلفي لا يقبل إلا فتوى الشيخ مُقبل الوادعي، والإخواني لا يقبل الفتوى إلا من الشيخ الزنداني، وهكذا، فما توجيهاتكم؟","title":"حكم البغضاء والتفرُّق بين التيارت المختلفة","answer":"الجواب: الواجب على الجميع الرجوع إلى كتاب الله وسنة رسوله ﷺ، والتَّأسي بالسلف الصالح، فيُنظر إلى ما ذكره السلفُ عن الصحابة وأتباعهم بإحسانٍ، والحذر من التَّهاجر، وإذا أشكل شيءٌ رجعوا إلى الأدلة الشرعية، أمَّا أن يُقلِّد هذا مُقبلًا، وهذا يُقلِّد عبدالمجيد، وهذا يُقلِّد فلانًا، وهذا يُقلِّد فلانًا؛ فهذا غلطٌ، فالواجب التَّحاكم إلى الكتاب والسنة، والرفق، والنظر في الأدلة الشرعية، وعدم التَّهاجر، وعدم التَّقاطع، وإذا أشكل شيءٌ ردُّوه إلى الكتاب والسنة، وتشاوروا من دون تقاطعٍ، ومن دون تهاجرٍ، فيتشاورون مع الشيخ مُقبل، ومع الشيخ عبدالمجيد، ومع غيرهم من الإخوان؛ حتى لا تكون القطيعةُ بينهم والشَّحناء، وهكذا المؤمنون فيما بينهم: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، فالمؤمنون يردّون ما تنازعوا فيه إلى الله ورسوله، وقال جلَّ وعلا: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ.. [الشورى:10].\nفالواجب عليهم التَّواضع والرفق، وأن يتحاكموا إلى الشرع، وأن يُنصفوا في أنفسهم، والشيخ مُقبل معروفٌ بالخير والعلم والفضل، وعنده والحمد لله نشاطٌ جيدٌ في التَّعليم، فينبغي للإخوان أن ينصفوا فيما بينهم، وأن يرجعوا إلى الأدلة الشرعية، وأن لا يتهاجروا، ولا يتقاطعوا، وإذا أشكل عليهم شيءٌ كتبوا لنا وكتبوا لغيرنا من باب التَّعاون ولا بأس.\nس: يقولون: نُجمع على فتوى الشيخ ابن باز؟\nج: ليس على كل حالٍ، بل على ما وافق الكتابَ والسنةَ.\nس: يقولون: هناك حزبٌ يُظْهِر الإسلامَ، ويُسمَّى: حزب التَّجمع اليمني للإصلاح، وله بيعة وعهد، وعلى رأسه الشيخ الزّنداني؟\nج: الواجب التَّحاكم إلى الكتاب والسنة، لا إلى التَّجمع الفلاني، ولا التَّجمع الفلاني، فقد يُخطئ ويُصيب.\nس: بعض أهل جماعة التَّبليغ تُوجد عندهم بِدَعٌ، ألا يُهْجَرُون لبدعتهم؟\nج: الذين عندهم بدعٌ يُنصحون، فإن أصرُّوا استحقُّوا الهجرَ، فيُنْصَحون ويُوجَّهون أولًا ويُبَلَّغون بالرفق لعلهم يهتدون.","link":"https://binbaz.org.sa/fatwas/22449/حكم-البغضاء-والتفرق-بين-التيارت-المختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/توجيه من الشيخ بن باز بخصوص الخلافات والانقسامات والجماعات بين الشباب الملتزم.mp3","categories":["نصائح وتوجيهات"]},{"id":3053,"question":"في قَبْض النفقة: يُؤخذ بقول الزوجة وإلا قول الزوج؟","title":"مَنْ يُؤخذ بقوله من الزوجين في قبض النفقة؟","answer":"الجواب: يُوكَل إلى أمرها، ما دام اسْتَفْتَت فالعهدة عليها، ما يُقال: هاتي البينة، يُبيّن لها الحكم والعُهدة عليها، لو قال... بالبيّنة؛ عَظُم الأمرُ واشتد.","link":"https://binbaz.org.sa/fatwas/23213/من-يوخذ-بقوله-من-الزوجين-في-قبض-النفقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يؤخذ بقول الزوجة أو قول الزوج في النفقة.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":5057,"question":"إذا خرجت من غير إذنه؟","title":"ما المشروع لمن خرجت زوجته بغير إذنه؟","answer":"الجواب: يُوجِّهها ويُعلمها، فإذا كان خروجها فيه مصلحة -كعيادة مريض أو زيارةٍ لأهلها- فلا يُشدّد في الأمور، وإذا  كان خروجها يرتاب فيه يمنعها منه. \nأما إذا كان خروجًا مشروعًا وله وجهٌ فينبغي له ألا يُشدّد، فبعض الناس عنده تشدد وسوء ظن دائمًا، فإذا كانت المرأة صالحةً لا ينبغي أن يُساء الظنّ بها، وإذا كان خروجها خروجًا مشروعًا لأهلها في وقتٍ مناسبٍ، أو لجيرانها في وقتٍ مناسبٍ؛ لا حرج.","link":"https://binbaz.org.sa/fatwas/29320/ما-المشروع-لمن-خرجت-زوجته-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما المشروع لمن خرجت زوجته بغير إذنه؟.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":5194,"question":"يقول: إني أُصلي والحمد لله، ولكن أحسّ بالضيق وعدم الراحة في الصلاة، فأرشدوني جزاكم الله خيرًا.","title":"حكم من يحسّ بالضيق وعدم الراحة في الصلاة","answer":"الجواب: هذا مرضٌ من الأمراض القلبية، والغالب أنَّ سببه الذنوب والغفلة، فالذي لا ينشرح للصلاة إنما وقع له ذلك من غفلته وإعراضه وذنوبه، فليَتُبْ إلى الله، وليُجاهد نفسه، ويسأل ربَّه التوفيق، وليحضر بقلبه في الصلاة، فالصلاة راحة وقُرَّة عينٍ، يقول النبيُّ ﷺ: جُعِلَتْ قُرَّةُ عيني في الصَّلاة، فهي قُرَّة العين، ويقول لبلالٍ: أقم، أرحنا بالصلاة. فالصلاة راحة القلوب، وراحة الضَّمائر، وقُرَّة العين، إذا دخل فيها المؤمنُ ارتاح لها، واطمأنَّ قلبه، وقرَّت عينه؛ لأنَّها عمود الإسلام، ولأنه يُرضي فيها ربَّه، ويقوم بين يديه خاشعًا، فهي راحة القلوب، ونعيم الأرواح، وقُرَّة العين، فإذا أحسَّ الإنسانُ بالضيق فيها فليعلم أنَّ هذه مصيبة، وليُعالجها بالتوبة إلى الله، وسؤاله التوفيق والهداية والإعانة، والله يتوب على التَّائبين جلَّ وعلا.","link":"https://binbaz.org.sa/fatwas/30136/حكم-من-يحس-بالضيق-وعدم-الراحة-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 165.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":5199,"question":"سماحة الشيخ، نرجو التكرم بتوجيه كلمة للنساء عن خطر التَّبرج والسُّفور؟","title":"ما أخطار التَّبرج والسُّفور على المجتمع؟","answer":"الجواب: الواجب على كل امرأةٍ الحذر من التبرج والسُّفور وأسباب الفتنة؛ لأن المرأة عورة، والرجال ميَّالون إليها، وهي ميَّالة إليهم، والمعصوم مَن عصمه الله، والمحفوظ مَن حفظه الله. فالواجب على الرجال الحذر، وعلى النساء الحذر، الرجل يحذر ويغُضّ بصره، ويحذر الخلوة، ويحذر كل أسباب الفتنة، والمرأة كذلك عليها أن تحذر أسباب الفتنة: من الخلوة بالرجل، والتبرج في الأسواق بإظهار المحاسن والمفاتن، والسفور الذي عند الأجانب، يقول الله جلَّ وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ أي: الزمنَ بيوتكن، وَلَا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى [الأحزاب:33]. قال العلماء: معنى التبرج: إظهار المحاسن والمفاتن من الرأس والرقبة والوجه والصدر والأقدام والسّيقان، كل هذه فتنة، فالواجب التَّستر، ولهذا قال : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53]، أطهر لقلوب الجميع من وراء حجاب، يعني: من وراء بابٍ أو سترٍ أو جدارٍ أو ملابس تستر، وقال جلَّ وعلا في النساء: وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ الآية [النور:31]. فعلى الجميع التعاون على البر والتقوى: المرأة عليها أن تحتجب، وأن تبتعد عن التبرج، وألا تخرج إلى الأسواق إلا للحاجة، وإذا خرجت للحاجة تكون متسترةً بعيدةً عن الفتنة، سواء لبيتٍ أو للسوق أو لغير ذلك من الحاجات، فتكون متسترةً بعيدةً عن أسباب الفتنة، وعلى الرجال غضّ البصر، والحذر من مُغازلة النساء ومُتابعتهن، فعلى الرجل أن يحذر ويبتعد عن الفتنة، قال تعالى: قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ الآية [النور:30]، ويقول سبحانه: وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ [النور:31].","link":"https://binbaz.org.sa/fatwas/30143/ما-اخطار-التبرج-والسفور-على-المجتمع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 172.mp3","categories":["النظر والخلوة والاختلاط","نصائح وتوجيهات"]},{"id":5204,"question":"في هذه الأيام تنتشر الإصابة بالعين، وهم يفتخرون بها، وهي تُصيب بعض الناس، فما نصيحتكم لهؤلاء؟","title":"ما حكم من يتعمّد إصابة الناس بالعين؟","answer":"الجواب: الواجب الحذر، وأن الإنسان يتعمّد، فإذا كانت العينُ يتعمّدها فعليه الحذر من ذلك، وإذا عُرف أنه يتعمّد ذلك يجب أن يُؤخذ بهذا ويُعاقب، أما إذا كان بغير اختياره فليس بيده قدرة، لا يُكلِّف الله نفسًا إلا وسعها، والمسلم يقول صباح ومساء: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات، ويقرأ آية الكرسي بعد كلِّ صلاةٍ: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255]، ويقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مراتٍ صباح ومساء ويَسْلَم، ما تضرُّه العين ولا غيرها. فيقرأ قُلْ هُوَ اللَّهُ أَحَدٌ والمعوذتين ثلاث مرات صباح ومساء، وقايةً من كل سوءٍ، ويقرآ آية الكُرسي بعد كل صلاةٍ، ففيها الوقاية من كل سوءٍ، ويقرأها أيضًا: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ عند النوم. كل هذه من أسباب الوقاية، ويقول: \"أعوذ بكلمات الله التامَّات من شرِّ ما خلق\" ثلاث مرات في الليل والنهار، و\"بسم الله الذي لا يضرُّ مع اسمه شيءٌ في الأرض ولا في السماء، وهو السميع العليم\" ثلاث مرات ليلًا ونهارًا، من أسباب الوقاية، ويقرأ آخر آيتين من سورة البقرة كل ليلةٍ: آمَنَ الرَّسُولُ [البقرة:285]، فهذه من أسباب العافية من كل سوءٍ.","link":"https://binbaz.org.sa/fatwas/30148/ما-حكم-من-يتعمد-اصابة-الناس-بالعين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 180.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":5209,"question":"هذا سائل يقول: نأمل من سماحتكم توجيه نصيحة للنساء، خاصَّةً أنهن حاضرات، وجزاكم الله خيرًا.","title":"ما النصيحة العامة التي توصى بها النساء؟","answer":"الجواب: نُوصي جميع أخواتنا في الله بتقوى الله، نوصيهن بطاعة الله، والاستقامة، والمُحافظة على الصلاة في وقتها، والسمع والطاعة للزوج في المعروف، والحذر من التبرج والسُّفور وأسباب الفتنة. ونُوصي جميع النساء بتقوى الله، والمحافظة على الصلاة في وقتها في البيت، والطُّمأنينة والخشوع، والحذر من التَّبرج الذي يضرُّ المسلمين، والحذر من جميع المعاصي: من الغِيبة والنَّميمة، وعصيان الزوج بغير حقٍّ، ونحو ذلك. ونوصي الجميع بتقوى الله، والتعاون على البر والتقوى، والمُعاشرة بالمعروف، كما نوصي الأزواج بذلك، نوصي الجميع بطاعة الله، والتَّعاون على البر والتقوى، كما قال تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وقال تعالى: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. ونوصي الجميع بتقوى الله، والتعاون على الخير، والحذر من كلِّ ما نهى الله عنه ورسوله. نسأل الله للجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/30153/ما-النصيحة-العامة-التي-توصى-بها-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 185.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":5239,"question":"فضيلة الشيخ، والدي رجلٌ متوسط في العمر، هداه الله، محافظٌ على الصَّلوات الخمس في المسجد مع الجماعة، ويأمرنا بالأمر بالمعروف، والنَّهي عن المنكر، ابتلاه الله بالخمر -والعياذ بالله- فهو يشربها بالأسبوع مرةً، ولا نراه عندما يشربها، ولا ندري أين يشربها؟ وهو يُحذرنا منها.أرجو من سماحتكم توجيه النَّصيحة له، وبيان حكمه، فهو معنا في هذا المسجد، والله يحفظكم.","title":"ما كيفية نصح الوالد الذي يشرب الخمر؟","answer":"الجواب: الخمر من أقبح الكبائر، من أقبح الموبقات -نعوذ بالله- فالواجب على كل مسلم أن يحذرها، وأن يبتعد عنها، وألا يشرب شيئًا منها مطلقًا، لا في الأسبوع، ولا في الشهر، ولا في السنة، ولا في جميع الأوقات، قال الله جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالْأَنْصَابُ وَالْأَزْلَامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ  ۝  إِنَّمَا يُرِيدُ الشَّيْطَانُ أَنْ يُوقِعَ بَيْنَكُمُ الْعَدَاوَةَ وَالْبَغْضَاءَ فِي الْخَمْرِ وَالْمَيْسِرِ وَيَصُدَّكُمْ عَنْ ذِكْرِ اللَّهِ وَعَنِ الصَّلَاةِ فَهَلْ أَنْتُمْ مُنْتَهُونَ [المائدة:90- 91]، قال عمر عندما سمع الآية: انتهينا، انتهينا. فالمقصود أنَّها من أقبح الكبائر، قال عليه الصلاة والسلام: إنَّ على الله عهدًا لمَن مات وهو يشرب الخمرَ أن يسقيه من طينة الخبال، قيل: يا رسول الله، ما طينة الخبال؟ قال: عُصارة أهل النار أو قال: عرق أهل النار. وثبت عنه ﷺ أنه لعن الخمر، وشاربها، وساقيها، وعاصرها، ومُعتصرها، وحاملها، والمحمولة إليه، وبائعها، ومُشتريها، وآكل ثمنها، عشرة -نسأل الله العافية. فالواجب الحذر، وعلى مَن يتعاطاها أن يتَّقي الله، وأن يُبادر بالتوبة النَّصوح، والله يتوب على مَن تاب، ويقول عليه الصلاة والسلام: لا يزني الزاني حين يزني وهو مؤمن، ولا يشرب الخمر حين يشربها وهو مؤمن، قال: وإن صلَّى وصام وزعم أنه مسلم، هذا وعيدٌ عظيمٌ، لو كان عنده إيمانٌ قوي لردعه، فهذا يدل على أنَّ إيمانه ضعيفٌ، ولهذا أقدم على هذه الفاحشة وهذه الجريمة. وأنتم أيها الأبناء عليكم نصيحته دائمًا، وألا تيأسوا، بالكلام الطيب، والأسلوب الحسن، ولو كان أباكم، عليكم أن تنصحوه دائمًا، مع الحكمة والأسلوب الحسن، وأن تُخوِّفوه من الله جلَّ وعلا، وأن تجتهدوا في أسباب سلامته من هذا البلاء، وأنتم على خيرٍ، لكن من دون أذًى، ومن دون عنفٍ.","link":"https://binbaz.org.sa/fatwas/30613/ما-كيفية-نصح-الوالد-الذي-يشرب-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 371.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق","نصائح وتوجيهات"]},{"id":5338,"question":"هناك من الشباب من يصرف كثيرًا من وقته فيما لا فائدة منه فإذا جئت تكلمه عن واجبه مثل الدعوة إلى الله اعتذر بضيق الوقت، فبم توجّهون هؤلاء؟","title":"ما النصيحة لمن يهدر كثيرًا من وقته بلا فائدة؟","answer":"الجواب: الواجب على الشاب وغير الشاب كالشيخ والرجل والمرأة الواجب شَغْل الوقت في طاعة الله، في نفع عباد الله، والحذر من إضاعته فيما لا فائدة فيه، فالوقت له قيمة ثمينة، يقول ﷺ: من كان يؤمن بالله واليوم الآخر فليقل خيرًا أو ليصمت فالوقت له شأن: مَا يَلْفِظُ مِنْ قَوْلٍ إِلَّا لَدَيْهِ رَقِيبٌ عَتِيدٌ [ق: 18] فَإِنْ لَمْ يَسْتَجِيبُوا لَكَ فَاعْلَمْ أَنَّمَا يَتَّبِعُونَ أَهْوَاءَهُمْ [القصص: 50]. فنصيحتي للشباب وللشيبان وللرجال والنساء نصيحتي للجميع: شغل الوقت في طاعة الله، في الذكر، في حفظ القرآن، في تلاوة القرآن، في التسبيح والتهليل، والتحدث مع الأهل في حاجات البيت بما يحصل به الخير وسعادة البال من دون إثم ولا قطيعة رحم، يتحدث مع أهله، يحدث أهل البيت في حاجاتهم فيما لا محذور فيه من المعاشرة الطيبة، مع أولاده، في الخير، في النصيحة، مع جلسائه، شغل الوقت، الوقت يكون محفوظًا فيما ينفع، قال الله تعالى: وَمَنْ يَعْشُ يعني: يغفل عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ [الزخرف: 36]وقال تعالى: وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُ عَنْ ذِكْرِنَا وَاتَّبَعَ هَوَاهُ وَكَانَ أَمْرُهُ فُرُطًا [الكهف: 28] يعني ضائعًا. قالت عائشة رضي الله عنها: كان النبي ﷺ دائم الذكر، يعني في جميع أوقاته، يذكر الله في كل أحيانه عليه الصلاة والسلام، لا يغفل، في بيته، في الطريق، قائمًا وقاعدًا، هكذا كان ﷺ، كان يذكر الله في كل أحيانه عليه الصلاة والسلام بقلبه ولسانه، فالمؤمن هكذا يكون ذاكرًا لله أينما كان، يتذكر عظمته، ويتذكر حقه، ويتذكر حق العباد، ويتذكر حق أهله وحق أولاده وحق زوجته، وهكذا لا يضيع شيئًا، مع زوجته بالأخلاق الطيبة والأخلاق الكريمة وحسن الخلق وطلاقة الوجه، ومع أولاده كذلك، ومع جلسائه الطيبين ومع المسلمين بالكلام الطيب والأسلوب الحسن، والتذكير بالله والدعوة إليه، والأمر بالمعروف والنهي عن المنكر، بكلام طيب، بطلاقة وجه، بعبارات حسنة، بالأسلوب الطيب، بالرفق؛ حتى يؤثر فيمن يتحدث معهم. يقول ﷺ في الحديث الصحيح: إن الرفق لا يكون في شيء إلا زانه ولا ينزع من شيء إلا شانه ويقول عليه الصلاة والسلام: من يُحرم الرفق يُحرم الخير كله والله يقول سبحانه في وصف نبيه ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لَانْفَضُّوا مِنْ حَوْلِكَ [آل عمران: 159] ويقول جل وعلا لموسى وهارون لما أرسلهما إلى فرعون: فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه: 44] وقال تعالى: وَلَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت: 46] حتى أهل الكتاب وهم كفرة بالتي هي أحسن إلا من ظلم، من ظلم له شأن آخر.[1]","link":"https://binbaz.org.sa/fatwas/31011/ما-النصيحة-لمن-يهدر-كثيرا-من-وقته-بلا-فاىدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 059.mp3","categories":["نصائح وتوجيهات"]},{"id":5341,"question":"ما توجيه سماحتكم لمن ينكر على الناس ولا يبدأ ببيته وأهله؟","title":"ما حكم مَن ينكر على الناس ولا يبدأ بأهله؟","answer":"الجواب: هذا على كل حال على خطر عظيم، الواجب أن يبدأ بنفسه وأهله: وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا [طه: 132] يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم: 6] فالعاقل يبدأ بنفسه، يجتهد في صلاحها، وإصلاح أهله وأقاربه وجيرانه، ولا يمنعه ذلك من التوسع في الخير والأمر بالمعروف والنهي عن المنكر لجميع الناس، لكن لا يغفل عن نفسه؛ حتى يكون مثالًا صالحًا وقدوة صالحة لأهله ولغير أهله، لأهله لأولاده وإخوته وأهل بيته، يبدأ بهم ويعتني بهم؛ حتى يكونوا كلهم أسوة صالحة وقدوة طيبة في الخير والعمل.[1]","link":"https://binbaz.org.sa/fatwas/31014/ما-حكم-من-ينكر-على-الناس-ولا-يبدا-باهله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 062.mp3","categories":["نصائح وتوجيهات"]},{"id":5343,"question":"بعض طلبة العلم ممن يحضرون هذه الدروس لا يسلِّمون، بل حتى لا يردون السلام على طلبة علم آخرين ممن يواضبون على حضور هذه الدروس، رغم أننا ما علمنا على هؤلاء إلا خيرًا، فما ظهر منهم شر، فإن كان هؤلاء قد بنوا فعلهم هذا على يقين وتأكد وتثبت فليبينوا لنا حتى يحصل المقصود من النصح والتذكير والإنكار، وإن بنوا فعلهم على أوهام وتخرصات وظنون فنرجو أن توجه لهم النصيحة يا شيخ؟","title":"ما النصيحة لمن لا يحسنون الظن بالناس؟","answer":"الجواب: الواجب على المؤمن حسن الظن بأخيه، والتعاون معه بالبر والتقوى، والتواصي بالحق والصبر عليه، هذا هو الواجب على الجميع، كما قال الله جل وعلا: إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ فَأَصْلِحُوا بَيْنَ أَخَوَيْكُمْ [الحجرات: 10] وقال جل وعلا: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ [التوبة: 71] وقال جل وعلا: وَالْعَصْرِ ۝ إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ ۝ إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ [العصر: 1-3] ويقول النبي ﷺ لما سئل: أي الإسلام أفضل؟ قال: أن تطعم الطعام، وتقرأ السلام على من عرفت ومن لم تعرف فالواجب التحاب في الله، والتعاون على الخير، والتواصي بالحق والصبر عليه، والحذر من أسباب غضب الله.[1]","link":"https://binbaz.org.sa/fatwas/31016/ما-النصيحة-لمن-لا-يحسنون-الظن-بالناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 064.mp3","categories":["نصائح وتوجيهات"]},{"id":5465,"question":"أنا أعلم أن السعادة الحقيقية في تقوى الله والزهد في هذه الدنيا، وأريد أن أتواضع في مأكلي وملبسي ومشربي ومركبي، ولكن لا أستطيع بسبب الواقع المترف الذي نعيش فيه، فما نصيحتكم؟","title":"ما النصيحة لتوازن المسلم بين الترف والتقتير؟","answer":"الجواب: نصيحتنا لك ألا تتكلّف، وعليك بالوسط، لا تفعل ما تُزدرى فيه، تلبس الملابس الرديئة وأنت لا يليق بك ذلك، وهكذا الطعام؛ تكون وسطًا في أمورك لا تفعل فعل الفقراء وأنت غني، ولا تطلب فعل الأغنياء وأنت فقير، فعليك بقدر استطاعتك. والله يحب من عبده أن يرى أثر نعمته عليك، فإذا كان الله وسّع عليك تَطْعم وتلبس الوسط الذي ليس فيه التكلُّف وليس فيه جَحْد لنعم الله. وانظر إلى من دونك، لا تنظر إلى من فوقك حتى لا تزدري نعم الله عليك، أما التكلُّف في الملابس والمشارب والمآكل فلا يليق، لكن الإنسان ينظر الوسط ولباس أمثاله وأكل أمثاله حتى لا يزدري نعمة الله عليه.[1]","link":"https://binbaz.org.sa/fatwas/31329/ما-النصيحة-لتوازن-المسلم-بين-الترف-والتقتير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/reyath_alsalhin 001.mp3","categories":["نصائح وتوجيهات"]},{"id":5674,"question":"ما نصيحتكم للذين لا يحضرون صلاةَ الفجر مع الجماعة؟","title":"ما النصيحة لمن لا يحضر صلاة الفجر؟","answer":"الجواب: الواجب على المؤمن وعلى المؤمنة الحرص على أداء الصلاة في وقتها، وعدم التَّشبه بالمنافقين، المنافق هذه حاله: أثقل الصلاة على المنافقين: صلاة العشاء، وصلاة الفجر، والواجب الحذر من التَّشبه بهم، وأن يقوم لصلاة الفجر مع المسلمين، وعلى أهله أن يُوقظوه حتى يُصلي مع المسلمين، ولا يجوز له التَّساهل في هذا. والمرأة كذلك عليها أن تُصلي في الوقت، كل هذا واجبٌ، من أهم المهمَّات، والواجب الحذر من مُشابهة المنافقين. والذي يتعمد ترك الصلاة حتى يُصليها في الضُّحى هذا كافر -نعوذ بالله-، مَن تعمَّد تركها، يقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة، فمَن تركها فقد كفر، ويقول ﷺ: بين الرجل وبين الكفر والشِّرك ترك الصلاة. فالواجب الحذر من ذلك، الواجب أن يُوقظ ويُوقت السَّاعة على الوقت؛ حتى يُصلي مع المسلمين، حتى يُصلي الصلاة في وقتها، والمرأة كذلك يجب عليها أن تحرص حتى تُصلي الصلاة في وقتها: الفجر، وغير الفجر، نسأل الله للجميع الهداية والعافية.[1]","link":"https://binbaz.org.sa/fatwas/31767/ما-النصيحة-لمن-لا-يحضر-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 020.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":5679,"question":"ما الفرق بين المذاهب الأربعة؟ وهل هناك مذهب أحسن من الثاني؟","title":"الفرق بين المذاهب الأربعة","answer":"الجواب: المذاهب الأربعة كلها تريد الحق، الشافعية والمالكية والحنبلية والحنفية كلها مذاهب في اتباع الحق، واتبعوا القرآن، والسنة -رضي الله عنهم ورحمهم- ولكن يعاب على بعض أتباعهم التعصب، وهكذا مذهب الظاهرية وهو مذهب خامس معروف، وهناك مذاهب أخرى كانت موجودة: الجريرية، والليثية، والثورية أتباع سفيان الثوري، وأتباع الليث بن سعد، وأتباع ابن جرير، والراهوية كذلك أتباع إسحاق بن راهويه، ولكنها انقرضت. والمهم هو اتباع الحق، فهؤلاء المذاهب الأربعة، والظاهرية ومن قبلهم من المذاهب التي انقرضت كلهم أهدافهم اتباع الحق، فقد يختلفوا في مسألة، أو مسألتين، أو ثلاث، فيشتهر بها العالم، فيكون له أصحاب، وأتباع، فيشتهر ذلك المذهب بهذا الشيء الذي انفرد به هذا العالم في مسألة، أو مسألتين، أو ثلاث، أو أكثر، وأخيها غير رأي أخيه، بسبب أدلة قد يخفى على هذا، وظهر في هذا، وهي مسائل فرعية ليس لها في الغالب تعلق بالأصول. لكن يعاب على الرجل التعصب للباطل، وعدم الاقتناع بالحق من أتباعهم؛ فهذا هو الذي يعاب عليه، وإلا فالمذاهب معروفة، كلها تريد الحق، وتتبع الكتاب والسنة، وتهدف إلى اتباع الكتاب والسنة، وإلى الثبات على ما جاء به الرسول، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/979/الفرق-بين-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_07.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":5683,"question":"قل من يوجه الشباب حتى من العلماء! عند ذلك يقع الشباب وراء ما يسمعون، ويرون من الأشياء التافهة، فما هو توجيهكم؟","title":"الحث على مجالسة أهل العلم","answer":"الجواب: على كل حال موجود من أهل العلم، وموجود من العلماء -بحمد الله- موجودون، وإن كانوا قليلًا، بالنسبة إلى غالب البلاد قليلين، ولكن -على كل حال- طالب العلم إذا سعى، وطلب أهل العلم وجدهم.  من المصيبة عدم الطلب، وعدم الاتصال بهم، والانزواء بنفسه، والاستغناء بنفسه؛ فقد يغلط كثيرًا، ويخفى عليه كثيرًا، بل يجب عليه أن يسعى بطلب العلم، وأن يعنى بالقرآن، وبطلب العلم، وأن يسأل أهل العلم عما يشكل عليه، ولا يحتقر، ولا يظن بهم السوء، بل عليه أن يحسن الظن بعلماء زمانه الذين لم يظهروا له منهم ما يخالف شرع الله، ولم يخالف له منهم ما يدل على باطلهم، وبعدهم عن الحق. فيتحرى أهل العلم، ويسألهم عما أشكل عليه، ولا يساء بهم الظن؛ هذا من أسباب توفيق الله له، ومن أسباب هداية الله له، وإذا غلط في مسألة قد لا يغلط في مسألة أخرى، قد يغلط في مسألة واحدة، ولكن يصيب في مسائل إلا إذا أشكل عليه، وقال لعله غلط، يسأل العالم الثاني، والعالم الثالث، والعالم الرابع. هكذا كان السلف يسألون حتى يطمئنوا، يسألون العلماء، لا لقصد الامتحان، والتعنت لا، ولكن للطمأنينة حتى يجد منهم ما يطابق ما عنده من الدليل، وما عرف من الدليل الذي أشكل عليه؛ فإذا وجد ما يدل على صحة ما ظهر له من آية، أو حديث استقام على ذلك، وصبر على ذلك، ولا ييأس، ولا يسيئ الظن، ويعمل ما يستطيع من الاتصال بأهل العلم والمطالعة، والمذاكرة مع إخوانه، وزملائه، حتى الزملاء قد يفيدوه لا يسيئ بهم الظن، ولا يقول: إنه أعلم منهم، بل يذاكر مع زملائه، ويبحث معهم، ويناقش من دون غلط؛ حتى يزول الإشكال، وتزول الشبهة. السؤال: العالم عند الناس عندهم عرف أن الذي تخرج من الكلية هو الشيخ، أما إذا تخرج من الثانوية، أو المتوسط فما هو بشيخ؟ الجواب: على كل حال كلما زاد علمه اقترب من الصواب، المتخرج من الجامعة أقرب إلى الصواب من الثانوي، وهكذا، لكن لا يحتقر أهل الثانوي إن شاء... زملاءه ولو من الثانوي، لا يحتقر.","link":"https://binbaz.org.sa/fatwas/974/الحث-على-مجالسة-اهل-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_03.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":5796,"question":"ما هو واجب الشباب المسلم في هذا الزمان بتجنب الوقوع في الإفراط والتفريط؟ وبماذا تنصحون الشباب أن يقرأ من الكتب لتحقيق ذلك؟","title":"نصيحة للشباب لتجنب الإفراط والتفريط","answer":"الجواب: \n\nهذا لا شك موضوع مهم، وينبغي للشباب أولًا: العناية بطلب العلم، والتفرغ لطلب العلم، والحرص على الفهم الصحيح؛ لأن كثيرًا من الناس قد يفهم خلاف الحق بسبب عدم العناية بالفهم، وهذا يسبب مشاكل كثيرة، كما قال الشاعر:\n\n\n\t\n\t\t\n\t\t\tوكم من عائب قولًا صحيحًا\n\t\t\tوآفته من الفهم السقيم\n\t\t\n\t\n\n\nفأنا أنصح الطلاب جميعًا أن يعنوا بطلب العلم، طلب العلم الشرعي، وأن يجتهدوا في فهمه فهم الأحكام الإسلامية، فهم قول الله، وقول رسوله فهمًا جيدًا، وألا يكتفوا بأول بادرة، بل يدرسوا الشيء مرة بعد مرة، ويتذاكروا فيه مع الزملاء، ومع الأساتذة الطيبين حتى يستقر الفهم الصحيح في قلب الطالب، وحتى يكون على بينة من كتاب الله، وسنة رسوله -عليه الصلاة والسلام- وبكل ما يدرسه.\n\nلكن أهم شيء النصوص، أهم شيء ما يتعلق من القرآن، وما يتعلق من السنة، فهذا أهم شيء أن يعنى به، ويفهم الفهم الصحيح، ويطبقه بالعمل، وألا يتساهل في ذلك، فربما زلت قدمه بسبب الفهم الرديء بسبب غلطة في كتاب الله، أو سنة رسوله، عليه الصلاة والسلام.\n\nفالواجب: أن يعنى بالفهم الصحيح، وأن يتشاور مع زملائه في المعنى، ويتدارسون ذلك، ويسأل أهل العلم، ثم للعلوم الأخرى التي يستطيع أن يتعلمها، حتى ينفع أمته، وينفع المسلمين، لا بأس، إذا تيسر له ذلك من طب، أو غيره مما ينفع المسلمين، لكن أهم شيء العلوم الإسلامية البحتة، التي بها يعرف الله، وبها يعبد، وبها تعرف أحكامه  وبها يعرف ما يدعو إليه، وما ينهى عنه، حتى يعمل بذلك، وحتى يبلغه الناس، فما حصل بعد هذا من علوم أخرى فهو خير إلى خير.\n\nوكذلك أوصيه بالعناية بالقرآن، فكتاب الله أهم شيء، أهم شيء القرآن العظيم، يعتني به لحفظه، ويكثر من تلاوته، وتدبر معانيه، وإذا لم يحفظه؛ فليكثر من تلاوته، فإن الإكثار من التلاوة تجعل الإنسان يذكره كثيرًا، ويكون قريبًا من الحافظ، فأنا أوصي بالإكثار من تلاوة كتاب الله، بتدبر، وتعقل في الأوقات المناسبة، كأول النهار، وفي أثناء الليل، ونحو ذلك، وآخر الليل حتى يحصل له حفظ القرآن، أو ما تيسر منه، مع العناية بالمعنى، ومطالعته في التفسير في ذلك كابن كثير، والبغوي، وغيرهم من أهل التفسير، حتى تكون معلوماته جيدة، وحتى يكون على بينة من كتاب الله .\n\nثم السنة، سنة رسول الله ﷺ أوصيه بأن يحفظ منها ما تيسر، مثل: بلوغ المرام كتاب جيد محرر مفيد، كذلك عمدة الأحكام للشيخ عبدالغني المقدسي من الصحيحين كتاب جيد أيضًا، والخمسين النووية، والرحبية يحفظها، ويعتني بها، وإذا تيسر له مزيد علم، وارتفعت همته، ومعلوماته فيعتني بالصحيحين، وينظر في الصحيحين، وكتب السنن، وموطأ مالك، ومسند أحمد، هذا خير إلى خير بعد ذلك، بعدما ينهي دراسته، وبعدما تستقضى معلوماته يرتفع إلى هذه الكتب، ويعتني بها، كالصحيحين، والسنن الأربعة، ومسند أحمد، وموطأ مالك، ونحوها من الكتب العظيمة التي هي ثروة عظمى، وفيها تفسير كتاب الله، وفيها العون على فهم كلام الله، وكلام رسوله، عليه الصلاة والسلام.\n\nثم يعنى بكتب اللغة في مطالعة كتب التفسير، ومطالعة كتب الحديث حتى يستعين بها على فهم القرآن، والسنة، وعلى ترجيح الراجح، وتزييف الزائف.\n\nومن الكتب المفيدة النافعة: منتقى الأخبار أيضًا، لابن تيمية، فإنه كتاب عظيم، جمع فيه خيرًا كثيرًا، وجامع الأصول لابن الأثير أيضًا، كذلك زاد المعاد لابن القيم، كتاب جيد، زاد المعاد في هدي خير العباد كتاب عظيم، وإعلام الموقعين لابن القيم أيضًا كتاب عظيم، وإغاثة اللهفان لابن القيم كتاب عظيم، فأنا أنصح بمطالعة هذه الكتب، والعناية بها، فهي كتب مفيدة.\n\nالسؤال: فقه السنة؟\n\nالجواب: فقه السنة لا بأس به، للشيخ سيد سابق، لا بأس به، وفيه بعض الأغلاط، وطالب العلم إذا تأمله يستفيد، ويعرف الخطأ.","link":"https://binbaz.org.sa/fatwas/1125/نصيحة-للشباب-لتجنب-الافراط-والتفريط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_131.mp3","categories":["نصائح وتوجيهات","العالم والمتعلم"]},{"id":5878,"question":"هل الجهاد في سبيل الله جهاد أصغر كما دل عليه معنى الحديث المذكور الضعيف، مع أنه لا يمكن أن يجاهد في سبيل الله إلا من جاهد نفسه حق الجهاد، وألزمها حتى أراد أن يستشهد في سبيل الله؟","title":"بيان الجهاد الأصغر والجهاد الأكبر","answer":"الجواب: الجهاد في سبيل الله هو الجهاد الأكبر كما تقدم، وهو الجهاد الأكبر؛ ولهذا أنكر العلماء هذا الحديث، وقالوا: إنه يقتضي أن الجهاد في سبيل الله هو الجهاد الأصغر، فهذا خطأ؛ فإن بذل النفوس، والأموال في جهاد الأعداء، ودعوتهم إلى الإسلام، وإخراجهم من ظلمات الجهل، والكفر هذا أمر عظيم فوق ما يتصوره الناس.  فلهذا صار الجهاد في سبيل الله الذي به بذل النفوس، وبذل الأموال، ومغادرة البلدان، والغربة عن الأوطان، والأولاد، والنساء، هذا هو الجهاد الأعظم، ثم يرجع الناس منه إلى الجهاد الأصغر، جهاد النفس على ما يعتريها من المعاصي، والسيئات، وعلى ما تقيم عليه من خطر، ونقصان، فهو يجاهدها لله حتى تستقيم.  ولا شك أن الجهاد الأكبر إنما يحصل في الجهاد الأصغر، جهاد النفس حتى تستقيم على أمر الله، حتى ترضى بالجهاد في سبيل الله، حتى تقدم النفس، والمال.  هذا هو شأن المؤمن، يجاهد نفسه، ويتصبر على جهاد الكفار لما يعلم في ذلك من الخير العظيم، وقد ثبت عن رسول الله ﷺ فيما رواه البخاري، وغيره أنه قال: ما من أحد يموت له خير عند الله يتمنى أن يرجع إلى الحياة الدنيا إلا الشهيد، فإنه يتمنى أن يرجع إلى الدنيا، فيقتل عشر مرات؛ لما يرى من فضل الشهادة في سبيل الله  والنبي ﷺ يقول: إني أود أن أقتل في سبيل الله، ثم أحيا، ثم أقتل، ثم أحيا، ثم أقتل.","link":"https://binbaz.org.sa/fatwas/1231/بيان-الجهاد-الاصغر-والجهاد-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_228.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":5890,"question":"هل الجهاد في سبيل الله جهاد أصغر كما دل عليه معنى الحديث المذكور الضعيف، مع أنه لا يمكن أن يجاهد في سبيل الله إلا من جاهد نفسه حق الجهاد، وألزمها حتى أراد أن يستشهد في سبيل الله؟","title":"بيان الجهاد الأصغر والجهاد الأكبر","answer":"الجواب: الجهاد في سبيل الله هو الجهاد الأكبر كما تقدم، وهو الجهاد الأكبر؛ ولهذا أنكر العلماء هذا الحديث، وقالوا: إنه يقتضي أن الجهاد في سبيل الله هو الجهاد الأصغر، فهذا خطأ؛ فإن بذل النفوس، والأموال في جهاد الأعداء، ودعوتهم إلى الإسلام، وإخراجهم من ظلمات الجهل، والكفر هذا أمر عظيم فوق ما يتصوره الناس.  فلهذا صار الجهاد في سبيل الله الذي به بذل النفوس، وبذل الأموال، ومغادرة البلدان، والغربة عن الأوطان، والأولاد، والنساء، هذا هو الجهاد الأعظم، ثم يرجع الناس منه إلى الجهاد الأصغر، جهاد النفس على ما يعتريها من المعاصي، والسيئات، وعلى ما تقيم عليه من خطر، ونقصان، فهو يجاهدها لله حتى تستقيم.  ولا شك أن الجهاد الأكبر إنما يحصل في الجهاد الأصغر، جهاد النفس حتى تستقيم على أمر الله، حتى ترضى بالجهاد في سبيل الله، حتى تقدم النفس، والمال.  هذا هو شأن المؤمن، يجاهد نفسه، ويتصبر على جهاد الكفار لما يعلم في ذلك من الخير العظيم، وقد ثبت عن رسول الله ﷺ فيما رواه البخاري، وغيره أنه قال: ما من أحد يموت له خير عند الله يتمنى أن يرجع إلى الحياة الدنيا إلا الشهيد، فإنه يتمنى أن يرجع إلى الدنيا، فيقتل عشر مرات؛ لما يرى من فضل الشهادة في سبيل الله  والنبي ﷺ يقول: إني أود أن أقتل في سبيل الله، ثم أحيا، ثم أقتل، ثم أحيا، ثم أقتل.","link":"https://binbaz.org.sa/fatwas/1231/بيان-الجهاد-الاصغر-والجهاد-الاكبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_228.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":6001,"question":"قرأت مقالًا لأحد العلماء أن ما يمر بالمسلمين من تسلط للأعداء، واحتلال لمقدساتهم أنه فرض عين على كل مسلم في الدفاع عما هم فيه من اضطهاد، فما رأيكم في هذا، أجيبونا، جزاكم الله خيرًا؟","title":"واجب المسلمين في الدفاع عن دينهم وأرضهم","answer":"الجواب: سبق الكلام في هذا، وأن الواجب على المسلمين: التكاتف، والتعاون ضد أعدائهم؛ لإنقاذ بلادهم من أيدي اليهود، وغير ذلك، يجب على المسلمين التكاتف، والتعاون لجهاد أعداء الله؛ لاستنقاذ البلاد التي هي لليهود، ولقتال كل من خرج عن دين الله، ولم يحكم شريعة الله.","link":"https://binbaz.org.sa/fatwas/1393/واجب-المسلمين-في-الدفاع-عن-دينهم-وارضهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_349.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":6062,"question":"لا يخفى على سماحتكم ما يلقاه الدعاة إلى الله في سائر البلاد الإسلامية، من الأذى، والبلاء، والاضطهاد في المال، والعرض من بعض الحكومات التي تدعي أنها إسلامية، وهي تحمل الكفر، والإلحاد، فما واجبنا تجاه هؤلاء الزنادقة، والناصريين؟ وما هو موقفنا تجاه إخواننا الدعاة هناك؟","title":"نصيحة إلى الدعاة المضطهدين في سائر البلدان","answer":"الجواب: الواجب مثل ما تقدم أن يكون الإنسان يدعو إلى الله حسب طاقته، ولا يتعرض للأمور التي تسبب إفشاله، لا يتعرض للملوك، والرؤساء، يتركهم جانبًا، ويعلم الناس الخير، ويرشدهم إلى الخير، والناس إذا فهموا الخير؛ قاموا بواجبهم بعد ذلك، أما إذا تعرض للحكومات، وسبَّهم، وجعل يتكلم فيهم لا يتركونه.  فعليه أن يعرض عن هذه الأشياء التي تتعلق بالرؤساء، وأعمالهم، ولكن يدعو إلى الله، يأمر بالخير، وينهى عن الشر، يوصي بتوحيد الله، والإخلاص له، وترك التعلق بالأموات، والاستغاثة بالأموات، والطواف في قبورهم، يوصي بالصلاة، والاستقامة عليها، وأدائها في المساجد، يوصي بالدعوة إلى الله، يوصي بأداء الزكاة، يوصي بالصيام، يوصي بحج الفريضة، يوصي ببر الوالدين، بصلة الأرحام، بالحذر من المعاصي، بالحذر من الزنا، بالحذر من شرب المسكرات من اللواط من الميسر، من سائر المعاصي، هذا شأن الداعي إلى الله  في أي مكان.  والداعي إلى الله إذا ما تعرض للرؤساء، ما تعرضوا له، إنما يتعرضون له إذا قال هذا الرئيس الكافر الظالم الذي فيه ما لا فيه، ما يتركونه؛ فيضيع على الناس الفائدة، ويحرم نفسه الدعوة إلى الله  ويعرضها للسجون، أو الضرب، أو القتل، فيحرم الناس من فائدته، ويحرم الناس من علمه بسبب سوء تصرفه، فلا ينبغي هذا، بل ينبغي أن يعنى بالدعوة إلى الله كما دعا الرسول ﷺ في مكة، ما تعرض للناس يدعو إلى الله، ويعلم الناس الخير، ويرشدهم إلى طاعة الله، ورسوله، ولو تعرض لهم لآذوه أشد الأذى زيادة على ما حصل، فالحال اليوم بالنسبة لغالب الدنيا تشبه حال الرسول مع أهل مكة قبل الهجرة. فالواجب أن يعنى بالدعوة فيما وقع الناس فيه من التفريط، والإضاعة، يدعوهم إلى توحيد الله، وإلى طاعة الله، وإلى مكارم الأخلاق، ومحاسن الأعمال، ويحذرهم من مساوئ الأخلاق، وسيئ الأعمال، ويجعل الرؤساء، ومن يخشى شرهم، يجعلهم جانبًا لا يتكلم فيهم لا بخير، ولا بشر، بل يعرض عنهم إلا إذا كان خيرًا، رأى من الرؤساء خيرًا فيشكرهم عليهم، سمعنا أن الرئيس الفلاني فعل كذا وكذا، وهذا طيب جزاه الله خيرًا، هداه الله، وفقه الله؛ فلا بأس. أما أن يتعرض لهم، وأنهم فعلوا، وأنهم فعلوا، وأنهم ظلموا الناس، وأنهم وأنهم، هذا معناه يعطله من الدعوة، ويعرضه للسجن، والأذى، والقتل.","link":"https://binbaz.org.sa/fatwas/1473/نصيحة-الى-الدعاة-المضطهدين-في-ساىر-البلدان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_403.mp3","categories":["نصائح وتوجيهات"]},{"id":6522,"question":"إن المشاكل الزوجية، والأخلاقية كثرت لهذا السبب، فأنا من الذين حصلت لهم مشكلة في هذا اليوم، فزوجتي تطالبني بإحضار خادمة بين أبنائي المراهقين، أو أن تذهب إلى أهلها، فماذا ترشدونني إليه؟","title":"إيجاد البديل عن الخادمات","answer":"الجواب:  بسم الله الرحمن الرحيم، اللهم صل وسلم على رسول الله، اللهم وفقنا لما فيه رضاك، اللهم ارزقنا علمًا نافعًا، وعملًا صالحًا، وتوفيقًا لما فيه نفع المسلمين. لا شك أن هذا الذي قاله أخونا واقع لكثير من الناس، وما نحصي من يتصل علينا، ويقول كذا وكذا وكذا، حوادث هذا الأمر لا تحصى أبدًا، لا مع الرجال -الذين هم الأزواج- ولا مع الأولاد، ولا مع غيرهم، ولا نحصي أيضًا من يشكو زوجته، ويقول: إنها تطالب بالخادمة، لا شك أن هذا واقع، ولكن أنا أنصح إخواني في هذا أن يجتهدوا في إقناع المرأة مهما أمكن إقناعها، بكل ممكن لعلها تقوم بواجب البيت، ولو يعطيها بعض الشيء، ولو يبصم لها بعض الشيء، بدل ما يأتي بخادمة تضره، وتضرها، ويعطيها خمسمائة ريال أو سبعمائة ريال، أو أكثر، أو أقل، يعطي لها مثل بعض الشيء، ويقول: أنت أعطيك كذا وكذا كل شهر، وقومي بالواجب، واكتفي بهذا عن خادمة تأتي، فتضرنا، ولا تنفعنا، ويحاول معها بالكلام الطيب، والتوجيه الحسن أنها تقوم بواجب البيت، وأنها تصبر على أعمال البيت، ولو ساعدها هو، ما في مانع أن يعطيها راتبًا شهريًا بدل ما يعطي الخادمة، يعطيها هي نصف ما يعطي الخادمة، أو ربع ما يعطي الخادمة، وربما تقنع بهذا الشيء.  فالمقصود: أن الواجب أن يحاول معها بكل طريق، أنها تقنع بالعمل، وترضى بالعمل، وتستغني عن الخادمة. ثبت في الصحيح عن النبي ﷺ أنه جاءته ابنته فاطمة -رضي الله عنها- بلغها أنه جاء إلى أبيها سبي، فجاءت إلى النبي ﷺ وتقول: يا أبت أريد خادمًا؟ فقال: يا ابنتي إن أصحاب الصفة فقراء، ضعفاء، وسوف تباع هذه السبايا و... فيهم فلا أعطيك خادمًا، وأدعهم تطوي بطونهم من الجوع، وردها، وعلمها أن تقول عند النوم: سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، سبحان الله ثلاثًا وثلاثين، والحمد لله ثلاثًا وثلاثين، والله أكبر أربعًا وثلاثين، مائة. وفي لفظ: أنه علمها أيضًا أن تقول: اللهم رب السماوات السبع، ورب الأرضين، ربنا ورب كل شيء، فالق الحب والنوى، منزل التوراة، والإنجيل والقرآن، أعوذ بك من شر كل شيء أنت آخذ بناصيته، أنت الأول فليس قبلك شيء، وأنت الآخر فليس بعدك شيء، وأنت الظاهر فليس فوقك شيء، وأنت الباطن فليس دونك شيء، اقض عنا الدين، وأغننا من الفقر قالت -رضي الله عنها-: فعملت بما أوصاني به من الذكر، فما وجدت تعبًا بعد ذلك، قالت عملت، وهذا ثابت في الصحيح -صحيح البخاري وصحيح مسلم- قالت: فعملت بما أوصاني به، فما وجدت تعبًا بعد ذلك، ثم بعد مدة جاءه سبي آخر، فجاءت إليه، وأعطاها خادمًا -عليه الصلاة والسلام- بعدما يسر الله الأمور، وتوسعت أمور الخير. فالمقصود: أن الخادمة قد تضر، ويستغني عنها الرجل والمرأة، قد يستغنيان عنها بطرق طيبة، فالرسول ﷺ لما أرشد ابنته فاطمة إلى الذكر عند النوم، وأنه قال لها: إنه خير لك من خادم، فاستعملت هذا الذكر عند النوم، وأغناها الله به عن الخادمة مدة طويلة، وكانت تطحن، وتكنس البيت، وتطحن الطحين، وتقوم بواجب البيت كله عند زوجها علي -رضي الله عنه وأرضاه- وهي بنت رسول الله -عليه الصلاة والسلام-.  فينبغي أن يرشد الزوج المرأة إلى ما لها من الخير، والأجر العظيم في تحمل الصبر، وأن لها قدوة في أزواج النبي ﷺ وفي بناته -عليه الصلاة والسلام- في الصبر على الخدمة، وفي الاستغناء عن الخادم؛ حتى يوسع الله، وحتى تأتي خادمة طيبة عند وجود أسباب الاقتناع بها. فالحاصل: أنه يوجهها إلى الخير، ويرشدها، ويساعدها بما يرى من المال؛ حتى تقنع بذلك، وعند الضرورة ينظر في الأمر بعد ذلك.","link":"https://binbaz.org.sa/fatwas/2273/ايجاد-البديل-عن-الخادمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_896.mp3","categories":["نصائح وتوجيهات"]},{"id":6573,"question":"بماذا تنصحون من أتعب سمعه، وبصره بمتابعة مسلسلات التلفاز ليل نهار، وأشغلوا أسماعهم، وأبصارهم في غير ما خلقت لأجله، ماذا تنصحونهم؟","title":"التحذير من وسائل الإعلام المختلفة","answer":"الجواب: التلفاز، والإذاعة، والصحافة هذه، ووسائل الإعلام فيها خطر عظيم، وقد ابتلي بها كثير من الناس، وشغل بها كثير من الناس، وقد حصل بها خطر عظيم، وفساد كبير لبعض الناس، فنصيحتي لكل مسلم، ولكل مسلمة الحذر، وألا يأخذ منها إلا ما ينفع، وأن يحذر ما يضر، وأن يكون كالذي يمشي على الشوك، يلتمس لقدمه السلامة، لا يضع قدمه إلا في المحل السليم، ولا يضع بصره إلا في المحل السليم، ولا سمعه إلا في المحل السليم، فليسمع ما فيه خير من قرآن، أو أحاديث دينية، أو أسئلة دينية، وجوابها، أو ما أشبه ذلك مما ينفعه في العاجل، والآجل. أما سماعه للأغاني، وآلات الملاهي، فهذا يضر قلبه، ويضره، وربما أفضى به إلى النفاق، والفساد، وربما أفضى به إلى شر عظيم، وفساد كبير، وعاقبة وخيمة، فليحذر سماع هذه الأغاني، والملهيات، وسماع الحكايات الفاسدة، وكذلك النظر إلى المسلسلات الضارة التي فيها مرض القلب، وفيها فتنة النساء، أو من الأغاني، أو ما أشبه ذلك مما يضر.  فالمؤمن ينظر لنفسه، فلا يوقعها في الخطر، بل ينظر لها، فإن كان ما يسمعه، أو يشاهده ينفعه؛ لأنه مباح؛ لأنه طاعة لله؛ وإلا فليحذر، وليبتعد عن أسباب الخطر، ولا يخاطر بدينه، ولا بنفسه، لا مع التلفاز، ولا مع الإذاعة، ولا مع الصحافة، ولا مع الفيديو، ولا مع غير ذلك من سائر ما يعرض، ومن سائر ما يسمع، ومن سائر ما يقرأ، الواجب الحذر، والواجب تقوى الله في هذه الأمور، فإن هذه بلية ابتلي بها الناس في آخر هذا الزمان، فيجب الحذر من شرها، وعواقبها.","link":"https://binbaz.org.sa/fatwas/2404/التحذير-من-وساىل-الاعلام-المختلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_932.mp3","categories":["نصائح وتوجيهات"]},{"id":6838,"question":"حيث إنني أنوي السفر إلى الخارج في دورة دراسية، وذلك غدًا، حرصت على أن أودعك، وأودع إخواني الحاضرين، وأحظى بدعوة صالحة منكم، ومن الحاضرين بالثبات، وأن ينفع الله بنا، وأبشركم أنني من فضل الله وجدت عمارة كبيرة يسكنها أكثر من ثمانين عائلة مسلمة، وقد خصصوا شقة كاملة استأجروها على حسابهم، وجعلوها مسجدًا للعمارة، ولا أطيل عليكم، وأستودعكم الله الذي لا تضيع ودائعه، نحب لكم، ولإخواننا المسلمين محبة، أرجو أن تكون خالصة لله .","title":"وصايا لمبتعث إلى بلاد الغرب","answer":"الجواب: نوصيكم بتقوى، ونسأل الله أن يحفظك في الحل، والترحال، وأن يكفيك شر سفرك، وشر ما أمامك، ونسأل الله أن يعينك، وإخوانك الذين معك على تقوى الله، وعلى القيام بأمر الله، وعلى التعاون على الخير، و.. في الدين، والحذر من أسباب الهلاك؛ فإن السفر إلى الخارج فيه أخطار كثيرة.  فينبغي للمؤمن أن يحذر تلك الأخطار، وإذا أمكنه ألا يسافر إلا إذا كان ذا علم، وبصيرة ليدعو إلى الله، وينكر المنكر، فهذا فيه خير -إن شاء الله- وإذا كان ليس عنده الكفاية، والأهلية لهذا الأمر، فالواجب عليه ألا يسافر، وألا يخاطر بنفسه، فإن هناك من الشرور ما لا يحصيه إلا الله  من الدعوة إلى الشرك بالله، والكفر بالله، والدعوة إلى الفواحش، والزنا، والخمور، واللواط، وغير ذلك.  فأمريكا، وإنجلترا، وفرنسا، وإيطاليا، وغيرها من دول الكفر، والضلال فيها من الشر، والباطل ما لا يحصيه إلا الله  فينبغي لمن أراد أن يتوجه إلى هذه الأمور أن يحذر، وألا يتوجه أبدًا، ولا يسافر إلى تلك البلاد إلا عند الضرورة القصوى.  أما ما أمكن يتعلم في بلاده، ويتفقه في بلاده، فهو خير له -إن شاء الله- وأبعد له عن الشر إلا في حال واحدة، إذا كان قد حصل من العلم ما يكفي، ورزقه الله من البصيرة، والهدى، والثبات على الحق، وأراد أن يدعو إلى الله، ويعلم الناس الخير في أوساط المسلمين، وأوساط حدثاء العهد بالإسلام، والجاليات الإسلامية؛ فله أجره، وثوابه، نسأل الله له الإعانة، والتوفيق.","link":"https://binbaz.org.sa/fatwas/2713/وصايا-لمبتعث-الى-بلاد-الغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1212.mp3","categories":["الأدعية والأذكار","الرقائق","نصائح وتوجيهات"]},{"id":6899,"question":"أنا شاب في السابعة عشر من عمري، أحب فتاة تصغرني بعامين، مشكلتي أني أحبها، وهي تبادلني شعوري، ولكن أخوها صديق لي، ولا يسمح لي ضميري بخيانة صديقي، ولا أريد أن يعلم بذلك، ولكن أريد مقابلتها، وهي تهوى بذلك، فهل أقابلها، أم أحافظ على صديقي؛ علمًا أن المقابلة لا تتعدى السلام؟ فأنا محتار، أأضحي بصديقي، أم بحبيبتي، ارحمونا هذه حالتي، أفيدونا أفادكم الله بمزيد من العلم، والمعرفة، وفي النهاية يقول: إنه معذب في هذا، ويتمنى أن تفيدوه.","title":"ما النصيحة لشاب بينه وبين فتاة علاقة حب؟","answer":"الجواب: هذا يا ولدي خطر عظيم، ولا ينبغي لك مثل هذا العمل، الواجب عليك إن كنت تستطيع النكاح أن تطلبها من أوليائها، تخطبها من أوليائها.  أما الاجتماع بها؛ فيزيدك شرًا وفتنة، وربما أهوى بكما إلى وقوع الفاحشة، فلا يجوز هذا، بل إذا كنت راغبًا فيها، وهي راغبة فيك؛ فائت ذلك من الطريق الشرعي إلى الطريق الشرعي، ولا تقربها، ولا تخل بها، ولا تتكلم معها في التلفونات، ولكن اطلبها من وليها، واخطبها من وليها، فإذا جاءت؛ فالحمد لله، وإلا أعطاك الله خيرًا منها. سل ربك أن يعطيك ما فيه الخير والصلاح، ولا تحرص على هذه التي قد تجتمع بها من طريق الشيطان .. فتضر دينك، ودنياك، ولا حول ولا قوة إلا بالله، وربما أفضى بك إلى ما لا تحمد عقباه من ... وسوء حال، وتغريب عن بلادك إلى غير ذلك. المقصود: أن الواجب على من أراد امرأة -سواء شابًا أو شيخا- أن يطلبها بالطريق الشرعي، يخطبها من أوليائها، فإذا أجابوه؛ فالحمد لله، وإن لم يجيبوا؛ يسر الله له غيرها إذا صدق، وأعطاه الله من هو -إن شاء الله- أبرك منها. وهكذا هي إذا رغبت أحدًا تكتب، وتقول لأوليائها خطبني فلان، أو إن فلانًا يرغب في، وتطلب منهم أن ينظروا في الأمر من الطريق الشرعي، أما من طريق المغازلات، أو الخلوة المنكرة هذا خطره عظيم -نسأل الله السلامة-.","link":"https://binbaz.org.sa/fatwas/2831/ما-النصيحة-لشاب-بينه-وبين-فتاة-علاقة-حب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1279.mp3","categories":["نصائح وتوجيهات"]},{"id":6950,"question":"تناقش الآن مشكلة في الضفة الغربية التي احتلها اليهود منذ 67، وهذه المشكلة هي: هل يجوز نهب أموال اليهود، وسرقتها، وأخذها بأي طريق كان؛ ذلك بأنهم أعداؤنا، والذين سرقوا أموالنا، وأرضنا، وسرقوا كرامتنا، أود أن أسمع رأي سماحتكم في هذا الموضوع، هل حصل في تاريخنا الإسلامي ما يشبه هذه المشكلة؟ علمًا بأن هناك من المشايخ من أفتى بجواز هذا الأمر، وآخرون أفتوا بعدمه؟","title":"حكم أخذ أموال الحربيين","answer":"الجواب: نعم نعم، لمن بينهم وبينهم الحرب أن يأخذوا أموالهم، وينهبوها، ويسرقوها؛ لأنهم حرب للمسلمين، وخصومهم. أما إن كان اليهود في بلد أدرك فيها الأمن، لا يحل أمانه إذا كان في بلد قد أمن فيها، في مصر، أو في أي مكان قد أمن فيها، لا يتعدى عليه حتى يخرج من بلاده، حتى يذهب عن بلادهم. أما من بينهم وبينهم الحرب، كالفلسطينيين؛ فإنهم لهم أن يأخذوا منهم ما شاؤوا، ولهم ما قدروا عليه، ويسرقون أولادهم، وبناتهم، وأموالهم، وغير ذلك.","link":"https://binbaz.org.sa/fatwas/2880/حكم-اخذ-اموال-الحربيين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1328.mp3","categories":["الجهاد والسير","نصائح وتوجيهات","قضايا معاصرة"]},{"id":6971,"question":"يا سماحة الشيخ حفظ الله علينا، وعلى المسلمين ديننا، فنحن بحاجة إلى الدعوة، والدعاة، وخاصة في أطراف البلاد -أي المملكة- خاصة بالذات الجنوب، وعندهم عدم الاعتناء بالاجتماع في المساجد، وعندهم شعوذة وعدم معرفة بالدين، لقد لاحظنا أنهم يصلون السنة قبل الفجر، وبعده، وما ذاك إلا لعدم العلم بذلك، والمعرفة، نرجو من الله، ثم من سماحتكم الحث على بعث الدعاة، وجزاكم الله، ويحفظكم الله.","title":"الحث على طلب العلم والتفقه في الدين","answer":"الجواب:  هذا الدعاة -بحمد الله- عندهم نشاط في هذا، وهم يوجهون، ويحرصون على هذا الخير في الجنوب، والشمال، ولا شك أن الجهل موجود، لكن نسأل الله أن يعين الدعاة على أداء الواجب، وأن يعين العامة على التفقه، وطلب العلم والسؤال عما أشكل عليهم، وأن يعينهم أيضًا على حضور النصائح، واستماع الفوائد.  بعض الناس يسمع الفائدة .. والندوة، والخطبة، والمحاضرة، ولا يحضرها، يأبى أن يحضرها، وأن يستمع، فنسأل الله أن يوفق المسلمين حتى يحضروا حلقات العلم، وحتى يفرحوا بالندوات، والمحاضرات في أي مكان حتى يطلبوها، ويحضروها، ويستفيدوا. وهنا وأنا قلت كم مرة، وأكرر: أن إذاعة القرآن فيها فوائد يعرفها، ويقرأها، ويسمعها الذي في الجنوب، والذي في الشمال، والذي في خارج المملكة، برنامج نور على الدرب، وإذاعة القرآن، هذه حلقات علم يستفيد منها كل من سمعها، سواء كان في داخل المملكة، أو في خارجها. فأنا أوصي الذي يحب الخير، ويريد الخير أن يسمع حلقات العلم أينما كانت، وأن يحضرها، ويطلب العلم، وأن يسمع هذا البرنامج -برنامج نور على الدرب- في إذاعة القرآن، فيه خير كثير، ويلقي فيه عدة من العلماء، والأخيار بين المغرب، والعشاء في بلاد الإسلام، وفي الساعة التاسعة والنصف ليلًا من كل ليلة، من إذاعة القرآن. فأنا أكرر، وأوصي الحاضرين، وغيرهم أن يوصوا غيرهم بأن يستفيدوا من هذا البرنامج، وأن يستفيدوا من حلقات العلم في كل مكان؛ في الجنوب، وفي غيرها، إذا سمعوا أن هناك ندوة في مسجد كذا، في حارة كذا، يذهبون إليها يسمعونها، يستفيدون منها من أهل العلم في الدمام، في الإحساء، في بريدة، في حائل، في أبها في خميس مشيط، في جيزان، في أي مكان، وهكذا في خارج البلاد في ندوات تكون في خارج البلاد، عند العلماء المعروفين في مصر، أو في الشام، أو في غير ذلك. هكذا يكون طالب العلم، الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43]، ويقول ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله به طريقًا إلى الجنة. العلم ما هو يطق الباب عليك وخذ، العلم يحتاج إلى طلب، تطلب العلم، تسمع الفوائد في الإذاعة، وفي غيرها، في خطبة، في ندوة، في محاضرة، في حلقات علم، تطلب تسأل.  الرسول ﷺ يقول: من سلك طريقًا، وسمعتم في الندوة قال الله -جل وعل-ا: فَلَوْلَا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طَائِفَةٌ لِيَتَفَقَّهُوا فِي الدِّينِ نفروا: سافروا هنا وهنا لِيَتَفَقَّهُوا فِي الدِّينِ وَلِيُنْذِرُوا قَوْمَهُمْ إِذَا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ [التوبة:122] لا يجلس ويريد العلم، وأنا جالس عند أمي، وزوجتي، لا، يطلب العلم، يلتمس العلم.  الله يقول: وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] كيف تعبد ربك وأنت ما تطلب العلم؟ّّ! لا بد من طلب العلم، لا بد من حضور حلقات العلم؛ حتى تعرف العبادة، ما هي العبادة التي أنت مخلوق لها؟! مأمور بها من توحيد الله، والإخلاص له، والصلاة، والصوم، والحقوق الأخرى التي عليك لله، ولعباده، فلا بد أن تطلب هذا العلم. وحديث آخر في الصحيحين يقول ﷺ: من يرد الله به خيرًا؛ يفقهه في الدين هذا الحديث العظيم: من يرد الله به خيرًا؛ يفقهه في الدين معنى هذا الحديث: أن الذي ما أراد الله به خيرًا ما يتفقه في الدين، هذا معنى الحديث، مفهومه أن المعرض الغافل الذي ما يهتم، معناه أن الله ما أراد به خيرًا -نسأل الله العافية-. أما الذي يطلب العلم، ويتفقه في الدين، ويسأل، ويحضر ندوات العلم، ويسأل العلماء، ويسمع أيضًا ما يذاع فيما يتعلق بالعلم، فهذا يريد يطلب العلم، ومن طلبه وجده. وعندكم القرآن أعظم كتاب، وأشرف كتاب، عندكم القرآن اسمعوه، تدبروه ممن يقرأه من إخوانكم، خلوه يقرأ يجلس في المجلس بدل السواليف التي ما فيها ثمرة، اقرؤوا جزءًًا من القرآن، صفحة من القرآن، اقرأ عنا، قد نسمع اسمعوا، اسمعوا وعوا ،وتدبروا، واعملوا، هذه إذاعة القرآن عندكم يذاع فيها القرآن بأصوات متنوعة، بقراءات متنوعة، بأصوات طيبة، بقراءات مجودة، اسمعوا لكن ما هو سماع المعرض الغافل لا، سماع الذي يريد الفائدة، يريد أن يعرف مراد الله؛ حتى يعمل، هكذا يكون طالب العلم. فالذي يريد الخيرن ويريد الفقه في الدينن ويريد السعادة؛ عليه بطلب العلم، وحضور حلقات العلمن وسماع العلم، وسماع القرآن، وتدبر القرآن، يقرأه بنفسه، أو يسمعه من أخيه في المسجد، أو في الإذاعة، أو في أي مكان، هكذا يكون طلب العلم.","link":"https://binbaz.org.sa/fatwas/2898/الحث-على-طلب-العلم-والتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1346.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":6973,"question":"وبعض الإخوة يقول بعض الأحيان يحدث عندي ضيق في صدري بدون سبب حتى أنني لا أستطيع أن أستقر في محل واحد، فماذا أفعل، وماذا تنصحونني؟","title":"ذكر الله دواء لضيق الصدر","answer":"الجواب: الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ [الرعد:28] عليك بذكر الله -جل وعلا- إذا أحسست بالضيق؛ فعليك بذكر الله: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده سبحان الله العظيم، لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، تكثر من هذا، من قراءة القرآن، تتعوذ بالله من الشيطان يزول، الحمد لله.","link":"https://binbaz.org.sa/fatwas/2893/ذكر-الله-دواء-لضيق-الصدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1341.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":7006,"question":"نرجو بيان الأحوال التي يكون للمرأة المطلقة السكنى، والنفقة، أو السكن وحده، أو النفقة وحدها؟ وهل نفقة المتوفي عنها زوجها واجبة، وكذلك سكناها؟","title":"حكم النفقة على المطلقة والمتوفى عنها زوجها","answer":"الجواب:\n\nالنفقة تكون للمطلقة الرجعية، طلقها واحدة، أو ثنتين، أما إذا كان طلقها آخر الثلاث -الطلقة الأخيرة آخر الثلاث- فلا نفقة لها، ولا سكنى بالمرة عن النبي ﷺ. \n\nوهكذا المتوفى عنها بائنة، ليس لها نفقة في مال الزوج، لأن مال الزوج صار للورثة، وإنما نفقتها في مالها، في نصيبها من الإرث، وهكذا المخلوعة التي طلقها على مال، هذه بائنة، ليس لها نفقة؛ لأنها غير رجعية، إنما النفقة كما قال النبي ﷺ للمرأة إذا كان لزوجها الرجوع إليها، أما إذا كان لا رجوع لها؛ فلا نفقة عليه، أما العدة فلا بد منها.\n\nالسؤال:...؟\n\nالجواب:  بعد العدة لا نفقة لها عند جميع العلماء، بعد خروجها من العدة لا نفقة لها عند جميع أهل العلم، وأما ما يوجد من طالب بالنفقة في الهند، فهذه طائفة كافرة، دولة كافرة، لا يستغرب ما يوقع منها، ..النفقة على المرأة المطلقة -ولو بعد العدة- إلى أن تموت، أو إلى أن تتزوج، هذا قول باطل، لا أساس له، وهو خلاف جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/2940/حكم-النفقة-على-المطلقة-والمتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1388.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":7016,"question":"نرجو بيان الأحوال التي يكون للمرأة المطلقة السكنى، والنفقة، أو السكن وحده، أو النفقة وحدها؟ وهل نفقة المتوفي عنها زوجها واجبة، وكذلك سكناها؟","title":"حكم النفقة على المطلقة والمتوفى عنها زوجها","answer":"الجواب:\n\nالنفقة تكون للمطلقة الرجعية، طلقها واحدة، أو ثنتين، أما إذا كان طلقها آخر الثلاث -الطلقة الأخيرة آخر الثلاث- فلا نفقة لها، ولا سكنى بالمرة عن النبي ﷺ. \n\nوهكذا المتوفى عنها بائنة، ليس لها نفقة في مال الزوج، لأن مال الزوج صار للورثة، وإنما نفقتها في مالها، في نصيبها من الإرث، وهكذا المخلوعة التي طلقها على مال، هذه بائنة، ليس لها نفقة؛ لأنها غير رجعية، إنما النفقة كما قال النبي ﷺ للمرأة إذا كان لزوجها الرجوع إليها، أما إذا كان لا رجوع لها؛ فلا نفقة عليه، أما العدة فلا بد منها.\n\nالسؤال:...؟\n\nالجواب:  بعد العدة لا نفقة لها عند جميع العلماء، بعد خروجها من العدة لا نفقة لها عند جميع أهل العلم، وأما ما يوجد من طالب بالنفقة في الهند، فهذه طائفة كافرة، دولة كافرة، لا يستغرب ما يوقع منها، ..النفقة على المرأة المطلقة -ولو بعد العدة- إلى أن تموت، أو إلى أن تتزوج، هذا قول باطل، لا أساس له، وهو خلاف جميع أهل العلم.","link":"https://binbaz.org.sa/fatwas/2940/حكم-النفقة-على-المطلقة-والمتوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1388.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":7261,"question":"ماذا تنصح الشباب الذين أهلكهم الفراغ والبطالة، لا أعني بالمجون، ولكن المكث في المنازل للأكل والشرب والجلوس، هكذا مما سبب ضعف الوازع الديني، وقسوة قلوبهم، وتبلبلها؟","title":"نصيحة للشباب حول الفراغ والبطالة","answer":"الجواب:\n\nننصحهم بتقوى الله، وطلب العلم، والإقبال على القرآن دراسة وتدبرًا وتعقلًا، والإقبال على سنة الرسول ﷺ وتعلمها في المدارس، وفي المساجد، والاجتماع بالإخوان الطيبين، وصحبة الأخيار؛ حتى يتذاكروا معهم في القرآن الكريم، وفي السنة المطهرة. \n\nوأن يكون لهم أعمال ينفعون بها الناس، إذا كان ما عندهم وظائف يجتهدون في وجود أعمال مصانع يفعلونها، شركات يقيمونها، ينفعون أنفسهم، وينفعون الناس، مع لزومهم تقوى الله، ومع حرصهم على طاعة الله ورسوله.\n\nأما البقاء في البيت للنوم، والكسل، والضعف فلا يليق بالمؤمن، ينبغي أن يكون عنده همة، عنده نشاط، يلتمس عملًا يؤدي فيه ما ينفع الناس، وينفع نفسه كالمزارع، والمصانع التي تنفع الناس، إنشاء شركات تنفع الناس، يكون فيها نفع للناس، ونفع له وإشغال لهذا الفراغ، وقضاء على الفراغ الذي يضره ولا ينفعه. \n\nالسؤال: طيب يا شيخ لو يأمر بالمعروف في الشارع، وفي المقاهي يضيع الفراغ عليه؟\n\nالجواب: هذا من طاعة الله ورسوله، إذا كان عنده علم وعنده غيرة، كونه يدور في الطرقات ويأمر بالمعروف وينهى عن المنكر يدعو، هذا عمل عظيم، عمل صالح، ويقضي على كثير من الفراغ.","link":"https://binbaz.org.sa/fatwas/3334/نصيحة-للشباب-حول-الفراغ-والبطالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1655.mp3","categories":["نصائح وتوجيهات"]},{"id":7271,"question":"ماذا تنصح الشباب الذين أهلكهم الفراغ والبطالة، لا أعني بالمجون، ولكن المكث في المنازل للأكل والشرب والجلوس، هكذا مما سبب ضعف الوازع الديني، وقسوة قلوبهم، وتبلبلها؟","title":"نصيحة للشباب حول الفراغ والبطالة","answer":"الجواب:\n\nننصحهم بتقوى الله، وطلب العلم، والإقبال على القرآن دراسة وتدبرًا وتعقلًا، والإقبال على سنة الرسول ﷺ وتعلمها في المدارس، وفي المساجد، والاجتماع بالإخوان الطيبين، وصحبة الأخيار؛ حتى يتذاكروا معهم في القرآن الكريم، وفي السنة المطهرة. \n\nوأن يكون لهم أعمال ينفعون بها الناس، إذا كان ما عندهم وظائف يجتهدون في وجود أعمال مصانع يفعلونها، شركات يقيمونها، ينفعون أنفسهم، وينفعون الناس، مع لزومهم تقوى الله، ومع حرصهم على طاعة الله ورسوله.\n\nأما البقاء في البيت للنوم، والكسل، والضعف فلا يليق بالمؤمن، ينبغي أن يكون عنده همة، عنده نشاط، يلتمس عملًا يؤدي فيه ما ينفع الناس، وينفع نفسه كالمزارع، والمصانع التي تنفع الناس، إنشاء شركات تنفع الناس، يكون فيها نفع للناس، ونفع له وإشغال لهذا الفراغ، وقضاء على الفراغ الذي يضره ولا ينفعه. \n\nالسؤال: طيب يا شيخ لو يأمر بالمعروف في الشارع، وفي المقاهي يضيع الفراغ عليه؟\n\nالجواب: هذا من طاعة الله ورسوله، إذا كان عنده علم وعنده غيرة، كونه يدور في الطرقات ويأمر بالمعروف وينهى عن المنكر يدعو، هذا عمل عظيم، عمل صالح، ويقضي على كثير من الفراغ.","link":"https://binbaz.org.sa/fatwas/3334/نصيحة-للشباب-حول-الفراغ-والبطالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1655.mp3","categories":["نصائح وتوجيهات"]},{"id":7332,"question":"المجتمع الإسلامي في كافة أقطار الإسلام يواجه حملة شرسة ومكثفة للإساءة للإسلام والمسلمين، وتشكيك أبنائه به، ويستخدم مواقع المسلمين الآن دليلًا لإقناع الشباب الطري، الذي ينخدع في مظاهر الأمور، وإن تجربتي الدراسية في أمريكا زادتني قناعة بهذه الحملة الحاقدة، وإننا أمة مستهدفة لإبعادها عن دينها من أجل أن تتحكم فيها أهواء الشيطان، وبالتالي اندثارها، إن مجتمعنا يعاني من أمراض خبيثة، صُدّرت إلينا مع خبراء الغرب الذين وفدوا إلينا تحت ستار التعاون الثنائي، إن الطفرة الاقتصادية التي مرت في دول جزيرة العرب جلبت معها مفاسد للأخلاق والذمم والعادات، إن مجتمعنا الإسلامي يعاني من أمراض مستعصية بحاجة إلى طبيب حاذق يكثف علاجها للقضاء عليها قبل أن تدمر هذا المجتمع المسلم، أرجو من سماحتكم إلقاء الضوء أو النصيحة لعامة المسلمين بهذا الشأن، وإذا ترون تخصيص إحدى الندوات عن هذا الموضوع -موضوع معالجة الأمراض- التي يعاني منها مجتمعنا الإسلامي.","title":"نصيحة لعموم المسلمين","answer":"الجواب: بارك الله فيك، هذا أمر معلوم يا أخي، وهذا في الحقيقة شيء يشهده كل من عرف العالم وأحوال العالم، وكل من سبر أحوال الناس اليوم في هذه البلاد وفي غيرها؛ فإنه يعلم أن أعداء الله قد جمعوا جهودهم، وقد عنوا عناية كبيرة بصد الناس عن دين الله، والتلبيس عليهم، وإلقاء الشبه عليهم في كل مكان، فهم لا يدخرون وسعًا في التضليل والدعوة إلى ما هم عليه من الباطل، وإلقاء الشبه على الناس، سواء كانوا نصارى، أو يهودًا أو شوعيين، أو غيرهم من أصناف الكفرة، ولكن هذا يوجب على أهل الإسلام مضاعفة الجهود ضد عدوهم ما داموا مستهدفين، ويعرفون هذا من عدوهم.  فالواجب أن يكونوا ضد هذا العدون وأن يجمعوا جهودهم ويتعاونوا في نشر الحق، وكشف الشبه، ورد الباطل، ودعوة الناس إلى الخير بكل نشاط، وبكل قوة، والله جل وعلا يقول: أَحَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ [العنكبوت:2] فالناس مفتنون مبتلون، ويقول -جل وعلا: وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ وَكَانَ عَرْشُهُ عَلَى الْمَاءِ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا [هود:7]، وقال سبحانه: إِنَّا جَعَلْنَا مَا عَلَى الْأَرْضِ زِينَةً لَهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا [الكهف:7]، قال سبحانه: الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا [الملك:2] فهذا ابتلاء وامتحان، يبتلي الله الأخيار بالأشرار، ويبتلي الأشرار بعضهم ببعض، والأخيار بعضهم ببعض؛ حتى يتبين من هو الصادق في دعوته إلى الله، ومن هو الصابر على الدعوة إلى الله، من هو المستقيم والمستمر، من هو الضعيف الجاهل، من هو المتخلف، من هو المغلوب على أمره. فالواجب على أهل العلم، وعلى الدول الإسلامية، وعلى كل من يستطيع بماله أو بعلمه أن يناصر الدعوة، وأن ينصر من دعا إليها، وأن يعينه على ذلك بالمال والتوجيه والإشارة والشفاعة وغير ذلك، لا شك أن هذا أمر عظيم، جدير بالعناية، والجهود مبذولة فيه بحمد الله.  ونسأل الله أن ينفع بالأسباب، والدولة وفقها الله قائمة بشيء كبير من هذا، وعلى حسابها جم غفير من الدعاة في أرجاء المعمورة؛ في أوروبا وأمريكا وآسيا وأفريقيا جم غفير، كلهم يدعون إلى الله، ونسأل الله أن يعينهم وأن يبارك في جهودهم، وأن يرزقهم المزيد من العلم النافع، وأن يمنحهم الصبر، وأن ييسر لهم الأعوان من كل مكان من إخوانهم،  نسأل الله أن يمنحهم الأعوان الطيبين الذين يدعون إلى الله على علم وعلى بصيرة وعن إخلاص لله ورغبة فيما عنده .","link":"https://binbaz.org.sa/fatwas/3407/نصيحة-لعموم-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1720.mp3","categories":["نصائح وتوجيهات"]},{"id":7452,"question":"نرى كثيرًا من الشباب يميلون إلى ملاهي الحياة الدنيا، مثل الفنانين في الغناء ولاعبي كرة القدم، حيث إنهم يفضلونهم على العبادات الدينية، وأعتقد أن بعضهم يحبونهم أكثر من الصحابة والتابعين، فما تعليق فضيلتكم على ذلك؟","title":"خطورة المبالغة في حب الفنانين ولاعبي الكرة","answer":"الجواب: سوء الظن بالناس إلى هذا الحد لا ينبغي، سوء الظن بالناس إلى هذا الحد أنهم يحبونهم أعظم من حب الصحابة، هذا ما يقع من مسلم، لكن على كل حال في الناس من السفهاء من يحب الفنانين، ويحب اللاعبين أكثر مما يحب الاشتغال بالطاعة التي ليست واجبة عليه، وهذا من الجهل، ومن قلة البصيرة؛ ولأن النفوس لها عادات تحب أن تنفذها من اللعب والمرح، وسماع ما قد يروق لها من أغاني، أو أشعار، لكن هذا فيه تفصيل.  فإن كانت الأغاني المعروفة التي يستعملها الناس في الحب، والعشق، ونحو ذلك، وذكر النساء، وحال النساء، هذه لا شك أنها محرمة، وإذا كان معها طبل، أو موسيقى، أو معها العود أو معها أنواع من آلات الملاهي المحرمة، فجنس الغناء محرم عند أكثر أهل العلم كما قال الله -جل وعلا: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6] قال أكثر العلماء إنه الغناء، وإذا كان معه آلات الملاهي صار أكثر تحريمًا وأشد إثمًا حتى حكى غير واحد إجماع أهل العلم على ذلك ابن الصلاح -رحمه الله-.  المقصود أن الغناء من حيث هو من اللهو المحرم الذي قال فيه أكثر العلماء إنه المراد في قوله تعالى: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ [لقمان:6] أما الأشعار العربية التي تعرف بلحون العرب، ما هي بلحون الغناء، فهذه ما كان منها طيبًا؛ أبيح سماعه، كشعر حسان، وشعر عبدالله بن أبي أوفى، وابن رواحة، وفلان وفلان. المقصود الأشعار التي يقولها العرب بلحون العرب في الجود، بالكرم، بالشجاعة، بالحرب، بالصناعة في غير هذا من الوجوه الطيبة، هذه تسمع، وفيها فائدة، وقد قال النبي ﷺ: إن من الشعر حكمة. أما الأشعار التي في ذم الدين، أو في مدح عاصٍ، أو الخمور، فهذه محرمة كالنثر، فحسنه حسن وقبيحه قبيح، فما كان في سبيل الله، وفي طاعة الله، من الأشعار العربية والأشعار الأخرى في مدح الحق والدعوة إلى الحق، ونشر الفضيلة؛ فهذه لا بأس بها، وما كان من الأشعار في ذم الحق أو في الدعوة إلى الرذائل، أو المسكرات، أو الزنا والفواحش هذا محرم، سواء كان شعرًا عربيًا أو نبطيًا أو عجميًا أو نثرًا كله محرم؛ لأنه يدعو إلى الباطل -نسأل الله العافية-. وأما كرة القدم والعرضات، فهذه إن كانت تشغل عن الصلاة أو يظهر فيها عورات؛ منعت، أما إن كانت في وقت لا يظهر فيها عورة، ولا تشغل عن واجب؛ فلا حرج فيها كأن تكون في وقت الضحى قبل الصلاة بوقت للتدرب على سير الأقدام، أو قوة البدن وما أشبه ذلك، أو حمل السلاح كالسيوف، والبنادق، والرماح، وأشباه ذلك مما يستعان به في الحرب كالدرق، والحراب كما فعل الحبشة في مسجد النبي ﷺ في عهده -عليه الصلاة والسلام- فهذا لا بأس به، وهذا من باب التدرب، من باب إعداد القوة، ولكن لا يكون فيها ما حرم الله من موسيقى، وطبول، وآلات الملاهي لا، بل تكون بالسيوف، بالرماح، بالدرق والحراب، بأشباه ذلك، والأشعار العربية التي فيها مدح الشجاعة، ومدح الكرم، ومدح القوة، وما أشبه ذلك، هذا مقام تفصيل. السؤال: ما معنى فنان في اللغة، بعضهم يقول معناه حمار؟ الجواب: لا، الذي نعرفه: الفنان صاحب الفن، الذي عنده معرفة فن الغناء، أو فن آخر، كفن الموسيقى، أو فن كذا، أو فن كذا، الفنون تختلف، قد يكون فنًا محرمًا، وقد يكون فنًا جائزًا، الفنون التي فيما أباح الله من فن، كيف يصنع كذا؟ كيف يعمل كذا مما أباح الله؟ هذا له حكمه. والفنون التي تتعلق بالأغاني المحرمة، أو بصناعة آلات الملاهي، أو ما أشبه ذلك، لها حكمها، فالفنان فيما نسمع عنه أنه هو الذي يتعاطى الأغاني، ويتفنن في الأغاني، كيف يلقيها، وكيف يشجع عليها، وقد يدخل في ذلك من يكون عنده معرفة بالطرب، كيف يضرب الآلة عند الغناء كيف يعزف؟  السؤال: حصيلة المغني مباح؟  الجواب: لا ما هو مباحٌ.","link":"https://binbaz.org.sa/fatwas/3541/خطورة-المبالغة-في-حب-الفنانين-ولاعبي-الكرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1846.mp3","categories":["نصائح وتوجيهات"]},{"id":7615,"question":"أحسنتم، أيضاً يقول في سؤاله الثاني: هل يجوز استعمال الدف في الحفلات الدينية أم يعتبر من الآلات الموسيقية المحرمة، أفيدونا جزاكم الله خيراً؟","title":"حكم ضرب الدف في الحفلات الدينية","answer":"الجواب: الدف إنما هو في حق النساء، هذا هو الذي يجوز في حق النساء في الأعراس ونحوها من أمور النساء، وأما الرجال فلا يجوز لهم لا الدف ولا الطبل ولا غير ذلك؛ لأنه من آلات الملاهي، وإنما يجوز اللعب بالحراب.. بالأسلحة.. بالرمي.. بالبنادق؛ لأنه تدرب على شئون الحرب، كما فعل الحبشة بين يدي النبي صلى الله عليه وسلم بالدرق والحراب في مسجده عليه الصلاة والسلام، هذا لا بأس به، أما اللعب بالدفوف والطبول والأغاني عليه، هذا لا يجوز، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4668/حكم-ضرب-الدف-في-الحفلات-الدينية ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02304.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":7671,"question":"هذه مشكلة عائلية يعرضها سالم محمد عامر العسيري من تهامة عسير بلاد آل خنارش قرية العلكة يقول فيها: أفيدكم أنني شاب أبلغ من العمر تسعة عشر سنة حسن السيرة مع أهلي وعشيرتي، تزوجت من بنت خالي على رضا من الطرفين أنا وهي، ولم يمض على زواجنا أكثر من أسبوع حتى بدأت مشاكل أهلها تزداد يوم بعد يوم، حتى منعوها من مواجهتي قائلين: إنها مريضة ولا تستطيع مواجهتي، ثم أحضر مرات أخرى وأجدهم كل وقت يدبرون عذر للتخلص مني، كما أن زوجتي مجبورة على تنفيذ كل كلمة يوجهونها إليها، أنا محتار قررت أن أطلق زوجتي ولكن زوجتي لا تريد الطلاق، وأنا لا أطيق فراقها ولا أقدر أعرض مشكلتي على المحكمة بصفة والدها خالي شقيق والدتي، والناس يعتبرون ذلك عاراً، فما الحل المناسب الذي ترونه موافقاً يا فضيلة الشيخ؟","title":"نصيحة لولي منع ابنته من زوجها","answer":"الجواب: ننصح السائل بالصبر، وأن لا يعجل في الطلاق، وأن يخاطب خاله بالتي هي أحسن، ويطلب منه تمكينه من زوجته، وإعادتها إلى بيت الطاعة، وأن يتوسل إلى ذلك بالأقارب الطيبين والجيران الطيبين حتى يشيروا على والدها وينصحوه ويعيدها إلى زوجه، هذا الذي ننصح به.\nكما ننصح والدها بأن يتقي الله، وأن يعيد المرأة إلى زوجها، إلا أن يكون هناك عذر شرعي فيبين للزوج هذا العذر، فإما أن يفارق وإما أن يذهب معه إلى المحكمة، وفي المحكمة البركة والخير، أما أن يمنعها من زوجها بغير وجه شرعي فهذا حرام وظلم، والله جل وعلا يقول في كتابه العظيم: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19]، ويقول سبحانه: وَالظَّالِمُونَ مَا لَهُمْ مِنْ وَلِيٍّ وَلا نَصِيرٍ [الشورى:8].\nوالنبي يقول ﷺ: اتقوا الظلم فإن الظلم ظلمات يوم القيامة، فالواجب على خال هذا الزوج وهو أب المرأة، الواجب عليه أن يتقي الله، وأن يعيد المرأة إلى زوجها، وأن يتوسط بينهما في الخير، وأن ينصح للجميع، وأن يكون عوناً لهما على الاستقامة، والسيرة الحسنة، والمعاشرة الطيبة بينهما هذا هو الواجب عليه، فإن كان هناك أمور أخرى قد أخفاها السائل تحتاج إلى حل وسط من الأجاويد والإخوان الطيبين من يحلوا النزاع بينهما، فإن أعضلت المسألة ولم يتيسر ذلك فبالإمكان الاتصال بالمحكمة، والنظر في أمرهما من جهة المحكمة، أما منعها بغير حق فهذا لا يجوز له. نعم.","link":"https://binbaz.org.sa/fatwas/4870/نصيحة-لولي-منع-ابنته-من-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_039/03904.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":7742,"question":"من المحتار والمشغول الضمير علي حسن الزهراني من الرياض وزارة الداخلية يقول: أنا شاب عمري ثلاثة وعشرين سنة، ومتزوج ولله الحمد والشكر، ولكن لدي موضوع -وهي في الحقيقة مشكلة- وهي على النحو التالي: أصلي جميع الفروض ما عدا صلاة الفجر فهي تفوتني كل صبح إلا ما شاء الله تعالى، وأنا في حيرة من أمري، وقلق من هذه الحالة التي أنا فيها ومشغول يقول: أرجو أن أجد حلاً لمشكلتي هذه؟!","title":"توجيه لمن تفوته صلاة الفجر بسبب النوم","answer":"الجواب: هذه المشكلة ليست لك وحدك بل معك فيها ناس كثير وشباب كثير وغير الشباب أيضاً وهو التأخر عن صلاة الفجر، ولهذا أسباب من أهمها ومن أخطرها السهر وعدم النوم المبكر هذا هو السبب الوحيد، الغالب على الناس يسهرون لمشاهدة التلفاز أو لأسباب أخرى، فإذا سقط في آخر الليل نائماًَ عجز أن يقوم في آخر الليل حتى ولو كان عنده ساعة تنبه ما يسمعها حتى ولو جاءه منبهون يعجزون عنه بسبب ثقل النوم وغلبته عليه؛ فالعلاج الوحيد لهذا الأمر مع سؤال الله التوفيق والإعانة العلاج الوحيد هو عدم السهر، أن ينام المؤمن مبكراً، وألا يضر نفسه بمشاهدة التلفاز حتى يمضي عليه الليل الكثير أو يشتغل بأشياء أخرى من سماع أغاني أو سماع القيل والقال من أصحابه وزملائه أو موانع أخرى تمنعه من النوم المبكر، وإذا عالج الأمر بهذه الطريقة إن شاء الله يفلح.\nوأنت يا أيها السائل! الواجب عليك ألا تسهر وأن تنظر في الأسباب التي منعتك من القيام فإن كانت الأسباب أنك تتأخر في النوم تسهر فاتق الله وبادر بالنوم في أول الليل بعد صلاة العشاء بادر بالنوم حتى تستطيع القيام لصلاة الفجر وتصلي مع المسلمين في جماعة المسلمين، وهذا واجب عليك، والتساهل بهذا محرم ومن التشبه بالمنافقين لأن المنافقين لا يأتون الصلاة إلا دباراً ولا يشهدون العشاء والفجر هذه من أعمالهم الخبيثة، فالواجب على المسلم أن يحذر مشابهة المنافقين، وأن يجتهد في أداء فريضة الله في أوقاتها مع إخوانه المسلمين هذا إذا كان رجل، والمرأة كذلك عليها أن تتقي الله وأن تجتهد في أداء الصلاة في وقتها بعد طلوع الفجر قبل الشمس، ولا يجوز أبداً لأحد من الناس أن يؤخرها بعد طلوع الشمس كما يفعل بعض الناس يؤخرها فإذا قام لعمله بعد طلوع الشمس صلى هذا غلط عظيم ومنكر كبير لا يجوز لا للرجل ولا للمرأة ليس للرجل أن يؤخر ذلك حتى يقوم للدراسة أو للعمل ثم يصلي بعد طلوع الشمس؛ هذا لا يجوز هذا محرم، بل ذهب جمع من أهل العلم إلى أن من فعله كفر؛ لأن تأخير الصلاة عن وقتها كفر إذا تعمد ذلك لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر. هكذا بعض الطالبات تؤخر الصلاة حتى تقوم للدراسة بعد طلوع الشمس، وهذا أيضاً منكر ولا يجوز، والواجب على الجميع تقوى الله -وعلى أهلهن التنبيه على آبائهن وأمهاتهن وعلى إخوانهن التنبيه على ذلك وعلى آباء الشباب كذلك وأمهات الشباب، كل هذه أمور عظيمة يشترك فيها أهل البيت في إثمها إذا لم يتعاونوا على زوالها والمسلمون شيء واحد وأهل البيت شيء واحد يجب أن يتعاونوا في نصيحة المتخلف والأخذ على يديه حتى يستقيم على طاعة الله وأداء فرائضه، هذا هو الواجب على الجميع فإن كان هناك أسباب أخرى غير السهر، فالواجب عليك أن تعالجها، وأن تنظر ما هي الأسباب إن كان النوم يطير عنك من أول الليل ما تنام فاسأل الأطباء لعل عندهم دواء يزيل عنك هذا القلق وهذا السهر ويحصل لك الراحة والطمأنينة حتى تنام، وإن كان هناك علل أخرى فعالجها وإن كنت ليس عندك من يوقظك فاجعل عندك الساعة المعروفة المنبهة وأكد ......... على الوقت المناسب الذي هو وقت الأذان أو قرب الأذان حتى تسمعها وتقوم.\nعلى كل حال الواجب العلاج، والعلاج لا يخفى على العاقل، العلاج واضح تارة بالساعة وتارة بالمنبهين وتارة بعدم السهر، الواجب العلاج على الرجل والمرأة على جميع الناس، على الشباب والشيب.. على البنات والعجائز على الجميع ليس هذا خاصاً بأحد دون أحد الواجب على الجميع أن يعالجوا ما يقع لهم من هذا التأخر وأن ينظروا في الأسباب حتى تزال هذه الأسباب التي تقتضي التأخر حتى لا يصلي إلا بعد الشمس هذا منكر عظيم يجب أن يعالج من ابتلي به الوضع حتى يصلي الصلاة في وقتها مع الجماعة إن كان رجلاً وحتى تصليها المرأة في بيتها في الوقت قبل طلوع الشمس ونسأل الله للجميع الهداية والتوفيق.\nالمقدم: أحسنتم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/4942/توجيه-لمن-تفوته-صلاة-الفجر-بسبب-النوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_041/04103.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":7803,"question":"سؤاله الثاني والأخير يقول فيه: إنني أرتاح عندما يرثى أو يغني جماعة ما بأحد الموتى وحيث أن الدين نهى عن ذلك ونهى عن البكاء على الميت ولكني أتأثر وأرتاح عندما يبكون جماعة أو يرثون أحد الموتى، فهل علي ذنب أو كفارة في ذلك أدامكم الله على طريق الحق؟","title":"حكم رثاء الموتى","answer":"الجواب: هذا فيه تفصيل: إذا كان الرثاء من باب ذكر محاسن الميت بما يشوق إلى التأسي به والاقتداء به في الأعمال الطيبة من الجود والكرم والجهاد في سبيل الله وإنكار المنكر والدعوة إلى الخير فذكر هذا في المراثي ينفع المسلمين ولا يضرهم ويرتاح له كل مؤمن، أما إذا كانت الرثاء تهيج المصائب بالمصائب وتدعو إلى النياحة وتحرك أحوال أقارب الميت حتى يشتغلوا بالنياحة والصياح فلا ينبغي ذكرها ولا ينبغي قراءتها عندهم؛ لأن هذا يسبب مشاكل ويفضي إلى محرمات فلا يفعل.\nأما الأغاني التي تتضمن دعوة إلى الفسوق والعصيان أو تتضمن دعوة إلى شرب الخمور أو إلى غير هذا من الفساد أو إلى التشويق إلى النساء بغير حق أو إلى الحب بغير حق أو ما أشبه ذلك فهذه يجب إنكارها ويجب الحذر منها؛ لأنها تفسد الأخلاق وتفسد القلوب، كما قال ابن مسعود : «الغناء ينبت النفاق في القلب كما ينبت الماء البقل » والله يقول سبحانه وهو أصدق القائلين: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ [لقمان:6].\nأما الغناء الذي فيه الدعوة إلى الخير والأمر بالخير فينبغي أن يكون بألحان العرب فيكون بالأشعار العربية المعروفة والقصائد العربية فلا محذور فيه لكن بغير ألحان النساء وأشباه النساء، لا، يكون بألحان عربية بالشعر العربي كما كان حسان ينشد في عهد النبي ﷺ في الرد على المشركين.","link":"https://binbaz.org.sa/fatwas/5156/حكم-رثاء-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05006.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8191,"question":"هذه أيضاً من الأخت المرسلة المعذبة الحائرة (م. م. ن) من مكة المكرمة، تقول في رسالتها: أرجو من البرنامج أن يعرض رسالتي هذه على فضيلة الشيخ عبد العزيز بن عبد الله بن باز وفقه الله لما يحبه ويرضاه، أنا فتاة مؤمنة بالله وبوحدانيته، مؤدية لطاعاته، أسعى إلى كل ما يقرب إليه، إلا أنني أعيش في دوامة مستمرة من أمري، أعيش في صراع دائم مع نفسي، هذه النفس الأمارة بالسوء والتي هي سبب حيرتي وعذابي في حياتي، والتي لا أجد فيها الطمأنينة أبداً في جميع أعمالي، وخاصة العبادة، وعلى رأسها الصلاة، فعندما أقوم لتأديتها لا أجد ذلك الخشوع والخضوع المطلوبين فيها، تراودني أفكار شتى تجعلني أقطع القراءة، لكن أتعوذ من الشيطان، وأستغفر الله ثم أكمل، ولا ألبث لحظات إلا وأعود لمثلها، ولا أزال كذلك حتى أنتهي منها، وبعدها أشعر أن صلاتي غير مقبولة، وأن جميع أعمالي غير مقبولة مني، بكيت كثيراً واستغفرت كثيراً، وتبت إلى الله أكثر من مرة، ولكن أجد نفسي تقودني إلى المعاصي، فأنا الآن أعيش في عذاب وقلق وحيرة وخوف، أخاف أن ينقضي عمري وأنا على هذه الحالة، أخاف من أن تنتهي حياتي ولم أغتنم منها شيء، علماً بأنني لم أكن كذلك من قبل، فأرجو من فضيلته أن يشير علي بما يجب فعله، حتى أعود كما كنت سابقاً، وفقكم الله لما يحبه ويرضاه؟","title":"وسائل علاج الوساوس الشيطانية أثناء العبادة وغيرها","answer":"الجواب: أولاً: أسأل الله سبحانه للسائلة أن يوفقها لما فيه رضاه، وأن يصلح قلبها وعملها، وأن يرشدها إلى خير الأمور، وأن يهبها ثباتاً واستقامة وصلاحاً ورشداً، وأن يدلها على الخير الذي به الطمأنينة، وبه السعادة العاجلة والآجلة. ونصيحتي أن تكثري أيها السائلة من قراءة القرآن الكريم، بالتدبر والتعقل في الأوقات المناسبة، مع مطالعة كتب السنة وكتب التفسير التي تنفعك، مثل: رياض الصالحين، مثل: بلوغ المرام، مثل: الوابل الصيب، مثل: تفسير ابن كثير ، والبغوي ، وابن جرير ، هذه التفاسير المفيدة، تفسير الشوكاني ، حتى تستفيدي وحتى تشغلي الوقت بما ينفعك.\nوأمر آخر وهو مجالسة الأخيار من أهل بيتك، والأنس بهم، من أب وأم أو أخوات صالحات، تشغلي به بعض الوقت أيضاً، وإذا كنت ليست ذات زوج أن تحرصي على الزواج، ولو أن تخطبيه أنت، تنظرين من أقاربك من هو طيب، ومن هو صالح لك من أبناء العم، أو أبناء الخال، أو غيرهم ممن تعرفين، ثم تطلبين من أبيك أو غيره من أوليائك أن يتوسط بهذا، وتقولين: إنه بلغني عنه كذا، وبلغني عنه كذا من غير ريبة، بل بالسؤال عنه، والتعرف عليه، فإذا عرفت أنه صالح، وأنه جيد قلت لأبيك أو غيره من أوليائك: إنك تطلبين فلان حتى يتزوجك، وتنصحيه بألا يتكلف في المهور، ولا في الولائم، وأن يتسامحوا معه في المهر وفي الوليمة، كل هذا من أسباب الهدوء، ومن أسباب الثبات، ومن أسباب زوال هذه الوساوس والأفكار الرديئة. وإن كنت ذات زوج فالحمد لله، وعليك أن تعيشي معه طيباً، وأن تعامليه بالخير، وأن تعاشريه بالمعروف، وأن تجتهدي في أسباب الألفة معه والمحبة، وقضاء الوطر الشرعي، مع العناية بما تقدم من قراءة القرآن الكريم بتدبر، كثرة الذكر والاستغفار، كثرة التعوذ بالله من الشيطان الرجيم، الإكثار من قول: لا حول ولا قوة إلا بالله، ومع المطالعة للكتب النافعة المفيدة، كل هذا من أسباب زوال ما ذكرت من القلق، والوساوس التي قد تضرك، وأسأل الله لك الهداية والتوفيق، وصلاح النية والعمل.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/6006/وساىل-علاج-الوساوس-الشيطانية-اثناء-العبادة-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09307.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8206,"question":"الرسالة التالية باعثها أخونا عبد الله العنيزان من الجبيل، أخونا له عدد من الأسئلة من بينها سؤال يقول: ابنتي تذهب إلى الروضة، رياض الأطفال، ولكن من بين الأشياء التي يؤدونها بالروضة: أن المدرسة تفتح لهم المسجل، وتسمعهم الأناشيد الغير مبتذلة، مثلاً عن الأم والوطن وما شابه ذلك، ولكن تلك الأناشيد تكون مصحوبة بالموسيقى، فهل يجوز لي أن أدع ابنتي تذهب، وهل يكون علي ذنب إذا استمعت لمثل ذلك؟","title":"حكم الأناشيد المصحوبة بالموسيقى","answer":"الجواب: هذا غلط من المدرسة، أما سماع الطفلة للأناشيد السليمة فلا حرج في ذلك، وهكذا الطفل، وهكذا غيرهما، من الأناشيد التي ليس فيها محرم، إنما هي للتشجيع على الأخلاق الفاضلة، أو ما يتعلق بواجب الوطن عليهم، وواجب دولتهم ونحو ذلك.\nأما إصحابها بالموسيقى هذا غلط ولا يجوز، والواجب على القائم على الروضات منع ذلك، حتى لا يبقى هناك مانع من مجيء الأطفال إليهم، فعليك أنت وإخوانك أن تتصلوا بالمسئولين عن هذه الروضات حتى يمنعوا هذا الشيء ؛ لأن هذا لا حاجة إليه، ويربي الأطفال الصغار على حب الموسيقى والتلذذ بها واستماعها بعد ذلك، فالطفل على ما ربي عليه، فعليكم أن تتصلوا بالمسئولين في هذا عن المدارس حتى يمنعوا ذلك، وحتى تسلم هذه الروضات مما يخالف شرع الله . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6016/حكم-الاناشيد-المصحوبة-بالموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09502.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8217,"question":"الرسالة التالية باعثها أخونا عبد الله العنيزان من الجبيل، أخونا له عدد من الأسئلة من بينها سؤال يقول: ابنتي تذهب إلى الروضة، رياض الأطفال، ولكن من بين الأشياء التي يؤدونها بالروضة: أن المدرسة تفتح لهم المسجل، وتسمعهم الأناشيد الغير مبتذلة، مثلاً عن الأم والوطن وما شابه ذلك، ولكن تلك الأناشيد تكون مصحوبة بالموسيقى، فهل يجوز لي أن أدع ابنتي تذهب، وهل يكون علي ذنب إذا استمعت لمثل ذلك؟","title":"حكم الأناشيد المصحوبة بالموسيقى","answer":"الجواب: هذا غلط من المدرسة، أما سماع الطفلة للأناشيد السليمة فلا حرج في ذلك، وهكذا الطفل، وهكذا غيرهما، من الأناشيد التي ليس فيها محرم، إنما هي للتشجيع على الأخلاق الفاضلة، أو ما يتعلق بواجب الوطن عليهم، وواجب دولتهم ونحو ذلك.\nأما إصحابها بالموسيقى هذا غلط ولا يجوز، والواجب على القائم على الروضات منع ذلك، حتى لا يبقى هناك مانع من مجيء الأطفال إليهم، فعليك أنت وإخوانك أن تتصلوا بالمسئولين عن هذه الروضات حتى يمنعوا هذا الشيء ؛ لأن هذا لا حاجة إليه، ويربي الأطفال الصغار على حب الموسيقى والتلذذ بها واستماعها بعد ذلك، فالطفل على ما ربي عليه، فعليكم أن تتصلوا بالمسئولين في هذا عن المدارس حتى يمنعوا ذلك، وحتى تسلم هذه الروضات مما يخالف شرع الله . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6016/حكم-الاناشيد-المصحوبة-بالموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09502.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8283,"question":"الرسالة التالية باعثتها إحدى الأخوات من العراق بغداد تقول: إيمان كاظم جبار تقول: إنها شابة وموظفة وتبلغ من العمر ثمان وعشرين سنة وغير متزوجة، قدم لها شاب لا يعرف الكتابة ولا القراءة ويعمل نجارا، فقالت للشاب: روح تعلم كيف تكتب اسمك ثم تقدم للخطبة، وحينئذ عاد هذا فانتحر -كما تقول- وبدأ أصدقاؤها وأقرباؤها يلومونها على هذه اللفظة التي طلعت منها، حتى إن البعض قال: لقد ارتكبت رقبة، وهي الآن في قلق كبير، بم تنصحونها سماحة الشيخ؟","title":"حكم رفض المرأة الزواج من العامي الذي لا يكتب","answer":"الجواب: ليس عليك بأس يا أختي، ليس عليك بأس، نصحتِه يتعلم شيئاً من الكتابة وليس عليك بأس، وكونه انتحر هذا من سخافة عقله ومن جهله وقلة بصيرته، أنت ما قلت له إلا خيرًا، وتعلم الكتابة القليلة ميسرة، ميسر ليس بصعب، كونه يتعلم في الكتاب أو عند بعض أصحابه وإخوانه، كل هذا ميسر.\nفنصيحتك له إذا قلت له: تعلم الكتابة أو تعلم وتفقه في دينك، أو تعلم القرآن، كل هذا طيب ليس فيه شيء، وليس عليك بأس من ذلك، وإثمه عليه في انتحاره، أما أنت فليس عليك شيء واطمئني ودعي قول الناس.\nالمقدم: بارك الله فيكم. هنا رسالة وصلت إلى البرنامج من أحد الإخوة السودانيين: حيدر عبد الله أبو دياب يقول...\nالشيخ: نريد أن نزيدها.\nالمقدم: تفضل، تفضل.\nالشيخ: ونوصيك أيضًاً ونوصيك ألا تردِّي الطيب ولو كان عاميًّا لا يكتب ولا يقرأ، نوصيك في المستقبل، إذا خطبك الطيب المعروف بالاستقامة في دينه وصلاته وسمعته الحسنة فلا ترديه وإن كان لا يقرأ ولا يكتب، والنصيحة بعد ذلك بعد الزواج بينك وبينه، فلا تردي الطيب وإن كان لا يقرأ ولا يكتب، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6091/حكم-رفض-المراة-الزواج-من-العامي-الذي-لا-يكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10005.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":8284,"question":"الرسالة التالية باعثتها إحدى الأخوات من العراق بغداد تقول: إيمان كاظم جبار تقول: إنها شابة وموظفة وتبلغ من العمر ثمان وعشرين سنة وغير متزوجة، قدم لها شاب لا يعرف الكتابة ولا القراءة ويعمل نجارا، فقالت للشاب: روح تعلم كيف تكتب اسمك ثم تقدم للخطبة، وحينئذ عاد هذا فانتحر -كما تقول- وبدأ أصدقاؤها وأقرباؤها يلومونها على هذه اللفظة التي طلعت منها، حتى إن البعض قال: لقد ارتكبت رقبة، وهي الآن في قلق كبير، بم تنصحونها سماحة الشيخ؟","title":"حكم رفض المرأة الزواج من العامي الذي لا يكتب","answer":"الجواب: ليس عليك بأس يا أختي، ليس عليك بأس، نصحتِه يتعلم شيئاً من الكتابة وليس عليك بأس، وكونه انتحر هذا من سخافة عقله ومن جهله وقلة بصيرته، أنت ما قلت له إلا خيرًا، وتعلم الكتابة القليلة ميسرة، ميسر ليس بصعب، كونه يتعلم في الكتاب أو عند بعض أصحابه وإخوانه، كل هذا ميسر.\nفنصيحتك له إذا قلت له: تعلم الكتابة أو تعلم وتفقه في دينك، أو تعلم القرآن، كل هذا طيب ليس فيه شيء، وليس عليك بأس من ذلك، وإثمه عليه في انتحاره، أما أنت فليس عليك شيء واطمئني ودعي قول الناس.\nالمقدم: بارك الله فيكم. هنا رسالة وصلت إلى البرنامج من أحد الإخوة السودانيين: حيدر عبد الله أبو دياب يقول...\nالشيخ: نريد أن نزيدها.\nالمقدم: تفضل، تفضل.\nالشيخ: ونوصيك أيضًاً ونوصيك ألا تردِّي الطيب ولو كان عاميًّا لا يكتب ولا يقرأ، نوصيك في المستقبل، إذا خطبك الطيب المعروف بالاستقامة في دينه وصلاته وسمعته الحسنة فلا ترديه وإن كان لا يقرأ ولا يكتب، والنصيحة بعد ذلك بعد الزواج بينك وبينه، فلا تردي الطيب وإن كان لا يقرأ ولا يكتب، وفق الله الجميع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6091/حكم-رفض-المراة-الزواج-من-العامي-الذي-لا-يكتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10005.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":8298,"question":"سؤاله الأخير في رسالته يقول: مع حفظي لكتاب الله، ومواظبتي على الصلوات إلا أنني أميل إلى استماع المطربين والمغنين، فما الحكم في هذا، وكيف أتخلص من ذلك؟","title":"كيفية الابتعاد عن سماع الغناء","answer":"الجواب: عليك أن تجاهد نفسك وأن تعتاض عن ذلك بسماع القرآن الكريم، والإكثار من تلاوته والاشتغال بذكر الله  وبما ينفعك في أمر دينك ودنياك، أما سماع المطربين والمطربات فهو من وسائل الشر، من وسائل عمى القلوب، ومن وسائل قسوتها وانحرافها عن طريق الخير، فإياك وهذا العمل احذره غاية الحذر، وقد قال الله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] فجعل لهو الحديث مضلاً عن سبيل الله، ولهو الحديث هو الغناء وآلات الملاهي كما قال جمهور أهل العلم في تفسير الآية.\nفالواجب عليك الحذر من هذا السبيل، وأن تعتاض عن هذا الشر بما شرع الله من الخير في استماع القرآن الكريم، وتدبر معانيه.. بالإكثار من تلاوته.. بالإكثار من ذكر الله.. في التحدث مع إخوانك فيما ينفعكم، والمذاكرة فيما ينفعكم.. في التحدث مع أهلك فيما ينفعكم.. في الاشتغال بشيء آخر من الأمور المباحة حتى تشتغل عما حرم الله بما أباح الله، رزق الله الجميع الهداية. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6114/كيفية-الابتعاد-عن-سماع-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20104.mp3","categories":["الشعر والأغاني","نصائح وتوجيهات"]},{"id":8309,"question":"سؤاله الأخير في رسالته يقول: مع حفظي لكتاب الله، ومواظبتي على الصلوات إلا أنني أميل إلى استماع المطربين والمغنين، فما الحكم في هذا، وكيف أتخلص من ذلك؟","title":"كيفية الابتعاد عن سماع الغناء","answer":"الجواب: عليك أن تجاهد نفسك وأن تعتاض عن ذلك بسماع القرآن الكريم، والإكثار من تلاوته والاشتغال بذكر الله  وبما ينفعك في أمر دينك ودنياك، أما سماع المطربين والمطربات فهو من وسائل الشر، من وسائل عمى القلوب، ومن وسائل قسوتها وانحرافها عن طريق الخير، فإياك وهذا العمل احذره غاية الحذر، وقد قال الله : وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6] فجعل لهو الحديث مضلاً عن سبيل الله، ولهو الحديث هو الغناء وآلات الملاهي كما قال جمهور أهل العلم في تفسير الآية.\nفالواجب عليك الحذر من هذا السبيل، وأن تعتاض عن هذا الشر بما شرع الله من الخير في استماع القرآن الكريم، وتدبر معانيه.. بالإكثار من تلاوته.. بالإكثار من ذكر الله.. في التحدث مع إخوانك فيما ينفعكم، والمذاكرة فيما ينفعكم.. في التحدث مع أهلك فيما ينفعكم.. في الاشتغال بشيء آخر من الأمور المباحة حتى تشتغل عما حرم الله بما أباح الله، رزق الله الجميع الهداية. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6114/كيفية-الابتعاد-عن-سماع-الغناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_201/20104.mp3","categories":["الشعر والأغاني","نصائح وتوجيهات"]},{"id":8336,"question":"أختنا تثير قضية سماحة الشيخ ألا وهي كون هذا الرجل الذي تزوجها ولم تحسن العشرة بينهما أنه كان متزوجاً وطلق، وهي تخاف ذلك الخوف، هل من كلمة حول هذا الموضوع لو تكرمتم؟","title":"حكم رفض الزواج من كبير السن وممن تزوج وطلق","answer":"الجواب: ليس هذا بعذر، الإنسان قد يتزوج ويطلق ثم يوفقه الله للزوجة الثانية ولا يطلق فليس هذا بعذر، وكذلك كبار السن كونه يكبرها بعشر سنين أو بعشرين سنة أو بثلاثين سنة ليس هذا بعذر، فقد تزوج النبي ﷺ عائشة وهو ابن ثلاث وخمسين سنة وهي بنت تسع سنين، وعند ....... وهي بنت ست أو سبع سنين، فالكبر لا يضر، فلا حرج أن تكون المرأة أكبر ولا حرج أن يكون الزوج أكبر، فقد تزوج النبي ﷺ خديجة وهي بنت أربعين وهو ابن خمس وعشرين قبل أن يوحى إليه عليه الصلاة والسلام، فهي تكبره بخمسة عشرة سنة رضي الله عنها وأرضاها، ثم تزوج عائشة وهي صغيرة بنت ست أو سبع سنين ودخل بها وهي بنت تسع سنين وهو ابن ثلاث وخمسين سنة. وكثير من هؤلاء الذين يتكلمون في المذياع أو في التلفاز وينفرون من تفاوت سن الزوج والزوجة كله خطأ كله غلط، لا يجوز لهم هذا الكلام، الواجب أن المرأة تنظر في الزوج فإذا كان صالحاً ومناسباً فإنه ينبغي لها أن توافق، ولو كان فوق هذا السن بكثير، وهكذا الرجل ينبغي له أن يعتني بالمرأة الصالحة ذات الدين ولو كانت أكبر منه، إذا كانت في سن الشباب وسن الإنجاب ولو كانت فوقه في السن.\nفالحاصل أن السن لا ينبغي أن يكون عذراً ولا ينبغي أن يكون عيباً ما دام الرجل صالحاً والفتاة صالحة، الله يصلح حال الجميع.","link":"https://binbaz.org.sa/fatwas/6151/حكم-رفض-الزواج-من-كبير-السن-وممن-تزوج-وطلق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_111/11108.mp3","categories":["نصائح وتوجيهات"]},{"id":8374,"question":"هل يجوز للخاطب عندما يخطب لابنه أو أحد أقربائه زوجة أن يخفي ما في ابنه أو غيره من عيوب، كأن يكون أعرج، أو أعمى؟","title":"حكم إخفاء عيوب الخاطب أو المخطوبة","answer":"الجواب: ليس له أن يخفي العيوب، وليس لأهل المرأة أن يخفوا عيوبها، الواجب البيان، لأن المسلم أخو المسلم والرسول ﷺ يقول: الدين النصيحة ويقول جرير : بايعت النبي ﷺ على إقام الصلاة وإيتاء الزكاة والنصح لكل مسلم.\nفليس له أن يخفي عيوبه، وليس لها أن تخفي عيوبها، وليس لأهل المرأة أن يخفوا عيوبها، بل عليهم أن يوضحوا للرجل على ما هي عليه، صحيحة أو مريضة، عوراء أو عمياء، عرجاء أو غير ذلك، حتى يقدم على بصيرة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6223/حكم-اخفاء-عيوب-الخاطب-او-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_114/11414.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8396,"question":"أولى رسائل هذه الحلقة سماحة الشيخ رسالة وصلت إلى البرنامج من الأخ (م. ع. أ) سوداني مقيم في المدينة المنورة، أخونا يقول: سبق أن قلت لوالدي: زوجني بابنة خالي؛ لأنها يتيمة، إلا أن والدي أصر على تزويجي بابنة عمي؛ لأن عمي له ثروة ضخمة، كما يقول سماحة الشيخ، ويرجو التوجيه لو تكرمتم؟","title":"مراعاة ذات الدين عند إرادة الزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، نبينا وإمامنا وسيدنا محمد بن عبد الله، وعلى آله وأصحابه ومن سلك سبيله واهتدى بهداه إلى يوم الدين.\nأما بعد:\nفالواجب عليك وعلى أبيك العناية بالزوجة الصالحة، وعدم النظر إلى المال، المهم أن تكون المرأة صالحة مستقيمة في دينها، فعليك أن تتحرى أنت ووالدك هذا الصنف من النساء.\nأما مراعاة المال فلا تنبغي أن تكون مقصودةً، وإنما المقصود الأعظم المهم هو مراعاة الدين والأخلاق، كما قال النبي ﷺ: فاظفر بذات الدين تربت يداك يقول ﷺ: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها فاظفر بذات الدين تربت يداك فإذا تيسر الدين فما معه بعد ذلك من جمال أو مال أو حسب خير إلى خير، لكن الأهم الأول هو كونها في نفسها صالحة مستقيمة حتى تنفعك، وحتى تأمنها على عرضها، وعلى بيتك، وعلى مالك، وعلى كل شئونك، فإذا كانت بنت خالتك أنسب في الدين فينبغي للوالد أن يوافقك على ذلك، وإن كانت بنت عمك أنسب فينبغي لك أن توافق أباك على ذلك، وإن لم تكونا مناسبتين فالتمسا غيرهما، التمسا امرأةً أخرى، وليس من اللازم أن تكون قريبة بنت خال أو بنت عم ولو بعيدة من الناس من سائر الناس، هذا هو الذي ينبغي لك ولأبيك، التماس المرأة الطيبة، وإذا كانت بنت عمك وبنت خالك متقاربتين، فالأولى أن تقبل ما رآه والدك، وأن تخضع لقول والدك إذا كانتا متقاربتين في الدين والأخلاق والجمال ونحو ذلك، بكل حال كونك توافق والدك أمر مطلوب، لكن بشرط أن تكون المرأة التي أشار بها صالحة مناسبة، وفق الله الجميع. نعم.","link":"https://binbaz.org.sa/fatwas/6262/مراعاة-ذات-الدين-عند-ارادة-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_117/11701.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8442,"question":"الأخ هارون أيضاً يقول: إن النساء هناك يستمعن إلى الأغاني، ويرجو من سماحة الشيخ النصيحة؟","title":"حكم الاستماع إلى الأغاني وآثار ذلك","answer":"الجواب: نصيحتي لجميع الرجال والنساء عدم استماع الأغاني؛ فالأغاني خطرها عظيم؛ وقد بلي الناس بها في الإذاعات وفي التلفاز وفي أشياء كثيرة من الأشرطة وهذا من البلاء.\nفالواجب على أهل الإسلام من الرجال والنساء أن يحذروا شرها، وأن يعتاضوا عنها بسماع ما ينفعهم من كلام الله عز وجل، ومن كلام رسوله عليه الصلاة والسلام، ومن كلام أهل العلم الموفقين في أحاديثهم الدينية وندواتهم ومقالاتهم، كل ذلك ينفعهم في الدنيا والآخرة.\nأما الأغاني فشرها عظيم، وربما سببت للمؤمن انحرافاً عن دينه، والمؤمنة كذلك، وربما أنبتت النفاق في القلب بكراهة الخير؛ لأن النفاق أصله كراهة الخير وحب الشر، إظهار الإسلام وإبطان سواه.\nفالنفاق خطره عظيم، والأغاني تدعو إليه، فإن من اعتادها ربما كره سماع القرآن، وسماع النصايح والأحاديث النافعة، وأحاديث الرسول عليه الصلاة والسلام؛ وربما جرته إلى حب الفحش، والفساد، واعتياد الفواحش والرغبة فيها، والتحدث مع أهلها، والميل إليهم. فالواجب على أهل الإيمان من الرجال والنساء الحذر من شرها، يقول الله عز وجل في كتابه العظيم: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ ۝ وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنََّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ [لقمان: 6 - 7].\nيقول علماء التفسير: إن لهو الحديث هو الغناء، ويلحق بذا كل صوت منكر، كالمزامير وآلات الملاهي، هكذا قال أكثر علماء التفسير رحمة الله عليهم.\nوقال عبد الله بن مسعود : هو والله الغناء -وكان يقسم على ذلك، ويقول: إن الغناء ينبت النفاق في القلب كما ينبت الماء البقل يعني: الزرع، ومعنى ذلك: أنه يسبب للإنسان كراهة الخير وحب الشر، كراهة الذكر والقرآن ونحو ذلك، وحب الأغاني والملاهي وأشباه ذلك، وهذا نوع من النفاق؛ لأن المنافق يتظاهر بالإسلام ويكرهه في الباطن، يتظاهر بأنه مؤمن وهو في الباطن ليس كذلك، يتظاهر بحب القرآن وهو في الباطن ليس كذلك؛ فالأغاني تدعو إلى ذلك، تدعو إلى كراهة سماع القرآن والاستماع له، وتدعو إلى كراهة سماع الذكر والدعوة إلى الله، ويدعو أهلها يعني: الغناء يدعو أهله إلى خلاف ذلك، إلى حب المجون وحب الباطل، وحب الكلام السيئ، وحب الكلام في الفحش والغناء والمحبة، ونحو ذلك مما يتسبب عن الغناء مما يجر إلى انحراف القلوب؛ ومحبتها لما حرم الله، وكراهتها لما شرع الله ، وهذا واضح ممن جرب ذلك، فإن من جرب ذلك وعرف ذلك يعلم هذا، وهكذا الذين عرفوا أصحاب الغناء، وعرفوا أحوالهم، يظهر عليهم من الانحراف والفساد؛ بسبب حبهم للغناء ما هو شر عظيم، وفساد كبير لمن اعتاد ذلك، ولا حول ولا قوة إلا بالله. نعم.","link":"https://binbaz.org.sa/fatwas/6326/حكم-الاستماع-الى-الاغاني-واثار-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_120/12007.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":8475,"question":"رسالة بعثت بها إحدى الأخوات المستمعات تقول: أختكم أم محمد: تقول: إنها أم لأربعة أطفال أكبرهم في السادسة، وليس في المدينة التي تسكن فيها أحد من قرائبها، وتحتاج إلى مساعدة في شئون المنزل وتفكر في استحضار خادمة، وأمها تلح عليها في ذلك، لكن لا ترتاح لظاهرة الخدم، ذلك أنها تخشى من خروج الخادمة إلى السوق وليس معها من يصونها فتسأل: هل نصون الخادمات كما نصون بناتنا وأخواتنا ويجب علينا ذلك وترجو التوجيه؟","title":"ضوابط الاستعانة بالخادمة","answer":"الجواب: نعم السلامة من جلب الخادمات أولى وأصلح، وإذا قامت المرأة بما يلزمها في البيت واستعانت بالله  واستغنت عن الخادمات فذلك خير لها، وأبعد عن الخطر، فقد تكون الخادمة ليست ذات دين، فتضر البيت وأهله، وتضر الزوج إذا كان في البيت زوج أو أخ للمرأة أو غير ذلك من الرجال.\nفالحاصل أن السلامة من الخادمات أولى وأحوط، فإذا دعت الحاجة إلى ذلك والضرورة فينبغي أن يختار من ذلك الخادمة الطيبة المسلمة وأن تلاحظ وتراقب حتى لا يقع ما يخالف أمر الله.\nوهكذا تمنع من الخروج إلا إذا كانت ممن يؤمن في ذلك، وكان الخروج لحاجة كشراء حاجة من السوق إذا كانت البلد آمنة والخروج لا خطر فيه، وإلا فليخرج معها ثانية أو ثالثة أو من هو مأمون حتى يكون معها إلى أن تقضي الحاجة وترجع.\nفالحاصل: أن هذا المقام يحتاج إلى عناية وإلى خوف من الله ومراقبة وإلى بعد مما قد يفضي إلى الخطر الذي لا يرضاه الله .\nومهما أمكنت السلامة من الخدم وأن تقوم المرأة بحاجات البيت، وأن تستريح من الأخطار التي قد تنجم عن وجود الخادمة، إما مع الزوج وإما مع رجال البيت، وإما في الخارج عند خروجها للحاجات فهذا خير للبيت وأهله، والله ولي التوفيق.\nالمقدم: جزاكم الله خيراً، إذاً الاهتمام بشئون الخادمة كالاهتمام بشئون نساء البيت؟\nالشيخ: حق.. حق عليهم نعم حق عليهم أن يهتموا بها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6512/ضوابط-الاستعانة-بالخادمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_125/12502.mp3","categories":["نصائح وتوجيهات"]},{"id":8557,"question":"هذه رسالة من السائل (ع. س) سوري الجنسية مقيم في الرياض، يقول في رسالته: أنا متزوج وبعد زواجي بخمس سنوات علمت من أحد الجيران أن زوجتي تمارس الفاحشة، فراقبت ذلك فوجدته صحيحاً، فما كان مني إلا أن قمت بضربها، فطلبت مني الطلاق أكثر من مرة فلم أطلقها خوفاً من تشتت الأولاد، ولو طلقتها ليس عندي مال أتزوج به، وأنا عامل عادي يوم أعمل وأكثر الأيام بدون عمل أفيدوني ماذا أفعل، بارك الله فيكم؟","title":"ما يجب على من علم عن زوجته أنها تفعل الفاحشة؟","answer":"الجواب: هذه من المصائب العظيمة، والواجب علاجها بالتأديب والنصيحة، وتوجيه اللوم إليها وبيان أن الواجب عليها العفة، والحذر مما حرم الله عليها فإن الزنا من أقبح الجرائم ومن أعظم الكبائر، وقد توعد الله الزاني بالعذاب الشديد، قال جل وعلا: وَالَّذِينَ لا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ۝ يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا نعوذ بالله، ... توعد الزاني بأنه يضاعف له العذاب، ويخلد فيه مهاناً يوم القيامة في النار نسأل الله العافية. والنبي عليه الصلاة والسلام قال: لا يزني الزاني حين يزني وهو مؤمن هذا من علامة ضعف الإيمان، أو عدم الإيمان نعوذ بالله، فعلى الزوج أن يلاحظها ويعتني بها ويؤدبها فيما إذا فعلت شيئاً من هذا، أو وجد علامات شيء من ذلك، فعليه أن يؤدبها الأدب الرادع مع الوعظ والتذكير بالله، وأن هذا منكر ومعصية لله ، ومن أسباب الفراق، فإن استقامت فالحمد لله، وإن لم تستقم فارقها طلقها؛ لئلا تحمل عليه أولاداً من غيره، ومتى استقامت وتابت ورجعت إلى الله  فالحمد لله، فالتوبة بابها مفتوح ومن تاب تاب الله عليه إذا كان صادقاً، فأما إن لم يحصل منها الرجوع والتوبة واستمرت على حالها السيئة، فإن مثل هذه لا ينبغي بقاؤها، بل ينبغي فراقها وعدم بقائها؛ لأن هذا يجر عليه شراً كثيراً في نفسه وفي أولاده، وفي سمعته، ولا حول ولا قوة إلا بالله! نعم.\nالمقدم: ألا توجهون سماحة الشيخ إلى سد أبواب التي تؤدي لمثل هذا من التساهل باختلاط النساء والرجال ودخول غير المحارم؟\nالشيخ: كذلك هذا حق أيضاً كونه يعني، يعتني بسد الأبواب التي تفضي إلى هذا الشيء مثل منعها من الخروج، ومثل عدم اختلاطها بالنساء الخبيثات من جيران أو غيرهم، إذا تيسر له هذا، هذا من أهم الأمور ألا تخالط الرديئات، وألا تخرج الأسواق، وأن تحرص على الحجاب، ولكن من اعتادت الفاحشة والعياذ بالله تحصلها ولو بالهاتف نسأل الله العافية وهي في بيتها نسأل الله ....، لكن على كل حال تعاطي الأسباب مهما أمكن إذا كان من عادتها الخروج يمنعها من الخروج إلا من ضرورة، وإذا كان يدخل عليها أحد رديء يمنع الداخل الرديء، وإذا كانت تخرج إلى جيران ليسوا بطيبين يمنعها من ذلك، وهكذا، يعني: يتعاطى الأسباب..\nالمقدم: والخروج إلى غير المحارم، مقابلة غير المحارم يتساهل فيه كثير من الناس؟\nالشيخ: كذلك خروجها إلى غير المحارم إلى بني عمها الذين لا يؤمنون، أو إلى غيرهم كل هذا يعني: عليه أن يجتهد في منع أسباب الشر مهما أمكن.\nالمقدم: جزاكم الله خير، وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6631/ما-يجب-على-من-علم-عن-زوجته-انها-تفعل-الفاحشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20604.mp3","categories":["الحقوق الزوجية","نصائح وتوجيهات"]},{"id":8595,"question":"إذاً أي مشاكل تنشأ في أسر يوجهوا بالتزام ماذا لو تكرمتم؟","title":"كيفية حل الخلافات العائلية","answer":"الجواب: جميع المشاكل التي تقع بين الأسر إذا كانت مشاكل لا تخالف النصوص وإنما هي عادية بين الناس، ويكون حلها من طريق اتفاقهم عليها لا بأس، فالأمور العادية والعرف العادي في المآكل أو مشارب أو أنواع الملابس أو ما أشبه ذلك، أما مشكلة قد جاء النص بإيضاحها من كتاب الله أو سنة رسوله ﷺ وقد بينها الله  أو رسوله فلا قول لأحد يخالف شرع الله، من قال بخلاف الشرع لا يطاع إنما الطاعة في المعروف كالسفور أو التبرج في الأسواق أو وقوف مواقف التهم أو ما أشبه ذلك كل هذه الأمور الشرع قضى فيها، فالواجب الالتزام بعمل الشرع، فلا يجوز للمرأة أن تتبرج بين الرجال، ولا يجوز لها أن تبدي زينتها، ولا يجوز لها أن تقف مواقف التهم، وهكذا الرجل ليس له أن يقف مواقف التهم.\nفالمقصود أن هذه أمور حلها الشرع، وبينها الشرع، فالواجب التزام الشرع. نعم.","link":"https://binbaz.org.sa/fatwas/6706/كيفية-حل-الخلافات-العاىلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_128/12807.mp3","categories":["نصائح وتوجيهات"]},{"id":8628,"question":"ا لسؤال: هذه رسالة وردتنا من السائل (ع. عبد الحميد مرسي ) مصري يعمل بالأردن، يقول: خطبت فتاة منذ ثلاثة أعوام، وقدمت لها شبكة وقمت بتجهيز كل شيء من الجهاز وخلافه، وفجأة حدث رفض من ناحية والدتها، وأصبح زواجي منها مستحيل، مع العلم أن الفتاة ليس لها أي ذنب في ذلك، هل لي الحق في استرداد كل ما قدمته من ذهب وخلافه أم لا؟","title":"حكم استرداد الخاطب ما دفعه للمخطوبة","answer":"الجواب: نعم، لك -يا أخي- الحق فيما قدمت؛ لأنك قدمته ليعطوك البنت، فإذا منعوا البنت وجب عليهم رد ما قدمت إليهم من قليل وكثير، والواجب على أمها أن تتقي الله، إذا كنت أهلاً للبنت في دينك وليس هناك مانع ديني والمرأة راضية -البنت راضية- وليس هناك موانع شرعية فالواجب أن تعين على الخير وأن لا تمنع زواج بنتها منك، هذا هو الواجب؛ لأن تزويج البنات من أهم المهمات لما فيه من العفة لهن والحرص على سلامتهن من الفساد، وهكذا الشباب تزويجهم من أهم المهمات لما في ذلك من إبعاده عن الخطر وتمكينه من غض البصر وإحصان الفرج، وقد قال النبي ﷺ في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء متفق على صحته، هذا الحديث الصحيح عن رسول الله عليه الصلاة والسلام يبين لنا أن المبادرة بالزواج للشباب أمر لازم، والصحيح: أنه فرض، لما فيه من الخير الكثير والمصالح العظيمة للذكر والأنثى.\nفعلى الآباء والإخوة والأقارب أن يساعدوا في هذا، وأن يعينوا الشاب على الزواج ويعينوا الفتاة على الزواج، وأن لا يضعوا العراقيل، وكذلك ينبغي التساهل في المهور والولائم؛ لأنها عقبة أيضاً، فالواجب على الجميع التعاون على الخير والتواصي بالحق، فالأم تساعد، والأب يساعد، والعم يساعد، والأخ يساعد، لا من جهة المهر وتخفيفه، ولا من جهة الولائم، ولا من جهة توابع المهر، كلها ينبغي فيها التخفيف ويشرع فيها التخفيف والإعانة على الخير.\nوإذا كانت الفتاة جيدة طيبة في دينها فينبغي المسارعة إلى خطبتها، وإذا كان الرجل طيباً فتنبغي المسارعة إلى قبوله وتلبية طلبه، والمبادرة إلى تزويجه؛ لأن الشاب الصالح غنيمة، والفتاة الصالحة غنيمة، فلا ينبغي للمؤمن إذا كان أباً أو أماً أن يعرقل هذه الأمور، نسأل الله للجميع الهداية.\nوبكل حال إذا خطب الإنسان وقدم المهر والكساوي وغير ذلك ثم ردوه يلزمهم أن يعطوه كلما أخذوا منه، يلزمهم أن يردوا عليه كلما أخذوا منه من قليل أو كثير إلا إذا سمح عن شيء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6766/حكم-استرداد-الخاطب-ما-دفعه-للمخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_211/21107.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":8640,"question":"وفي مطلع الحلقة نكمل رسالة سبق أن عرضنا بعض أسئلتها للسائل عبد الله رجا معايعة من الأردن يقول: هناك بعض المسلمين يمتنعون عن الأكل مع بعض الناس ولو مع نسائهم ولو مع إخوانهم، وعندما تقول له: لماذا؟ يقول: لأن هؤلاء الناس يأكلون مع مرابي أو مع شارب خمر، فما حكم هذا العمل أفيدونا أفادكم الله؟","title":"الحث على تحري صحبة الأخيار","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أنه ينبغي للمؤمن أن يتحرى صحبة الأخيار ومجالستهم، قال النبي ﷺ: لا تصاحب إلا مؤمناً ولا يأكل طعامك إلا تقي قال جمع من أهل العلم: معناه: لا تتخذهم أصحاباً وأخداناً إلا إذا كانوا أتقياء أهل خير، لكن ما يتعلق بالضيف والشيء العارض لا حرج إذا أكل معك من لا يرتضى، جاء ضيفاً أو صادفته عند غيرك فلا بأس؛ ولو كان ممن يظن فيه الربا أو يظن فيه أنه يجالس أهل الخمر أو ما أشبه ذلك، لكن أنت لا تتخذهم أصحاب إذا عرفت أنهم أصحاب خمر أو أصحاب فساد اجتنبهم وابتعد عنهم. يقول النبي ﷺ: مثل الجليس الصالح كحامل المسك؛ إما إن يحذيك -يعني: يعطيك- وإما أن تبتاع منه، وإما أن تجد منه ريحاً طيبة، ومثل جليس السوء مثل نافخ الكير؛ إما أن يحرق ثيابك، وإما أن تجد منه ريحاً خبيثة فالنبي ﷺ يحثنا بهذا على صحبة الأخيار وأن يكونوا هم الجلساء هم الأصحاب في الحضر والسفر، ويحذرنا من صحبة الأشرار، لكن ما يعرض من العوارض من غير أن يكون صاحبا لكونه ضيفاً، أو لكونك صادفته في دعوة ووليمة فلا حرج في ذلك. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6774/الحث-على-تحري-صحبة-الاخيار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21201.mp3","categories":["نصائح وتوجيهات"]},{"id":8643,"question":"هذه رسالة وردتنا من السائل: (م. ع. أ) من السودان في الحقيقة له فيها عدة أسئلة نعرض بعضها والبعض الآخر قد تكررت الإجابة عنه في كثير من حلقات البرنامج، يقول في سؤاله: تزوجت ولي عشر سنوات ولم أنجب، وتلك إرادة الله سبحانه، ولكن  إذا كان في هذه المسألة مصدر عدم الإنجاب الرجل، فهل عليه ذنب إذا لم يصارح المرأة بذلك، وهل يترتب على الإنسان أن يسرحها، وما الحكم أفيدونا أفادكم الله؟","title":"ما يفعله من أصيب بالعقم مع امرأته","answer":"الجواب: إذا لم يقدر للمؤمن الإنجاب فليس من المقطوع به أن يكون عقيماً، فقد تكون هناك أسباب تحتاج إلى علاج فكل داء له دواء، فإذا تحقق من طريق أهل الخبرة من الأطباء أنه عقيم فقد اختلف العلماء، هل للمرأة الفسخ أم لا؟ فإن طلقها تحقيقاً لطلبها ورحمة لها فهذا حسن من دون حاجة إلى المخاصمة إذا طلبت ذلك، فالأولى له والأفضل والأحوط أن يطلقها إذا طلبت الطلاق، أو يرضيها بشيء حتى تبقى معه راضية مطمئنة، وأما كونه يحكم لها بالفراق هذا محل نظر ويرجع إلى المحاكم.\nلكن نصيحتي لمن أصيب بالعقم أن يستشير المرأة ويخبرها؛ فإن سمحت ورضيت فلا بأس ولا حرج عليه، وإن أرضاها بشيء من المال كمقرر شهري أو سنوي فلا بأس، أما إن صممت على طلب الطلاق فإن نصيحتي له أن يطلقها وأن لا يخاصمها عند المحاكم بل يطلقها لعل الله يرزقها ذرية، وهو قد يجد غيرها وربما أخطأ الأطباء في قولهم: إنه عقيم، وربما يسر الله له زوجة أخرى أو زوجة ثالثة فتحمل منه، فقد يقول الأطباء: إنه عقيم ويخطئون ويغلطون، هذه نصيحتي للأخ السائل. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6775/ما-يفعله-من-اصيب-بالعقم-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21202.mp3","categories":["الطب والتداوي","نصائح وتوجيهات"]},{"id":8646,"question":"هذه رسالة وردتنا من السائل: (م. ع. أ) من السودان في الحقيقة له فيها عدة أسئلة نعرض بعضها والبعض الآخر قد تكررت الإجابة عنه في كثير من حلقات البرنامج، يقول في سؤاله: تزوجت ولي عشر سنوات ولم أنجب، وتلك إرادة الله سبحانه، ولكن  إذا كان في هذه المسألة مصدر عدم الإنجاب الرجل، فهل عليه ذنب إذا لم يصارح المرأة بذلك، وهل يترتب على الإنسان أن يسرحها، وما الحكم أفيدونا أفادكم الله؟","title":"ما يفعله من أصيب بالعقم مع امرأته","answer":"الجواب: إذا لم يقدر للمؤمن الإنجاب فليس من المقطوع به أن يكون عقيماً، فقد تكون هناك أسباب تحتاج إلى علاج فكل داء له دواء، فإذا تحقق من طريق أهل الخبرة من الأطباء أنه عقيم فقد اختلف العلماء، هل للمرأة الفسخ أم لا؟ فإن طلقها تحقيقاً لطلبها ورحمة لها فهذا حسن من دون حاجة إلى المخاصمة إذا طلبت ذلك، فالأولى له والأفضل والأحوط أن يطلقها إذا طلبت الطلاق، أو يرضيها بشيء حتى تبقى معه راضية مطمئنة، وأما كونه يحكم لها بالفراق هذا محل نظر ويرجع إلى المحاكم.\nلكن نصيحتي لمن أصيب بالعقم أن يستشير المرأة ويخبرها؛ فإن سمحت ورضيت فلا بأس ولا حرج عليه، وإن أرضاها بشيء من المال كمقرر شهري أو سنوي فلا بأس، أما إن صممت على طلب الطلاق فإن نصيحتي له أن يطلقها وأن لا يخاصمها عند المحاكم بل يطلقها لعل الله يرزقها ذرية، وهو قد يجد غيرها وربما أخطأ الأطباء في قولهم: إنه عقيم، وربما يسر الله له زوجة أخرى أو زوجة ثالثة فتحمل منه، فقد يقول الأطباء: إنه عقيم ويخطئون ويغلطون، هذه نصيحتي للأخ السائل. نعم.\nالمقدم: بارك الله فيكم وجزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6775/ما-يفعله-من-اصيب-بالعقم-مع-امراته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_212/21202.mp3","categories":["الطب والتداوي","نصائح وتوجيهات"]},{"id":8913,"question":"كثرت الصوارف عن صلاة الليل سماحة الشيخ، هل من توجيه لو تكرمتم؟","title":"ما النصيحة للتغلُّب على التقصير في صلاة الليل؟","answer":"فالحاصل أنه يجب على المؤمن أن يحذر ما يشغله عن صلاة الفريضة، ويستحب له أن يعتاد التبكير حتى يقوم من الليل، وحتى يتيسر له القيام من الليل، لأداء العبادة التي هي النافلة في التهجد من الليل، ولا ينبغي له السمر مطلقًا إلا في مصالح المسلمين أو في أمورٍ ضرورية مع ضيف ونحوه أو مع أهله، وكل سمر قد يفضي به إلى ترك الفريضة، إلى إضاعة صلاة الفجر، فهو سمر ممنوع لا يجوز، حتى ولو كان في قراءة القرآن ولو في صلاة التهجد، ليس له أن يسمر ويسهر على وجه يضيع عليه صلاة الفجر، بل ينام مبكرًا ويصلي ما تيسر في أول الليل أو في آخره حتى يصلي صلاة الفجر، ويستعين على هذا بخير أهله يوقظونه، أو بالساعة المنبهة، يؤكدها على وقت مناسب قبل أذان الفجر بقليل حتى يقوم، أو في وقت تهجده قبل الأذان بساعة أو بأكثر على حسب حاله حتى يقوم الليل بتهجده، فإذا أوتر في أول الليل ولم يقم إلا عند الفجر فلا بأس به، لا حرج في ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، كدت أسألكم عن القراءة، وإذا بكم تقولون: حتى السهر على قراءة القرآن إذا أدى ذلك إلى التأثير على صلاة الفريضة أو على قيام الليل فإن المرء مدعو لتركه.\nالشيخ: الله المستعان! وفق الله الجميع.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7070/ما-النصيحة-للتغلب-على-التقصير-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_169/16906.mp3","categories":["نصائح وتوجيهات","الوتر وقيام الليل"]},{"id":9210,"question":"قد يقف بعض السادة المستمعين كما وقفت سماحة الشيخ عبدالعزيز عند هذه المناقشة الواعية اليقظة من طالب في الثانوية، لعل هذا الوقت يسمح لنا بكلمة توجهونها لمن مثله وفي هذا السن وفي هذه المرحلة من التعليم؟","title":"نصيحة لطلاب الثانوية العامة ومدرسيهم","answer":"الجواب: لا شك أن الطلبة قدوة لغيرهم وقدوة لزملائهم والأساتذة فوق ذلك، وهذا الكلام يعطينا أن هذا الطالب عنده اهتمام بدينه ونشاط في معرفة الحق زاده الله خيرًا، فوصيتي له ولأمثاله من الشباب أن يتقوا الله، وأن يهتموا بدينهم، وأن لا يشغلوا بالمواد الأخرى عن مواد الدين وعن التفقه في الدين، فقد قال النبي ﷺ: من يرد الله به خيرا يفقهه في الدين.\nفالواجب على الجميع أن يعنوا بدينهم وأن يتفقهوا فيه في الثانوي وفي الدراسة الجامعية، وفي المطالعة بينهم والمذاكرة ومع الأساتذة حتى يفقهوا دينهم وحتى يتبصروا، وحتى يعرفوا الحكم بدليله؛ لأن العلم هو معرفة الحكم بدليله لا بالتقليد ورأي فلان وفلان، فالعالم هو الذي يعرف الأحكام بأدلتها من كتاب الله وسنة رسوله عليه الصلاة والسلام.\nكما أني أوصي الأساتذة والمدرسين في كل مكان أن يتقوا الله وأن يكونوا قدوة صالحة للطلبة في المحافظة على الصلاة في الجماعة والعناية بها والتعظيم من شأنها وحث الطلبة على ذلك، حتى يكون الأستاذ قدوة للطالب في تعظيم أمر الله ونهيه، وفي المحافظة على الصلاة في الجماعة، وفي تعظيم شأنها والحذر من التهاون بها.\nرزق الله الجميع التوفيق والهداية.\nالمقدم: اللهم آمين .. اللهم آمين.","link":"https://binbaz.org.sa/fatwas/7370/نصيحة-لطلاب-الثانوية-العامة-ومدرسيهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18202.mp3","categories":["نصائح وتوجيهات"]},{"id":9220,"question":"أختنا تسأل أيضاً عن قضايا مختلفة فتقول في القضية الأولى: ما حكم المكالمة الهاتفية بين الخاطب والمخطوبة، والقصد كما يقولون: هو التعارف قبل الارتباط بالزواج، وإذا كانوا صائمين هل يتغير الحكم، وهذا يوجد بكثرة في مجتمعنا الإسلامي، والمكالمات بريئة في ظاهرها وحسب كلامهم، وهذا السؤال نابع من الرغبة في التمسك بتعاليم ديننا؟","title":"حكم المكالمة الهاتفية بين الخاطب والمخطوبة","answer":"الجواب: لا نعلم حرجاً في الكلام بين الخاطب والمخطوبة إذا كان كلاماً بريئاً لا يجر إلى شر وإنما يقصد منه التعرف منه عليها ومنها عليه لا بأس في هذا، تسأله عن حاله وعن أعماله وعن ديانته ونحو ذلك وهو يسألها عن مثل ذلك لقصد التوثق من الإقدام على هذا النكاح فلا حرج في هذا، أما إن كان القصد سوى ذلك من التمتع بصوته وصوتها أو المواعيد التي قد تجر إلى الفاحشة فهذا لا يجوز، فالواجب على الخاطب والمخطوبة أن يتحريا الشيء الذي لابد منه في المخاطبة للتعرف فقط، أما ما يخشى منه الفتنة فالواجب اجتنابه.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7380/حكم-المكالمة-الهاتفية-بين-الخاطب-والمخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15302.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":9323,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة عمره ثمان عشرة سنة كما يقول: يشعر بالخوف والخجل ولا يستطيع مجالسة الناس ويرجو من سماحة الشيخ التوجيه، وهل هناك أدعية تؤثر على هذه الحالة التي تنتابه ويعاني منها كثيراً كما يقول؟","title":"توجيه لمن يشعر بالخوف والخجل من مجالسة الناس","answer":"الجواب: نعم، هذا من الشيطان، فينبغي له أن يتعوذ بالله من الشيطان وأن يستشعر أنه رجل مع الرجال، وأنه لا وجه لهذا الخوف ولا وجه لهذا الخجل فهو رجل يجلس مع الرجال ويمشي مع الرجال، ويصلي مع الرجال، ويتكلم مع الرجال، ويعمل مع الرجال، فلا وجه لهذا الخجل ولا وجه لهذا الخوف، ولكن مما يستعان به في ذلك أن يتعوذ بكلمات الله التامات من شر ما خلق. ثلاث مرات صباحاً ومساءً، وأن يقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم. ثلاث مرات صباحاً ومساءً، فإن هذا من أسباب أن الله يكفيه كل شر، ومن ذلك قراءة آية الكرسي بعد كل صلاة، وكذلك قراءة الآيتين من آخر سورة البقرة كل ليلة: آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ [البقرة:285] إلى آخر السورة، وقراءة (قل هو الله أحد) والمعوذتين بعد الصلوات، مرة بعد الظهر والعصر والعشاء، وثلاث مرات بعد المغرب والفجر، كل هذا من أسباب السلامة وإزالة المخاوف. نعم.","link":"https://binbaz.org.sa/fatwas/7478/توجيه-لمن-يشعر-بالخوف-والخجل-من-مجالسة-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_155/15503.mp3","categories":["نصائح وتوجيهات"]},{"id":9366,"question":"أخت لنا من السودان بعثت برسالة مطولة وضمنتها اثني عشر سؤالًا متنوعة من أحد أسئلتها: تقول: لي أربعة أطفال، أكبرهم في السابعة من عمره، كانت أمنيتي قبل أن يرزقني الله بهم إن كانت لي ذرية سأحاول بقدر الإمكان تعليمهم أمور الدين وتهيئة الجو الإسلامي لهم، وفعلًا أخذت أعلمهم ومنهم من يحفظ كثيرًا من القرآن الكريم والأحاديث حتى القصص لا يعلمون غير قصص الأنبياء، ولم أدخل عليهم أي جهاز من الأجهزة الحديثة كالمسجل أو الفيديو أو ما أشبه ذلك، إلا أنهم يعيشون في جو غريب تمامًا، وبدءوا يستنكرون كل ما عدا ما في منزلنا أو كل ما عدا ما يسمعون منا، وبدءوا يعيشون في شيء من الازدواجية وترجو التوجيه جزاكم الله خيرًا؟","title":"نصيحة في تربية الأبناء","answer":"الجواب: قد أحسنت في تعليمهم وتوجيههم، وعليك أن تكملي أنت ووالدهم وإخوتهم الكبار وغير ذلك من أقاربهم، عليكم أن تلاحظوهم حتى لا يضرهم ما حولهم من المجتمع، أنت على خير، وأبوهم على خير في التعليم والتوجيه والإرشاد والتربية الإسلامية، ولكن لابد من اختلاطهم بمن حولهم، فعليكم بالحرص عليهم وتوجيههم إلى الخير، وتحذيرهم مما قد يسمعون من الباطل، أو يشاهدون من الباطل حولهم حتى لا يتأثروا به، والله جل وعلا هو الموفق الهادي، وإنما عليكم أن تفعلوا المستطاع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وأنتم على خير إن شاء الله وسوف ينفع الله بجهودكم. نعم.","link":"https://binbaz.org.sa/fatwas/7530/نصيحة-في-تربية-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18606.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":9418,"question":"من الكويت رسالة بعث بها أحد الإخوة من هناك يقول راشد عبدالله راشد أخونا شاب في الحادية والعشرين من عمره كما يقول ويشكو من ظلم والده له في صفحة كاملة سماحة الشيخ، ويرجو توجيهكم لو تكرمتم؟الشيخ: ويشكو من ظلم..المقدم: والده له، الوالد ظلم ابنه وهذا الابن يشكو من تلكم المظلمة؟","title":"نصيحة لمن يشكو ظلم والده له","answer":"الجواب: أوصيك -أيها السائل- بالصبر على ما قد يقع من الوالد من بعض الظلم، والنظر في أسبابه فلعلك أنت عاق له؛ فلهذا ظلمك وجازاك بالسيئة أكثر، فعليك أن تحاسب نفسك وأن تبر والدك، وأن تسأله عن أسباب الظلم حتى تعرف الأسباب التي تعدى عليك بأسبابها فتدعها إذا كانت غير لازمة لك، حتى تكسب بر والدك ورضا والدك.\nأما إذا كان تعدى عليك بغير سبب فينبغي أن تسعى في إزالة ذلك بواسطة أعمامك وأقاربك ونحو ذلك ممن تظن أنهم يفيدون في هذا الشيء، فلعل ذلك يزول من دون حاجة إلى الرفع إلى ولاة الأمور وإلى المحاكم، هذا خير لك وأولى، أن تسعى بإزالة الظلم الواقع من أبيك بالطرق الحسنة الطرق التي ليس فيها ما يسبب زيادة الشحناء بينك وبين أبيك. وعليك أن تحاسب نفسك فلعلك أنت الظالم وأنت لا تدري، حاسب نفسك وانظر في طاعتك لوالدك وبرك له، وما هي الأسباب التي جعلته يتعدى عليك ويظلمك، ثم استشر الناس الطيبين العارفين بحالك وحال أبيك، لعلهم يرشدونك إلى طرق الحل بينك وبين والدك، ويجمع بينكما على خير، نسأل الله للجميع الهداية.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7583/نصيحة-لمن-يشكو-ظلم-والده-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_190/19004.mp3","categories":["نصائح وتوجيهات"]},{"id":9464,"question":"لها سؤال آخر تقول: إن زوجي قال لي: عليك الحرج إذا اشتريت لأولادي شيئاً من مالك أو مال أهلك، وهو لا يحافظ على الصلاة جيداً، ويأكل المحرمات التي حرم الله كالحبوب والخمر إلى آخرها، فهل هذا الحرج يلزمني، يعني: هل تحريجه هذا يلزمني أفيدوني أفادكم الله؟","title":"حكم منع الزوجة من الإنفاق على أبنائه من مالها","answer":"الجواب: إذا كان يقوم بحقهم ويعطيك حاجتهم فلا تأخذي لهم من أحد شيئًا، أما إذا كان قصر أو تركهم بدون كسوة، ومن دون حاجاتهم فلا بأس، ولكن ما دام يقوم بحاجاتهم فامتثلي أمره، وإن كان في نفسه عنده معاصي، لكن إذا كان لا يصلي لا تبقين معه؛ لأن من لا يصلي كافر، إذا كان لا يصلي فالذي لا يصلي كافر نسأل الله العافية، أما إذا كان يصلي ولكن قد يفعل بعض المحرمات فهذا عاصي وأنت بالخيار، إن صبرت عليه فلا بأس، وإن طلبت الفراق فهذا إلى المحكمة تتصلين بالمحكمة أنت وإياه والمحكمة تنظر في أمركما. نسأل الله للجميع الهداية.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/7621/حكم-منع-الزوجة-من-الانفاق-على-ابناىه-من-مالها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_255/25510.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":9662,"question":"السؤال الثاني في رسالة الأخت إستبرق من العراق تقول فيه: إذا تقدم الشاب لخطبة فتاة في هذه الحالة هل يجب أن يراها، وأيضًا هل يصح أن تكشف الفتاة عن رأسها لتبين جمالها أكثر لخاطبها أفيدونا أفادكم الله؟","title":"حكم رؤية الخاطب للمخطوبة وكشف شعرها للخاطب","answer":"الجواب: لا بأس لكن لا يجب يستحب، يستحب أن يراها وتراه؛ لأن هذا أقرب إلى الوئام، النبي ﷺ أمر من خطب أن ينظر، فإذا كشفت له وجهها ويديها ورأسها فلا بأس على الصحيح، قال بعض أهل العلم: يكفي الوجه والكفان ولكن الصحيح أنه لا بأس بكشف الرأس والقدمين أيضًا حتى يستكمل محاسنها، فلها أن تنظر إليه وله أن ينظر إليها؛ لأن هذا أقرب إلى يؤدم بينهما كما جاء به الحديث؟ نعم، ينبغي أن يكون هذا من دون خلوة بل يكون معهما أبوها أو أخوها أو امرأة أخرى، لا يخلو بها. نعم.","link":"https://binbaz.org.sa/fatwas/7824/حكم-روية-الخاطب-للمخطوبة-وكشف-شعرها-للخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_194/19414.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":9728,"question":"سماحة الشيخ! هذه رسالة وصلت من السائلة (ش. ص) الرياض تقول: تذكر يا سماحة الشيخ بأنها فتاة اقتربت من الثلاثين ومتخرجة من الجامعة منذ فترة طويلة، ووالدها رافض فكرة الزواج طمعًا في الوظيفة التي تقول: لم أستطع الحصول عليها منذ زمن، وتقول: بأنني ألجأ إلى الله  أدعوه بأن يرزقني الزوج الصالح، وإنني أدعو الله بعد كل صلاة وخاصةً في الثلث الأخير من الليل، والذي زادني أسى ولوعة هو أن الله  لم يستجب لدعائي ولم يحقق لي الأمنية التي تتمناها كل فتاة، تقول تذكر: وإنني أفكر دائماً بأنني قد أدعو بشيء لم يكتبه الله  لي من الأساس، فهل هذا التفكير جائز؟ وفي آخر رسالتي أتوجه أن تدعو لي يا سماحة الشيخ مأجورين؟","title":"نصيحة لفتاة تأخر زواجها وحث الآباء على تزويج البنات","answer":"الجواب: يسر الله أمرك، ورزقك الزوج الصالح، ونوصيك بسؤال الله جل وعلا أن يمنحك الزوج الصالح في السجود، وفي آخر التحيات، وفي آخر الليل، اسألي الله جل وعلا ولا تقنطي ولا تيئسي، اسألي الله أن الله يمنحك ... الزوج الصالح، وأن يعينك على حق الزوجية، وأبشري بالخير إن شاء الله أبشري بالخير. والواجب على أبيك أن يساعد في هذا، الواجب على أبيك أن يتقي الله وأن يلتمس لك الزوج الصالح، وأن لا يشغله حب المال عن تزويجك، بل يجب أن يجتهد في تزويجك وسوف يغنيه الله عن وظيفتك وعن راتبك، وأنت لا تقنطي ولا تيئسي، قد يكون عدم الإجابة بأسباب معاصيك، قد يكون لك معاصي فعلتيها، فاتق الله وتوبي إلى الله وحاسبي نفسك، فقد تمنع الإجابة بأسباب المعصية، قد تكوني تساهلت في الفرائض في الصلوات الفريضة، قد تكوني تساهلت ببر والديك، قد تكوني تساهلت في غير ذلك من المعاصي فاتق الله حاسبي نفسك جاهديها، وتوبي إلى الله من تقصيرك في المعاصي، وأبشري بالخير سوف يجيب الله دعوتك، وسوف يرزقك الزوج الصالح إذا صدقت وأخلصت في الدعاء وتجنبت أسباب الحرمان من المعاصي والسيئات. نعم.\nالمقدم: هل من نصيحة للآباء سماحة الشيخ؟\nالشيخ: الواجب على الآباء أن يتقوا الله، نعم ننصح الآباء جميعاً والأجداد وجميع الأولياء ننصحهم أن يتقوا الله وأن يزوجوا مولياتهم، وأن لا يمنعوا ذلك من أجل الدراهم والدنانير، الواجب عليهم أن يزوجوهن حرصاً على عفتهن وعلى سلامتهن، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7883/نصيحة-لفتاة-تاخر-زواجها-وحث-الاباء-على-تزويج-البنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27218.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":9783,"question":"أخيراً لصاحبنا هذا من السودان محمد نصر الدين يقول: خطبت ابنة عمي خطوبة رسمية، والخطوبة عندنا تطول كما تعلمون وسافرت وطلبت منها بعدما سافرت إرسال صورة لها، وفعلاً أرسلتها إلي، هل علي إثم في ذلك وما هي الكفارة؟","title":"طلب الخطيب من مخطوبته صورة لها","answer":"الجواب: نعم لا يجوز طلب إرسال الصورة، وعليك التوبة إلى الله هذا الكفارة، أن تتوب إلى الله توبة صادقة بالندم على ما فعلت والعزم ألا تعود إلى ذلك وتمزيق الصورة، هذا هو الواجب عليك، ليس لها أن ترسل لك صورة وليس لك أن ترسل لها صورة، بل لا بأس أن تنظر إليها إذا خطبتها أو أردت خطبتها لا بأس أن تنظر إليها، الرسول ﷺ أمر بهذا قال: انظر إليها ... فانظر إليها.\nفالمقصود: أن النظر إلى المخطوبة لا بأس من دون خلوة، بل بحضرة أبيها أو أمها أو أخيها من دون خلوة، ينظر إلى وجهها وما ظهر منها كأطرافها أو شعرها لا بأس، ولكن ليس له الخلوة بها ولا الخروج معها في السيارة كما يفعل بعض الناس مع مخطوبته يتمشى معها في البلد أو في الحدائق هذا منكر ووسيلة إلى الفساد، وإنما ينظر إليها بحضرة وليها أو أمها أو أخيها ونحو ذلك، حتى ينظر منها ما يرغبه فيها أو ينفره منها، وليس له أخذ الصورة منها وليس لها أن تطلب صورته، كلاهما ممنوع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7955/طلب-الخطيب-من-مخطوبته-صورة-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_259/25908.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":9998,"question":"تسأل وتقول: بعض الآباء إذا تقدم لبناتهم خاطب لا يزوجونه، بحجة أن الفتاة لا تزال صغيرة، أو لأنها لا تحسن أعمال المنزل، فهل من كلمة إلى مثل هؤلاء الآباء؟","title":"ضرورة مبادرة الآباء بتزويج الأبناء والبنات","answer":"الجواب: نعم، وصيتي للآباء ولجميع الأولياء من إخوة وبني إخوة وأعمام نوصي الجميع بأن يتقوا الله في مولياتهم من البنات والأخوات وبنات الأخ وبنات العم، نوصي الجميع بأن يتقوا الله فيهن وأن يحرصوا على تزويجهن متى جاء الخاطب الكفء، ولو كانت غير متعلمة تتعلم عند زوجها ما دامت أهلاً للزواج وتتحمل الزواج بنت خمسة عشر بنت ستة عشر بنت سبعة عشر فأكثر، تتحمل الزواج تقوى على الزواج، فالواجب أن يجاب الخاطب بمشورتها ورضاها، تستشار وإذا سكتت وهي بكر كفى ذلك، النبي عليه السلام قال: إذنها سكوتها.\nأما إن كانت ثيبا -يعني: قد تزوجت- فلابد من الإذن، اللفظ تقول: نعم لا بأس.\nوالواجب على الولي أن يتقي الله وأن يحرص على تزويج الفتاة فإن جلوسها بدون زوج فيه خطر عليها، فلا يجوز التساهل في هذا الأمر، والواجب على الآباء أيضاً الحرص على تزويج الأبناء إذا قدروا على ذلك، لأن جلوس الولد بغير زواج فيه خطر عظيم، فالواجب على الأب أن يزوجه وأن يجتهد في تزويجه ولو تساهل الولد يلزمه بالزواج يجاهده حتى يتزوج حتى يسلم من الفتنة لأن الزواج من رحمة الله وبفضله من أسباب السلامة، يقول النبي ﷺ في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج -يعني: المئونة- فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء فأمر ﷺ الشباب بالزواج وقال: إنه أغض للبصر وأحصن للفرج، وهذا يعم الفتاة والذكر، يعم الشباب من الذكور والإناث.\nفالواجب على الآباء وغيرهم أن يعتنوا بتزويج بنيهم وإخوتهم إذا تأهلوا للزواج وقدروا على تزويجهم من أموالهم أو من أموال المزوجين، بحيث لا يتساهلون بهذا، إن كان ابنه غنياً جاهده حتى يتزوج، وإن كان فقيراً زوَّجه من ماله إذا كان الولي غنياً، وهكذا البنت إذا خطبها الكفء زوجها وإذا تيسر يخطب لها هو يلتمس، هذا طيب كونه يلتمس هو من الشباب الطيبين يقول: يا فلان! أنا عندي بنت أحب أن أزوجك إياها، أو عندي أخت فإذا وافق الحمد لله، عمر وهو أفضل الخلق بعد النبي ﷺ وبعد الصديق عمر أفضل الخلق بعد نبي الله بعد الأنبياء وبعد الصديق خطب لبنته حفصة لما خرجت من عدة زوجها الذي مات عنها عرضها على عثمان وعرضها على الصديق لفضلهما، فـعثمان اعتذر والصديق سكت لأنه علم أن النبي ﷺ له رغبة فيها، فتزوجها النبي ﷺ، وهي حفصة ، فكون الإنسان يخطب لابنته أو لأخته ليس فيه نقص بل هو مشكور ومأجور إذا التمس لها الزوج الصالح، فإذا جاء الزوج الصالح وخطب فالواجب البدار إلى إجابته ولا يؤخر ذلك، لأن البنت كذا أو لأنه فقير أو وظيفته ما هي بكبيرة لا، الرزق عند الله الرزق عند الله، جاء في الحديث عن النبي ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه إلا تفعلوه تكن فتنة في الأرض وفساد كبير.\nولا سيما في عصرنا هذا عصر الفتن وعصر الانحراف، فالواجب الحذر من التساهل والواجب البدار بتزويج البنين والبنات إذا خطب البنات الأكفاء وتيسر الكفء ولو أن تخطب أنت لها، ولو أن تلتمس لها أنت، وهكذا بنوك وإخوتك وبنو أخيك تحرص على تزويجهم بالكلام والمشورة والنصيحة، وبالمال إذا كانوا فقراء حسب طاقتك، يقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته متفق على صحته.\nحديث عظيم يقول ﷺ: من كان في حاجة أخيه كان الله في حاجته فإذا كنت في حاجة أخيك في الزواج أو أختك أو بنتك فأنت على خير عظيم، أو أخيك أو ابن أخيك، ويقول جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فالتعاون على الزواج من التعاون على البر والتقوى، نسأل الله للجميع التوفيق والهداية.\nالمقدم: اللهم آمين جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8168/ضرورة-مبادرة-الاباء-بتزويج-الابناء-والبنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30006.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":10010,"question":"ترغمني ظروف العمل أحيانًا أن أعمل ضمن مجموعة من العمال الذين يرتكبون الكثير من المعاصي ولا يؤدون شعائر الدين رغم نصحي لهم، فهل علي إثم فيما لو استمريت في العمل، أم أن علي أن أتركه رغم عدم ضمان وجود عمل آخر، أفيدونا جزاكم الله خيرًا؟","title":"توجيه لمن ابتلي بالعمل في بيئة سوء","answer":"الجواب: لا حرج عليك إن شاء الله في البقاء في العمل إذا دعت إليه الحاجة الشديدة أو الضرورة مع النصح وإنكار المنكر، ومتى تيسر لك الترك فاحرص على ذلك؛ لأن قربهم قد يضرك ويقسي قلبك، لكن مع هذا كله عليك أن تنكر المنكر، وأن تنصح لعل الله أن يهديهم أو بعضهم بأسبابك.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8178/توجيه-لمن-ابتلي-بالعمل-في-بيىة-سوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_331/33114.mp3","categories":["نصائح وتوجيهات"]},{"id":10038,"question":"المستمع محمد نصر الدين مصطفى من السودان بعث يقول: خطبت ابنة عمي قبل خمس سنوات، ونظراً لظروف الحياة لم أستطع حتى الآن تكملة أغراض الزواج، فهل في ذلك حرج، علماً بأن المخطوبة موافقة على هذا الانتظار، جزاكم الله خيراً؟","title":"حكم خطبة المرأة وتأخير الزواج بموافقة الطرفين","answer":"الجواب: لا حرج في هذا، ما دامت المخطوبة موافقة فلا حرج في ذلك، نسأل الله أن يسهل أمركما جميعاً. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8206/حكم-خطبة-المراة-وتاخير-الزواج-بموافقة-الطرفين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30109.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10046,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م.ر.ش) من حائل، أخونا رسالته مطولة بعض الشيء يقول فيها:أنا شاب في الثانية والعشرين من عمري متدين والحمد لله، ولكني أجالس أصحاباً لي لا يصلون، نصحتهم مراراً وتكراراً ولكن دون جدوى، ولم يزدهم نصحي إلا إصراراًَ على المعاصي، حاولت هجرهم ولكن لم أستطع على ذلك لأنهم أصحاب لي منذ الصغر ولا أحب سواهم من الشباب، حصلت لي اضطرابات نفسية بسبب ما أسمعه من الناس حيث يقولون: كيف واحد مثلك يماشي مثل هؤلاء، أرى أن تنصحوني سماحة الشيخ كيف أتصرف جزاكم الله خيراً؟","title":"نصيحة لشاب متدين ابتلي بمجالسة رفقاء السوء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالحمد لله الذي هداك ووفقك لما فيه رضاه سبحانه، ورزقك الاستقامة على دينه، فاحمد الله على هذا الخير العظيم واشكر الله، ونوصيك بالحذر من هؤلاء الأصحاب الذين لا يصلون فإن صحبتهم تضرك في دينك ودنياك وسمعتك فاتق الله واحذرهم، وسوف تجد إن شاء الله خيراً منهم، فالتمس الأخيار والزملاء الطيبين فإنهم يعينوك على الخير ويرشدونك إلى أسباب النجاة.\nأما الأشرار فهم شر عليك وضرر عليك في دينك ودنياك فاحذرهم وابتعد عن صحبتهم ما داموا لم ينتفعوا بالنصيحة فاحذرهم واهجرهم وابتعد عنهم واسأل الله لهم الهداية، نسأل الله أن يهديهم وأن يكفيك شرهم.\nفالحذر الحذر منهم ما داموا على حالهم الرديئة والتمس الأصحاب الطيبين وأبشر بالخير والله يعينك، كما قال سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2، 3] فاستقم على أمر الله وحافظ على طاعته وسل ربك التوفيق والإعانة، وابتعد عن الأشرار غاية البعد لعلك تنجو من شرهم وسوف يعوضك الله خيراً منهم. نعم.","link":"https://binbaz.org.sa/fatwas/8215/نصيحة-لشاب-متدين-ابتلي-بمجالسة-رفقاء-السوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_302/30201.mp3","categories":["نصائح وتوجيهات"]},{"id":10210,"question":"تسأل أختنا من جمهورية مصر العربية سؤالًا ثالث فتقول: شاب مؤمن ملتزم، خطب فتاة هي الأخرى ملتزمة، ولكن دون أن يراها، فهل هذه الخطبة صحيحة؟ وهل هذا الشاب يعد مخالفًا للسنة؟","title":"مشروعية رؤية الخاطب لمخطوبته دون خلوة","answer":"الجواب: كونه يراها أفضل، النبي ﷺ أمر بأن يراها إذا أمكن له ذلك، وقال لبعض الصحابة: اذهب فانظر إليها وقال: إذا خطب أحدكم امرأة فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها فليفعل فإن ذلك أقرب إلى أن يؤدم بينهما يعني: إلى أن يلتئم النكاح بينهما والحب بينهما، فالمقصود أنه إذا تيسر له النظر إليها فذلك مستحب وهو أقرب إلى الاجتماع والوئام وحصول المودة، ولهذا قال عليه الصلاة والسلام: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل فإن ذلك أقرب إلى أن يؤدم بينهما أو كما قال عليه الصلاة والسلام، فأنت -يا عبد الله- يشرع لك أن تنظر إلى خطيبتك، فإذا تيسر ذلك برضا أهلها أو بطريقة أخرى، فإن لم يرضوا إذا كان ذلك على وجه ليس فيه خلوة ولا تعاطي ما حرم الله بأن يجلس لها في محل عند الجيران أو غيرهم حتى يراها على وجه يمكنه من الرغبة فيها أو عدم ذلك.\nقال جابر: إنه خطب امرأة فجعل يتخبأ لها بين النخل حتى رأى منها ما دعاه إلى نكاحها أو كما قال . فالمقصود أن رؤيته لها أمر مطلوب، وإذا تيسر باختيارها واختيار أهلها كان أكمل من دون خلوة، يزورهم ويرونه إياها بحضور أمها أو أبيها أو عمها أو نحو ذلك حتى لا تكون خلوة، وإن نظر إليها من جهة أخرى ليس فيها علمهم فلا بأس بذلك إذا كان على وجه ليس فيه محذور شرعًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8380/مشروعية-روية-الخاطب-لمخطوبته-دون-خلوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33503.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10362,"question":"أخيراً يقول: إنه فكر في الزواج فبماذا تنصحونه؟","title":"نصيحة لمن أراد الزواج بالثانية","answer":"الجواب: الزواج مطلوب، قربة عظيمة أنا أنصحه بالمبادرة، إن كان عنده زوجة واحتاج إلى الزوجة الثانية في ...، وإن كان ما عنده زوجة فأولى وأولى أن يبادر.\nالمقدم: زوجته هذه عنده التي يشكو منها، وفكر في الزواج لعل الأمور تصلح؟\nالشيخ: لا بأس إذا أحب أن يتزوج ثانية أو ثالثة أو رابعة فالأمر واسع، لكن عليه أن يتحرى العدل، لقوله سبحانه: فَانكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلاثَ وَرُبَاعَ فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً [النساء:3]، فإذا كان الرجل يغلب على ظنه أنه يعدل ويستطيع الزواج بثانية أو ثالثة أو رابعة فلا مانع، وعلى الزوجة الأولى أن تصبر، إذا عدل وأن تتقي الله وأن ترفق وأن تعاشر بالمعروف، أما إذا ظلم ولم يعدل فلها حينئذ طلب الطلاق أو الرفع إلى المحكمة، والواجب عليه أن يعدل. نعم.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8533/نصيحة-لمن-اراد-الزواج-بالثانية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_279/27911.mp3","categories":["نصائح وتوجيهات","تعدد الزوجات"]},{"id":10526,"question":"يسأل ويقول سماحة الشيخ: ما هي الصفات التي ترونها في الزوجة الصالحة التي يريد أن يخطبها الرجل؟","title":"صفات الزوجة الصالحة","answer":"الجواب: الزوجة الصالحة هي المقيمة لأمر الله، المحافظة على الصلاة في أوقاتها، البعيدة عن التبرج في خروجها إلى الأسواق، المعروفة بحسن السمت والسيرة، هذه هي الزوجة الصالحة. فالتي تريد زواجها اسأل عنها؛ لقوله ﷺ: فاظفر بذات الدين تربت يداك، فإذا ذكرت لك بالمحافظة على الصلاة، والتستر وعدم التبرج، وعدم تعاطي الكذب وأشباه ذلك، فهذه هي المرأة الصالحة، الله ييسر أمرنا وأمرك. نعم.\nالمقدم: اللهم آمين جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8701/صفات-الزوجة-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_283/28315.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10558,"question":"يقول: إنني أحرص على كسب لقمة العيش الحلال؛ حتى أضمن قبول دعائي، وعبادتي لله ، إذ أن الله طيب لا يقبل إلا طيباً، فما حكم تناول الطعام عند أشخاص أعلم أنهم يأكلون الحرام، ولا يخرجون زكاة أموالهم وإن كانوا من أقرب الأقرباء؟","title":"وجوب تحري الكسب الطيب وعدم الأكل من الكسب الخبيث","answer":"الجواب: الواجب على كل مسلم أن يتحرى الكسب الطيب، وأن يحذر الكسب الخبيث، يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِنْ طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّا أَخْرَجْنَا لَكُمْ مِنَ الأَرْضِ وَلا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُمْ بِآخِذِيهِ إِلَّا أَنْ تُغْمِضُوا فِيهِ وَاعْلَمُوا أَنَّ اللَّهَ غَنِيٌّ حَمِيدٌ [البقرة:267] فكما أن المؤمن يتحرى في نفقته الكسب الطيب الذي ينفع المعطى والمهدى إليه وينفع المسكين ولا يتيمم الخبيث -يعني: يقصد الخبيث الرديء- فينفق منه إذا كان نهي عن هذا وهو حلال فكيف بما إذا كان الكسب حراماً فالأمر أشد، فليس للمسلم أن يكسب الحرام بالسرقة أو بالخيانة أو بالربا أو بغير هذا من الأكساب المحرمة.\nوفي الحديث الصحيح يقول ﷺ: إن الله تعالى طيب ولا يقبل إلا طيباً ويقول: ما تصدق عبد بعدل تمرة من كسب طيب، ولا يقبل الله إلا الطيب إلا تقبلها الله بيمينه، أي: يربيها لصاحبها كما يربي أحدكم فلوه أو فصيله حتى تكون مثل الجبل.\nوصح عنه عليه الصلاة والسلام أنه قال: ما أكل أحد طعاماً خيراً من أن يأكل من عمل يده، وإنَّ نبي الله داود -عليه الصلاة والسلام- كان يأكل من عمل يده ولما سئل عليه الصلاة والسلام: أي الكسب أطيب قال: عمل الرجل بيده وكل بيع مبرور فقد أحسنت في تحري الكسب الطيب والحرص عليه، أما من عرف بأن كسبه حرام فينبغي عدم تناول طعامه وعدم إجابة دعوته، إذا عرف أن كسبه خبيث من الربا أو من السرقات والغصب، أو من أنواع أخرى من الكسب الحرام كبيع الخمور وأشباه ذلك مثل هذا ينصح ويوجه إلى الخير ويحذر من مغبة عمله لأن الدين النصيحة، والمسلم أخو المسلم ينصحه ويشير عليه، وإذا لم يقبل النصح ولم يدع هذه المكاسب فهو جدير بأن يهجر حتى يتوب، وجدير بأن لا تجاب دعوته حتى يتوب.\nوهذا من باب التعاون على البر والتقوى ومن باب النصح لله ولعباده، ونسأل الله أن يصلح أحوال المسلمين، وأن يمنحهم الفقه في الدين، وأن يرزقهم الكسب الطيب، وأن يعينهم على التعاون على البر والتقوى، والتناصح إنه خير مسئول. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8732/وجوب-تحري-الكسب-الطيب-وعدم-الاكل-من-الكسب-الخبيث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_322/32202.mp3","categories":["نصائح وتوجيهات"]},{"id":10575,"question":"أختنا نادية من الجزائر تسأل عن الجلوس أمام الخاطب بحضرة الأهل هل يجوز هذا أو لا؟","title":"حكم الجلوس مع الخاطب بحضور محرم وتكرار الجلوس","answer":"الجواب: لا مانع أن تجلس أمام الخاطب حتى ينظر إليها من دون خلوة، يكون معها أبوها أو أخوها أو امرأة أو أمها أو نحو ذلك، ليس له الخلوة بها، والنبي ﷺ قال للخاطب: اذهب فانظر إليها، وقال عليه الصلاة والسلام: إذا خطب أحدكم امرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل.\nالمقصود: أنه إذا تيسر أن ينظر إليها فهو مناسب؛ لأن هذا أقرب إلى أن يؤدم بينهما، أقرب إلى أن تنجح الخطبة وأقرب إلى أن ينجح النكاح، لكن ليس له أن يخلو بها، بل يراها بحضور غيرها كأبيها ونحوه. نعم.\nالمقدم: جزاكم الله خيرا، تكرار الجلوس سماحة الشيخ، هي تسأل عن تكرار الجلوس؟\nالشيخ: إذا دعت الحاجة للتكرار لا بأس، كأن تكون المرة الأولى لم تكف أو الثانية، إذا دعت الحاجة لا حرج حتى تعرفه ويعرفها جيداً.\nالمقدم: أما باستمرار.\nالشيخ: أما باستمرار بدون حاجة ما ينبغي، لأن الأصل التحريم وإنما جاز للمصلحة والحاجة، ولأن التكرار الكثير بدون حاجة قد يفضي إلى فساد، قد يفضي إلى خلوة، وقد يفضي إلى زنا نسأل الله السلامة، نعم، كما قد وقع لكثير من الناس.\nالمقدم: نعم نعم، إذاً: الجلوس للحاجة فقط.\nالشيخ: والمصلحة التي تتعلق بالنكاح من دون خلوة.\nالمقدم: بارك الله فيكم، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8742/حكم-الجلوس-مع-الخاطب-بحضور-محرم-وتكرار-الجلوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_323/32302.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10620,"question":"رسالة وصلت إلى البرنامج من شقرا باعثها مستمع من هناك، رمز إلى اسمه بقوله: أبو مسلم ، أخونا يقول: لدي ابنة تقدم إليها أكثر من شخص، ولكن مشكلتي أن من يتقدم فيه إحدى هذه الأمور، أولاً: إما أنه لا يصلي فقط، أو أنه متساهل لا يرى في المسجد إلا نادراً، أو يشرب الدخان ويصلي، أو لا يشرب الدخان ولا يصلي، ولقد تعبت من لوم الناس لي بعدم تزويج ابنتي، وحجتهم: أن الله يهديهم بعد الزواج، ماذا ترون هل أرفضهم، أم أزوجهم لإبراء الذمة؟ وأي الأشخاص تنصحونني بتزويجه من هذه الأصناف التي ذكرت؟","title":"حكم تزويج من لا يصلي ومن يشرب الدخان","answer":"الجواب: من لا يصلي لا يزوج، لأن ترك الصلاة كفر أكبر، نسأل الله..، في أصح قولي العلماء، وإن كان لا يجحد وجوبها، فالصواب: أن تاركها كافر؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ، وقال عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر.\nفالذي لا يصلي أو لا يعرف في المساجد لا ينبغي أن يزوج، ولا يجوز أن يزوج بمسلمة.\nأما من كان يتعاطى الدخان، ولكنه يصلي فهذا يزوج، معصية لا تمنع من الزواج، وذلك أولى من تركها وتعطيلها، وهكذا لو كان عنده معصية أخرى، مثل يتساهل في بعض الأمور الأخرى التي لا تجعله كافراً، كأن تفوته بعض الجماعة وإلا هو يصلي معروف يصلي مع الناس ويقيم الصلاة لكن قد تفوته بعض الجماعة في بعض الأحيان، أو يعرف بشيء من المعاصي الأخرى مثل قص لحيته أو ما أشبه ذلك، هذا إذا لم يتيسر غيره فلا بأس ولا تعطل، فالمعصية لا تمنع الزواج، إنما يمنع الزواج الكفر، أما المعصية لا تمنع إذا رضيت البنت بذلك، وإذا تيسر السليم من المعاصي فذلك ينبغي طلبه والحرص عليه الله المستعان.\nالمقدم: الله المستعان جزاكم الله خيراً ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/8797/حكم-تزويج-من-لا-يصلي-ومن-يشرب-الدخان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_327/32709.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10683,"question":"من تعز في الجمهورية العربية اليمنية المستمع محمد الأديمي بعث يسأل ويقول: ما هي آداب الخطوبة الإسلامية جزاكم الله خيراً؟","title":"آداب الخطوبة وضوابطها","answer":"الجواب: المستحب أن يرى المرأة إذا تيسر، هذا من الآداب، ومن أسباب التوفيق أن يجتهد في رؤيتها قبل أن يعقد عليها بالطرق الشرعية، إما بالاستئذان من أهلها حتى يراها، أو بأن يجلس في مجلس يمكن أن يراها ولو بغير إذنها، ولو بغير إذن أهلها أيضاً، فيكون في محل يمكنه أن يراها من دون علمها، من طريق جيرانها أو غير ذلك على وجه ليس فيه خلوة، إنما من بعيد إلى بعيد، وإن استأذنهم واجتمع بها ورآها وكلمها وكلمته فلا بأس؛ لأن الرسول ﷺ أمر الخاطب أن ينظر قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل، وجاءه رجل ﷺ فذكر له أنه خطب امرأة، فقال: أنظرت إليها؟ قال: لا. قال: فاذهب فانظر إليها رواه مسلم .\nفالسنة أن ينظر إذا تيسر لكن من دون خلوة، بل بحضرة أبيها أو أخيها أو أمها، أو جماعات آخرين، المقصود لا يخلو بها، أو ينظرها من بعيد من دون علمها أو من دون علم أهلها لا بأس بذلك؛ لأن هذا من أسباب التوفيق إذا رآها واقتنع بها، فإن لم يتيسر ذلك شرع له أن يبعث إليها من ينظرها من النساء الثقات ويعطيه خبرها. نعم.\nالمقدم: جزاكم الله خيراً، إذاً تشترطون في كل الأحوال عدم الخلوة؟\nالشيخ: لابد من عدم الخلوة، لا تجوز الخلوة؛ لأنها حرام ولأنها من أسباب الفتنة أيضاً. نعم.\nالمقدم: وقد لا تتم الخطوبة؟\nالشيخ: نعم، وقد لا تتم الخطوبة.\nالمقدم: جزاكم الله خيراً، هل يمكن أن تمتد الخطوبة بين المخطوبين فترة طويلة إذا اتفقا؛ بسبب ظروف الدراسة مثلاً سنتين أو ثلاث سنوات؟\nالشيخ: لا، ليس لها حد، لا نعلم حداً في هذا، لكن بس ليس له أن يخلو بها ولا أن تركب معه ولا يسافر بها، بل يجب أن يكون كل واحد بعيد عن الآخر؛ حتى لا تقع الفتنة، إنما كلام من طريق الهاتف، أو الزيارة من طريق الجهر يعني: بين أهلها، يزورهم ويتصل بها ويتخبر أخبارها، لا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8859/اداب-الخطوبة-وضوابطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33009.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10688,"question":"من تعز في الجمهورية العربية اليمنية المستمع محمد الأديمي بعث يسأل ويقول: ما هي آداب الخطوبة الإسلامية جزاكم الله خيراً؟","title":"آداب الخطوبة وضوابطها","answer":"الجواب: المستحب أن يرى المرأة إذا تيسر، هذا من الآداب، ومن أسباب التوفيق أن يجتهد في رؤيتها قبل أن يعقد عليها بالطرق الشرعية، إما بالاستئذان من أهلها حتى يراها، أو بأن يجلس في مجلس يمكن أن يراها ولو بغير إذنها، ولو بغير إذن أهلها أيضاً، فيكون في محل يمكنه أن يراها من دون علمها، من طريق جيرانها أو غير ذلك على وجه ليس فيه خلوة، إنما من بعيد إلى بعيد، وإن استأذنهم واجتمع بها ورآها وكلمها وكلمته فلا بأس؛ لأن الرسول ﷺ أمر الخاطب أن ينظر قال: إذا خطب أحدكم المرأة فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها فليفعل، وجاءه رجل ﷺ فذكر له أنه خطب امرأة، فقال: أنظرت إليها؟ قال: لا. قال: فاذهب فانظر إليها رواه مسلم .\nفالسنة أن ينظر إذا تيسر لكن من دون خلوة، بل بحضرة أبيها أو أخيها أو أمها، أو جماعات آخرين، المقصود لا يخلو بها، أو ينظرها من بعيد من دون علمها أو من دون علم أهلها لا بأس بذلك؛ لأن هذا من أسباب التوفيق إذا رآها واقتنع بها، فإن لم يتيسر ذلك شرع له أن يبعث إليها من ينظرها من النساء الثقات ويعطيه خبرها. نعم.\nالمقدم: جزاكم الله خيراً، إذاً تشترطون في كل الأحوال عدم الخلوة؟\nالشيخ: لابد من عدم الخلوة، لا تجوز الخلوة؛ لأنها حرام ولأنها من أسباب الفتنة أيضاً. نعم.\nالمقدم: وقد لا تتم الخطوبة؟\nالشيخ: نعم، وقد لا تتم الخطوبة.\nالمقدم: جزاكم الله خيراً، هل يمكن أن تمتد الخطوبة بين المخطوبين فترة طويلة إذا اتفقا؛ بسبب ظروف الدراسة مثلاً سنتين أو ثلاث سنوات؟\nالشيخ: لا، ليس لها حد، لا نعلم حداً في هذا، لكن بس ليس له أن يخلو بها ولا أن تركب معه ولا يسافر بها، بل يجب أن يكون كل واحد بعيد عن الآخر؛ حتى لا تقع الفتنة، إنما كلام من طريق الهاتف، أو الزيارة من طريق الجهر يعني: بين أهلها، يزورهم ويتصل بها ويتخبر أخبارها، لا بأس.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8859/اداب-الخطوبة-وضوابطها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33009.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10692,"question":"إذا كانت المخطوبة لا تصلي، وقام الخطيب بتعليمها الصلاة أثناء فترة الخطوبة، واشترط عليها أن تصلي، وكانت من أهم الشروط، فما حكم الشرع في ذلك، جزاكم الله خيراً؟","title":"حكم تعليم الخطيب لمخطوبته الصلاة","answer":"الجواب: هذا من أهم الأمور كونه يعلمها الصلاة ويدعوها إليها هذا من أبرك ما يكون وهو واجب، ليس له أن يتزوجها وهي لا تصلي إذا كان مسلماً، ليس له أن يتزوجها حتى تصلي، تلتزم بالصلاة تتوب، وهي كذلك ليس لها أن تزوج رجلاً لا يصلي، لابد أن يكون مصلياً مستقيماً، فالمرأة تحرص على أن يكون زوجها وخطيبها يصلي وهو كذلك يحرص، حتى يكونا جميعاً مصليين مسلمين، وكثير من الناس اليوم يتساهل في هذا، فربما كان الزوج لا يصلي وهي تصلي، وربما كان العكس، هي لا تصلي وهو يصلي، فالواجب الحذر، والواجب أن لا يتزوج امرأة لا تصلي، والواجب عليها هي أن لا تزوج رجلاً لا يصلي، بل يجب الحذر من ذلك؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، فالأمر عظيم، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة، وقال عليه الصلاة والسلام: رأس الأمر الإسلام، وعموده الصلاة.\nفالحاصل أن الصلاة عمود الإسلام، فلابد أن يكون الرجل يصلي وهي تصلي، إذا كانا منتسبين للإسلام لابد من هذا، أما إذا كانا كفار فالمسألة ثانية، يجوز لليهودي أن ينكح اليهودية، والنصراني النصرانية، والكافر ينكح الكافرة، لكن ماداما منتسبين للإسلام فلابد من الصلاة، فإذا تزوج أحدهما الآخر وهو لا يصلي لم يصح النكاح، بل لابد أن يكونا جميعاً مصليين يصليان أو لا يصليان، يكونان مشتركين في الصلاة أو في عدمها، أما إذا كان أحدهما يصلي والآخر لا يصلي، فإنه لا يصح النكاح في أصح قولي العلماء؛ لأن ترك الصلاة كفر أكبر، وإن كان لم يجحد وجوبها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8860/حكم-تعليم-الخطيب-لمخطوبته-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33010.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10841,"question":"ننتقل إلى سؤال آخر لصاحب هذه الرسالة فيقول: ترد بعض أحاديث الرسول ﷺ وقد تخالف هواي وأجد بعض الضيق والحرج في تفسيرها، وفي نفسي، ولكني لا أتكلم، ولا أكتب شيئًا، هل أخرج بذلك من الإسلام، وخاصة أن هذا الأمر يرد علي كثيرًا، وكذلك إني أقرأ بعض الكتب النصرانية، أفيدوني إذ أنني في حرج شديد، ومرض شديد، وأحيطكم علمًا أنني أحافظ على الإسلام، والصلوات الخمس، وأحب الله ورسوله؟","title":"توجيه لمن ابتلي بالشكوك والوساوس","answer":"الجواب:  هذه من نعم الله العظيمة عليك حب الله ورسوله، والمحافظة على ما شرع الله في الإسلام، هذه من نعم الله، ومن أسباب السعادة، والنجاة في الدنيا والآخرة، فنوصيك بالثبات على الحق، والحذر مما قد يشتبه عليك؛ لأنه قد تكون هناك أحاديث موضوعة مكذوبة، وأحاديث ضعيفة يحصل لك بها شك وضيق، وهي غير ثابتة عن النبي ﷺ أما ما قاله الله -جل وعلا- أو ثبت عن رسوله ﷺ ففيه الخير والصلاح، وفيه الهدى والرشاد، وفيه الخير العظيم لمن تأمله وعرف معناه وتقبله بصدر رحب، فإن الله -جل وعلا- لا يأمر إلا بالخير، ولا يدعو إلا إلى الخير، وفي طاعته كل السعادة، وهكذا رسوله -عليه الصلاة والسلام- عندما يدعو إلى الخير، ويأمر بالخير -عليه الصلاة والسلام- فالطاعة والسعادة في اتباع شرع الله، وفي التمسك بدين الله، والوقوف عند حدود الله، والهلاك والشقاء في مخالفة ذلك. وإذا أشكل عليك شيء من ذلك فاسأل أهل العلم من أهل السنة والجماعة من أهل البصيرة عما أشكل عليك، وإذا كنت ذا معرفة باصطلاح أهل العلم في معرفة الحديث الصحيح والضعيف فراجع كلام أهل العلم، واعرف درجة الحديث وصحته وضعفه، أو كونه موضوعًا حتى تكون على بينة، وحتى يزول ما في نفسك من الحرج، فكل ما كان من الشريعة فليس فيه بحمد الله إلا الخير والهدى والصلاح، والله -جل وعلا- بين لعباده ما فيه خيرهم وصلاحهم وسعادتهم في الدنيا والآخرة، وهو أرحم بهم من أمهاتهم  ورسوله ﷺ كذلك أرشدهم إلى أسباب النجاة، ودعاهم إلى أسباب الخير. فأنت كن مطمئنًا أن كل ما شرعه الله، وكل ما ثبت عن الله وعن رسوله ﷺ فهو حق وهدى وصلاح، وما أشكل عليك، وضاق به صدرك فلا تعجل حتى تعرف حقيقة الأمر، وحتى تسأل أهل العلم عما أشكل عليك، فربما فهمت من النص ما ليس هو معنى للنص، وربما ظننت أنه صحيح، وليس بصحيح، بل هو من الأحاديث الموضوعة، أو الضعيفة، فالواجب التثبت في الأمور وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]. ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] ويقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا إِنْ تَتَّقُوا اللَّهَ يَجْعَلْ لَكُمْ فُرْقَانًا [الأنفال:29] يعني: نورًا وبصيرة وهدى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9010/توجيه-لمن-ابتلي-بالشكوك-والوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35503.mp3","categories":["نصائح وتوجيهات"]},{"id":10902,"question":"رسالة وصلت إلى البرنامج من الموصل في الجمهورية العراقية حي العامل، وباعثها مستمع من هناك يقول أخوكم في الإسلام: (س. ف. ع)، رسالته من صفحتين، لخصت ما في هاتين الصفحتين في العبارة التالية يقول: كيف أعالج كثرة النسيان، إذ أني أنسى كثيرًا ما أحفظ من القرآن، أو الأحاديث، أو الأدعية المأثورة؟","title":"نصيحة لمن ابتلي بكثرة النسيان","answer":"الجواب: \n\nعليك أن تعالج ذلك بأمور، منها: سؤال الله، والضراعة إليه، والاجتهاد في ذلك أن يعينك على حفظ كتابه، وأحاديث رسوله ﷺ وعلى حفظ كل ما ينفعك، تسأله كثيرًا فهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُم [غافر:60]، وهو القائل -جل وعلا-: وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186]، فاضرع إليه دائمًا -جل وعلا- واسأله أن يعينك، وأن يمنحك الحفظ لكتابه العظيم، وسنة رسوله الأمين -عليه الصلاة والسلام- ولكل ما ينفعك، في سجودك، وفي آخر التحيات، وفي صلاة الليل، وبين الأذان والإقامة، وعند جلوس الخطيب يوم الجمعة، إلى أن تقضى الصلاة في الأوقات المناسبة، مثل: بين الخطبتين، ومثل السجود في صلاة الجمعة، في آخر التحيات، كل هذه أوقات إجابة، كذلك في آخر النهار من يوم الجمعة بعد العصر، إذا جلست تنتظر المغرب فادع ربك فإنه وقت إجابة.\n\nالثاني: الإكثار من الدراسة والعناية، تدرس ما تحفظ من كتاب الله، تعتني به في أوقات معينة، ترتبها وتدرس ما حفظته؛ لأن الدراسة من أسباب الحفظ، وهكذا الأحاديث تدرسها، وتعتني بها، إذا أبطأت عنها قد تذهب عليك، يعني تجتهد في دراستها، ومراجعتها بين وقت وآخر، وكلما قرب الوقت فهو أولى وأقرب إلى الحفظ حسب طاقتك.\n\nالأمر الثالث: الحذر من المعاصي والسيئات، المعاصي شرها عظيم، ومن أخطر الأشياء على حفظك وعلى فهمك أيضًا، ومن هذا قول الشافعي رحمه الله:\n\n\n\t\n\t\t\n\t\t\tشكوت إلى وكيع سوء حفظي\n\t\t\tفأرشدني إلى ترك المعاصي\n\t\t\n\t\t\n\t\t\tوقال اعلم بأن العلم نور\n\t\t\tونور الله لا يؤتاه عاصي\n\t\t\n\t\n\n\nفهذا علاج عظيم، الحذر من المعاصي، والبعد عنها من الغيبة والنميمة، والتثاقل عن الصلوات، عقوق الوالدين أو أحدهما، قطيعة الرحم، أكل الربا، الكذب، إيذاء المسلمين بكلامك، أو فعالك، إلى غير هذا من المعاصي، احذرها، وابتعد عنها، وتب إلى الله مما سلف من ذلك، ومن هذا قول مالك -رحمه الله- للشافعي -رحمه الله- لما جلس بين يديه، ورأى مالك من الشافعي الحرص والفهم الجيد قال: \"إني أرى أن الله سبحانه قد ألقى عليك من نوره، فاحذر أن تطفئ هذا النور بالمعاصي\".\n\nفالمقصود: أن المعاصي من أسباب ظلمة القلب، وذهاب نور القلب، ومن أسباب سوء الحفظ، وسوء الفهم، ومن أسباب كل شر، قال تعالى وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا عَنْ كَثِيرٍ [الشورى:30].\n\nفالمعاصي شرها عظيم، وعواقبها وخيمة، فالواجب على المؤمن والمؤمنة الحذر منها، والبعد عنها، والتوبة إلى الله من سالفها.\n\nوالرابع: الحذر من خلطة أهل الشر، فإن خلطتهم من أسباب الشر، وهي من جملة المعاصي، فالخلطة لأصحاب الشر وأصحاب القيل والقال والكلام الفارغ تنسيك الخير، فاحذر صحبة الأشرار، وصحبة أهل الفراغ والبطالة الذين لا مهمة لهم إلا القيل والقال والسواليف التي لا فائدة فيها، فإن هذا ينسيك ما أنت حريص عليه من كتاب ربك، وسنة نبيك -عليه الصلاة والسلام- نسأل الله لنا ولك التوفيق.\n\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9079/نصيحة-لمن-ابتلي-بكثرة-النسيان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36006.mp3","categories":["نصائح وتوجيهات"]},{"id":10913,"question":"سؤال آخر -لعله ينبئ عن حياته- سماحة الشيخ يقول: إنه عندما يريد أن ينام، أو يكون في بعض الحالات يتذكر كثيرًا من الأغاني، كيف يتخلص من هذا؟","title":"نصيحة لمن ابتلي بحفظ الأغاني","answer":"الجواب:  هذا أيضًا من أسباب نسيانه، هذا من أسباب نسيانك أيضًا لكتاب ربك، وسنة نبيك، تشاغلك بالأغاني، وتذكرك إياها، وتفكيرك فيها هذا مما ينسيك، وهو من المعاصي التي سمعت أنها من أسباب سوء الحفظ، فاحذرها، وأعرض عنها، ولا تلتفت إليها، وقد عوضك الله عنها خيرًا عظيمًا؛ كتاب ربك، وسنة نبيك -عليه الصلاة والسلام- فالزم كتاب ربك، واحذر الأغاني والمجون. أما الأشعار الطيبة التي فيها الحكمة من أشعار أهل الخير والعلم والصحابة وغيرهم، والأشعار التي تفيدك في دينك وفي لغة القرآن والسنة هذه لا بأس بها إن من الشعر حكمة يقول النبي ﷺ. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9080/نصيحة-لمن-ابتلي-بحفظ-الاغاني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36007.mp3","categories":["نصائح وتوجيهات","الشعر والأغاني"]},{"id":10972,"question":"من القصيم وردتنا هذه الرسالة بها مجموعة من الأسئلة السائل: (أ. ص. ع). القصيم يقول: سماحة الشيخ: ما حكم نظر المخطوب إلى مخطوبته وهي بكامل زينتها، ودون حجاب على رأسها، نرجو من سماحة الشيخ التوجيه؟","title":"حكم نظر الخاطب إلى مخطوبته وهي بكامل زينتها","answer":"الجواب:  لا بأس بذلك، النبي ﷺ أمر بالنظر إلى المخطوبة، فالسنة للخاطب أن ينظر إليها، وإلى وجهها وشعرها ويديها وقدميها، كل هذا لا بأس به، لكن من غير خلوة، ينظر إليها من دون خلوة بها.. بحضور أبيها، أو أمها، أو غيرهما، أو من بعيد من فرجة، أو من جدار، أو من شبه ذلك لا بأس، أما الخلوة بها في محل واحد لا، لا يجوز، لكن إذا اجتمع بها مع أمها، أو مع أختها، أو مع عمتها، أو مع غيرهم فلا حرج في ذلك، بل هو مستحب، وله أن ينظر؛ لأن هذا من أسباب التوفيق ومن أسباب أن يؤدم بينهما.","link":"https://binbaz.org.sa/fatwas/9150/حكم-نظر-الخاطب-الى-مخطوبته-وهي-بكامل-زينتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28616.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":10994,"question":"رسالة جاءت من الموصل في العراق، وباعثها أحد الإخوة من هناك يقول: إنني المسلم (ن. ش. ح) يقول: إني شاب في السابعة والعشرين من عمري أريد أن أتزوج، ولا أطيق ذلك؛ لأننا في بلدنا يطلبون علينا المهر وهو خمسة إلى عشرة آلاف دينار، وأنا لا أملك سوى راتبي الذي لا يكفي إلا لعيشي أنا وعائلتي، فأرشدوني سماحة الشيخ؟ كيف أتصرف جزاكم الله خيرًا؟","title":"نصيحة لشاب لا يستطيع الزواج","answer":"الجواب:  نوصيك بتقوى الله والصبر حتى تستطيع الزواج، ونوصيك أيضًا بالصوم إذا تيسر لك ذلك؛ لأن الله سبحانه يقول في كتابه العظيم: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ [النور:33]، فأنت مأمور بالاستعفاف عما حرم الله حتى يغنيك الله من فضله، وتستطيع الزواج. ونوصيك أيضًا بالصيام يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء، فإذا كنت عاجزًا عن النكاح فاتق الله واصبر، واجتهد في البعد عن أسباب الفتنة، وعن النظر إلى النساء، أو مخالطة النساء حتى يسهل الله لك الزواج، وإن تيسر لك القرض من بعض إخوانك، وأن تتزوج فسوف يوفي الله عنك، اقترض من بعض إخوانك وتزوج وأبشر بالخير، الله يقول سبحانه: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]. ويقول النبي ﷺ: ثلاثة حق على الله عونهم ذكر منهم: المتزوج يريد العفاف ويقول ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه. فأنت إذا أخذت ذلك تريد العفاف فأنت على خير، والله -جل وعلا- يوفي عنك  فإذا تيسر لك من إخوانك الطيبين من يقرضك، من يعينك على الزواج، ولو من جماعة، هذا منه كذا، وهذا منه كذا، حتى تتزوج فهذا مناسب، وينبغي البدار به، حرصًا على العفة والسلامة.  أما إذا لم يتيسر ذلك فاصبر وصابر، واجتهد في جمع ما تيسر من النقود حتى تستطيع الزواج، يسر الله أمرك، وأعانك على ما فيه عفتك وسلامتك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9180/نصيحة-لشاب-لا-يستطيع-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36514.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":11005,"question":"رسالة جاءت من الموصل في العراق، وباعثها أحد الإخوة من هناك يقول: إنني المسلم (ن. ش. ح) يقول: إني شاب في السابعة والعشرين من عمري أريد أن أتزوج، ولا أطيق ذلك؛ لأننا في بلدنا يطلبون علينا المهر وهو خمسة إلى عشرة آلاف دينار، وأنا لا أملك سوى راتبي الذي لا يكفي إلا لعيشي أنا وعائلتي، فأرشدوني سماحة الشيخ؟ كيف أتصرف جزاكم الله خيرًا؟","title":"نصيحة لشاب لا يستطيع الزواج","answer":"الجواب:  نوصيك بتقوى الله والصبر حتى تستطيع الزواج، ونوصيك أيضًا بالصوم إذا تيسر لك ذلك؛ لأن الله سبحانه يقول في كتابه العظيم: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ [النور:33]، فأنت مأمور بالاستعفاف عما حرم الله حتى يغنيك الله من فضله، وتستطيع الزواج. ونوصيك أيضًا بالصيام يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء، فإذا كنت عاجزًا عن النكاح فاتق الله واصبر، واجتهد في البعد عن أسباب الفتنة، وعن النظر إلى النساء، أو مخالطة النساء حتى يسهل الله لك الزواج، وإن تيسر لك القرض من بعض إخوانك، وأن تتزوج فسوف يوفي الله عنك، اقترض من بعض إخوانك وتزوج وأبشر بالخير، الله يقول سبحانه: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]. ويقول النبي ﷺ: ثلاثة حق على الله عونهم ذكر منهم: المتزوج يريد العفاف ويقول ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه. فأنت إذا أخذت ذلك تريد العفاف فأنت على خير، والله -جل وعلا- يوفي عنك  فإذا تيسر لك من إخوانك الطيبين من يقرضك، من يعينك على الزواج، ولو من جماعة، هذا منه كذا، وهذا منه كذا، حتى تتزوج فهذا مناسب، وينبغي البدار به، حرصًا على العفة والسلامة.  أما إذا لم يتيسر ذلك فاصبر وصابر، واجتهد في جمع ما تيسر من النقود حتى تستطيع الزواج، يسر الله أمرك، وأعانك على ما فيه عفتك وسلامتك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9180/نصيحة-لشاب-لا-يستطيع-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36514.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":11084,"question":"هذا السائل الذي رمز لاسمه بـ (أ. أ) يقول: سماحة الشيخ ما كيفية صلاة الاستخارة؟ وما هو الدعاء المطلوب، وهل يكون الدعاء أثناء صلاة الركعتين أم بعد الانتهاء منها؟ جزاكم الله خيرًا.","title":"ما كيفية صلاة الاستخارة ودعائها؟","answer":"الجواب:  صلاة الاستخارة أن يصلي ركعتين، ثم يدعو بعدها، ويستخير بما ورد عن النبي ﷺ بعد السلام يرفع يديه ويسأل، يقول: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم؛ فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه، كأن يتزوج بفلانة، سفري إلى البلد الفلانية، تجارتي في هذا الشيء، يسميه خير لي في ديني ومعاشي وعاقبة أمري فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر ويسميه باسمه شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان، ثم أرضني به هذه السنة في الاستخارة نعم.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9262/ما-كيفية-صلاة-الاستخارة-ودعاىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28910.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":11351,"question":"يقول: والدي يبغضني ولا يريدني أن أتعامل معه، وكثيرًا ما يأمرني بالسكوت وعدم مكالمته، وهو قاسٍ جدًا في معاملته إلى درجة تصل إلى الضرب المتكرر مما سبب لي أذى نفسيًا، وكل هذا لأنه يريدني مثاليًا جدًا بدون أخطاء وهذا مستحيل فكان عقابي الضرب وقام في مرات كثيرة بأذيتي فهل أكون عاقًا إذا ما خرجت من البيت؟ جزاكم الله خيرًا.","title":"موقف الولد من قسوة الوالد معه","answer":"الجواب:  الواجب عليك السمع والطاعة للوالد في المعروف والتأدب بالآداب الشرعية حتى لا يضربك، هو مأمور بأن يؤدبك حتى تستقيم على الأخلاق المرضية، مشروع له أن يؤدبك ويعلمك، لكن إذا كان يضربك بغير حق وظلمًا منه وأنت لم تفعل شيئًا يوجب الضرب فلا مانع أن تخرج وتغادر البيت حتى تسلم من هذا الضرب، أما إذا كان ناصحًا لك يضربك لأنك تتأخر عن الصلاة في الجماعة، يضربك لأنك تؤذي أمك أو تؤذي إخوانك، يضربك لأنك تعمل أعمالًا منكرة أخرى فهو مأجور، والواجب عليك السمع والطاعة والحذر من الأشياء التي أنكرها عليك مما يغضب الله . أما إذا كان ضربه لك ظلمًا منه ليس له أسباب فلا بأس أن تخرج وتهرب منه. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9538/موقف-الولد-من-قسوة-الوالد-معه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37815.mp3","categories":["نصائح وتوجيهات"]},{"id":11375,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات، أختنا تشكو من حالة مرضية نفسية وتقول المرسلة (أ. م) تقول عن نفسها: أنا فتاة ابتليت بالخوف، ولا أستطيع أن أنام بالغرفة وحدي، وكذلك لا أستطيع الذهاب لمكان أو حاجة إلا برفقة أحد معي، وقد سمعت أن الخوف له أثر معين في العقيدة، فهل هذا صحيح؟ وبماذا تنصحونني حتى تزول هذه الحالة عني؟ جزاكم الله خيرًا.","title":"نصيحة لمن ابتلي بالخوف","answer":"الجواب:  ننصحك بأن تستكثري من قراءة آية الكرسي بعد كل صلاة وعند النوم، وقراءة قل هو الله أحد والمعوذتين بعد كل صلاة، وبعد صلاة الفجر والمغرب ثلاث مرات، وأن تكثري من قول: أعوذ بكلمات الله التامات من شر ما خلق، وقول: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ثلاث مرات؛ لأن الرسول ﷺ قال: من قالها ثلاث مرات لم يضره شيء ويقول: من نزل منزلًا فقال: أعوذ بكلمات الله التامات من شر ما خلق لم يضره شيء حتى يرتحل من منزله ذلك، ويقول ﷺ: من قرأ قل هو الله أحد والمعوذتين صباحًا ومساءً ثلاث مرات فإنها تكفيه أو كما قال، عليه الصلاة والسلام. المقصود أن هذه الأسباب نوصيك بها وبذلك يزول الخوف عنك بإذن الله.","link":"https://binbaz.org.sa/fatwas/9561/نصيحة-لمن-ابتلي-بالخوف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_379/37910.mp3","categories":["نصائح وتوجيهات"]},{"id":11430,"question":"المستمع (س. ع) بعث يسأل ويقول: عندما يريد إنسان خطبة فتاة في الشرع يباح أن ينظر إلى وجهها، و تستمر فترة الخطوبة أحيانًا شهرًا، وشهرين، وسنة، هل يجوز لها في هذه الفترة أن تكشف الوجه والأيدي، أم تستر وجهها، وأيديها حتى يتم الدخول بها؟ جزاكم الله خيرًا.","title":"حكم النظر إلى المخطوبة بين فترة وأخرى","answer":"الجواب:  لا حرج على الخاطب في النظر إلى مخطوبته، ولا حرج عليها في النظر إليه، حتى يطمئن كلًا منهما للآخر، فإذا اطمأن كلًا منهما؛ كفى، والحمد لله. المقصود أن الخاطب له النظر؛ ليزداد رغبة، أو يعرف أشياء يريدها حتى يرجع عن الخطبة إذا كان يخشى شيئًا.  المقصود أن النظر لا بأس به من دون خلوة، حتى يطمئن، وتطمئن إلى الرغبة، أو عدمها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9612/حكم-النظر-الى-المخطوبة-بين-فترة-واخرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29406.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11437,"question":"المستمع صالح عبدالرحمن من الرياض، بعث يسأل ويقول: ما هي مواصفات المرأة التي يقدم المسلم على الاقتران بها؟","title":"مواصفات المرأة التي يقدم المسلم على الزواج بها","answer":"الجواب:  يقول النبي ﷺ في الحديث الصحيح: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها؛ فاظفر بذات الدين تربت يداك  فليكن همك الوحيد هو صلاح دينها، فإذا كان مع ذلك جمال ومال وحسب؛ فهذا خير إلى خير، طيب، لكن لا يكون همك الجمال، أو المال، أو الحسب، لا. فليكن أكبر الهم، وأعظم القصد صلاح الدين، واستقامة الأخلاق، تسأل عنها الخبيرين بها، فإذا كانت ذات دين، بعيدة عن التبرج، وعن أسباب الفتنة، محافظة على الصلاة في أوقاتها؛ فاقرب منها، وإذا كانت بخلاف ذلك؛ فاتركها، المهم أن العناية الكبرى تكون بالدين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9619/مواصفات-المراة-التي-يقدم-المسلم-على-الزواج-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_294/29413.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11492,"question":"بعد هذا ننتقل إلى مكة المكرمة عبر رسالة بعث بها المستمع محمد أحمد، أخونا يقول: عندما ألتقي بجماعة من الناس أشعر بخجل وضيق وقلق، فبماذا تنصحونني؟","title":"توجيه لمن يشعر بالخجل عند ملاقاة الناس","answer":"الجواب:  ننصحك بأن تعلم أنهم من جنسك، لماذا تكن صبورًا قويًا، تعلم أنهم من جنسك، وأن بنو آدم من جنسك، لا تخجل، تكلمهم كما ينبغي، تجلس معهم كما ينبغي، لماذا تخجل؟ هم مثلك سواءً بسواء، هذا فلان، وأنت فلان، هذا يأكل ويشرب ويبول ويتغوط، وأنت كذلك. ويش الذي يجعلك تخاف منهم؟ ويش الذي يجعلك تخجل؟ استحضر أنهم من جنسك، وأنهم بنو آدم من جنسك؛ حتى لا تخجل، تكلمهم بصراحة، تحادثهم، تطمئن إليهم من جنس بقية إخوانك، لا تخجل، النقص عام في الناس ولغيرك، فعليك بالاجتهاد والتحري، والخلق الفاضل، وتخاطبهم بالتي هي أحسن، ولا تخجل. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9673/توجيه-لمن-يشعر-بالخجل-عند-ملاقاة-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_383/38306.mp3","categories":["نصائح وتوجيهات"]},{"id":11516,"question":"ما هي نصيحتكم للتجار حينئذ سماحة الشيخ حتى لا يستغلوا حاجة الفقراء؟","title":"توجيه للتجار الذين يستغلون حاجة الفقراء","answer":"الجواب:  نصيحتي للتجار أن يتقوا الله، وأن لا يبيعوا السلع إلا وهي عندهم، قد ملكوها وحازوها، وأن يحرصوا على التخفيف والتيسير، وعدم التكلف في الثمن، يرحموا إخوانهم المحاويج، نوصيهم بالرحمة للمحاويج، وأن تكون الأثمان مناسبة حتى لا يضروا إخوانهم؛ لأنهم ما جاءوا إليهم إلا عند الحاجة، فالوصية للتجار أن تكون الأرباح خفيفة مراعاة لحاجة إخوانهم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9696/توجيه-للتجار-الذين-يستغلون-حاجة-الفقراء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38412.mp3","categories":["نصائح وتوجيهات"]},{"id":11643,"question":"رسالة بتوقيع إحدى الأخوات من الغاط تقول أم عبدالله، أم عبدالله تشتكتي من امرأة ابنها، وتقول: إنها كثيرًا ما تتهجم عليها، وتؤذيها بلسانها، وهذه المشكلة تتكرر كثيرًا سماحة الشيخ، إما أن زوجة الابن تشتكي من والدة زوجها، أو تكون والدة الزوج تشتكي من زوجة ابنها، وهكذا وهكذا؟","title":"نصيحة للزوجة وأم زوجها بالصبر والتحمل والبعد عن المشاكل","answer":"الجواب:  أوصي الجميع بالحلم والصبر والتحمل، أوصي الوالدة بالتحمل من زوجة ابنها، حتى لا يحصل الطلاق، وتنصحها، عليها، توصيها بالكلام الطيب: يا ابنة فلان اتقي الله، دعي هذا الكلام، توصيها بالكلام الطيب، أو تعرض عن كلامها كأنها لا تسمع، حتى لا يحصل تشويش بينها وبين زوجها، وأوصي الزوجة إذا كان الأذى من الأم أن تحمل، وأن تصبر، وأن تخاطبها بالتي هي أحسن، يا خالتي كذا! يا أم فلان كذا! هداك الله، أنا -إن شاء الله- ما أتعود هذا الشيء، تخاطبها بالتي هي أحسن. المقصود: أوصي كل واحدة بالكلام الطيب، والأسلوب الحسن، والحذر من أن تكون سببًا في الفراق والطلاق، الأم تجتهد في الأسباب الطيبة، والكلام الطيب والنصيحة، والزوجة كذلك تجتهد في إرضاء الوالدة، والكلام الطيب معها، وقضاء حاجاتها، وإن أساءت إليها تصبر وتتحمل، كل هذا خير للجميع. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9832/نصيحة-للزوجة-وام-زوجها-بالصبر-والتحمل-والبعد-عن-المشاكل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38919.mp3","categories":["قضايا المرأة","نصائح وتوجيهات"]},{"id":11805,"question":"يقول: لي صديق كان يخطب امرأة من مدة عامين، وكان هو في الخارج يعمل، وعندما قدم من الخارج قال لوالد العروسة: إن شاء سوف نكتب الكتاب، فرفض والد العروسة، وقال: نعمل شبكة -يعني حلي- وبعد عام نكتب الكتاب، فرفض صديقي هذا، وقام بفك الخطوبة،  هل -يا سماحة الشيخ- صديقي عليه إثم؟ وهل هو ظلم تلك المرأة؟ أفيدونا عن هذه القضية جزاكم الله خيرًا.","title":"حكم من فسخ الخطوبة لتأخير والد المخطوبة موعد الزواج","answer":"الجواب:  لا حرج في ذلك أن يدع الخطوبة، مادام والدها لم يبادر بالتزويج؛ فلا حرج على الخاطب أن يدع الخطوبة، وإن أحب أن يصبر؛ فلا بأس، المقصود لا يلزمه الصبر إن عجلوا له الزواج؛ فالحمد لله، وإلا فله أن يدع هذه البنت، ويلتمس غيرها؛ لأن المدة طويلة، حتى ولو كان المدة قصيرة مادام لم يتزوج؛ فهو حر إن شاء استمر في الخطبة وتزوج، وإن شاء ترك، ولو قبل ذلك بيوم أو يومين، لا حرج عليه. المقصود: أن الخطبة لا تلزمه، متى شاء تحويله عن المرأة، وهي كذلك إذا أحبت أن ترغب عنه؛ فلا بأس، مادام العقد لم يتم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9989/حكم-من-فسخ-الخطوبة-لتاخير-والد-المخطوبة-موعد-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42307.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":11840,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (خ) و (ع) و (ح) تقول: أنا شابة، لي أب لا يؤدي ما استوجبه الله عليه من فرائض وواجبات، ويرتكب معاصي عظيمة منها: عقوق الوالدين وعدم إحسان تربية أبنائه، ورعاية المنزل، والقيام عليه، والنظر في شؤونه، وهو دائمًا يهينني أمام القريب والبعيد، والشريف والوضيع، ويتلفظ علي بألفاظ قبيحة للغاية، ومقصر في واجباتي من ملبس ومأكل وغيره، وهو دائمًا يسعى إلى تشويه صورتي بين الناس، فهل أرد عليه إذا تلفظ بكلام قبيح؟ أم أصمت ولا أرد عليه بشيء؟ علمًا بأن معاملته مع الجميع هي نفس المعاملة مع البنت والابن والزوجة؟ جزاكم الله خيرًا.","title":"نصيحة لمن ابتليت بأب عاص وفاحش القول","answer":"الجواب:  يقول الله -جل وعلا- في كتابه الكريم: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] هذا الوالد المشرك الذي يأمر بالشرك يقول الله -جل وعلا-: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما والدان مشركان يأمران بالشرك، فأنت عليك الصبر، والكلام الطيب مع الوالد، والدعاء له بالهداية، ادعي له بالهداية، والكلام الطيب، هداك الله، عافاك الله، وفقك الله؛ لأنه قد أساء الحال معك، ومع غيرك، فعليك الصبر، وألا تقابلي هذا البلاء إلا بالصبر، والكلام الطيب، كما قال الله -جل وعلا- في حق الوالدين المشركين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فهذا إذا كان لا يصلي؛ فهو مشرك، فيعامل بما قال الله: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]. فأنت احلمي، وتوجهي له بالدعاء، واسألي الله في أوقات الإجابة أن الله يمن عليه بالهداية، ويعيذه من الشيطان، ويضع في قلبه الرحمة والحلم على أولاده، وأن يوفقه لبر والديه، إلى غير ذلك. الواجب عليك الصبر، وأن تصحبيه بالمعروف، وأن تسألي الله له الهداية، وأن تلتمسي أسباب الهداية الشرعية لوالدك بالكلام الطيب، بالمشورة على والديه بنصيحته، على أصحابه ورفقائه أن ينصحوه، وبغير هذا من وجوه الخير. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10028/نصيحة-لمن-ابتليت-باب-عاص-وفاحش-القول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_396/39608.mp3","categories":["نصائح وتوجيهات"]},{"id":12089,"question":"لها شكوى وفيها شيء من المرارة سماحة الشيخ، الشكوى من زوجة أبيها، وتصفها بأوصاف أترفع بسماحتكم عن الاستماع إلى مثلها، حبذا لو وجهتموها، ووجهتم مثل تلك المرأة المشتكى منها، جزاكم الله خيرًا.","title":"نصيحة لمن ابتليت بزوجة أب لا تخاف الله","answer":"الجواب:  يجب على كل مؤمن ومؤمنة تقوى الله سبحانه، وأن يحذر من ظلم أخيه، أو أخته في الله، وعلى زوجة الأب، وعلى زوجة الأخ، وعلى كل مسلمة أن تتقي الله، وأن تحذر الظلم لابنة زوجها، أو أخت زوجها، أو غيرهما، فنصيحتي للجميع تقوى الله، وأن يحذر كل واحد، وكل امرأة من الظلم بالقول والفعل. وعلى من ابتليت بشر من زوجة أبيها، أو زوجة أخيها، أو غيرهما أن تسأل الله العافية من شرهما، وأن تضرع إلى الله أن يكفيها شرهما، وتحرص على التعوذات الشرعية صباحًا ومساء، مثل: أعوذ بكلمات الله التامات من شر ما خلق صباحًا ومساء ثلاث مرات، وقراءة قل هو الله أحد، والمعوذتين بعد الصبح ثلاث مرات، وبعد المغرب ثلاث مرات، كل هذا من أسباب العافية من شر كل أحد. كذلك مثلما تقدم: باسم الله الذي لا يضر مع اسمه شيء، في الأرض، ولا في السماء، وهو السميع العليم ثلاث مرات صباحا ومساء، هذا من أسباب العافية والسلامة من كل شر، ينبغي للمؤمن أن يعتادها، والمؤمنة كذلك صباحا ومساء، باسم الله الذي لا يضر مع اسمهه شيء، في الأرض، ولا في السماء، وهو السميع العليم ثلاث مرات صباحا ومساء، من أسباب العافية من كل شر، شر النساء والرجال جميعًا، ومن شر المخلوقات الأخرى. والنصيحة لكل مؤمنة، ولكل مؤمن تقوى الله، والحذر من ظلم الناس، والحذر من إيذاء الناس بقول أو فعل، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10274/نصيحة-لمن-ابتليت-بزوجة-اب-لا-تخاف-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43603.mp3","categories":["نصائح وتوجيهات"]},{"id":12200,"question":"السؤال الأخير الذي نعرضه لأختنا في هذه الحلقة يقول: كيف يقضي المسلم وقته من أول اليوم إلى آخره؟","title":"كيفية استغلال الوقت","answer":"الجواب:  ينبغي للمسلم أن يحفظ وقته ليلًا ونهارًا، وأن يقضيه في طاعة الله من صلاة وتسبيح وتهليل وذكر ودعاء صالح، كما يشرع له أن يقضيه أيضًا في حاجاته، حاجات أهله، كان النبي ﷺ في بيته يقضي حاجات أهله، عليه الصلاة والسلام. وهكذا في كسب الحلال في البيع والشراء والتجارة المباحة، في الأعمال المباحة يكسب بها الرزق حتى ينفق على أهله، وعلى نفسه، ويكون وقته محفوظًا، إما في طلب الرزق الحلال، وإما في العبادات، كالذكر والقراءة، قراءة القرآن، والتسبيح، والتهليل، والصلاة النافلة في أوقات الصلاة، وهكذا ما ينفعه في الآخرة من دعوة إلى الله، وأمر بمعروف ونهي عن منكر، عيادة المريض إلى غير هذا من وجوه الخير، شفاعة حسنة يقضي بها حاجة أخيه، وهكذا طلب الرزق بالبيع والشراء، أو بالعمل المباح، يطلب الرزق، هكذا يكون ليله ونهاره، يكون ليله ونهاره محفوظين فيما ينفعه في الدنيا والآخرة، يحذر أن يصرف بعض وقته فيما حرم الله من المعاصي، ويكون في غاية من الحذر حتى يحفظ لسانه، ويحفظ جوارحه من كل ما حرم الله  وهكذا يحفظ وقته من الفضول والكلام اللاغي الذي لا فائدة فيه، بل تكون أوقاته محفوظة إما في طلب الآخرة والأعمال الصالحة، وإما في طلب الرزق الحلال الذي يستغني به عن الناس، وإما في سكوت، أو نوم يحتاج إليه، أو تحدث مع أهله، يباسط أهله، ويؤانس أهله، زوجته وأولاده وأمه وأبيه، يأنس بهم، ويتحدث معهم في بعض الأوقات، يؤانسهم، كل هذا مما يحبه الله  نعم. المقدم: ندع هذا الموضوع جانبًا إلى أن تحان فرصة أخرى -إن شاء الله تعالى- لنتحدث عنه بطريقة أوسع.","link":"https://binbaz.org.sa/fatwas/10386/كيفية-استغلال-الوقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44407.mp3","categories":["نصائح وتوجيهات"]},{"id":12295,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من اليمن الجنوبي، وباعثة الرسالة إحدى الأخوات من هناك تقول: أم أيمن، أم أيمن عرضنا لها أربعة أسئلة في حلقة مضت، وفي هذه الحلقة لها جمع من الأسئلة، فتقول في أحدها: إنني فتاة ملتزمة بتعاليم ديني، والحمد لله، ولا أريد أن أتزوج إلا من شاب ملتزم مجاهد بنفسه، ومجاهد بماله في سبيل الله، ولكن أهل القرية التي أعيش فيها يصلون، ويصومون فقط، ويتغاضون عن بعض التعاليم الإسلامية، ولا أنكر إيمانهم، فإن الله عليم بذات الصدور، وسؤالي هو: هل أتزوج على أي شاب من هؤلاء إذا تقدم إلي، أم أرفضهم؛ لأنهم قاعدون عن الجهاد بالنفس، علمًا بأن ظروفي الأسرية قاسية، وكذا ظروفي المادية، وأنا لا أريد الخروج إلى العمل؛ لأن جميع مرافق العمل تعاني من ميكروب الاختلاط الفتاك، خذوا بيدي إلى طريق الخير والرشاد، جزاكم الله خيرًا؟","title":"الوصية بتحري الرجل الذي ظاهره الاستقامة لمن أرادت الزواج","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه. نصيحتي لك أيها السائلة، أن تزوجي بمن ظاهره الإسلام والاستقامة، ما دام يصلي وظاهره الإسلام، ولم تعلمي عنه ما يوجب كفره بالله؛ فتزوجي، ونسأل الله أن يصلح أحوال المسلمين، وأن يوفق الدولة لديك للالتزام بالإسلام والدعوة إليه، ونبذ ما خالف الإسلام. وأنت اجتهدي في التماس الرجل الصالح، واسألي عنه أنت وأولياؤك، اسألي عنه أهل الخير، فإذا كان ملتزمًا بالصلاة، مستقيمًا في دينه؛ فلا بأس أن تتزوجي عليه، وإن كان ليس بكامل، وإن كان عنده بعض النقص في بعض المعاصي والسيئات، ما دام مسلمًا لا يدعو القبور، ولا يستغيث بالأموات، وليس شيوعيًا، وإنما هو مسلم لا يرضى بـالشيوعية ولا يعتقدها ولا يوالي أهلها، بل هو مصل صائم مستقيم، فلا بأس عليك ... بتزوجه وإن كان عنده شيء من النقص، كأخذ بعض لحيته، أو تدخين، أو ما أشبه هذا من المعاصي التي تقع من بعض الناس، ولا تجلسي هكذا بدون زوج، ونسأل الله أن يسهل لك الرجل الصالح، وأن يصلح أحوال الجميع، وأن يهدي الدولة، ويوفقها لما فيه رضاه، وأن يهديها حتى تدع ما يخالف الشرع المطهر، وحتى تستقيم على دين الله الذي به سعادتها ونجاتها، وسعادة شعبها ونجاة شعبها، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10495/الوصية-بتحري-الرجل-الذي-ظاهره-الاستقامة-لمن-ارادت-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45301.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":12326,"question":"ننتقل إلى موضوع آخر يسأل عنه أخونا: صالح ناصر إسماعيل البلوشي يقول: أنا شاب في العشرين من عمري، وغير متزوج، لكني دائمًا أفكر في الزواج، وحالتي المادية لا تسمح لي بذلك في الوقت الحاضر، بماذا توصونني وتوجهونني؟ جزاكم الله خيرًا؟","title":"وصية لشاب تاقت نفسه للزواج وهو غير قادر عليه","answer":"الجواب:  نوصيك بما أوصى به النبي ﷺ الشباب، جاء في الحديث الصحيح، يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج الباءة: يعني: الزواج فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج ، ومن لم يستطع؛ فعليه بالصوم؛ فإنه له وجاء خرجه الشيخان في الصحيحين، من حديث عبد الله بن مسعود، رضي الله تعالى عنه. فإذا تيسر لك الاستدانة، أو القرض حتى تتزوج فافعل ذلك، وأبشر بالوفاء يوفي الله عنك، يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه فأنت تأخذها، تستلف، أو تشتري سلعة، وتبيعها سيارة، أو غيرها، تبيعها، ثم تتزوج، والله يوفي عنك، أبشر بالخير -إن شاء الله- فإن لم يتيسر هذا؛ فأكثر من الصوم، أكثر من الصوم حتى يسهل الله لك النكاح. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10516/وصية-لشاب-تاقت-نفسه-للزواج-وهو-غير-قادر-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39804.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":12378,"question":"يقول: أخي الصغير طالب في الجامعة، وقبل عامين تقدم أحد الأشخاص يخطب أختنا، لكننا رفضنا هذا الخاطب؛ لأن فيه بعض الصفات التي لا نرضاها، إلا أن والدنا أصر على تزويجه، وحينئذٍ أخي غضب غضبًا شديدًا من هذا الموضوع، وجافى والدي، فبماذا تنصحونه؟ لأنني أخشى عليه، جزاكم الله خيرًا.","title":"نصيحة لولد جفا والده بسبب الخلاف في مسألة ما","answer":"الجواب:  أنصح أخاك أن يرضي والده، وأن يستسمحه، وأن يدع هذا الجفاء، مع المناصحة إذا أمكنت، المناصحة في عدم تزويج الشخص. المقصود أن عليه الصفاء مع والده، والكلام الطيب مع الوالد، والحذر من الجفاء، وسوء الأسلوب؛ لأن بر الوالد من أهم المهمات، ومن أعظم الواجبات، فإذا خالفه والده في مسألة من المسائل؛ فلا يجوز له أن يهجره، ولا أن يخشن القول له، ولا أن يتكلم معه بما لا ينبغي، بل يجب أن يكون متأدبًا مع والده، فلا يقل له: أفٍ، ولا ينهره، بل عليه أن يتكلم بالكلام الطيب، ويتحرى الأسلوب الحسن، مع النصيحة التي يراها. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10577/نصيحة-لولد-جفا-والده-بسبب-الخلاف-في-مسالة-ما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40015.mp3","categories":["نصائح وتوجيهات"]},{"id":12480,"question":"بعد هذا رسالة وصلت إلى البرنامج من الظهران بتوقيع أحد الإخوة يقول: المرسل (ع. أ. ح) يسأل ويقول: أنا متزوج منذ ما يقارب أربعة عشرة سنة، وعندي من الأولاد ولدين، وأربع بنات، وأحمد الله وأشكره على ذلك، والدي ووالدتي يعيشون معنا من حين لآخر، وهم طاعنون في السن، ولا يقدرون الإقامة معنا، ولا يستطيعون القيام بشؤونهم، ولا يجدون الراحة النفسية من زوجتي عندما يكونون عندنا، وأنا أحس بالإرهاق؛ لأنني تحملت كثيرًا لزوجتي، لعل الحال يتغير، ولكن بدون جدوى، وأنا أعرف مدى التأثير الذي سيلحق الأولاد عندما أقرر الانفصال، أرشدوني، جزاكم الله خيرًا، إذ أنني في حيرة من أمري.","title":"إرشاد من كان له والدان وله زوجة لا تحسن إليهما","answer":"الجواب:  نوصيك بالإحسان إلى والديك، ولو بزوجة ثانية تكون عندهما، إذا استطعت تزوج ثانية تكون عندهما في بيتهما تخدمهما، وأنت على خير، ولا تعجل في الطلاق لأم أولادك، وعليك بنصيحتها وتوجيهها إلى الخير، وإخبارها بأن لوالديك حقًا عليك عظيمًا، وأن لها أجرًا عظيمًا؛ إذا أحسنت إليهما، وساعدتك على برهما، فلا تعجل في الطلاق، وادع لها بالهداية، وانصح لها، وقل لأبيها أو أمها أو أخواتها: أن ينصحوها، وعلى والديك أن يتسامحا معها، وأبشر بالخير العظيم، وعلى والديك التسامح والصبر؛ لأن بقاءها مع أولادها قد يكون فيه الخير العظيم والمصلحة. فالوصية ألا تعجل، وأن تنصحها، وتوصيها بالخير وترفق، وهكذا والداك عليهما أن يتحملا بعض الشيء، وأن يصبرا بعض الشيء، وعلى والديها وأقاربها أن ينصحوها، ويوجهوها إلى الخير، وإذا تيسر لك زوجة ثانية تكون عند والديك تخدمهما، ولعلها تكون أطيب من هذه بالنسبة إليهما؛ فهذا طيب. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10683/ارشاد-من-كان-له-والدان-وله-زوجة-لا-تحسن-اليهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_405/40504.mp3","categories":["نصائح وتوجيهات"]},{"id":12529,"question":"أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ب. م) يقول: إن أمي كثيرة الغيبة، وتريدني أن أجلس معها، وأنا الآن بلغت من العمر أربعين سنة، وأريد أن أعود إلى ربي بالصلاة والصيام والذكر في حجرتي، لكن أمي تريد أن أجلس معها بدون عمل غير الحديث بأن تشتكي من أبنائها، وزوجاتهم معها، فماذا أعمل؟ هل يجوز تركها، والجلوس في داري للذكر والصلاة، أم أجلس عندها، مع العلم أن عندها خادمة تقوم بخدمتها؟ جزاكم الله خيرًا.","title":"كيفية معالجة مشاكل الأم مع أبنائها وزوجاتهم","answer":"الجواب:  عليك أن تسعى في رضاها، وأن تنصحها فيما يتعلق بالغيبة، ولا تقطعها، بل اجلس معها، وانصحها، وبين لها أحكام الغيبة، وإذا كانت تشكو إليك شيئًا من تقصير إخوانك؛ فساعدها في صلاحهم وتوجيههم؛ حتى يستقيموا، وحتى يبروها. وهكذا زوجاتهم، كن معها على الخير، لا مع الشر، كن معها في نصيحة إخوانك، وزوجاتهم، وأن يعطوها حقها، وحذرها مما حرم الله من الغيبة، وأشباهها، تجمع بين المصالح، جزاك الله خيرًا.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10723/كيفية-معالجة-مشاكل-الام-مع-ابناىها-وزوجاتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40802.mp3","categories":["نصائح وتوجيهات"]},{"id":12980,"question":"هذا السائل من الرياض أبو محمد ( أ . أ ) يقول: إذا خطب مني الشخص ابنتي وقيل لي: بأن هذا الخاطب محافظ على الصلوات تمامًا في جميع أوقاتها، فهل أكتفي بهذا في قبوله زوجًا، أم أن هناك أمورًا أخرى أسأل عنها مثل: شرب الدخان، سفره، أصحابه، وغير ذلك؟","title":"الاحتياط في السؤال عن دين الخاطب وأخلاقه وجلسائه","answer":"الجواب:  الاحتياط السؤال الكامل عن سيرته وأعماله وجلسائه حتى تكون على بينة، وإلا فالمحافظة على الصلوات علامة خير، لكن قد يكون هناك عنده أشياء أخرى، فإذا سألت عنه سؤالًا تامًا؛ كان ذلك أكمل، وأفضل احتياطًا للأمانة التي عندك لهذه البنت، أو الأخت، أو نحوها؛ لأنها أمانة. فالواجب عليك أن تحتاط لها، ولا سيما في هذا العصر الذي اختلط فيه الحابل بالنابل، واختلط فيه المسلم بالكفار، والعصاة بالأبرار، فالواجب على الولي أن يحتاط؛ ولهذا قال ﷺ: إذا خطب إليكم من ترضون دينه وخلقه؛ فزوجوه إلا تفعلوه؛ تكن فتنة في الأرض، وفساد كبير كيف يمكنك أن ترضى دينه وخلقه وأنت ما سألت عنه الأخيار الطيبين؟! مجرد حضوره للصلاة ما يكفي، وإن كان ذلك علامة خير، وعلامة هدى، ولكن الاحتياط أن تسأل عن سيرته أيضًا ........ المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11197/الاحتياط-في-السوال-عن-دين-الخاطب-واخلاقه-وجلساىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50310.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":12982,"question":"تسأل أيضًا وتقول: كيف تختار المرأة المسلمة المحجبة المؤمنة بالله شريك الحياة؟ وما هي صفاته؟ بينوها لنا مأجورين؟ جزاكم الله خيرًا.","title":"صفات الزوج الصالح","answer":"الجواب:  تلتمس الرجل الطيب المعروف بالخير المحافظ على الصلوات، صاحب العقيدة الطيبة، تسأل عنه من يعرفه من الثقات الذين تعرفهم إذا خطبها، ولو تخطبه هي لا بأس، إذا عرفته بالخير والاستقامة، وأوصت عليه وليها، أو غير وليها أنها توافق على خطبته لها؛ فلا بأس، فقد أهدت امرأة نفسها للنبي ﷺ وأقرها على ذلك -عليه الصلاة والسلام- ولما لم يرغب فيها زوجها غيره -عليه الصلاة والسلام- وعمر  عرض ابنته حفصة على الصديق ، وعلى عثمان بعدما تأيمت من زوجها، ثم تزوجها النبي ﷺ. فالمقصود: أن المرأة لا مانع أن تختار لنفسها الرجل الطيب المعروف بالاستقامة في دينه، ولكن لا تبت في ذلك إلا بطريق وليها، وليها هو الذي يزوجها، فإذا اتفقت مع وليها على رجل طيب؛ هذا هو المطلوب، وليس لوليها أن يجبرها على شخص ليس بطيب، أو على شخص لا ترضاه، وليس لها هي أن تختار شخصًا يضر أولياءها، ويسبب المشاكل بينها وبين أوليائها، عليها أن تسلك المسالك الحسنة، وأن تختار الطيب الذي ليس في اختياره مشاكل ولا مضرة على أوليائها، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11199/صفات-الزوج-الصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_470/47011.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13186,"question":"نختم هذا اللقاء بسؤال لنفس السائل الأخ صالح يقول: أذكر الله بعض الأحيان وأنا غير حاضر القلب، هل أثاب على هذا الذكر، أم لا؟","title":"ثواب ذكر الله مع عدم حضور القلب","answer":"الجواب:  نعم، يرجى لك الثواب، لكن من أقبل على الثواب .. عن إحضار قلب .. وعن تضرع، وعن خشية، وعن صدق؛ يكون ثوابه أكثر، نعم. المقدم: شكر الله لكم -يا سماحة الشيخ- وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين. الشيخ: وفق الله الجميع. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/11441/ثواب-ذكر-الله-مع-عدم-حضور-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51122.mp3","categories":["الأدعية والأذكار","الرقائق","نصائح وتوجيهات"]},{"id":13211,"question":"السائل من جمهورية مصر العربية، والذي رمز لاسمه بـ (س. م) يعمل بالرياض يقول في هذا  ما حكم الشرع في نظركم في مراسلة الخطيب لخطيبته، والعكس مع ملاحظة ذلك بأن عدم المراسلة قد يسبب للخطيبة تعبًا نفسيًا، وأضرارًا صحية ودراسية، وجهونا في ضوء هذا السؤال؟","title":"حكم مراسلة الخطيب خطيبته والعكس","answer":"الجواب:  لا أعلم بأسًا في ذلك أن يخاطبها، وتخاطبه بالتلفون، أو بالمكاتبة لتأكيد الخطبة أو للسؤال عن بعض المهمات التي ليس فيها وسيلة إلى الاجتماع المحرم قبل الزواج، إنما سؤال عن كذا أو كذا، تسأله وهو يسألها عن أمور تتعلق بالزواج، وبمصلحة الزواج، ولا يخشى منها فتنة، فلا حرج في ذلك من طريق الكتابة، أو من طريق المهاتفة التلفون. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11485/حكم-مراسلة-الخطيب-خطيبته-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51214.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13310,"question":"من بلاد زهران الباحة السائلة التي رمزت لاسمها بـ (ع. م) تقول سماحة الشيخ -حفظكم الله- تذكر بأنها امرأة متزوجة، وعندها أطفال، تعمل مدرسة في المرحلة الابتدائية، وتذكر وتقول: بأن زوجي يريد أن أجلس في البيت مع الأطفال، وأترك التعليم، مع العلم بأنني أخرج من المدرسة في وقت غير متأخر، أحيانًا الساعة الحادية عشرة والنصف، أو الثانية عشرة بحجة الخادمة التي توجد لدينا، حيث يوجد لدينا خادمة مسلمة محافظة وملتزمة، لا يراها ولا يصادفها، وإنني أحب زوجي وأطفالي، وأحب عملي، ولا أريد أن أخسره، فوجهوني في ضوء سؤالي ذلك مأجورين؟","title":"بقاء المرأة مع زوجها وأطفالها أولى من الخروج للعمل","answer":"الجواب: لا ريب أن بقاءك عند أولادك وأطفالك هو المصلحة والخير، وأن وجود الخادمة في البيت بدلًا منك لا يكفي، بل فيه خطر بينها وبين زوجك. فالحاصل: أن الذي أرى وجودك عند الأطفال، وترك التدريس، تبقين عند أطفالك، وزوجك، وتقومين بالواجب، وتحفظين سمعتك، وسمعة زوجك. فالمقصود: أن بقاءك في البيت أولى وأصلح، والتدريس سوف يغني الله عنك، ويسهل لهم من يقوم مقامك، دينك وأمانتك عليك أهم وألزم، فالجلوس في البيت فيه مصالح كثيرة لتربية الأطفال، هذا لا شك أنه خير لك، وأصلح لك ولزوجك، ونسأل الله أن يصلح حال الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11596/بقاء-المراة-مع-زوجها-واطفالها-اولى-من-الخروج-للعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52108.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":13316,"question":"هذه سائلة للبرنامج تقول: مشكلتي يا سماحة الشيخ بأنني أعاني من وسواس، ولا أعرف صدق هذا الوسواس الذي يزداد كل يوم، حيث إنني أشعر بعدم الصدق والإخلاص لله  ومرة أشعر بصميم الإيمان الذي يدفعني إلى العمل الصالح الذي يرضاه الله  فأنا دائمًا في حيرة من أمري، لا أدري ماذا أفعل، لقد سألت البعض من الإخوة عن هذا فقالوا لي: اطمئني فإنك مأجورة، وتذكر في رسالتها وتقول: هذا الوسواس كثيرًا ما يراودني حيث إنني عندما أسمع الرد من بعض المشايخ؛ أشعر بالارتياح والاطمئنان، ولكن بعد فترة أعود لما كنت إليه في السابق للشك، والحيرة والقلق، وعدم الاستقرار للروح والبدن، أفتوني في مشكلتي، جزاكم الله خيرًا سماحة الشيخ.","title":"كيفية التخلص من كثرة الوساوس في الإيمان","answer":"الجواب: هذا كله من الشيطان، والواجب عليك تقوى الله -سبحانه-والضراعة إليه أن يعيذك من الشيطان، ونزغاته وهمساته، والحذر من هذه الوساوس، عليك بالصدق والإقبال على الله  في جميع أعمالك، وأبشري بالخير العظيم، ودعي عنك الوساوس، اجزمي على أنك فعلت المطلوب، ولا تلتفتي للظنون الكاذبة التي يأتي بها الشيطان، لا في الصلاة، ولا في الوضوء، ولا في غير ذلك، عليك بالجزم إذا صليت اجزمي أنك صليت والحمد لله، إذا توضأت كذلك، ودعي الوساوس، حاربيها بالتعوذ بالله من الشيطان الرجيم، وبتركها، والحذر منها، والبناء على ما وقع في نفسك أنك فعلتيه من وضوء، أو صلاة أو غير ذلك؛ لأن الشيطان عدو مبين، حريص على إفساد أعمال بني آدم، فالواجب محاربته كما قال الله -جل وعلا-: وَإِمَّا يَنزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ [الأعراف:200] وجاء رجل إلى النبي ﷺ قال: يا رسول الله! إن الشيطان قد لبس علي صلاتي، فقال له ﷺ: استعذ بالله ثلاثًا، انفث عن يسارك ثلاث مرات، واستعذ بالله ثلاثًا قال عثمان بن أبي العاص وهو الذي سأل: فعلت ذلك؛ فأذهب الله عني ما أجد. هكذا ينبغي إذا أحس الإنسان ينفث عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان ولو في الصلاة، إذا جاءته الوسوسة ينفث عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان الرجيم، ثلاث مرات، وهكذا في جميع الأحوال، كلما أحس بالوساوس يستعيذ بالله من الشيطان، ويزول -إن شاء الله-  يزول ذلك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11602/كيفية-التخلص-من-كثرة-الوساوس-في-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52102.mp3","categories":["نصائح وتوجيهات"," الوسواس بأنواعه"]},{"id":13333,"question":"هذا السائل حسين صالح من اليمن يقول: البعض من الشباب هذه الأيام وأنا من ضمنهم يقول: يشكو من كثرة وقت الفراغ، فكيف يمكن للمسلم أن يشغل وقته؟ جزاكم الله خيرًا.","title":"كيف يمكن للمسلم أن يشغل وقته؟","answer":"الجواب: الوقت ثمين، أعز من الذهب، فينبغي أن يشغل بما ينفع، قراءة القرآن، بالتسبيح والتهليل والذكر، بحضور مجالس العلم، وحلقات العلم، عيادة المريض، بالإكثار من قراءة القرآن، بالجلوس في بيته يذكر الله، ويقرأ القرآن، ويستغفر، ويدعو، يعني: يستغل الوقت حتى لا يضيع عليه، ومن أحسن ما يستغله فيه قراءة القرآن، والإكثار من ذكر الله، والصلاة تطوعًا، فإذا تيسر له أن يعود مريضًا من إخوانه، أو يزور صديقًا له، يعينه على الخير، أو يذهب إلى حلقة علم إن وجدت، يحضرها، أو ما أشبه ذلك. يعني: هذا الوقت يحفظه فيما ينفعه في دينه، أو في دنياه، أو في مزرعته؛ لسقيها، والقيام بحاجاتها، أو في السوق لطلب الرزق، سوق البيع والشراء لطلب الرزق، ويتحرى الحلال، ويحذر شهادة الزور، ويحذر الكذب، ويحذر الغش، فلا بأس كله طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11619/كيف-يمكن-للمسلم-ان-يشغل-وقته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52215.mp3","categories":["نصائح وتوجيهات"]},{"id":13346,"question":"من السودان الخرطوم: (ع. ع. ع) يقول في هذا  إذا كان الشخص مريضًا نفسيًا بمرض الوسواس الذي يسيطر عليه في كل لحظة من عمره، ويصدر نتيجة لهذا المرض تصرفات خاطئة، فهل هذه الأخطاء يحاسب عليها؟ وهل هذه التصرفات تعتبر ابتلاء من الله ؟ وهل يؤجر على هذا الابتلاء؟ أم هي أفعال من الشيطان يحاسب عليها، ولا يؤجر عليه؟ وجهونا في ذلك.","title":"هل يحاسب المصاب بالوساوس على وساوسه؟","answer":"الجواب: الوساوس من الشيطان مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ [الناس:4] والواجب على من ابتلي بها أن يحذرها، وأن يضرع إلى الله، أن يعيذه من الشيطان، فيستعيذ بالله من الشيطان، يسأل ربه العافية، ويحذر من الاسترسال مع الوساوس؛ لأن الله أمره بالاستعاذة، قال تعالى: وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ [فصلت:36] وقال -عليه الصلاة والسلام- في الذي سأله عن الوساوس؟ قال له: انفث عن يسارك ثلاث مرات، وتعوذ بالله من الشيطان، ومن شره ثلاث مرات، ثم انقلب على الجنب الآخر. فالمؤمن يتعوذ بالله من الشيطان، ولا يلين للوساوس؛ لأنها من الشيطان، ولا يؤجر على ذلك، بل هو مؤاخذ على ذلك، يخشى عليه من العقوبة والإثم إذا استرسل معه، وتساهل، فالواجب الحذر. أما إذا لم يستطع، وغلب؛ فلا إثم عليه لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] إذا كان مغلوبًا على ذلك، ليس له فيه اختيار؛ فهذا كالمعتوه والمجنون. لكن الواجب عليه أن يحاسب نفسه، وأن يجاهدها لله، وأن يتعوذ بالله من الشيطان؛ حتى يحارب هذه الوساوس، ولما شكى بعض الصحابة إلى النبي ﷺ ذلك، قال له: انفث عن يسارك ثلاث مرات، وتعوذ بالله من الشيطان ثلاث مرات فقال: ففعلت، فأذهب الله عني ما أجد. وقال له بعض الصحابة: يا رسول الله! إن أحدنا ليجد في نفسه ما لا أن يخر من السماء أحب إليه من أن يتكلم به؟ قال: تلك الوسوسة، ثم أمرهم إذا وجدوا ذلك أن يتعوذوا بالله من الشيطان، ويقول: آمنت بالله ورسله، قال لهم: إذا وجد أحد ذلك فليقل: آمنت بالله ورسله، وليتعوذ بالله من الشيطان يعني يوسوس له الشيطان: من خلق ربك، من كذا، ما هناك جنة، ما هناك نار، وأشباه ذلك. فإذا وجد هذه الوساوس؛ فالمشروع له أن يقول: آمنت بالله ورسله، أعوذ بالله من الشيطان الرجيم هكذا يجاهد هذا العدو، آمنت بالله ورسله، آمنت بالله ورسله، أعوذ بالله من الشيطان الرجيم، وينفث عن يساره ثلاث مرات، ويتعوذ بالله من الشيطان، هكذا يحاسب نفسه، ويجاهدها طاعة للرسول ﷺ وعملًا بتوجيهه، فإذا فعل هذا؛ سلم، وأنجاه الله من شر هذه الوساوس، وسلم من شرها، ومن إثمها. أما إذا تساهل في هذه الوساوس، وانقاد لها؛ فإنه يأثم، نسأل الله العافية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11632/هل-يحاسب-المصاب-بالوساوس-على-وساوسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54207.mp3","categories":["الأدعية والأذكار","الرقائق","نصائح وتوجيهات"]},{"id":13353,"question":"السائل يقول: هناك موضوع يقلقني سماحة الشيخ، أرجو أن توجهوني إليه، وهو: أنني أخاف جدًا من عقاب الله  وأشعر أنني أرتكب سيئات كثيرة في حياتي، وأحاول التقرب إلى الله بالصلاة والتسبيح، ولكن مع ذلك أشعر بأنني مقصر جدًا في حقوق الله، وخصوصًا عندما أقرأ عن منازل المؤمنين في الجنة، وجهوني سماحة الشيخ؟","title":"توجيه لمن يشعر بارتكابه المعاصي مع طاعته لله","answer":"الجواب: هذه وساوس يا أخي، اتق الله، هذه وساوس، اطرحها من بالك، وتعوذ بالله من الشيطان، إذا كنت لا تعلم شيئًا من الذنوب؛ فاطرح هذه الوساوس، واعلم أنها من الشيطان، وقل: أعوذ بالله من الشيطان الرجيم، ولا بأس أن تتفل عن يسارك، ولو في الصلاة ثلاث مرات، وقل: أعوذ بالله من الشيطان الرجيم. أما إن كنت تعلم شيئًا من الذنوب؛ فبادر بالتوبة، تعلم أنك عاق لوالديك، أنك تركت شيئًا من الصلوات، تعلم أنك ضربت أحدًا، أخذت مال أحد، فبادر بالتوبة، الذنب الذي تعرفه؛ بادر بالتوبة، والتوبة: الندم على الماضي، والعزم الصادق ألا تعود للذنب مع تركه، والإقلاع منه؛ خوفًا من الله، وتعظيمًا لله، وإن كان الذنب يتعلق بالمخلوقين؛ ترد عليهم حقوقهم، تعطيهم حقوقهم، أو تستحلهم من حقهم، من تمام التوبة أن تعطيه حقه، المال الذي أخذته منه، أو ضربته، أو قتلت ولده، أو ما أشبه ذلك، تعطيه حقه بالقصاص، برد المال، هذا من تمام التوبة. أما وساوس ما لها أساس، ما تعرف ذنوبًا فعلتها؛ فهذا من الشيطان، لا تبال بها، واطرحها، وسل ربك العافية منها، وتعوذ بالله من الشيطان، وأبشر بالخير. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11639/توجيه-لمن-يشعر-بارتكابه-المعاصي-مع-طاعته-لله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52310.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":13359,"question":"فضيلة الشيخ! هذا السائل عبدالعزيز من الرياض يقول: كثير من الناس هداهم الله يذهبون في رمضان للمساجد البعيدة عن بيوتهم لأداء صلاة التراويح؛ طلبًا لحسن الصوت لبعض الأئمة، ولكن المشكلة يا سماحة الشيخ بأنهم يذهبون متأخرين جدًا، فنراهم قد تفوتهم صلاة العشاء، فيقضون جماعات في آخر المسجد، هل من كلمة لهؤلاء يا سماحة الشيخ؟","title":"توجيه لمن يقصد مسجدًا بعيدًا لأجل التراويح وتفوته العشاء","answer":"الجواب: نعم، نصيحتي للجميع أن يتقوا الله، وأن يحرصوا على أداء الفريضة، وإذا ذهب بعد الفريضة، أو مبكرًا حتى يدرك الفريضة إلى شخص آخر، يرى أن صوته أحسن، وأنه يخشع لقراءته، ويستفيد؛ فلا بأس، ولو كان بعيدًا عن بيته، لكن يحرص على أداء الفريضة، لا تفوته الفريضة، إما يصليها في المساجد القريبة، وإلا أن يبكر حتى يصلي مع ذاك الإمام الفريضة، ولا يعرض نفسه أن تفوته الفريضة؛ لأن الفريضة فرض عليه، والتراويح مستحبة، فلا يضيع الفرض من أجل المستحب. يجب أن يعتني بالفريضة حتى يؤديها مع إخوانه المسلمين، وإذا أحب أن يصلي مع شخص آخر؛ فليبكر، يذهب قبل العشاء حتى يدرك الفريضة معه، أو بعد العشاء إذا صلى الفريضة، ولا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11644/توجيه-لمن-يقصد-مسجدا-بعيدا-لاجل-التراويح-وتفوته-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_524/52402.mp3","categories":["الآداب والأخلاق","نصائح وتوجيهات","وقت الصلاة"]},{"id":13373,"question":"هذا سائل للبرنامج يقول في هذا السؤال أحمد مصري، ويعمل بالرياض، يقول: أبي تزوج بامرأة غير أمي، وذلك منذ عشر سنوات، وهو الآن لا يراها، ولا ينفق عليها، ولا علينا، فما الواجب علينا تجاهه، وبماذا تنصحوننا مأجورين؟","title":"توجيه لمن لا ينفق على زوجته وأولاده","answer":"الجواب: إذا كانت راضية وسامحة؛ لا شيء عليه، إذا سمحت أمك أنها تبقى في عصمته، ولا ينفق، ولا يراها؛ فلا بأس، الرسول ﷺ أراد أن يطلق سودة، فقالت: \"يا رسول الله! أبقني في حبالك وحقي ساقط، ويومي لعائشة\" فوافق النبي ﷺ وبقيت في حباله، ولا يأتيها، ولا ينظر إليها، ولا ينفق عليها، فإذا سمحت أمك، ورضيت عنه؛ فلا حرج. أما إذا قالت: لا، أنا ما أرضى، إما أنفق، وإلا طلق؛ يلزمه الطلاق، يلزمه أن يطلق طلقة واحدة، أما إذا كانت لا، راضية تقول: لا، أنا صابرة، وأبغى عند عيالي، وأنت مسامح، ولا تجيني، ولا تنفق، أنا أصنع نفسي؛ فلا حرج، والحمد لله، لكن إذا كانت لا، تقول: لا، إما اعدل، وإلا طلق؛ يلزمه إما العدل، وإلا الطلاق، هذا الواجب.  المقدم: جزاكم الله خيرًا. المقدم: يقول في سؤال له سماحة الشيخ: بالإضافة إلى هجره لأمنا فهو يعاملنا بقسوة، ولا يعطينا شيئًا، علمًا بأنه يملك الكثير من الأموال مما أحدث في قلوبنا شيء من الكراهية له، فماذا توجهونه مأجورين؟ الشيخ: الواجب عليه أن ينفق على أولاده إذا كانوا فقراء، الواجب عليه أن ينفق عليهم، وأن يعاملهم باللطف، والإحسان، والخلق الحسن، والواجب على الأولاد أيضًا أن يعرفوا قدره، وأن يبروه، وأن يخاطبوه بالتي هي أحسن، وإذا دعت الحاجة إلى أن يرفعوا الأمر إلى المحكمة؛ فلا بأس، يقولون: والدنا احنا فقراء، ولم ينفق علينا، يرفعوا الأمر إلى المحكمة، وإذا توسط لهم بعض الطيبين من الجيران والأقارب لدى الوالد، حتى ينفق؛ فهذا أحسن من المحكمة، أحسن من الخصومة. وصيتي للأولاد: الرفق، والبر بالوالد، والكلام الطيب مع الوالد، ووصيتي للوالد أن يتقي الله، وأن ينفق على أولاده المحتاجين، وأن لا يحوجهم إلى الشكوى إلى المحكمة، أو إلى توسط الناس، يجب أن يعدل من نفسه، وأن يعرف ما أوجب الله عليه، وأن ينفق عليهم ما داموا فقراء، وأن يحسن إليهم، وألا يحوجهم إلى شكوى، ولا إلى غيرها، وعلى الأولاد جميعًا أن يجتهدوا في بر والدهم، والكلام الطيب معه، ومخاطبته بالتي هي أحسن، وإذا دعت الحاجة إلى أن يطلبوا من أعمامهم، أو من بعض جيرانهم، أو أصدقاء والدهم أن يتوسطوا لدى والدهم في الإحسان إليهم، وفي أداء حقهم بدلًا من الشكوى؛ فهذا أطيب، وأحسن. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11664/توجيه-لمن-لا-ينفق-على-زوجته-واولاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51506.mp3","categories":["النفقات","نصائح وتوجيهات"]},{"id":13379,"question":"تقول: شخص ترك ثلاثة من الأولاد، ولد وبنتين، وترك الإرث للولد، وتوفي هذا الولد، وواحدة من البنات، وواحدة ما تزال على قيد الحياة، فهل يحق لها أن تطالب ابن أخيها المتوفى؟","title":"هل للأنثى أن تطالب بحقها من الميراث؟","answer":"الجواب: نعم، هذا جور جعله المال للذكر، وإلا للأنثيين، هذا جور، ولا مانع من مطالبة البنتين لأخيهم بحقهما، أو لابنه بعد موته بحقهما، ورثة الميتة، والحية تطالب بحقها، إلا أن يكون له مسوغ شرعي، يعني: يعتقد أنهما كافرتان، ليس لهما إرث منه، فهذا يرجع إلى للمحكمة، تراجع المحكمة في ذلك. أما إذا كان الولد مسلمًا، والبنتان مسلمتين، والميت مسلم، فالواجب أن تكون التركة بين الجميع بين الذكر والأنثى.. لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] تقسم بينهما، للرجل نصفها، وللبنتين نصفها، الثاني بينهما، فإذا كان في ذلك إشكال، أو نزاع؛ فهذا يرجع فيه إلى المحكمة الشرعية. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11669/هل-للانثى-ان-تطالب-بحقها-من-الميراث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47704.mp3","categories":["الفرائض","الهبة والعطية","نصائح وتوجيهات"]},{"id":13395,"question":"يقول هذا السائل: أعاني كثيرًا من الرياء، مع أنني أصلي وأصوم وأزكي وأعمل الأعمال الصالحة، فهل آثم في ذلك؟ وهل أدخل في الشرك الأصغر؟","title":"توجيه لمن يرائي بأعماله الصالحة","answer":"الجواب: عليك أن تحذر الرياء، والرياء: مراءاة الناس بأعمالك من قراءة، أو صلاة، أو صدقات، أو غير ذلك، يجب أن تحذره، وأن تعتمد الإخلاص لله في أعمالك، وأن لا تبالي بالمخلوق، يكون عملك لله وحده، لا تقصد رياء أحد من الناس، لا في القراءة، ولا في الأمر بالمعروف، ولا في النهي عن المنكر، ولا في صلاة، ولا في غير ذلك، تقصد وجه الله، تقصد بأعمالك وجه الله، والقربة لديه  ولو كان عندك أمك، أو أبوك، أو قراباتك الآخرون؛ تجعل القصد وجه الله -جل وعلا- واعمل ابتغاء مرضاته، سواء كان العمل مع أمك، أو مع أبيك، أو مع غيرهم، فالواجب أن تكون أعمالك كلها لله وحده، ويقصد بها وجهه الكريم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11686/توجيه-لمن-يراىي-باعماله-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52514.mp3","categories":["نصائح وتوجيهات","الرياء والسمعة"]},{"id":13416,"question":"تقول السائلة: أشكو لكم حالي في أعمالي الخيرية، أو المشاريع الخيرية التي أساهم فيها، حيث أنني إذا فكرت في أعمال، أو مشاريع خير أجد الشيطان يدخل علي؛ فأتوقف عن عملها، رغم أن لها فائدة، فأفتوني ماذا أفعل؟","title":"توجيه لمن يتوقف عن أعمال الخير لوساوس الشيطان","answer":"الجواب: هذا من الشيطان، الواجب الحذر، إذا فكرت في بناء مسجد، أو في صدقة على فقير، أو صلة رحم؛ بادر، ولا تلتفت لوساوس الشيطان، احذر، إذا فكرت في خير؛ فبادر به، من بناء مسجد، من صلاة نافلة، من صوم نافلة، من صدقة، من سلام، من رد سلام، بادر، ولا تلتفت إلى وساوس الشيطان، احذر تثبيط الشيطان، وتعوذ بالله من الشيطان، وأرغم أنف الشيطان، قل: أعوذ بالله من الشيطان الرجيم، وبادر بالخير. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11710/توجيه-لمن-يتوقف-عن-اعمال-الخير-لوساوس-الشيطان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_526/52609.mp3","categories":["نصائح وتوجيهات"]},{"id":13606,"question":"هذه سائلة من الرياض تقول: سماحة الشيخ عبدالعزيز حفظه الله، تذكر بأنها امرأة تقول: لي جارة وهي أختي من أم وأب، وأنا يا شيخ أتصدق عليها من فترة إلى أخرى، ولكن بسبب خلاف بين زوجي وزوجها منع زوجي أن أتصدق عليها، أو أعطيها بعض الاحتياجات، مثل الخضروات، وغيرها، هل آثم إذا طلبت مني شيئًا ولم أعطيها بسبب منع زوجي، وما هي نصيحتكم لزوجي؟ جزاكم الله خيرًا.","title":"هل تأثم الزوجة في طاعة زوجها بعدم الصدقة على أختها؟","answer":"الجواب: لا إثم عليك إذا كانت زوجها يقوم بحالها ما هي بمضطرة، زوجها يقوم بحالها، وينفق عليها، ليس لك عصيان زوجك، بل عليك السمع والطاعة لزوجك، ولا تخالفي زوجك. أما إذا كانت مضطرة زوجها ما عنده شيء، وهي مضطرة لطعام ينقذها من الموت؛ فعليك أن تتصدقي عليها؛ لأنه لا طاعة لمخلوق في معصية الخالق، أما إذا كان عندها ما يقوم بحالها، زوجها ينفق عليها، وإنما هي تبرعات بخضروات، وهذا لا يجوز، بل عليك السمع والطاعة لزوجك وهي بحمد الله يقوم بها زوجها، والحمد لله؛ حتى يرضى عنك زوجك. والنصيحة لزوجك أن يتقي الله، وأن يسمح لك، وأن يدفع الشر بالخير، وأن يكون واسع البال، طيب الخلق، ولو غضب على زوجها لا يمنعك من أختك، هذا المشروع له، نوصيه بذلك، نوصيه بأن يعينك على البر والصلة، وإذا غضب على زوجها لا يمنعك من صلة أختك، نوصيه بذلك، نوصيه بأن يكون عنده رفق ورحمة وعناية، وأن يسمح لك بالصلة لأختك. المقدم: شكر الله لكم سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين. الشيخ: وإياكم.","link":"https://binbaz.org.sa/fatwas/11942/هل-تاثم-الزوجة-في-طاعة-زوجها-بعدم-الصدقة-على-اختها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52724.mp3","categories":["قضايا المرأة","نصائح وتوجيهات"]},{"id":13652,"question":"المستمعة التي رمزت لاسمها بـ (م. م) تقول في هذا  سماحة الشيخ! كيف نكون بارين بوالدينا ونحن نعيش في بلد، وهم في بلد آخر؟ وإذا كان الوالد، أو الوالدة يصلون، ولكنهم لا يحافظون عليها في وقتها، أو يصلونها بسرعة جدًا، فماذا علينا ونحن بعيدين عنهم؟","title":"كيفية بر المسافر لوالديه","answer":"الجواب: على الولد النصيحة لوالديه، وبرهما حسب الطاقة؛ لقول الله تعالى: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إن كان حاضرًا بالكلام الطيب، والفعل الطيب، وإن كان غائبًا بالمكاتبة بالهاتف -التلفون- فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ينصح، يسلم عليه، يدعو له، في الكتابة، في التلفون، وإذا حضر يدعو له، ويشكره على أعماله الطيبة، وإذا رأى منه تقصيرًا في الصلاة، أو غيرها؛ نصحه بالعبارة الطيبة، وبالرفق، كما قال الله -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا [لقمان:15] ثم قال بعده: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران، قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمر الولد أن يصحب أبويه بالمعروف، وإن كانا كافرين، فكيف إذا كانا مسلمين؟ فالواجب على الولد ذكرًا كان، أو أنثى أن يتقي الله، وأن يبر والديه بالفعل والقول، إن كانا فقيرين وهو قادر؛ أنفق عليهما، وإذا أمراه أطاعهما في المعروف، وإذا دخل عليهما؛ سلم عليهما، واحترمهما، ودعا لهما، وإذا كانا غائبين؛ راسلهما بالمكاتبة، أو من طريق الهاتف، يدعو لهما، ويسلم عليهما.. وهكذا، يجتهد في أنواع الخير، وإذا كانا محتاجين؛ أنفق عليهما وهو قادر؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وقال رجل: يا رسول الله! من أبر؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب وفي رواية قال: يا رسول الله! من أحق الناس بحسن صحبتي؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك. فالمؤمن يجتهد في بر والديه، ويخص الأم بمزيد عناية، ثم الأقرب فالأقرب، من أولاده، وإخوته، وأعمامه، وعماته، وأخواله، وخالاته، ثم الأقرب فالأقرب. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12000/كيفية-بر-المسافر-لوالديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_543/54304.mp3","categories":["نصائح وتوجيهات"]},{"id":13657,"question":"المستمعة التي رمزت لاسمها بـ (م. م) تقول في هذا  سماحة الشيخ! كيف نكون بارين بوالدينا ونحن نعيش في بلد، وهم في بلد آخر؟ وإذا كان الوالد، أو الوالدة يصلون، ولكنهم لا يحافظون عليها في وقتها، أو يصلونها بسرعة جدًا، فماذا علينا ونحن بعيدين عنهم؟","title":"كيفية بر المسافر لوالديه","answer":"الجواب: على الولد النصيحة لوالديه، وبرهما حسب الطاقة؛ لقول الله تعالى: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] إن كان حاضرًا بالكلام الطيب، والفعل الطيب، وإن كان غائبًا بالمكاتبة بالهاتف -التلفون- فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ينصح، يسلم عليه، يدعو له، في الكتابة، في التلفون، وإذا حضر يدعو له، ويشكره على أعماله الطيبة، وإذا رأى منه تقصيرًا في الصلاة، أو غيرها؛ نصحه بالعبارة الطيبة، وبالرفق، كما قال الله -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا [لقمان:15] ثم قال بعده: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران، قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] فأمر الولد أن يصحب أبويه بالمعروف، وإن كانا كافرين، فكيف إذا كانا مسلمين؟ فالواجب على الولد ذكرًا كان، أو أنثى أن يتقي الله، وأن يبر والديه بالفعل والقول، إن كانا فقيرين وهو قادر؛ أنفق عليهما، وإذا أمراه أطاعهما في المعروف، وإذا دخل عليهما؛ سلم عليهما، واحترمهما، ودعا لهما، وإذا كانا غائبين؛ راسلهما بالمكاتبة، أو من طريق الهاتف، يدعو لهما، ويسلم عليهما.. وهكذا، يجتهد في أنواع الخير، وإذا كانا محتاجين؛ أنفق عليهما وهو قادر؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وقال رجل: يا رسول الله! من أبر؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أمك. قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب وفي رواية قال: يا رسول الله! من أحق الناس بحسن صحبتي؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك. فالمؤمن يجتهد في بر والديه، ويخص الأم بمزيد عناية، ثم الأقرب فالأقرب، من أولاده، وإخوته، وأعمامه، وعماته، وأخواله، وخالاته، ثم الأقرب فالأقرب. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12000/كيفية-بر-المسافر-لوالديه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_543/54304.mp3","categories":["نصائح وتوجيهات"]},{"id":13689,"question":"بعد ذلك ننتقل إلى رسالة هذا السائل الذي رمز لاسمه بـ (ص. ع. ش) السؤال هو: أنني وبعض الأشخاص نذهب يوم الجمعة إلى أداء صلاة الجمعة في مسجد جامع في قرى مجاورة بالرغم من وجود مسجد جامع لدينا، وبه خطيب، فهل يجب أن يصلي الشخص في الجامع الموجود في قريته؟ أم أنه يصلي الجمعة في أي جامع آخر؟ والسلام عليكم.","title":"حكم الذهاب للمساجد المجاورة لأداء الجمعة وترك مسجد القرية","answer":"الجواب:  لا حرج على المسلم أن يصلي في أي جامع، ولاسيما إذا كان الجامع الذي يقصده خطبة صاحبه أحسن وأنفع، أو صلاته أرشد، أو جماعته أكثر، لا بأس إذا ترك المسجد الذي حوله لمصلحة شرعية، وإن صلى في المسجد الذي قربه؛ فلا بأس والحمد لله، لكن إذا ترك المسجد الأقرب لمصلحة شرعية من أجل كثرة الخطى، أو من أجل أن خطيب ذلك المسجد أكثر فائدة، أو صلاته أكمل، أو لأسباب أخرى؛ فلا بأس. أما إذا ترك المسجد القريب على وجه -يعني- يشق على أهل تركه لهم، أو يوجب أنهم يتهمونه بأنه غير راض عن الإمام، أو يتهموا الإمام؛ ينبغي أن يدفع عن نفسه الشيء الذي يخشى منه، ينبغي يصلي مع هذا تارة، ومع هذا تارة؛ حتى لا تكون هناك شكوك وأوهام إذا كان إمام المسجد الذي حوله طيب، ولا شبهة فيه يصلي معه بعض الأحيان؛ حتى لا يظن أنه ظن به السوء، أو أنه لا يصلح. المقصود: إذا كانت صلاته في المسجد البعيد لا يترتب عليها شيء من المضار؛ فلا بأس، ولاسيما إذا كان تجاوزه هذا المسجد قد يسبب ظنًا بإمامه، وأنه ليس أهلًا للإمامة، فينبغي له أن يصلي فيه بعض الأحيان حتى تزول هذه الشكوك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12041/حكم-الذهاب-للمساجد-المجاورة-لاداء-الجمعة-وترك-مسجد-القرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_519/51918.mp3","categories":["صلاة الجمعة","نصائح وتوجيهات"]},{"id":13697,"question":"هذا السائل مصري خالد محمد ومقيم بتبوك، يقول في هذا  ما حكم الشرع في نظركم -سماحة الشيخ- في شاب خطب فتاة، واستمرت الخطوبة ما يقارب من عامين، ولكن الشاب ابتعد عنها لأسباب عائلية، ما حكم ذلك مأجورين؟","title":"حكم فسخ الخطبة","answer":"الجواب: لا حرج في ذلك، إذا خطب، ثم بدا له أن لا يتزوج له حق، سواء بعد سنة، أو أقل، أو أكثر، إذا خطبها ثم بدا له ألا يتزوجها، أو هي وافقت، ثم رجعت؛ لا حرج في ذلك، الحمد لله، ما دام ما تم العقد كل بالخيار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12079/حكم-فسخ-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53507.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13699,"question":"هذا السائل مصري خالد محمد ومقيم بتبوك، يقول في هذا  ما حكم الشرع في نظركم -سماحة الشيخ- في شاب خطب فتاة، واستمرت الخطوبة ما يقارب من عامين، ولكن الشاب ابتعد عنها لأسباب عائلية، ما حكم ذلك مأجورين؟","title":"حكم فسخ الخطبة","answer":"الجواب: لا حرج في ذلك، إذا خطب، ثم بدا له أن لا يتزوج له حق، سواء بعد سنة، أو أقل، أو أكثر، إذا خطبها ثم بدا له ألا يتزوجها، أو هي وافقت، ثم رجعت؛ لا حرج في ذلك، الحمد لله، ما دام ما تم العقد كل بالخيار، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12079/حكم-فسخ-الخطبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53507.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":13716,"question":"في ثاني أسئلة السائل (ع. ع. ج) من الرياض يقول: هناك رجل متزوج من زوجتين، ولم يعدل بينهما لا في النفقة، ولا المبيت، فهل لسماحة الشيخ عبدالعزيز من كلمة تجاه هؤلاء الأزواج؟","title":"توجيه للأزواج بالعدل بين الزوجات","answer":"الجواب: نعم، الواجب على الزوج أن يعدل إذا كان له زوجتان أو ثلاث، فالواجب عليه أن يعدل في النفقة والقسم، ليتق الله في ذلك، وفي الخلق الحسن مهما استطاع. أما الجماع ما يجب العدل فيه؛ لأنه ليس باختياره، قد يشتهي هذه في بعض الأحيان، ولا يشتهي الأخرى، لكن في النفقة والقسم وحسن الخلق يجب أن يعدل، ويتقي الله في ذلك، لا يظلم هذه دون هذه، لا يظلمهما جميعًا، ولا يقصر في حق هذه، ويكمل في حق هذه، بل يجب أن يعدل في الجميع، ينفق على كل واحدة النفقة اللائقة بها، ويقسم لها قسم الذي فرضه الله عليه، ولكن كونه يحب هذه أكثر، أو يجامعها أكثر هذا ليس باختياره، هذا بيد الله -جل وعلا- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12087/توجيه-للازواج-بالعدل-بين-الزوجات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54509.mp3","categories":["تعدد الزوجات","نصائح وتوجيهات"]},{"id":13733,"question":"في ثاني أسئلة هذا السائل من الدمام يقول: ما حكم التعامل مع شخص تارك للصلاة، ومتهاون في أداء العبادات؟ جزاكم الله خيرًا.","title":"حكم التعامل مع تارك الصلاة","answer":"الجواب: يكره التعامل مع هذا، ومع بقية الكفرة؛ لأن فيه خطر، قد يجرك إلى ما هو عليه من الباطل، فلا ينبغي التعاون معه، بل ينبغي هجره؛ حتى يتوب إلى الله، وإن كان كافرًا أصليًا؛ ينبغي إبعاده، وعدم صحبته؛ حتى لا يجرك إلى الباطل، وإن كان مسلمًا، ثم ارتد فهو أقبح وأقبح، يجب الحذر منه، لكن مع دعوته إلى الله مع نصيحته؛ لعله يرجع، لعله يتوب إلى الله، لعله يرجع إلى الإسلام، وإن كان كافرًا أصليًا؛ لعله يتوب، لعله يقبل الحق، فإذا نصحته لله، ورجع؛ فالحمد لله، وإلا فاتركه، والتمس الطيب من المسلمين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12104/حكم-التعامل-مع-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_545/54518.mp3","categories":["حكم الصلاة وأهميتها","نصائح وتوجيهات"]},{"id":13769,"question":"عن دعاء الاستخارة - سماحة الشيخ - يقول هذا السائل: متى يكون دعاء الاستخارة؟ هل يكون في السجود أم بعد السلام من صلاة الركعتين؟ وهل لا بد لذلك الدعاء أن يبدأ بالحمد والثناء على المصطفى ﷺ؟","title":"متى يكون دعاء الاستخارة؟","answer":"الجواب: هذا هو الأفضل بلا شك، هذا هو الأفضل يبدأ بالصلاة والسلام على النبي ﷺ.\nالشيخ: أعد سؤاله.\nالمقدم: متى يكون دعاء الاستخارة؟ هل يكون في السجود أم بعد السلام من صلاة الركعتين؟وهل لا بد لذلك الدعاء أن يبدأ بالحمد والثناء على الرسول ﷺ؟\nالشيخ: يكون بعد السلام، ويبدأ بالحمد والثناء، يقول النبي ﷺ: إذا هم أحدكم بأمر فليركع ركعتين من غير الفريضة، ثم يقول: اللهم إني أستخيرك بعلمك.. إلى آخره، فالسنة أن يرفع يديه ويدعو بعد الركعتين، يدعو ويرفع يديه ويبدأ بحمد الله والصلاة على النبي ﷺ؛ لقوله ﷺ: إذا دعا أحدكم فليبدأ بتحميد ربه، والثناء عليه ثم يصلي على النبي ﷺ ثم يدعو بما شاء فالذي يستخير أولاً: يصلي ركعتين في وقت الصلاة .. ضحى وإلا في الليل وإلا بعد الظهر، ثم إذا سلم يرفع يديه ويستخير، يحمد الله ويصلي على النبي ﷺ، ثم يقول : اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر - ويسميه باسمه - اللهم إن كنت تعلم أن هذا الأمر، - يعني: أن هذا الزواج بفلانة، أو شرائي للعقار الفلاني، أو سفري إلى كذا، يعيِّن - خير لي في ديني ودنياي ومعاشي وعاقبة أمري فيسره لي ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر - ويسميه باسمه - شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه، وقدر لي الخير حيث كان ثم أرضني به هكذا جاء في الحديث الصحيح في الاستخارة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12157/متى-يكون-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53610.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":13787,"question":"هذا السائل جمال صالح يقول في هذا  سماحة الشيخ! ما حكم الإسلام في نظركم في المغالاة في المهور؟ وعدم تزويج الشباب وتحميلهم أعباء كثيرة على الزواج من حيث الترتيبات؟ وما نصيحتكم لأولياء الأمور في هذه المسألة الخطيرة التي يجب أن تعالج من قبلكم؟ جزاكم الله خيرًا.","title":"توجيه في تيسير المهور وعدم المغلاة فيها","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فنصيحتي لجميع المسلمين من الرجال والنساء عدم المغالاة في المهور وعدم التكلف تسهيلًا للزواج لعفة الرجال والنساء جميعًا، فهذه نصيحتي لهم، وقد جاءت الأحاديث والآثار عن السلف بالدلالة على ذلك فالسنة للمؤمن عدم المغالاة.\nوعلى أولياء الأمور أن يتقوا الله في هذا الأمر وأن يحرصوا على تزويج بنيهم وبناتهم بالطرق الممكنة الميسرة التي ليس فيها ضرر على الجميع، والأوقات تختلف، ولكن يتحرون المهر المناسب الذي يحصل به المطلوب من دون مشقة على الزوج؛ لأن كثيرًا من الناس قد يتأخر عن الزواج بسبب المغالاة لا يقدر، وربما تعطل كثير من النساء بسبب ذلك وحصل من الفساد ما لا يحصيه إلا الله .\nفالمشروع للجميع العناية بهذا الأمر؛ الرجل يعتني والمرأة تعتني، الرجل يعتني ويحرص على التخفيف والتيسير لتزويج بناته وأخواته وغيرهم، والنصيحة لهن في ذلك، والمرأة كذلك تتقي الله وتحرص على التخفيف مع بنتها ومع أختها ومع قريباتها حتى يتعاون الجميع على التخفيف والتيسير، وبهذا يتيسر الزواج لجميع الشباب من الرجال والنساء، ولا يخفى أن وجود الزواج مع المئونة القليلة خير من تعطيل الرجل أو تعطيل المرأة، كونها تتزوج ويعفها الرجل بمهر مناسب ليس فيه تكلف خير لها في الدنيا والآخرة، وهكذا الرجل كونه يتزوج ويتيسر له المرأة المناسبة من دون تكلف خير له في الدنيا والآخرة، فالجميع عليهم التعاون والتواصي بهذا الأمر لعل الله جل وعلا يكتب لذلك النجاح. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12146/توجيه-في-تيسير-المهور-وعدم-المغلاة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53001.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":13863,"question":"المستمع (ن. ن. ن) بعث بعدد من الأسئلة يسأل في أحد أسئلته عن الكيفية الصحيحة للأمر بالمعروف والنهي عن المنكر، وما هي الحكمة المقصودة في مثل هذا المقام؟","title":"الكيفية الصحيحة في الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: هذا سؤال عظيم وجدير بالعناية؛ لأن الأمر بالمعروف أو النهي عن المنكر من أهم الواجبات ومن فرائض الإسلام، ولأن القيام بذلك من أهل العلم والإيمان والبصيرة من أعظم الأسباب في صلاح المجتمع وسلامته من عقاب الله سبحانه واستقامته على الصراط المستقيم.\nولهذا يقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] فجعلهم خير أمة بسبب هذه الأعمال الطيبة، وقال سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] وصفهم بالفلاح لهذا الأمر العظيم لدعوتهم إلى الخير وأمرهم بالمعروف ونهيهم عن المنكر، فجعلهم مفلحين بعملهم الطيب، والفلاح: هو الحصول على كل خير، الحصول على أسباب السعادة، وقال : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] فوعدهم الرحمة على أعمالهم الطيبة التي منها الأمر بالمعروف والنهي عن المنكر.\nوهذا يدل على أن هذا هو الواجب على المؤمنين والمؤمنات ليس خاصًا بأحد دون أحد، بل هذا هو الواجب على المؤمنين والمؤمنات وهو من صفاتهم العظيمة وأخلاقهم الكريمة لكن يكون بالحكمة، يكون بالعلم لا بالجهل ولا بالعنف والشدة ولكن بالعلم، يأمر بالمعروف وينهى عن المنكر عن علم وعن بصيرة بما أمر الله به وما نهى الله عنه، فالمعروف هو ما أمر الله به ورسوله، والمنكر هو ما نهى الله عنه ورسوله.\nفالواجب على الآمر الناهي أن يكون ذا بصيرة أن يكون على علم سواء كان رجل أو امرأة لابد أن يكون على علم وإلا فليمسك حتى لا يأمر بالمنكر أو ينهى عن المعروف، قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم، ويقول سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] والدعوة إلى الله من جنس الأمر بالمعروف والنهي عن المنكر؛ لأنه بيان الحق وإظهاره للناس، فالآمر كذلك يدعو إلى الله والناهي كذلك إلا أن الآمر والناهي قد يكون عنده من السلطة ما يردع المنكر ويلزم بالمعروف، والداعي إلى الله أوسع من ذلك يبين للناس ويرشدهم إلى الحق وقد لا تكون عنده سلطة للإلزام.\nفالحاصل أن الواجب على الداعي إلى الله والآمر بالمعروف والناهي عن المنكر أن يكون على علم وأن يكون على بينة وعلى بصيرة حتى لا يأمر بما يخالف الشرع، وحتى لا ينهى عما هو موافق للشرع. والواجب أيضًا أن يكون برفق وعدم عنف وعدم كلمات بذيئة، بل يكون بكلام طيب وأسلوب حسن ورفق كما قال الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] وقال سبحانه لـموسى وهارون لما بعثهما إلى فرعون: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] فالآمر الناهي يرفق بالناس ويأمر بالألفاظ الحسنة وينهاهم بالألفاظ الحسنة حتى يكون ذلك أقرب إلى قبول أمره ونهيه والاستفادة من ذلك إلا من ظلم وتعدى وأبى فهذا له أسلوب آخر من التعنيف والتأديب إذا لم يلتزم بالأمر بالمعروف ولم ينته عن المنكر، أما في أول الأمر فإنه يخاطبهم بالتي هي أحسن ويرشدهم وينصحهم حتى يلتزموا الحق، فمن عاند وأبى فله حال أخرى من جهة إجراء ما يستحق من تعنيف ومن تشديد وتأديب أو سجن أو غير ذلك مما يقتضيه الشرع المطهر، والله المستعان. نعم.\nالمقدم: الله المستعان على كل حال، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12237/الكيفية-الصحيحة-في-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60308.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":13866,"question":"المستمع (ن. ن. ن) بعث بعدد من الأسئلة يسأل في أحد أسئلته عن الكيفية الصحيحة للأمر بالمعروف والنهي عن المنكر، وما هي الحكمة المقصودة في مثل هذا المقام؟","title":"الكيفية الصحيحة في الأمر بالمعروف والنهي عن المنكر","answer":"الجواب: هذا سؤال عظيم وجدير بالعناية؛ لأن الأمر بالمعروف أو النهي عن المنكر من أهم الواجبات ومن فرائض الإسلام، ولأن القيام بذلك من أهل العلم والإيمان والبصيرة من أعظم الأسباب في صلاح المجتمع وسلامته من عقاب الله سبحانه واستقامته على الصراط المستقيم.\nولهذا يقول سبحانه: كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ [آل عمران:110] فجعلهم خير أمة بسبب هذه الأعمال الطيبة، وقال سبحانه: وَلْتَكُنْ مِنْكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنْكَرِ وَأُوْلَئِكَ هُمُ الْمُفْلِحُونَ [آل عمران:104] وصفهم بالفلاح لهذا الأمر العظيم لدعوتهم إلى الخير وأمرهم بالمعروف ونهيهم عن المنكر، فجعلهم مفلحين بعملهم الطيب، والفلاح: هو الحصول على كل خير، الحصول على أسباب السعادة، وقال : وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] فوعدهم الرحمة على أعمالهم الطيبة التي منها الأمر بالمعروف والنهي عن المنكر.\nوهذا يدل على أن هذا هو الواجب على المؤمنين والمؤمنات ليس خاصًا بأحد دون أحد، بل هذا هو الواجب على المؤمنين والمؤمنات وهو من صفاتهم العظيمة وأخلاقهم الكريمة لكن يكون بالحكمة، يكون بالعلم لا بالجهل ولا بالعنف والشدة ولكن بالعلم، يأمر بالمعروف وينهى عن المنكر عن علم وعن بصيرة بما أمر الله به وما نهى الله عنه، فالمعروف هو ما أمر الله به ورسوله، والمنكر هو ما نهى الله عنه ورسوله.\nفالواجب على الآمر الناهي أن يكون ذا بصيرة أن يكون على علم سواء كان رجل أو امرأة لابد أن يكون على علم وإلا فليمسك حتى لا يأمر بالمنكر أو ينهى عن المعروف، قال تعالى: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ [يوسف:108] يعني: على علم، ويقول سبحانه: ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] والدعوة إلى الله من جنس الأمر بالمعروف والنهي عن المنكر؛ لأنه بيان الحق وإظهاره للناس، فالآمر كذلك يدعو إلى الله والناهي كذلك إلا أن الآمر والناهي قد يكون عنده من السلطة ما يردع المنكر ويلزم بالمعروف، والداعي إلى الله أوسع من ذلك يبين للناس ويرشدهم إلى الحق وقد لا تكون عنده سلطة للإلزام.\nفالحاصل أن الواجب على الداعي إلى الله والآمر بالمعروف والناهي عن المنكر أن يكون على علم وأن يكون على بينة وعلى بصيرة حتى لا يأمر بما يخالف الشرع، وحتى لا ينهى عما هو موافق للشرع. والواجب أيضًا أن يكون برفق وعدم عنف وعدم كلمات بذيئة، بل يكون بكلام طيب وأسلوب حسن ورفق كما قال الله : فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] وقال سبحانه لـموسى وهارون لما بعثهما إلى فرعون: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] فالآمر الناهي يرفق بالناس ويأمر بالألفاظ الحسنة وينهاهم بالألفاظ الحسنة حتى يكون ذلك أقرب إلى قبول أمره ونهيه والاستفادة من ذلك إلا من ظلم وتعدى وأبى فهذا له أسلوب آخر من التعنيف والتأديب إذا لم يلتزم بالأمر بالمعروف ولم ينته عن المنكر، أما في أول الأمر فإنه يخاطبهم بالتي هي أحسن ويرشدهم وينصحهم حتى يلتزموا الحق، فمن عاند وأبى فله حال أخرى من جهة إجراء ما يستحق من تعنيف ومن تشديد وتأديب أو سجن أو غير ذلك مما يقتضيه الشرع المطهر، والله المستعان. نعم.\nالمقدم: الله المستعان على كل حال، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12237/الكيفية-الصحيحة-في-الامر-بالمعروف-والنهي-عن-المنكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60308.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":13867,"question":"أخيرًا يسأل الأخ عن الكتب التي تنصحون طلبة المتوسطة بقراءتها من كتب السنة؟","title":"كتب ينصح بقراءتها لطلبة المرحلة المتوسطة","answer":"الجواب: نوصي طلبة المرحلة المتوسطة بالعناية بمقرراتهم والإقبال عليها والحرص على الاستفادة منها؛ لأنهم مشغلون بها ولينجحوا فيها أيضاً ولأنها مفيدة، المقررات الدراسية فيما يتعلق بالتوحيد والعبادات مهمة ومفيدة، فإذا كان عنده وقت فنوصيه بمثل: كتاب التوحيد يدرسه، ومثل: كشف الشبهات يحفظه ويتأمل هذين الكتابين فهما مفيدان، ومثل: الأربعين النووية يحفظها خمسين حديث اثنين وأربعين للنووي وثمانية للحافظ ابن رجب خمسون حديثًا من جوامع الكلم يحفظها، فهذه المرحلة ....... جيدة يحفظها وفي هذا كفاية حتى ينتقل للثانوي إن شاء الله. نعم.","link":"https://binbaz.org.sa/fatwas/12239/كتب-ينصح-بقراءتها-لطلبة-المرحلة-المتوسطة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_603/60310.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":13878,"question":"سماحة الشيخ! قبل أن نختم هذا اللقاء هل من كلمة للذين يقومون على الأيتام؟ جزاكم الله خيرًا.","title":"نصيحة لأولياء الأيتام","answer":"الجواب: نعم. نوصيهم بتقوى الله، والحرص على تربية الأيتام التربية الشرعية، والقيام عليهم في الصلاة إذا كانوا قد بلغوا السابعة فأكثر، وتربيتهم التربية الإسلامية في أمرهم بطاعة الله ونهيهم عن المعاصي وعن قرناء السوء، والعناية بأموالهم وحفظها وتربيتها وتنميتها، كل هذا أمر مهم، فنوصي أولياء الأيتام بالنصح للأيتام وأن يؤمروا بطاعة الله، وأن يمنعوا عن محارم الله، وأن يمنعوا من قرناء السوء، وأن ... حفظ أموالهم وتربيتها، وإذا كانوا دون السبع كذلك يوصى بهم خيرًا تربيتهم وتعليمهم والإحسان إليهم حتى يميزوا، ثم يؤمروا بالصلاة مع الناس، ويلاحظ عليهم كل شيء ينفعهم في الدين والدنيا.","link":"https://binbaz.org.sa/fatwas/12294/نصيحة-لاولياء-الايتام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50622.mp3","categories":["نصائح وتوجيهات"]},{"id":13892,"question":"سماحة الشيخ! قبل أن نختم هذا اللقاء هل من كلمة للذين يقومون على الأيتام؟ جزاكم الله خيرًا.","title":"نصيحة لأولياء الأيتام","answer":"الجواب: نعم. نوصيهم بتقوى الله، والحرص على تربية الأيتام التربية الشرعية، والقيام عليهم في الصلاة إذا كانوا قد بلغوا السابعة فأكثر، وتربيتهم التربية الإسلامية في أمرهم بطاعة الله ونهيهم عن المعاصي وعن قرناء السوء، والعناية بأموالهم وحفظها وتربيتها وتنميتها، كل هذا أمر مهم، فنوصي أولياء الأيتام بالنصح للأيتام وأن يؤمروا بطاعة الله، وأن يمنعوا عن محارم الله، وأن يمنعوا من قرناء السوء، وأن ... حفظ أموالهم وتربيتها، وإذا كانوا دون السبع كذلك يوصى بهم خيرًا تربيتهم وتعليمهم والإحسان إليهم حتى يميزوا، ثم يؤمروا بالصلاة مع الناس، ويلاحظ عليهم كل شيء ينفعهم في الدين والدنيا.","link":"https://binbaz.org.sa/fatwas/12294/نصيحة-لاولياء-الايتام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50622.mp3","categories":["نصائح وتوجيهات"]},{"id":13907,"question":"هذا سائل أرسل بمجموعة من الأسئلة السائلة أختكم في الله سمية علي من السودان تقول في هذا  ما هي الأسباب التي تعين الإنسان على قيام الليل؟ جزاكم الله خيرًا.","title":"ما الأسباب التي تعين الإنسان على قيام الليل؟","answer":"الجواب: الأسباب التي تعين الإنسان على قيام الليل كثيرة منها: فإذا اتخذ الأسباب يسر الله أمره، وأهمها الصدق مع الله والإخلاص في هذا وعدم السهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12302/ما-الاسباب-التي-تعين-الانسان-على-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53819.mp3","categories":["نصائح وتوجيهات","الوتر وقيام الليل"]},{"id":13910,"question":"هذا سائل أرسل بمجموعة من الأسئلة السائلة أختكم في الله سمية علي من السودان تقول في هذا  ما هي الأسباب التي تعين الإنسان على قيام الليل؟ جزاكم الله خيرًا.","title":"ما الأسباب التي تعين الإنسان على قيام الليل؟","answer":"الجواب: الأسباب التي تعين الإنسان على قيام الليل كثيرة منها: فإذا اتخذ الأسباب يسر الله أمره، وأهمها الصدق مع الله والإخلاص في هذا وعدم السهر. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12302/ما-الاسباب-التي-تعين-الانسان-على-قيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53819.mp3","categories":["نصائح وتوجيهات","الوتر وقيام الليل"]},{"id":13913,"question":"في آخر أسئلة هذا السائل من الأردن يقول: نحن ثلاث إخوان من أم وأب، أنا وأختان، الأخت الكبيرة متزوجة ولله الحمد ومتعلمة، أما الأخت الثانية فهي غير متزوجة ولديها مشكلة ألا وهي أنها لا تعرف أن تقرأ ولا تعرف أن تكتب، فقد خرجت من المدرسة في صغرها فأنا أعطيها أشرطة قرآن من السور القصيرة لتحفظها مع تكرار التلاوة، فهل هذا يكفي يا سماحة الشيخ؟","title":"مشروعية تعليم الأمي أمور دينه","answer":"الجواب: هذا طيب جزاك الله خير، ويشرع لك أن تعلمها أنت، وأختك الكبيرة تعلمها أيضًا حتى تحفظ ما تيسر من القرآن، وعليكما أن تعلماها أحكام الدين.. أحكام الصلاة.. أحكام الصيام.. أحكام الحيض حتى تكون على بصيرة، علموها، هكذا المؤمن يعلم أقاربه في الذمة، ويقول النبي ﷺ: خيركم من تعلم القرآن وعلمه ويقول ﷺ: من يرد الله به خيرًا يفقهه في الدين، ويقول عليه الصلاة والسلام: والله في عون العبد ما كان العبد في عون أخيه، ويقول عليه الصلاة والسلام: من كان في حاجة أخيه كان الله في حاجته.\nفالواجب تعليمها وإرشادها منك ومن أختها بكل ما قد تجهل من صلاة أو أحكام حيض أو أحكام نفاس أو أحكام صيام أو غير هذا، مع تعليمها ما تيسر من القرآن الكريم ومن أحكام الصلاة وأنتم على خير ولكم أجر عظيم، يقول النبي ﷺ: من دل على خير فله مثل أجر فاعله ويقول ﷺ: خيركم من تعلم القرآن وعلمه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12317/مشروعية-تعليم-الامي-امور-دينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54408.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":13934,"question":"يقول: حلفت يمين أن أترك الدخان، وتركته فترة معينة إلا أنني رجعت ما حكم ما فعلت؟ وماذا أفعل إذا كان علي كفارة؟ جزاكم الله خيرًا.","title":"حكم من حلف على ترك الدخان ثم عاد إليه","answer":"الجواب: عليك التوبة إلى الله؛ لأن الدخان محرم خبيث ومضاره كثيرة، فعليك التوبة إلى الله جل وعلا وأن تحذر مجالسة المدخنين، فإن مجالستهم من أسباب رجوعك إليه. وعليك كفارة اليمين عن يمينك وهي إطعام عشرة مساكين أو كسوتهم أو عتق رقبة، فإن كنت فقير لا تستطيع عاجز عن الطعام والكسوة والعتق فإنك تصوم ثلاثة أيام هذه كفارة اليمين، قال الله سبحانه: لا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِنْ يُؤَاخِذُكُمْ بِمَا عَقَّدْتُمُ الأَيْمَانَ فَكَفَّارَتُهُ إِطْعَامُ عَشَرَةِ مَسَاكِينَ مِنْ أَوْسَطِ مَا تُطْعِمُونَ أَهْلِيكُمْ أَوْ كِسْوَتُهُمْ أَوْ تَحْرِيرُ رَقَبَةٍ فَمَنْ لَمْ يَجِدْ فَصِيَامُ ثَلاثَةِ أَيَّامٍ ذَلِكَ كَفَّارَةُ أَيْمَانِكُمْ إِذَا حَلَفْتُمْ وَاحْفَظُوا أَيْمَانَكُمْ [المائدة:89] الآية في سورة المائدة، فالرب جل وعلا يأمرنا بالكفارة من أوسط الطعام أو كسوة أو عتق رقبة، فإن عجز الحالف صام ثلاثة أيام، وأمر بحفظ الأيمان، وأنه لا ينبغي للإنسان أن يحلف إلا عند الحاجة. والدخان شره كثير، فينبغي لك يا عبد الله! أيها السائل! أن تحذره وأن تستمر في تركه، وألا تجالس أهله، وأن تنصحهم لعل الله يهديك ويهدي بك، بارك الله فيك. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12333/حكم-من-حلف-على-ترك-الدخان-ثم-عاد-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48209.mp3","categories":["الطلاق","الأيمان والنذور","نصائح وتوجيهات"]},{"id":13936,"question":"سماحة الشيخ! هذه سائلة تقول: بأنها من المستمعات لهذا البرنامج المفيد، وتذكر بأنها في بداية حياتها تقول: كنت مفرطة على نفسي بكثير من المعاصي، وحصلت لي مشكلة قلبت موازيني فاستعنت بالله عليها ووجدت الراحة النفسية والسعادة الحقيقية عندما عدت إلى الله، فأنا أحافظ على الصلوات في أوقاتها وأصوم ثلاثة أيام من كل شهر وأقرأ القرآن وأحمد الله وأشكره على ذلك.وبعد سنوات من الاستقامة أحسست ببعض الأمراض النفسية تنتابني في بعض الأحيان، ووساوس وأفكار وضيق بالنفس أحس وكأن أحد يشد على حلقي كلما تذكرت ذنوبي لأرتاح بصلاتي فأنا لا أرتاح لا بصلاتي ولا بنومي ولا حتى بقراءتي، أرجو من سماحة الشيخ أن يوجهني في هذه الكلمات.","title":"توجيه لمن تشعر بوساوس وضيق النفس بعد الاستقامة","answer":"الجواب: هذا الحرج الجديد هذا من الشيطان، فالمشروع لك حينئذ أن تكثري من التعوذ بالله من الشيطان، وأن تذكري رحمة الله وفضله وإحسانه، فإنه جل وعلا يتوب على التائبين، وهو القائل : وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] ويقول سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] فالتوبة تجب ما قبلها والحمد لله.\nواحذري وساوس الشيطان، واطمئني على ما هداك الله له من الأعمال الصالحة والتقوى والاستقامة، واحذري نزغات الشيطان، كوني منشرحة الصدر طيبة النفس بما هداك الله له من طاعته وتوحيده وذكره والأعمال الصالحة، وكلما عرض عليك شيء من الوساوس قولي: أعوذ بالله من الشيطان الرجيم واتفلي عن يسارك ثلاث مرات، وتعوذي بالله من الشيطان ثلاث مرات، وأبشري بالخير، أرغمي عدو الله الشيطان بالتعوذ بالله من الشيطان، وانشرحي الصدر بالثقة بالله وأنه الغفور الرحيم، وأنه الجواد الكريم وأنه يتوب على التائبين، ويقبل توبة التائبين الصادقين وأبشري بالخير.","link":"https://binbaz.org.sa/fatwas/12332/توجيه-لمن-تشعر-بوساوس-وضيق-النفس-بعد-الاستقامة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54417.mp3","categories":["الأدعية والأذكار","قضايا المرأة","نصائح وتوجيهات"]},{"id":13942,"question":"من العراق محافظة نينوى هذه رسالة بعث بها المستمع محسن مرفوء أحمد لأخينا سبعة أسئلة يسأل في سؤاله الأول ويقول: إن أكثر الشباب عندما أنصحهم بالصلاة يقولون: لا نستطيع أن نصلي؛ لأننا ننظر إلى النساء وخاصة المتبرجات، فهل النظر يمنع الصلاة؟ أو يبطلها؟ جزاكم الله خيرًا.","title":"حكم الامتناع عن الصلاة بسبب المعاصي","answer":"الجواب: هذا عذر باطل، الواجب عليهم أن يصلوا مع المسلمين وأن يحافظوا على ما أوجب الله عليهم من الصلاة ومن غض البصر، والصلاة في الجماعة في المساجد فريضة، يقول ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وهي عمود الإسلام يجب على المسلم أن يؤديها إذا كان مكلفًا يجب عليه أن يؤديها، وتركها كفر بالله وضلال، وليس رؤية النساء في الطريق أو في المسجد إذا كن يصلين في المسجد ليس هذا عذرًا في ترك الصلاة أو ترك الجماعة، بل هذا غلط ومنكر، واعتذار بمنكر عن منكر، وهو ترك الصلاة. نسأل الله العافية. والواجب على المسلم غض البصر أن يتقي الله ويغض بصره عن النساء في الأسواق وفي كل مكان، وليس عذرًا له أن يذهب إلى الصلاة أن يصادفه في الطريق نساء، إذا صادف في الطريق نساء يغض بصره ويجاهد نفسه، قال الله : قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ [النور:30].\nفالمسلم يغض بصره ويتقي الله ويحفظ فرجه ويؤدي ما أوجب الله عليه من الصلاة في مساجد الله مع المسلمين يخاف الله ويرجوه، قال تعالى: فِي بُيُوتٍ أَذِنَ اللَّهُ أَنْ تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ [النور:36]، وقال عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر وقال في شأن الصلاة وعظمتها: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر خرجه الإمام أحمد وأهل السنن بإسناد صحيح، وقال عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه الإمام مسلم في صحيحه رحمه الله، في أحاديث أخرى دالة على عظم شأنها، ويقول ﷺ: رأس الأمر الإسلام وعموده الصلاة وقد هم عليه الصلاة والسلام أن يحرق على المتخلفين بيوتهم، المتخلفين عن الصلاة في الجماعة.\nفالواجب على كل مسلم وعلى كل مسلمة أن يتقي الله وأن يحافظ على الصلاة في أوقاتها، وأن يحذر التخلف عنها فإن التخلف عنها من صفات أهل النفاق ومن صفات الكفرة، ومن أسباب دخول النار، قال الله تعالى في كتابه العظيم عن الكفار: مَا سَلَكَكُمْ فِي سَقَرَ ۝ قَالُوا لَمْ نَكُ مِنَ الْمُصَلِّينَ [المدثر:43]، فأجابوا بأنهم دخلوا النار لأنهم لم يكونوا من المصلين، نسأل الله العافية. فالمؤمن يتقي الله في كل شيء فيغض البصر ويحفظ الفرج ويحفظ الجوارح مما حرم الله ويؤدي ما أوجب الله من الصلاة والزكاة وبر الوالدين وصلة الرحم وغير ذلك، يجمع بين هذا وهذا، هذه الدار دار العمل دار التكليف دار الابتلاء والامتحان، فالواجب على كل مسلم وعلى كل مسلمة أن يتقي الله وأن يحافظ على ما أوجب الله وأن يتباعد عن محارم الله وأن يقف عند حدود الله يرجو ثواب الله ويخشى عقاب الله، ولهذا خلق، يقول سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56]. وهذه هي العبادة؛ الصلاة الزكاة الصيام الحج الجهاد الأمر بالمعروف والنهي عن المنكر الدعوة إلى الله بر الوالدين صلة الرحم.. إلى غير هذا مما شرعه الله، وهكذا ترك المحارم التي حرم الله على عباده تركها طاعة لله وتعظيمًا له من أفضل القربات. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12353/حكم-الامتناع-عن-الصلاة-بسبب-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60404.mp3","categories":["حكم الصلاة وأهميتها","نصائح وتوجيهات"]},{"id":13959,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول السائلة: أختكم في الله (ف. م) تسأل وتقول: ما حكم الشرع في فتاة ترفض الزواج وهي فتاة مسلمة ملتزمة صائنة لعفافها، ولذلك فهي ترى لا حاجة لها للزواج، بالإضافة إلى أنها تعيش في مجتمع يستهزئ بالدين ويسخر من الملتزمين به، لذلك فهي تحرص أن لا تكون أسرة في مثل هذا المجتمع خوفًا من الانحراف والضياع، التوجيه لو تكرمتم شيخ عبد العزيز.","title":"حكم امتناع المرأة عن الزواج ‏","answer":"الجواب: المشروع للمرأة وللرجل هو الزواج، هذا هو المشروع للشباب والفتيات هو الزواج؛ لما فيه من إحصان الفرج وغض البصر وتكثير النسل وتكثير الأمة، وقد قال الله  في كتابه العظيم: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]، وقال النبي عليه الصلاة والسلام: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء، وكان ﷺ ينهى عن التبتل ويأمر بالزواج، ويقول: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالمشروع للشاب وللفتاة المبادرة بالزواج والحرص على الزواج كما أرشد إليه النبي عليه الصلاة والسلام وأمر به، وللمصالح التي سبق ذكرها، والجلوس بدون زواج فيه خطر عظيم، فلا يليق بالشاب وهو قادر أن يتأخر عن الزواج، ولا يليق بالفتاة أن تتأخر عن الزواج إذا خطبها الشخص المناسب، لكن إذا كان لها عذر لا تحب أن تبديه للناس فهي أعلم بنفسها، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12372/حكم-امتناع-المراة-عن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60416.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","حكم الزواج وأهميته"]},{"id":13966,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الإمارات العربية المتحدة وباعثها أحد الإخوة من هناك يقول: المرسل (م. س. س) من رأس الخيمة، أخونا تكلف كثيرًا حينما بعث رسالته بالبريد الممتاز، ويبدو أن الموضوع عاجل فبدأه يقول: بسم الله الرحمن الرحيم.إلى سماحة الشيخ عبد العزيز بن عبد الله بن باز .السلام عليكم ورحمة الله وبركاته.يا حضرة الشيخ! أنا أب لفتاة تقدم لخطبتها شاب أرتضي دينه وخلقه، وقد وافقت أمها وابنتي المخطوبة وإخوانها وجدها وجدتها من قبل الأم، وجميع الأهل إلا والدتي، وهي تعتبر جدة البنت من قبل الأب، هل أزوج ابنتي من هذا الشاب الذي ارتضيناه جميعًا؟ أم آخذ برأي والدتي؟ أفيدونا مأجورين جزاكم الله خيرًا.","title":"حكم تزويج الفتاة مع اعتراض جدتها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. أما بعد: فإن الواجب عليك وعلى جميع الأسرة المساعدة على تزويج الفتاة بالرجل الصالح المرضي في دينه وأخلاقه، ومن خالف في ذلك فلا يعتبر خلافه، سواء كان المخالف الجدة أو غيرها؛ لأن الرسول عليه الصلاة والسلام قال في الحديث الصحيح: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، ، قالوا: يا رسول الله! وكيف إذنها قال: أن تسكت متفق على صحته، وقال أيضًا عليه الصلاة والسلام: إذا خطب إليكم من ترضون دينه وخلقه؛ فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير، وفي لفظ آخر: وفساد عريض، هذا يدل على أن الواجب تزويج الكفء، وعدم رده إذا رضيت به المخطوبة، وما دامت رضيت والحمد لله وأنت ترضاه أيضًا؛ فهذا من نعم الله العظيمة، ونسأل الله للجميع التوفيق، ولا يجوز أن يعترض على ذلك بقول الجدة ولا غيرها. المقدم: جزاكم الله خيرًا سماحة الشيخ! كثيرًا ما يحدث مثل هذا في كثير من البيوت، تعضل البنت عن الزواج بسبب رأي أحد أفراد الأسرة؛ حبذا لو تفضلتم بتوجيه عام في هذا الموضوع. الشيخ: الواجب على الأسرة -وبالأخص على وليها-: أن يختار لها الرجل الصالح الطيب في دينه، والمرضي في خلقه، فإذا رضيت؛ وجب أن تزوج، ولا يجوز لأحد أن يعترض في ذلك لهوى في نفسه، أو لغرض آخر من الدنيا، أو لعداوة وشحناء، كل ذلك لا يجوز اعتباره، وإنما المعتبر كونه مرضيًا في دينه وأخلاقه، ولهذا قال النبي ﷺ في الحديث الصحيح في شأن المرأة: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ودينها، فاظفر بذات الدين تربت يداك، هكذا يقال في الرجل، سواء بسواء، الواجب الظفر بصاحب الدين، وإن أبى بعض الناس بعض الأسرة؛ لا يلتفت إليه. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ! راتب البنت ووظيفتها، أيضًا الحالة المادية والاجتماعية للخاطب، دراسة المخطوبة أيضًا؛ تكون أسبابًا أحيانًا في تأخير الزواج، توجيهكم لو تكرمتم. الشيخ: الواجب البدار بالزواج، ولا ينبغي أن يتأخر الشاب عن الزواج من أجل الدراسة ولا ينبغي أن تؤخر الفتاة عن الزواج للدراسة، فالزواج لا يمنع، فبالإمكان أن يتزوج الشاب ويحفظ دينه وخلقه، ويغض بصره، ومع هذا يستمر في الدراسة والحمد لله، وهكذا الفتاة: إذا يسر الله لها الكفء فينبغي البدار بالزواج وإن كانت في الدراسة، سواء كانت في الثانوية، أو في الدراسات العليا، كل ذلك لا يمنع. فالواجب البدار بالموافقة على الزواج إذا خطب الكفء، والدراسة لا تمنع من ذلك، ولو قطعت الدراسة فلا بأس، حتى ولو قطعت الدراسة، المهم أن تتعلم ما تعرف به دينها، والباقي فائدة، والزواج فيه مصالح كثيرة ولا سيما في هذا العصر، والترك فيه خطورة على الشاب وعلى الفتاة. فالواجب على كل شاب وعلى كل فتاة البدار بالزواج إذا تيسر الخاطب الكفء للمرأة، وإذا تيسرت المخطوبة الطيبة للشاب؛ فليبادر، عملاً بقول النبي الكريم عليه الصلاة والسلام في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم؛ فإنه له وجاء، متفق على صحته، وهذا يعم الشباب من الرجال، والفتيات من النساء، ليس خاصًا بالرجال، بل يعم الجميع، وكلهم في حاجة إلى الزواج، نسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا أفهم مما تفضلتم به شيخ عبد العزيز أن كل شيء عدا الزواج يعتبر من الباب الزائد. الشيخ: إذا تعلمت ما تعرف دينها، وتعلم هو كذلك ما يحصل به معرفة دينه؛ فالحمد لله، هذا إذا قدر أن الزوج يمنع، أما إذا كان لا يمنع، فالحمد لله. المقصود: أن الشاب يتعلم ما يفقه به دينه، والفتاة كذلك، ولا يمنع ذلك أن يتزوج الشاب، ولا يمنع من أن تزوج الفتاة، فإن استمر الشاب في الدراسة؛ فالحمد لله، وإن اشتغل بطلب الرزق ليقوم بحاله وحال زوجته فلا بأس، وفي إمكانه أن يتعلم خارج المدرسة، في المساجد وعلى العلماء، أو دراسة مسائية إذا تيسر ذلك، والفتاة كذلك إذا حصل لها تعلم ما لا يسعها جهله من دينها؛ فالحمد لله، لا تأخر عن الزواج، وربما تيسر لها الزواج مع الدراسة، وسمح لها الزوج بذلك، وربما تيسر لها دراسة خاصة مسائية في محل مأمون طيب يرضاه الزوج، وربما درست من طريق سماع (نور على الدرب) وأشباهه من المحاضرات والندوات التي تذاع، إذا تحرتها الفتاة في أوقاتها لقصد الفائدة؛ فإنها دروس عظيمة مفيدة، وهكذا للرجال: الكبار والصغار دروس مفيدة عظيمة، إذا اعتنوا بها في أوقاتها، من هذا البرنامج ومن غيره من الدراسات الإسلامية، نسأل الله للجميع الهداية والتوفيق. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12376/حكم-تزويج-الفتاة-مع-اعتراض-جدتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_605/60501.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","شروط وأركان الزواج"]},{"id":13969,"question":"في آخر أسئلة الأخ السائل من الجزائر يقول: ما هو أقل شيء يلزمني فعله ليكون نهاري في طاعة الله ؟","title":"كيف يقضي المسلم نهاره في طاعة الله؟","answer":"الجواب: عليك أن تحرص على أداء الواجبات، وأن تحفظ لسانك وجوارحك عن محارم الله؛ حتى تكون سعيدًا موفقًا، فتحرص على ما أوجب الله عليك من صلاة الفجر، ومن أداء حق أهل البيت من أولاد وزوجة، وحفظ جوارحك عما حرم الله من المعاصي في حق الله وفي حق عباده، وبهذا تكون ناجيًا سليمًا، وهكذا في الليل تحرص على أن تحفظ أوقاتك من سائر المعاصي، وأن تأمرها بالطاعات، وأن تؤدي ما أوجب الله عليك من صلاة وغيرها، هذا هو طريق النجاة .. هذا هو طريق السلامة؛ الحرص على حفظ الوقت مما حرم الله، وعلى حفظه بأداء ما أوجب الله، وعلى شغله بالأعمال الطيبة من الاستغفار والذكر وقراءة القرآن وسائر وجوه الخير، مع أداء واجب أهل البيت وحقهم من النفقة والمعاشرة الطيبة، وحق الجيران من إكرامهم والإحسان إليهم وكف الأذى عنهم.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12391/كيف-يقضي-المسلم-نهاره-في-طاعة-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53905.mp3","categories":["نصائح وتوجيهات"]},{"id":14027,"question":"رسالة وصلت إلى البرنامج من السودان أيضًا وباعثها مستمع من هناك يقول: المسلم الحائر (م. أ. أ) من وادي حلفا، أخونا يقول: ما هو السبيل في عدم الشعور بإتقان الصلاة والخشوع فيها حيث أنني أقوم إمامًا لأهل الحي في الصلوات الخمس ولله الحمد، ولكن كل محاولاتي لحفظ القرآن وتجويد القراءة أثناء الصلاة أشعر بأنني أرائي الناس فيها خاصة الصلوات الجهرية، حيث أنني أحسن من الصوت وإطالة القراءة حتى يخيل إلي أنني أفعل ذلك من أجل إشعار الناس بأنني أهل للإمامة، ما حكم ذلك؟ ثم إذا كان هذا دأبي فهل تصح صلاتي؟ وهل بإمكاني التخلي عن إمامة الناس في الصلاة مع أنني أكثر من التعوذ من الرياء أثناء السجود وأدعو الله كثيرًا في سجودي أن يجعل عملي وصلاتي خالصة لوجه الله تعالى، ماذا تنصحونني سماحة الشيخ؟ جزاكم الله خيرًا، وبارك فيكم.","title":"توجيه لمن يشعر بالرياء أثناء صلاته بالناس","answer":"الجواب: عليك -يا أخي- أن تستمر بعملك هذا من سؤال الله التوفيق للإخلاص والحرص على التعوذ بالله من الرياء وأبشر بالخير، ودع عنك الوساوس التي يمليها الشيطان بأنك تقصد الرياء وتحسين صوتك لأجل مدح الناس أو ليقولوا: إنك أهل للإمامة، دع عنك هذه الوساوس وأبشر بالخير. وأنت مأمور بتحسين الصوت في القراءة حتى ينتفع بك المأمومون ولا عليك شيء مما يخطر من هذه الوساوس بل حاربها، حاربها بالتعوذ بالله من الشيطان وسؤال الله التوفيق والهداية والإعانة على الخير وأنت على خير عظيم واستمر في الإمامة وأحسن إلى إخوانك واجتهد في تحسين الصوت، فقد جاء الحديث عن رسول الله عليه الصلاة والسلام أنه قال: ليس منا من لم يتغن بالقرآن ويجهر به، يعني: يحسن صوته بالقراءة؛ لأن تحسين الصوت بالقراءة من أعظم الأسباب للتدبر والتعقل والفهم للمعنى والتلذذ بسماع القرآن، وفي الحديث الصحيح يقول النبي ﷺ: ما أذن الله لشيء ما أذن لنبي حسن الصوت بالقرآن يجهر به يعني: ما استمع سبحانه لشيء كاستماعه لنبي وهو استماعًا يليق بالله لا يشابه صفات المخلوقين فإن صفات الله  تليق به سبحانه لا يشابه فيها خلقه جل وعلا كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ[الشورى:11].  ولكن يدلنا هذا على أنه سبحانه يحب تحسين الصوت بالقراءة، ويحب أن القراء يجتهدون في تحسين أصواتهم حتى ينتفعوا وحتى ينتفع من يستمع لقراءتهم، وما يخطر ببالك من الرياء فهو من الشيطان فلا تلتفت إلى ذلك وحارب عدو الله بالاستعاذة بالله منه والاستمرار في تحسين صوتك وإحسان قراءتك مع الخشوع بخضوعك وسجودك وسائر أحوال الصلاة وأنت على خير إن شاء الله، ونسأل الله لك التوفيق والثبات على الحق.\nالمقدم: اللهم آمين. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12452/توجيه-لمن-يشعر-بالرياء-اثناء-صلاته-بالناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61203.mp3","categories":["نصائح وتوجيهات"]},{"id":14028,"question":"من سوريا هذه رسالة بعث بها مستمع من هناك يقول: أحمد محمد حبوس سوري الجنسية يسأل ويقول: لقد تركت بلدي مسقط رأسي وذهبت إلى بلد آخر يبعد عن مسقط رأسي عشرين كيلو متر، وهناك والدتي رفضت أن تأتي معي وهي غاضبة ولن ترضى إلا إذا رجعت، أي: عدت إلى بلدي، وأنا أرى إقامتي في البلد الحالي لي به صلاح لذريتي وأنا خائف من غضب السيدة الوالدة، أرجو توجيهي، جزاكم الله خيرًا.","title":"هل يلزم البقاء في البلد طاعة للأم مع تضرر الأولاد؟","answer":"الجواب: إذا كانت إقامتك في البلد الأخير أصلح لدينك وأصلح لذريتك فالزم ذلك ولا حرج عليك، إذا كانت إقامتك في بلد أمك تضرك أو تضر ذريتك لما فيها من الفساد الكثير والشر العظيم فأنت مأجور وأنت على خير، والزم المحل الذي فيه الخير والصلاح، ولا يضرك غضبها عليك، وعليك ببذل الأسباب في التماس رضاها، وشرح حالك لها وبيان الأسباب باللطف والكلام الطيب والعبارات الحسنة حتى ترضى عنك إن شاء الله، وقد قال النبي عليه الصلاة والسلام: من التمس رضا الله بسخط الناس رضي الله عنه وأرضى عنه الناس، وفي اللفظ الآخر: من التمس رضا الله بسخط الناس كفاه الله مئونة الناس. فأنت يا أخي التمس رضا الله واستقم واصبر وعليك بالكلام الطيب مع الوالدة والإحسان إليها والتماس رضاها بالأسلوب الحسن وشرح الأحوال التي أوجبت لك هذا الانتقال وهي إن شاء الله ترضى عنك، والله جل وعلا هو الموفق الهادي . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12454/هل-يلزم-البقاء-في-البلد-طاعة-للام-مع-تضرر-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61204.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14029,"question":"من سوريا هذه رسالة بعث بها مستمع من هناك يقول: أحمد محمد حبوس سوري الجنسية يسأل ويقول: لقد تركت بلدي مسقط رأسي وذهبت إلى بلد آخر يبعد عن مسقط رأسي عشرين كيلو متر، وهناك والدتي رفضت أن تأتي معي وهي غاضبة ولن ترضى إلا إذا رجعت، أي: عدت إلى بلدي، وأنا أرى إقامتي في البلد الحالي لي به صلاح لذريتي وأنا خائف من غضب السيدة الوالدة، أرجو توجيهي، جزاكم الله خيرًا.","title":"هل يلزم البقاء في البلد طاعة للأم مع تضرر الأولاد؟","answer":"الجواب: إذا كانت إقامتك في البلد الأخير أصلح لدينك وأصلح لذريتك فالزم ذلك ولا حرج عليك، إذا كانت إقامتك في بلد أمك تضرك أو تضر ذريتك لما فيها من الفساد الكثير والشر العظيم فأنت مأجور وأنت على خير، والزم المحل الذي فيه الخير والصلاح، ولا يضرك غضبها عليك، وعليك ببذل الأسباب في التماس رضاها، وشرح حالك لها وبيان الأسباب باللطف والكلام الطيب والعبارات الحسنة حتى ترضى عنك إن شاء الله، وقد قال النبي عليه الصلاة والسلام: من التمس رضا الله بسخط الناس رضي الله عنه وأرضى عنه الناس، وفي اللفظ الآخر: من التمس رضا الله بسخط الناس كفاه الله مئونة الناس. فأنت يا أخي التمس رضا الله واستقم واصبر وعليك بالكلام الطيب مع الوالدة والإحسان إليها والتماس رضاها بالأسلوب الحسن وشرح الأحوال التي أوجبت لك هذا الانتقال وهي إن شاء الله ترضى عنك، والله جل وعلا هو الموفق الهادي . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12454/هل-يلزم-البقاء-في-البلد-طاعة-للام-مع-تضرر-الاولاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_612/61204.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14049,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع أحمد محمد علي سوداني وعمره خمس وعشرون سنة وعنوانه في العراق، أخونا له بعض الأسئلة، فيسأل في أحد أسئلته عن حكم تزوج الرجل المسلم بامرأة مسيحية، ويرجو التفصيل من سماحة الشيخ.","title":"حكم زواج المسلم بالمسيحية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد بين الله  في كتابه الكريم في سورة المائدة حل الزواج من محصنات أهل الكتاب، كما قال جل وعلا في كتابه العظيم: الْيَوْمَ أُحِلَّ لَكُمُ الطَّيِّبَاتُ وَطَعَامُ الَّذِينَ أُوتُوا الْكِتَابَ حِلٌّ لَكُمْ وَطَعَامُكُمْ حِلٌّ لَهُمْ وَالْمُحْصَنَاتُ مِنَ الْمُؤْمِنَاتِ وَالْمُحْصَنَاتُ مِنَ الَّذِينَ أُوتُوا الْكِتَابَ مِنْ قَبْلِكُمْ إِذَا آتَيْتُمُوهُنَّ أُجُورَهُنَّ مُحْصِنِينَ غَيْرَ مُسَافِحِينَ وَلا مُتَّخِذِي أَخْدَانٍ[المائدة:5].  فأباح سبحانه المحصنات من أهل الكتاب وهم اليهود والنصارى، والمحصنة: هي العفيفة، الحرة العفيفة هي المحصنة، فإذا كانت معروفة بالعفة والبعد عن الفواحش فإنه يجوز للمسلم نكاحها، أما إذا كانت لا تعرف بذلك فلا يحل نكاحها، أو معروفة بالفحش والفساد فلا يجوز نكاحها، وإن كانت كافرة لكنها مستثناة، المحصنة من اليهود والنصارى مستثناة من المسلمين إذا كانت محصنة، والمحصنة - كما تقدم - الحرة العفيفة التي لا يعرف عنها تعاطي الفواحش يعني: الزنا، فهي محصنة عفيفة بعيدة عن تعاطي الفواحش وإن كانت على دينها على دين النصرانية، ولكن نكاح المسلمات أولى وأفضل وأحق وأحسن وأبعد عن الشر ولاسيما المسلمات المعروفات بالديانة والاستقامة فإن زواجهن أفضل بكثير وأولى بكثير وأبعد عن الخطر.\nفنصيحتي لإخواني جميعًا الحرص على الزواج من المسلمات الطيبات وعدم الزواج من المحصنات من أهل الكتاب؛ لأن في ذلك خطرًا من جهة تنصير أولاده ومن جهة عدم عفتها أيضًا ولو تظاهرت بخلاف ذلك، نسأل الله للجميع العافية والسلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، سماحة الشيخ في حالة وقوع ذلك بم تنصحون الزوج؟\nالشيخ: إذا كانت محصنة ولا رأى منها إلا الخير فلا بأس بذلك، فلا بأس ببقائها، وأما إن شك فيها أو رأى منها ما يريبه فينبغي له طلاقها.\nكذلك إذا تيسرت له امرأة صالحة مسلمة فإن الأولى والأحق به أن يتزوجها ويطلق تلك حرصًا على سلامة دينه ودين أولاده، فإن الأولاد على خطر من ذهابهم مع أمهم عند أقل خلاف أو عند موت الزوج أو عند الفرقة بينه وبينها فالخطر قائم، ولا حول ولا قوة إلا بالله.\nالمقدم: الله المستعان، جزاكم الله خيرًا، كأن الحدود ضيقة في إباحة الزواج بغير .... ؟\nالشيخ: نعم نعم، ولهذا كره بعض الصحابة ذلك، كان عمر يكره ذلك ويرغب الصحابة في ترك ذلك رضي الله عن الجميع. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12479/حكم-زواج-المسلم-بالمسيحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_613/61301.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":14065,"question":"المستمع أنيس يحيى من مدينة الدوادمي بعث يسأل ويشكو من سوء معاملة أبيه، فهو يقول: إن له أخًا أكبر منه، وقد زوجه أبوه وأعطاه سيارة لكنه لم يفعل به مثل ما فعل بأخيه رغم نصح الناس له، ثم إنه أعطاه قطعة أرض فتصرف فيها وباعها، وسلم الثمن للوالد، ثم طلب والده ثمن تلك الأرض فأبى أن يعطيه، ويسأل سماحة الشيخ كيف يتصرف؟ وهل إذا ذهب إلى المحكمة هل يكون آثمًا؟ وجهوه ووجهوا والده جزاكم الله خيرًا.","title":"ما حكم عطية بعض الأولاد دون الآخرين؟","answer":"الجواب: الواجب على الوالد أن يعدل، ولا يجوز أن يخص بعض الأولاد بعطية أو زيادة على بقية الأولاد هذا لا يجوز؛ لأن الرسول عليه السلام قال: اتقوا الله واعدلوا بين أولادكم، هذا كلام المصطفى عليه الصلاة والسلام، اتقوا الله واعدلوا بين أولادكم، ولما جاءه بشير بن سعد الأنصاري  وذكر له أنه أعطى ابنه النعمان غلامًا، قال له النبي ﷺ: أعطيت ولدك كلهم مثله؟ ، قال: لا، قال: رده، اتقوا الله واعدلوا بين أولادكم، فليس له أن يعطي بعضهم سيارة أو مالًا أو أرضًا ولا يعطي الآخرين لا، بل إما أن يسوي بينهم في العطاء وإما أن يرجع في عطيته، هذا هو الواجب عليه. وأنت أيها الولد! لو توسطت بعض الطيبين من الأقارب أو غيرهم حتى يصلحوا بينك وبين الوالد يكون هذا حسنًا إن شاء الله، أحسن من الذهاب إلى المحكمة، إن تيسر من يشير على والدك وينصحه حتى يلتزم بالحق، وحتى يعدل فهذا حسن، وهذا أولى من المخاصمة، فإن أبى فلك أن تخاصمه إلى المحكمة، لك أن تخاصمه لأجل أنه قد ظلم، ولا بد من تعديل من جار عن الطريق، لا بد أن يعدل ويلزم بالحق من طريق المحكمة، وإن سمحت أنت ولم تخاصمه فأنت مأجور، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12487/ما-حكم-عطية-بعض-الاولاد-دون-الاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48406.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية"]},{"id":14082,"question":"شخص يصلي وينقطع مرارًا عنها وهذا حاله، ما هي نصيحتكم له؟","title":"ما النصيحة لمن يصلي أحيانا ويترك أحيانًا؟","answer":"الجواب: الواجب على كل مسلم ومسلمة تقوى الله في كل شيء، والصلاة عمود الإسلام وهي أعظم الفرائض وأهم الفرائض بعد الشهادتين، فالواجب على كل مسلم وعلى كل مسلمة العناية بالصلاة والمحافظة عليها كما قال الله : حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلاةِ الْوُسْطَى[البقرة:238]، وقال تعالى: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ[البقرة:43]، وقال سبحانه: وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَأَطِيعُوا الرَّسُولَ لَعَلَّكُمْ تُرْحَمُونَ[النور:56]، والصلاة أهم عمل وأعظم عمل بعد الشهادتين، من حفظها حفظ دينه، ومن ضيعها فهو لما سواها أضيع، والذي يفعلها تارة ويضيعها تارة كافر في أصح قولي العلماء -نسأل الله العافية- ولو ما جحد وجوبها، ولو لم يجحد وجوبها؛ لقول النبي ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر أخرجه الإمام أحمد وأهل السنن بإسناد صحيح عن بريدة  ابن الحصيب، ولقوله عليه الصلاة والسلام: بين الرجل وبين الكفر والشرك ترك الصلاة خرجه مسلم في صحيحه، ولأحاديث أخرى جاءت في الباب. فالواجب على المسلمين ذكورًا وإناثًا الحذر من التهاون بالصلاة والتساهل بها، والواجب المحافظة عليها في الوقت والعناية بها والطمأنينة والخشوع حتى تؤدى كما أمر الله.\nوعلى الرجل أن يحافظ عليها في الجماعة في مساجد الله مع إخوانه المسلمين، وأن يحذر من التشبه بالمنافقين الذين لا يؤدونها في الصلاة إلا رياء.. لا يؤدونها في الجماعة إلا رياءً، وإذا غابوا عن الناس تساهلوا بها وتركوها، يقول الله سبحانه: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى يُرَاءُونَ النَّاسَ وَلا يَذْكُرُونَ اللَّهَ إِلَّا قَلِيلًا  ۝  مُذَبْذَبِينَ بَيْنَ ذَلِكَ لا إِلَى هَؤُلاءِ وَلا إِلَى هَؤُلاءِ[النساء:142-143] أي: ليسوا مع المسلمين حقًا ولا مع الكفار حقًا، بل هكذا وهكذا مترددون في شكهم وريبهم وكفرهم وضلالهم، ويقول سبحانه: إِنَّ الْمُنَافِقِينَ فِي الدَّرْكِ الأَسْفَلِ مِنَ النَّارِ وَلَنْ تَجِدَ لَهُمْ نَصِيرًا[النساء:145] لكفرهم ونفاقهم وشكهم وريبهم وإبطانهم الكفر، فالوجب الحذر من صفاتهم والحذر من أخلاقهم الذميمة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12516/ما-النصيحة-لمن-يصلي-احيانا-ويترك-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61404.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14089,"question":"يقول: ألاحظ أن كثيرًا من الناس يحرص على وضع القرآن في السيارة، فهل توجهونهم بشيء؟","title":"توجيه لمن يضع المصحف في السيارة","answer":"الجواب: نعم، إذا كان وضع القرآن في السيارة للقراءة حتى يقرأ إذا تيسر له القراءة أو يقرأ من معه من الركاب، فهو مشكور يعينهم على طاعة الله وعلى قراءة كتاب الله، أما إذا كان عن اعتقاد أنه حرز وأنه ... القرآن حرز للسيارة من الانقلاب ومن الصدام هذا منكر لا يجوز ليس بحرز، ولكن إذا أراد بذلك أن يعين من ركب معه على القراءة، أو هو يقرأ إذا وقف للحاجة فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12518/توجيه-لمن-يضع-المصحف-في-السيارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48411.mp3","categories":["وقت الصلاة","نصائح وتوجيهات"]},{"id":14094,"question":"رسالة وصلت إلى البرنامج من الرياض وباعثها المستمع (م. عبد الله)، أخونا يقول: إنني تزوجت امرأة، وقد رزقني الله منها بولد، وأنا أفكر في طلاقها من ثاني أيام العرس، سبب ذلك أنني لم أحضر لخطبتها، والسبب الثاني: أنها كانت لا تصلي قبل الزواج، وبعد الزواج أمرتها تصلي فصلت، وعندما سافرت للعمل؛ قطعت الصلاة. سؤالي: هل إذا طلقتها أكون آثم؟ وهل إذا صبرت عليها أكون مأجور؟ وهل هذا ابتلاء من الله  لعباده بهذا النوع من النساء؟ نرجو أن تفيدونا حول هذه القضايا. جزاكم الله خيرًا.","title":"حكم طلاق الرجل للمرأة التي لا تصلي","answer":"الجواب: إذا كانت لا تصلي؛ فالنكاح غير صحيح، مادمت تصلي والحمد لله أنت، فهي لتركها الصلاة تعتبر كافرة في أصح قولي العلماء، ولو كانت تقر بالوجوب.\nفالواجب تجديد العقد إذا تابت إلى الله وأنابت إليه توبة صادقة، وأنت ترغب فيها، يجدد العقد، أما الآن فالواجب عليك فراقها، ما دامت تصلي إذا حضرت وتترك الصلاة إذا غبت؛ فهذه لا خير فيها، هذه فاسدة، عقيدتها فاسدة، وخوفها من الله معدوم أو ضعيف، تراعيك ولا تراعي حق الله! فهذه ينبغي فراقها وإبعادها، وأنت مأجور، بل واجب عليك طلاقها وإبعادها؛ لفساد دينها، بسبب تضييعها الصلاة. وقد ذهب جمع من أهل العلم من أئمة الحديث وغيرهم من المحققين إلى كفر تارك الصلاة كفرًا أكبر، ولو أقر بوجوبها، مع أن إقراره بوجوبها في الغالب لا يكون صحيحًا بل مجاملة، لو كان يقر بوجوبها إقرارًا صحيحًا لما تركها؛ لأن إقراره بالوجوب يدفعه إلى أن يصلي، ولكن عدم إقراره بالوجوب أو ضعف عقيدته في ذلك جرأته على تركها -نسأل الله العافية- وهكذا المرأة.\nفالواجب عليك وعلى أمثالك تطليق المرأة التي لا تصلي وإبعادها، ومتى تابت توبة صادقة وشهد لها بالخير؛ أمكنك أن تزوجها من جديد بعقد جديد، وهكذا المرأة التي عند زوج لا يصلي؛ تبتعد عنه، وتذهب إلى أهلها، ولا تبقى معه؛ لأنه متى ترك الصلاة كفر، وهذه مصيبة عظيمة اليوم وقعت في الناس.\nفالواجب على الرجل أن يبعد المرأة التي لا تصلي، وعلى المرأة أن تبتعد عن الرجل الذي لا يصلي، وأن تذهب إلى أهلها، حتى ولو كان معها أولاد، رزقهم على الله، وهي أحق بأولادها من هذا الزوج الذي لا يصلي، وعلى القاضي أن يجعل أولادها عندها، ويلزمه بنفقتهم، حتى يتوب إلى الله ويرجع إلى الله، ثم بعد ذلك يجدد العقد، إذا كان بعد خروجها من العدة، وإن كان تاب في العدة؛ فهي زوجته إذا كان حين الزواج يصلي وهي تصلي، أما البقاء مع زوج لا يصلي أو مع زوجة لا تصلي؛ فهذا لا يجوز، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12523/حكم-طلاق-الرجل-للمراة-التي-لا-تصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_610/61002.mp3","categories":["حكم الصلاة وأهميتها","الأنكحة المحرمة","مبطلات النكاح","نصائح وتوجيهات"]},{"id":14102,"question":"رسالة وصلت إلى البرنامج من الجمهورية التونسية وباعثها مستمع من هناك، يقول (ص. ح) أخونا صدر رسالته بثناء وتقدير على هذا البرنامج وعلى المشاركين فيه، وأخذ في أسئلته ليسأل ويقول: هل يجوز الأكل من ذبائح تارك الصلاة عمدًا؟ علمًا أنه إذا أخبر بذلك احتج بأنه ينطق بالشهادة، كيف العمل إذا لم يوجد أي جزار يصلي؟","title":"هل تحل ذبيحة تارك الصلاة؟","answer":"الجواب: الذي لا يصلي لا تؤكل ذبيحته، هذا هو الصواب، لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله عليه الصلاة والسلام: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر، وقوله ﷺ: رأس الأمر الإسلام وعموده الصلاة شيء ترك عموده هل يستقيم؟ وهل يبقى؟ متى ترك العمود سقط الفسطاط، فالذي لا يصلي لا دين له ولا تؤكل ذبيحته، وإذا كنت في بلد ليس فيها جزار مسلم فاذبح لنفسك واستعمل يدك فيما ينفعك أو التمس جزارًا مسلمًا ولو في بيتك حتى يذبح لك، وهذا بحمد الله ميسر، وليس لك أن تتساهل في الأمر، وعليك أن تنصح هذا الرجل وأن يتقي الله وأن يصلي. وقوله: إنه يكتفى بالشهادتين هذا غلط، الشهادتان لا بد من حقهما معهما، يقول النبي ﷺ: أمرت أن أقاتل الناس حتى يشهدوا أن لا إله إلا الله وأني رسول الله ويقيموا الصلاة ويؤتوا الزكاة، فإذا فعلوا ذلك عصموا مني دماءهم وأموالهم إلا بحق الإسلام وحسابهم على الله متفق على صحته، فذكر الصلاة والزكاة مع الشهادتين، وفي اللفظ الآخر قال: أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله فإذا قالوها عصموا مني دماءهم وأموالهم إلا بحقها وحسابهم على الله فالصلاة من حقها والزكاة من حقها.\nفالواجب على المؤمن أن يتقي الله، والواجب على كل من ينتسب للإسلام أن يتقي الله وأن يصلي الصلوات الخمس وأن يحافظ عليها، هي عمود الإسلام وهي الركن الأعظم من أركان الإسلام بعد الشهاتين فمن ضيعها ضيع دينه ومن تركها خرج من دينه نسأل الله العافية، هذا هو الحق والصواب. وقال بعض أهل العلم: إنه لا يكون كافرًا كفرًا أكبر بل يكون كفره كفرًا أصغر ويكون عاصيًا معصية عظيمة أعظم من الزنا وأعظم من السرقة وأعظم من شرب الخمر ولكنه لا يكون كافرًا كفرًا أكبر، هكذا قال جمع من أهل العلم، ولكن الصواب ما دل عليه قول الرسول ﷺ أن مثل هذا يكون كافر كفرًا أكبر؛ لأنه ضيع عمود الإسلام وهو الصلاة، فلا ينبغي التساهل في هذا الأمر، وقال عبد الله بن شقيق العقيلي التابعي الجليل : لم يكن أصحاب النبي ﷺ يرون شيئًا تركه كفر إلا الصلاة، فذكر إجماع الصحابة على أن تاركها كافر، نسأل الله العافية.\nفالواجب الحذر، والواجب المحافظة على هذه الفريضة العظيمة وعدم التساهل مع من تركها، فلا يؤكل طعامه ولا تؤكل ذبيحته ولا يدعى للوليمة، ولا تجاب دعوته بل يهجر حتى يتوب إلى الله وحتى يصلي، نسأل الله الهداية للجميع.\nالمقدم: جزاكم الله خيرًا، شيخ عبد العزيز! لا شك أنكم تفضلتم بإبداء بعض ما يجب أن يكون عليه المسلمون تجاه تارك الصلاة وهو ذلكم الذي يدعي الإسلام، هل من زيادة على هذا يا شيخ عبد العزيز ؟\nالشيخ: لعل هذا يكفي، يكفينا أنه كافر، نسأل الله العافية، بنص الرسول ﷺ، وهل بعد الكفر ذنب؟! ما بعد الكفر شيء، أعظم الذنوب الكفر بالله ، نسأل الله العافية.\nالمقدم: اللهم آمين. لكن ماذا على من يعرفه في هذه الصفة؟\nالشيخ: عليه أن ينصح له وعليه أن يهجره إذا لم يقبل النصيحة، فلا يجيب دعوته لو دعاه، ولا يدعوه إلى وليمة، ولا يسلم عليه إذا لقيه، ويحذر الناس من شره حتى يتوب إلى الله. نعم.","link":"https://binbaz.org.sa/fatwas/12535/هل-تحل-ذبيحة-تارك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61409.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14113,"question":"رسالة وصلت إلى البرنامج من زبيد في الجمهورية العربية اليمنية باعثها مستمع من هناك هو محمد يحيى مداد، رسالته يقول فيها: أعيش في منزل ليس فيه سوى والدي وزوجتي وطفلان صغيران، وفي إحدى المرات أمرني والدي بأن أذهب لأصلي الفجر في المسجد لكن زوجتي استحلفتني بالله ألا أخرج من البيت إلا بعد مجيء والدي من المسجد خوفًا من بقائها وحدها، وعندما عاد والدي وسألني عن سبب عدم ذهابي إلى المسجد أخبرته، فاستحلفني بالله ألا أذهب إلى المسجد وأن أصلي في البيت، فأخبرته بأن صلاة المسجد أفضل من صلاة المنزل، وأن الرسول ﷺ قال: لا صلاة لجار المسجد إلا في المسجد، ومع هذا أصر علي بأن أصلي في البيت، وإنني إذا خرجت سوف لن يسمح لي بدخوله مرة أخرى، فأطعته امتثالًا لأمره، أفتوني في هذا جزاكم الله خيرًا، ولاسيما وأن الزوجة تشكو دائمًا من بقائها وحدها في المنزل؟","title":"حكم صلاة الرجل في المنزل خوفًا من بقاء امرأته وحدها","answer":"الجواب: إذا كان على زوجتك خطر وهي غير آمنة؛ لأن حولها من يخشى منه فلك عذر أن تصلي في البيت خوفًا على زوجتك، أما إذا كان المحل آمنًا ولا شبهة فيما ذكرته الزوجة وإنما هو تساهل منها فصل في المسجد وأطع والدك، بل أطع الله قبل والدك، فعليك أن تصلي في المسجد مع المسلمين، يقول النبي ﷺ: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، وقد سأله رجل أعمى فقال: «يا رسول الله! ليس لي قائد يلائمني للمسجد فهل لي من رخصة أن أصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب رواه مسلم في الصحيح. فالرسول ﷺ أمر أعمى ليس له قائد يلائمه أن يصلي في المسجد ولم يعذره، فأنت أولى وأولى، ولا تلزم طاعة الوالد في خلاف الشرع؛ لأن الرسول يقول عليه الصلاة والسلام: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق، لكن إذا كانت الزوجة غير آمنة والمحل غير آمن والخطر موجود فلا بأس هذا عذر شرعي. أما حديث: لا صلاة لجار المسجد إلا في المسجد فهذا حديث ضعيف ليس محفوظ عن النبي ﷺ وإنما هو مشهور عن علي ، ولكن صح عن النبي ﷺ ما يغني عن ذلك وهما الحديثان السابقان: من سمع النداء فلم يأت فلا صلاة له إلا من عذر، حديث أبي هريرة في قصة الأعمى الذي تقدم ذكره قال له النبي ﷺ: أجب فهذان الحديثان الصحيحان يغنيان عن حديث: لا صلاة لجار المسجد إلا في المسجد.\nوالمقصود أن الواجب على المسلمين من الرجال أن يصلوا في المساجد وأن يكثروا سواد المسلمين، وأن يخرجوا إلى المسجد وألا يتشبهوا بالمنافقين، يقول ابن مسعود : \"لقد رأيتنا وما يتخلف عنها -  يعني: في البيت - إلا منافق معلوم النفاق\". وقد هم النبي ﷺ أن يحرق على من تخلف بيته. فالواجب عليك وعلى كل مسلم قادر أن يصلي في المسجد، وليس له أن يصلي في بيته إلا من عذر شرعي كالمرض والخوف، رزق الله الجميع الهداية والتوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12546/حكم-صلاة-الرجل-في-المنزل-خوفا-من-بقاء-امراته-وحدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61411.mp3","categories":["نصائح وتوجيهات","صلاة الجماعة"]},{"id":14119,"question":"شيخ عبد العزيز! من المؤسف أن بعض أولياء الأمور يتهاونون في مسائل تعد من الأهمية بمكان وذلك كالتقوى.. كالصلاة.. كإقامة شعائر الإسلام بينما يتمسكون بأمور ربما أن لسماحتكم فيها وجهة نظر كأن تكون البنت مخطوبة لابن عمها والواقع أن الأمر ليس كذلك، بل يقولون: هي موقوفة لابن عمها ولا يجوز لأحد أن يتزوجها من الخارج، توجيهكم حول هذا الأمر شيخ عبد العزيز.","title":"توجيه لمن يتساهل بأمور الدين في الزواج ويتمسك بالأعراف","answer":"الجواب: التساهل بأمور الدين خطير، ولا يجوز للأولياء التساهل بأمور الدين، وإنما يقع التساهل من بعض الناس لضعف دينه وضعف إيمانه وقلة تقواه، فلهذا يتساهل في أمور الدين ويشدد في أمور أخرى عرفية بين جماعته وقبيلته، وهذا من ضعف الإيمان كأن يقول: إن بنتي تبقى لابن عمها، أو أختي تبقى لابن عمها، هذا غلط، يجب أن تزوج بالرجل الصالح وإن كان من قبيلة أخرى ومن قوم آخرين، ولا يجوز حبسها لابن عمها ولا تجبر على ابن عمها ولو كان صالحًا، لا تجبر عليه، إنما تزوج بإذنها، قال عليه الصلاة والسلام: لا تنكح الأيم حتى تستأمر، ولا تنكح البكر حتى تستأذن، قالوا: يا رسول الله! كيف إذنها؟ قال: أن تسكت متفق على صحته، وقال عليه الصلاة والسلام: البكر يستأذنها أبوها وإذنها صماتها. حتى الأب ليس له أن يجبرها على الصحيح، وليس له أن يقهرها ولو كانت بكرًا، فلا يجبر البكر ولا الثيب بل يجب أن يشاورها، فالثيب تنطق وتقول: نعم. والبكر يكفي سكوتها، ويختار لها وليها الرجل الصالح والخاطب الصالح ولو كان من غير قبيلتها حتى ولو كان غير قبلي غير عربي، ولو كان أعجميًا إذا كان ذا دين وذا خلق، قال الله : يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُمْ مِنْ ذَكَرٍ وَأُنثَى وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا إِنَّ أَكْرَمَكُمْ عِنْدَ اللَّهِ أَتْقَاكُمْ[الحجرات:13].\nوإذا كانت قبيلته لا ترضى بذلك أو يخشى من أذى في ذلك لا مانع يلتمس من قبيلتها أو من القبائل الأخرى العربية المعروفة، لكن يلتمس صاحب الدين يلتمس الأخيار، لا يقهرها على ابن عمها ولا يزوجها بمن لا ترضى، بل يجب أن يختار لها الطيب وأن ينصح لها ثم يشير عليها بما يرى ولا يجبرها ولا يلزمها ولو بقيت عانسة، هذا إليها هذا حقها، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12564/توجيه-لمن-يتساهل-بامور-الدين-في-الزواج-ويتمسك-بالاعراف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61503.mp3","categories":["نصائح وتوجيهات","الزواج وأحكامه"]},{"id":14122,"question":"هذا السائل سلطان العمر من المدينة النبوية يقول: زوجة صالحة ذات صلاة وعبادة، ولكنها ذات خلق سيئ حيث ترفع كثيرًا من صوتها على زوجها وأبنائها، تنظر إلى الأمور نظرة سوداوية متشائمة، وتحمل الأمور ما لم تتحمل، هل من كلمة توجهونها إلى مثل ذلك عبر الأثير؟ فلعلها تستمع إلى ما تقولون يا سماحة الشيخ، وحيث أنها أيضًا تستمع إلى برامج إذاعة القرآن الكريم.","title":"وجوب الحذر من سوء الظن","answer":"الجواب: بسم الله الرحمن الرحيم. الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فنوصي المرأة المذكورة وأشباهها بتقوى الله جل وعلا، والعناية بحسن الظن، ومراعاة الأساليب الحسنة، والبعد عن سوء الظن لا بأولادها ولا بغيرهم، يقول الله جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا اجْتَنِبُوا كَثِيرًا مِنَ الظَّنِّ إِنَّ بَعْضَ الظَّنِّ إِثْمٌ [الحجرات:12]، ويقول النبي ﷺ: إياكم والظن فإن الظن أكذب الحديث.\nفالواجب على كل مسلم -رجل أو امرأة- الواجب الحذر من سوء الظن إلا بأسباب واضحة، وإلا فالواجب ترك الظن السيئ، لا بالمرأة ولا بالزوج ولا بالأولاد ولا بأخي الزوج ولا بأبيه.. ولا بغير ذلك، الواجب حسن الظن بالله، وحسن الظن بأخيك المسلم أو بأختك المسلمة، وأن لا تسيء الظن إلا بأسباب واضحة توجب التهمة، وإلا فالأصل البراءة والسلامة، وسوء الظن يسبب الفرقة والاختلاف والشحناء والعداوة، حتى الرجل مع أولاده إذا ساء ظنه بهم والمرأة مع أولادها إذا ساء ظنها بهم ساءت الحال بينهم، فالواجب الحذر من ذلك، والواجب العناية بحسن الظن مادام هناك مجال لحسن الظن، أما إذا وجد، وجدت أسباب تقتضي سوء الظن فلا بأس، كاجتماعه بمن يساء بهم الظن، وكوقوفه مواقف التهم.\nالمقصود متى وجدت أمور واضحة تقتضي سوء الظن فلا بأس، ولهذا إذا قامت البينة عمل بها وأسيء الظن بمن قامت عليه البينة بأنه سرق أو بأنه زنى أو بأنه شرب الخمر، فإذا قامت البينة الشرعية أقيم عليه الحد وأسيء به الظن بسبب البينة، أما عند عدم البينات فالواجب ترك سوء الظن والاعتماد على البراءة الأصلية والسلامة الأصلية والحذر من سوء الظن بالمسلم بغير حق، نسأل الله للجميع الهداية. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12559/وجوب-الحذر-من-سوء-الظن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52501.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات"]},{"id":14157,"question":"هذه السائلة أم خالد لها مجموعة من الأسئلة تذكر بأنها مدرسة لمادة الدين، وأحيانًا تقول: أطلب من التلميذة الإجابة على السؤال وأطلب الدليل من القرآن والسنة، ويكون لفظ الطالبة للآية خطأ، هل أعطي الطالبة الدرجة الكاملة حتى وإن كان لفظها للآية خطأ؟","title":"حكم إعطاء الدرجة كاملة لمن يلحن في قراءة الآية","answer":"الجواب: هذا العمل طيب، المطالبة بالأدلة الشرعية والسؤال عن أمور الدين هذا تلقين طيب للطالبات حتى يعتدن ذلك، وأنت مأجورة في هذا الخير العظيم، وإذا غلطت في الآية ما يضر تعطى الدرجة التي فهمتها وعرفتها بالدليل والخطأ يعدل، إذا لحنت في الآية أو شبه ذلك لا يضر لا يمنعها من أخذ الدرجة.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12598/حكم-اعطاء-الدرجة-كاملة-لمن-يلحن-في-قراءة-الاية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54620.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":14193,"question":"هذا سائل للبرنامج يقول: سماحة الشيخ! أب رفض الزواج لابنته حتى بلغ عمرها أربعين سنة رغم خطبتها من شباب معروفين منذ ثمانية عشر سنة ولم يزوجها حتى بلغت ما يقارب من ثلاثة وأربعين سنة، بعد هذا العمر زوجها؟","title":"حكم تأخير الولي زواج موليته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الأب الذي فعل هذا الفعل ظالم لبنته وعليه خطر من عقوبة الله له، إذا كان خطبها بعض الأكفاء ولم يزوجه لا يجوز للمسلم أن يعضل بنته ولا أخته ولا غيرهما من مولياته بل يجب أن يسارع إلى تزويجها إذا خطبها الكفء؛ لقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير ولأنها أمانة فالواجب عليه أداء الأمانة، هذه أمانة في ذمته يجب البدار إلى أداء الأمانة بتزويجها على من خطبها من الأكفاء والمسارعة في ذلك، ولأن تركها بدون تزويج من وسائل الشر ووسائل الفساد، ولأنه من الظلم. فالواجب على من فعل هذا التوبة إلى الله والحذر من العود إلى مثل ذلك مع غيرها، والواجب على الأولياء جميعًا أن يتقوا الله في مولياتهم وأن يزوجوهن متى جاء الكفء حتى ولو بالخطبة لهن، عمر  خطب لابنته حفصة، عرضها على الصديق وعرضها على عثمان ثم خطبها النبي ﷺ وتزوجها، فالولي يكون عنده النصح عنده المحبة لتزويج مولياته، لما في هذا من عفتهن وتيسير وجود من يكفلهن ولعل الله يرزقهن بعض الأولاد.\nفالحاصل أن حبس المرأة وعدم تزويجها مع وجود الأكفاء الخاطبين ظلم عظيم يستحق صاحبه العقوبة ويستحق التأديب من ولي الأمر، فوصيتي لجميع الأولياء أن يتقوا الله في مولياتهم وأن يبادروا ويسارعوا إلى تزويج المولية إذا خطبها الكفء سواء بنتًا أو أختًا أو بنت أخ أو بنت عم الواجب البدار بالتزويج إذا جاء الكفء وعدم التعطيل. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12646/حكم-تاخير-الولي-زواج-موليته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54801.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":14202,"question":"للأخ (س. ع. م. ل) من الحبشة سؤال آخر يقول فيه: إنني كثيرًا ما أندفع للدعوة إلى الله  لكنني ألاحظ على نفسي عدم الامتثال لكل ما أقول وهذا يجعلني في حيرة وقلق، فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"توجيه لمن يدعو إلى الله ولا يطبق كل ما يقول","answer":"الجواب: ننصحك أن تستعين بالله في الدعوة وفي العمل، وأن تجاهد نفسك حتى تعمل بما أوجب الله، وحتى تنتهي عما حرم الله، وحتى تكون من أسبق الناس إلى ما تدعو إليه من الخير، وحتى تكون من أبعد الناس عما تنهى عنه من الشر، حتى لا يحتج عليك من تدعوه إلى الله، وحتى لا يقول: لو كان هذا صادقًا لما خالف قوله عمله وعمله قوله، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آَمَنُوا لِمَ تَقُولُونَ مَا لا تَفْعَلُونَ  ۝  كَبُرَ مَقْتًا عِنْدَ اللَّهِ أَنْ تَقُولُوا مَا لا تَفْعَلُونَ[الصف:2، 3]، وينكر على بني إسرائيل ويقول لهم سبحانه: أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنْتُمْ تَتْلُونَ الْكِتَابَ أَفَلا تَعْقِلُونَ[البقرة:44]. فعليك يا أخي أن لا تجبن وأن لا تضعف عن الدعوة إذا كان عندك علم تدعو إلى الله على حسب علمك وبصيرتك، وعليك أن تحذر القول على الله بغير علم، عليك أن تتفقه في الدين، وأن تتبصر، وأن تدعو إلى الله على بصيرة كما قال سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108]. فإذا كان عندك علم فادع إلى الله على حسب العلم الذي عندك من كتاب الله وسنة رسوله عليه الصلاة والسلام. وعليك أن تسأل أهل العلم المعروفين بالخير والفضل والبصيرة عما أشكل عليك، وأن تجتهد في تدبر كتاب الله والإكثار من قراءته، وهكذا السنة تجتهد في حفظ ما تيسر منها وتتعقل مراد النبي ﷺ، وتذاكر أهل العلم في ذلك حتى تكون على بينة. وعليك مع ذلك أن تعمل بما أوجب الله عليك، وأن تحذر ما حرم الله عليك، عليك أن لا تكون كالفتيلة يضيء للناس ويحرق نفسه، اتق الله لا تضئ للناس وتحرق نفسك، ولكن أضئ للناس ونور للناس واعمل بطاعة ربك واحذر معصيته . جعلنا الله وإياك من الهداة المهتدين. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12662/توجيه-لمن-يدعو-الى-الله-ولا-يطبق-كل-ما-يقول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_616/61604.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":14237,"question":"أختنا تقول: أنا طالبة في الكلية ودائمًا لا نخرج منها إلا بعد الساعة الثانية وأكون منهكة وأحاول الصبر إلى أن تحين صلاة العصر، ثم المغرب وبعد ذلك أنام ولا أستيقظ إلا في الحادية عشرة ليلًا ثم أصلي العشاء، فهل علي إثم في تأخير صلاة العشاء إلى الحادي عشرة؟","title":"حكم النوم بعد المغرب وتأخير صلاة العشاء","answer":"الجواب: النوم بين المغرب والعشاء مكروه، كان النبي ﷺ يكره النوم قبلها والحديث بعدها، فينبغي الصبر حتى تصلي العشاء إذا غاب الشفق، ولكن لو أخرت العشاء وصليتيها قبل نصف الليل فلا بأس، فالمعول عليه نصف الليل لا بد أن تصليها قبل نصف الليل والليل يختلف، فلا بد أن تصلي العشاء قبل نصف الليل ولكن يكره لك النوم بين المغرب والعشاء إذا استطعت ذلك، وإذا استرحت بين العصر وبين المغرب، بين صلاة العصر وبين المغرب كان أولى من النوم بعد المغرب؛ لأن النوم بعد المغرب مكروه «كان النبي ﷺ يكره النوم قبلها والحديث بعدها» يعني بعد العشاء لكن لو استرحت ونمت بعد العصر، بعد صلاة العصر وقبل المغرب كان هذا أولى من النوم بعد المغرب حتى تصلي المغرب والعشاء في أوقاتهما. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12696/حكم-النوم-بعد-المغرب-وتاخير-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61706.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":14240,"question":"أختنا تقول: أنا طالبة في الكلية ودائمًا لا نخرج منها إلا بعد الساعة الثانية وأكون منهكة وأحاول الصبر إلى أن تحين صلاة العصر، ثم المغرب وبعد ذلك أنام ولا أستيقظ إلا في الحادية عشرة ليلًا ثم أصلي العشاء، فهل علي إثم في تأخير صلاة العشاء إلى الحادي عشرة؟","title":"حكم النوم بعد المغرب وتأخير صلاة العشاء","answer":"الجواب: النوم بين المغرب والعشاء مكروه، كان النبي ﷺ يكره النوم قبلها والحديث بعدها، فينبغي الصبر حتى تصلي العشاء إذا غاب الشفق، ولكن لو أخرت العشاء وصليتيها قبل نصف الليل فلا بأس، فالمعول عليه نصف الليل لا بد أن تصليها قبل نصف الليل والليل يختلف، فلا بد أن تصلي العشاء قبل نصف الليل ولكن يكره لك النوم بين المغرب والعشاء إذا استطعت ذلك، وإذا استرحت بين العصر وبين المغرب، بين صلاة العصر وبين المغرب كان أولى من النوم بعد المغرب؛ لأن النوم بعد المغرب مكروه «كان النبي ﷺ يكره النوم قبلها والحديث بعدها» يعني بعد العشاء لكن لو استرحت ونمت بعد العصر، بعد صلاة العصر وقبل المغرب كان هذا أولى من النوم بعد المغرب حتى تصلي المغرب والعشاء في أوقاتهما. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12696/حكم-النوم-بعد-المغرب-وتاخير-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61706.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":14242,"question":"يقول هذا السائل: لي جدة لا تصلي وهي جاهلة لا تعرف تقرأ ولا تكتب، كيف أعلمها الصلاة وأعلمها الطهارة، فأنا ألاحظ عليها أنها لا تعرف حتى الطهارة الشرعية لجهلها، وضحوا لنا ذلك، وهل تبرأ ذمتنا؟","title":"حكم تعليم الجاهل كيفية الطهارة والصلاة وغيرهما","answer":"الجواب: علمها أنت، علمها أنت أو أحد أولادها أو غيركم، علموها كيف تصلي وكيف تتوضأ، العلم بالتعلم هذا واجب عليكم، إذا كانت جاهلة علموها، الله أخذ على من عنده علم أن يعلم، وهذا من برها أيضًا، فيجب عليكم تعليمها وإرشادها بالكلام الطيب والرفق والحلم لا بالشدة والعنف، بل عليكم الرفق بها وتعليمها وتوجيهها إلى الخير هذا شيء لازم لكم، نعم. الله المستعان.\nالمقدم: الله المستعان جزاكم الله خيرًا سماحة الشيخ! يتساهل الكثير من الناس حيث يرون أهلهم وذويهم يخطئون في العبادات، فكيف توجهون مثل هؤلاء يا سماحة الشيخ؟\nالشيخ: الواجب عليهم أن يعلموا جميع من تحت أيديهم، وألا يتساهلوا في هذا الأمر، يعلم بنته، ويعلم أخته، يعلم جدته وأمه، يعلم خالته، يعلم جميع من تحت يده، حتى الخدم الذي عنده يعلمهم ويرشدهم إلى الحق، الله أخذ على أهل العلم أن يعلموا، كل من كان عنده علم عليه العهد والميثاق أن يعلم ويتقي الله، ولو كان ليس بعالم لكن يعلم مما علمه الله، فهو يعرف الصلاة ويعرف كيفيتها .... يعلم الناس يعلم بنته وأخته وجدته وأمه، يعرف أن الغيبة حرام يعلمهم أن هذا لا يجوز، يعرف أن الزنا حرام يعلمهم أن الزنا محرم، يعرف أن المسكر حرام فيعلمهم أنه محرم، وهكذا يعلمهم مما علمه الله؛ لأن ..... قسمان: قسم يحتاج إلى أهل العلم لأنه يخفى دليله، وقسم لا يحتاج إلى أهل العلم بل هو واضح، الصلاة واضحة يعرفها الخاص والعام من أهل الإسلام الذين تعلموا وتبصروا، تحريم الخمر، تحريم الزنا، تحريم العقوق للوالدين أو أحدهما، وهكذا، نعم الشيء الواضح يعلمه واللي ما هو بواضح يسأل أهل العلم ثم يعلم أهل بيته.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12707/حكم-تعليم-الجاهل-كيفية-الطهارة-والصلاة-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53018.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14260,"question":"يسأل أخونا أيضًا ويقول: أنا من أسرة نشأت بينها وبين أسرة عمي خلاف قديم لا أعلم سببه، سوى أنهم يقولون بسبب الورث، وفشلت كل المحاولات للتوفيق والصلح بينهم، وحيث أن الظروف جمعت بيني وبين ابن عمي الأصغر في المدرسة وفي فصل واحد كما أننا نسكن بشارع واحد أيضًا فأصبحنا أصدقاء رغم الخلافات العائلية بين الأسرتين، ولكن سرعان ما تأثر ابن عمي بأسرته وتغير من ناحيتي خصوصًا بعد إتمام المرحلة التعليمية لدرجة أنه يقابلني كأننا لم نعرف بعض ولم يكلمني، ورغم تداخل أصدقائنا للصلح بيننا فما يلبث أن يعود مرة ثانية للمقاطعة، وقد وسطت أهل الخير ولكن دون جدوى، وعندما يئست منه تركته وحتى الآن لم أكلمه، أرجو أن تفيدوني أفادكم الله عن حكم الدين في هذا الخصام حتى لا أكون ارتكبت ذنبًا بمقاطعته، جزاكم الله خيرًا.","title":"توجيه لمن يحرص على صلة قرابته وهم يقاطعونه","answer":"الجواب: قد أحسنت فيما فعلت؛ لأنك حاولت صلة الرحم، فقد أحسنت جزاك الله خيرًا، ونوصيك بالمحاولة والحرص على صلة الرحم مع ابن عمك وبني عمك وعمك إن كان موجودًا ولو كرهوا ذلك، فأنت تفعل ما تستطيع من السلام عليهم وزيارتهم إذا مرضوا، والدعاء لهم بالخير والهداية ومواساة فقيرهم وأنت على خير، لقول النبي ﷺ في الحديث الصحيح: ليس الواصل بالمكافئ وإنما الواصل الذي إذا قطعت رحمه وصلها رواه البخاري في الصحيح، وقوله ﷺ لما سأله رجل قال: يا رسول الله! إن لي قرابة أصلهم ويقطعونني وأحسن إليهم ويسيئون إلي وأحلم عنهم ويجهلون علي، فقال له النبي ﷺ: لئن كنت كما قلت لكأنما تسفهم المل ولا يزال معك من الله ظهير عليهم ما دمت على ذلك.\nفأنت يا أخي على خير، احرص على الصلة والإحسان مهما استطعت، وإذا لم تنجح فالإثم عليهم، وأنت لك أجر، والإثم على من امتنع، وأنت لك أجر في المحاولة وتوسيط من ترى من الأخيار والمشورة على أهلك وعلى أهل عمك بترك الشحناء، فالمال أمره سهل، والدنيا أمرها كلها سهل، فينبغي للمؤمن أن يتحرى ما يرضي الله ويقرب لديه، وأن يدع الشحناء والقطيعة والمال الذي فات يخلفه الله بأفضل منه، وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى [القصص:60]، هذا الذي ينبغي لك ولغيرك من المسلمين مع قراباتهم، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12772/توجيه-لمن-يحرص-على-صلة-قرابته-وهم-يقاطعونه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62113.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14265,"question":"رسالة وصلت إلى البرنامج من المستمع وحيد خليفي مصطفى عنيو مصري ومقيم في المملكة، أخونا له جمع من الأسئلة في أحد أسئلته يقول: أرجو أن تفيدوني أفادكم الله عن الطريقة المثلى والسهلة التي يمكن أن تحبب إلينا القرآن وتجعلني أحفظه بأسرع وقت، وكيف أبدأ، كما أريد حفظ الأحاديث فهل أبدأ أولًا بحفظ القرآن الكريم؟ أم أبدأ بحفظ الاثنين معًا، وما هي الكتب التي تشتمل على الأحاديث الصحيحة؟","title":"كيفية حفظ القرآن والكتب التي ينصح بحفظها","answer":"الجواب: حفظ القرآن من أفضل القربات والطاعات، وهكذا حفظ ما تيسر من السنة الصحيحة من أفضل القربات والطاعات، والأفضل أن تبدأ بحفظ ما تيسر من القرآن وأنت مخير إن شئت بدأت بالمفصل ق وَالْقُرْآنِ الْمَجِيدِ [ق:1]، وما بعدها حتى تكمل تحفظ الأجزاء الأخيرة الأربعة، وإن شئت بدأت بالبقرة ورتبت لك جزءًا معلومًا كل ليلة أو كل صباح صفحة صفحتين ثلاث صفحات ترتب شيئًا معلومًا وتستمر عليه، تسأل ربك العون والتوفيق، وتتحرى الأوقات المناسبة التي ليس فيها مشاغل.\nوإذا جمعت بين الأمرين وجعلت وقتًا لحفظ ما تيسر من القرآن، ووقتًا لحفظ ما تيسر من السنة فهذا حسن؛ لأن حفظ القرآن قد يطول وتطول مدته، فإذا جمعت بين هذا وهذا فهذا شيء طيب.\nونوصيك بحفظ عمدة الحديث للشيخ عبد الغني بن عبد الواحد المقدسي فإنها أحاديث صحيحة ومختصرة، أربعمائة حديث وزيادة يسيرة، فإذا حفظت هذا الكتاب فهو كتاب جيد عظيم مفيد، وإن كان عندك قدرة على حفظ بلوغ المرام للحافظ ابن حجر فهو كتاب أيضًا محرر وجيد، وفيه بعض الأحاديث ضعيفة التي بينها المؤلف رحمه الله. ونوصيك أيضًا بحفظ بعض كتب العقيدة، مثل: كتاب التوحيد، وثلاثة الأصول، وكشف الشبهات للإمام العلامة شيخ الإسلام في زمانه محمد بن عبد الوهاب رحمه الله فهي كتب مفيدة في العقيدة، ومثل: كتاب العقيدة الواسطية لشيخ الإسلام ابن تيمية، ولمعة الاعتقاد للموفق بن قدامة رحمه الله، وهذه كتب جيدة في العقيدة نوصي بحفظها أيضًا؛ لأنها مفيدة وكلها مأخوذة من كتاب الله العظيم وسنة رسوله الأمين عليه الصلاة والسلام، فهي كتب مفيدة مختصرة في العقيدة. نعم.\nالمقدم: جزاكم الله خيرًا، يسأل عن الكتب التي تشتمل على الأحاديث الصحيحة شيخ عبد العزيز؟\nالشيخ: ذكرنا عمدة الحديث كلها من الصحيحين من البخاري ومسلم سوى أفراد قليلة من أحدهما، فالعمدة للشيخ عبد الغني بن عبد الواحد بن سرور المقدسي هي في الحقيقة كتاب مفيد جدًا، سماها العمدة لما فيها من الأحاديث الصحيحة، فإذا حفظها طالب العلم أو حفظتها طالبة العلم فذلك مناسب جدًا، وإن تيسر مع هذا حفظ بلوغ المرام فهو كتاب أوسع ومحرر وفيه علم جم، وفيه أحاديث يسيرة ضعيفة قد بينها المؤلف رحمه الله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12768/كيفية-حفظ-القران-والكتب-التي-ينصح-بحفظها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62112.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14270,"question":"أخونا يقول: إني طالب في معهد وأبلغ الآن واحدًا وعشرين عامًا، وقد منَّ الله علي بنعمة الإيمان والحمد لله قررت أن أكفر عما كنت عليه بأن أتزهد وأستغفر الله، ما هو أحسن طريق ترشدوني إليه؟ جزاكم الله خيرًا.","title":"وصايا لحديث عهد بتوبة","answer":"الجواب: نرشدك إلى لزوم التوبة عما سلف من سيئاتك، أن تلزم التوبة بالندم عما مضى من سيئاتك، والاستقامة على طاعة الله ورسوله والعزم الصادق أن لا تعود إلى الذنوب والمعاصي، ونوصيك بالإكثار من قراءة كتاب الله القرآن وتدبر معانيه، والإكثار أيضًا من حفظ الحديث النبوي مثل: بلوغ المرام للحافظ ابن حجر، وعمدة الحديث للحافظ عبد الغني المقدسي، الأربعين النووية وتتمتها لابن رجب هذه كتب مفيدة ونافعة، كتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله، العقيدة الواسطية لشيخ الإسلام ابن تيمية، كشف الشبهات للشيخ محمد بن عبد الوهاب رحمه الله، هذه كتب عظيمة ومفيدة تنفعك فنوصيك بها وبأمثالها، ومراجعة كتاب زاد المعاد في هدي خير العباد لابن القيم كتاب مفيد عظيم الفائدة، فتح المجيد شرح كتاب التوحيد كذلك كتاب عظيم في العقيدة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12731/وصايا-لحديث-عهد-بتوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61714.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14273,"question":"السائل (ح. أ. أ) يقول: يذكر بأنه شاب موظف في إحدى الشركات ويحفظ من كتاب الله كثيرًا والحمد لله، يقول: ما بقي لي إلا جزءًا وكنت أحفظ نصف صفحة في اليوم تقريبًا، ومشكلتي الآن: إذا بدأت بالحفظ أو المراجعة يأتيني نوم ولا أستطيع أن أملك نفسي عن النوم، ولي أكثر من شهرين في سورة الصافات، ما نصيحتكم لي يا سماحة الشيخ؟","title":"نصيحة لمن يأتيه النوم عند حفظ القرآن","answer":"الجواب: نصيحتي لك أنك تسأل ربك أن يعينك، تضرع إليه جل وعلا أن الله يعينك على حفظه وأن يعيذك من الشيطان وأن يمنحك النشاط والقوة، مع أني أنصحك أيضًا أن تنظر في الأوقات المناسبة، تتحرى الأوقات المناسبة التي أنت فيها نشيط، بعد صلاة الفجر بعد صلاة العشاء، في أي وقت ترى نفسك نشيطًا تقرأ فيه، مع التعوذ بالله من الشيطان؛ لأن الشيطان حريص على تكسيل الإنسان عن عمل الخير، فقد يكون يأتي بأسباب النوم، تعوذ بالله من الشيطان الرجيم، تسأل ربك العون والتوفيق، وتلتمس الأوقات المناسبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12728/نصيحة-لمن-ياتيه-النوم-عند-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54912.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14283,"question":"من سوريا صلاح من حلب يقول: حين أقوم لأداء الصلاة فرضًا أتثاءب كثيرًا وأحاول منع هذا التثاؤب ولم أستطع، وأشرد أيضًا في الصلاة في كثير من الأوقات أنسى كم صليت، فأرجو منكم هدايتي إلى طريق الخلاص من هذا التقصير، وجزاكم الله خيرًا.","title":"توجيه لمن يغلبه التثاؤب في الصلاة","answer":"الجواب: هذا من الشيطان وعليك أن تستعيذ بالله من الشيطان، وأن تجتهد في أسباب النشاط، سؤال الله.. التعوذ بالله من الشيطان الرجيم، وتقرأ ما تيسر من القرآن ولا تطول ... التطويل الذي يشق عليك ويأتي بالنعاس، وتسأل ربك أن يعينك وأن يوفقك وأن يمنحك النشاط والقوة؛ لأن الشيطان عدو للعبد يكسله ويشككه ويوهمه ويوسوس عليه، فلابد من الجهاد، لابد من جهاد النفس وجهاد الشيطان، فجهاد النفس بأسباب النشاط من الوضوء وتعاطي ما ينشط من وضوء وقهوة.. الشيء الذي ينشط على قيام الليل، ولابد من التعوذ بالله من الشيطان عند الوساوس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12745/توجيه-لمن-يغلبه-التثاوب-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54919.mp3","categories":["مكروهات الصلاة","نصائح وتوجيهات"]},{"id":14285,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع (م. ج. محمد عبد السيد) مصري ومقيم في المملكة، أخونا له قضية يقول فيها: إذا حفظ إنسان علمًا من علوم الدين لكي يقوم بدوره في القرية التي يسكنها، وحفظ القرآن لكي يصلي بالشباب صلاة قيام رمضان في اليوم بجزء، هل يكون هناك شيء من الشرك الأصغر؟ مع العلم أنني عندما كنت في قريتي أقوم بالخطبة والوعظ في القرى المجاورة، وأصلي بالشباب صلاة القيام بالمصحف، وأريد من ذلك أن أتوسع في العلوم ولكي أستغني عن المصحف في القراءة، أرجو توجيهي، جزاكم الله خيرًا.","title":"توجيه لمن يدعو إلى الله ويصلي بالناس ويخاف الرياء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فمن المعلوم بالأدلة الشرعية أن طلب العلم والتفقه في الدين من أفضل القربات، ومن أفضل الطاعات، وهكذا دراسة القرآن الكريم والعناية بالإكثار من تلاوته، والحرص على حفظه أو ما تيسر منه، كل ذلك من أفضل القربات، وإذا قمت بما ينبغي من تعليم أهل قريتك وتوجيههم والصلاة بهم، والصلاة بالشباب وغيرهم من أهل القرية في رمضان فكل هذا عمل صالح تشكر عليه وتؤجر عليه، وليس ذلك من الرياء وليس من الشرك، إذا كان قصدك وجه الله والدار الآخرة ولم ترد رياء الناس ولا حمدهم ولا ثناءهم، وإنما أردت بذلك أن تنفعهم وأن تتزود من العلم والفقه في الدين، وإنما يكون شركًا أصغر إذا فعلت ذلك رياءً للناس وطلبًا لثنائهم، كما قال النبي الكريم عليه الصلاة والسلام: أخوف ما أخاف عليكم الشرك الأصغر، فسئل عنه؟ فقال: الرياء يقول الله يوم القيامة للمرائين: اذهبوا إلى من كنتم تراءون في الدنيا فانظروا هل تجدون عندهم من جزاء.\nفالرياء: هو أن تعمل العمل من أجل رياء الناس حتى يشاهدوك ويثنوا عليك ويمدحوك، ومن ذلك: السمعة، كأن تقرأ ليثنوا عليك ويقولوا: إنه جيد القراءة، ويحسن القراءة، أو تكثر من ذكر الله ليثنوا عليك ويقولوا: إنه يكثر من الذكر، أو تأمر بالمعروف وتنهى عن منكر بقولك، لتمدح ويثنى عليك، هذا هو الرياء، وهذا هو الشرك الأصغر.\nفالواجب الحذر من ذلك وأن تعمل أعمالك لله وحده لا لأجل مراءاة الناس وحمدهم وثنائهم، ولكن تعلم إخوانك وتصلي بهم، ترجو ما عند الله من المثوبة، وتقصد بذلك نفعهم، لا رياءً ولا سمعة، وإذا قرأت من المصحف فلا بأس، كونك تصلي بإخوانك من المصحف في رمضان، كان مولى عائشة رضي الله عنها يصلي بها من المصحف.\nفالحاصل أنه لا بأس أن يقرأ المصلي القرآن من المصحف في قيام رمضان إذا كان لا يحفظ، وإن حفظه وقرأه عن ظهر قلب فهو أفضل وأحسن ولكن لا حرج في القراءة من المصحف عند الحاجة إلى ذلك، هذا هو الصواب، وفق الله الجميع لما يرضيه. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، فهمت جانبًا آخر سماحة الشيخ من رسالة أخينا هو أنه يريد الاستفادة من صلاته بالناس كقراءته للقرآن ومذاكرته، وأيضًا أن يكسب أجر إمامته للناس؟\nالشيخ: كل ذلك طيب، كونه يقصد نفعهم ويقصد الصلاة بهم وإعانتهم على الخير، ويقصد مع هذا أن يستفيد وأن يقوى حفظه للقرآن وأن تكثر معلوماته، كل هذا طيب، وكلها مقاصد حسنة ليس فيها رياء.\nالمقدم: ليس فيها رياء.\nالشيخ: نعم.\nالمقدم: وهذا هو المقصود، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12750/توجيه-لمن-يدعو-الى-الله-ويصلي-بالناس-ويخاف-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61801.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14327,"question":"شيخ: عبد العزيز ! لا أدري هناك أمر مطلوب من المسلم بخصوص الصلاة، وذلكم الأمر هو: أن تكون في جماعة، وأعني بالجماعة؛ جماعة المساجد، لعل لكم توجيه حول هذا..؟","title":"وجوب الاعتناء بصلاة الجماعة","answer":"الجواب: نعم، هذا من المهمات، يجب على الرجل أن يعتني بالجماعة وألا يصلي في بيته، لا الفجر ولا غيرها من الصلوات، بل يجب أن يحضر مع المسلمين وأن يصلي مع المسلمين، كما كان النبي ﷺ وأصحابه، وقد قال عليه الصلاة والسلام: من سمع النداء فلم يأت فلا صلاة له إلا من عذر قيل لابن عباس: «ما العذر؟ قال: خوف أو مرض» وجاءه رجل أعمى فقال: «يا رسول الله! ليس لي قائد يلائمني للمسجد، فهل لي من رخصة أن أصلي في بيتي؟ قال: هل تسمع النداء بالصلاة؟ قال: نعم. قال: فأجب ولم يرخص له مع أنه أعمى ليس له قائد يلائمه، لم يرخص له أن يتخلى عن الصلاة مع المسلمين في المساجد. وقد ثبت عنه ﷺ أنه: «همَّ أن يحرق على المتخلفين بيوتهم» وذلك يدل على أن الأمر عظيم، ولهذا قال عليه الصلاة والسلام: لقد هممت أن آمر بالصلاة فتقام ثم آمر رجلًا فيؤم الناس، ثم أنطلق برجال معهم حزم من حطب إلى رجال لا يشهدون الصلاة فأحرق عليهم بيوتهم وفي لفظ: إلى قوم لا يشهدون الصلاة فأحرق عليهم بيوتهم هذا يدل على أن الأمر عظيم، وأن المتخلفين جديرون بهذه العقوبة. فينبغي للمؤمن بل يجب عليه أن يحذر صفات المنافقين، وأن يبادر بالمحافظة على الصلاة في الجماعة في جميع الأوقات طاعة لله ورسوله، وحذرًا من غضب الله وعقابه. الله المستعان.\nالمقدم: جزاكم الله خيرًا، الله المستعان.","link":"https://binbaz.org.sa/fatwas/12802/وجوب-الاعتناء-بصلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_618/61810.mp3","categories":["نصائح وتوجيهات","صلاة الجماعة"]},{"id":14330,"question":"السائل (ج. س) من جمهورية مصر العربية شمال سيناء يقول: أنا شاب أبلغ من العمر الثامنة عشرة وأسكن أنا وأخي في بيت واحد، وأخي متزوج وأنا غير متزوج، وزوجة أخي تقوم بأعمال وأشغال البيت، وتقوم بخدمتنا، فهل يجوز لي أن أجالسها وأن أتحدث معها، وقد سألت البعض من الناس فقالوا: لا يجوز، وجهونا في ذلك؟","title":"حكم التحدث والخلوة بزوجة الأخ","answer":"الجواب: ليس لك الخلوة بزوجة أخيك، أما التحدث معها بحضور أخيك أو بحضور شخص آخر فلا بأس؛ لقول النبي ﷺ: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فليس لك أن تخلو بها وحدك ولكن مع أخيك أو مع أمها أو أختها أو خالتها أو أختك أو أمك أو نحوها لا بأس، تزول الخلوة ويزول المحذور. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12805/حكم-التحدث-والخلوة-بزوجة-الاخ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55013.mp3","categories":["النظر والخلوة والاختلاط","نصائح وتوجيهات"]},{"id":14331,"question":"هذا سائل للبرنامج عبد الحليم عثمان من الجمهورية اليمنية يقول في هذا  هل يجوز قراءة الفاتحة عقب كل صلاة على روح النبي ﷺ أم أن هذا بدعة؟ وكيف نعرف البدع يا سماحة الشيخ؟","title":"حكم قراءة الفاتحة بعد الصلاة على روح النبي ﷺ","answer":"الجواب: هذا بدعة، القراءة على روح النبي ﷺ من البدع ليس له أصل في الشرع، والبدعة: هي فعل شيء ما شرعه الله، هذه البدعة التعبد بشيء ما شرعه الله؛ لقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد يعني: فهو مردود، وقال أيضًا عليه الصلاة والسلام: من عمل عملًا ليس عليه أمرنا فهو رد، وقال عليه الصلاة والسلام: كل محدثة بدعة وكل بدعة ضلالة فالتعبد بشيء ما شرعه الله يسمى ضلالة.\nومن هذا القراءة للنبي ﷺ قراءة مخصوصة، أو مطلقة، هذا ما شرعه الله، لكن تصلي عليه تقول: اللهم صل على محمد وعلى آل محمد كما صليت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد كما باركت على إبراهيم وعلى آل إبراهيم إنك حميد مجيد، اللهم صل وسلم على نبينا محمد، اللهم صل وسلم على خاتم أنبيائك، اللهم صل وسلم على رسولنا محمد.. وما أشبه ذلك.\nوتقول: اللهم اجزه عنا خيرًا كما أحسن إلينا، تقول: اللهم صل على محمد وعلى أزواجه وذريته كما صليت على إبراهيم .. إلى آخره، هكذا، تكثر من الصلاة عليه، عليه الصلاة والسلام، وتدعو له وتثني عليه وتتبع سنته، تحرص على اتباع السنة والاستقامة على دينه والعمل بشرعه.\nأما القراءة له ما شرع الله القراءة له، لا تقرأ للنبي ﷺ، ولكن تصلي عليه وتسلم عليه وتدعو له، تقول: جزاه الله عنا خيرًا، وضاعف الله مثوبته وأكثر حسناته.. إلى غير هذا من الدعوات الطيبة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12806/حكم-قراءة-الفاتحة-بعد-الصلاة-على-روح-النبي-ﷺ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55014.mp3","categories":["البدع والمحدثات","العالم والمتعلم","نصائح وتوجيهات"]},{"id":14351,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع عبدالله حامد عبود، الأخ عبدالله عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة له سؤال طويل جدًا عن غلاء المهور، وهل يعتبر المهر الغالي بمثابة بيع البنت -كما يقول-؟يرجو التوجيه، جزاكم الله خيرًا.","title":"الحث على التيسير في المهور","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالشرع المطهر لم يحدد في المهر شيئًا معلومًا، بل أطلق للناس ما يتفقون عليه من المهور قليلةً أو كثيرة، لكن الشارع رغب في التقليل والتيسير ترغيبًا في النكاح، وعفة الرجال والنساء، ومن ذلك قوله : خير الصداق أيسره وكان زوج بناته على خمسمائة وتزوج على خمسمائة، ويروى أنه زوج بناته على أربعمائة. فالمقصود: أنه ﷺ كان يحث على تخفيف المهور وتيسيرها، ولم يغال فيها لا مع أزواجه ولا مع بناته -عليه الصلاة والسلام-، فالمشروع للمؤمن أن يخفف، وأن لا يتكلف في ذلك، ولكن الأوقات تختلف في الغلاء والرخص، وتيسر الحاجات، وعدم تيسرها، فيشرع لأهل الزواج أن يتفقوا على شيء مناسب ليس فيه إجحاف بالزوج، ولا مضرة على الزوج، ولا تعطيل للنساء والشباب، كل ما كان ذلك أيسر وأقل كان أفضل حتى يتيسر للجميع حصول النكاح؛ لقوله ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء. فالمؤمن يحرص على أن يقدم بنته وأخته وموليته بكل وسيلة شرعية حتى لا تتعطل، وحتى لا تتعرض للأخطار، والرجل كذلك يحرص على أن يتزوج، ويحرص أبوه وأخوه والقادر على تزويجه، والتعاون معه في ذلك حتى لا يتعرض لأخطار العزوبة، ولا سيما في هذا العصر الذي كثرت فيه الفتن، وكثر فيه المتبرجات من النساء.","link":"https://binbaz.org.sa/fatwas/12823/الحث-على-التيسير-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_620/62001.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":14353,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من ليبيا، المرز، وهي بتوقيع أحد المستمعين أو المستمعات من هناك تقول (ع. م) بدأت الرسالة كالتالي:بسم الله الرحمن الرحيم. الحمد لله، والصلاة والسلام على سيدنا محمد وعلى آله وصحبه أجمعين.إلى سماحة الشيخ الفاضل: عبدالعزيز بن عبدالله بن باز، لك جل احترامي وتقديري وإعزازي وإكباري لشخصك، وإني أخبرك بأني أحبك في الله، وأتمنى أن ألقاك، وأتعرف عليك إن وفقني الله في زيارة البيت الحرام، وباختصار فإني أعتبرك في ضميري، وأتمنى لك دوام الصحة والعافية، وأدعو الله أن يكثر من أمثالك: إني فتاه أبلغ من العمر إحدى وعشرين سنة، معلمة لمادة التربية الإسلامية، وسأكون لك شاكرة لو تفضلت بإسداء النصح لي لتعينني على مصاعب هذه الحياة، وكما أخبرتك في البداية بأنك تحل في نفسي محل الضمير، فإني لن أنسى نصيحتك لي مدى الحياة، ولدي بعض الأسئلة أرجو أن تنال منك التوضيح:أولًا: كيف يكون باستطاعة المسلم إبعاد وساوس الشيطان عنه، وبأي شيء يقاوم هذه الوساوس؟ هل بالدعاء أم بقراءة القرآن؟","title":"فضل الحب في الله ووصية للمربين والمربيات وعلاج الوسوسة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فجواب لك -أيها الأخت في الله- في محبتك لي في الله، أقول: أحبك الله الذي أحببتيني له، وأسأل الله أن يجعلنا وسائر إخواننا من المتحابين في جلاله، والمتواصين بالحق، والصبر عليه، فقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: سبعة يظلهم الله في ظله، يوم لا ظل إلا ظله: إمام عادل، وشاب نشأ في عبادة الله، ورجل قلبه معلق بالمساجد، ورجلان تحابا في الله، اجتمعا على ذلك، وتفرقا عليه، ورجل دعته امرأة ذات منصب وجمال فقال: إني أخاف الله، ورجل تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، ورجل ذكر الله خاليًا ففاضت عيناه هذا الحديث متفق على صحته. وذكر فيه: رجلين تحابا في الله اجتمعا على ذلك، وتفرقا عليه وأنهم من السبعة الذين يظلهم الله في ظله يوم لا ظل إلا ظله، وهذا تمثيل، وهو يشمل الرجلين والمرأتين، والرجل والمرأة، إذا كان الحب في الله -جل وعلا-، وفي طاعته . كذلك ذكر: رجل دعته امرأة ذات منصب وجمال، فقال: إني أخاف الله كذلك المرأة إذا دعاها ذو منصب وجمال فقالت: إني أخاف الله، تكون من السبعة الذين يظلهم الله في ظله، يوم لا ظل إلا ظله. وذكر منهم: من تصدق بصدقة فأخفاها حتى لا تعلم شماله ما تنفق يمينه، وهذا فيه الحث على إخفاء الصدقة وأن تكون سرًا بين العبد وبين ربه يرجو ثوابه، ويخشى عقابه، ولا شك أن ذلك أكمل في الإخلاص، وأبعد عن الرياء؛ ولأن بعض الفقراء يستحي أن يعطى والناس ينظرون، فإذا أعطاه أخوه في الله صدقة سرية كان أكمل في الإخلاص، وكان أرفق بالمعطى.\nكما أنه ذكر في السبعة: رجل قلبه معلق بالمساجد وهذا يدل على أن العناية بالمساجد، والمحافظة على الصلاة فيها من أهم المهمات، وأن من اعتنى بالمساجد، وحافظ على الصلاة فيها مع إخوانه في الله، هو من السبعة الذين يظلهم الله في ظله، يوم لا ظل إلا ظله.  وصح عن رسول الله -عليه الصلاة والسلام- أنه قال أيضًا: يقول الله يوم القيامة: أين المتحابون بجلالي؟ اليوم أظلهم في ظلي يوم لا ظل إلا ظلي. أما وصيتي لك: فإني أوصيك بتقوى الله؛ لأن التربية أمرها عظيم، فهي تربية الأجيال من الفتيات، وهكذا التربية للرجال هي من أهم المهمات، وهي أساس عظيم، إن كانت التربية صالحة نفعت المربي، وإن كانت سيئة ضرت المربى، فنوصيك بتقوى الله في ذلك، وأن تربي من لديك على طاعة الله ورسوله، على الحب في الله، والإخلاص لله، والاستقامة على دين الله، والمحبة في الله، والكراهة في الله، تربينهم على حب القرآن، والإكثار من تلاوة القرآن، وتدبر معانيه، تربينهم على حب السنة، سنة رسول الله ﷺ والحرص على التأسي بها، وأن اتباعه ﷺ من أسباب دخول الجنة، والنجاة من النار، ومن أسباب محبة الله للعبد، كما قال الله سبحانه: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ[آل عمران:31]. فمن أهم المهمات: تربية البنات وتربية البنين على حب الله ورسوله، والإخلاص لله في العمل، وتعظيم القرآن، والإكثار من تلاوته، تعظيم السنة سنة الرسول ﷺ، والتشجيع على حفظ ما تيسر منها؛ لأن هذا الدين مبني على الكتاب والسنة، فالإسلام هو ما دل عليه كتاب الله وسنة رسوله -عليه الصلاة والسلام-، من توحيد الله والإخلاص له، والشهادة بأنه لا إله إلا الله، أي: لا معبود حق إلا الله، والشهادة بأن محمدًا رسول الله، أرسله الله إلى الناس عامة للجن والإنس، وختم به المرسلين، فمن اتبعه واستقام على دينه فله الجنة والكرامة والسعادة في الدنيا والآخرة.\nومن أعظم التربية، التربية على حب الصلاة، وتعظيم الصلاة، والمحافظة عليها في أوقاتها من الرجال والنساء، فيربى الفتيات على حب الصلاة والمحافظة عليها في أوقاتها، والعناية بما شرع الله فيها، وهكذا المربي، الأستاذ يربي أطفاله وتلاميذه على تعظيم الصلاة وحبها، وأدائها في الجماعة، والمحافظة عليها، والخشوع فيها لله ، وهكذا يربى الصبي والفتاة كل منهما يربى على كثرة الذكر لله، والإكثار من تسبيح الله وتحميده، وتكبيره ودعاءه والاستغفار، يربى الطفل والطفلة على كثرة الذكر، كما قال الله سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا[الأحزاب:41] والنبي ﷺ يقول: سبق المفردون قيل: يا رسول الله، ما المفردون؟ قال: الذاكرون الله كثيرًا والذاكرات. فيربى الطفل والطفلة على كثرة ذكر الله، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير، سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده، سبحان الله العظيم.\nويربى على الضراعة إلى الله، وسؤال الله العافية، والتوفيق لما يحب ويرضى، مغفرة الذنوب، يربى الطفل والطفلة على الضراعة إلى الله في الدعاء، والحرص على دعائه -جل وعلا-، وطلب العافية منه، والسلامة وصلاح القلب والعمل، والتوفيق لكل ما يحبه ويرضاه .\nومن التربية حث الطالب والطالبة على حفظ الوقت، هذا من أعظم التربية أن يحفظ الوقت، وأن لا يضيع فيما لا ينفع، والطالب يحفظه في حفظ دروسه، في مراجعتها، في طاعة والديه وبر والديه، في التعاون مع أهل بيته في الخير، في ترك ما لا ينبغي من السب والشتم والكذب، أو صحبة الأشرار، أو التخلف عن الصلاة، أو ما أشبه ذلك، فالتربية على حفظ الوقت بطاعة الله، والإكثار من ذكره، وصحبة الطيبين، وبر الوالدين والتعاون مع أهل البيت في الخير والصلاح، هذا من المهمات. أما الوساوس فهي لا شك من الشيطان، كما قال -جل وعلا- في كتابه العظيم: قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ[الناس:1-4] وهو الشيطان.\nفهي من عدو الله، ودواؤها الاستعاذة بالله من الشيطان، هذا دواؤها، الاستعاذة صدقًا بالله، تقول: اللهم أعذني من الشيطان الرجيم، أعوذ بالله من الشيطان الرجيم، صادقًا مخلصًا لله، تعلم أنه هو الذي يعينك ، وهو القادر على أن يقيك شره، وهو القائل سبحانه: وَإِمَّا يَنزَغَنَّكَ مِنَ الشَّيْطَانِ نَزْغٌ فَاسْتَعِذْ بِاللَّهِ[الأعراف:200].\nفأوصيك بالاستعاذة بالله من الشيطان عند كل وسوسة، مع ذكر الله ، ومع استحضار أن هذا العدو لا يريد إلا إهلاكك، وإهلاك جميع المسلمين، فلا بد من الحذر منه غاية الحذر، وذلك بالتعوذ بالله منه، هو القادر  أن يعيذك ويعيذ غيرك منه، فأكثري من التعوذ بالله من الشيطان، مع الإكثار من ذكر الله سبحانه، وبذلك تسلمين من عدو الله ومكائده، وإذا عرض في الصلاة فلا مانع من أن تنفثي عن يسارك قائلة: أعوذ بالله من الشيطان -ثلاث مرات- أعوذ بالله من الشيطان الرجيم، كما «أوصى النبي ﷺ عثمان بن أبي العاص لما أخبره أن الشيطان لبس عليه صلاته، فأمره أن ينفث عن يساره ثلاث مرات، وأن يستعيذ بالله من الشيطان، قال عثمان: ففعلت، فسلمني الله من شره». فإذا كان يعرض في الصلاة فانفثي عن يسارك التفت يسيرًا، وانفثي عن يسارك قائلةً: أعوذ بالله من الشيطان الرجيم، ثلاث مرات، ويزول -إن شاء الله-.\nوبكل حال فعلاج هذا العدو هو اللجأ إلى الله الذي يملك كف شره، لا يملك كف شره سواه ، فاللجأ إلى الله في كف شر هذا العدو بالتعوذ بالله من الشيطان، وبالإكثار من ذكر الله ، وبطلبه سبحانه السلامة من مكائد هذا العدو، هذا هو الطريق، وهذا هو العلاج. والله المسؤول أن يوفقك لما في رضاه، وأن يعيذك من مكائد الشيطان، وأن يمنحك العلم النافع، والعمل الصالح، وأن يثبتنا وإياك وسائر إخواننا وأخواتنا في الله على الحق والهدى حتى نلقاه سبحانه، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12831/فضل-الحب-في-الله-ووصية-للمربين-والمربيات-وعلاج-الوسوسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_631/nour_63101.mp3","categories":["نصائح وتوجيهات"," الوسواس بأنواعه"]},{"id":14384,"question":"في آخر أسئلة هذا السائل يقول سماحة الشيخ: كيف يستطيع الإنسان أن يصلح من قلبه؛ وذلك من الآثام والمعاصي؟","title":"كيفية صيانة القلب من الآثام والمعاصي","answer":"الجواب: يسأل ربه التوفيق، ويجاهد، الله يقول: وَمَنْ جَاهَدَ فَإِنَّمَا يُجَاهِدُ لِنَفْسِهِ [العنكبوت:6] ويقول سبحانه: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69] فعليه أن يجاهد نفسه لله حتى يصونها عما حرم الله عليه، وعليه أن يسأل ربه التوفيق والإعانة، ويكثر من ذكر الله، ويبتعد عن جلساء السوء، فهذه من أسباب السلامة، كونه يخاف الله ويراقبه، ويتذكر أن المعاصي تسبب غضبه، وتسبب عذابه، ويجتهد في سؤاله والضراعة في أن يحفظه، وأن يصونه عما حرم الله عليه، ويكثر من قراءة القرآن، والتدبر لمعانيه، ويجتهد في مصاحبة الأخيار ومجالستهم، والبعد عن صحبة الأشرار، هذه من أسباب السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/12865/كيفية-صيانة-القلب-من-الاثام-والمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55207.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14391,"question":"إحدى المستمعات من الأردن، بعثت برسالة طويلة بعض الشيء، أستأذن سماحة الشيخ في قراءتها كاملة تقول:بسم الله الرحمن الرحيم، وبه نستعين.السلام عليكم ورحمة الله وبركاته، وبعد: تقول عن نفسها: أنا فتاة في الثانية والعشرين من عمري، أصبت بمرض نفسي ضيق علي الحياة من جميع أبوابها، وجعلني أشعر بيأس قاتل، يأس من الشفاء من هذا المرض، وهو انعدام الشخصية، فبعد تجربتي المريرة مع هذا المرض اكتشفت أن كل مصائب الدنيا أهون منه، فقد انفصلت عن الواقع الذي يعيشه الناس انفصالًا كاملًا، فأصبحت لا أحس بمشاعر الإنسانية التي يحسونها من فرح وحزن وسرور وحب وكره، فكيف تتصورون إنسانًا بدون مشاعر، وأنا دائمًا أعترف بأنني ظلمت نفسي إذ أوقعتها في هذا المرض، وضيعت شخصيتي لأسباب تافهة، لا داعي لذكرها. وسؤالي هو: إنني كثيرًا ما تنتابني حالات يأس كامل من الحياة، وهذا ليس مني، ولكن من شدة الألم النفسي الذي أعانيه من جراء هذا المرض القاتل، فهل هذا قنوط من رحمة الله أعاقب عليه؟ خاصة وأنني دائمًا أعترف بيني وبين نفسي أنني أنا الذي ظلمت نفسي، ودائماً أدعو الله العلي القدير أن يقدر لي الشفاء من هذا المرض، وحالة اليأس هذه تجعلني أفكر في الانتحار، لكن أرجع فأتعوذ بالله من الشيطان الرجيم، فهل أعاقب على هذا التفكير أم لا؟وجهوني، وانصحوني، وأخلصوا لي النصح، وادعوا لي، جزاكم الله خيرًا.","title":"نصيحة لفتاة مصابة بحالة نفسية","answer":"الجواب: أسأل الله لك الشفاء والعافية، وأسأل الله أن يمنحك الشفاء، وأن يعيذك من شر نفسك وشيطانك، الواجب عليك أيها الأخت في الله، وأيها الفتاة أن ترجعي إلى الله -جل وعلا-، وأن تتوبي من هذا العمل السيئ، وهذا الظن السيئ، وهذا الشعور السيئ، وعليك أن تستعيذي بالله من الشيطان، وأن تسألي الله أن يعينك على ذكره وشكره، وعلى القيام بحقه، وعلى المباعدة لهذه الظنون، وهذه المشاعر الرديئة، حتى يجيبك سبحانه ويعطيك من فضله ما ترجعين به إلى الحالة الطبيعية، اضرعي إلى الله بصدق، واسأليه أن يمنحك الشفاء في سجودك، وفي آخر الصلاة، وفي وسط الليل في آخر الليل، بعد الأذان قبل الصلاة، كل هذه أوقات عظيمة للإجابة، فلا تيأسي أبدًا، جالسي الأخيار من أخواتك أو عماتك، اجلسي مع الأخيار تحدثي معهم، جاهدي نفسك، وأكثري من التسبيح والتهليل والتحميد والتكبير والاستغفار، واضرعي إلى الله دائمًا بصدق أن يمنحك العافية. وإياك والانتحار، الانتحار من أعظم الجرائم، ومن أعظم الكبائر، ومن أسباب دخول النار، ولكن عليك بالصدق في الضراعة إلى الله، وسؤاله العافية والشفاء، واختلطي مع الطيبين والطيبات من أهلك، وتحدثي معهم، وشاوريهم، وخذي نصيحتهم، واسألي الله من فضله، اسأليه أن يمنحك الشفاء، واحذري اليأس لا تيأسي أبدًا، فضل الله واسع، وهو سبحانه القائل: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] وهو الجواد الكريم ، ومتى صدقت في ذلك فأبشري بالخير، وقولي أيضًا: أعوذ بكلمات الله التامات من شر ما خلق، أعوذ بكلمات الله التامة من كل شيطان وهامة، ومن كل عين لامة كثري هذا، كرري ثلاثًا، وأكثر صباحًا ومساء، دائمًا حتى يزول هذا البلاء، كذلك قولي: باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء، وهو السميع العليم ثلاث مرات، صباحًا ومساء كرريها، باسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم واقرئي آية الكرسي، اقرئيها بعد كل صلاة وعند النوم، فهي من أعظم الأسباب للعافية من كل سوء.\nوهكذا قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتان، اقرئيها كلها ثلاث مرات صباحًا ومساء، صباحًا بعد الفجر ومساء بعد المغرب، وعند النوم ثلاث مرات، وبعد الظهر والعصر والعشاء مرة واحدة، تقرئين هذه السور الثلاث، كل هذا من أسباب العافية والشفاء كما جاء عن رسول الله -عليه الصلاة والسلام-. فالحاصل: أن عليك حسن الظن بالله، والصدق مع الله، وسؤاله العافية والشفاء من هذا البلاء، وعليك أن تكثري من ذكر الله وتسبيحه وتهليله وتحميده والاستغفار والدعاء بطلب العافية، وعليك أن تجلسي مع الأخيار، مع الطيبات، من أهل بيتك للتحدث والأنس بهم والمشاورة والنصيحة، نسأل الله لك العافية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12874/نصيحة-لفتاة-مصابة-بحالة-نفسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48712.mp3","categories":["نصائح وتوجيهات"]},{"id":14393,"question":"ما هي الوسائل التي يمكن اتباعها لحفظ كتاب الله؟","title":"الوسائل المعينة على حفظ القرآن الكريم","answer":"الجواب: العناية بالحفظ والتكرار، والصبر في أوقات مناسبة من الليل والنهار، تكرر تأخذ شيئًا فشيئًا مع العناية وتكرار التلاوة، وتتحرى الأوقات المناسبة التي ما فيها شغل القلب، يكون القلب فارغًا، كذلك من أسباب الحفظ المدارسة مع الإخوان الطيبين، والتعاون مع الإخوان الطيبين، وأعظم من ذلك سؤال الله، والضراعة إليه، أن يعينك ويوفقك ويمنحك السداد، فكل هذا من أسباب الحفظ، فعليك أن تجتهد وتحرص على الرفيق الطيب، وعليك أن تسأل الله التوفيق والإعانة، وأبشر بالخير. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12875/الوساىل-المعينة-على-حفظ-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_488/48801.mp3","categories":["القرآن وعلومه","نصائح وتوجيهات"]},{"id":14396,"question":"هذا سائل للبرنامج السائلة (هـ .أ) الرياض، رمزت لاسمها بهذا الرمز، تقول: ما هي الأعمال والأقوال التي تعين على تثبيت الإيمان واليقين، والتي تبعد القلب عن القسوة، وعدم الطمأنينة والخشوع؟حيث أنني في بعض الأحيان أحس بلين وخشوع في القلب، وأحيانًا أحس بعكس ذلك، وجهوني سماحة الشيخ.","title":"الأعمال التي تعين على تثبيت الإيمان واليقين","answer":"الجواب: المشروع للمؤمن والمؤمنة الإكثار من ذكر الله، وقراءة القرآن، وسؤال الله التوفيق والهداية، وصلاح القلب، هذه التي تعين على صلاح القلوب وعلى عمارتها بذكر الله وخشوعها وسلامتها من الوساوس، فالإكثار من ذكر الله، ومن قراءة القرآن بالتدبر، وتذكر عظمة الله، وأنه سبحانه يحب من عباده أن يسألوه، وأن يذكروه، وأن يخافوه ويرجوه، هكذا المؤمن والمؤمنة، يستحضر عظمة الله، وأنه سبحانه هو الحكيم العليم، المستحق لأن يعبد، وأن يعظم ويذكر؛ فيكثر من ذكر الله، ومن قراءة القرآن، ومن الدعاء، يقول: اللهم أصلح قلبي، اللهم ارحمني، اللهم وفقني لما يرضيك، اللهم اهدني سواء السبيل، يجتهد في الدعاء مع ذكر الله، مع استحضار عظمة الله، والخوف من الله ، وصحبة الأخيار يحرص عليه، وصحبة الطيبين والطيبات، المرأة تحرص على صحبة الطيبات، والرجل يحرص على صحبة الطيبين الذين يعينونه على الخير، نعم.","link":"https://binbaz.org.sa/fatwas/12878/الاعمال-التي-تعين-على-تثبيت-الايمان-واليقين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55215.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14397,"question":"وصلتنا هذه الرسالة سماحة الشيخ من سائلات رمزن لاسمهن بهذا الرمز بنات (ع. ز) يقلن في هذه الرسالة: سماحة الشيخ عبدالعزيز بن عبدالله بن باز -حفظه الله-. السلام عليكم ورحمة الله وبركاته وبعد:نحن أخوات من مدينة سراة عبيدة في المنطقة الجنوبية، نسكن في الرياض، خريجات من الجامعة، تقدم لنا العديد من الخطاب، لكن أبانا هداه الله يرفض كل من يتقدم إلينا؛ وذلك لأسباب سخيفة وواهية، فمنها: بأنه ليس من نفس أهل المدينة، أي أنه من مدينة أخرى، نرجو من سماحة الشيخ -حفظه الله- النصح لهذا الأب ودلالته إلى الصواب، مأجورين.","title":"توجيه للآباء بتزويج بناتهم إذا خطبهن الأكفاء","answer":"الجواب: الواجب على أولياء النساء أن يتقوا الله، سواء كان أبًا أو عمًا أو أخًا أو ولدًا، الواجب أن يتقوا الله، وأن يزوجوا النساء إذا خطبهن الأكفاء، ولا يحبسوهن لا لطمع ولا لوظيفة، ولا لكون الرجل ليس من بلدهم، إذا جاء الكفء ولو كان من بلد أخرى، ولو كان من قبيلة أخرى، يقول الله -جل وعلا-: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] ويقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوا تكن فتنة في الأرض وفساد كبير ما قال: بشرط أن يكون من الجماعة أو من الحمولة، لا، ما هو بلزوم، ولو من قرية أخرى، ولو من قبيلة أخرى، المهم أن يكون صالحًا طيبًا. فالواجب على أولياء النساء أن يتقوا الله، وأن يسارعوا في تزويج مولياتهم من بنات أو أخوات أو بنات أخ أو غير ذلك، وأن يحذروا حبسهن وعضلهن لطمع في رواتبهن، أو لأسباب أخرى، فالواجب الحرص على تزويجهن بالرجل الطيب، والحذر من عضلهن وظلمهن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12879/توجيه-للاباء-بتزويج-بناتهم-اذا-خطبهن-الاكفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55216.mp3","categories":["نصائح وتوجيهات","الزواج وأحكامه"]},{"id":14400,"question":"السائل الذي رمز لاسمه بـ (ع. ع) من جمهورية مصر العربية، له مجموعة من الأسئلة، يقول في هذا  هل منع زوجتي عن زيارة بيت والدها يعتبر قطعًا لصلة الرحم؟","title":"حكم منع الرجل زوجته من زيارة أهلها","answer":"الجواب: منعها لا يجوز، لا بد من تنظيم لزيارة، لا تضرك، ولا يحصل بها قطيعة، الواجب تمكينها من زيارة أبيها وإخوتها لصلة الرحم، إلا إذا كانت الزيارة يترتب عليها فساد، إذا كان في بيت أبيها شر، أو أبوها ليس بطيب، زيارتها له تضرها، أو يدعوها إلى منكر فلا بأس أن تمنعها، أما إذا كان أبوها طيبًا وسليمًا، ولا يترتب على زيارتها ما يضرك ولا يضرها فلا تمنعها؛ لأن منعها من قطيعة الرحم، ومن العقوق، فلا ينبغي منك منعها. والمرأة عليها أن تصل أرحامها، وعليك أنت أن تمكنها من ذلك، فبقاؤها لديك وخدمتها لك حسب العرف، ومن عرف المسلمين أن المرأة تزور أباها، وتزور أمها، وتزور أقاربها، فليس لك أن تمنعها إلا إذا كانت الزيارة فيها شر، تضرها في دينها، أو تضرك فلا بأس أن تمنعها إذا كان أبوها فاسقًا تضرها زيارته، أو تضرك زيارته أو أخوها أو عمها، فإذا كان في الزيارة شر عليك أو شر عليها لا بأس أن تمنع، نعم.","link":"https://binbaz.org.sa/fatwas/12882/حكم-منع-الرجل-زوجته-من-زيارة-اهلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_552/55219.mp3","categories":["الحقوق الزوجية","نصائح وتوجيهات"]},{"id":14429,"question":"ما هي الصفات الواجب توفرها في الداعي المسلم لدعوة ملحد أو يهودي، أو نصراني، أي: هل باستطاعة أي مسلم أن يكون داعيًا إلى الله؟","title":"الصفات الواجب توافرها في الداعية","answer":"الجواب: ليس في استطاعة كل مسلم إلا بعد التعلم، الدعوة إلى الله تحتاج إلى علم، وتحتاج إلى لغة المخاطب أيضًا، والله يقول سبحانه: قُلْ هَذِهِ سَبِيلِي أَدْعُوا إِلَى اللَّهِ عَلَى بَصِيرَةٍ[يوسف:108] يعني: على علم، فمن أراد أن يدعو الناس إلى الله فليتعلم وليتفقه في الدين، وليعتني بالقرآن الكريم وتفسيره ومعرفة معانيه؛ وليحضر عند أهل العلم، يحضر حلقات العلم، يسأل أهل العلم عما أشكل عليه، حتى يصلح للدعوة، فإذا وجد من نفسه قوة على ذلك، واستشار من يطمئن إليه من أساتذته حتى يصلح للدعوة وحتى يوجهه إلى ما ينبغي، وحتى يشير عليه بما ينبغي أن يستعمل، فإذا وجد من نفسه القدرة؛ لأن عنده حصيلة من الأدلة الشرعية من الكتاب والسنة في أي موضوع من المواضيع التي يريد أن يدعو إليها، أو يناقش فيها فيتكلم، وإذا كانت لغة المدعو غير العربية فلا بد أن يستعين بمن يفهم اللغة من الثقات حتى يكون واسطة بينه وبينه في توجيه الخير، وإرشاده إلى الحق باللغة التي يفهمها، بواسطة من يعرف اللغة المذكورة من الثقات المعروفين بالعلم والفضل، وإذا كان الداعي يعرف اللغة، فهذا نعمة كبيرة، يدعو إلى الله باللغة التي يفهمها، ويعرفها المخاطب. وبكل حال فالصفات التي يجب توافرها في الداعي هي أن يكون عنده علم وعنده حلم وبصيرة حتى يدعو إلى الله على بينة وبرفق ولين، وبأسلوب يؤثر على المدعو، وأن يكون في نفسه صالحًا حتى لا يحتج عليه المدعو يقول: أنت تدعوني إلى كذا وأنت فاسد، تخالف أقوالك أعمالك، وأعمالك أقوالك، ينبغي له أن يكون حريصًا على أن يعمل بما يدعو إليه، وأن يحذر ما ينهى عنه، فالداعي يمثل دعوته بأفعاله وأخلاقه وسيرته مع الناس. وينبغي أيضًا أن تكون عنده حصيلة محفوظة من الأحاديث الصحيحة، ومن آثار السلف الصالح الذين قاموا بالدعوة حتى يتأسى بهم، مع كتاب الله  والعناية بحفظه وتدبر معانيه، والاستعانة بكلام أئمة التفسير المعروفين، بالعلم والفضل والعقيدة الصالحة، كالإمام ابن جرير والبغوي وابن كثير وغيرهم من أئمة التفسير الذين يستفاد من كلامهم في تفسير كلام الله . فالحاصل: أنه لا بد من بصيرة، ولا بد من أخلاق فاضلة، أن يكون ذا خلق كريم في حلمه وقوله وعمله وأساليبه حتى لا يجد المدعو ثغرة يدخل منها عليه لينتقصه أو ليهجن دعوته، ويقول: إنك لست كما تقول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12917/الصفات-الواجب-توافرها-في-الداعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_631/nour_63103.mp3","categories":["نصائح وتوجيهات","الدعوة والدعاة"]},{"id":14432,"question":"المستمع (س. س. غ) بعث بسؤال طويل ملخصه: أنه ارتكب معصية معينة، وعاهد الله أن يتوب منها، ثم إنه عاد، وهكذا يعاهد ويعود عددًا من المرات، والآن يستفسر سماحة الشيخ ويقول: ما العمل؟ وكيف يتم الإقلاع عن المعصية؟","title":"توجيه لمن عاهد الله ألا يعود للمعصية ثم عاد","answer":"الجواب: عليك أن تجاهد نفسك، وأن تراقب الله ، وأن تعلم أنه لك بالمرصاد، وأن التلاعب بمحارمه من أعظم أسباب غضبه عليك، وقد يكون من عقوباتك أن يطبع على قلبك، حتى لا ترجع إلى الحق -والعياذ بالله- بسبب تساهلك وتكرار المعصية، نسأل الله العافية. فالواجب عليك البدار بالتوبة الصادقة، والندم على الماضي، والعزم الصادق ألا تعود في ذلك، وعليك كفارة اليمين عما جرى منك من المعاهدة لربك، والأيمان أنك لا تعود، عليك أن تكفر كفارة اليمين عن ذلك، مع التوبة الصادقة والإنابة، وكافرة اليمين: إطعام عشرة مساكين، أو كسوتهم، لكل واحد نصف صاع من قوت البلد من تمر أو أرز أو غيرهما، فإن عجزت لفقرك ولم تستطع صمت ثلاثة أيام.\nوالواجب على كل حال الحرص التام على التوبة ولزومها، وخوف الله ومراقبته  حتى تقف عن هذه المعصية، نسأل الله لنا ولك الهداية، ولا حول ولا قوة إلا بالله، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12923/توجيه-لمن-عاهد-الله-الا-يعود-للمعصية-ثم-عاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62404.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14451,"question":"ما كيفية صلاة الاستخارة؟ وما هو دعاؤها؟ وفي أي وقت تصلى؟","title":"كيفية صلاة الاستخارة والدعاء الوارد فيها","answer":"الجواب: صلاة الاستخارة ركعتان، النبي ﷺ قال: إذا هم أحدكم بأمر فليصل ركعتين، ثم ليقل: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه باسمه يقول: هذا الأمر، زواجي بفلانة، أو سفري إلى محل كذا، أو شراء كذا، أو ما أشبه ذلك، يعين حاجته اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري، فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه، وقدر لي الخير حيث كان، ثم رضني به هذه السنة هذا دعاء الاستخارة.  وإذا كان لا يعرف هذا الدعاء يدعو بما تيسر، يقول: اللهم قدر لي الخير، اللهم يسر لي الخير، اللهم اشرح صدري لهذا السفر إن كان خيرًا، اللهم اشرح صدري لهذا الزواج إن كان خيرًا، يدعو بما يفهم بما يعرف بعد السلام، يرفع يديه ويدعو بعد الصلاة الركعتين، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12919/كيفية-صلاة-الاستخارة-والدعاء-الوارد-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55409.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":14484,"question":"السؤال الآخر: ما حكم الصلاة وراء رجل يستغيث بغير الله، ويتوسل بالصالحين؟","title":"حكم الصلاة خلف من يتوسل بالصالحين ويستغيث بغير الله","answer":"الجواب: الصلاة خلف المشرك لا تجوز، ولا يجوز أن يقتدى به؛ لأن من استغاث بغير الله يعتبر مشركًا، فلا يصلى خلفه سواءً استغاث بالنبي ﷺ، أو بـالبدوي أو بـالحسين ، أو بالشيخ عبدالقادر، أو بغيرهم من الناس، فالذي يستغيث بالأموات، ويسألهم الحاجات والمدد يعتبر مشركًا، عليه أن يتوب إلى الله، وأن يبادر بذلك، ومن تاب صادقًا تاب الله عليه؛ لكن لا يتخذ إمامًا ولا مؤذنًا، بل يجب أن يكون المؤذن من أهل التوحيد، وهكذا الإمام، وإذا وجد في المسجد إمام مشرك يجب أن يزال، يجب على ولاة الأمور أن يزيلوه، وأن يعينوا مكانه عالمًا موحدًا بعيدًا عن الشرك؛ لأن ذلك هو الواجب على أئمة الإسلام، وعلى حكام المسلمين ألا يقدموا في المساجد من هو مشرك بالله، فإن إمامته باطلة، وهكذا المؤذنون يجب أن يكونوا مسلمين؛ لأنهم يخبروا الناس بالأوقات، ويعتمد عليهم، فلا بد أن يكون المؤذن أمينًا مسلمًا موحدًا، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12982/حكم-الصلاة-خلف-من-يتوسل-بالصالحين-ويستغيث-بغير-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62509.mp3","categories":["نواقض الإسلام","التوسل والشفاعة","نصائح وتوجيهات"]},{"id":14494,"question":"أولى أسئلة هذه الحلقة بقية أسئلة أحد السادة المستمعين، الذين بعثوا إلى هذا البرنامج، هذا المستمع بعث بعشرة أسئلة، عرضنا أربعة منها في حلقة مضت، وفي هذه الحلقة بقي له عدد آخر، فيسأل ويقول: لظروف عملي أسافر يوم الجمعة قبل أذان الظهر، أو بعد الأذان، وأقوم بصلاة الظهر والعصر جمع تقديم وقصر في نفس الوقت، هل هذا جائز؟ وهل يجوز لي التأخير؟علمًا بأن هذا يحدث في كل شهر مرة.","title":"حكم السفر قبل صلاة الجمعة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإذا كان السفر قبل الأذان -قبل زوال الشمس- فلا حرج -إن شاء الله-، والأفضل لك عدم السفر حتى تصلي الجمعة، هذا هو الأفضل لك، لكن إن سافرت قبل دخول الوقت فلا حرج عليك في ذلك، ولا حرج في الجمع ما دام السفر سفر قصر، كالسفر إلى الخرج، أو مكة، أو الحوطة، وغير ذلك، المقصود: مسافة ثمانين كيلو تقريبًا، يعني: يوم وليلة للمطية سابقًا، وهي الآن بالكيلو سبعون كيلو، ثمانون كيلو، ما يقارب هذه المسافة تعد سفرًا، لكن ينبغي لك -يا أخي- أن تحرص على حضور الجمعة لما فيها من الخير العظيم، والفائدة الكبيرة؛ ولئلا تتخذ هذا عادة، فيقسو القلب، ويقل الاعتناء بهذا الأمر، فأنصحك أن تجاهد نفسك حتى تصلي الجمعة ثم تسافر، لكن لا يلزمك ذلك إذا كان السفر قبل وقت الجمعة، قبل الزوال، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ يقول: إنه يفعل هذا في كل شهر مرة؟\nالشيخ: سواء في الشهر مرة، أو في الشهرين، الحكم واحد، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/12964/حكم-السفر-قبل-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62501.mp3","categories":["صلاة الجمعة","نصائح وتوجيهات"]},{"id":14533,"question":"رسالة وصلت إلى البرنامج من المستمع: عبدالرحمن محمد عباس، يقول: أنا طالب جامعي، وفي بعض الأحيان تفوتني صلاة الظهر بما فيها سنة رسول الله ﷺ، فهل يجوز أن أؤدي صلاة الظهر مع صلاة العصر وبدون السنة، أم أصلي صلاة الظهر بما فيها السنة مع صلاة العصر جمعًا؟","title":"حكم تأخير الظهر إلى العصر بعذر الدراسة","answer":"الجواب: لا يجوز لك الجمع، بل يجب عليك أن تصلي الظهر في وقتها، وليس لك تأخيرها إلى العصر، وليست الدراسة عذرًا في ذلك، بل يجب عليك أن تصلي الظهر في وقتها، ويشرع لك فعل السنة، وهي أربع قبل الظهر، وثنتين بعدها، كما كان النبي يفعل -عليه الصلاة والسلام- يصلي أربعًا قبل الظهر، وثنتين بعدها، وهذه نافلة، والمهم الفريضة. فالواجب عليك أن تصلي الفريضة في وقتها، وهي أربع في حق المقيم، وركعتين في حق المسافر، كما هو معلوم، وليس لك أن تؤخرها إلى العصر وأنت مقيم.  أما المسافر فلا بأس له التأخير والمريض كذلك، أما الاحتجاج بالدراسة فلا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13028/حكم-تاخير-الظهر-الى-العصر-بعذر-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63410.mp3","categories":["نصائح وتوجيهات","وقت الصلاة"]},{"id":14537,"question":"تقول السائلة: عندما أصلي لا أشعر بالاطمئنان إلا إذا أغمضت من عيني، ولا أفكر في أشياء دنيوية، ورغم ذلك، فأنا أستعيذ بالله من بداية صلاتي، ولكنني رغم ذلك أفكر وأشعر بالحزن لذلك، ما رأيكم في إغماض العينين؟","title":"حكم إغماض العينين أثناء الصلاة","answer":"الجواب: عليك أن تجتهدي في إحضار قلبك في الصلاة، وسؤال الله أن يعينك على هذا، وتذكري أنك بين يدي الله، وأن الله يطلع عليك ، فالمؤمن إذا قام في الصلاة يراقب ربه، ويستحضر عظمته -جل وعلا-، فالواجب هو العناية بهذا الأمر، والتذكر أنك بين يدي الله، وأن الله ينصب وجهه إلى عبده ما دام يصلي. فعليك أن تجتهدي في إحضار قلبك، والخشوع لله، وترك الإغماض، الإغماض في العينين مكروه، تركه أولى، ويذكر بعض أهل العلم أنه من فعل اليهود، فالأولى ترك ذلك، ولكن ضعي البصر في موضع السجود، انظري موضع السجود، واخشعي لله، واذكري عظمته، وأنك بين يديه، واجتهدي في ذلك، وأبشري بالخير. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13033/حكم-اغماض-العينين-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55501.mp3","categories":["نصائح وتوجيهات","مكروهات الصلاة"]},{"id":14549,"question":"هناك كتيب صغير، باسم (إنا نحن نزلنا الذكر وإنا له لحافظون) يشتمل على بعض السور القرآنية والأدلة بالأحاديث النبوية، مع فضل قراءتهما ومنزلتهما، مثل سورة الملك والواقعة والدخان وياسين والكهف والسجدة، والحاقة، فهل يركز القارئ عليها دون غيرها من السور القرآنية؟","title":"تقييم كتاب (إنا نحن نزلنا الذكر...)","answer":"الجواب: لا، هذا يحتاج إلى نظر؛ لأن كثير من هذه الأحاديث غير صحيح، التي أشار إليها صاحب الكتيب، لا بد ينظر فيها، فما ثبت عن النبي ﷺ أنه كان يستعمله في الليل أو في النهار فعله المؤمن، وما لم يثبت فلا يستحب، يقرأ كبقية القرآن، يقرأ مع القرآن كبقية القرآن.  أما أن يخص سورة، أو آية بشيء فلا إلا بدليل، مثل آية الكرسي بعد الصلاة تستحب، ومثل قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] والمعوذتين بعد كل صلاة مستحبة، وتكرر في المغرب والفجر ثلاث مرات بعد الفجر، وبعد المغرب؛ لأنه ثبت عن النبي هذا -عليه الصلاة والسلام-. أما شيء يأتي به الإنسان من نفسه، لا، مثل أن يقول: أريد أكرر سورة كذا، سورة الأعراف، سورة مثلًا الأنعام لا يكرر، إلا بدليل، يقرأها مثل بقية القرآن، إلا ما ثبت فيه الدليل، ما صح عن النبي ﷺ أنه خصه بشيء يخص، وهذا الكتاب يحتاج إلى نظر، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13047/تقييم-كتاب-انا-نحن-نزلنا-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48906.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":14556,"question":"هناك كثير من الكتب تروي أحاديث وتقول: إنها عن الرسول ﷺ وتذكر فضائل بعض السور، كالسور التي ذكرها صاحب السؤال، رأيكم في مثل هذا الكتب سماحة الشيخ؟","title":"توجيه حول بعض الكتب التي تروي فضائل السور","answer":"الجواب: الواجب على طالب العلم أنه يبين الصحيح من الضعيف، إذا صنف كتابًا يبين، أما أنه يذكر الغث والسمين والصحيح والضعيف ولا يبين، ما يستقيم، لا بد من بيان؛ لأن العامة لا يعرفون الصحيح من السقيم، فلا بد في حق المؤلف أن يحسن في جمعه، ويبين الصحيح، ويترك الضعيف، حتى يستفيد المؤمن من كتابه، وينتفع المؤمن بكتابه، ويستريح من التعب في الضعيف. المقصود: أن أهل العلم يجب على طالب العلم، بل يشرع له لا الوجوب لا يجب، لكن يشرع له أن يعتني بالصحيح حتى يكون العامة على بصيرة، ولا يجعل لهم الضعيف والصحيح، فإنهم لا يميزون، لكن أهل العلم جمهور أهل العلم ذكروا إنه يجوز ذكر الضعيف للترغيب والترهيب، كما فعل صاحب الترغيب والترهيب المنذري -رحمه الله-، ذكر جملة من أحاديث الترغيب والترهيب على هذه القاعدة، أنه من باب الترغيب والترهيب، وذكر غيره من أهل العلم، مثل صاحب بلوغ المرام، والمنتقى وغيرهم ذكروا أحاديث ضعيفة، للفائدة لتعرف أو ليضمها طالب العلم إلى غيرها مما يتقوى بها. فالحاصل: أنه ينبغي لمن ألف كتابًا أنه يوضح الصحيح، ولا سيما الكتب التي فيها بيان خصوصية بعض السور، أو خصوصية بعض الأذكار، يبين أنها صحيحة، ثبت عن النبي ﷺ أنه قال كذا في كذا، حتى يكون المطالع للكتاب على بينة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13054/توجيه-حول-بعض-الكتب-التي-تروي-فضاىل-السور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48907.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14564,"question":"سماحة الشيخ، بعض الآباء في المعاملة يميلون إلى البعض دون الآخرين، ويفرقون بينهم، هل من توجيه للآباء حول ذلك؟","title":"توجيه للأباء الذين لا يعدلون بين أولادهم","answer":"الجواب: الواجب على الآباء والأمهات تقوى الله في أولادهم، والعدل بينهم في النصيحة والتوجيه والإرشاد والتعليم؛ لأنهم جميعًا في الذمة أمانة، فيجب على الوالدين أن يتقوا الله في أولادهم، وأن يجتهدوا في تربيتهم التربية الإسلامية، وأن يحرصوا على الجد في الإحسان إليهم جميعًا، وعدم التخصيص؛ لأنهم جميعًا في الذمة.  فالواجب العناية بهم جميعًا، والحرص على تربيتهم التربية الإسلامية، وإذا كانوا محاويج جميعًا وجب الإنفاق عليهم بحسب حاجتهم إذا كان والدهم قادرًا على ذلك. أما أن يخص بعضهم من غير موجب شرعي، بل بالهوى فلا يجوز، فالواجب تقوى الله والعدل، كما قال النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم. فعلى الأب وعلى الأم العدل، وتحري الحق في تربية الأولاد، والإنفاق على الأولاد وغير ذلك، لكن من عصى الله من الأولاد وعق والديه لا يكون له حق مثل حق من أطاع وبر بوالديه، من عصى والديه وعقهم فهو يستحق العقوبة والتأديب، وليس له حق مثل حق من أطاع وبر، فالعاق يؤدب ويعامل بما يستحق حتى يدع العقوق، وحتى يستقيم على بر والديه، ولا يكون له من الحق مثل حق من بر والديه، واستقام على طاعة الله فيهما. وهكذا من كان غنيًا ليس له حق فيما يعطاه الفقير، إذا كان أحد الأولاد فقيرًا أو مريضًا ليس عنده قدرة على الكسب، وأبوه يستطيع فإنه ينفق عليه، وليس للغني حق في ذلك، بل هذا من أجل الحاجة، فالأب ينفق على ولده الفقير والأم كذلك، ولا يكون جائرًا ولا ظالمًا إذا أنفق على الفقير، وعالج المريض؛ لأنه لا يستطيع، وترك القادر الذي يستطيع عنده المال ينفق على نفسه، ويعالج نفسه فهو مستغن عن والديه بما أعطاه الله من المال. أما الفقير كالطفل والمريض الذي ليس عنده ما يعالج به ونحو ذلك ممن يعجز عن النفقة لفقره أو مرضه أو علة به أو نحو ذلك ليس مثل الصحيح الغني، والله -جل وعلا- يقول سبحانه في كتابه العظيم: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ويقول -جل وعلا-: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فعلى المؤمن أن يتقي الله في جميع ما يأتي ويذر حسب شرع الله، وعليه أن يحذر الظلم والعدوان في أولاده أو في غيرهم، بل عليه أن يتحرى الحق أو العدل في كل شيء، وفق الله الجميع، نعم. المقدم: اللهم آمين، أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13061/توجيه-للاباء-الذين-لا-يعدلون-بين-اولادهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55602.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":14575,"question":"الأخوات السائلات اللاتي رمزن لأسمائهن بـ (م. ن) يقلن في هذا سماحة الشيخ، نحن أخوات من أهالي المنطقة الشرقية، منا الموظفة، ومنا الأستاذة في الجامعة، ومنا الدارسة في الدراسات الجامعية المتقدمة، لنا أب -هداه الله- يرفض جميع من يتقدم لنا، مع العلم بأن المتقدمين منهم المؤهلين، ومنهم ذوي الأخلاق الحميدة، وذوي الالتزام بطاعة الله، وأبونا يرفض ذلك بحجج واهية ليس لها من الله سلطان، فهو يقول: بأنه لن يزوجنا إلا إذا كان المتقدم لنا من مدينتنا، مع أنه هداه الله متزوج من زوجتين من نفس المدينة، فالرجاء من سماحة الشيخ عبدالعزيز تقديم النصح لأبينا وإرشاده إلى الحق في برنامج نور على الدرب. جزاكم الله خيرًا.","title":"نصيحة لمن يمتنع عن زواج بناته","answer":"الجواب: بسم الله الرحمن الرحيم .\nالحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالواجب على جميع الأولياء أن يتقوا الله في مولياتهم، وأن يزوجوهن إذا خطبهن الكفء، سواء كان الولي أبًا أو جدًا أو ولدًا أو أخًا أو عمًا أو غير ذلك.  الواجب على الولي أن يتقي الله، وأن يبادر بتزويج موليته، سواء كانت بنته أو أخته أو غير ذلك، ولا يجوز له التساهل في هذا أو التعلل بأشياء لا وجه لها؛ لقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير ولقوله ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء وهذا يعم الرجال والنساء، متى خطبت المرأة وجب تزويجها، إذا خطبها الكفء؛ لأن ذلك أحصن لفرجها، وأغض لبصرها، وأبعد لها عن الفتنة، سواء كانت مدرسة أو طالبة أو موظفة أو غير ذلك، وسواء كان في حاجة إلى مرتبها أم ليس له حاجة في ذلك. يجب على الأب وعلى غيره أن يتقي الله، وأن يراقب الله، وأن يحذر ظلم البنت في تأخير تزويجها، بل متى خطبها الكفء سواء كان من بلدها أو من قبيلتها أو من غير بلدها، أو من غير قبيلتها ما دام كفء في دينه، فالواجب تزويجه؛ لقوله ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير ولم يقل: من أهلكم، من قبيلتكم، أو من بلدكم، لا، المهم صلاح أخلاقه ودينه. ولا يجوز حبس المرأة لأجل المرتب، أو لأجل خدمتها له، أو ما أشبه ذلك، بل يجب أن يزوجها، وأن يتقي الله فيها، ويطلب من يقوم بخدمته من سواها من خادم أو زوجة يتزوجها، أما أن يحبس بنته أو أخته من أجل أن تخدمه، أو من أجل أن يأخذ راتبها، هذا من الظلم، ويقول الرسول ﷺ: اتقوا الظلم، فإن الظلم ظلمات يوم القيامة نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13072/نصيحة-لمن-يمتنع-عن-زواج-بناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55701.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":14578,"question":"سماحة الشيخ، هذا سائل لم يذكر الاسم في هذه الرسالة، ويقول: أريد من سماحة الشيخ الإجابة على هذا السؤال، يقول:قال رسول الله ﷺ فيما رواه الشيخان: إنكم سترون ربكم عيانًا كما ترون هذا القمر لا تضامون في رؤيته، فإن استطعتم أن لا تغلبوا على صلاة قبل طلوع الشمس وقبل غروبها فافعلوا والسؤال هو: لماذا قرن في هذا الحديث بين رؤية الله  وبين صلاة الفجر والعصر، هل المحافظة على هذه الصلاة في هذين الوقتين سبب لرؤية الله ؟وجهونا سماحة الشيخ.","title":"السر في اقتران رؤية الله بصلاتي الفجر والعصر","answer":"الجواب: رؤية الله سبحانه في الجنة ويوم القيامة حق يراه المؤمنون، وهو أعلى نعيم أهل الجنة، إذا كشف الحجاب عن وجهه ورأوه ما أعطوا شيئًا أحب إليهم من النظر إلى وجهه ، وقد أخبر -جل وعلا- أنهم يرونه يوم القيامة عيانًا، كما يرون الشمس صحوة ليس دونها سحاب، وكما يرون القمر ليلة البدر، لا يضامون في رؤيته، هذا حق عند أهل السنة والجماعة، يقول ﷺ: فإن استطعتم أن لا تغلبوا على صلاة قبل طلوع الشمس وقبل غروبها فافعلوا يعني: صلاة العصر وصلاة الفجر، ذكر أهل العلم أن السر في ذلك أن من حافظ عليهما يكون ممن ينظر إلى الله بكرة وعشيًا في الجنة، يعني في مقدار البكرة والعشي؛ لأن الجنة ليس فيها ليل كلها نهار مطرد، لكن في مقدار البكرة والعشي، كما قال تعالى: وَلَهُمْ رِزْقُهُمْ فِيهَا بُكْرَةً وَعَشِيًّا [مريم:62] يعني: في مقدار البكرة والعشي في الدنيا، وهكذا في الرؤية في مقدار البكرة والعشي يعني: خواص أهل الجنة لهم رؤية ما بين البكرة والعشي، يعني رؤية كثيرة بسبب أعمالهم الطيبة، وإيمانهم الصادق.  ومن أسباب ذلك محافظتهم على صلاة العصر، وصلاة الصبح لها خصوصية هاتان الصلاتان، والمحافظة عليهما من دلائل قوة الإيمان وكمال الإيمان مع بقية الصلوات. فالواجب أن يحافظ على الجميع، ولكن يخص العصر والفجر بمزيد عناية؛ لأنها ضد ما عليه المنافقون، وضد ما عليه الكسالى، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.\nتساهل كثير من الناس فضيلة الشيخ بهذين الوقتين وهما العصر والفجر هل من نصيحة لهؤلاء؟ جزاكم الله خيرًا.\nالشيخ: نعم، الواجب على كل مؤمن ومؤمنة الحرص على المحافظة على الصلاة في وقتها جميع الصلوات الخمس، وأن يخص الفجر والعصر بمزيد عناية، فالفجر في الحقيقة كثير من الناس يتكاسل عنها، وينام حتى طلوع الشمس، وربما لا يقوم لها إلا إذا قام لعمله إن صلى، وهذه مصيبة عظيمة، ومنكر عظيم.  فالواجب أن يصلى في الوقت، وقد ذهب جمع من أهل العلم أنه إذا تعمد تركها حتى تطلع الشمس كفر؛ لقوله ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة وهذا قد تعمد تركها حتى خرج وقتها، وهكذا من تعمد ترك صلاة العصر حتى غابت الشمس يكفر عند جمع من أهل العلم لهذا الحديث الصحيح: بين الرجل وبين الكفر والشرك ترك الصلاة وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر. فالواجب على المؤمن وعلى المؤمنة العناية بالصلوات الخمس، والمحافظة عليها في أوقاتها، وأن يخص الفجر بمزيد عناية حتى يقوم لها، ويصليها مع المسلمين في وقتها، وتصليها المرأة في وقتها، وهكذا العصر بعض الناس إذا جاء من عمل سقط نائمًا، وترك صلاة العصر، وهذا منكر عظيم، والعياذ بالله، وكفر أكبر عند بعض أهل العلم إذا تعمد ذلك، فالواجب الحذر. وهكذا بعض الناس يسهر على القيل والقال أو اللعب، ثم إذا طاح نام عن صلاة الفجر، وهذا منكر عظيم، الواجب عدم السهر وأن يتحرى بنومه ما يعينه على القيام لصلاة الفجر، وأن يصليها في الجماعة، ولا يجوز له التشبه بالمنافقين أثقل الصلاة على المنافقين صلاة العشاء وصلاة الفجر وهكذا صلاة العصر، كل الصلوات ثقيلة عليهم: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فالواجب الحذر من مشابهتهم، والواجب المحافظة عليها في وقتها كلها الصلوات الخمس جميعًا، يجب أن يحافظ عليها في أوقاتها، مع إخوانه في المساجد، وأن يخص الفجر والعصر والعشاء بمزيد عناية، حتى يحذر من صفات المنافقين، نسأل الله للجميع العافية والهداية. المقدم: اللهم آمين، جزاكم الله عنا كل خير سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13075/السر-في-اقتران-روية-الله-بصلاتي-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55704.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14580,"question":"أخونا السائل الحقيقة كتب رسالة مطولة أخوكم (ن. ي. م) نلخصها سماحة الشيخ بأنه يقول:بأنه يسكن في بيت أهله مع زوجته وبنته منذ خمس سنوات، يقول:أولًا: أغتنم فرصة وجودي لإرضاء والدي ووالدتي. وثانيًا: ليس عندي بيت وأنا مرتاح جدًا، ولا يوجد عقبات أمامي، والحمد لله سوى مشكلة واحدة وهي: بأنني سميت ابنتي الأولى حسب رغبة الوالدة، وهو اسم جميل، وأنا مسرور به، وأحمد الله على ذلك.أما الثانية -البنت الثانية- فقد أحرجتني والدتي كثيرًا حتى سميت اسم لا أحبه، ولا يحبه أحد، والمشكلة هي بأنني سجلت اسمها في دائرة النفوس اسم أحبه وهو جميل جدًا، وهو من أسماء الصحابيات ولا حرج فيه أمام الناس والشرع، وفي البيت أطلق عليها الاسم الذي رغبت فيه والدتي، ولا أحد يعرف بالحقيقة سوى زوجتي، سماحة الشيخ، هل أنا مذنب أو مسيئ أمام الله؟ وماذا علي أن أفعل؟علمًا بأنني أسكن مع والدي ووالدتي وهما بأمس الحاجة إلي وأنا أخشى أن تعرف بالحقيقة فتغضب مني، وجهوني سماحة الشيخ.","title":"حكم مخالفة رغبة الأم في تسمية المولود","answer":"الجواب: قد أحسنت فيما فعلت إرضاءً لوالدتك اسمها المكتوب هو المعتمد المقرر في الدوائر الرسمية هو المعتمد، وإذا أرضيت والدتك بأن سميتها بالاسم الذي رغبت فيه فلا بأس -إن شاء الله-، إذا كان الاسم الذي رغبته الوالدة غير مناسب غير طيب، ولا يناسب تسميتها به، فأنت تسعى في مصلحة طفلتك ولا تسميها باسم يضرها، ويسيئ سمعتها، ولكن إذا أرضيت والدتك بإخفاء ذلك فالأمر في هذا سهل -إن شاء الله-، إذا كان الاسم الذي سميتها به مناسب، والاسم الذي قالت أمك ليس فيه محذور شرعًا، فلا حرج.  أما إذا كان الاسم الذي قالته أمك اسم لا يناسب، ولا يليق شرعًا فتركه واجب؛ لأن الطاعة في المعروف، لا تطاع الأم في المعصية، ولا الأب في المعصية، إنما الطاعة في المعروف، لكن إذا كانت طلبت اسمًا لا حرج فيه شرعًا، فإن سميتها به فلا بأس، وإن رأيت الأصلح سميتها اسمًا آخر، وأخفيته على أمك؛ لأنك تراه أصلح للبنت فلا حرج في ذلك -إن شاء الله-، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ، أقول سماحة الشيخ: اختيار الأسماء الطيبة، واختيار بعض الناس لبعض الأسماء التي يكون قد فيها حرج، ومن ثم نجدهم يتحرجون بعد كبر هؤلاء الأطفال، ويريدون التغيير، لعل لكم كلمة أو توجيه في اختيار الأسماء سماحة الشيخ. الشيخ: المشروع للوالد والوالدة أن يتحريا الأسماء الطيبة؛ لأن الإنسان ينادى باسمه يوم القيامة باسم أبيه، فالمشروع للأب والأم أن يتحريا الأسماء الطيبة لأولادهم الذكور والإناث، وأن يتقيا الله في ذلك، هذا هو الواجب على الجميع، والمشروع للجميع أن يتحريا الأسماء المناسبة، لكن لا يجوز التعبيد لغير الله في الأسماء لا يقال: عبد الكعبة، ولا عبد النبي، ولا عبد اللات ولا عبد العزى ولا عبد زيد، ما يسمى بالتعبيد لغير الله، ولكن يتحرى الأسماء المناسبة: محمد، صالح، أحمد، زيد، فلان، إبراهيم، الأسماء ليس فيها محذور، وهكذا أسماء النساء عائشة، مريم، فاطمة، زينب، خديجة.. إلى غير هذا من الأسماء الطيبة، وإذا سماها باسم لا بأس به معتاد عند جماعته فلا بأس. المقصود: أن الأسماء لا مشاحة فيها، إلا ما عبد لغير الله لا يجوز، أو فيه تزكية كونه يسميها بشيء يعني فيه تزكية النبي غير اسم برة إلى غير هذا، قال: الله أعلم بأهل البر منكم أو اسم قبيح يغيره، اسمها عاصية فيغير اسمه عاصية إلى مطيعة، أو إلى زينب أو إلى مريم، يعني أسماء قبيحة إن غيرها لا بأس. فالمقصود: أن المؤمن من الأب والأم يتخير الاسم الطيب لابنه وبنته، الأب والأم يتخيران الأسماء الطيبة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13077/حكم-مخالفة-رغبة-الام-في-تسمية-المولود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55706.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":14587,"question":"رسالة وصلت إلى البرنامج من المستمع: عبدالله عبدربه الشمز -فيما يبدو- أخونا من المقيمين في الرياض، يسأل ويقول: ما رأيكم فيمن ينكر على بعض الملتزمين بكتاب الله وسنة رسوله ﷺ، ويصفونهم بالتشدد، وأضرب على ذلك مثلًا: عدم مصافحة غير المحارم، فإنهم يتهموننا بالتخلف، فبماذا تنصحون هؤلاء؟","title":"نصيحة لمن يصف المتدينين بالتشدد","answer":"الجواب: من نبز الملتزمين بالحق بالتشدد فقد أخطأ وغلط، الملتزم بالحق يوصف بالخير والاستقامة، يوصف بالاعتدال، ويدعى له بالتوفيق والثبات، ما يقال: متشدد، ولا متنطع، بل يقال: ملتزم ومستقيم، قال تعالى: إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا تَتَنَزَّلُ عَلَيْهِمُ الْمَلائِكَةُ أَلَّا تَخَافُوا وَلا تَحْزَنُوا وَأَبْشِرُوا بِالْجَنَّةِ الَّتِي كُنْتُمْ تُوعَدُونَ[فصلت:30] ويقول سبحانه: إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا فَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ  ۝ أُوْلَئِكَ أَصْحَابُ الْجَنَّةِ خَالِدِينَ فِيهَا جَزَاءً بِمَا كَانُوا يَعْمَلُونَ[الأحقاف:13-14]. فالله -جل وعلا- أمر عباده بالاستقامة؛ فَلِذَلِكَ فَادْعُ وَاسْتَقِمْ[الشورى:15] قال تعالى: فَاسْتَقِمْ كَمَا أُمِرْتَ[هود:112] والاستقامة هي لزوم الحق والثبات عليه بأداء الواجب، وترك المحارم، هذه الاستقامة، هذا هو الالتزام. فالذي لا يصافح غير المحارم هذا ملتزم مشكور مأجور، والذي يصافح النساء ولسن محارم آثم مفرط متعدٍ جافٍ غير ملتزم.  فالمقصود: أن الذي يصف الملتزمين بطاعة الله، وأداء ما أوجب الله عليه، وترك ما حرم الله عليهم بالتشديد، أو بالتشدد أو بالتزمت، كل هذا غلط، فعليه أن يستغفر الله، وعليه أن يتوب إلى الله، وأن يترك هذا العمل، ومن قصر عن طاعة الله، وفرط في الواجب هذا يقال له: جافٍ، ويقال له: مقصر وغير ملتزم. أما المشدد هو الذي يبتدع في الدين، هو الذي ينهى عما أباح الله فيقول مثلًا: لا تصافح المحرم، لا تصافح الرجل، أو يقول مثلًا: لا تجهر بذكر الله بعد الصلاة، يبتدع في الدين، أو يقول: إذا جاء يوم المولد يوم الثاني عشر من ربيع الأول، فيجعل حفلة بالمولد هذا ابتداع -تشديد-؛ كذلك يقول: اجعل حفلة لعيد أمك، أو عيد ولدك، أو عيد أبيك في وقت من السنة أو في وقت...، هذا كله من الزيادة والتشديد، أو يأتي ببدع أخرى يدعو إليها، يعني: يشرع للناس ما لم يأذن به الله، كأن يقول: إذا كان في ليلة كذا تصلي صلاة كذا، وفي ليلة كذا تصلي صلاة كذا، صلوات ما شرعها الله، هذا يقال له: مبتدع، ويقال له: متشدد، أو يقول للناس: إذا صليتم لا بد أن تكون الصلاة طويلة زائدة على ما شرع الله هذا تشديد. أو يقول: إذا صمت فلا تكلم الناس، أو لا تبع، ولا تشتر هذا تشديد، وما أشبه ذلك مما يكون فيه النهي عما أباح الله أو تشريع ما لم يأذن به الله، هذا التشديد، نعم.","link":"https://binbaz.org.sa/fatwas/13084/نصيحة-لمن-يصف-المتدينين-بالتشدد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63507.mp3","categories":["نصائح وتوجيهات"]},{"id":14594,"question":"أولًا: نبدأ برسالة المستمع خضر حسن الشريدة، من سوريا محافظة القنيطرة قرية قصيبة، يقول في رسالته هذه بعد أن يشكر العلماء الذين ينيرون الطريق في دياجر الظلم المعنوية، ويشكر الدولة التي تبنت مثل هذا البرنامج الفريد من نوعه، كما يشكر الإذاعة السعودية صاحبة السبق إلى ما يفيد المستمع.يقول في سؤاله الأول: ما واجب المسلم إذا أوذي واضطهد بسبب تمسكه بدينه؟","title":"ما واجب من أوذي بسبب تمسكه بدينه؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله وخليله وأمينه على وحيه نبينا وإمامنا محمد بن عبدالله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد أوذي الرسل -عليهم الصلاة والسلام-، وأوذي المؤمنون في سابق الزمان ولاحقه، والواجب على المؤمن إذا أوذي في دينه الصبر والاحتساب، والأخذ بالأسباب التي تدفع عنه الأذى -الأسباب الشرعية-، مثل الهجرة من بلاد الأذى إلى بلاد ليس فيها أذى، مثل الكف عما يسبب الأذى إذا كان ذلك الشيء لا يضره في دينه، كبعض الأمور المباحات أو المستحبات إذا تركها دفعًا للأذى فلا حرج عليه. المقصود: أنه يتحمل ويتصبر، ويسأل ربه العون، ويلجأ إلى الله  في عافيته مما أصابه، وفي دفع الأذى عنه، ويدعو على من ظلمه لا بأس. ومن العلاج: أن ينتقل ويهاجر من بلاد الأذى إلى بلاد سليمة، أو من محل الأذى إلى محل آخر في وطنه بعيدًا عن الأذى، مع سؤال الله  الإعانة على الصبر، وسؤال الله العافية من الأذى، وفعل الأسباب الأخرى المباحة التي تقيه الأذى، نعم.","link":"https://binbaz.org.sa/fatwas/13091/ما-واجب-من-اوذي-بسبب-تمسكه-بدينه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_558/55801.mp3","categories":["نصائح وتوجيهات"]},{"id":14663,"question":"أم معاذ من المدينة المنورة أرسلت بمجموعة من الأسئلة، تقول في السؤال الأول: دعاء الاستخارة قبل السلام أم بعد السلام من الصلاة سماحة الشيخ؟","title":"متى يكون دعاء الاستخارة؟","answer":"الجواب: السنة أن يكون بعد السلام؛ لأن النبي ﷺ قال: إذا هم أحدكم بأمر فليصل ركعتين، ثم ليقل فجعل الدعاء بعد الصلاة، نعم.","link":"https://binbaz.org.sa/fatwas/13150/متى-يكون-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56004.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":14691,"question":"بعض الأخوات سماحة الشيخ في مجمع النساء قد يتساهلن ببعض الألفاظ، والتي قد تخل بالعقيدة، هل من كلمة للنساء في هذا المجال؟","title":"نصيحة للمتساهلات فيما يخل بالعقيدة من ألفاظ","answer":"الجواب: نعم، الواجب عليهن تقوى الله، وأن يحفظن ألسنتهن مما يغضب الله، يجب على كل رجل وعلى كل امرأة أن يتقي الله، وأن يحفظ لسانه عما يغضب الله -جل وعلا- لا من جهة العقيدة، ولا غير العقيدة، يجب أن يصون الإنسان عقيدته والمرأة تصون عقيدتها مما يخل بها من المعاصي والكلام الرديء، كل واحد من الرجال والنساء عليه أن يتقي الله، وأن يراقب الله في حفظ عقيدته، والاستقامة على دين الله، وعلى ترك محارم الله، والحذر من كل ما يغضب الله -جل وعلا- قولًا وعملًا، على الرجال والنساء جميعًا من جهة توحيد الله، والإخلاص له، وترك الشرك، من جهة الإيمان بأسماء الله وصفاته، من جهة أداء ما أوجب الله ترك ما حرم الله، من جهة حفظ اللسان عن الغيبة والنميمة والسب والشتم، إلى غير هذا، كل واحد عليه أن يحاسب نفسه، وعليه أن يتقي الله، وعليه أن ينصح من قصر في هذا من أخيه أو عمه أو عمته أو خاله أو خالته أو أبويه أو غير ذلك، النصيحة واجبة، يقول النبي ﷺ: الدين النصيحة، الدين النصيحة، الدين النصيحة قيل: لمن يا رسول الله؟ قال: لله ولكتابه ولرسوله ولأئمة المسلمين وعامتهم ويقول ﷺ: لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه كما تحب أن تكون من خير الناس، فهكذا تحب لأخيك وعمك وأبيك وأمك وقريبك وأخيك المسلم، وتنصح له بالكلام الطيب، والأسلوب الحسن، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13183/نصيحة-للمتساهلات-فيما-يخل-بالعقيدة-من-الفاظ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56016.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":14700,"question":"أيضًا له قضية مطولة لخصتها سماحة الشيخ، يقول إنه ارتكب عدد معاصٍ في جهالته ويقول: إنه تاب، وبدأ بالصالحات، ويرجو التوجيه.","title":"توجيه لمن ارتكب المعاصي ثم تاب","answer":"الجواب: من تاب تاب الله عليه، إذا أتى الإنسان معاصٍ بل حتى الكفر إذا أتى كفرًا أو معاصٍ، ثم تاب تاب الله عليه، إذا صدق في التوبة، واستكمل شروطها، وهي الندم على الماضي من السيئات، والإقلاع منها، وتركها، والحذر منها، والعزم الصادق ألا يعود فيها؛ خوفًا من الله، وتعظيمًا له، فإن الله سبحانه يقبل توبته، ويغفر له، كما قال : وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له. فالواجب على المؤمن البدار بالتوبة، وحسن الظن بالله ، ثم الاستمرار والصدق في عدم العودة إلى الذنوب الماضية، ومما يلتحق بالتوبة: رد المظالم إلى أهلها إذا كانت المعصية ظلمًا للناس: في نفس أو مال أو عرض، فإن التوبة لا تتم حتى يدفع المال لصاحبه إن كان مسروقًا أو مغصوبًا، أو نحو ذلك، عليه أن يدفع لصاحبه، أو يتحلله من ذلك، ويقول: سامحني، فإذا سامحه سقط، وإن كان عرضًا استحله، قال: يا أخي، تكلمت في عرضك، أبحني سامحني، فإن لم يستطع ذلك وخشي الفتنة، فإنه يذكره بالخير الذي يعلمه منه في المجالس والمحافل التي اغتابه فيها، حتى يقابل هذا هذا، فإذا كان يخشى الفتنة إذا أخبره بأنه تكلم في عرضه، فإنه بدل ما ذكره بالأشياء الرديئة يذكره بالأشياء الطيبة التي يعلمها منه، يذكره في الأماكن التي اغتابه فيها: فلان فيه كذا، وفلان كذا، كي يعرفوا خصاله الحميدة، حتى يكون ذلك كفارة لما ذكر من خصاله السيئة؛ لأن كل إنسان لا يخلو من خصال طيبة، وخصال حميدة، وخصال رديئة. فإن المغتاب الذي لم يتيسر له الاستباحة من صاحبه فإنه يذكره بالخصال الحميدة الطيبة التي يعلمها منه، لا يكذب، لكن يذكر الخصال الحميدة بدلًا من الخصال الذميمة التي عابه بها سابقًا، مع الندم فيما بينه وبين الله الندم والأسف على ما صدر منه، والعزم ألا يعود، والحذر من تعاطي ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13225/توجيه-لمن-ارتكب-المعاصي-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62912.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14706,"question":"أيضًا له قضية مطولة لخصتها سماحة الشيخ، يقول إنه ارتكب عدد معاصٍ في جهالته ويقول: إنه تاب، وبدأ بالصالحات، ويرجو التوجيه.","title":"توجيه لمن ارتكب المعاصي ثم تاب","answer":"الجواب: من تاب تاب الله عليه، إذا أتى الإنسان معاصٍ بل حتى الكفر إذا أتى كفرًا أو معاصٍ، ثم تاب تاب الله عليه، إذا صدق في التوبة، واستكمل شروطها، وهي الندم على الماضي من السيئات، والإقلاع منها، وتركها، والحذر منها، والعزم الصادق ألا يعود فيها؛ خوفًا من الله، وتعظيمًا له، فإن الله سبحانه يقبل توبته، ويغفر له، كما قال : وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82] وقال سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] وقال النبي ﷺ: التائب من الذنب كمن لا ذنب له. فالواجب على المؤمن البدار بالتوبة، وحسن الظن بالله ، ثم الاستمرار والصدق في عدم العودة إلى الذنوب الماضية، ومما يلتحق بالتوبة: رد المظالم إلى أهلها إذا كانت المعصية ظلمًا للناس: في نفس أو مال أو عرض، فإن التوبة لا تتم حتى يدفع المال لصاحبه إن كان مسروقًا أو مغصوبًا، أو نحو ذلك، عليه أن يدفع لصاحبه، أو يتحلله من ذلك، ويقول: سامحني، فإذا سامحه سقط، وإن كان عرضًا استحله، قال: يا أخي، تكلمت في عرضك، أبحني سامحني، فإن لم يستطع ذلك وخشي الفتنة، فإنه يذكره بالخير الذي يعلمه منه في المجالس والمحافل التي اغتابه فيها، حتى يقابل هذا هذا، فإذا كان يخشى الفتنة إذا أخبره بأنه تكلم في عرضه، فإنه بدل ما ذكره بالأشياء الرديئة يذكره بالأشياء الطيبة التي يعلمها منه، يذكره في الأماكن التي اغتابه فيها: فلان فيه كذا، وفلان كذا، كي يعرفوا خصاله الحميدة، حتى يكون ذلك كفارة لما ذكر من خصاله السيئة؛ لأن كل إنسان لا يخلو من خصال طيبة، وخصال حميدة، وخصال رديئة. فإن المغتاب الذي لم يتيسر له الاستباحة من صاحبه فإنه يذكره بالخصال الحميدة الطيبة التي يعلمها منه، لا يكذب، لكن يذكر الخصال الحميدة بدلًا من الخصال الذميمة التي عابه بها سابقًا، مع الندم فيما بينه وبين الله الندم والأسف على ما صدر منه، والعزم ألا يعود، والحذر من تعاطي ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13225/توجيه-لمن-ارتكب-المعاصي-ثم-تاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_629/nour_62912.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14746,"question":"أيضًا في نهاية رسالتها تسأل سماحة الشيخ وتقول: إنها تبكي بكاءً شديدًا على أولادها الستة الذين توفوا وترجو التوجيه.","title":"توجيه لمن ابتليت بوفاة ستة من أولادها","answer":"الجواب: ننصحك بأن تصبري وتحتسبي، وأن تسألي الله أن يجعلهم شفعاء لك، وأن يعوضك عنهم خير الدنيا والآخرة، وأن يبارك في الباقين، ويصلحهم، ولا تجزعي ولا تكثري البكاء، بل عليك الصبر، يقول الله -جل وعلا-: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ[البقرة:155-156] وقال سبحانه: أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ[البقرة:157]. فالصبر هو الواجب، وقد يكون لك في ذلك خير كثير وعاقبة حميدة والله أحكم وأعلم ، فاحتسبي واصبري واسألي الله الأجر العظيم، وحسن العاقبة، وصلاح الموجودين. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13238/توجيه-لمن-ابتليت-بوفاة-ستة-من-اولادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63718.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":14772,"question":"سماحة الشيخ التجربة لها تأثير، نحن في الرياض نعيش هذه النعمة، ولله الحمد، ويتوجها حضوركم باستمرار، كيف تصورون هذه التجربة للإخوة المسلمين حتى يستفيدوا منها؟","title":"نصيحة بالحرص على التعليم وحلق العلم","answer":"الجواب: لا ريب أن حلقات العلم لها شأنٌ عظيم، وكان الرسول ﷺ يفعلها، ويجلس لأصحابه يعلمهم، ويذكرهم بين وقتٍ وآخر، ويتحلقون حوله، ويجتمعون ، وهكذا الصحابة بعده كانوا يستعملون الحلقات للعلم والتعليم، وهكذا العلماء إلى زماننا هذا. فالفائدة من الحلقات عظيمة، فطالب العلم يحضر ويستمع، والعامة يحضرون، ويستمعون، وطالب العلم يحضر بكتابه الذي فيه الدرس، حتى يستفيد، وحتى يكتب بعض الفوائد؛ ولهذا فائدة عظيمة، فإنه إذا استمع وكتب ما قد يفوته لولا الكتابة، يكون هذا عملًا طيبًا، وهكذا العامة يحضرون ويستفيدون، ويسألون عما أشكل عليهم، كل هذا مما يحبه الله، وفي الحديث يقول ﷺ: إذا مررتم برياض الجنة فارتعوا قالوا: يا رسول الله، وما رياض الجنة؟ قال: حلق الذكر وفي الصحيحين أنه كان -عليه الصلاة والسلام- كان ذات يوم في المسجد، وحوله أصحابه يذكرهم -عليه الصلاة والسلام-، فدخل ثلاثة والنبي ﷺ يعلم الناس وحوله الحلقة، فجاء أحدهم فدخل في الحلقة، والثاني جلس خلف الحلقة، والثالث خرج، فلما فرغ النبي من حديثه -عليه الصلاة والسلام-، قال: ألا أنبئكم بشأن الثلاثة؟ قالوا: بلى يا رسول الله، قال: أما أحدهم فآوى، فآواه الله وهو الذي دخل في الحلقة  وأما الثاني فاستحيا، فاستحيا الله منه، وأما الثالث فأعرض، فأعرض الله عنه.\nالمقدم: الذي استحيا الذي بقي في...\nالشيخ: الذي خلف الحلقة، ما زاحم، ولا دخل في الحلقة، وأما الثالث: فأعرض، فأعرض الله عنه وهذا وعيد شديد، يفيد الحذر من الإعراض عن حلقات العلم، وعن طلب العلم.  وفي الصحيحين عن معاوية  عن النبي -عليه الصلاة والسلام- أنه قال: من يرد الله به خيرًا يفقهه في الدين وهذا حديثٌ عظيم، يدل على أن من علامات السعادة، وأن الله أراد بالعبد خيرًا أن يفقه في الدين، وأن يتبصر في الدين، كما يدل على أن من علامات الهلاك، وعدم الخير، أن لا يتفقه في الدين، وأن يعرض، ويغفل. وفي صحيح مسلم عن النبي ﷺ أنه قال: من سلك طريقًا يلتمس فيه علمًا؛ سهل الله له به طريقًا إلى الجنة فطلب العلم من أفضل القربات، ومن أهم المهمات، فنصيحتي لكل مسلم، ولكل مسلمة الحرص على التفقه في الدين، والتعلم، وعلى طلب العلم بكل وسيلة، ومن ذلك سماع هذا البرنامج: نور على الدرب، سماعه من طلب العلم، ومن العناية بالعلم، فهو برنامج مفيد، يصل إليك وأنت على فراشك، وفي مجلسك، وفي سيارتك، فنصيحتي لكل مسلم ولكل مسلمة العناية بهذا البرنامج للاستفادة. وهكذا نصيحتي للجميع سؤال أهل العلم عما أشكل، وعدم الحياء، بالبرقية، بالهاتف، بالمكاتبة، بالمشافهة إذا كان طالب العلم قريبًا، ولا ينبغي لأحد أن يسكت على الجهل، لا رجل، ولا امرأة، الواجب السؤال عما أشكل، قال الله سبحانه: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنتُمْ لا تَعْلَمُونَ [الأنبياء:7] ويروى عنه -عليه الصلاة والسلام- أنه قال لقومٍ أفتوا بغير علم: ألا سألوا إذ لم يعلموا، إنما شفاء العي السؤال. فالنصيحة أكررها: الحرص على طلب العلم، والتفقه في الدين، من طريق المكاتبة، من طريق الهاتف -التلفون- من طريق سماع هذا البرنامج في كل مكان، من طريق حضور حلقات العلم في المساجد، إلى غير ذلك، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13296/نصيحة-بالحرص-على-التعليم-وحلق-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_641/nour_64109.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14774,"question":"هناك من الأصدقاء من أسير معهم وأعتبرهم كالإخوة، فهم أوفياء ومخلصون، ولكنهم لا يصلون، والعياذ بالله، وبعضهم يصلي في رمضان فقط، والبعض الآخر يأتي الفواحش ما نهى الله ورسوله ﷺ عنه. وأنا بصفتي مسلم أحاول مع بعض الأصدقاء جذبهم إلى الصلاة والعبادة، فهل أقاطعهم التزامًا بقول رسول الله ﷺ: بين المسلم والكافر ترك الصلاة، فمن تركها فقد كفر صدق رسول الله؟ وإن قاطعتهم فهل معنى ذلك أن أقاطع معظم الزملاء من منطقتي، ومن مرحلتي الدراسية الذين لا يصلون، وأبقى منعزلًا عن هؤلاء الناس؟أفيدوني، جزاكم الله خيرًا.","title":"حكم مجالسة وصُحبة من لا يصلي","answer":"الجواب: نعم، نعم، عليك أن تقاطعهم إذا لم يقبلوا النصح، ولم يستفيدوا منك، ولم يسترشدوا منك، فعليك أن لا تصحبهم، وأن لا يكونوا زملاء لك في الزيارات، أو الأكل، ونحو ذلك، بل تقاطعهم ولا يضرك أن تدرس في المدرسة التي هم فيها، لكن لا تتخذهم أصحابًا، ولا زملاء في الأكل والشرب، والزيارة للإخون الآخرين لا، قاطعهم حتى يعلموا أنك تهجرهم، وأنك تبغضهم في الله؛ لأن ترك الصلاة كفر أكبر على الصحيح، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة. فالذين لا يصلون وقد نصحتهم لله، وأعذرت فيهم عليك أن تقاطعهم، لا تجب دعوتهم، ولا تدعوهم إلى وليمة عندك، ولا تكن معهم في الزيارات، قاطعهم حتى يعلموا صدقك في بغضهم في الله، وإنكارك عليهم، وتسأل الله مع هذا أن الله يهديهم في صلاتك، وفي سجودك، وفي أوقات أخرى، تسأل الله أن الله يهديهم، ويمن عليهم بالتوبة، فأنت تحب لهم الخير تسأل الله لهم الهداية، لكن تظهر لهم الجفاء والكراهة والهجر لعلهم يهتدون. فإن رجوت إسلامهم، ورجوت هدايتهم فلا تقطع عنهم الزيارة للدعوة فقط، تزورهم بين وقت وآخر للدعوة، لا لأنهم أصحاب، بل للدعوة والتوجيه لعلهم يهتدون، نعم. السائل: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13269/حكم-مجالسة-وصحبة-من-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_490/49017.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":14793,"question":"هل من كلمة للأزواج في معاملة الزوجات يا سماحة الشيخ؟","title":"نصيحة في حسن تعامل الزوج مع زوجته","answer":"الجواب: نعم، نصيحتي للأزواج أن يتقوا الله، نصيحتي لجميع الأزواج أن يتقوا الله في نسائهم، وأن يعاملوهن باللطف، والمعاملة الطيبة، كما قال الله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] بالكلام الطيب، بالأسلوب الحسن، بالحلم، بالخلق الكريم، بأداء حقوقهن كاملة، هذا الواجب على جميع الأزواج، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] مثل ما أنك تحب أن تعاشر بالمعروف، وأن تكون طيبة معك في أخلاقها وسيرتها أنت كذلك، الله يقول: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] كون حقك أكبر لك درجة زيادة لا يقتضي، هذه الدرجة ما تقتضي أنك تسيء إليها، وأنك تظلمها لا، يجب عليك أن تحسن الخلق، وأن تعاشر بالمعروف، وأن تقوم بالواجب، من جهة النفقة اللازمة بالمعروف، ومن جهة طيب الكلام، وحسن المخاطبة، هذا هو الواجب على الأزواج جميعًا أن يتقوا الله، وأن يحسنوا إلى أزواجهم بالكلام الطيب، والأسلوب الحسن، والسيرة الحميدة، وعدم السهر، وعدم التقتير في النفقة، كل هذا واجب. عليك أن تنفق بالمعروف، وعليك أن تحذر السهر الذي يضر زوجتك ويضرك، ويسبب أيضًا فساد دينك، فإن السهر شره عظيم، قد تضيع معه صلاة الفريضة، قد يكون مع أناس من أهل الشر يضرونك ويجرونك إلى أنواع الفساد، فاحذر. الرسول ﷺ نهى عن السمر بعد العشاء، فالسنة أن تأتي إلى بيتك بعد العشاء، وأن تنام مع أهلك، تستريح في بيتك، تدع السهر بعد العشاء. ويجب على الرجل أن يحذر صحبة الأشرار، صحبة الأشرار شرها عظيم، فالواجب الحذر من صحبة الأشرار، والواجب العناية بصحبة الأخيار، وعدم السهر، والعناية بالصلوات الخمس، والمحافظة عليها في الجماعة، وحسن الخلق مع الزوجة، وطيب الكلام مع الزوجة، هكذا، كما قال ﷺ: خياركم خياركم لنسائهم والله يقول وهو أعظم: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228] ويقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13285/نصيحة-في-حسن-تعامل-الزوج-مع-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56116.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":14822,"question":"المستمع (م. ق) من الرياض، بعث برسالة يقول فيها: أنا شاب كنت أرتكب المعاصي، وكلما أرتكب معصية أتوب إلى الله، وأقول: إنني سأقرأ سورة كذا وكذا توبة لله، ولكن الشيطان اللعين زين لي المعاصي واستمريت هكذا، كلما أرتكب معصية أتوب، وأقرأ مع توبتي سورة أو سورتين، واستمريت على هذا الحال حتى قسا قلبي، وفقدت حلاوة الإيمان، وأخاف أن الله ختم على قلبي، وأخاف أني منافق أخادع الله. أفيدوني، جزاكم الله خير الجزاء ماذا أعمل حتى تعود لي حلاوة الإيمان، وذهاب قساوة القلب؟ فأنا خائف من عذاب الله أرجو رحمته، والله يحفظكم.","title":"ما يجب على من يعود إلى الذنب كلما تاب منه؟","answer":"الجواب: الواجب عليك حسن الظن بالله، والمبادرة إلى التوبة، والتصميم عليها، ولزومها، والحذر من العودة إلى الذنب، والاستعانة بالله في ذلك، والصدق مع الله، وأبشر بالخير وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. والتوبة الصادقة تمحو الذنب، وإذا عدت إليه بعد توبة صادقة، ما ضرك الأول، إنما يضرك الثاني حتى تتوب منه وهكذا، فإذا كنت صادقًا في التوبة الأولى والثانية والثالثة لم يضرك ما فعلته قبل ذلك؛ لأن التوبة يمحو الله بها الذنوب، الذي يخشى منه أن تكون توبتك غير صادقة، وأن تكون أماني، أما إذا كانت التوبة صادقة جازمة قد ندمت على الماضي، وعزمت أن لا تعود، وأقلعت من ذلك فإنها يمحو الله بها الذنب الماضي. وعليك الصدق في التوبة الأخيرة، والعزم الصادق، وأن لا تعود إلى ما حرم الله عليك، وأن تستعين بالله، وتحسن به الظن، وترجو رحمته -جل وعلا-، وأن تبتعد عن صحبة الأشرار الذين قد يعينونك على المعصية، وعليك بصحبة الأخيار ولزومهم؛ فإنهم يعينون على الخير، ومن استعان بالله أعانه الله، ومن صدق مع الله يسر الله أمره، فاصدق مع الله، واجتهد، وسل ربك العون، والزم التوبة، وحاذر صحبة الأشرار، وأبشر بالخير، يسر الله أمرك، ووفقنا وإياك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13336/ما-يجب-على-من-يعود-الى-الذنب-كلما-تاب-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64315.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":14824,"question":"المستمعة (ن. م) من الكويت، تقول في رسالتها: أنا فتاة في بداية العشرينيات، وأنا وكأي فتاة تحلم بأن يمن الله عليها بزوج صالح، وذرية صالحة، ولكن المشكلة هنا أنني عندما أسمع بأن شخصًا قادمًا إلي أفرح كثيرًا، وأشكر الله، ولكني فجأة أرى نفسي حزينة، لا أريد الزواج، وكأن شيطانًا دخل إلى قلبي وأخافني، وأصبح قلقة بسبب وبغير سبب وحزينة، وأرفض هذا الشخص، ولكنني لا أعلم لماذا؟ سماحة الشيخ أنا -والحمد لله- أحب ختم المصحف، وأحب سماع القرآن الكريم كثيرًا، وأتوكل على الله في كل وقت، ولكن أشك أن هناك من عمل لي عملًا؛ لهذا الموضوع حتى لا أتزوج وحتى لا أفرح. أرجو توجيهي -جزاكم الله خيرًا- كيف أتصرف؟ وإن كنت أعلم أن النفع والضر بيد الله .","title":"توجيه لمن ترفض الزواج ولديها شكوك في سبب ذلك","answer":"الجواب: هذا من الشيطان، هذا يا ابنتي من الشيطان، فعليك أن تتعوذي بالله من الشيطان، وأن تعتمدي على الله ، وأن تحسني الظن به -جل وعلا-، فإذا خطبك من ترضين دينه وخلقه ومدح لك في دينه وأخلاقه بواسطة الثقات العارفين به، فاستعيني بالله وتزوجي، ودعي عنك هذه الوساوس وهذه الأفكار الرديئة فإنها من الشيطان، من عدو الله يثبطك بذلك، حتى تبقي في تعب ومشقة وحرمان من الزواج والذرية، والشيطان يحب كل شر للإنسان، ويدعوه إلى كل شر، هو يسره أن تبقي عانسة لا زوج لك، وربما عرضك بعد هذا لما حرم الله . فالواجب عليك تقوى الله، والمبادرة إلى الزواج إذا جاء الكفء وترك هذه الوساوس، وهذه الكراهة، وهذه البغضاء، وهذا التحرج، كل هذا من الشيطان عدو الله، ودعي عنك الوساوس، فإنه المأمون لك في هذا كله من الشيطان، لن يعمل لك شيئًا، ولكنه الشيطان يثبطك، ويسعى في منعك من الزواج؛ لأنه يحب أن كل إنسان لا يتزوج، وأن يبقى في الفساد والتعب والمشقة، نسأل الله السلامة، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/13331/توجيه-لمن-ترفض-الزواج-ولديها-شكوك-في-سبب-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64312.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات","قضايا المرأة"]},{"id":14868,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، ضمنها خمسة أسئلة، المستمع هو جمال عبده أحمد صالح الشعبي من اليمن، يقول في رسالته:أرجو من سماحة الشيخ التوجيه والنصح للآباء الذين يحتكرون بناتهم طمعًا في كثرة المهر؛ ولهذا السبب اختلط الحابل بالنابل، وأصبح الناس يتلهفون وراء المادة، ولا يبالون بمن يزوجون، والذي لديه ثروة مالية يقبل ما فرضه عليه الأب من مهر، وتكاليف باهضة، وأصبح الفقير عاجزًا عن الزواج، ولا يلتفت إليه أحد، بل ينظرون إليه بعين الاحتقار، فما هو رأي سماحتكم؟ وما هو توجيهكم؟بارك الله فيكم.","title":"نصيحة بعدم المغالاة في المهور","answer":"الجواب: الواجب على الأولياء سواءً كانوا آباءً أو إخوة أو أعمامًا أو غيرهم، الواجب عليهم تقوى الله ، وأن يخافوا الله في مولياتهم، وأن يجتهدوا في تزويجهن على الأكفاء، ولو بالمهور القليلة، وأن لا يتكلفوا في ذلك لا في المهر، ولا في الوليمة.  الواجب التماس الأكفاء الأخيار الطيبين، ولو كانوا فقراء، لكن يستطيعون المهر، ويستطيعون النفقة على زوجاتهم. وفي الحديث عنه -عليه الصلاة والسلام- أنه قال إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد عريض. فالمؤمن يتحرى الزوج الصالح لبنته وأخته وابنة أخيه ونحو ذلك، ولا يهمه المال، يهمه الرجل الصالح ولو كان المهر قليلًا، ولو كانت التكاليف قليلة، ولو كانت الوليمة قليلة، هذا هو الواجب على الأولياء، ولا يجوز لهم أن يحبسوا النساء لطلب كثرة المال، هذا غلط كبير وشر عظيم، وقد يزوجون من ليس بكفء لأجل المال، ويدعون الكفء لأجل قلة المال، وهذا منكر، وخيانة للأمانة، فالموليات أمانة عند الأولياء. فالواجب على الأولياء أن يتقوا الله في الأمانة، وأن يلتمسوا للأمانة الرجل الصالح الطيب، وإذا لم يوجد إلا ناقصون يختار الأفضل، فالأفضل والأقل شرًا، حتى لا تعطل البنات والأخوات، هذا هو الواجب على الجميع، مع تقوى الله في ذلك، والحذر من ظلم النساء، والحرص على تزويجهن بمن يخطب من الأكفاء، ولو قل المال، ولو قلت التكاليف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13366/نصيحة-بعدم-المغالاة-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64509.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":14870,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، ضمنها خمسة أسئلة، المستمع هو جمال عبده أحمد صالح الشعبي من اليمن، يقول في رسالته:أرجو من سماحة الشيخ التوجيه والنصح للآباء الذين يحتكرون بناتهم طمعًا في كثرة المهر؛ ولهذا السبب اختلط الحابل بالنابل، وأصبح الناس يتلهفون وراء المادة، ولا يبالون بمن يزوجون، والذي لديه ثروة مالية يقبل ما فرضه عليه الأب من مهر، وتكاليف باهضة، وأصبح الفقير عاجزًا عن الزواج، ولا يلتفت إليه أحد، بل ينظرون إليه بعين الاحتقار، فما هو رأي سماحتكم؟ وما هو توجيهكم؟بارك الله فيكم.","title":"نصيحة بعدم المغالاة في المهور","answer":"الجواب: الواجب على الأولياء سواءً كانوا آباءً أو إخوة أو أعمامًا أو غيرهم، الواجب عليهم تقوى الله ، وأن يخافوا الله في مولياتهم، وأن يجتهدوا في تزويجهن على الأكفاء، ولو بالمهور القليلة، وأن لا يتكلفوا في ذلك لا في المهر، ولا في الوليمة.  الواجب التماس الأكفاء الأخيار الطيبين، ولو كانوا فقراء، لكن يستطيعون المهر، ويستطيعون النفقة على زوجاتهم. وفي الحديث عنه -عليه الصلاة والسلام- أنه قال إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد عريض. فالمؤمن يتحرى الزوج الصالح لبنته وأخته وابنة أخيه ونحو ذلك، ولا يهمه المال، يهمه الرجل الصالح ولو كان المهر قليلًا، ولو كانت التكاليف قليلة، ولو كانت الوليمة قليلة، هذا هو الواجب على الأولياء، ولا يجوز لهم أن يحبسوا النساء لطلب كثرة المال، هذا غلط كبير وشر عظيم، وقد يزوجون من ليس بكفء لأجل المال، ويدعون الكفء لأجل قلة المال، وهذا منكر، وخيانة للأمانة، فالموليات أمانة عند الأولياء. فالواجب على الأولياء أن يتقوا الله في الأمانة، وأن يلتمسوا للأمانة الرجل الصالح الطيب، وإذا لم يوجد إلا ناقصون يختار الأفضل، فالأفضل والأقل شرًا، حتى لا تعطل البنات والأخوات، هذا هو الواجب على الجميع، مع تقوى الله في ذلك، والحذر من ظلم النساء، والحرص على تزويجهن بمن يخطب من الأكفاء، ولو قل المال، ولو قلت التكاليف، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13366/نصيحة-بعدم-المغالاة-في-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64509.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":14880,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يقول: سافرت أنا ووالدي إلى اليمن، فخطب لي فتاة لم أكن أعرفها، وبعد الخطوبة زرنا أهل الفتاة، فسألني أبي: ما رأيك فيها؟ فقلت له: مناسبة، وتزوجتها وأحببتها، وبعد عدة شهور بدأ الخلاف بيننا وبين الوالدين؛ لكونها تختلف مع إخوتي الصغار، والدي يقول: إنها تنقل أسرارنا إلى الجيران، وطلب مني أن أطلقها، ما هو رأيكم؟جزاكم الله خيرًا.","title":"حكم الاستجابة للوالد في طلاق الزوجة","answer":"الجواب: لا تعجل، وانصحها حتى لا تفعل ما يخالف رأي والديك من نقل أسرارهم إلى الجيران، انصحها وعلمها وخبرها أن هذا لا يجوز، وأن عليها السمع والطاعة في المعروف، فأنت تنصحها، وهي عليها السمع والطاعة، والوالدان كذلك لا يعجلان في طلب طلاقها، وينصحانها أيضًا بالكلام الطيب، والأسلوب الحسن، حتى تزول المشكلة، وحتى تستقر الأمور.  ولا تعجل في الطلاق؛ لأن هذا مرض يحتاج إلى علاج، فعليك بعلاجها بالكلام الطيب، والأسلوب الحسن، والترغيب والترهيب، وهكذا الوالدان يعالجان معك ذلك بالكلام الطيب، والأسلوب الحسن، حتى تزول المشكلة -إن شاء الله-، وتهدأ الأمور وتستمر العشرة بينكما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13376/حكم-الاستجابة-للوالد-في-طلاق-الزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64519.mp3","categories":["الطلاق","الأيمان والنذور","نصائح وتوجيهات"]},{"id":14914,"question":"نبدأ برسالة محمد بن ناصر الصالح من القصيم، يقول محمد في رسالته: سمعنا في حلقة من حلقات البرنامج (برنامج نور على الدرب) وأعتقد أنها الماضية لفضيلة الشيخ عبدالعزيز بن عبدالله بن باز، وكثير من هذه الأسئلة كان من المفروض للحجاج أن يرسلوها أو للمسلمين أن يرسلوها قبل أن يتلبسوا بالعبادة، لا أن يرسلوها بعدما يتلبسون بالعبادة، ويخطؤون، فما موقف الإسلام من ذلك؟وما رأي الشيخ جزاه الله عنا خيرًا؟","title":"توجيه بأن يتفقه المسلم قبل أن يتلبس بالعبادة","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: هذا هو الواجب، الواجب على المسلم أن يسأل قبل التلبس بالعبادة يسأل عن أمور دينه، ويتفقه في دينه قبل أن يتلبس بالعبادة، يسأل عن أمور الحج قبل أن يحرم، يسأل عن أمور الصلاة قبل أن يشرع في الصلاة، يسأل عن أمور الصيام قبل الشروع في الصيام إذا تيسر ذلك، يعني: لا يغفل، بل يبادر ويسارع إلى السؤال قبل الشغل في العبادات، لكن لو قدر أنه فرط وتساهل، ولم يسأل إلا بعد ذلك فلا حرج، المهم أنه تعلم، مثلما قال النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا سهل الله له به طريقًا إلى الجنة وقال -عليه الصلاة والسلام-: من يرد الله به خيرًا يفقهه في الدين. فالواجب على أهل الإسلام أن يتعلموا ويتفقهوا قبل أن يقعوا في الخطأ في عباداتهم، في صلاتهم، في صومهم، في حجهم، في جهادهم، في جميع أمورهم، لكن لو قدر أنه غفل وسأل بعدما صلى يعني عما جرى له في صلاته، أو عما جرى في صيامه، كل هذا طلب علم، كله واجب متعين، الله قال: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43] قبل العبادة وبعدها، قبل التلبس، وبعد التلبس، لكن كونه يتأهب، كونه يسأل قبل أن يتلبس، كونه يعد نفسه إعدادًا كاملًا، حتى إذا شرع في العبادة، إذا هو يؤديها عن علم وعن بصيرة، هذا هو الواجب، وهذا هو الطريق السليم، نعم.","link":"https://binbaz.org.sa/fatwas/13413/توجيه-بان-يتفقه-المسلم-قبل-ان-يتلبس-بالعبادة","audio":"","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":14944,"question":"وهذه رسالة المستمع (س. ق. ع) يقول: رجل أراد السفر لطلب العلم، وله أهل من الزوجة والأولاد، وشاور مع زوجته في طلاقها، وعدم نفقتها، وقالت: لا تطلقني، وقد عفوت عن نفقتي وخلافه، فهل تبقى بدون نفقة ولا يضره شيء أم لا؟","title":"حكم تنازل المرأة عن النفقة مقابل عدم طلاقها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالحق للمرأة لا لغيرها، فإذا سمحت عن نفقتها فلا حرج، ويجوز للزوج إبقاؤها في عصمته من دون أن ينفق عليها إذا سمحت، ومتى عادت وطلبت النفقة فإنه يخير، إما أن ينفق، وإما أن يطلق، نعم.","link":"https://binbaz.org.sa/fatwas/13440/حكم-تنازل-المراة-عن-النفقة-مقابل-عدم-طلاقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64901.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":14959,"question":"هذه السائلة من أسئلتها هذا السؤال تقول: بأنها تعاني من الوسواس، حيث أنني -تقول-: عندما أذكر الله أو أسبح أظل أعيد وأعيد حتى أبكي، فما العلاج في نظركم في ذلك؟","title":"توجيه لمن تعاني من الوساوس","answer":"الجواب: التعوذ بالله من الشيطان، كلما جاء الوسواس تقول: أعوذ بالله من الشيطان الرجيم، تتعوذ في صلاتها، وإذا كثر عليها تنفث عن يسارها ثلاث مرات، وتقول: أعوذ بالله من الشيطان الرجيم، ثلاث مرات، كما أمر النبي ﷺ بهذا عثمان بن أبي العاص؛ لما قال: إنه كثر علي الوساوس، وإن الشيطان شغلني عن صلاتي، فقال: قل كذا، فقال له: انفث عن يسارك ثلاث مرات، وقل: أعوذ بالله من الشيطان، ثلاث مرات قال عثمان: ففعلت هذا، فأذهب الله عني ما أجد». فالمقصود: أن الإنسان إذا عرض له الوساوس في الصلاة يدافعها بالتعوذ بالله من الشيطان، ويحرص على إحضار قلبه في صلاته، فإذا كثر عليه ذلك ينفث عن يساره ثلاث مرات، ويقول: أعوذ بالله من الشيطان الرجيم، ثلاث مرات، وهذا من أسباب السلامة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13453/توجيه-لمن-تعاني-من-الوساوس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56214.mp3","categories":["الأدعية والأذكار","قضايا المرأة","نصائح وتوجيهات"]},{"id":15002,"question":"الأخت السائلة من الأردن تقول: ما هو الدعاء الذي ينصحني سماحة الشيخ بترديده وبالإكثار منه؟جزاكم الله خيرًا.","title":"استحباب الإكثار من طلب المغفرة","answer":"الجواب: طلب المغفرة، الإكثار من طلب المغفرة، اللهم اغفر لي، اللهم ارحمني، اللهم أصلح قلبي وعملي، النبي ﷺ كان يكثر من الاستغفار -عليه الصلاة والسلام-، ومن جوامع الكلام، وكان يكثر من قوله: سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك اللهم وأتوب إليك ويكثر من قوله: اللهم اغفر لي وتب علي فأنت أكثري من الاستغفار والتوبة والتسبيح، سبحانك الله وبحمدك، اللهم اغفر لي، نعم.","link":"https://binbaz.org.sa/fatwas/13501/استحباب-الاكثار-من-طلب-المغفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56224.mp3","categories":["الأدعية والأذكار","الرقائق","نصائح وتوجيهات"]},{"id":15005,"question":"الأخت السائلة من الأردن تقول: ما هو الدعاء الذي ينصحني سماحة الشيخ بترديده وبالإكثار منه؟جزاكم الله خيرًا.","title":"استحباب الإكثار من طلب المغفرة","answer":"الجواب: طلب المغفرة، الإكثار من طلب المغفرة، اللهم اغفر لي، اللهم ارحمني، اللهم أصلح قلبي وعملي، النبي ﷺ كان يكثر من الاستغفار -عليه الصلاة والسلام-، ومن جوامع الكلام، وكان يكثر من قوله: سبحانك اللهم وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك اللهم وأتوب إليك ويكثر من قوله: اللهم اغفر لي وتب علي فأنت أكثري من الاستغفار والتوبة والتسبيح، سبحانك الله وبحمدك، اللهم اغفر لي، نعم.","link":"https://binbaz.org.sa/fatwas/13501/استحباب-الاكثار-من-طلب-المغفرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56224.mp3","categories":["الأدعية والأذكار","الرقائق","نصائح وتوجيهات"]},{"id":15070,"question":"سماحة الشيخ ما هي أشهر كتب التفسير التي تنصحون المسلم بالرجوع إليها، والتزود منها؟","title":"أهم كتب التفسير التي ينصح بقراءتها","answer":"الجواب: أشهر كتب التفسير وأحسنها: تفسير ابن جرير -رحمه الله-، تفسير عظيم ومفيد، تفسير ابن أبي حاتم، تفسير الحافظ ابن كثير -رحمه الله-، هذه الكتب أشهر التفاسير؛ وكذلك البغوي -رحمه الله- تفسير عظيم، تفسيره تفسير عظيم، فنوصي بها كثيرًا، فإنها من الكتب العظيمة المعتنية بالكتاب والسنة. وهناك كتب أخرى مفيدة، مثل: تفسير الشوكاني، وتفسير الشيخ صديق، وتفاسير أخرى، لكن هذه الكتب الأولى هي الإمام في هذا المقام، تفسير ابن جرير -رحمه الله-، تفسير ابن أبي حاتم، والبغوي وابن كثير، هذه الكتب لها الأهمية والتقدمة، نعم. والكل يخطئ ويصيب ما أحد معصوم، قد يقع في بعضها أشياء من الخطأ والغلط، ولكن المعول على الأدلة الشرعية، ليس ابن جرير، ولا ابن كثير، ولا البغوي، ولا ابن أبي حاتم ولا غيرهم، ليس واحد معصومًا من الخطأ، لكن على طالب العلم، وعلى من يراجع كتب التفسير أن يعتني بالأدلة الشرعية، وإذا أشكل عليه شيء يعرض ذلك على القرآن العظيم، والسنة المطهرة الصحيحة، أو يسأل أهل العلم إن كان ما عنده علم، يسأل أهل العلم من أهل السنة والجماعة من علماء السنة، يسألهم عما أشكل عليه، نعم. ومن كتب التفسير المهمة كما تقدم، تفسير أيضًا الشنقيطي -رحمه الله-، الشيخ: محمد أمين الشنقيطي أيضًا هو من التفاسير المهمة، وقد اعتنى به -رحمه الله-، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13561/اهم-كتب-التفسير-التي-ينصح-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56402.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":15076,"question":"هذه أيضًا مشكلة عائلية، وسببها الأخ الحمو، يقول مرسلها المراسل فوزي محمد النجار، يقول: عندما عدت إلى بلدي بعد فترة عمل هنا -ويقصد يعني في السعودية بعد عمل ثلاثة عشر شهرًا- وبعد أن جلست فترة قالت لي زوجتي: إن أخوك يحضر إلى هنا، وأنا أقابله بملابس بدون أكمام بحسب كلامها، وقد قلت لها: إن هذا اللباس حرام، ولم أعط الأمر أي اهتمام، ولكن قبل أن أسافر بيومين قال لي صاحب المنزل الذي أسكن فيه: إن أخوك يحضر إلى منزلك الساعة اثنا عشر ليلًا، ولم يزد على ذلك بكلمة، وكان كلامه معي في مكان عام، وكنت مشغول مع والدي وبعض الناس، ومن كثرة مشاغلي بسبب تحضير أوراق السفر لم أفكر في هذا الموضوع، وعندما عدت إلى هنا لم أعط أي اهتمام، ولكن بعد فترة أخذت زوجتي ترسل إليَّ خطابات، ومن هذه الخطابات أن أخي المذكور لا يذهب لرؤية أولادي، فكتبت لها إنني علمت أن أخي يحضر إلى البيت الساعة اثنا عشر ليلًا، وهذا الوقت غير مناسب، ويمضي أيضًا في رسالته ويقول: إنني بعثت له رسالة، وعرضها على الوالد، والوالد كأنه جاء في باله أو في خاطره شيء، يسأل عن حل هذه المشكلة، وما حكم هذا العمل؟","title":"حكم الخلوة بزوجة الأخ والظهور أمامه بلباس دون أكمام","answer":"الجواب: لا شك أن خروجها إلى أخيك بلباس ليس له أكمام، وسفورها لديه بوجهها ورأسها، ونحو ذلك كله حرام، كله منكر ومن أسباب الفتنة، ومن أسباب وقوع الفاحشة، فالواجب الإنكار عليها، وتحذيرها من هذا العمل، والواجب الإنكار على أخيك أيضًا، وأن ينكر عليها، وألا يسمح لها بأن تقابله هذه المقابلة؛ لأن المسلم ينكر المنكر، ويخاف الله ويرجوه ، ولا يرضى في أهله، ولا في أهل أخيه ما حرمه الله ، وليس له أن يخلو بها، لا في الليل، ولا في النهار، وليس له أن يجيء إليها في نصف الليل، وهي في بيت وحدها، فهذا محل الريبة، ومحل الشر.  فالواجب منعه من ذلك وإخباره بأن الواجب عليه أن يأتي إليها في وقت ليس فيه خلوة، بل عند الناس عند أبيه أو أمه، ونحو ذلك، فلا يخلو بها وحدها أبدًا، لا في الليل، ولا في النهار؛ لأن النبي ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما ولأن الخلوة وسيلة إلى وقوع الفاحشة. فالواجب عليك -أيها السائل- أن تحرص على منعها من هذه المقابلة السيئة، لا مع أخيك، ولا مع غيره، بل تكون متسترة متحجبة مع جميع الأجانب؛ لأن أخاك في حكم الأجنبي ليس بمحرم، وعليها أن تقابل غير المحارم بالستر والحجاب، وعلى أخيك أن يتقي الله وأن يحذر مقابلتها على حالة سيئة، أو المجيء إليها في وقت لا يناسب؛ لأنه يتهم في هذه الحال بما يحرم الله ؛ ولأن تركها على حالها، وعدم الإنكار عليها من باب التعاون على الإثم والعدوان، وإذا أمكنك -يا أخي- إحضارها، وأن تكون معك، فهذا هو الذي ينبغي، حتى تسلم من هذه الفتنة، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13591/حكم-الخلوة-بزوجة-الاخ-والظهور-امامه-بلباس-دون-اكمام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_664/nour_66403.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة","نصائح وتوجيهات"]},{"id":15094,"question":"يقول: ما هي نصيحتكم لرجل بلغ الستين من عمره، وهو لا يدع قول الكذب، وأيضًا يغتاب الناس؟","title":"نصيحة لمن ابتلي بالكذب وغيبة المسلمين","answer":"الجواب: يجب عليه أن يتقي الله، ويحذر الكذب والغيبة، سواءً كان ابن ستين أو أقل أو أكثر، الكذب محرم على جميع الناس، فليس له أن يكذب، ولو كان في الشباب، وليس له أن يكذب ولو كان ابن مائة سنة.\nوعليه أن يحذر الغيبة أيضًا، الله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12].\nوالكذب من أقبح الخصال، وهو من خصال المنافقين، فيجب الحذر منه، وإذا كان كبير السن كان أشد في الإثم، نسأل الله العافية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13592/نصيحة-لمن-ابتلي-بالكذب-وغيبة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_494/49405.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":15131,"question":"وردتنا رسالة من بيشة، بعث بها المرسل يحيى سعد مخيلي الشهراني، يقول: تزوجت فتاة، وكان عمرها سبعة عشر سنة، ثم بقيت عند أهلها سبعة عشر سنة أخرى، وأنا لم أدخل بها، وأنها تحبني وأحبها، ولكن أهلها منعوها من الزواج الفعلي، أي: الدخول بالمعنى المعروف، وأخيرًا طلقتها، ثم خطبت زوجة أخرى، وحصل معها ما حصل مع الأولى، فهل أطلقها؟ أم أن هناك رأيًا للشرع آخر؟علمًا بأنني متزوج من امرأة، وعندي منها أطفال، وأنا أرغب في الزواج من الثانية، وفقكم الله.","title":"حكم منع الولي موليته من الدخول على زوجها بعد العقد","answer":"الجواب: الواجب على أولياء الزوجة أولياء المرأة وأهلها من أم وأخت وخالة ونحو ذلك، أن يساعدوا على الخير، وأن يشجعوا على الجمع بين الرجل وأهله، وأن لا يعطلوا المرأة عن زوجها، لا قبل العقد، ولا بعد العقد.  فإذا تم العقد فالواجب البدار بإدخالها على زوجها، وتمكينه منها؛ حتى يحصل المقصود بالنكاح من قضاء الوطر، وعفة الفرج، وغض البصر، ووجود النسل والذرية للجميع، هذا هو الواجب، ولا يجوز لأمها ولا لأبيها ولا لأوليائها تعطيلها من الزواج، ولا تعطيلها من دخولها على زوجها بعد العقد، هذا هو الواجب عليهم. وكثير من الناس -والعياذ بالله- لا يبالي بموليته، ولا يهتم منها، بل يعطلها كثيرًا؛ إما لخدمتها في بيته، وإما لرعيها غنمه، وإما لغضبه على أمها، أو غضبه عليها لأسباب صار ذلك؛ فيظلمها، ويتعدى عليها، ويحبسها عن الزواج لما في نفسه من الشر عليها، أو على أمها، أو على إخوتها الخاصين بها، أو نحو ذلك، وهذا ظلم وعدوان لا يجوز، بل الواجب عليه أن يتقي الله، وأن يبادر بتزويج موليته، سواء كان أخاها، أو أباها أو عمها، وأن لا يعطلها، ثم إذا تم العقد فالواجب أيضًا أن لا يعطلها، بل عليه -الولي- أن يبادر بإدخالها على زوجها، أو إدخاله عليها إن كان الدخول عليها في بيتهم، أما التعطيل فهو منكر، وهذا واقع في كثير من الناس، يعطلون بناتهم وأخواتهم لأسباب خبيثة ظالمة، إما لتخدم بيته، وتخدم زوجته، أو لتخدمه في رعي غنمه، أو لأسباب أخرى، وهذا لا شك أنه منكر وحرام عليه، وإثم وظلم. وبعد العقد كذلك لا يجوز تعطيلها أيضًا، بل يجب البدار بإدخالها على زوجها، وتمكينه منها، حتى يحصل المقصود من النكاح، والله يقول -جل وعلا-: وَمَنْ يَظْلِمْ مِنْكُمْ نُذِقْهُ عَذَابًا كَبِيرًا [الفرقان:19] فالظلم قبيح، وشره عظيم، ويقول ﷺ: اتقوا الظلم، فإن الظلم ظلمات يوم القيامة وحبس النساء عن الزواج -سواء كن بنات أو أخوات أو غيرهن- ظلم وعدوان، وهكذا حبسهن بعد العقد، وعدم إدخالهن على أزواجهن ظلم وعدوان.  فأرجو ممن يسمع كلامي هذا أن يبلغه غيره، وأن ينصح من يعلم منه هذا العمل الخبيث هذا المنكر؛ فينصحه لله، ويحرضه على تزويج موليته، وعدم حبسها ظلمًا وعدوانًا. وعلى ولاة الأمور إذا علموا ذلك أن يعاقبوا من فعل هذا، على القضاة والأمراء وولاة الأمور جميعًا عليهم أن يعاقبوا من عرف بهذا الظلم لموليته؛ فإنه يستحق العقاب ردعًا له ولأمثاله عن هذا الظلم، والقاضي أخص بهذا؛ فإنه يعلم من هذه الأمور ما لا يعلمه غيره، فالواجب على القضاة أن يهتموا بهذا، وأن يحكموا بتعزير وتأديب من يعرف بهذا الأمر رجاء السلامة من هذا الظلم لهؤلاء النساء، نعم، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13632/حكم-منع-الولي-موليته-من-الدخول-على-زوجها-بعد-العقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_657/nour_65704.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":15136,"question":"في ثالث أسئلة هذا السائل يقول: بحكم طلب العيش فقد تشتت الأسر، وأصبح من الصعب أن نصل أرحامنا، هل في ذلك إثم علينا -يا فضيلة الشيخ- رغم تباعد المسافات؟","title":"توجيه لمن أرحامه بعيدون ولا يستطيع صلتهم","answer":"الجواب: عليك أن تتقي الله ما استطعت؛ لأن الله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] صل رحمك بما تستطيع إذا كانوا فقراء وأنت قادر تواسيهم من مالك، ولو بالمراسلة، ترسل لهم ما تيسر من المال، وإذا كانوا أغنياء ولو بالمكاتبة أو بالهاتف: كيف حالكم؟ كيف أنتم؟ من باب السلام والاطمئنان عن صحتهم، ويكفي هذا، والحمد لله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13635/توجيه-لمن-ارحامه-بعيدون-ولا-يستطيع-صلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56409.mp3","categories":["نصائح وتوجيهات"]},{"id":15142,"question":"يطلب من سماحتكم -جزاكم الله خيرًا- يقول: أن ترشدوني إلى بعض الكتب التي تنهى عن البدع والحلف بالأولياء، وهل هناك بدع حسنة؟","title":"كتب تنهى عن البدع ينصح بقراءتها","answer":"الجواب: نعم، نرشد إلى كتاب فتح المجيد، وكتاب التوحيد، كتاب التوحيد للشيخ: محمد عبد الوهاب، وفتح المجيد لحفيده الشيخ: عبدالرحمن بن حسن، والبدع والنهي عنها للشيخ ابن وضاح -رحمه الله-، والاعتصام للشاطبي -رحمه الله-، كل هذه فيها التحذير من البدع.  ويكفي قول النبي ﷺ: خير الكلام كلام الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة ما أحدث الناس في الدين من عبادة لم يشرعها الله اجتنبها واحذرها، ولكن تشتغل بالكتب التي ذكرنا وغيرها من الكتب المعروفة في بيان السنة، وبيان البدعة، وإذا أشكل عليك شيء تسأل أهل العلم من أهل السنة والجماعة. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13639/كتب-تنهى-عن-البدع-ينصح-بقراءتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56411.mp3","categories":["البدع والمحدثات","نصائح وتوجيهات"]},{"id":15148,"question":"أيضًا تقول الأخت فاطمة بنت علي من القصيم: هل يعتبر زانيًا الشخص يجعل في بيته خادمة شابة نضيرة، ويجلس معها، ويمزح معها؟ وما هو دوركم -وفقكم الله- يا فضيلة الشيخ في ذلك تقصد في ذلك جميع العلماء؟","title":"التحذير من استقدام الخادمات الجميلات والخلوة بهن","answer":"الجواب: لا يعتبر زانيًا، لكن يكون قد تسبب في الزنا، لا يعتبر زانيًا بكونه جعلها في بيته وحادثها، لكنه قد تعاطى أسباب الزنا، وفعل أمرًا منكرًا، فالذي ينبغي أن لا يستقدم إلا المرأة الكبيرة، والمرأة التي ليست نضيرة، ينبغي إذا دعت الضرورة إلى استقدامهم أن تكون امرأة طاعنة في السن، وأن تكون غير جميلة؛ لأن هذا أبعد عن الشر، ويكون في البيت من يخالطها من النساء؛ حتى لا يخلو بها.  فينبغي له أن لا يستقدم امرأة أجنبية إلا إذا كان عنده في البيت غير زوجته؛ حتى تكون الخلوة منتفية، وحتى يكون هذا أبعد عن الشر، وأن تكون طاعنة في السن وغير جميلة، كل هذه يجب أن يحتاط لها، وأن يحرص على وجودها؛ بعدًا عن الشر، واحتياطًا للدين؛ لأن الواجب على المسلم أن يحتاط لدينه، وأن يبتعد عن أسباب الشر مهما أمكن، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/13650/التحذير-من-استقدام-الخادمات-الجميلات-والخلوة-بهن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_658/nour_65805.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة","نصائح وتوجيهات"]},{"id":15160,"question":"الأخ علي عبدالحي القحطاني له ستة اقتراحات بالنسبة للبرنامج هي: تكرار عنوان المراسلة، وتسجيل الحلقات على كاسيت وتوزيعها، وتدوين الأسئلة، ثم نشرها، وإعادة بعض الأسئلة المفيدة، وزيادة مدة البرنامج، والإجابة على أسئلته المرفقة في رسالته هذه.ونقول للأخ علي اقتراحاتك موضع الاهتمام، وبعضها ينفذ الآن.وسؤال الأخ علي عبدالحي القحطاني من خميس مشيط الأول يقول: تنتشر في الجنوب من بلادنا عادة سيئة، وأقول: (تنتشر) لأن تسعة وتسعين من سكان هذه البلاد يفعلونها، ألا وهي عدم تغطية المرأة لوجهها أمام الرجال الأجانب، وخصوصًا الأقارب.أرجو بيان ذلك بيانًا شافيًا وكافيًا، وتخويف من يفعل ذلك من عقاب الله.وفقكم الله.","title":"حكم كشف المرأة وجهها أمام الأجانب","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد:\nفإن هذه العادة التي ذكرها السائل وهي تساهل النساء في الجنوب بكشف الوجه عند غير المحارم لا شك أنها عادة سيئة، وأن الواجب على المرأة التحجب عن غير محارمها، وعدم كشف الوجه عند أخي الزوج، أو عم الزوج، أو زوج الأخت، أو أبناء العم، ونحو ذلك، كل هذا لا يجوز؛ لأن الله سبحانه يقول في محكم التنزيل: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] فأخبر سبحانه أن الحجاب أطهر لقلوب الجميع، وأمر به سبحانه.  فالواجب على الرجال والنساء الأخذ بذلك، والتعاون في ذلك، وعلى المرأة أن تخاف الله وتراقبه، وأن تحذر ما حرم عليها . وقال  في سورة النور: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ[النور:31] الآية، والزينة تشمل كشف الوجه، وغير ذلك، فالوجه من أعظم زينتها، وهكذا حليها في حلقها، وفي يديها، وفي أذنيها، كل هذه من الزينة التي يجب سترها، وهكذا ما يكون في رجليها من الخلاخل كله زينة يجب سترها، وعلى المرأة وعلى وليها وزوجها أن يخافوا الله جميعًا، وأن يتعاونوا على البر والتقوى، وأن يحذروا ما حرم الله عليهم. ومن المعلوم: أن إظهار الزينة والمحاسن من المرأة من أسباب الفتنة بها، ومن أسباب وقوع الفواحش، فعلى الجميع تقوى الله في ذلك والحذر من غضبه ، نعم.","link":"https://binbaz.org.sa/fatwas/13653/حكم-كشف-المراة-وجهها-امام-الاجانب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66506.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","اللباس والزينة"]},{"id":15168,"question":"متى يقرأ الشخص دعاء الاستخارة في صلاته؟ هل عندما ينتهي من التشهد قبل التسليم، أو أن ذلك من الممكن أن يكون بعد التسليم؟","title":"موضع دعاء الاستخارة","answer":"الجواب: دعاء الاستخارة يكون بعد التسليم، يشرع له أن يصلي ركعتين، وبعد التسليم يرفع يديه ويدعو ويستخير، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13662/موضع-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56418.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":15174,"question":"متى يقرأ الشخص دعاء الاستخارة في صلاته؟ هل عندما ينتهي من التشهد قبل التسليم، أو أن ذلك من الممكن أن يكون بعد التسليم؟","title":"موضع دعاء الاستخارة","answer":"الجواب: دعاء الاستخارة يكون بعد التسليم، يشرع له أن يصلي ركعتين، وبعد التسليم يرفع يديه ويدعو ويستخير، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13662/موضع-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56418.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":15247,"question":"هذه رسالة من السائل علي محمد ياسين، من اليمن، تعز، يقول: أنا شاب أقيم في المملكة العربية السعودية، بحثًا عن الرزق الحلال، ومشكلتي هو والدي فهو سيئ التعامل معنا منذ صغري، فقد تركني عند والدتي، وهجرنا من كل شيء، إلى أن كبرت وهو لا يعرفني، وأنا لا أعرفه، نتيجة هجره لنا، ثم بعد أن كبرت سافرت إلى المملكة للعمل، وكنت أبعث نقودًا بقصد التزوج بها، ولكنه كان يأخذها، ويقول لمن أريد التزوج منهم: ابني متوفى، ثم أرسلت النقود مرة أخرى إلى أهل مخطوبتي، ولكنه حينما علم بذلك رفع عليهم دعوى بقصد أخذ ما دفعته لهم من مال، بحجة أنني متوفى، وبعد ذلك رجعت إلى بلدي لأبحث معه هذا الوضع السيئ، ولكنه استقبلني أسوأ استقبال، وهددني بكل سوء إن أنا رفضت إعطاءه ما جمعته من مال، مما جعلني أفر منه ومن معاملته، وأقطع صلته. فما هي نصيحتكم لهذا الأب؟ وبماذا ترشدوني؟أفيدوني، بارك الله فيكم.","title":"نصيحة لمن يعامله أبوه معاملة قاسية ويعرقل زواجه","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن حق الوالد عظيم، وبره واجب، وننصحك بأن تعامله بالتي هي أحسن، وتلتمس الزواج في جهة أخرى من بنات اليمن الموجودات في المملكة، أو في اليمن الشمالي، وتحسن إليه إذا كان فقيرًا بما يتيسر، إذا كان فقيرًا تحسن إليه بما يسر الله لك، وتخاطبه بالتي هي أحسن؛ لأن البر بالوالدين أمره عظيم، والله سبحانه يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا[الإسراء:23] والنبي ﷺ لما سئل: أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي يا رسول الله؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فجعل بر الوالدين مقدم على الجهاد في سبيل الله، فبرهما عظيم، وأمر لازم. فنوصيك بالإحسان إليه، ومخاطبته بالتي هي أحسن، والدعاء له بالهداية والتوفيق، وحسن الخاتمة، وتترك الخطبة من الناس الذين حوله، لعلك تجد امرأة أخرى في جهة أخرى، والنساء كثير، في اليمن الشمالي في المملكة العربية السعودية حتى لا يحصل بينك وبين أبيك ما لا تحمد عقباه، وإن تيسر أن الذين خطبت منهم يتوجهون بها إلى المملكة، وتزوج هنا في المملكة بها فهذا خير كبير، وفيه مصلحة لك وراحة من المشاقة لأبيك، نسأل الله لنا ولك الهداية والتوفيق. وبكل حال نوصيك بالرفق بوالدك، والإحسان إليه، والتماس الطريق الصالحة التي تمكنك من الزواج من دون مشقة بينك وبين أبيك، سواء بالبنت التي خطبتها أو بغيرها، نسأل الله لك التيسير والتسهيل.\nالمقدم: لكن فعل والده بأن ادعى وفاة ابنه طمعًا في الحصول على المال؟ الشيخ: هذا منكر، كلام والده غلط، كونه كذب عليه، وكونه يمنعه من الزواج، هذا ظلم من والده غلط، لكن الوالد يُتحمل، يُتحمل ولو جرى منه هذا الغلط وهذا المنكر، لا بد من التحمل.\nالمقدم: إنما هو مخطئ في عمله هذا. الشيخ: مخطئ لا شك، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/13772/نصيحة-لمن-يعامله-ابوه-معاملة-قاسية-ويعرقل-زواجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68101.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":15263,"question":"سماحة الشيخ، تساهل الكثير من الناس في الانصراف عن أطفالهم، يبلغون الحادية عشرة، والثانية عشرة وهم مهملون لهم، هل من توجيه للآباء والأمهات؟","title":"توجيه لمن يهملون أولادهم ولا يحثونهم على الصلاة","answer":"الجواب: نعم، لا يجوز هذا، الواجب على الآباء والأمهات توجيه الأولاد ونصيحتهم، إذا بلغ سبعًا أن يؤمر بالصلاة، والمرأة والبنت تؤمر بالصلاة وتعلم، والولد كذلك يؤمر ويعلم، ويخرج به أبوه أو أخوه إلى المسجد، وإذا بلغ عشرًا يضرب؛ لقوله ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر، وفرقوا بينهم في المضاجع هذا هو الواجب، متى بلغ عشرًا فأكثر يؤمر بالصلاة مع الناس، ويضرب إذا تخلف، يضربه أبوه أو أخوه الكبير أو عمه، أما إذا بلغ الحلم، فإنها تجب عليه تكون فريضة، إذا تركها كفر، نسأل الله العافية.  أما ابن سبع وابن ثمان وابن تسع هذا يؤمر ولا يضرب، نعم، الله المستعان. المقدم: الله المستعان، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13756/توجيه-لمن-يهملون-اولادهم-ولا-يحثونهم-على-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_565/56511.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15269,"question":"المستمع المحتار، كما وصف نفسه (م. س. ح. ن) من منطقة تربة، بعث يقول: لدي مشكلة وهي الخجل من الناس، إنني لا أستطيع المجالسة معهم، ولا أستطيع مقابلتهم أدنى مقابلة، وأنا أعيش في حالة رهيبة، أرجو أن توجهوني.علمًا بأنني أصلي، وأدعو الله كثيرًا، وعمري في الثامنة عشرة.","title":"نصيحة لمن يمنعه الخجل من مقابلة الناس","answer":"الجواب:  عليك -بارك الله فيك- أن تسأل الله أن يزيل من قلبك هذه الأوهام وهذه التوهمات، وهذا الخجل، تسأل ربك أن يزيل هذا من قلبك، وتجاهد نفسك في الجلوس مع زملائك، ومع الإخوان، ومع أهلك، وأي شيء في هذا، هذا كله من الشيطان، هذا الخجل من الشيطان، فتقول: أعوذ بالله من الشيطان الرجيم، وتعزم على نفسك في الجلوس مع الناس، والتحدث مع الزملاء، ومع الأهل والأقارب، حتى يزول هذا، في المساجد، في حلقات العلم، في البيت، في التزاور مع إخوانك، جاهد نفسك؛ لأن هذا لا يليق بالرجل، بل هذا من الشيطان، فينبغي لك أن تجاهد نفسك، وأن تسأل الله -جل وعلا- أن يعينك على ذلك، وأن يزيل من قلبك هذه الأوهام، وهذا الخجل الذي لا وجه له، وأبشر بالخير متى صدقت يسر الله أمرك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13769/نصيحة-لمن-يمنعه-الخجل-من-مقابلة-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49709.mp3","categories":["نصائح وتوجيهات"]},{"id":15367,"question":"السائلة تقول: بأنها فتاة تحفظ القرآن، ولكن كثيرة النسيان، فهل عليها إثم في ذلك لكثرة المشاغل المنزلية وغير ذلك؟ فبماذا تنصحونها سماحة الشيخ؟","title":"نصيحة لمن تحفظ القرآن وتنسى لكثرة مشاغلها","answer":"الجواب: أنصحها تجتهد في حفظ القرآن، ولا يضرها لو نسيت فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] النبي ﷺ قد ينسى بعض الآيات وهو رسول الله، ويقول: إنما أنا بشر أنسى كما تنسون فلا حرج إذا وقع النسيان. أما حديث: من حفظ القرآن ثم نسيه لقي الله وهو أجذم فهذا الحديث غير صحيح، حديث الوعيد هذا غير صحيح، الإنسان يجتهد في حفظ القرآن، ويحرص ويعمل الأسباب والتوفيق بيد الله، ولا بد من نسي بعض الآيات أو بعض السور فلا حرج، وعليه المجاهدة.","link":"https://binbaz.org.sa/fatwas/13870/نصيحة-لمن-تحفظ-القران-وتنسى-لكثرة-مشاغلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49910.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":15369,"question":"هذا السائل (أ. أ. أ) من جمهورية مصر العربية، يقول: بعض الناس إذا أراد أن يبارك للمتزوج يقول له: بالرفاه والبنين يا فلان، فهل هذا يجوز يا شيخ؟","title":"دعاء التهنئة المشروع لمن تزوج","answer":"الجواب: كان هذا من دعاء الجاهلية، فعوض الله المسلمين بغيره بارك الله لك وعليك، وجمع بينكما في خير هذا السنة، السنة أنه يدعى للتزوج بارك الله لك وعليك، وجمع بينكما في خير هذا هو السنة، نعم.","link":"https://binbaz.org.sa/fatwas/13872/دعاء-التهنىة-المشروع-لمن-تزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_499/49912.mp3","categories":["نصائح وتوجيهات","الزواج وأحكامه"]},{"id":15390,"question":"هل من توجيه -يا سماحة الشيخ- للذين يتأخرون عن صلاة الجمعة هذا اليوم العظيم؟","title":"الحث على التبكير لصلاة الجمعة","answer":"الجواب: الواجب على كل مسلم أن يبادر إلى الجمعة قبل الأذان الأخير؛ لأن هذا الأذان بعده الخطبة؛ فالواجب أن يبادر حتى يسمع الخطبة ويحضر الصلاة، والله -جل وعلا- بين لعباده أن الواجب إذا نودي للصلاة بالجمعة أن يذروا البيع، ويتركوا المشاغل. فالواجب على المؤمن أن يتحرى الوقت المناسب يوم الجمعة، ويفرغ نفسه حتى يبكر لها، يصلي ما تيسر، يقرأ من القرآن ما تيسر، حتى إذا جاء الخطيب، فإذا هو قد فرغ من صلاته، وقراءته التي أراد. المقصود: أن المشروع للمؤمن أن يبكر، ويبادر إلى الجمعة، والذي يأتي لها في أول الوقت كالمهدي بدنة، والذي يليه كالمهدي بقرة، والذي يليه كالمهدي كبش، والذي يليه كالمهدي دجاجة، والخامس كالمهدي بيضة.  فالمشروع للمؤمن أن يبادر ويسارع قبل الأذان الأخير، حتى إذا أذن الأخير إذا هو حاضر قد فرغ، وقد استعد لسماع الخطبة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13891/الحث-على-التبكير-لصلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56716.mp3","categories":["صلاة الجمعة","نصائح وتوجيهات"]},{"id":15417,"question":"هذا آخر سؤال في حلقتنا اليوم من السائل محمد حمد الرحال، من الإمارات العربية، أبو ظبي، يقول: لي إخوة وأقارب لكنهم للأسف الشديد لا يصلون، ولا يقيمون حدود الله، فهل علي أن أقاطعهم؟ فكلما آمرهم بمعروف، أو أنهاهم عن منكر يهزؤون مني، ويسخرون، ويقولون: هل تريد أن تصلح الناس جميعًا؟ وقد كرهوا هم مجالستي، وقاطعوني، فماذا علي أن أفعل تجاههم؟","title":"توجيه لمن يسخر منه أقاربه عند نصحهم","answer":"الجواب: عليك أن تهجرهم وتقاطعهم ما داموا لم يقبلوا النصيحة، وهم على الحال التي ذكرت من قطعهم الصلاة، وبعدهم عن الخير، فينبغي لك أن تهجرهم، وأن تقاطعهم حتى يهديهم الله، هذا هو الواجب، بل هذا هو السنة المؤكدة، وبعض أهل العلم يرى وجوب ذلك وجوب المهاجرة والقطيعة لهم لضلالهم، وبعدهم عن الخير. لكن إذا اتصلت بهم بعض الأحيان، رجاء أن يهديهم الله بالدعوة والتوجيه والإرشاد فلا بأس، وإن يئست منهم فلا مانع من هجرهم ومباعدتهم بالكلية، وقد هجر النبي ﷺ ثلاثة من الصحابة؛ لما تركوا الغزوة معه بغير عذر.  فالحاصل: أن هؤلاء ينبغي أن يهجروا وعلى الأقل يكون هجرهم سنة مؤكدة حتى يهديهم الله، ويردهم إلى الصواب.\nنسأل الله لنا ولهم الهداية. المقدم: اللهم آمين، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/13928/توجيه-لمن-يسخر-منه-اقاربه-عند-نصحهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_684/nour_68417.mp3","categories":["نصائح وتوجيهات","الدعوة والدعاة"]},{"id":15427,"question":"تقول هذه السائلة: امرأة علمت بمصيبة لي وذهبت تنشرها بين النساء وبين الناس، فهل يجوز أن أنتقم لنفسي بفضحي ونشر عيوبها وتخريب بيتها؟ وهل يجوز لي ذلك؟","title":"حكم مقابلة السيئة بسيئة مثلها","answer":"الجواب: لا يجوز لك ذلك، لكن تنصح، ويبين لها أن هذا لا يجوز، وإذا ظلمك لا تظلمها، وإذا اغتابت لا تغتبها، وهكذا، ولكن تنصحها، وتنظر من ينصحها، ويوجهها إلى الخير، ويعلمها أن هذا منكر، وأنه لا يجوز، ولكن لا تعاقبها بنشر بعض مساويها؛ لأن نشر المساوي من الغيبة، والله حرم الغيبة ، ومن أسباب الفتنة والشر العظيم، والعداوة الكثيرة، فإذا ظلمتك فلا تظلمها أنت، ولكن تدعو الله لها بالهداية، وتنصحها، وتدعو بعض إخوانك الذين يؤثرون عليها إلى نصيحتها، وكف لسانها، نعم.  وإن أردت العقوبة فلا بأس، إن أردت أن تطلب العقوبة من المحكمة بأن تجازى على فعلها، فلا بأس. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13940/حكم-مقابلة-السيىة-بسيىة-مثلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50008.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":15433,"question":"السائلة من الرياض تذكر في رسالتها، وملخص هذه الرسالة تقول: بأن أهل زوجي لا يقومون بزيارتنا، ويبغضونني، ولا يريد أن نزورهم، ويتشاءمون مني، فهل بمقاطعتهم لي لهم أأثم أنا وزوجي؟نرجو بهذا الإفادة، مع العلم بأننا نحافظ على الصلوات والفروض، أفيدونا، مأجورين.","title":"توجيه لمن أقارب زوجها لا يحبون زيارتها","answer":"الجواب: إذا كان الواقع ما ذكرت، فلا حرج عليك، إذا كان الخطأ منهم، لا يريدونكم، ولا يقبلون منكم الزيارة، فالإثم عليهم، أما أنت فعليك.....، وعليك الكلام الطيب، والدعاء لهم بالتوفيق والهداية، وإذا تيسر أن تزوريهم على وجه حسن ليس فيه ثقل، ولا مشقة، فلك أجر، ولكن إذا تيسر من ينصحهم، ويقوم بالواجب بالوساطة الطيبة بينكما، فهذا طيب. المقصود: أنه لا إثم عليك إذا كانوا يكرهون زيارتك، ولا يرضون عنك، لكن إن زرت وصبرت ودعوت لهم بالخير وأحسنت إليهم، وتكلمت معهم بالكلام الطيب، فأنت مأجورة، أنت وزوجك، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13950/توجيه-لمن-اقارب-زوجها-لا-يحبون-زيارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_500/50011.mp3","categories":["نصائح وتوجيهات"]},{"id":15520,"question":"سماحة الشيخ بعض الأخوات الفتيات قد ترد الخطاب بحجة أنها ترغب في إكمال دراستها، أو أنها تريد شخصًا مكتملًا، هل لسماحتكم توجيه حول هذا؟","title":"توجيه لمن ترفض الزواج بحجة إكمال الدراسة","answer":"الجواب: المشروع للشاب والشابة المبادرة في الزواج، وأن لا يؤخر الزواج، فيشرع للرجل أن يبادر بالزواج، ويشرع للفتاة أن تبادر بالزواج إذا تيسر الكفء؛ لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء. والصواب: أنه واجب مع وجود الشهوة والاستطاعة، والمرأة كذلك إذا خطبها الكفء وجب عليها الموافقة، ولا يجوز لها التأخير إلى انتهاء الدراسة، أو لكذا وكذا؛ لأن في التأخير أخطارًا كثيرة، نعم.","link":"https://binbaz.org.sa/fatwas/14057/توجيه-لمن-ترفض-الزواج-بحجة-اكمال-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56918.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات","قضايا المرأة"]},{"id":15549,"question":"من القصيم الأخت السائلة أم خالد تقول: يا سماحة الشيخ، أنا وزوجي نتفق دائمًا على كل شيء، ونحن في حياة أسرية سعيدة، ولكن عمي أبو زوجي يتكلم علي ظلم وعدوان، ويقوم بسبي، وأنا أنصحه، وأطلب منه الهدوء، بأن لا يتكلم علي، مع العلم بأن عندي ثقل في السمع، ولا أسمع أكثر الكلام الذي يقوله عمي أبو زوجي، ولكن يصلني تفسير الكلام من زوجي، ومن جيراني، وإنه رجل شكوك، فهل هذا الشك حرام؟ وأنا أدعو له دائمًا، وأقابل الإساءة بالإحسان، فالرجاء من سماحتكم التنبيه إلى خطر ذلك.","title":"توجيه لمن تعاني من أذى أبي زوجها","answer":"الجواب: هذا الذي فعلت هو المشروع، جزاك الله خيرًا، استقيمي على هذا، سامحيه وانصحيه، وردي عليه بالكلام الطيب، وأوصي زوجك وغيره بأن ينصحوه، حتى يدع التعدي عليك، وإذا تعدى فالإثم عليه، وأنت مأجورة في الكلام الطيب، والرد الحسن، وأبشري بالخير، والإثم عليه إذا ظلمك، وتعدى عليك، الإثم عليه، أما أنت فأنت مأجورة ومشكورة على الصبر والاحتساب والرد الطيب، بارك الله فيك، نعم. المقدم: جزاكم الله خيرًا فضيلة الشيخ.","link":"https://binbaz.org.sa/fatwas/14085/توجيه-لمن-تعاني-من-اذى-ابي-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69121.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":15612,"question":"تساهل بعض الناس -سماحة الشيخ- في العبادات، ومن ثم يسألون بعد ذلك، هل لكم توجيه حول ذلك؟","title":"توجيه للمسلم بالاهتمام بتعلم أحكام العبادات","answer":"الجواب: الواجب على المؤمن أن يهتم بعبادته، الحج، والعمرة، والصلاة وغيرها، الواجب عليه أن يهتم بذلك، وأن يعتني وأن يتعلم حتى يؤدي الصلاة على وجهها، ويؤدي الصوم على وجهه، والحج على وجهه، والعمرة على وجهها، يجب أن يتعلم ويتفقه؛ لأن الله أوجب عليه الصلاة، وأوجب عليه صيام رمضان، وأوجب عليه الحج، وأوجب عليه العمرة؛ فلا بد أن يتعلم ما يؤدي به هذا الفرض، ولا يتساهل في هذا، وما لا يتم الواجب إلا به فهو واجب، وقد قال ﷺ: من يرد الله به خيرًا يفقهه في الدين فالتفقه في الدين من علامات أن الله أراد بالعبد خيرًا، والإعراض والغفلة من علامات الشر، ونسأل الله العافية. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14148/توجيه-للمسلم-بالاهتمام-بتعلم-احكام-العبادات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57021.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":15628,"question":"يقول السائل: في هذه الأيام يفضل التمييز بين الأبناء، يقول: وهذا يخلق عداوة بين الإخوان فيما بينهم أفيدونا بتوجيه الآباء ونصيحتكم. جزاكم الله خيرًا.","title":"ما النصيحة للآباء في المفاضلة بين الأبناء؟","answer":"الجواب: لا يجوز للآباء تفضيل بعض الأولاد على بعض، لا يجوز لهم ذلك، بل هذا منكر؛ النبي ﷺ لما سأله بشير بن سعد أن يعطي النعمان ولده غلامًا قال: أعطيت ولدك كلهم؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وأراد أن النبي ﷺ يشهد فقال: إني لا أشهد على جور سماه النبي ﷺ جورًا. فالمقصود: أنه لا يجوز للأم ولا للأب التفضيل بين الأولاد، بل يجب التسوية بينهم للذكر مثل حظ الأنثيين، فلا يجوز أن يعطى زيد كذا، ويترك الآخر، لا، بل يجب التعديل بين الأولاد ذكورهم وإناثهم؛ ولهذا في الحديث الآخر: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فهكذا؛ لأنه إذا فرق بينهم ساءت أحوالهم، وربما قطعوه أيضًا. فالواجب على الأب والأم والجد والجدة عدم التفضيل، بل يجب العدل للذكر مثل حظ الأنثيين، إذا أعطى الذكر مائة يعطي الأنثى خمسين، وإذا أعطى الرجل ألفًا يعطي الأنثى خمسمائة وهكذا، يجب التعديل؛ لقوله ﷺ: اتقوا الله واعدلوا بين أولادكم ولقوله لـبشير بن سعد الأنصاري لما أراد أن يشهده على عطيته للنعمان وحده قال: إني لا أشهد على جور وقال لـبشير: أيسرك أن يكونوا لك في البر سواء؟ قال: نعم، قال: فلا إذًا يعني: فلا تخص بعضهم، سوِّ بينهم حتى يكونوا كلهم في البر لك سواء، نعم. المقدم: أحسن الله إليكم وبارك فيكم..","link":"https://binbaz.org.sa/fatwas/14169/ما-النصيحة-للاباء-في-المفاضلة-بين-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_571/57111.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":15641,"question":"أريد أن أتزوج فما هو رأي سماحتكم في الشروط التي اشترطها في المخطوبة، ما هي؟وجهوني، جزاكم الله خيرًا.","title":"صفات الزوجة التي ينبغي اختيارها","answer":"الجواب: عليك بذات الدين، عليك بالمرأة الصالحة المعروفة بالأخلاق الطيبة، بالصلاة والعفاف، وطيب الخلق، وطيب الكلام، وحسن الصورة أيضًا؛ لقوله ﷺ: تنكح المرأة لأربع: لمالها ولجمالها ولحسبها ولدينها؛ فاظفر بذات الدين تربت يداك. فأوصى بذات الدين، فنوصيك بما أوصى به النبي ﷺ، ذات الدين، نوصيك بالمرأة المعروفة بالاستقامة بالصلاة في وقتها بالعفة عما حرم الله، بطيب اللسان، وطيب الكلام، بالأخلاق الكريمة، وحسن الخلق، وإذا تيسر مع هذا الجمال والنسب الحسن والمال؛ هذا خير إلى خير، ولكن المهم أن تكون أخلاقها كريمة، محافظة على الدين، طيبة في الصلاة، طيبة في أخلاقها، بعيدة عما حرم الله من الفواحش، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14181/صفات-الزوجة-التي-ينبغي-اختيارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70509.mp3","categories":["نصائح وتوجيهات","الخِطْبَة والاختيار ","نكاح الكفار"]},{"id":15649,"question":"من القصيم بريدة، هذه رسالة بعثت بها إحدى الأخوات من هناك، تقول أختكم أم هبة عبد الهادي، أختنا عرضنا لها سؤالًا في حلقات مضت من هذا البرنامج، وفي هذه الحلقة تسأل سماحتكم فتقول: لي جارة تقوم بالاختلاط بالرجال، ولا ترتدي الحجاب الشرعي الذي أمر الله تعالى به، وهي دائمًا تغتاب الناس، وقد قمت بنصحها ودعوتها إلى الطريق الصحيح، ولكنها لم تستجب حتى الآن، فماذا علي؟جزاكم الله خيرًا. وهل أقاطعها؟","title":"توجيه لمن لها جارة ترتكب بعض المعاصي","answer":"الجواب: عليك أن تنصحيها كثيرًا، وتخوفيها من الله ؛ فإن اختلاطها بالرجال على وجه يثير الفتنة هذا لا يجوز، وهكذا عدم ارتدائها الحجاب، فالواجب عليها الحذر من هذا الأمر، عليها التستر والحجاب والبعد عن الاختلاط الضار، أما اختلاط لا يضر: كالبيع في السوق في محل النساء، أو تشتري حاجتها من السوق، أو تبيع حاجة في السوق مع التحفظ، ومع الحجاب، ومع التستر، هذا لا بأس به، تشتري حاجتها، وتبيع شيئًا في السوق، وإذا كان للنساء سوق خاص باعت فيه واشترت، بعدًا عن الخطر والخلطة بالرجال. أما الغيبة فشرها عظيم، الغيبة منكرة وجريمة، ومن كبائر الذنوب، فالواجب تحذيرها من ذلك، وذكيرها بقول الله سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12] وهي ذكرك أخاك بما يكره، الغيبة: ذكر الإنسان بما يكره من رجل أو امرأة، أنه بخيل، أنه بذيء اللسان، أنه يأكل الحرام، أن يذكر بشيء يكرهه، هذه هي الغيبة، فالواجب نصيحتها والإكثار عليها في ذلك، وتخويفها من الله ؛ لعلها تهتدي فيكون لك مثل أجرها، فإن أصرت فالمشروع أن تقاطعيها وتهجريها، إذا أصرت ولم تقبل؛ فالمشروع لك هجرها، والبعد عنها؛ لأنها قد تجرك إلى عملها الخبيث، وعملها السيئ، وهجر من أظهر المعصية ولم يقبل النصيحة مشروع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14185/توجيه-لمن-لها-جارة-ترتكب-بعض-المعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_705/nour_70512.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات","قضايا المرأة"]},{"id":15723,"question":"هل المشروع أن أرفع يدي أثناء الاستخارة؟","title":"حكم رفع الأيدي في دعاء الاستخارة","answer":"الجواب: نعم؛ إذا صلى ركعتين يرفع يديه، ويدعو، هذا هو الأفضل؛ لأن رفع اليدين من أسباب الإجابة. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14282/حكم-رفع-الايدي-في-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57411.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":15730,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ف. م. ع) أخونا له بعض الأسئلة، من بينها سؤال يقول فيه:بعض الأوقات يوسوس الشيطان في قلبي، وأقرأ المعوذتين، وآية الكرسي، لكن لم أستفد، فما هو توجيه سماحتكم؟جزاكم الله خيرًا.","title":"الحث على مجاهدة الشيطان والصبر على ذلك","answer":"الجواب: تجتهد في التعوذ بالله من الشيطان؛ لأن الشيطان عدو مبين، فلا بد من الجهاد والصبر والقوة، والله يقول سبحانه: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا [العنكبوت:69] ويقول سبحانه: إِنَّ الشَّيْطَانَ لَكُمْ عَدُوٌّ فَاتَّخِذُوهُ عَدُوًّا [فاطر:6] لا بد من قوة وصبر، لا بد من قوة تستعيذ بالله من الشيطان، وأنت قوي، تعلم أن الله -جل وعلا- هو القادر على دفعه عنك، فتستعيذ بالله من الشيطان، وتكرر وأبشر بالخير، وعند النوم تقرأ آية الكرسي، بعد كل صلاة تقرأ قُلْ هُوَ اللَّهُ أَحَد [الإخلاص: 1] والمعوذتين، تقرأ آية الكرسي أيضًا بعد كل صلاة، يكون عندك قوة ونشاط، لا تكن ضعيفًا، عليك بالقوة عند تعوذك من عدو الله الشيطان، والصدق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14296/الحث-على-مجاهدة-الشيطان-والصبر-على-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70616.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":15731,"question":"رجل له أرحام يتخلفون عن أداء الصلاة جماعةً في المسجد، ويقعون في كثير من المعاصي والمنكرات، فكيف يمكن لهذا الرجل أن يصل أرحامه وهم مقيمون على تلك المحرمات؟ وكيف يمكن كذلك أن يبر والديه إذا كانوا كذلك في هذه الحال؟","title":"كيفية صلة الأرحام إذا كانوا عصاة","answer":"الجواب: السنة له أن يصلهم بالمال إذا كانوا فقراء، ويحسن إليهم، وعليه أن ينصحهم أيضًا، ويوجههم إلى الخير، ويأمرهم بالمعروف، وينهاهم عن المنكر؛ لا يسكت، سواءً كان ذلك مع الوالدين، أو مع الإخوة، أو أخوال، أو أعمام، أو غيرهم، الواجب عليه دعوتهم إلى الله، ونصيحتهم، وأمرهم بالمعروف، ونهيهم عن المنكر باللطف والرفق والأسلوب الحسن؛ لعل الله ينفع به؛ لعل الله يهديهم بأسبابه، وإذا كانوا فقراء ساعدهم، وتألف قلوبهم بالمال إذا كان عنده قدرة يعطيهم من المال، وإذا كان عنده زكاة أعطاهم من الزكاة، إذا كانوا ليسوا بآباء ولا بأولاد إنما هم إخوة أو أعمام أو نحو ذلك. المقصود: إنه يتألفهم بالمال إذا كانوا ليسوا بوالديه، ولا من أولاده، يتألفهم بالمال، وبالكلام الطيب، وإذا كانوا من والديه أو من أولاده بالكلام الطيب، والأسلوب الحسن، يجتهد في دعوتهم إلى الله، والرفق بهم، ونصيحتهم، وبيان سوء ما فعلوا، ويستعين في ذلك أيضًا بأقاربه الآخرين كإخوته أو أعمامه حتى يساعدوك في هذا الأمر؛ لعل الله يهدي هؤلاء بأسبابهم، لأنه إذا كان وحده قد لا يستجيبون له، فإذا كان مع بعض أقاربه لعلهم يستجيبون، وإلا الدعوة تنفع، فإذا صمموا على المنكر، ولم يستجيبوا له فله هجرهم، لكن يعمل الأصلح مهما أمكن، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14297/كيفية-صلة-الارحام-اذا-كانوا-عصاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57415.mp3","categories":["نصائح وتوجيهات","الدعوة والدعاة"]},{"id":15793,"question":"تقول: كثيرًا ما يحصل بيني وبين أخت زوجي شجار، ينعكس ذلك على حياتي الزوجية، فيحصل من النكد الشديد ما لا يوصف. سؤالي يا سماحة الشيخ: هل في مقاطعتي لها وعدم زيارتي لها إثم؟ وهل أهل الزوج عمومًا يعدون من الأرحام بالنسبة لزوجة الابن؟","title":"حكم ترك المرأة زيارة أهل زوجها","answer":"الجواب: ليسوا من الأرحام، ولكن مهما أمكن المواصلة بالتي هي أحسن، والكلام الطيب، والصبر والتحمل فهو أحسن، إذا عاملتيها باللطف، والكلام الطيب، ولم تلتفت إلى كلامها السيىء، وصفحت عنها وعفوت فهذا أطيب وأحسن، فإن لم تستطيعي فالمقاطعة أولى، وعدم الزيارة لهم إذا كان يترتب على هذا شر بينك وبين زوجك، فاتركي زيارتها، والكلام معها، وإن تحملت الصبر، وأعرضت عن كلامها السيىء، وسمحت عنها، فهذا طيب، وبهذا تنتهي المشكلة، وترجع عن غيها وسوئها منك، لكن إذا كان منك كلمة، ومنها كلمة، وعدم صبر يطول الأمر، ويحصل الشر، لكن نوصيك بالسماح، وعدم الرد عليها، والتحمل والصبر حتى ترجع إلى صوابها، وتدع الإيذاء، فإن لم تتحملي ولم تصبري فاتركي الزيارة، ولا حرج عليك في ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14383/حكم-ترك-المراة-زيارة-اهل-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_742/nour_74220.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":15805,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من الرياض، وباعثتها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (س.م.و.ك) أختنا لها قضية طويلة جدًا ملخصها:أن أمها تزوجت من رجل آخر بعد أن طلقها أبوها، ولها من ذلكم الرجل المتوفى عدد من الأولاد والبنات، وأيضًا لهن أخ من أبيهن، ملخص ما في القضية: أن أمهن منعتهن عن الاتصال بأخيهن لأبيهن، ويسألن: هل لهن أن يزرن ذلك الأخ بالرغم من تصرف والدتهن؟جزاكم الله خيرًا.","title":"حكم طاعة الأم في قطيعة الرحم","answer":"الجواب: يقول النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق فالواجب عليكن صلة الرحم، فالأخ من الأب رحم قريب، فإذا كان لا يستحق الهجر، فإنه يوصل بالكلام الطيب، أو بالمكاتبة، أو بالهاتف، وإذا كان فقيرًا يوصل بالصدقة والإحسان.  أما إن كان رجلًا كافرًا، أو معلنًا للفسق والبدعة؛ ولهذا كرهت الوالدة أن تتصلوا به، فهذا له وجه شرعي من باب الهجر، أما إذا كان مستورًا أو طيبًا، فالواجب عدم طاعتها في ذلك؛ لأن صلة الرحم حق، ولا طاعة لمخلوق في معصية الخالق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14393/حكم-طاعة-الام-في-قطيعة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74308.mp3","categories":["نصائح وتوجيهات"]},{"id":15813,"question":"رجل عق والديه كثيرًا حتى إنه لا يزورهما، بل ويتكلم عليهما بما لا يتكلم به الابن على أبيه، سؤالنا أيضًا أنه لا يهتم كثيرًا بالصلاة، وقد يطردنا عند زيارته؛ لذلك فنحن لا نحب زيارته، ولا نذهب إليه، فهل علينا إثم في ذلك؟","title":"حكم هجر العاق لوالديه التارك للصلاة","answer":"الجواب: عليكم أن تنصحوه حتى يتوب إلى الله من عقوق والديه، فإن حق الوالدين عظيم، فالواجب عليه أن يبرهما، ويحسن إليهما، ولو ضرباه، ولو سباه، حقهما عظيم، حتى ولو كانا كافرين (وصاحبهما معروفًا) كما قال الله تعالى في الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا[لقمان:15] فليس له أن يسبهما، ولا أن يعقهما، لكن ليس له أن يطيعهما في معصية، ليس للمخلوق طاعة في معصية الله، قال النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. وإذا كان لا يصلي فالذي لا يصلي كافر، لا تزوروه، بل اهجروه حتى يتوب إلى الله ، فهو يستحق الهجر لعقوقه، وإذا كان يترك الصلاة فترك الصلاة أعظم وأكبر، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فهذا يستحق أن يهجر، ويرفع أمره إلى ولي الأمر، حتى يعاقب حتى يستتاب حتى يستقيم على الصلاة، فإن لم يستقم وثبت عند الحاكم أنه لا يبالي بالصلاة، وأنه يتركها، فالحاكم ينظر في أمره فيما يستحق من قتل وغيره. فالمقصود: أن الواجب على أقارب هذا الرجل الذي لا يصلي أن يهجروه إذا لم يقبل النصيحة، ولم يتب إلى الله ، وإذا رفعوا أمره إلى ولي الأمر حتى يقام عليه ما يجب فهو مناسب أيضًا إذا ثبت عليه ذلك بالبينة الشرعية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14406/حكم-هجر-العاق-لوالديه-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74405.mp3","categories":["نصائح وتوجيهات"]},{"id":15814,"question":"رجل عق والديه كثيرًا حتى إنه لا يزورهما، بل ويتكلم عليهما بما لا يتكلم به الابن على أبيه، سؤالنا أيضًا أنه لا يهتم كثيرًا بالصلاة، وقد يطردنا عند زيارته؛ لذلك فنحن لا نحب زيارته، ولا نذهب إليه، فهل علينا إثم في ذلك؟","title":"حكم هجر العاق لوالديه التارك للصلاة","answer":"الجواب: عليكم أن تنصحوه حتى يتوب إلى الله من عقوق والديه، فإن حق الوالدين عظيم، فالواجب عليه أن يبرهما، ويحسن إليهما، ولو ضرباه، ولو سباه، حقهما عظيم، حتى ولو كانا كافرين (وصاحبهما معروفًا) كما قال الله تعالى في الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا[لقمان:15] فليس له أن يسبهما، ولا أن يعقهما، لكن ليس له أن يطيعهما في معصية، ليس للمخلوق طاعة في معصية الله، قال النبي ﷺ: إنما الطاعة في المعروف، لا طاعة لمخلوق في معصية الخالق. وإذا كان لا يصلي فالذي لا يصلي كافر، لا تزوروه، بل اهجروه حتى يتوب إلى الله ، فهو يستحق الهجر لعقوقه، وإذا كان يترك الصلاة فترك الصلاة أعظم وأكبر، يقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة، فمن تركها فقد كفر فهذا يستحق أن يهجر، ويرفع أمره إلى ولي الأمر، حتى يعاقب حتى يستتاب حتى يستقيم على الصلاة، فإن لم يستقم وثبت عند الحاكم أنه لا يبالي بالصلاة، وأنه يتركها، فالحاكم ينظر في أمره فيما يستحق من قتل وغيره. فالمقصود: أن الواجب على أقارب هذا الرجل الذي لا يصلي أن يهجروه إذا لم يقبل النصيحة، ولم يتب إلى الله ، وإذا رفعوا أمره إلى ولي الأمر حتى يقام عليه ما يجب فهو مناسب أيضًا إذا ثبت عليه ذلك بالبينة الشرعية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14406/حكم-هجر-العاق-لوالديه-التارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74405.mp3","categories":["نصائح وتوجيهات"]},{"id":15881,"question":"في نهاية الحلقة، وفي نهاية الرسالة يقول: أوصونا سماحة الشيخ.","title":"نصيحة لعامة المسلمين","answer":"الجواب: نوصيك وجميع المسلمين المستمعين لهذا البرنامج نوصي الجميع بتقوى الله، والاستقامة على دينه، والتفقه في الدين، والتواصي بالحق، والتعاون على البر والتقوى، هذا الذي نوصي به الجميع، تقوى الله في كل وقت، وفي كل حين بأداء حقه، وترك معصيته، والتعاون مع إخوانه على البر والتقوى، والتواصي بالحق، والصبر عليه، والإكثار من قراءة القرآن، والإكثار من ذكر الله، والاستغفار والتسبيح والتهليل والتحميد والتكبير، والضراعة إلى الله، ودعائه بطلب الثبات على الحق، والعافية من مضلات الفتن، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14473/نصيحة-لعامة-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74418.mp3","categories":["نصائح وتوجيهات"]},{"id":15902,"question":"يقول: يكثر عليَّ التثاؤب والنعاس أثناء الصلاة، فكيف توجهونني؟أثابكم الله.","title":"توجيه لمن يأتيه التثاؤب والنعاس أثناء الصلاة","answer":"الجواب: نوجهك بأن تجتهد في أن تدخل الصلاة وأنت نشيط، توضأ إذا كنت كسلان توضأ وضوءًا ولو تجديدًا، ولو كنت على طهارة تتوضأ للنشاط، وتحضر في قلبك أنك بين يدي الله، وأنك في عبادة عظيمة، وهي عمود الإسلام، وهي أعظم أركان الإسلام بعد الشهادتين، حتى تنشط وتقوى في هذا العمل، ويذهب عنك النعاس والكسل، فإن الإنسان إذا استحضر أنه في أمر عظيم، وأنه بين يدي العظيم  كان هذا مما يقويه وينشطه ويبعده من الكسل.","link":"https://binbaz.org.sa/fatwas/14493/توجيه-لمن-ياتيه-التثاوب-والنعاس-اثناء-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74602.mp3","categories":["نصائح وتوجيهات","مكروهات الصلاة"]},{"id":15904,"question":"يقول: أرجو من سماحة الشيخ أن يتفضل بتوجيهي إلى الأقوال والأفعال التي تساعد المسلم على اجتناب الشيطان ووسوسته؟جزاكم الله خيرًا.","title":"الأسباب المعينة على تجنب الشيطان ووساوسه","answer":"الجواب: ننصح كل مسلم أن يبتعد عن أسباب استيلاء الشيطان عليه؛ وذلك بالغفلة عن ذكر الله، وتعاطي المعاصي، ومجالسة الأشرار، كل هذه من أسباب استيلاء الشيطان وغلبته عليه، فليحرص على الإكثار من ذكر الله، فإن الذكر يطرد الشيطان، وبه تطمئن القلوب، يقول الله : وَمَنْ يَعْشُ عَنْ ذِكْرِ الرَّحْمَنِ نُقَيِّضْ لَهُ شَيْطَانًا فَهُوَ لَهُ قَرِينٌ[الزخرف:36] فإذا أكثر من ذكر الله ابتعد عنه الشيطان، وهكذا المعاصي تسبب قرب الشيطان، وقسوة القلب، والعقوبات، ومن أعظم العقوبات أن ينسى ذكر الله، وأن تغلب عليه الوساوس حتى لا يضبط عمله، وهكذا صحبة الأشرار فإنها تضره ضررًا عظيمًا وتنسيه ما عليه من الحقوق، وتباعده من طاعة الله ورسوله فيجب الحذر من ذلك. ومن أسباب السلامة: الضراعة إلى الله ودعاؤه -جل وعلا- أن يعينك، وأن يصلح قلبك، وأن يمنحك التوفيق لذكره، والقيام بحقه على الوجه الذي يرضيه، فهو القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ[غافر:60] فاضرع إلى الله، وأكثر من دعائه  أن يعينك، وأن يمنحك التوفيق، ويعيذك من الشيطان ونزغاته ووساوسه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14495/الاسباب-المعينة-على-تجنب-الشيطان-ووساوسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74604.mp3","categories":["نصائح وتوجيهات"]},{"id":15922,"question":"هذه سائلة للبرنامج تقول: أردنية، ومقيمة في تبوك، تذكر بأنها فتاة تقدم لخطبتها منذ أربع سنوات شابين، تقول: أنا وافقت على شخص، وأمي وافقت على الشخص الآخر، باعتباره قريب لنا، وحاولنا إقناعها بأنه سيئ الأخلاق، وأنا كنت موافقة على الشخص الآخر؛ لأنني أريد أن أبتعد عن أهلي، فكانت أمي واقفة عند باب الحمام يوم جمعة عند الظهيرة، فقالت لي: إن شاء الله لا تتزوجين أبدًا، فأنهت الموضوع بالنسبة للشخص الذي أريده من أجل المهر، واكتشفت أمي بعد فترة أن الشخص الذي كانت تريده غير مناسب أخلاقيًا، وقد نسيت أمي هذه الدعوة؛ لأنها من وراء قلبها، وبعد الحادثة كثيرًا ما كانت أمي تدعو مع الأوقات التي تكون فيها الإجابة موجودة بأن يرزقني الله بابن الحلال، فهل تكون الدعوة قد أجيبت يا سماحة الشيخ؟!","title":"نصيحة بالمبادرة في تزويج الأولاد والحذر من الدعاء عليهم","answer":"الجواب: الله أعلم ، لكن نوصيك بالتزوج بالرجل الطيب الصالح، ولو أبت أمك، نوصيك بالرجل الصالح تزوجيه، ولا تبقي عزباء بعدم الزواج، بل نوصيك بأن تجتهدي في الزواج، ونوصي وليك بذلك، لأن الرسول ﷺ يقول: إنما الطاعة في المعروف وما دامت أمك -هداها الله- رجعت عن رأيها، فالحمد لله.  المقصود: إذا خطب الكفء فبادروا بالزواج، يقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه نسأل الله لك الزوج الصالح، نعم.\nالمقدم: سماحة الشيخ لعل لكم توجيه حول دعاء الآباء على الأبناء في مثل هذه الحالة.\nالشيخ: نوصي جميع المسلمين بالحذر من الدعاء على أولادهم، بل الدعاء لهم بالخير، المشروع للوالد والوالدة الدعاء لهم بالخير، لا عليهم، يشرع للوالد والوالدة الدعاء لأولادهما بالتوفيق والصلاح، ويدعى للرجل بالزوجة الصالحة، والذرية الصالحة، ويدعى للمرأة بالزوج الصالح، والذرية الصالحة، هكذا يجب، وهكذا ينبغي للآباء والأمهات والأقارب أن يتعاونوا على البر والتقوى، وأن يتناصحوا، وأن يدعو كل واحد لأخيه بالخير والصلاح، والعاقبة الحميدة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14517/نصيحة-بالمبادرة-في-تزويج-الاولاد-والحذر-من-الدعاء-عليهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57712.mp3","categories":["تربية الأولاد","نصائح وتوجيهات"]},{"id":15923,"question":"تذكر في ضمن فقرات سؤالها -يا سماحة الشيخ- هذه السائلة تقول: نحن البنات نعاني من ظلم الوالدة، وتفضيل أخي علينا، رغم أنه ينهال عليهم بالسب والشتم، وتدعو علينا كثيرًا. تفضيل البنات أو الأولاد على بعضهم سماحة الشيخ.","title":"موقف الولد تجاه إساءة الوالدين له","answer":"الجواب: نوصيكم بالرفق بها، وسؤال الله لها الهداية، والصبر عليها والسماح، وإن حصل منها ما حصل، الواجب على الولد السماح عن والدته، والحرص على إرضائها -الذكر والأنثى- الله -جل وعلا- يقول في حق الوالدين: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24]، ويقول -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]. فالمشروع للولد -ذكرًا كان أو أنثى- الحرص على إرضاء والديه، وعلى محبتهما وبرهما، والإحسان إليهما، وإن أساءا، يقول النبي ﷺ ليس الواصل بالمكافي، ولكن الواصل الذي إذا قطعت رحمه وصلها هكذا الواصل، قيل: يا رسول الله، أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فقدم برهما على الجهاد.\nفالوصية للولد -ذكرًا كان أو أنثى- الحرص على بر أبيه وأمه، والصبر على ما قد يقع من الأذى، نسأل الله للجميع الهداية والتوفيق، نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14518/موقف-الولد-تجاه-اساءة-الوالدين-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57713.mp3","categories":["نصائح وتوجيهات"]},{"id":15971,"question":"يقول: قرأت قولًا يقول: (اغتربوا تضووا) هل هو حديث صحيح؟ وهل هناك أحاديث أخرى حول هذا الموضوع؟ نرجو توضيح السنة الصحيحة في مسألة اختيار الزوجة.","title":"الحكم على حديث: (اغتربوا تضووا)","answer":"الجواب: ليس لهذا أصل، بل كونه يتزوج من أقاربه أفضل، والنبي تزوج من أقاربه -عليه الصلاة والسلام-، أما قول بعض الفقهاء أنه يتزوج أجنبية هذا لا أصل له، بل هو مخير إن شاء تزوج قريبة كبنت عمه وخاله، وإن شاء تزوج البعيدة لا حرج في ذلك، وأما قول من قال: إن الأجنبية أنجب وأفضل فهذا لا أصل له ولا دليل عليه، بل إذا تيسرت قريبة طيبة فهي أولى لما في هذا من صلة الرحم، أما إذا كانت الأجنبية أدين وأكثر خيرًا فالأجنبية أفضل. المقصود: أنه يتحرى المرأة الصالحة قريبة أو غير قريبة؛ لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها، فاظفر بذات الدين تربت يداك فالمؤمن يلتمس ذات الدين الطيبة وإن كانت من غير أقاربه، والزوجة كذلك تلتمس الزوج الصالح وتسأل عنه وإن كان من غير أقاربها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14587/الحكم-على-حديث-اغتربوا-تضووا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74623.mp3","categories":["نصائح وتوجيهات","الزواج وأحكامه"]},{"id":16003,"question":"نعود مرة أخرى إلى حائل عبر رسالة بعث بها المستمع فهد السمري، الأخ فهد يقول: يبعد المسجد عني أنا وجاري بحوالي ستمائة متر، نذهب له في جميع أوقات الصلاة، ولكن..الشيخ: أعد.المقدم: يبعد المسجد عني أنا وجاري بحوالي ستمائة متر، نذهب له في جميع أوقات الصلاة، ولكن في فصل الشتاء نعاني من شدة البرد، حيث إن الجو عندنا بارد جدًا كما تعلمون، هل يجوز أن نبني بالقرب منا مسجدًا أنا وجاري، ونصلي فيه، ولا سيما في فصل الشتاء؟وجهونا، جزاكم الله خيرًا.","title":"الحث على تحمل بعد مسافة المسجد","answer":"الجواب: ننصحكم أن لا تبنوا، وأن تصلوا مع إخوانكم في الشتاء والصيف، وأبشروا بالخير، اصبروا وصابروا، طريق الآخرة يحتاج إلى صبر، فالواجب على مثلكما الصبر والاحتساب؛ لأن صلاتكما مع الجماعة فيها خير عظيم، وستمائة متر ليست كثيرة، وليست طويلة، فاصبروا وصابروا، واحتسبوا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14626/الحث-على-تحمل-بعد-مسافة-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74712.mp3","categories":["صلاة الجماعة","نصائح وتوجيهات"]},{"id":16130,"question":"رسالة من أحد الإخوة المستمعين آثر عدم ذكر اسمه يسأل في سؤاله الأول ويقول: الذي يكون عاقًا لوالديه، هل تقبل منه صلاته وصومه وصدقته؟ وبماذا تنصحون الناس؟ جزاكم الله خيرًا.","title":"حكم قبول أعمال العاق لوالديه والحلف على المصحف","answer":"الجواب: عقوق الوالدين من كبائر الذنوب، ومن المحرمات العظيمة، فالواجب الحذر منه، وقد ثبت عن رسول الله -عليه الصلاة والسلام- أنه قال: إن الله حرم عليكم عقوق الأمهات وقال -عليه الصلاة والسلام-: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله، وعقوق الوالدين وكان متكئًا فجلس فقال: ألا وقول الزور، ألا وشهادة الزور متفق على صحته.  والله يقول في كتابه الكريم : وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23] يعني: أمر أن لا تعبدوا إلا إياه وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23، 24] ويقول سبحانه في سورة لقمان: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]. فالواجب على الولد أن يشكر لوالديه، وأن يحسن إليهما، وأن يبرهما، وأن يطيعهما في المعروف، ويحرم عليه عقوقهما لا بالكلام، ولا بالفعل، فليس له أن يرفع صوته عليهما، وليس له ضربهما، وليس له عدم النفقة عليهما مع الحاجة إلى ذلك، وليس له عصيانهما في المعروف، بل يجب عليه طاعتهما في المعروف، وبرهما، وخفض الصوت إذا خاطبهما، والتأدب معهما في كل شيء. لكن لا يطيعهما في المعصية، يقول النبي ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق فلو أمراه أن يزني، أو يشرب الخمر، أو لا يصلي في الجماعة؛ لا يطيعهما، لكن يطيعهما في المعروف، يبرهما في المعروف، يحسن إليهما، يخاطبهما بالتي هي أحسن، ينفق عليهما إذا احتاجا إلى ذلك، هكذا المؤمن مع والديه، فحقهما عظيم، وبرهما من أهم الواجبات،. لكن ليس عقوقهما مبطلًا للصلاة، ولا للصوم، ولا للأعمال الصالحات، ولكن صاحبه على خطر من هذه الكبيرة العظيمة. وإنما تبطل الأعمال بالشرك، قال تعالى: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] أما بالعقوق، أو قطيعة الرحم، أو المعاصي الأخرى فإنها لا تبطل الأعمال، وإنما يبطلها الشرك الأكبر. وكذلك رفع الصوت على رسول الله ﷺ يخشى منه بطلان العمل في حياته ﷺ كما قال الله : يَا أَيُّهَا الَّذِينَ آمَنُوا لا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لا تَشْعُرُونَ [الحجرات:2] يعني: لئلا تحبط أعمالكم، فهذا يفيد أنه يخشى على من رفع صوته على النبي ﷺ وجهر له بالقول أن يحبط عمله، وهذا وعيد عظيم، ولهذا كان الصحابة يتأدبون مع الرسول ﷺ ويتكلمون معه كلامًا خفيفًا لينًا مخفوضًا تأدبًا معه، عليه الصلاة والسلام. فالمقصود: أن الواجب على المؤمن أن يبر والديه، وأن لا يعقهما، وأن يحسن إليهما في حياتهما، وبعد وفاتهما، ويحرم عليه العقوق لهما بالكلام السيء، أو السب، أو الضرب، أو أي إساءة لهما، أو رفع الصوت عليهما، أو عدم طاعتهما في المعروف، كل هذا من العقوق. المقدم: جزاكم الله خيرًا.  الشيخ: نسأل الله العافية. المقدم: اللهم آمين. المقدم: يسأل أيضًا أخونا ويقول: إذا حلف إنسان على القرآن وهو يحلف في نفسه، هل يجوز هذا، أم لا؟ الشيخ: كيف؟ المقدم: يقول: إذا حلف إنسان على القرآن، وهو يحلف في نفسه -لعله يقصد سرًا- هل يجوز، أم لا؟ جزاكم الله خيرًا. الشيخ: هذا السؤال ليس بواضح، إذا حلف على القرآن؛ صار أشد في اليمين، وليس هناك حاجة إلى الحلف بالقرآن، يحلف ولا حاجة إلى أن يحضر القرآن، يتقي الله وهو يحلف، ويتحرى الصدق، ولا يلزم إحضار القرآن، كثير من الناس يطلب إحضار القرآن، هذا لا أصل له، ولا حاجة إليه. الواجب على المؤمن أن يصدق أينما كان، ولا يجوز الكذب لا مع قرآن، ولا مع غير القرآن، يجب أن يصدق في الخصومات وفي غيرها، وليس له الكذب إلا إذا كان مظلومًا، إذا كان مظلومًا؛ فله الكذب، ويتأول إذا كان مظلومًا. وأما إذا كان غير مظلوم؛ فليس له أن يكذب، وليس له أن يحلف في أي شيء كاذبًا، كأن يدعى عليه أنه أخذ مال فلان، أو ضرب فلانًا، أو قتل فلانًا، ليس له أن يحلف، ينكر ذلك، بل عليه أن يقر بالحق، يعطيهم مالهم، يلزمه القصاص إذا توفرت شروطه، لا يكذب. أما إذا كان مظلومًا هذا شيء آخر، له أن يتأول إذا كان مظلومًا، أن يقال له: احلف أنك ما فعلت كذا وكذا، وهو لم يفعله، ولم يقع منه، فيحلف بالله أنه لم يقع منه، وليس في هذا شيء عليه؛ لأنه صادق. المقصود: أنه ليس له أن يكذب لا بإحضار القرآن، ولا في غير القرآن، بل عليه أن يتحرى الصدق إلا في المسائل التي أباح فيها النبي ﷺ الكذب، كالإصلاح بين الناس، والحرب، وحديث الرجل امرأته، فإذا كان ألزم باليمين في هذا، أو رأى المصلحة في هذا؛ فلا بأس أن يقول: والله ما كان كذا في الحرب، أو والله ما فعلت كذا في الحرب، إذا رأى فيه المصلحة للمسلمين. أو والله ما -يقول لامرأته-: والله ما فعلت هذا ليرضيها، ولا يضر غيره، ولا غيرها، أو في الإصلاح بين الناس، يجي قبيلة ويقول: والله ما قال هذا فلان ... يصلح بينهم، أو والله ما قالت القبيلة، أو والله إنها تحبكم، أو والله إنها تود الصلح معكم؛ ليصلح بينهم على وجه لا يضر أحدًا، هذا كله لا بأس به. المقدم: جزاكم الله خيرًا، إذًا نفهم من سماحتكم أن الحلف على المصحف أمر غير مشروع. الشيخ: ليس له أصل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14786/حكم-قبول-اعمال-العاق-لوالديه-والحلف-على-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80311.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":16137,"question":"أخيرًا تسأل أختنا بعض الأسئلة، حول القرآن الكريم، وحول تفسيره، فتسأل أولًا: عن تفسير الجلالين؟","title":"توجيه حول كتاب تفسير الجلالين","answer":"الجواب: تفسير مفيد، وفيه بعض الأخطاء في الصفات، وفي بعض التفسير لكن مفيد، تفسير مفيد، وقل كتاب إلا ويكون فيه بعض الأخطاء إلا كتاب الله  فكتب الناس يكون فيها بعض الأخطاء، لكن مقل ومكثر، فتفسير الجلالين فيه بعض الأخطاء، فإذا تيسر أن يدرسه صاحب سنة ليعرف كلام أهل السنة والجماعة؛ حتى ينبه على الأخطاء، فهذا طيب، وإذا أشكل شيء على الدارس يسأل أهل العلم، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ! هل تنادون أحد طلبة العلم بتتبع هذا التفسير والإرشاد إلى ما فيه من أخطاء، والقول الصحيح أيضًا؟ الشيخ: نعم، عندي نية في هذا، وقد كتبت فيه بعض الشيء، عندي نية أن أتتبع هذا -إن شاء الله- وأن أكتب ما تيسر في ذلك، ولعلي أوصي أيضًا بعض أهل العلم؛ لأنهم أفرغ مني، قد يفعلون هذا أسرع مني، فأرجو أن أوصي بعض أهل العلم بذلك -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا، طلبة كلية أصول الدين سماحة الشيخ كثيرًا ما يتناولون الدراسات القرآنية لنيل شهادة الماجستير، أو الدكتوراه هل تنصحون أحدًا منهم بتناول هذا الكتاب؟ الشيخ: لعله يتيسر إن شاء الله. المقدم: ليكون أطروحة علمية. الشيخ: أنا أوصي بهذا، نعم. أوصي بهذا؛ لأن فيه مصلحة كبيرة، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14807/توجيه-حول-كتاب-تفسير-الجلالين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_804/nour_80407.mp3","categories":["القرآن وعلومه","العالم والمتعلم","نصائح وتوجيهات"]},{"id":16177,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين رمز إلى اسمه بالحروف (ح) و(ق) و(أ) من حائل، أخونا له سؤال طويل جدًا ملخصه: أنه كان يصلي بالناس، وله صوت حسن وجميل، وكان يتعمد أيضًا تحسين صوته، وخوفًا من الرياء امتنع عن الإمامة، وجعل أناسًا آخرين يصلون بالناس، رغم أنهم لا يقرؤون، ولا يكتبون، كيف توجهونه؟ جزاكم الله خيرًا.","title":"توجيه لمن ترك إمامة المصلين خوفًا من الرياء","answer":"الجواب: نوجهه بأن يصلي بالناس، ويحسن صوته والحمد لله، ويجاهد نفسه في عدم الرياء؛ لقول النبي ﷺ: ليس منا من لم يتغن بالقرآن يعني: يحسن صوته به، ومر ذات ليلة على أبي موسى الأشعري وهو يقرأ، فاستمع له النبي ﷺ، فلما أصبح أتاه أبو موسى، فأخبره النبي ﷺ: إني سمعت صوتك، فقال: لقد أوتي أبو موسى مزمارًا من مزامير آل داود يعني: صوتًا من أصواتهم. فقال أبو موسى : \"لو علمت أنك تسمع؛ لحبرته لك تحبيرًا\" أي: حسنته لك تحسينًا. فتحسين الصوت لأجل منفعة المسلمين ليستمعوا، وينصتوا، ويتدبروا أمر مطلوب، وليس هذا من الرياء، هذا من الإحسان، والرسول -عليه الصلاة والسلام- قال: زينوا القرآن بأصواتكم تزيين الصوت ينفع الأمة، وينفع المستمعين، وأنت تفعله لنفعهم، لا ليمدحونك، دع عنك الرياء، ولكن تفعله حتى يستفيدوا، وينتفعوا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14838/توجيه-لمن-ترك-امامة-المصلين-خوفا-من-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75013.mp3","categories":["صلاة الجماعة","نصائح وتوجيهات"]},{"id":16193,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من القصيم يقول: بالنسبة لصلاة الرواتب ما هو عددها؟ وما كيفية أدائها؟ وهل النافلة التي بعد الظهر يمتد وقتها إلى دخول أذان العصر، أم لا؟ وهل بعد أذان العصر يمكن التنفل قبل الفريضة، أم لا؟ كذلك بالنسبة للنافلة التي بعد صلاة المغرب هل يمتد وقتها إلى دخول أذان العشاء، أم لا؟ وهل بعد أذان العشاء يمكن التنفل قبل صلاة الفريضة، أم لا؟ وضحوا لنا هذه الأمور حول النوافل، جزاكم الله خيرًا.","title":"ما هي السنن الرواتب؟ وما أوقاتها؟","answer":"الجواب:  الرواتب التي شرعها الله -جل وعلا- مع الصلوات الخمس، وكان النبي يحافظ عليها -عليه الصلاة والسلام- في الحضر اثنتا عشرة ركعة، منها أربع قبل صلاة الظهر بعد الزوال، يسلم من كل ثنتين، وثنتان بعد الظهر، تسليمة واحدة، هذه ست: ثنتان بعد المغرب.. ثنتان بعد صلاة العشاء.. ثنتان قبل صلاة الفجر، هذه هي الرواتب التي كان يحافظ عليها -عليه الصلاة والسلام- في الحضر، أما في السفر فكان يتركها ﷺ إلا سنة الفجر، كان في السفر لا يصلي هذه الرواتب إلا سنة الفجر، فإنه كان يحافظ عليها سفرًا وحضرًا. ويشرع للمؤمن مع الصلوات الخمس -سوى هذه الرواتب- أن يصلي أربعًا قبل العصر، بعد دخول الوقت، أربعًا، تسليمتين؛ لقوله ﷺ: رحم الله امرأ صلى أربعًا قبل العصر وهذه ليست راتبة، يروى عن النبي ﷺ كان ربما صلى ثنتين قبل العصر، ربما صلى أربعًا قبل العصر، لكن ليست راتبة، ولكنها مستحبة إذا صلاها المؤمن والمؤمنة فهو أفضل، أربع قبل العصر تسليمتين، وثنتان قبل المغرب، هذه مستحبة بعد الأذان، وقبل الإقامة ثنتان، كذلك بعد أذان العشاء يصلي ركعتين قبل صلاة العشاء أفضل، وليست من الرواتب، لكن يستحب إذا أذن المؤذن وهو جالس في المسجد أن يقوم، فيصلي ركعتين بعد المغرب، بعد أذان المغرب، وبعد أذان العشاء، وإن صلى أكثر فلا بأس. وكذلك يستحب له أن يتهجد بالليل بعد صلاة العشاء إلى آخر الليل، يتهجد بما يسر الله له ولو بركعة واحدة يوتر بها، وكل ما زاد فهو أفضل، أوتر بثلاث، أو بخمس، أو بسبع، أو بأكثر، يسلم من كل ثنتين فهذا هو الأفضل، والأفضل إحدى عشرة، أو ثلاث عشرة، وإن نقص، أو زاد فلا بأس، يسلم من كل ثنتين تأسيًا بالنبي ﷺ في ذلك. ولا بأس أن يتأخر في أداء الراتبة بعد الظهر، يمتد وقتها إلى أذان العصر، يصليها قبل العصر، ولو تأخر، لكن قبل العصر، قبل دخول وقت العصر، هكذا المغرب لو أخرها.. لو أخر الراتبة لم يصلها إلا قرب غروب الشفق، يعني: قرب العشاء فلا بأس، لكن الأفضل أن يبادر بها قبل العوائق، هذا هو الأفضل، وإلا فوقتها يمتد إلى أن يغيب الشفق الأحمر من جهة المغرب .... دخول وقت العشاء. كما أن سنة الظهر البعدية يمتد إلى دخول وقت العصر، لكن إذا بادر بهذه وهذه قبل دخول وقت الذي بعدها؛ فهو الذي أولى له؛ حتى لا يعرض له عارض، والأفضل في بيته، إذا صلاها في البيت؛ فهو أفضل، وإن صلاها في المسجد؛ فلا بأس، لكن في البيت أفضل، نعم. المقدم: جزاكم الله خيرًا، يستوي هذا الحكم سماحة الشيخ، وهذا التوجيه، يستوي في حق الرجال، وحق النساء ؟ الجواب: نعم عام للرجال والنساء جميعًا، الحكم عام للرجال والنساء، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14870/ما-هي-السنن-الرواتب-وما-اوقاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75102.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":16247,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه إلا بقوله: المرسل عوض يقول: يا سماحة الشيخ! لدي عم أنا متزوج ابنته، وهو لا يصلي، وأنا محتار كيف أعامله، فهل أطلق ابنته من أجل أبيها؟ علمًا بأنها مؤدية للصلاة، ولا ذنب لها، وجهوني جزاكم الله خيرًا.","title":"حكم طلاق المرأة لأن والدها لا يصلي","answer":"الجواب: يقول الله سبحانه: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] ويقول النبي ﷺ: لا يجني الجاني إلا على نفسه فلا تطلقها من أجل أبيها، ما دامت مستقيمة؛ فالحمد لله، الزمها، وأحسن إليها، وعاملها بما ينبغي من المعاملة الطيبة: خياركم خياركم لنسائهم فعليك بالخلق الطيب، والمعاملة الحسنة مع زوجتك. أما أبوها فعليك أن تدعو له بالهداية، ادع الله له بالهداية، وانصحه كثيرًا، أنت ومن معك من إخوانك الطيبين، تذهبون إليه.. تنصحونه؛ لأن أداء الصلاة أمر مفترض، والصلاة ركن من أركان الإسلام، بل هي عمود الإسلام. فعليك أنت وإخوانك الطيبين أن تنصحوه، وتوجهوه إلى الخير، وأن تلاحظوه دائمًا، ولعل الله يهديه على أيديكم، فإن أبى؛ فيستحق الهجر؛ يهجر.. لا تدعوه لوليمة، ولا تجب لدعوته إن دعاك حتى يتوب. لكن مهما استطعت أن تنصح أنت وإخوانك الطيبون من جيرانه وأقاربه؛ فاحرصوا، يقول النبي ﷺ في الحديث الصحيح: لأن يهدي الله بك رجلًا واحدًا خير لك من حمر النعم ويقول ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه وأنتم تستطيعون -بحمد الله- باللسان؛ فأنكروا عليه باللسان، وأشيروا عليه، وانصحوه، وكرروا عليه؛ لعل الله يجعل الهداية على أيديكم، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14934/حكم-طلاق-المراة-لان-والدها-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75202.mp3","categories":["الطلاق","نصائح وتوجيهات"]},{"id":16270,"question":"من محافظة مطروح، في جمهورية مصر العربية المستمع: (ج. م. ع) رسالة يقول فيها: إنني أتخلف أحيانًا عن صلاة الفجر بسبب تكاسل شديد يمنعني من أن أفتح عيني، فلا أقوم من النوم إلا بعد طلوع الشمس، ثم أصلي، ما هو توجيهكم لي؟ جزاكم الله خيرًا.","title":"ما النصيحة لمن يتكاسل عن صلاة الفجر؟","answer":"الجواب: هذا العمل منكر، لا يجوز لك أن تتساهل بصلاة الفجر، ولا بغيرها، بل يجب على المسلم والمسلمة الصلاة في الوقت، وليس للمسلم، ولا للمسلمة تأخير الصلاة عن وقتها، لا الفجر ولا غيرها، بل هذا من خصال أهل النفاق، قال الله  في أهل النفاق: إِنَّ الْمُنَافِقِينَ يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ وَإِذَا قَامُوا إِلَى الصَّلاةِ قَامُوا كُسَالَى [النساء:142]. فأنت بهذا العمل، عملك أردى من عمل المنافقين، هم يقومون وأنت ما قمت، أخرتها إلى بعد الشمس، فالواجب عليك أن تصلي في الوقت، وأن تكون نشيطًا قويًا، وأن تصليها مع الجماعة، ولا تتشبه بأهل النفاق، قال النبي ﷺ: أثقل الصلاة على المنافقين: صلاة العشاء، وصلاة الفجر، ولو يعلمون ما فيهما  يعني: من الأجر لأتوهما ولو حبوا وقال النبي ﷺ: من سمع النداء فلم يأت؛ فلا صلاة له إلا من عذر قيل لابن عباس ! ما هو العذر؟ قال: مرض أو خوف. وجاء إليه ﷺ رجل أعمى، فقال: يا رسول الله! ليس لي قائد يلائمني إلى المسجد -وفي لفظٍ: يقودني إلى المسجد- فهل لي من رخصة أن أصلي في بيتي؟ فقال له -عليه الصلاة والسلام-: هل تسمع النداء بالصلاة؟ -يعني: الأذان- قال: نعم، قال: فأجب أمره النبي ﷺ أن يجيب وهو أعمى، ليس له قائد يقود إلى المسجد، فكيف بالصحيح البصير، يكون الأمر عليه أعظم. فالواجب عليك أن تتقي الله، وأن تصلي مع الجماعة، وأن تبادر بالصلاة في وقتها. والذي يتعمد تأخيرها عن وقتها؛ يكفر عند جمعٍ من أهل العلم؛ لأنه متعمد تركها، وقد قال -عليه الصلاة والسلام-: بين الرجل وبين الكفر والشرك ترك الصلاة وقال -عليه الصلاة والسلام-: العهد الذي بيننا وبينهم الصلاة، فمن تركها؛ فقد كفر فظاهر هذا الحديث أن من تعمد تركها حتى تطلع الشمس بغير عذر؛ يكون كافرًا، نسأل الله العافية. فالواجب الحذر، وأن تصلي في الوقت، وأن تصلي مع الجماعة في المسجد، وعليك أن تفعل الأسباب التي تعينك على ذلك، عليك أن تعتني بالأسباب المعينة على قيامك إلى الصلاة، وذلك بالنوم المبكر، عليك أن تنام مبكرًا، حتى لا تكسل عن الفجر، وعليك أن تحتفظ بالساعة التي تسمع صوتها، ساعة الخراش التي تعينك على ذلك، توكدها على قرب الفجر حتى إذا خرشت؛ قمت، سمعت صوت المنبه، أو يكون عندك امرأة تعينك على ذلك، أو أبوك، أو أخوك. المقصود: لابد من القيام للصلاة، سواء بإيقاظ بعض أهلك، أو بوجود الساعة التي توكدها ... على قرب الوقت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14957/ما-النصيحة-لمن-يتكاسل-عن-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_808/nour_80808.mp3","categories":["نصائح وتوجيهات","حكم الصلاة وأهميتها"]},{"id":16292,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من حقل يقول: خضر سالم، أخونا في أحد أسئلته يقول: ماذا يجب على الشاب الذي يريد أن يتعفف عن الشهوات، ويتبع طريق الحق؟ جزاكم الله خيرًا.","title":"الواجب على الشاب الذي يريد التعفف","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالواجب على الشاب، وعلى غير الشاب تقوى الله -جل وعلا- في جميع الأوقات، والحذر من كل ما حرم الله، ليس هذا خاصًا بالشاب، بل بكل مكلف، وكل مكلفة من الرجال والنساء، وإن كان ابن ثمانين، أو تسعين، يجب على كل مسلم شابًا أو شيخًا، رجلًا أو امرأة أن يتقي الله، وأن يبتعد عن محارم الله، وأن يحافظ على طاعة الله ورسوله التي أوجب الله عليه، وأن يبتعد عن كل ما يغضب الله  وأن يبذل وسعه في ذلك أينما كان سفرًا وحضرًا، في شدة ورخاء، في صحة ومرض .. في جميع الأحوال. ومتى صدق في ذلك، وعلم الله من قلبه الإخلاص؛ يسر الله أمره وأعانه ووفقه كما قال : وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2، 3].. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. ومن تقوى الله أن يصحب الأخيار، يجتهد في صحبة الطيبين الذين يعينونه على طاعة الله، ويباعدونه عن محارم الله، ويبتعد عن صحبة الأشرار، وهكذا المرأة تحرص على لزوم بيتها، وإن دعت الحاجة إلى الخروج؛ فليكن للأخيار الطيبين.. الخيرات الطيبات بإذن زوجها إن كان لها زوج، وتبتعد عن زيارة من يدعو إلى الشر، أو يخشى منه الشر، وهذا هو الطريق السوي للنجاة من أسباب الشر، أن يبتعد الإنسان عما حرم الله، وأن يحرص على أداء ما أوجب الله، وأن يشتغل بالخير من قراءة القرآن الكريم وذكر الله  وغير هذا من وجوه الخير، وأن يصحب الطيبين، ويبتعد عن صحبة الأشرار .. إلى غير هذا من وجوه الخير، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14979/الواجب-على-الشاب-الذي-يريد-التعفف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_75301.mp3","categories":["نصائح وتوجيهات"]},{"id":16317,"question":"رسالة وصلت إلى البرنامج من المستمع عبدالرحمن محمود يقول: عند قراءتي لكتاب الله العزيز أخطئ في بعض الكلمات، فما الحكم؟","title":"توجيه لمن يقرأ القرآن ويخطئ في بعض الكلمات","answer":"الجواب: عليك أن تجتهد، وأن تتعلم من الذين يعرفون، وأبشر بالخير -إن شاء الله- يقول النبي ﷺ: الماهر بالقرآن مع السفرة الكرام البررة، والذي يقرأ القرآن وهو عليه شاق، ويتتعتع فيه له أجران فأنت -إن شاء الله- مع الاجتهاد، والتحري لك أجران، لكن عليك أن تجتهد في القراءة على أهل العلم من زملائك، ومن المدرسين، وممن تظن أن عنده علمًا حتى تستفيد، اجتهد، وأبشر بالخير -إن شاء الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15015/توجيه-لمن-يقرا-القران-ويخطى-في-بعض-الكلمات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_753/nour_753015.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":16327,"question":"رسالة وصلت إلى البرنامج بتوقيع إحدى الأخوات المستمعات تقول: أم محمد من الرياض، أم محمد لها جمع من الأسئلة في أحدها تقول: أنا امرأة أكره الذهاب لحفلات الأعراس؛ لما فيها من تفاخر بين النساء في الملبس والتسريحات، ولكن الجميع يغضب مني، ويريد دليلًا على التحريم، أو الكراهية، أرجو التوضيح مأجورين جزاكم الله خيرًا.","title":"حكم حفلات الزواج والتفاخر فيها بين النساء","answer":"الجواب: المشروع حضور الزواج، حضور حفل الزواج مع الرجل، ومع المرأة، المرأة مع النساء، والرجل مع الرجال؛ لإعلان النكاح، والنبي ﷺ أمر بإعلان النكاح، واجتماع النساء ليلة العرس موجود في عهد النبي ﷺ، وكان أزواج النبي ﷺ يحضرن ذلك، وهن خير النساء، وأفضل النساء، فلا ينبغي التحرج من ذلك، إذا كان الاحتفال ليس فيه منكر. أما كون النساء يلبسن ملابس جميلة، هذه من عادة الناس في الزواج، لبس الملابس الجميلة، وتحري الملابس الجميلة هذا غير مستنكر، كذلك ضرب الدف، والغناء العادي بين النساء؛ لا بأس بذلك، كل هذا من إعلان النكاح، إذا كن وحدهن ليس فيه اختلاط، فننصحك بعدم التأخر، وعدم التشويش على غيرك، وإذا حضرت، ورأيت منكرًا، أو رأيت شيئًا ما يناسب؛ انصحي، ووجهي إلى الخير، وأعيني على الخير، يقول النبي ﷺ: من دل على خير؛ فله مثل أجر فاعله ويقول ﷺ: من رأى منكم منكرًا؛ فليغيره بيده، فإن لم يستطع؛ فبلسانه، فإن لم يستطع؛ فبقلبه، وذلك أضعف الإيمان وهذا يعم الرجال، والنساء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15011/حكم-حفلات-الزواج-والتفاخر-فيها-بين-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81011.mp3","categories":["نصائح وتوجيهات","قضايا المرأة"]},{"id":16331,"question":"مع بداية هذه الحلقة نعود إلى رسالة وصلت إلى البرنامج من المستمع عبدالرحيم أحمد من أبو ظبي، الأخ عبدالرحيم عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل ويقول: إذا خطب الإنسان من أناس، فهل له أن يذهب إلى بيتهم ليزورهم من أجل أن يتم الاتفاق على كل شيء؟ وكذلك من أجل أن تحصل الألفة بين العروسين؟ وجهونا جزاكم الله خيرًا.","title":"حكم زيارة الخاطب أهل المخطوبة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج في الزيارة من الخطيب إلى أهل المخطوبة، لا بأس بذلك إذا كان في ذلك مصلحة للخاطب والمخطوبة، للتعرف، ولمعرفة أحوال الجميع، وللتعاون على البر والتقوى، المقصود: أنه لا حرج في الزيارة للمصلحة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15027/حكم-زيارة-الخاطب-اهل-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75401.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16348,"question":"رسالة بعث بها أحد الإخوة المستمعين يقول المرسل: (خ. ع. م) يقول: يا سماحة الشيخ! إنني أعمل في مطبخ، وفي قصر للأفراح، والمشكلة التي تواجهني أنا وزملائي أننا في كل زواج يتم ذبح غنم في الغالب من عشر إلى ثلاثين، حسب طلب صاحب الزواج، ويتم توزيعها بأكملها على التباسي، والصحون، إلا أنها لا تؤكل كلها، مما يضطرنا إلى وضعها في الزبالة، فبماذا توجهوننا نحن كعمال؟ وبماذا توجهون الناس حول هذا الذي نراه من الإسراف، والتبذير؟ جزاكم الله خيرًا، وأحسن إليكم.","title":"كيفية التعامل مع الفائض من أطعمة المناسبات","answer":"الجواب: هذه اللحوم التي تفضل الواجب أنها توزع بين الفقراء، توزع في الحارات التي فيها الفقراء، أو تعطاها الجمعيات التي تقوم بهذا الواجب، توزع، فيه جمعيات تقوم بهذا، فالواجب عليكم، وعلى صاحب المطعم، الواجب عليكم جميعًا أن تفعلوا ما تستطيعون، إما توزيعه على الفقراء، أو تسليمها للجهات التي توزعها، ولا يجوز طرحها في الزبالة، بل تحفظ حتى تسلم للفقراء، أو للجمعيات المتبرعة التي توزعها بين الفقراء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، هل من كلمة إلى أصحاب المناسبات شيخ عبدالعزيز ؟ الشيخ: نعم، نعم.. نوصي جميع أصحاب المناسبات في زواج، أو غيره أن يحرصوا على إيصال فضل الطعام إلى الفقراء والمساكين، ولا يجوز طرح ذلك في الزبالة، ولا في مكان غير مناسب ممتهن، بل يجب حفظ الطعام في الثلاجات حتى يوصل إلى الفقراء والمساكين، فإذا كان ولابد -لم يجد فقراء ولا مساكين ولا جمعيات- يجعله في مكان نظيف، بعيد عن الامتهان، في البرية، يذهب به إلى البرية في مكان نظيف، بعيد عن الطرقات، تأكله السباع، والكلاب، والطيور، ولا يمتهنه أحد، إذا لم يتيسر دفعه للفقراء، والمساكين، أو لجمعيات.. جمعيات الإغاثة، الجمعيات التي توزع على الفقراء، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15042/كيفية-التعامل-مع-الفاىض-من-اطعمة-المناسبات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71411.mp3","categories":["نصائح وتوجيهات"]},{"id":16358,"question":"تقول يا سماحة الشيخ هذه الأم السائلة: إذا دعا الشخص على أولاده هل يجاب الدعاء؟","title":"التحذير من الدعاء على الأبناء","answer":"الجواب: على خطر، ينبغي له ألا يدعو، ينبغي أن يدعو بالخير، إذا غضب على أولاده لا يدعو عليهم إلا بالخير، يتقي الله؛ لئلا تصادف ساعة إجابة، فينبغي للمؤمن أن يتحرى الدعاء الطيب، وإذا غضب على أولاده يدعو لهم بالهداية والصلاح، لا يدعو عليهم، هذا هو الذي ينبغي له؛ يتحرى الخير، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15057/التحذير-من-الدعاء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58108.mp3","categories":["الأدعية والأذكار","تربية الأولاد","نصائح وتوجيهات"]},{"id":16404,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين كل هذه الرسالة -سماحة الشيخ- وتتكون من ثلاث صفحات من القطع الصغير شكوى من والدته، فيقول عنها: لي والدة متسلطة، فهي دائمًا تخلق لي ولزوجتي المشاكل، بل ولإخوتي الآخرين، وأنا بشكل أخص، فمن ذلك أنها تفضل زوجات أخي بسبب الراتب الذي يتقاضينه، بعكس زوجتي التي ليس لها راتب، ويستمر في سرد قضايا كهذه القضية يا سماحة الشيخ! ويرجوكم التوجيه جزاكم الله خيرًا.","title":"توجيه لمن يعاني من مشاكل مع أمه","answer":"الجواب: نوصيك بالوالدة خيرًا، نوصيك أيها الأخ بالوالدة خيرًا، وأن تعفو عما يقع منها، وأن تخاطبها بالتي هي أحسن، وتطلب منها السماح، والعفو عما قد يقع منك، أو من زوجتك، وإذا فضلت بعض الزوجات لأجل ما يحصل من دراهم من عندهم، لا حرج عليها في مقابلة المعروف بالمعروف إذا كان يعطونها من رواتبهم، وتفضلهم ببعض الشيء لأجل ما يحصل منهم من المساعدة لها لا بأس، فالرسول ﷺ يقول: من صنع إليكم معروفًا؛ فكافئوه فإذا كافأتهم بكلام طيب، أو بهدية، ولم تعط زوجتك مثلها؛ فلا بأس، لأنهم أحسنوا إليها.  المقصود: أن عليك أن تعامل الوالدة بالكلام الطيب، والأسلوب الحسن، وتوصي زوجتك بالكلام الطيب، والأسلوب الحسن مع الوالدة، وما حصل من الوالدة من بعض التفضيل للزوجات -زوجات إخوتك- لا حرج فيه، إذا كان للأسباب التي ذكرت. وفي كل حال حتى لو أخطأت عليك الوالدة، وحتى لو سبتك عليك بالرفق، والكلام الطيب، وطلبها العفو، والسماح عنها؛ لأن حقها عظيم، حق الوالدين عظيم، وحق الأم أكبر، قال رجل: يا رسول الله! من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب فالأم لها شأن عظيم.  فعليك أن تحرص على رضاها، وعلى معاملتها بالتي هي أحسن، وإن أساءت إليك، وإن تعدت عليك، وإن.. عليك أن تصفح، وتعفو عنها، وتطلب رضاها دائمًا، وهكذا زوجتك، عليها أن تجتهد في المعاملة الطيبة مع أمك، أصلح الله حال الجميع. المقدم: اللهم! آمين، جزاكم الله خيرًا، الواقع سماحة الشيخ! كما تفضلتم كثيرًا ما يصل شكاوى من الزوجات من أمهات الأزواج لعلها مناسبة كريمة أن تتفضلوا بتوجيه الزوجات كيما يكن عونًا للأزواج على البر بالأمهات؟ الشيخ: نعم، الواجب على الزوجات أن يتقين الله  وأن يحرصن على إصلاح الحال بين الرجل، وأمه، وأبيه، وألا يكن سببًا للفساد، والشر، والعقوق، والواجب على الولد أن يتقي الله في أبيه، وأمه، وأن يبرهما، وأن يحسن معاشرتهما، وملاطفتهما، حتى ولو أساءا إليه، حتى ولو ضرباه؛ يجتهد في إرضائهما، وطلب السماح منهما، قال الله -جل وعلا- في كتابه الكريم: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ[لقمان:14] وقال سبحانه: وَإِنْ جَاهَدَاكَ [لقمان:15] يعني الوالدان وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَاا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]. أمر بمصاحبتهما بالمعروف وإن كانا كافرين لعظم حقهما، قال: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا لكن لا تطعهما في المعصية والشرك، لا يطاع أحد في المعصية والشرك، لكن تجتهد في العبارات الطيبة، والأسلوب الحسن، في الاعتذار إليهما، وعدم السمع، والطاعة لهما في المعصية، وأن هذا لا يجوز لك، وأن الرسول ﷺ نهاك عن الطاعة في المعاصي لأحد من الناس، وتجتهد في دعوتهما إلى الخير، وترغيبهما في الخير، وهكذا زوجتك تجتهد في المعاملة الطيبة مع والديك، حتى لا تكون أنت سببًا لعقوقه إياهما، أو سببًا لتعديهما عليك، أنت وزوجتك عليكما العناية بحق الوالدين، والحرص على إكرام الوالدين، والسمع والطاعة لهما في المعروف، وعدم الإساءة إليهما، وإذا أخطأا عليك، أو على الزوجة؛ فاجتهد في إظهار السماح، والعفو، والصفح، وأحسن معهما الخلق والكلام. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15110/توجيه-لمن-يعاني-من-مشاكل-مع-امه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_715/nour_71505.mp3","categories":["نصائح وتوجيهات"]},{"id":16447,"question":"السائلة تقول يا سماحة الشيخ بأنها طالبة في الصف الثاني الثانوي، ويكون هناك وقت فراغ بين الحصص، وتقضي هذا الفراغ بقراءة القرآن، وتحمد الله على ذلك، وتقول الأخت السائلة: لكنني أحس أحيانًا بأنني لا أخلص العمل لله  وأحس بأني مرائية، فأتوقف عن قراءة القرآن، وأشتغل بشيء آخر؛ علمًا بأنه لا يوجد أحد في الصف يقضي معي وقت الفراغ بقراءة القرآن مثلي، وهذا مما يزيد من إحساسي، وشعوري بالمراءاة، فهل لكم توجيه يا سماحة الشيخ؟","title":"توجيه لمن يترك الأعمال الصالحة خوف الرياء","answer":"الجواب: نعم، ننصحك بالقراءة، والاجتهاد في الخير، واتركي الوساوس، وساوس الشيطان بالمراءاة، واجتهدي في القراءة، وأفعال الخير، ولا تبالي بهذه الوسوسة، اطرحيها، واحذريها، فهذا من الشيطان للتثبيط عن الخير، فعليك بالإخلاص لله، والحرص على الخير من القراءة، وصلاة النافلة، وصوم النافلة، وغير ذلك، واحذري وساوس الشيطان المثبط، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15149/توجيه-لمن-يترك-الاعمال-الصالحة-خوف-الرياء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58202.mp3","categories":["نصائح وتوجيهات","الرياء والسمعة"]},{"id":16473,"question":"من الكويت السائلة (أ. أ. أ) تقول: سماحة الشيخ! والدي يسهر مع مجموعة من أصدقائه غير الطيبين حتى منتصف الليل، ونحن مجموعة من البنات، وطفل صغير في العاشرة من عمره، ووالدتي امرأة مريضة، وكلما نصحنا هذا الأب عن تأخره؛ نهرنا وسبنا، ماذا نعمل معه؟ مع أن لنا جارًا صالحًا إمامًا للمسجد، هل نخبره عن واقع والدنا لعله يناصحه؟","title":"واجب الأولاد تجاه والدهم الذي يجالس رفقاء السوء","answer":"الجواب: نصيحته مهمة، ينصح منكم، وممن يعلم حاله من الجيران، ينصحونه حتى لا يتأخر في المبيت، النبي ﷺ كان يكره النوم قبل العشاء، والسمر بعدها، وإذا أخبرتم الجار ينصحه من باب النصيحة؛ فلا بأس، أو غير الجار من الأقارب ينصحونه؛ فهذا طيب، ولكن لا يعلم أنكم قلتوا له شيئًا؛ حتى لا يكون شرًا بينكم وبينه، توعزون للجار، أو غير الجار من الأقارب أن ينصحوه عن السهر، ولا يبين أنكم أبلغتموه، لا يبين الجار، أو غيره أن فلانة أبلغتني كذا وكذا، كأنه بلغه من غيركم. فالمقصود: أن نصيحته مهمة، والدعاء له، تدعو له بالتوفيق في السجود، وفي آخر الصلاة، وفي غير ذلك، تدعو له: أن الله يهديه، وأن الله يعيذه من الشيطان، ومن جلساء السوء، هذا أمر مطلوب، والوالد له حق عظيم، تدعو له أن الله يوفقه، ويهديه، ويكفيه شر جلساء السوء، ويعيذه من شر نفسه والشيطان، كل هذا طيب. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15177/واجب-الاولاد-تجاه-والدهم-الذي-يجالس-رفقاء-السوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58208.mp3","categories":["نصائح وتوجيهات"]},{"id":16474,"question":"من الكويت السائلة (أ. أ. أ) تقول: سماحة الشيخ! والدي يسهر مع مجموعة من أصدقائه غير الطيبين حتى منتصف الليل، ونحن مجموعة من البنات، وطفل صغير في العاشرة من عمره، ووالدتي امرأة مريضة، وكلما نصحنا هذا الأب عن تأخره؛ نهرنا وسبنا، ماذا نعمل معه؟ مع أن لنا جارًا صالحًا إمامًا للمسجد، هل نخبره عن واقع والدنا لعله يناصحه؟","title":"واجب الأولاد تجاه والدهم الذي يجالس رفقاء السوء","answer":"الجواب: نصيحته مهمة، ينصح منكم، وممن يعلم حاله من الجيران، ينصحونه حتى لا يتأخر في المبيت، النبي ﷺ كان يكره النوم قبل العشاء، والسمر بعدها، وإذا أخبرتم الجار ينصحه من باب النصيحة؛ فلا بأس، أو غير الجار من الأقارب ينصحونه؛ فهذا طيب، ولكن لا يعلم أنكم قلتوا له شيئًا؛ حتى لا يكون شرًا بينكم وبينه، توعزون للجار، أو غير الجار من الأقارب أن ينصحوه عن السهر، ولا يبين أنكم أبلغتموه، لا يبين الجار، أو غيره أن فلانة أبلغتني كذا وكذا، كأنه بلغه من غيركم. فالمقصود: أن نصيحته مهمة، والدعاء له، تدعو له بالتوفيق في السجود، وفي آخر الصلاة، وفي غير ذلك، تدعو له: أن الله يهديه، وأن الله يعيذه من الشيطان، ومن جلساء السوء، هذا أمر مطلوب، والوالد له حق عظيم، تدعو له أن الله يوفقه، ويهديه، ويكفيه شر جلساء السوء، ويعيذه من شر نفسه والشيطان، كل هذا طيب. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15177/واجب-الاولاد-تجاه-والدهم-الذي-يجالس-رفقاء-السوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58208.mp3","categories":["نصائح وتوجيهات"]},{"id":16491,"question":"هذا السائل (علي .ف. ع) يقول: سماحة الشيخ! من أسئلتي: أنا رجل، يقول: بأنه ارتكب ذنوبًا ومعاصي، منها الصغائر، ومنها الكبائر، وقد منَّ الله عليه بالتوبة، ويحمد الله على ذلك، ولكن يقول: دائمًا ما أتذكر هذه الذنوب والمعاصي، ويدخل بها الشيطان علي في صلاتي، وقد أسرح، ولا أعرف ماذا أقول في صلاتي، هل أتممت الواجبات والأركان، أم لا، وأنا أحاول جاهدًا مجاهدة نفسي، فما توجيه سماحتكم؟ وهل علي ذنب في ذلك؟","title":"التحذير من الوساوس وعلاجها","answer":"الجواب: ننصحك بأن تحذر هذه الوساوس، وأن تتعوذ بالله من الشيطان إذا عرضت لك، وتتفل عن يسارك ثلاث مرات، وتقول: أعوذ بالله من الشيطان ثلاث مرات، وهكذا كلما عرض لك... تستعيذ بالله من الشيطان، تعاند عدو الله، ترغمه، هذا عدو الله يؤذيك؛ فعليك أن تلجأ إلى الله في طلب العافية منه، وتسأله في سجودك، وفي غير ذلك أن الله يعافيك من هذه الوساوس، وأنت -والحمد لله- على خير، ما دمت صدقت في التوبة فأنت على خير عظيم، وهذه من عدو الله ليؤذيك، فعليك أن تتعوذ بالله منه، وأن تستعيذ بالله منه، وأن تلجأ إلى الله، وتسأله العافية، وأبشر بالخير. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15201/التحذير-من-الوساوس-وعلاجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58218.mp3","categories":["الأدعية والأذكار","الرقائق","نصائح وتوجيهات"]},{"id":16508,"question":"هل من كلمة أيضًا للشباب الذين بدؤوا هذا الالتزام، وبدؤوا يمارسون الدعوة إلى الله، ويلتزمون بأحكام السنن، هل من كلمة يتفضل بها سماحة الشيخ؟","title":"وصية للشباب والدعاة بالحكمة في الدعوة إلى الله","answer":"الجواب: نعم نوصيهم بتقوى الله، وأن يشكروا الله على ما من به عليهم من الالتزام بطاعة الله ورسوله، ونوصيهم بعدم العجلة في الأمور، وعدم التشديد الذي لا يوافق الشرع، بل نوصيهم بالتثبت، والتوسط في الأمور، وعدم الغلو، وعدم الجفاء، لا هذا ولا هذا، الواجب التوسط في الأمور، فلا غلو ولا جفاء، لا إفراط ولا تفريط، بل إذا التزم بالحق بإعفاء لحيته، والصلاة في الجماعة بالطمأنينة، بعدم الإسبال، بعدم حلق اللحية يستقيم على ذلك، ويسأل ربه العون والتوفيق.  ولا يعنف على الآخرين بشدة، بل يدعوهم إلى الله بالحكمة، والكلام الطيب، يا أخي! الرسول ﷺ أمر بإعفاء اللحى، يا أخي! نوصيك بإعفائها، يا أخي! لا تسبل ثيابك، الرسول ﷺ نهى عن الإسبال، نهى عن الخيلاء بالكلام الطيب، والأسلوب الحسن الذي يرجى من ورائه قبول الحق، والتأثر، فإن الشدة قد يحصل بها التنفير، والمخاصمة، والنزاع، ولكن بالكلام الطيب، والأسلوب الحسن يحصل الخير الكثير، يقول الله : ادْعُ إِلَى سَبِيلِ رَبِّكَ بِالْحِكْمَةِ وَالْمَوْعِظَةِ الْحَسَنَةِ وَجَادِلْهُمْ بِالَّتِي هِيَ أَحْسَنُ [النحل:125] هكذا أرشدنا مولانا . ويقول -جل وعلا- في كتابه العظيم، في وصف النبي ﷺ: فَبِمَا رَحْمَةٍ مِنَ اللَّهِ لِنْتَ لَهُمْ وَلَوْ كُنْتَ فَظًّا غَلِيظَ الْقَلْبِ لانْفَضُّوا مِنْ حَوْلِكَ [آل عمران:159] ويقول الله لموسى وهارون لما بعثهما إلى فرعون، قال سبحانه: فَقُولا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى [طه:44] ويقول سبحانه في جدال أهل الكتاب اليهود والنصارى: وَلا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ [العنكبوت:46] فإذا كان اليهود والنصارى يجادلون بالتي هي أحسن، فكيف بالمسلم؟! من باب أولى. فوصيتي للشباب وغير الشباب لجميع من يأمر بالمعروف وينهى عن المنكر، لجميع الدعاة إلى الله، وصيتي للجميع الرفق في الأمور كلها، والجدال بالتي هي أحسن، وتحري الأسلوب الجيد اللين؛ لعل الله ينفع بذلك. كما نوصي بالحذر من العنف، والشدة والكلام البذي؛ فإن هذا ينفر من الحق، وربما سبب خصومة، ونزاعًا، ومقاتلة ومضاربة، والمؤمن قصده الخير، والداعي إلى الله قصده الخير، فينبغي سلوك أسباب الخير، الواجب على الداعي إلى الله، والآمر والناهي أن يسلك المسالك التي تعينه على حصول الخير، وتعين إخوانه على قبول الحق، نسأل الله للجميع الهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15265/وصية-للشباب-والدعاة-بالحكمة-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_814/nour_81411.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات"]},{"id":16542,"question":"نعود مع بداية هذه الحلقة إلى رسالة وصلت إلينا من الأردن، صاحبها نسي أن يذكر اسمه، عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة يسأل عن قضية بين امرأة وأخيها، يقول: إن هناك امرأة تشكو من أخ لها قاسٍ، وتصفه بأوصاف سيئة، وتقول: إنه يهددها بالتسبب في طلاقها من زوجها، وترجو التوجيه، جزاكم الله خيرًا، وكيف تقابل مثل هذا الأخ؟","title":"وصية لامرأة تشكو من سوء معاملة أخيها لها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالذي أنصح به هذه المرأة أن تستعمل الأسلوب الحسن مع أخيها، والكلام الطيب، وأن تدعو له بظهر الغيب، أن الله يوفقه، ويهديه، ويعيذه من الشيطان، ومن ظلمها، وظلم زوجها، وتسأل عن الأسباب التي تسبب المشاكل حتى تحل، وإذا تيسر أن يتوسط بينهما أعمام، أو أخوال، أو جيران طيبون، يصلحون بينهما؛ فهذا طيب. على كل حال أوصيها بالرفق، والكلام الطيب، والأسلوب الحسن، والتحمل، والصبر حتى يحل الله المشكلة بينهما، إلا أن يكون الزوج غير طيب في دينه، وأن أخاها يريد منها مفارقته لفساد دينه، كونه ما يصلي، أو لكونه يسب الدين، أو لكونه صاحب معاصي ظاهرة، فيكون أخوها في هذا مصيبًا ناصحًا لها، فإذا طلبت من هذا الزوج أن يستقيم أو يطلقها إن كان مسلمًا، أما إن كان لا يصلي، أو كان عنده شيء من نواقض الإسلام من سب الدين، أو التعلق بعبادة القبور، فهذا لا يجوز بقاؤها معه، وهي مسلمة، وأخوها ناصح لها، فيجب عليها أن تفارقه، وأن تطلب من المحكمة التفريق بينهما، وأن لا يقربها إذا كان كافرًا، لا يقربها أبدًا، لا بجماع، ولا غيره حتى يتوب الله عليه. فالحاصل: أنه إذا كان هناك أمور دينية ينقمها الأخ على الزوج، فينبغي لها أن تتصل بولاة الأمور في المحكمة، وتعرض مشكلتها مع الزوج على المحكمة، والمحكمة تنظر في الأمر، إن كان مسلمًا؛ نصحته المحكمة بالتوبة إلى الله من معاصيه، وإن كان كافرًا؛ نصحته المحكمة بالتوبة، والرجوع إلى الله، ومن تاب؛ تاب الله عليه، وبالرفق والحكمة، والرجوع إلى ما شرع الله تنتهي المشاكل، وتحل المشاكل -بإذن الله- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15266/وصية-لامراة-تشكو-من-سوء-معاملة-اخيها-لها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_815/nour_81501.mp3","categories":["الدعوة والدعاة","نصائح وتوجيهات","قضايا المرأة"]},{"id":16550,"question":"رسالة وصلت إلى البرنامج من المستمع، عبدالرحيم أحمد من أبو ظبي يسأل فيها سؤالًا فيقول: قام شاب بخطبة شابة من أهلها، وقاموا بقراءة الفاتحة بينهم؛ لتكون ارتباطًا بينهما، وبعد أسبوعين سافر هذا الشاب إلى إحدى الدول العربية للعمل بها ...الشيخ: أعد، أعد.المقدم: يقول: قام شاب بخطبة شابة من أهلها، وقاموا بقراءة الفاتحة بينهم؛ لتكون ارتباطًا بينهما، وبعد أسبوعين سافر هذا الشاب إلى إحدى الدول العربية للعمل بها، فهل يجوز لهذا الشاب أن يراسلها وتراسله من أجل أن يتفهم كل منهم الآخر، ومن أجل تقريب نظرية كل منهم للآخر؟ جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة عند الخطبة، ومراسلة المخطوبة","answer":"الجواب: قراءة الفاتحة ما لها أصل... بينهما ليس لهذا أصل، الخطبة وحدها ما تكفي، وقراءة الفاتحة لا وجه لها في هذا المقام، وإنما تقرأ الفاتحة، والحمد عند العقد، إذا أراد العقد يقرأ السنة ما هو الفاتحة، يقرأ: إن الحمد لله نحمده ونستعينه... كما كان النبي ﷺ يفعل في الحاجة، خطبة الحاجة، ما هو يقرأ الفاتحة، يقرأ: إن الحمد لله.. إلى آخره، كما جاءت به السنة من حديث ابن مسعود في خطبة الحاجة، أما هذه فهذه من خرافات العامة، ومن أعمال العامة، إذا قرأ الفاتحة للربط بينهما، هذا ما له أصل، كلام ما له أصل، إنما الخطبة لا بأس بها، وكل منهم بالخيار، الخطبة ما تلزمهم، من شاء ترك هون. من شاء هون هي تهون، وهم يهونون كل من شاء منهم التهوينة له يهون لا بأس، إنما العمدة على العقد. أما المراسلة بعد الخطبة كونه يراسلها، ويسألها عن حالها وعن دروسها، أو عن كذا عن شيء ينفع، أو تراسله لتسأل عن شيء مهمات، مراسلة ما فيها خطر، ما فيها شر، ولا تدعو إلى خلوة، ولا تدعو إلى فساد، ولا زنا، هذا لا بأس. أما إذا كانت مراسلة قد يخشى منها الشر؛ فلا ينبغي أن يراسلها، ولا ينبغي أن تراسله، وينبغي سد الباب حتى لا يتهموا بالشر.  لكن إذا كانت المراسلة واضحة يعرفها أهلهما، ليس فيها شبهة، ولا توقع في شبهة، إنما هي لحاجتهما للتفاهم في بعض المسائل؛ فلا بأس بذلك، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15290/حكم-قراءة-الفاتحة-عند-الخطبة-ومراسلة-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75714.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16571,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية اليمنية، وباعثتها إحدى الأخوات من هناك، رمزت إلى اسمها بالحروف (ف. ع. ج) لها جمع من الأسئلة، ملخص سؤالها الأول تقول: إن والدها يعارضها في مواصلة الدراسة، وترجو من سماحتكم التوجيه لها ولوالدها؟","title":"نصيحة لمن يمنع بناته من الدراسة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن طلب العلم للنوعين الرجال والنساء من أفضل القربات، ومن أهم الطاعات؛ لقول النبي ﷺ: من سلك طريقًا يلتمس فيه علمًا؛ سهل له به طريقًا إلى الجنة ولقوله -عليه الصلاة والسلام-: من يرد الله به خيرًا؛ يفقهه في الدين ولقوله ﷺ: خيركم من تعلم القرآن وعلمه. فنصيحتي لك وللوالد الاستمرار في الدراسة الإسلامية النافعة المفيدة على يد العلماء المعروفين بالاستقامة، وحسن العقيدة، والسيرة، وذلك من التفقه في الدين الذي هو علامة الخير، وعلامة أن الله أراد بالعبد خيرًا، وعلى الوالد أن يلاحظ ما ينبغي أن يلاحظ من ذهابك إلى المدرسة بصحبة الثقات المأمونات، وعدم ذهابك مع السائق وحده، ومن جهة العناية بالمدرسة إذا كانت المدرسة جيدة، وفيها معلمات معروفات بحسن العقيدة والسيرة، فهذا مما ينبغي للوالد أن يعين عليه. أما إن كانت الدراسة فيها شيء يخشاه الوالد عليك، فاسمعي، وأطيعي للوالد، وهذا من نصحه لك، وبره لك. فالخلاصة: أن عليك أن تتفاهمي مع الوالد في الموضوع، فإذا كانت الدراسة على مدرسات طيبات معروفات بالخير، وتيسر لك الذهاب إلى المدرسة بطريقة سليمة، ليس فيها خلوة بالسائق، ولا غيره، فالوالد يوافق -إن شاء الله- على هذا الخير العظيم، وإن كان هناك أسباب للمنع، فالوالد لا يريد لك إلا الخير -إن شاء الله- فاسمعي، وأطيعي للوالد، وبره من أهم المهمات، والله -جل وعلا- أوصى ببر الوالدين في آيات كثيرات  منها قوله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] أسأل الله أن يوفقك، ووالدك لما فيه براءة ذمة الجميع، وصلاح الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15284/نصيحة-لمن-يمنع-بناته-من-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81601.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":16579,"question":"له حالة معينة تخصه بالذات سماحة الشيخ هل أذكرها، أو لا؟ ويطلب التوجيه فيها؟الشيخ: لا بأس.المقدم: جزاكم الله خيرًا، يقول: إنني عندي طلاقة في الحديث، ولكن ينقصها المعرفة، والعلم الجيد، أي: أنني -هكذا يصف نفسه- أي: أنني إناء فارغ، ولكني إناء قوي -يريد من يستعمله إن صح التعبير- وجهوني جزاكم الله خيرًا.","title":"الوصية بالتفقه في الدين","answer":"الجواب: نوصيك بطلب العلم، والتفقه في الدين؛ حتى تستغل هذا الإناء، فاجتهد في طلب العلم، واحضر حلقات العلم، وإن تيسر لك الالتحاق بالمعاهد العلمية، ثم كلية، فهذا أكمل. ونوصيك بالعناية بالقرآن الكريم، والإكثار من تلاوته، تدبر معانيه؛ فهو أصل كل خير، وينبوع كل خير، وفقك الله ويسر أمرك، نعم. المقدم: آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15305/الوصية-بالتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75804.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":16596,"question":"يسأل ويقول: إنني أقيم الآن في المملكة، وأغيب عن زوجتي عامًا، أو عامًا ونصف، هل في بعدي عن زوجتي وعن أولادي ضرر؟","title":"نصيحة لمن يطيل الغياب عن زوجته","answer":"الجواب: الوصية والنصيحة ألا تبعد عنهم كثيرًا، وإذا بعدت فراجعهم بين الشهرين، والثلاثة، ولا تهملهم، إلا عند الضرورة القصوى، ولاسيما إذا كانت سامحة، وراضية بذلك. فالمقصود: أن المرأة على خطر في بعد زوجها عنها، ولا سيما في هذا العصر، فنصيحتي لك، ولأمثالك عدم البعد عن الزوجة، وعدم طول الغيبة، بل كن قريبًا منها، ولو بالرزق القليل، فإن ذلك فيه خير عظيم لك، ولأهلك، ولا تحرص على كثرة المال مع الغيبة، والبعد عن أهلك، وتعريض نفسك وأهلك للأخطار، فإن الإنسان على خطر، والنفس أمارة بالسوء، والوقت وقت خطير لظهور الفساد في الأرض، وكثرة من يتعرض للمؤمن في حياته الآن بالشر، فينبغي لك أن تحرص على قربك من أهلك، وعلى عفة فرجك، وعفة نظرك، وسمعك، وعفة أهلك، ولو كان الدخل قليلًا، مادام يقوم بحالك، فإذا غبت فلا تطول الغيبة، بل اكتف بالشهرين، والثلاثة؛ لعل ذلك يكفيك، ويحصل به الخير للجميع لك، ولأهلك، رزق الله الجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15321/نصيحة-لمن-يطيل-الغياب-عن-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81704.mp3","categories":["نصائح وتوجيهات","غياب وفقدان الزوج"]},{"id":16622,"question":"سؤالها الأخير الذي نعرضه تقول فيه: أريد أن أحفظ القرآن الكريم، إلا أني أجد في ذلك صعوبة، فما هي نصيحتكم، وإرشاداتكم لي في هذا الموضوع؟ جزاكم الله خيرًا.","title":"توجيهات لمن أراد حفظ كتاب الله تعالى","answer":"الجواب: نوصيك بالاستعانة بالله.. الضراعة إلى الله، أن تسأليه في السجود، في آخر التحيات، في الليل، في آخر الليل، في جوف الليل، تسألينه سبحانه أن يعينك على حفظه، وأنت صادقة خاشعة، تقولي: يا رب أعني على حفظ كتابك العظيم، اللهم أعني على حفظه، اللهم يسر لي حفظه، ومع الدعاء الصادق تجتهدين في العمل، تجتهدين في الحفظ في الأوقات المناسبة التي أنت فيها فارغة في الليل، أو في النهار، تبدئين من البقرة، أو من المفصل، وتقرئين ما تيسر، كل يوم شيئًا ولو قليلًا، تقرئين كل يوم شيئًا، ولو قليلًا، وتجتهدين في دراسته... تكراره حتى يستقر، وهكذا حتى تكملي، إن شاء الله. تحرصين على الأوقات المناسبة في الليل، أو في النهار التي فيها القلب فارغ، وترتبين شيئًا فشيئًا قليلًا: نصفًا... ثمنًا... صفحة كل يوم، كل ليلة صفحتين، حسب التيسير، ومع الصدق، والرغبة فيما عند الله، وسؤال الله التوفيق، والإعانة؛ أبشري بالخير، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2، 3]. فهو سبحانه مع أوليائه المتقين بالتيسير، والتسديد، والتوفيق، والإعانة، يسر الله أمرك، وأعانك، وثبتنا وإياك وجميع المسلمين على الحق والهدى. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15359/توجيهات-لمن-اراد-حفظ-كتاب-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_759/nour_75903.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":16663,"question":"يقول السائل يا سماحة الشيخ: أريد السعادة، ولكن أين الطريق الموصل إليها؟ مع العلم بأنني قد بدأت -والحمد لله- في الاستقامة على شرع الله وسنة رسوله ﷺ وجهوني يا سماحة الشيخ.","title":"توجيه إلى الطريق الموصل إلى السعادة","answer":"الجواب: السعادة طريقها واضح، من أراد السعادة؛ فعليه بأسبابها، وأسبابها: طاعة الله ورسوله، وصحبة الأخيار، والبعد عن صحبة الأشرار، والصبر على المصائب، والشكر عند النعم، هذه السعادة، أن تكون صبورًا على طاعة الله، صبورًا عن معاصي الله، شكورًا عند النعم، بعيدًا عن صحبة الأشرار، قريبًا من صحبة الأخيار، مكثرًا لذكر الله  والدعاء، هذه السعادة، من أراد السعادة؛ فعليه بطاعة الله ورسوله، والاستقامة على دين الله، وصحبة الأخيار، والصبر على مر الأقدار، والشكر عند النعم، هذه السعادة في الدنيا والآخرة، الله المستعان. المقدم: الله المستعان، أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15396/توجيه-الى-الطريق-الموصل-الى-السعادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58320.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":16669,"question":"سماحة الشيخ! هل تتفضلون بكلمة حول صلة الأرحام من قبل المرأة؛ لأنها خصت هذا الموضوع بجزء من السؤال؟","title":"توجيه حول صلة المرأة لأرحامها","answer":"الجواب: نعم، نعم، الجميع عليهم صلة الرحم مثلما تقدم، كلهم سواء في صلة الرحم، وفي بر الوالدين، كبقية الأعمال إلا ما خصه الدليل؛ فعلى المرأة أن تصل رحمها: من أبويها، وأولادها، وإخوانها، وأخواتها، وأعمامها، وعماتها، وأخوالها، وخالاتها، وبني عمها، وبني عمتها.. إلى غير ذلك، الأقرب فالأقرب. يقول النبي ﷺ لما سأله سائل قال: يا رسول الله! من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك، ثم الأقرب فالأقرب هكذا يبدأ بالوالدين، ثم الأقرب فالأقرب، أولاده ثم إخوته، وهكذا، نعم. بالكلام الطيب، وبصلة الرحم، بالمال، ومواساة الفقير.. بالشفاعة للمظلوم.. بالإعانة على ردع الظالم.. بتعليم الجاهل.. بأمره بالمعروف، بنهيه عن المنكر، كل هذا من صلة الرحم، بالمال، وبالفعل، والقول، بالمال، وبالفعل الطيب، وبالقول الطيب، كله من صلة الرحم، كله من بر الوالدين. وهكذا الزيارة النزيهة السليمة التي ليس فيها محذور، هذه من صلة الرحم، كذلك الحرص على السؤال عنه، وعن أحواله، ومساعدته فيما قد يحتاج إليه، وعيادته إذا مرض، والدعاء له بظهر الغيب، كل هذا من صلة الرحم، الستر عليه إذا زلت قدمه، لا يفضحه عند الناس فيما بينه وبين الله.. إلى غير هذا مما ينفع قريبه في الدين والدنيا، كله صلة رحم. لكن لا يصله بمعصية الله، لا يصله بالمعاصي، ولا بالمداهنة، وعدم إنكار المنكر، يصله بما أباح الله، وبما شرع الله، لا بما حرم الله، وفق الله الجميع، نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15428/توجيه-حول-صلة-المراة-لارحامها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76006.mp3","categories":["قضايا المرأة","نصائح وتوجيهات"]},{"id":16670,"question":"سماحة الشيخ كثيرة هي الأسئلة التي تتوارد على الخاطر، وأنا أنصت إلى ما تتفضلون به حول ما اهتم به ديننا تجاه المرأة، وتجاه تكاليفها، وتجاه خطابها كخطاب الرجل سواء بسواء، لعل لسماحتكم من كلمة حول حجاب المرأة، وصلة الأرحام؛ لأن البعض يعتقد أن الحجاب يحول دون صلة الرحم، فما هو تعليق سماحتكم؟","title":"توجيه حول الحجاب وصلة الرحم","answer":"الجواب: الحجاب لا يحول بين المرأة، وصلة الرحم، الحجاب ومنع الخلوة، هذا من كمال الدين، ومن باب البعد عن الشر، والفساد؛ لأنه إذا وصلت أرحامها من بني عم، أو بني عمة، أو بني خال، وهي متبرجة، أو سافرة؛ فهذا من أسباب الفساد، وكذا إذا خلت بواحد من بني عمها، أو بني خالها، هذا من أسباب الفساد. فمن رحمة الله، ومن إحسانه العظيم، ومن كمال الشريعة: أنه حرم على المرأة، وعلى الرجل الخلوة، على الرجل الخلوة بغير محرمه، وعلى المرأة الخلوة بغير محرمها، حرام على هذا وهذا، فعلى الرجل أن يتقي الله، ولا يخلو بمرأة أجنبية، وعلى المرأة أن تتقي الله أيضًا، ولا تخلو برجل أجنبي، لا السائق، ولا غيره، لا السائق، ولا خادم، ولا غيرهما، لا تخلو بالرجل أبدًا. يقول النبي ﷺ في الحديث الصحيح: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما ويقول ﷺ: إياكم والدخول على النساء وفي لفظ: المغيبات اللاتي ما عندهن أحد قيل: يا رسول الله! أفرأيت الحمو؟ قال: الحمو الموت الحمو.  يعني: الأخ، والعم، وابن العم، وابن الخال، والخال، وأشباهه؛ سماه موتًا؛ لأنه خطر، يدخل، ولا يستنكر ..، قد يخلو بزوجة أخيه، أو يخلو بزوجة خاله، أو بزوجة ابن أخيه؛ فتقع المصيبة، وتقع الفاحشة... والواجب الحذر من الخلوة: لا بزوجة الأخ، ولا بأخت الزوجة، ولا بزوجة الخال، ولا بزوجة العم، ولا ابن العم، ولا ابن الخال. أما زوجة الأب محرم، زوجة الجد محرم، زوجة ابنك محرم؛ من النسب والرضاعة، ابن البنت زوجته محرم، وهكذا... محارم بالنسب، أو بالرضاع، بالنسب، والمصاهرة: كأم الزوجة... بنت الزوجة المدخول بها، جدة الزوجة محرم؛ من أجل المصاهرة، سواء كانت من النسب، أو من الرضاع، يقول النبي ﷺ: يحرم من الرضاع ما يحرم من النسب. أما الخلوة فخطرها عظيم، لكن إذا كان معهما ثالث في السيارة، أو في البيت مثلًا: جلس مع امرأة أخيه، وهي مستورة متحجبة، ولكن بحضرة أمه، أو بحضرة أخته، أو بحضرة شخص آخر، لا شبهة فيه، ولا ريبة فيه؛ زالت الخلوة، وهكذا لو ركبت مع السائق ومعها شخص آخر، أو امرأة أخرى بدون ريبة؛ زالت الخلوة، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15433/توجيه-حول-الحجاب-وصلة-الرحم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76007.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","اللباس والزينة"]},{"id":16700,"question":"تسأل عن مختصر تفسير ابن كثير لـ الصابوني؟","title":"توجيه حول مختصر تفسير ابن كثير للصابوني","answer":"الجواب: أنصح بتركه؛ لأن فيه بعض .. عليه بعض الملاحظات، فأنصح بتركه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15456/توجيه-حول-مختصر-تفسير-ابن-كثير-للصابوني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_820/nour_82008.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":16817,"question":"سماحة الشيخ! يقول هذا السائل: شخص خطب فتاة، وأهل هذه الفتاة منعوه من الجلوس معها، والتحدث إليها، أو حتى النظر إليها، إذا خطب الرجل امرأة هل له أن ينظر إليها في حضور أقاربها؟","title":"حكم نظر الرجل إلى مخطوبته","answer":"الجواب: السنة النظر، الرسول ﷺ أمر من خطب أن ينظر، قال: إن استطاع أن ينظر إلى ما يدعوه إلى نكاحها؛ فليفعل. المقصود: أنه أمر من خطب أن ينظر، وقال له رجل: «يا رسول الله! إني خطبت فلانة، قال: هل نظرت إليها؟ قال: لا، قال: اذهب فانظر إليها وقال: إذا خطب أحدكم المرأة، فإن استطاع أن ينظر منها إلى ما يدعوه إلى نكاحها؛ فليفعل. فالسنة أن ينظر إلى المخطوبة حسب التيسير، لكن لا يخلو بها، إنما يستحب له أن ينظر إليها بحضرة أخيها، أو أمها، أو غيرهم، أو من بعيد؛ لعله يرى منها ما يدعوه إلى نكاحها، فإن تزوجها، ولم ينظر إليها؛ فلا حرج، وإن تيسر أن يرسل إليها من ينظر إليها، ويعرف حالها، ثم يخبره بصفاتها؛ فهذا يكفي عن النظر. المقصود: أن السنة أن يتثبت في الأمر، هذا السنة، الخاطب يتثبت بالنظر، أو بإرسال من يطمئن إليها حتى ينظر إليها من أمه، أو أخته، أو بنته، أو نحو ذلك؛ حتى تفيده عن صفاتها، وأخلاقها، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15557/حكم-نظر-الرجل-الى-مخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_585/58514.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16835,"question":"رسالة من الرياض، وباعثتها إحدى الأخوات المستمعات تقول: السائلة (و. م. خ) لها جمع من الأسئلة في أحدها تقول: لي أخ يريد الزواج من امرأة معينة، وهو شاب يخشى عليه، لكنه طلب منا نحن إخواته تمكينه من رؤيتها، دون علمها؛ شرط ألا يخل هذا بحكم الله  وذلك حتى لا يقع الحرج له، أو لها إذا كان رأيه ألا يتزوج بها، فما الحكم هنا؟ وما السبيل إلى ذلك؟ مع العلم بأننا -والحمد لله- محافظون على تطبيق ما يرضى عنه الله .","title":"جواز النظر للمخطوبة دون علمها","answer":"الجواب: لا حرج في ذلك: أن تسعين في تمكينه من رؤيتها من دون خلوة، كأن تعزمها إحداكن، ثم ينظر إليها من باب، أو هوة، أو غير ذلك، وهي معكن، لا حرج في ذلك، النبي ﷺ رخص للصحابة أن ينظروا في المخطوبة، كان جابر لما أراد أن يتزوج امرأة جعل يتخبأ لها؛ حتى ينظر إليها. فالمقصود: إذا كان النظر من دون خلوة؛ فلا حرج في ذلك، إذا كان يريد خطبتها، نعم. المقدم: جزاكم الله خيرًا، إنما بشرط أن يكون مريدًا للخطبة؟ الجواب: نعم، لا بد أن يكون مريدًا، وإلا فلا يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15623/جواز-النظر-للمخطوبة-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82417.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16850,"question":"رسالة من الرياض، وباعثتها إحدى الأخوات المستمعات تقول: السائلة (و. م. خ) لها جمع من الأسئلة في أحدها تقول: لي أخ يريد الزواج من امرأة معينة، وهو شاب يخشى عليه، لكنه طلب منا نحن إخواته تمكينه من رؤيتها، دون علمها؛ شرط ألا يخل هذا بحكم الله  وذلك حتى لا يقع الحرج له، أو لها إذا كان رأيه ألا يتزوج بها، فما الحكم هنا؟ وما السبيل إلى ذلك؟ مع العلم بأننا -والحمد لله- محافظون على تطبيق ما يرضى عنه الله .","title":"جواز النظر للمخطوبة دون علمها","answer":"الجواب: لا حرج في ذلك: أن تسعين في تمكينه من رؤيتها من دون خلوة، كأن تعزمها إحداكن، ثم ينظر إليها من باب، أو هوة، أو غير ذلك، وهي معكن، لا حرج في ذلك، النبي ﷺ رخص للصحابة أن ينظروا في المخطوبة، كان جابر لما أراد أن يتزوج امرأة جعل يتخبأ لها؛ حتى ينظر إليها. فالمقصود: إذا كان النظر من دون خلوة؛ فلا حرج في ذلك، إذا كان يريد خطبتها، نعم. المقدم: جزاكم الله خيرًا، إنما بشرط أن يكون مريدًا للخطبة؟ الجواب: نعم، لا بد أن يكون مريدًا، وإلا فلا يجوز. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15623/جواز-النظر-للمخطوبة-دون-علمها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_824/nour_82417.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":16901,"question":"بعد هذا رسالة وصلت إلى البرنامج من جمهورية مصر العربية باعثها المستمع أحمد منصور، الأخ أحمد بدأ رسالته كالتالي: بسم الله الرحمن الرحيم، سماحة الشيخ عبدالعزيز بن عبدالله بن باز -حفظه الله ورعاه- أولًا يا سماحة الشيخ أعرفك أنني أحبك في الله تعالى، وأرجو الله، ثم منك أن تدعو الله لي بظهر الغيب أن يرزقني الإخلاص في كل أعمالي الدينية والدنيوية، حيث إنني دائمًا أشعر أن عملي يخالطه شيئًا من الرياء، وإذا ما قرأت القرآن، وسمعت الناس ينصتون إلي ينتابني حالة من العجب، وجهوني سماحة الشيخ؛ حتى أكون مخلصًا لله تعالى، وهل يؤثر ذلكم الإحساس على عملي؟ جزاكم الله خيرًا.","title":"نصيحة لمن ينتابه الرياء والعجب إذا عمل صالحًا","answer":"الجواب: نقول: أحبك الله الذي أحببتنا له، ونسأل الله أن يمنحك الإخلاص، والتوفيق، والهداية، نسأل الله لنا ولك التوفيق، والهداية، وأن تكون مخلصًا في أعمالك كلها. ونوصيك بالحذر من العجب والرياء، وأن تجاهد نفسك، فإذا جاهدت نفسك فأبشر بالخير -إن شاء الله- إذا قرأت القرآن، أو صليت، أو فعلت شيئًا من الخير؛ فاحرص أن يكون ذلك لله وحده، ليس فيه رياء، ولا سمعة، وإذا خطر لك شيء؛ فاطرده بالاستعاذة بالله من الشيطان، وبالحذر، والمجاهد يعان، ربنا يقول سبحانه: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ [العنكبوت:69].  فكلما عرض لك شيء من الرياء؛ فعليك بالمجاهدة، والطرد له بالتعوذ بالله من الشيطان، والحرص على الإخلاص لله سبحانه في قراءتك، وفي صلاتك، وفي جميع عباداتك. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15659/نصيحة-لمن-ينتابه-الرياء-والعجب-اذا-عمل-صالحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71908.mp3","categories":["نصائح وتوجيهات","الرياء والسمعة"," الوسواس بأنواعه"]},{"id":16934,"question":"يقول في سؤال آخر: يقيس الذين يرون التبرك بالصالحين، يقيسون عملهم بما كان يفعله الصحابة  من التبرك بآثار النبي ﷺ وشعره، وملابسه، وفضلات جسمه، فبينوا لنا المعتقد الصحيح في هذا، جزاكم الله خيرًا.","title":"ما حكم التبرك بالصالحين؟","answer":"الجواب: هذا القياس باطل، النبي ﷺ شرع الله لنا أن نقتدي به، ونتأسى به ﷺ وشرع الله -جل وعلا- التبرك بما مس جسده من شعر، وعرق، ونحو ذلك؛ لأنه ﷺ لما حلق رأسه في حجة الوداع وزعه على الصحابة، هذا يدل على أن هذا جائز بالنسبة إليه -عليه الصلاة والسلام- وهكذا ملابسه التي تلي جسده فيها بركة؛ لأن الله جعله مباركًا، وجعل ما أصاب بدنه فيه بركة. أما غيره فلا يقاس عليه، ولا يدعى من دون الله، ولكن مس العرق، أو مس الشعر لا بأس أن يجعل في طيب الإنسان، أو يلبسه على جسده، يرجو أن الله يجعل فيه بركة له، كما جعل ماء زمزم مباركًا  فهذا فضل منه -جل وعلا- وكما جعل في الأطعمة واللحوم ..... بركةً للمسلمين، فليس هذا بمستنكر. أما أن يتبرك بفلان، بثياب فلان، أو شعر فلان، أو عرق فلان، لا؛ لأنه لا يقاس على النبي غيره -عليه الصلاة والسلام-القياس لابد أن يكون الفرع مساويًا للأصل، وليس أحد يساوي النبي ﷺ فهو أفضل الخلق، وسيد الخلق، وله خصائص، ولهذا لم يفعل الصحابة -رضي الله عنهم وأرضاهم- هذا التبرك مع الصديق، ولا مع عمر، ولا مع عثمان، ولا مع علي، ولا مع غيرهم من سادات الصحابة، وكبارهم؛ لعلمهم بأن هذا خاص بالنبي ﷺ لا بغيره، اللهم صل عليه، وهم القدوة والأسوة، وهم أعلم الناس بعد الأنبياء -عليهم الصلاة والسلام- ورضي الله عنهم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15719/ما-حكم-التبرك-بالصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82703.mp3","categories":["نصائح وتوجيهات","التبرك وأنواعه"]},{"id":16959,"question":"ما هي وصيتكم للحاج العائد إلى دياره؟","title":"وصية للحاج العائد إلى دياره","answer":"الجواب: وصيتي له أن يتقي الله، وأن يلتزم الحق، وأن يتبع حجه بالأعمال الصالحة، وأن يحذر الرجوع إلى أعماله السيئة التي كانت قبل الحج، وأن يستقيم حتى يلقى ربه، في طلب العلم، والتفقه في الدين، وفي طاعة الله، وترك معصيته، في جميع الأحوال، هذا وصيتي لكل حاج أن يلزم الحق، وأن يستقيم عليه بعد رجوعه، وأن يستمر إلى الموت، وأن يتواصى مع أهل بيته، وإخوانه بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15759/وصية-للحاج-العاىد-الى-دياره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82817.mp3","categories":["نصائح وتوجيهات"]},{"id":16968,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من الجماهيرية الليبية محمد علي البشير، يقول: هل يجوز للإنسان أن يجلس مع أهل المعاصي ولاسيما أولئك الذين يشربون الخمر، وربما يلعبون الميسر؟ جزاكم الله خيرًا.","title":"حكم مجالسة أصحاب الكبائر","answer":"الجواب: ليس للمسلم أن يجلس مع من يتظاهرون بالمعاصي، بل يجب الحذر منهم، والبعد عنهم؛ لئلا يصيبه ما أصابهم، ولئلا يفعل فعلهم، إلا إذا حضر للإنكار والدعوة، بأن وقف عليهم، ودعاهم، ونصحهم بالأسلوب الحسن فإن استجابوا وإلا انصرف فلا بأس، أما الجلوس معهم لا، والله -جل وعلا- يقول: وَإِذَا رَأَيْتَ الَّذِينَ يَخُوضُونَ فِي آيَاتِنَا فَأَعْرِضْ عَنْهُمْ حَتَّى يَخُوضُوا فِي حَدِيثٍ غَيْرِهِ وَإِمَّا يُنسِيَنَّكَ الشَّيْطَانُ فَلا تَقْعُدْ بَعْدَ الذِّكْرَى مَعَ الْقَوْمِ الظَّالِمِينَ [الأنعام:68].  فالله نهى عن القعود بعد الذكرى مع القوم الظالمين فَلا تَقْعُدْ بَعْدَ الذِّكْرَى مَعَ الْقَوْمِ الظَّالِمِينَ [الأنعام:68]؛ لأنه قد يميل إليهم، قد يفعل مثل فعلهم، فالواجب الحذر، لكن إذا وقف عليهم للدعوة إلى الله، التوجيه إلى الخير، وإنكار المنكر بالأسلوب الحسن، والنصيحة، لعل الله يهديهم بأسبابه، لعلهم يستجيبون فهذا أمر مطلوب، وإن استطاع ذلك، وظن أنه ينفع وجب عليه؛ لقوله : فَذَكِّرْ إِنْ نَفَعَتِ الذِّكْرَى [الأعلى:9] فَذَكِّرْ إِنَّمَا أَنْتَ مُذَكِّرٌ [الغاشية:21]. فالمقصود: أن الله -جل وعلا- شرع لنا التذكير، والدعوة، فإذا أمكنك أن تدعوهم إلى الله، وأن ترشدهم إلى الخير، وأن تحذرهم من الباطل فأنت على خير عظيم، أما الجلوس معهم فلا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15737/حكم-مجالسة-اصحاب-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72002.mp3","categories":["نصائح وتوجيهات"]},{"id":16990,"question":"ما هي النصيحة التي تتفضلون بها، وتنصحونني عندما أقرأ القرآن الكريم، ولاسيما وأن حفظي بسيط؟","title":"نصيحة لمن أراد قراءة القرآن الكريم","answer":"الجواب: أنصحك بالعناية بالدراسة، وتحري الأوقات المناسبة التي يكون قلبك فيها حاضرًا، والمشاغل فيها قليلة؛ حتى تنتفع بالقراءة أكثر، أوصيك أيضًا بأن تسأل ربك الإعانة والتوفيق، وأن يمنحك حفظ كتابه، وفهمه، والعمل به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15772/نصيحة-لمن-اراد-قراءة-القران-الكريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82903.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":17016,"question":"الزائر للحرمين الشريفين خاصة -سماحة الشيخ- يتأذى كثيرًا من أولئك السافرات عن وجوههن، حتى لو فقد محرمًا له كأمه، أو زوجته، أو أخته، وبدأ يبحث عنها لا يستطيع البحث؛ لأن بصره يقع على ما لا يريد، ما هو توجيه سماحتكم لأخواتنا المسلمات إذا ما كن في الحرمين خاصة، وفي جميع المناطق عامة؟ جزاكم الله خيرًا.","title":"نصيحة حول ظاهرة السفور والتبرج في الحرمين","answer":"الجواب: وصيتي لجميع أخواتي في الله في الحرم الشريف، وفي المطار، وفي السعي، وفي المسجد النبوي، في أي مكان، الوصية للجميع تقوى الله، والاستقامة على أمره، والمحافظة على حدوده التي حدها سبحانه، والحرص على الستر، والحجاب، ولا ينبغي أن تغتر بقول بعض الناس: أنه لا حرج عليها في كشف وجهها، ويديها، هذا قول مرجوح يخالف الأدلة الشرعية، إلا إذا كانت محرمة بحج، أو عمرة؛ فإنها لا تلبس النقاب المصنوع للوجه، لكن تحتجب بالخمار، ونحوه مما يوضع على الوجه. وأما النقاب الذي هو مصنوع على قدر الوجه، ونقب العينين هذا تتركه في حال الإحرام، وفي العمرة والحج، لكن تستر وجهها بالخمار بجلباب فوق رأسها كما قالت عائشة -رضي الله عنها-: \"كنا مع النبي ﷺ في حجة الوداع، فإذا دنا منا الرجال سدلت إحدانا جلبابها على وجهها، أو قالت: خمارها على وجهها، فإذا بعدوا كشفنا\" وهن محرمات. فالوصية للجميع تقوى الله، والحرص على التستر، والحجاب لجميع البدن، في الطواف، وفي السعي، وفي كل مكان عن الأجانب، وأن تحذر أسباب الفتنة من التبرج بالملابس الجميلة، أو إظهار بعض المحاسن التي تفتن الناس، والله يقول -جل وعلا-: وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى [الأحزاب:33] ويقول: فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ [الأحزاب:32] يكون القول قولًا عاديًا، كلامًا، العادي ما فيه خضوع، ولا تغنج مع التستر والحجاب، كل هذا لإبعادها عن الفتنة، وأن يفتن بها غيرها أيضًا. نعم. المقدم: جزاكم الله خيرًا، إذًا لا يجوز للمرأة المسلمة أن تكشف وجهها، سواءً كانت في المشاعر المقدسة، أو في غيرها. الشيخ: عند الأجنبي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15814/نصيحة-حول-ظاهرة-السفور-والتبرج-في-الحرمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_767/nour_76709.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","اللباس والزينة"]},{"id":17049,"question":"تقول السائلة يا سماحة الشيخ: تزوجت وأنا صغيرة، ولم أكن أعرف حقوق الزوج، وغرر بي أحدهم حيث تطلقت من زوجي، وظلمت زوجي، وأنا الآن نادمة، فماذا يلزمني حفظكم الله؟ وأرجو يا سماحة الشيخ أن تدعو له بالخير، وبتيسير الرزق، وأنا أتمنى العودة له، فما توجيهكم حفظكم الله؟","title":"الحث على إحسان معاملة المرأة لزوجها","answer":"الجواب: التوجيه أن عليك التوبة إلى الله مما فعلت من التقصير، الندم والتوبة إلى الله، وسؤاله المغفرة  وعدم العودة إلى مثل ذلك مع الزوج الجديد، وإذا عدت إليه إن كان الطلاق طلقة واحدة، أو طلقتين له العود إليك، وعليك الجد في إحسان المعاشرة إذا عدت إليه بالكلام الطيب والأسلوب الحسن، والسمع، والطاعة في المعروف، وعدم المعاكسة، هكذا ينبغي للزوجة، الله يقول سبحانه: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19] ويقول ﷺ: استوصوا بالنساء خيرًا.  ويقول في حق النساء: على المرأة ألا تأذن في بيت زوجها إلا بإذنه، ولا يطأ فراشها أحد إلا بإذنه وعليها السمع والطاعة لزوجها في المعروف، فعلى المرأة السمع والطاعة لزوجها في المعروف، والعناية بإكرامه، والإحسان إليه؛ لأن حقه عليها أكبر وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228]. وهو عليه أن يستوصي بها خيرًا، وألا يظلمها، وأن يحسن عشرتها، لكن حقه عليها أكبر، فعليها أن تسمع وتطيع في المعروف، وأن تعينه في أمور بيته، وأن تكرمه حتى تستقيم الحال بينها وبينه، لكن لا تطيعه في المعاصي، إنما تكرمه في لباسه، وفي فراشه، وفي تمكينه من نفسها إذا أرادها، وفي غير هذا من شؤون البيت، ومع أولاده وأهل بيته، ووالديه، ونحو ذلك، يكون لها سيرة حسنة معه، ومع والديه، ومع أقاربه حتى تشكر، ويدعى لها، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15838/الحث-على-احسان-معاملة-المراة-لزوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58724.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17056,"question":"سماحة الشيخ! حفظكم الله، كثرت في زماننا هذا الذين يعانون من الوساوس، سواءً كان ذلك في الطهارة، أو في الصلاة، ما العلاج الناجع في ذلك، مأجورين؟","title":"ما العلاج الناجع للوساوس في الطهارة والصلاة؟","answer":"الجواب: العلاج الاستعاذة بالله من الشيطان، الاستعاذة بالله من الشيطان، والعمل بالأصل، وهو السلامة واليقين، هذا هو الأصل، فإن وسوس هو طلق، أو ما طلق ما عليه شيء، وسوس هو أحدث، أو ما أحدث ما عليه شيء، وسوس، هل حرم زوجته، لا ما عليه شيء، هذه كلها من الشيطان يلعب ببني آدم، يقول ﷺ: إن الله تجاوز عن أمتي ما حدثت به أنفسها ما لم تعمل أو تكلم. فحديث النفس مطَّرح، هكذا أمر النبي ﷺ حتى يعلم الإنسان يقينًا أنه تكلم عامدًا لهذا الشيء، أو عمل ما يوجب عليه إثمًا، أو فديةً، أو غير ذلك، مادام وساوسًا، فليس عليها عمل إن الله تجاوز عن أمتي ما حدثت به أنفسها، ما لم تعمل، أو تكلم. فإذا وقع له في الصلاة، أو في خارج الصلاة وسوسة أنه أحدث، أو أنه طلق، أو أنه حرم زوجته، أو ما أشبه ذلك فليطرحها، وليتعوذ بالله من الشيطان، ينفث عن يساره ثلاث مرات، يقول: أعوذ بالله من الشيطان الرجيم، أعوذ بالله من الشيطان الرجيم، ولو في الصلاة، حتى في الصلاة، يستعيذ بالله من الشيطان، \"قال رجل: يا رسول الله! إن الشيطان قد لبس علي صلاتي؟\" فقال له النبي ﷺ: انفث عن يسارك ثلاث مرات، وتعوذ بالله من الشيطان ثلاث مرات قال عثمان بن أبي العاص -السائل هو عثمان بن أبي العاص الثقفي ... - قال: \"ففعلت ذلك؛ فأذهب الله عني ما وجدت\". المقصود: الصدق في الاستعاذة بالله من الشيطان، فإذا صدق وتعوذ بالله من الشيطان، وأعرض عن الوساوس؛ كفاه الله شرها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15847/ما-العلاج-الناجع-للوساوس-في-الطهارة-والصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58802.mp3","categories":["نصائح وتوجيهات"," الوسواس بأنواعه"]},{"id":17071,"question":"تقول السائلة: بأن زوجها شحيح لا يعطيها ما يكفيها وأولادها من مصاريف البيت، وأدوات المدرسة.. وغير ذلك، هل يحل لها أن تأخذ من ماله بدون علمه؟","title":"حكم أخذ المرأة من مال زوجها البخيل","answer":"الجواب: نعم، إذا كان يقصر في نفقة البيت لها أن تأخذ من ماله بغير علمه، إذا قصر في نفقتها ونفقة أولاده منها لها أن تأخذ بالمعروف من غير إسراف، ولا تبذير، لكن بالمعروف؛ لأن هند بنت عتبة امرأة أبي سفيان -رضي الله عنهما- قالت: «يا رسول الله، إن أبا سفيان رجلٌ شحيح، لا يعطيني من النفقة ما يكفيني، ويكفي بني، فهل آخذ من ماله ما يكفيني؟ قال: نعم. خذي من ماله بالمعروف ما يكفيك، ويكفي بنيك خذي من ماله بالمعروف يعني: من غير إسراف، ولا تبذير. نعم. المقدم: إذًا يا سماحة الشيخ بعض الأخوات يقلن: هل النفقة محددة مثلًا أو معينة؟ الجواب: غير محددة حسب الحاجة، تختلف بحسب الغلاء والرخص، حسب حاجة الأولاد، وكثرتهم، وقلتهم، حسب الحاجة ... الوسط، مثلما قال الله -جل وعلا- في عباده الصالحين: وَالَّذِينَ إِذَا أَنفَقُوا لَمْ يُسْرِفُوا وَلَمْ يَقْتُرُوا وَكَانَ بَيْنَ ذَلِكَ قَوَامًا [الفرقان:67] وقال -جل وعلا-: وَلا تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلا تَبْسُطْهَا كُلَّ الْبَسْطِ فَتَقْعُدَ مَلُومًا مَحْسُورًا [الإسراء:29] المغلولة: البخيل، والبسط كل البسط: هذا المسرف، المبذر. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15876/حكم-اخذ-المراة-من-مال-زوجها-البخيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58811.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17073,"question":"تقول أخيرًا هذه السائلة: بأن عندها ولد يريد أن يحفظ القرآن كاملًا عن ظهر قلب، ترجو من سماحة الشيخ عبدالعزيز توجيه طريقة معينة تعينه على حفظ كتاب الله -جل وعلا- وأن تدعو له في ظهر الغيب، أن يكون من حفاظ كتاب الله، وجزاكم الله خيرًا، وبارك في عمركم على طاعة الله.","title":"وسائل حفظ القرآن","answer":"الجواب: نسأل الله له العون، نسأل الله له العون والتوفيق، نسأل الله أن يعينه ويوفقه، ونوصيه بالعناية بحفظ القرآن في الأوقات المناسبة التي قلبه فيها يكون مستعدًا للقراءة، مثل: بعد صلاة الفجر، مثل: في أثناء الليل، في الأوقات التي يراها مناسبة يجتمع فيها قلبه ولسانه، حتى يدرس وحتى يتحفظ. نعم.","link":"https://binbaz.org.sa/fatwas/15878/وساىل-حفظ-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58813.mp3","categories":["العالم والمتعلم","القرآن وعلومه","نصائح وتوجيهات"]},{"id":17129,"question":"يقول عن نفسه سماحة الشيخ يقول: أنا مؤمن، والحمد لله، وقد أديت مناسك الحج والعمرة، ومع ذلك لا أشعر بحلاوة الإيمان، فبماذا تنصحونني؟","title":"نصيحة لمن لا يشعر بحلاوة الإيمان","answer":"الجواب: ننصحك باستعمال ما شرع الله -جل وعلا- من الحرص على الطاعات، وقراءة القرآن الكريم، والإكثار من ذكر الله  فإن هذا من أسباب.. لذوق المحبة، ذوق حلاوة الإيمان، يقول النبي ﷺ: ثلاث من كن فيه وجد بهن حلاوة الإيمان: أن يكون الله ورسوله أحب إليه مما سواهما، وأن يحب المرء لا يحبه إلا لله، وأن يكره أن يعود في الكفر بعد إذ أنقذه الله منه كما يكره أن يقذف في النار. فالصدق في محبة الله ورسوله، والإيمان بالله ورسوله، ومحبة إخوانه في الله، وكراهة الكفر بالله، من أسباب ذوق طعم الإيمان، ويقول ﷺ: ذاق طعم الإيمان من رضي بالله ربًا، وبالإسلام دينًا، وبمحمد رسولًا ويقول في حديث ابن عباس : من أحب في الله، وأبغض في الله، وأعطى لله، ومنع لله؛ وجد حلاوة الإيمان أو قال: ذاق طعم الإيمان. فالمقصود: أن الإكثار من ذكر الله، ومن قراءة القرآن، والاستقامة على طاعة الله ورسوله، ومحبة الله ورسوله، وأن تحب إخوانك في الله، وأن تكره الكفر، وسائر المعاصي، كل هذا من أسباب ذوق طعم الإيمان، ووجود حلاوة الإيمان في قلبك، وأنسك بطاعة الله، ورسوله، وتلذذك بذلك بسبب، صدقك في طاعة الله، ومحبة الله . نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15949/نصيحة-لمن-لا-يشعر-بحلاوة-الايمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72208.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":17162,"question":"أيضًا لها قضية طولت في السؤال عنها ملخص ما تسأل عنه سماحة الشيخ: أنها تريد التوجيه كيما تحب القرآن الكريم، وتشغل وقتها بحفظه، فكيف يكون ذلك؟ جزاكم الله خيرًا.","title":"كيفية غرس حب القرآن وحلاوته في القلب","answer":"الجواب: ننصحها بأن تقرأ القرآن وقت خلو ذهنها -وقت فراغها- حتى تأنس به، وتستريح به، وتطمئن إليه، تنظر الأوقات المناسبة من الليل والنهار التي ليس فيها شواغل، ثم تقرأ، وترتل القراءة من أوله إلى آخره، على حسب طاقتها، كل يوم نصف جزء.. جزء.. جزءين على حسب التيسير، وسوف يشرح الله صدرها، وتجد حلاوة الإيمان، وحلاوة القرآن، وتعلم أنه كلام الله، وأن الله يعطيها بكل حرف حسنة، والحسنة بعشر أمثالها، وأنه مشروع لها التدبر والقراءة، يقول النبي ﷺ: اقرؤوا القرآن فإنه يأتي شفيعًا لأصحابه يوم القيامة والله يقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29].  فعليها أن تطمئن بهذا الكتاب العظيم، وتعلم أنه كلام الله، وأنها مأجورة في قراءته، وأن الله يعطيها بكل حرف حسنة، والحسنة بعشر أمثالها هذا خير عظيم، والمؤمن يتحرى، الرجل والمرأة يتحريا الأوقات المناسبة التي فيها فراغ قلبه.. فراغ ذهنه من ليل أو نهار حتى يقرأ بنفس مطمئنة، راغبة، تتفكر، وتتدبر، وتتعقل حتى تستفيد، وحتى تخشع لكلام الله، وحتى تجد الحلاوة في القلب. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15980/كيفية-غرس-حب-القران-وحلاوته-في-القلب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_722/nour_72214.mp3","categories":["نصائح وتوجيهات"]},{"id":17176,"question":"هذا السائل مهدي محمد يقول: بأنه شاب، ويحب أن يتزوج ببنت، ولكن والد هذه البنت طلب منه مبالغ كبيرة، ودفعة واحدة، يقول: وأنا أحب هذه البنت، فكيف يكون الحل؟ وأطلب منكم الدعاء بأن يهدي الله  قلبي، ولكم جزيل الشكر.","title":"الحث على التسهيل في الزواج وترك التكلف","answer":"الجواب: يسر الله أمرك، وأمر كل مسلم، وهدى أباها حتى يسامحك بعض الشيء، والتسهيل في الزواج مهم، وعدم التكلف، إذا حصل الكفء؛ فالأفضل للولي، والمرأة عدم التكلف، وأن يرضوا بالشيء الميسور، وألا يتكلفوا في المهور، ولا في الولائم حتى يتيسر الزواج للرجال، والنساء جميعًا، هذا هو الأفضل. وإذا لم تستطع؛ فاصبر حتى يسهل الله الأمر، لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم، فإنه له وجاء والله يقول -جل وعلا-: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32] ثم يقول بعده: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ [النور:33] يعني: الذي لا يجد عليه أن يستعف، يتصبر، ويتحمل حتى يغنيه الله. فالمقصود: أن المؤمن يسعى في النكاح، وأسبابه حسب طاقته، فإذا لم يتيسر ذلك صبر حتى يفرج الله الأمور. نعم.","link":"https://binbaz.org.sa/fatwas/15994/الحث-على-التسهيل-في-الزواج-وترك-التكلف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59005.mp3","categories":["الصداق","نصائح وتوجيهات"]},{"id":17187,"question":"هذا شاب أرسل بهذا السؤال يقول سماحة الشيخ: بأنه شاب يبلغ من العمر الثامنة والعشرين من العمر، يعاني من مرض نفسي، وهو التفكير الدائم؛ القلق.. التوتر.. والخوف من المستقبل، والأرق، وعدم النوم، فبماذا تنصحونه من الكتاب والسنة للشفاء من هذا المرض؟ مأجورين، وهل يوجد كتب تنصحونه بقراءتها؟","title":"نصيحة لمصاب بمرض النفسي","answer":"الجواب: أنصحه بالتعوذ بكلمات الله التامات من شر ما خلق، يكررها، والتعوذ بالله من الشيطان الرجيم، ويكرر ذلك، ويطرح الشكوك، ويسأل ربه العافية من ذلك، ويبشر بالخير، يكثر من التعوذ بكلمات الله التامات من شر ما خلق، والتعوذ بالله من الشيطان الرجيم؛ لأن هذا من الشيطان، ويكتفي بهذا والحمد لله، ويحارب الشكوك والأوهام التي تقعده من عدو الله الشيطان، فإذا اجتهد في ذلك، وأكثر من التعوذ بالله من الشيطان الرجيم، والتعوذ بكلمات الله التامات من شر ما خلق فإنه يسلم بتوفيق الله. النبي ﷺ لما قال له بعض الصحابة «يا رسول الله! إن أحدنا يجد في صلاته ما لا أن يخر من السماء أهون من أن ينطق به؟ قال: تلك الوسوسة ثم قال: إذا وجد أحدكم ذلك؛ فليقل: آمنت بالله ورسله إذا كان ... يتعلق بالله فليقل: آمنت بالله ورسله، ثم ليستعذ بالله ولينته وإذا كان يتعلق بأشياء أخرى يتعوذ بالله من الشيطان الرجيم، وينتهي، والحمد لله، ويسلم، يكثر من التعوذ بالله من الشيطان. نعم. المقدم: أحسن الله إليكم سماحة الشيخ! في زماننا هذا الحقيقة كثر الذين يعانون من هذه الأمراض المتعددة، في نظركم ما هي الأسباب في ذلك؟ الجواب: الأقرب -والله أعلم- كثرة المشاغل التي تشغل القلوب، تحدث وسوسة، وبعض الناس لرغبته في الدين، وحرصه على الدين، وعدم علمه يأتيه الشيطان من جهة الدين، ويكثر عليه الوساوس من جهة الدين، وبعضهم من جهة المشاكل الكثيرة في بيته، أو مع الناس تأتيه الوساوس، والعلاج في هذا، أن يتعوذ بالله من الشيطان كثيرًا، يسأل ربه العافية من ذلك، ويتعوذ بكلمات الله التامات من شر ما خلق، وبإذن الله يسلم من هذه الأمور. نعم. المقدم: البعد عن الذكر، وقراءة القرآن سماحة الشيخ، أليس له سبب؟ الشيخ: كذلك الغفلة من أسباب ذلك، والإكثار من قراءة القرآن، ومن ذكر الله من أسباب التوفيق، ومن أسباب السلامة، إذا أكثر من ذكر الله، ومن قراءة القرآن هذا من أسباب السلامة، والعافية من الشيطان، ووساوسه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16006/نصيحة-لمصاب-بمرض-النفسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59015.mp3","categories":["نصائح وتوجيهات"," الوسواس بأنواعه"]},{"id":17207,"question":"من الدوحة قطر الأخت المستمعة (أ. غ. ع) رسالتها ضمنتها أربعة أسئلة، في أحد أسئلتها تقول: ما حكم ذهاب النساء إلى محل تصفيف الشعر، أو الكوافيرة -كما يسمونه- علمًا بأن هذه المحلات لا يدخلها غير النساء؟ جزاكم الله خيرًا.","title":"نصيحة لمن يردن الذهاب إلى محلات الكوافير","answer":"الجواب: نصيحتي أن لا يذهبن إلى ذلك، وأن تعطل هذه المحلات؛ لأنه يخشى فيها الشر والفتنة، ودعوى ....... عمل أشياء لا حاجة إليها، فالمرأة -والحمد لله- تستطيع تعلم نفسها في بيتها مع أمها، أو أخواتها، أو صديقاتها كل ما يحتاج إليه، ولا ينبغي التكلف .... الشعر معروف، وكذلك فتل العمائم معروف، ولا حاجة إلى هذه المحلات التي أحدثها الناس، فربما يكون فيها فتنة، أو شر، نعم، فينبغي تركها. المقدم: وهذا مؤكد سماحة الشيخ، جزاكم الله خيرًا.  الشيخ: هذا الذي بلغنا، بلغنا أنها لا خير فيها، وينبغي تركها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16033/نصيحة-لمن-يردن-الذهاب-الى-محلات-الكوافير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_723/nour_72303.mp3","categories":["اللباس والزينة","المساجد ومواضع السجود","قضايا المرأة","نصائح وتوجيهات"]},{"id":17251,"question":"من أسئلتها تقول يا سماحة الشيخ: هل يجوز أن نقرأ دعاء صلاة الاستخارة في التشهد الأخير، وقبل السلام في سنن الرواتب؟","title":"وقت دعاء الاستخارة ومحله","answer":"الجواب: دعاء الاستخارة بعد الصلاة، النبي ﷺ أمر من أراد أن يستخير يصلي ركعتين، ثم يستخير، ولو قرأ عند الاستخارة في الدعاء قبل أن يسلم، أو قرأه من دون صلاة، لا حرج، لكن كونه يصلي ركعتين، ثم يأتي به أفضل، كما أمر النبي ﷺ. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16083/وقت-دعاء-الاستخارة-ومحله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59205.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":17265,"question":"سماحة الشيخ، لعل لسماحتكم كلمة في هذا المقام حول من يقوم بتمريض هذا النوع من المرضى، يحتاجون -ولا شك- إلى عناية خاصة، وإلى عدم معاملتهم معاملة أولئك الأسوياء، أرجو من سماحتكم أن تتفضلوا بكلمة إلى كل من يعول، أو يسأل عن مثل هذا النوع من المرضى؟ جزاكم الله خيرًا.","title":"وصية للقائمين على تمريض المجانين والمعتوهين","answer":"الجواب: لاشك أن هؤلاء جديرون بالرحمة، والعطف ممن يتولاهم، فعلى أوليائهم الرفق بهم، والرحمة لهم والإحسان إليهم، والتلطف بتوجيههم، قد يستفيدون من بعض التوجيهات؛ لأن عندهم بعض الشيء الذي يستفيد به، فالمجنون قد يستفيد من التأديب، كما أن الصبي وهو غير المكلف يستفيد من التأديب والتوجيه، وهكذا الأطباء نوصيهم بتقوى الله، والرفق بهؤلاء، والرحمة لهم، والإحسان إليهم، والحرص على أسباب الشفاء. نعم. المقدم: جزاكم الله خيرًا، هل من كلمة للممرضين، أو من يخدم هذا النوع. الشيخ: وهكذا الممرضون والممرضات كلهم نوصيهم بتقوى الله في ذلك، والرحمة، والعطف، والإحسان والرفق. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16104/وصية-للقاىمين-على-تمريض-المجانين-والمعتوهين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76802.mp3","categories":["نصائح وتوجيهات"]},{"id":17282,"question":"أولئك الذين ينتقدون الشخص عندما يتمسك بشعيرة من شعائر الله، فربما أطلقوا عليه كلمة: معقد كما قيل لأختنا هذه، ماذا يقول سماحة الشيخ لمثل هؤلاء؟","title":"نصيحة لمن يصفون المتديّن بأنه معقد","answer":"الجواب: هذا لا يجوز، الواجب تشجيع الناس على الخير، وحثهم على الخير، والذي يتمسك بالسنة هذا لا يقال له: معقد، يقال له: موفق، الذي مثلًا لا يسبل ثيابه، ولا يحلق لحيته، ولا يجلس مع أهل الشر، بل يبتعد عنهم؛ هذا موفق ما هو بمعقد، المعقد الموسوس الذي لا يعرف يؤدي الحق من وساوسه وشكوكه، هذا يقال له: معقد، أما من عافاه الله من الوساوس والشكوك، واتبع الشرع، واستقام عليه، وابتعد عن محارم الله؛ هذا موفق. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16122/نصيحة-لمن-يصفون-المتدين-بانه-معقد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76813.mp3","categories":["نصائح وتوجيهات"]},{"id":17303,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المدينة المنورة، وباعثها أحد الإخوة المستمعين رمز إلى اسمه بالحرف (خ) يقول: أنا شاب كنت أصلي كل الفرائض في وقتها، ثم ابتعدت عن ذلك فترة، ثم إني تبت إلى الله  ورجعت عما كنت فيه من الشر، ولكني بعد هذه التوبة أشعر بالألم، والأسى لذلكم الماضي الأسود، وجهوني شيخ عبدالعزيز -جزاكم الله خيرًا- هل أقضي ما فاتني، أو بم توجهونني شكر الله لكم؟","title":"توجيه لمن تاب من ترك الصلاة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فعليك أن تحمد ربك، وتشكره كثيرًا على ما من به عليك من التوبة، واعلم يا أخي أن التوبة تجب ما قبلها، وتمحو ما قبلها إذا كانت التوبة تامة، مستوفية لشروطها، يقول الله -جل وعلا- في كتابه الكريم: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فدل ذلك على أن من تاب التوبة الشرعية أفلح، ويقول النبي ﷺ: التائب من الذنب كمن لا ذنب له ويقول ﷺ: التوبة تهدم ما كان قبلها فاحمد الله -جل وعلا- واشكره سبحانه، وأحسن به الظن، فالذنوب الماضية تمحى بالتوبة، وليس عليك قضاء، إنما عليك لزوم التوبة. والتوبة النصوح هي المشتملة على أمور ثلاثة: الندم على الماضي من السيئات، والإقلاع منها، وتركها؛ خوفًا من الله وتعظيمًا له، والعزم الصادق ألا تعود إليها.  فإذا اشتملت التوبة على هذه الأمور الثلاثة: الندم، والإقلاع، والعزم الصادق ألا تعود، محا الله عنك الذنب الماضي، وأفلحت، فاستقم واثبت على الحق. وهناك شرط رابع لصحة التوبة، وسلامتها، إذا كان الحق للمخلوقين، كالدماء، والأموال، والأعراض فلابد من استحلالهم، أو إعطائهم حقوقهم، من تمام التوبة في حق الآدمي أن تعطيه حقه، المال، أو الدم، يعني: القصاص. وهكذا العرض، تقل: أرحني يا أخي، سامحني جرى مني كذا، وجرى مني كذا، سامحني، فإذا سامحك في حقه من مال، أو دم، أو عرض؛ صحت التوبة، وبرئت من هذا الحق، وإن لم يسمح؛ سقط ما كان لله، وبقي حق الآدمي بينك وبينه يوم القيامة، وإذا استقامت توبتك، أرضاه الله عنك يوم القيامة  لكن عليك أن تجتهد في الدنيا في إعطاء حقه، أو تحلله، فإذا عجزت، وصدقت في التوبة؛ أوفى الله عنك يوم القيامة. وهكذا العرض إذا كنت تخشى إذا أخبرته أن يكون الأمر أشد، وأن يترتب عليه ما لا تحمد عقباه فلا تخبره، ولكن استغفر له، واذكره بالخصال الحميدة التي تعرفها عنه، بدلًا من الخصال الذميمة التي اغتبته بها، فهذه بهذه، تذكر ما تعلم من أعماله الطيبة في المجالس التي ذكرته فيها بالسوء، وتدعو له، وتستغفر له، وهذا يقوم مقام استحلالك له إذا خشيت من الاستحلال أمرًا أخطر، وأكبر، والله المستعان. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16146/توجيه-لمن-تاب-من-ترك-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72403.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":17337,"question":"والدنا حفظه الله! آمل أن أجد لديكم الحل لما أنا فيه، فقد أخذ مني الهم مأخذًا بليغًا، فقد فقدت الخشوع في جميع الصلوات، وفقدت قيام الليل، وفقدت كثيرًا مما كنت أحفظه من كتاب الله، وتركت القيام بالدعوة التي كان لي نشاط فيها، وفقدت أشياء كثيرة بسبب كثرة التفكير فيما أصابني، وفي الختام أطلب منكم يا والدنا أن توصيني، وأن تدعو لي وحفظكم الله.الشيخ: أعد، أعد هذا الكلام الأخير .المقدم: آمل أن أجد لديكم الحل لما أنا فيه، فقد أخذ مني الهم مأخذًا بليغًا، فقد فقدت الخشوع في جميع الصلوات، وفقدت كثيرًا مما كنت أحفظه من كتاب الله..","title":"الصبر والاحتساب لمن أصيب بحدث دائم","answer":"الجواب: عليك يا أخي أن تسأل ربك -جل وعلا- وتضرع إليه أن الله يشفيك من هذا البلاء، وأنت على خير ، إذا كان ليس عن اختيارك، ولكن مغلوب على هذا الأمر، فأنت تسأل ربك أن يعينك، تجتهد في الخشوع في الصلاة، والإقبال عليها بقلبك، تستحضر أن الله -جل وعلا- ينظر إليك، وأنه سبحانه يشاهدك، وأنك بين يديه، فاستحي، ودع التفكير هذا الذي أصبت به، أمر الله غالب، فاحمد الله، لا يقضي الله لعبده من قضاء إلا كان خيرًا له، فعليك بالصبر، والاحتساب، وحسن الظن بالله، والإقبال على صلاتك، والخشوع فيها، والدعوة إلى الله حسب طاقتك في أهلك، وفي جيرانك، وغيرهم، والعناية بقيام الليل حسب طاقتك، في أوله، أو في وسطه، أو في آخره: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. وإياك وسوء الظن بالله، عليك بحسن الظن بالله، واجتهد في السؤال، والضراعة إليه أن يعافيك، وأن يشفيك، ويردك إلى الحالة الأولى التي هي أحسن، وأن يرزقك الخشوع في الصلاة، والعناية بصلاة الليل، والعناية بالدعوة إلى الله، أنت بين يدي الله، أنت عبد من عبيده، اضرع إليه، واسأله بصدق أن يعينك، وأن يعافيك، وأن يهبك حالك الأولى من الدعوة إلى الله، والخشوع، والإقبال على صلاة الليل، وأبشر بالخير، فالله يقول سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60]. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، سماحة الشيخ! يبدو أن أخانا مصاب بمرضين: مرض عضوي، ومرض نفسي، هل تنصحونه بمراجعة أحد المستشفيات؛ لعل الله  أن يهيئ له الشفاء؟ الشيخ: لا مانع إذا كان المرض مما يستطيع الأطباء علاجه، فلا بأس، أما الشيء النفسي فعلاجه ذكر الله، وطاعة الله، وسؤال الله، والضراعة إليه، أن يهبه حاله الأولى من الإخلاص لله، والخشوع بين يديه، وقيام الليل، ونحو ذلك، الشيء الذي يتعلق بالعضوي البدني في البدن، شيء من البدن هذا يعالج عند الأطباء المختصين، والحمد لله. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16173/الصبر-والاحتساب-لمن-اصيب-بحدث-داىم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_724/nour_72410.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":17364,"question":"سماحة الشيخ -حفظكم الله- في زماننا هذا كثر التلفظ بالطلاق، والتهاون به من بعض الناس حيث صار ديدنهم، ما هي الأسباب في نظركم؟ وما العلاج؟ وما توجيهكم للإخوة الذين وقعوا في ذلك؟","title":"بعض أسباب الطلاق وعلاج ذلك","answer":"الجواب: هذا نعم هذا واقع كثيرًا، الطلاق واقع من الناس كثيرًا، بأسباب كثيرة، تارةً من الزوج، وتارةً من المرأة، وتارةً منهما جميعًا، فقد تكون المرأة بذيئة اللسان، سليطة اللسان، فتسبه وتتكلم عليه بكلام غير لائق، فلا يتحمل، ويطلق، وقد تطالبه بأشياء لا تجب، وتكثر عليه، وتتعبه فيطلق، وقد يكون هو سريع الغضب، قليل الصبر؛ فلا يتحمل شيئًا، وقد يكون عنده أعمال أخرى قد أشغلته، وكلفته، وأقظت مضجعه، فلا يتحمل، قد يكون يتعاطى المسكرات فلا يتحمل إلى غير هذا من الأسباب. فالواجب على المطلق، والمطلقة تقوى الله، وأن يتعاونا على البر والتقوى، وأن تحذر المرأة إيذاء زوجها، وإيقاعه فيما لا ينبغي بسبب سلاطة لسانها، ومطالباتها الكثيرة بغير حق. والواجب على الزوج أن يتقي الله في المرأة، وأن يعطيها حقوقها، وألا يظلمها؛ حتى لا يلجئها إلى إيذائه، وإلى المطالبة بما يجب لها حتى يقع منه الطلاق.  الواجب على الجميع التعاون على البر والتقوى، والتواصي بالحق، فالزوج ينبغي له أن يحلم، ولا يعجل، والواجب عليه أن يعطيها حقوقها، وألا يلجئها إلى المطالبة، وإغضابه. والواجب عليها هي أيضًا السمع والطاعة لزوجها في المعروف، وحسن المعاشرة، وطيب الكلام، وتحمل بعض ما يقع من الخلل من الزوج؛ لقول الله -جل وعلا-: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]؛ ولقوله سبحانه: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ [البقرة:228] وقوله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]. فينبغي للزوجين التعاون على البر والتقوى، والتواصي بالحق، والتعاون على الخير، هو يجتهد في أداء حقها، والإحسان إليها، وإحسان عشرتها، وهي تجتهد في أداء حقه، وعدم إلجائه إلى الطلاق، وعدم إغضابه بغير حق، فإذا حصل التعاون؛ قل الطلاق، وإذا لم يحصل التعاون؛ كثر الطلاق، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16199/بعض-اسباب-الطلاق-وعلاج-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77002.mp3","categories":["الطلاق","نصائح وتوجيهات"]},{"id":17373,"question":"هذا السائل الذي رمز لاسمه بـ (ع. ل. ب) يقول: أريد أن أفيدكم بأنني مقيم بالمملكة منذ أربع سنوات، ولم أسافر، ولي زوجة، وبنات، وهم في بلدي، والسبب في ذلك بأنني أريد أن أكسب لقمة العيش في هذا البلد المبارك، وأعمل عاملًا بالبقالة بالراتب، وأرسل لهم شهريًا، هل آثم على تركي لهم هذه المدة؟","title":"ما حكم الغياب عن الأهل لمدة طويلة؟","answer":"الجواب: يخشى عليك من الإثم؛ لأن المدة طويلة، فالذي أرى أن الواجب عليك أن تذهب إليهم بين وقت وآخر، كان عمر  وقَّت ستة أشهر للمجاهدين والغائبين، فأنت يا أخي! اذهب إليهم كل ستة أشهر، أو كل أربعة أشهر، أو نحو ذلك، أو أحضرهم لديك، أما أن تتركهم هذه المدة الطويلة هذا فيه خطر كبير عليهم، وعليك أيضًا. فالمشروع لك ترك هذا الأمر، وأن تحضرهم لديك إذا أمكن، أو تذهب إليهم كل ستة أشهر.. كل أربعة أشهر.. كل خمسة أشهر، لا تطول المدة، تبقى عندهم شهرًا.. شهرين ثم ترجع لطلب الرزق. فالحاصل: أن الواجب عليك العناية بهذا الأمر، والحذر من مدة طويلة قد توقعهم في الفاحشة، أو توقعك أنت في الفاحشة، ولا حول ولا قوة إلا بالله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16220/ما-حكم-الغياب-عن-الاهل-لمدة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77006.mp3","categories":["نصائح وتوجيهات","غياب وفقدان الزوج"]},{"id":17384,"question":"يقول هذا السائل: يا سماحة الشيخ حفظكم الله! هل يجوز قراءة الأذكار المشروعة بعد الفراغ من الصلاة، أي: بعد الراتبة، وليس بعد الفريضة مباشرة؟","title":"ما حكم قول أذكار الصلاة بعد النوافل؟","answer":"الجواب: لا. السنة بعد الفريضة، السنة أن يأتي بالأذكار الشرعية بعد الفريضة، ثم الراتبة بعد ذلك، النبي كان يفعلها إذا سلم -عليه الصلاة والسلام- هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/16240/ما-حكم-قول-اذكار-الصلاة-بعد-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59404.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":17410,"question":"هذه مستمعة من الأردن كتبت -الحقيقة- سؤالًا طويلًا، ملخصه: سماحة الشيخ -وقد كتبت هذه الرسالة بأسلوبها الخاص- تقول: لقد جرت العادة في قريتنا بأن البنات لا يرثوا، وإنما يعطون من بعض المال مقابل أن تتنازل هذه البنات لإخوتها عن حصتها في الميراث، ويقولون: بأنه بيع وشراء، وأنا أحرص على إرضاء والدي، وقد عرض علينا والدي -نحن البنات- مبلغًا من المال مقابل التنازل لإخواني عن نصيبنا نحن البنات، تقول: علمًا بأن المال من والدي، وليس من إخوتي، وقد قلت لوالدي: بأن هذا لا يجوز، وبأن ذلك يعرضه للعذاب، ولكن إخوتي يقولون لأبي: بأنهم لن يعملوا بالأرض، ولا بالشجر إلا إذا سجل بأسمائهم، وأبي مصر على الموافقة، فنرجو من سماحة الشيخ الإجابة.","title":"حكم حرمان البنات من الإرث","answer":"الجواب: لا يجوز للأب أن يخص البنين بالورث، ولا أن يلزم البنات بأن يأخذن عوضًا، هذا منكر، هذا من عمل الجاهلية، ولا يجوز، بل يجب أن يساعد على الأمر الشرعي، وأن تكون التركة للجميع، للبنين والبنات للذكر مثل حظ الأنثيين كما قال الله سبحانه: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:12]. وهكذا الإخوة الأشقاء، والإخوة لأب يرثون للذكر مثل حظ الأنثيين كما قال -جل وعلا-: وَإِنْ كَانُوا إِخْوَةً رِجَالًا وَنِسَاءً فَلِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:176] يعني: الإخوة الأشقاء، والإخوة لأب، هذا واجب، ولا يجوز للأب، ولا الأخ أن يحيد عن هذا الأمر، هذا حرام منكر، من سنة الجاهلية، كان أهل الجاهلية لا يورثون النساء، والصبيان، ويورثون الذكور الكبار، وهذا غلط كبير، لا .... للمسلم أن يتشبه بالكفار، بل التركة للصغار، والكبار، والذكور، والإناث على قسمة الله، وليس للأب أن يلزم البنات، أو يعطيهم شيئًا من غير رضاهم ليسمحوا، لا، بل يجب أن يمكنوا من إرثهم، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16275/حكم-حرمان-البنات-من-الارث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77111.mp3","categories":["الفرائض","الهبة والعطية","نصائح وتوجيهات"]},{"id":17413,"question":"إذا غضبت الزوجة على زوجها فما الواجب أن تفعله في ذلك؟","title":"واجب المرأة تجاه زوجها","answer":"الجواب: الواجب عليها عدم العصيان لزوجها، وعدم المخالفة لأوامره الشرعية والمباحة، عليها السمع والطاعة لأوامره الشرعية والمباحة، وعليها كف الأذى. وهو كذلك عليه أيضًا كف الأذى عنها، وأن يعاملها بالحسنى، وأن يستوصي بها خيرًا، وعليهما التعاون على البر والتقوى، فإذا وجد ما يغضبها؛ فلا حرج عليها، إذا سبها، وغضبت؛ لا حرج، لكن عليها أن تجاهد نفسها، وعليها أن تنصحه عن السب والشتم، تقول له: اتق الله، هذا لا يجوز لك.. بالكلام الطيب. ولا شك أن الأذى منه يوجب غضبها، يسبب الغضب، لكن عليها أن تجتهد، وأن تتحمل، وأن تحرص على السمع والطاعة في المعروف، وأن تنصحه عما يقع منه من الغضب، والشتم، أو الضرب حتى تزول المشكلة بينهما مهما أمكن، فإن لم يفعل ذلك؛ فلها الخروج إلى بيت أهلها، والرفع إلى المحكمة.  المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16279/واجب-المراة-تجاه-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77114.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17428,"question":"تقول: بما أن هذا حالي، فإنني لا أستطيع الحركة، وكذلك الخروج من البيت، وأقضي وقتي كاملًا في المنزل، فبماذا تنصحونني والحال ما ذكر؟ هل أسمع القرآن الكريم، وإن كنت على غير طهارة؟","title":"توجيه للمقعد عن الحركة بالإكثار من الذكر","answer":"الجواب: نعم ننصحك بالإكثار من ذكر الله، وقراءة ما تحفظين من القرآن، وسماع القرآن من المذياع، وإن كنت على غير طهارة؛ لأن الطهارة ليست شرطًا في سماع الذكر، والقرآن، وإنما هي شرط في لمس المصحف، والقراءة من المصحف. أما السماع فالإنسان يستمع للقرآن، ولو كان جنبًا، ولو كانت حائضة، يستمع القرآن ويستفيد، لكن لا يمس المصحف إلا وهو على طهارة من الحدثين جميعًا، أما كونه يقرأ عن ظهر قلب فلا بأس أن يقرأ، وإن كان على غير طهارة من جهة الحدث الأصغر، والحيض كذلك، الحائض والنفساء لهما القراءة عن ظهر قلب؛ لأن مدتهما تطول. أما الجنب فلا، ليس له أن يقرأ حتى يغتسل، فلا يمس المصحف، ولا يقرأ أيضًا حتى يغتسل؛ لأن النبي ﷺ كان لا يمنعه شيء عن القرآن إلا الجنابة، وقال في الجنب: أما الجنب فلا ولا آية يعني: حتى يغتسل، ونوصيك بالإكثار من ذكر الله، والتسبيح، والتحميد، والتهليل، والاستغفار، وقراءة ما تيسر معك من القرآن، ولو الفاتحة ترددينها مع ما تيسر معها، فلك بكل حرف حسنة، والحسنة بعشر أمثالها، وهذا خير عظيم. نعم. المقدم: جزاكم الله خيرًا، تركز على سماع القرآن الكريم سماحة الشيخ؟ الشيخ: نعم، الله يقول سبحانه في كتابه العظيم: وَإِذَا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنصِتُوا [الأعراف:204] كان النبي ﷺ يقرأ على أصحابه القرآن وهم ينصتون، ويستمعون، ويستفيدون، والمستمع شريك القارئ في الأجر إذا أراد ذلك، وقصد ذلك، والقارئ له بكل حرف حسنة، والحسنة بعشر أمثالها، كما جاء في الحديث عنه ﷺ والمستمع نرجو له ذلك أيضًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16306/توجيه-للمقعد-عن-الحركة-بالاكثار-من-الذكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83609.mp3","categories":["نصائح وتوجيهات"]},{"id":17429,"question":"سماحة الشيخ عبد العزيز حفظكم الله، البعض من الناس يلزمون أنفسهم بهذه النذور، ومن ثم يعجزون عنها، ويطلبون الفتيا من المشايخ، ما الواجب على الناس في ذلك يا شيخ؟","title":"توجيه لمن يلزمون أنفسهم بالنذور","answer":"الجواب: النذر لا ينبغي، الرسول نهى عن النذر، وقال ﷺ: لا تنذروا فإن النذر لا يرد من قدر الله شيئًا، وإنما يستخرج به من البخيل.  فالواجب على الناس ترك النذور، وعدم التعاطي، يعني: ينبغي للمسلم أن يتجنب النذور؛ لأنه ينذر، ثم يندم، فالواجب تجنب النذور، لكن متى نذر طاعةً؛ وجب الوفاء؛ لأن الله قال سبحانه: يُوفُونَ بِالنَّذْرِ وَيَخَافُونَ يَوْمًا كَانَ شَرُّهُ مُسْتَطِيرًا[الإنسان:7] ويقول سبحانه: وَمَا أَنفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ [البقرة:270] يعني: فيجازيكم عليه، والنبي يقول ﷺ: من نذر أن يطيع الله فليطعه.  فإذا وقع النذر نظر فيه، فإن كان طاعةً لله؛ وجب الوفاء، وإن كان غير طاعة؛ كفَّر عن نذره، لكن لا ينبغي له أن ينذر أولًا، يعني: يعلم ألا ينذر أبدًا، لكن متى نذر طاعةً، كأن يقول مثلما تقدم: إن الله شفى مريضي؛ صمت شهرًا، أو صمت عشرة أيام.. تصدقت بألف ريال، وما أشبه ذلك؛ يلزمه الوفاء، لكن أولًا يقال له: لا تنذر، لكن متى نذر طاعة؛ لزمه الوفاء، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16300/توجيه-لمن-يلزمون-انفسهم-بالنذور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77122.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":17435,"question":"سماحة الشيخ، أمامي رسالة مكونة من صفحتين، لا أدري هل أقرأ هاتين الصفحتين؟ أم أقرأ ما لخصته عنها؟الشيخ: الملخص يكفي.المقدم: ملخص ما في هذه الرسالة: أن صاحبها يشكو من زوجته شكوى فيها كثير من المرارة، فهو يقول: إنها تصر على الذهاب لأهلها في كل أسبوع، ثم إنها تدفع الراتب كاملًا إلى أهلها، مع العلم أنه هو الذي يذهب بها إلى المدرسة، ويعيدها أيضًا إلى المدرسة، وهي تترك البيت كثيرًا في سبيل هذه الوظيفة، ثم يقول: إنها تهمل رعاية البيت، والطفل، وتترك كل ذلك للخادمة، وهي كثيرة الذهاب والإياب إلى الناس، ويرجو من سماحتكم التوجيه؟ جزاكم الله خيرًا.","title":"نصيحة لمن تؤذي زوجها ولا تطيعه","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، سيد ولد آدم، وعلى آله وأصحابه، ومن سلك سبيله، واهتدى بهداه إلى يوم الدين، أما بعد.  فإن الواجب على كل زوجة أن تسمع، وتطيع لزوجها في المعروف، وليس لها أن تذهب إلى أهلها إلا بإذنه، ولا إلى غير أهلها إلا بإذنه، وهكذا التدريس ليس لها أن تدرس إلا بإذنه إلا أن يكون قد شرط عليه عند العقد، فـ المسلمون على شروطهم وإلا فليس لها أن تدرس إلا بإذنه. وكونها تذهب إلى أهلها كل أسبوع ليس لها ذلك إلا بإذنك، فينبغي لك أن تلاحظ الموضوع، وأن تنظر في المصلحة، فإن رأيت أن في ذهابها مصلحة؛ فلا بأس مراعاة لخاطر والديها، وحرصًا على سلامة القلوب، وبقاء المودة، وإن تيسر أن يكون ذهابها إليهم في أكثر من ذلك، كعشرة أيام، أو نصف شهر، فلا بأس، تتفق أنت والوالدان، والمرأة على الشيء الذي فيه المصلحة للجميع، وفيه كسب رضاك، وعدم التسبب في الفراق. وهكذا ليس لها الخروج لغير أهلها إلا بإذنك، والواجب عليها أن تلزم البيت، وتعتني بالأولاد، وتربيتهم التربية الطيبة، ولا ينبغي أن تكلهم إلى الخادمة، بل ينبغي أن تعتني بهم هي، وأن تجتهد في تربيتهم، والإحسان إليهم، وإذا كانوا يفهمون تحرص على تربيتهم التربية الإسلامية، وتوجيههم إلى الخير. أما الراتب فهو لها، لكن ينبغي لها أن تعطيك بعض الشيء في مقابل تعبك، وذهابك، وإيابك، وتسميحًا لخاطرك ولا سيما إذا كنت محتاجًا، فإن المشروع لها أن تساعدك؛ لأن الله يقول سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، ويقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته ويقول النبي ﷺ: والله في عون العبد ما كان العبد في عون أخيه فنصيحتي لها أن تساعدك من الراتب، والواجب عليها أن تسمع، وتطيع لك في كل شيء، ليس فيه معصية لله  لا في ذهابها إلى أهلها، ولا في غيرهم. أما وجود الخادمة لديكم فأنت قد أخطأت في الإتيان بالخادمة، هي التي سببت هذه المشاكل، أبعد الخادمة حتى تقيم في البيت هي، وتقوم بأولادها، وخدمة البيت، فإبعاد الخادمة هو الطريق إلى ... السلامة من ذهابها إلى أهلها، وغيرهم في كل وقت، ثم الخادمة وجودها عندك فيه خطر عليك، وعلى دينك، وليس في البيت غيرها، والرسول ﷺ قال: لا يخلون رجل بامرأة فإن الشيطان ثالثهما فوجودها في البيت، والمرأة خارج البيت في الدرس، أو عند أهلها فيه خطر عظيم.  فنصيحتي لك إبعاد الخادمة، وردها إلى أهلها، وأن تقوم الزوجة بما يتعلق بالبيت، ولو تركت التدريس، هذه نصيحتي لكما جميعًا، ونسأل الله للجميع الهداية والتوفيق. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا الأولى في هذه الأمور الحياة الزوجية؟ الشيخ: نعم، على كل منهما العناية بالحياة الزوجية، والحرص على بقائها على الوجه الشرعي من دون معصية لله . فالمقصود: أن المشروع لك أيها الأخ أن تعتني بحفظ زوجتك، وبقائها في البيت، وأن تعمل كل الأسباب التي تبعدها عن الخروج إلا بإذنك. المقدم: جزاكم الله خيرًا، لعل هذه الرسالة تتيح لنا الفرصة سماحة الشيخ كي ما نسأل: إذا ما أراد الإنسان أن يتزوج من موظفة، فما هي الشروط التي تنصحونه أن يشترطها حتى تكون الحياة الزوجية مستقيمة؟ الشيخ: هو يعمل بالأصلح، إن رأى الموافقة على بقائها في الوظيفة؛ فلا بأس، وإن رأى اشتراط ترك الوظيفة: فلا بأس، هو أعلم بنفسه، وهذا شيء يرجع إلى علمه، وإلى حاجته، وإلى تقديره، فإذا تيسر بقاؤها في الوظيفة الطيبة، وفي البيت من يقوم مقامها في إصلاح البيت، كأمه، وأخواته، ونحو ذلك، وإلا فالأصلح ألا يقبل موظفة، بل يتزوج امرأة غير موظفة؛ حتى تقيم في بيته، وحتى تعتني بالبيت، وحتى يرتاح إليها، إذا جاء من عمله وجدها. والمقصود بكل حال: هو أن ينظر فيما هو أصلح له في دينه، ودنياه مع الموظفة، وغيرها. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/16296/نصيحة-لمن-توذي-زوجها-ولا-تطيعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_836/nour_83601.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17447,"question":"على بركة الله نبدأ هذه الحلقة برسالة السائلة من جدة التي رمزت لاسمها بـ (ش) استعرضنا لها في حلقة سابقة سؤالًا بقي ... هذا السؤال، تقول: سماحة الشيخ! لقد كثر العقوق في هذه الأيام بشكل مرعب، ومخيف، حيث أن البعض منهم من يضرب والديه، والبعض منهم من يذهب عنهم، ويتركهم، ويقوم مع زوجته أيضًا، تكون الزوجة أيضًا عونًا لهذا الزوج على هذا العقوق، نرجو من سماحة الشيخ التوجيه للأولاد، وللزوجات حول هذا الموضوع مأجورين.","title":"توجيه للأبناء ببر الوالدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فقد بيَّن الله سبحانه في كتابه الكريم، وهكذا رسوله -عليه الصلاة والسلام- حق الوالدين، وأوجب برهما، والإحسان إليهما، وحرم عقوقهما، فالواجب على كل مسلم، وعلى كل مسلمة بر الوالدين، والإحسان إليهما، والحرص على رضاهما، والحذر من عقوقهما، قال الله -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24] وقال سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا[النساء:36] قال -جل وعلا-: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ[لقمان:14].  فشُكْر الوالدين، والإحسان إليهما أمر لازم، قال: وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ إِحْسَانًا [الأحقاف:15] فالله -جل وعلا- أوصى بهما، والإحسان إليهما. فالواجب على كل مسلم، وعلى كل مسلمة برهما، والإحسان إليهما، والحذر من عقوقهما، وثبت عنه ﷺ أنه قال لما سئل: أي العمل أفضل؟ قال: الصلاة على وقتها قيل: ثم أي؟ قال: بر الوالدين قيل: ثم أي؟ قال: الجهاد في سبيل الله فبيَّن ﷺ أن بر الوالدين من أهم الواجبات، وقال ﷺ في الحديث الصحيح: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله، قال:  الاشراك بالله، وعقوق الوالدين وكان متكئًا فجلس، فقال: ألا وقول الزور، ألا وشهادة الزور رواه الشيخان، البخاري ومسلم في الصحيحين.  هذا يبين لنا عظم كبيرة عقوق الوالدين، وأن عقوقهما من أكبر الكبائر، قرنه الله بالشرك، وقرنه الرسول ﷺ في هذا الحديث بالشرك، وفي الحديث الصحيح يقول النبي ﷺ: من الكبائر شتم الرجل والديه قيل: يا رسول الله! وهل يسب الرجل والديه؟! -استنكر الصحابة ذلك- قال: نعم. يسب أبا الرجل؛ فيسب أباه، ويسب أمه؛ فيسب أمه. فالواجب على جميع المسلمين من رجال ونساء العناية ببر الوالدين، والإحسان إليهما، والحذر كل الحذر من عقوقهما بالقول، أو الفعل، نسأل الله لجميع المسلمين الهداية، والتوفيق، وصلاح القول، والعمل. نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ، قد يتساءل الشاب، أو الشابة: كيف يكون البر في الحياة، وفي الممات يا شيخ؟ الشيخ: بالمعروف؛ الإحسان إليهما بالنفقة عليهما إن كانا فقيرين، وبالسمع والطاعة لهم في المعروف، إذا طلب منه أن يذهب كذا، أو يأتي بكذا، يطيعهما في المعروف، والإتيان بحاجاتهما إذا طلباه في حاجة لهما، في تنفيذ أوامرهما التي ليست معصية لله، هذا من برهما، وإذا كانا فقيرين من برهما الإنفاق عليهما إذا كان يقدر، ومن برهما السمع والطاعة لهما في المعروف، إذا قالا له: اذهب هات كذا، أو اذهب بكذا، أو ادع لنا فلانًا.. أو ما أشبه ذلك، يعني: معناه السمع والطاعة لهم في المعروف، وبرهما بالمال، والكلام الطيب، والأسلوب الحسن حسب الطاقة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16309/توجيه-للابناء-ببر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77201.mp3","categories":["نصائح وتوجيهات"]},{"id":17461,"question":"تقول السائلة: والدي متزوج من امرأة ثانية منذ أكثر من عشر سنوات، وهو لا ينفق على أمي، ولا على إخوتي، وإنما ينفق على زوجته الأخرى، وأولادها الذين هم إخوتي من أبي بحجة أنه لا يستطيع النفقة على أمي وإخوتي، والحجة بأن إخوتي قد توظفوا ولهم رواتب، مع العلم أن منهم من لم يزل طالبًا، ويأخذ المصروف من أخته الموظفة، ومن أخيه الموظف، فما الحكم؟ تقول: إن والدي يطلب من إخوتي أن يعطوه من رواتبهم، ويغضب إذا لم يعطوه، مع أن والدي موظف، ويتقاضى راتبًا شهريًا، لكن هو يقول: بأنه مديون، وعليه ديون كثيرة، لكن الله أعلم، على العموم إذا كانت الحالة كما ذكرت لكم فهل لي أن أدفع زكاة أموالي لوالدي؟ أفتوني مأجورين.","title":"حكم ترك الزوج النفقة على الزوجة الأولى","answer":"الجواب: يلزم الوالد النفقة على زوجته الأولى إذا كان أولادها لا يقومون بها، أما إذا كان أولادها يكفونها المؤونة، وقد أنفقوا عليها كفوا؛ لأن أولاده له، حقه عليهم كبير، والرسول ﷺ يقول: أنت ومالك لأبيك فإذا كفوه مؤونة أمهم، وأنفقوا عليها؛ كفى والحمد لله، أما إذا لم يكفوه، وهي تطلب النفقة مخيرة، إن شاءت صبرت، وإن شاءت قالت: طلقني، تطلب الطلاق إن لم تصبر، وإلا صبرت، وإن أنفق عليها أولاده كفوه المؤونة، والحمد لله، ولا حرج عليه. وإن طلب منهم شيئًا فعليهم أن يعطوه من مالهم ما لا يضرهم، أما إذا كان يضرهم، ولا يستطيعون؛ فلا يلزمهم ذلك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] لكن ما داموا يستطيعون؛ فعليهم أن يرضوه، ويعطوه من رواتبهم ما يعينه على قضاء دينه، وعلى النفقة على زوجته الجديدة، يقول النبي ﷺ: إن أطيب ما أكلتم من كسبكم، وإن أولادكم من كسبكم ويقول ﷺ: أنت ومالك لأبيك حق الوالد عظيم.  فالواجب عليهم أن يجتهدوا في إرضائه وفي مساعدته، ويقوموا بأمهم، وإذا كانت أمهم لا تصبر، وتقول: أبي النفقة من الزوج، تخيره تقول، تطلب الطلاق، إلا إذا قام أولاده بالنفقة فلا حق لها؛ لأن نفقة أولاده كنفقته، إذا أنفقوا عليها بما يكفيها الحمد لله، أما إذا ما أنفقوا عليها، ولا أنفق هو؛ فلها طلب الطلاق، نعم. المقدم: العدل بين الزوجات أمر مطلوب، هل لكم في ختام هذا ... ؟ الشيخ: العدل واجب، لكن إذا كان أولادها ينفقون عليها هم يقومون مقامه، والحمد لله ما يسمى جائرًا، أولاده يقومون مقامه في النفقة عليها، لكن عليه أن يقسم لها مثلما يقسم لضرتها، نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16329/حكم-ترك-الزوج-النفقة-على-الزوجة-الاولى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_772/nour_77217.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17525,"question":"على بركة الله نبدأ هذا اللقاء برسالة السائلة أم سارة من المدينة المنورة كتبت هذه الرسالة بأسلوبها الخاص تقول: سماحة الشيخ! زوجي أحيانًا لا يؤدي بعض الصلوات في المسجد مع الجماعة ولكنه يصليها في المنزل، وخاصة صلاتي الفجر والعصر، ويعلم الله بأنني حاولت معه كثيرًا ولكن دون جدوى، فكنت دائمًا أحرص على إيقاظه لأداء الصلاة في المسجد، وكان يستجيب لذلك في أول الأمر وبعد ذلك أصبح يرفض الاستيقاظ وينبهنا على ذلك قبل نومه ويقول: لا توقظوني، ولكنني أوقظه للصلاة رغبة في الأجر وتحريًا في الأجر، فأصبحنا على خلاف دائم بسبب ذلك الأمر، وتعبت تعبًا نفسيًا من كثرة الخلافات الزوجية والنقاش عند استيقاظه، وإذا طلبت من إحدى بناته أن توقظه فإنه يزجرهم وينهاهم عن ذلك، لذلك فإنني في الأشهر الأخيرة تقريبًا تركت إيقاظه تمامًا، فإذا استيقظ على الوقت صلى في المسجد، وإلا فإنه يصلي في المنزل، أرجو من سماحة الشيخ عبد العزيز حفظه الله أن يبين لي هل علي إثم في ذلك في عدم إيقاظه؛ وذلك لكثرة الخلافات الزوجية، وقد تسبب لي الإحراجات، وجهوني مأجورين حيث تركت تأثيرًا على صحتي وعلى نفسيتي؟","title":"كيفية التعامل مع الزوج المقصر في صلاة الجماعة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالواجب على كل مؤمن ومؤمنة إنكار المنكر على من فعله سواء كان زوجًا أو غير زوج لقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71]، ولقول الله : كُنْتُمْ خَيْرَ أُمَّةٍ أُخْرِجَتْ لِلنَّاسِ تَأْمُرُونَ بِالْمَعْرُوفِ وَتَنْهَوْنَ عَنِ الْمُنكَرِ وَتُؤْمِنُونَ بِاللَّهِ[آل عمران:110]، ولقوله سبحانه: لُعِنَ الَّذِينَ كَفَرُوا مِنْ بَنِي إِسْرَائِيلَ عَلَى لِسَانِ دَاوُدَ وَعِيسَى ابْنِ مَرْيَمَ ذَلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ ۝ كَانُوا لا يَتَنَاهَوْنَ عَنْ مُنكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ[المائدة:78-79] فلعنهم سبحانه على أعمالهم الخبيثة التي منها عدم التناهي عن المنكر.\nفالواجب عليك إيقاظه والصبر على ما يحصل من بعض الأذى، وأبشري بالخير، والأجر العظيم، وإذا كان يؤخر الصلاة إلى طلوع الشمس ويتعمد ذلك، أو يؤخر العصر إلى غروب الشمس؛ فهذا كفر أكبر؛ لأن تأخير الصلاة عن وقتها عمدًا كفر أكبر على الصحيح من أقوال العلماء؛ لقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة، وقوله ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر. أما إذا كان لا، يقوم ويصلي في الوقت لكن لا يصلي في الجماعة هذه معصية، والواجب عليه التوبة إلى الله من ذلك، وعليك أنت أن تنكري عليه المنكر، وأن تجتهدي في ذلك وتصبري، وعلى بناته وعلى أمه إن كانت موجودة، وعلى أبيه إن كان موجودًا أن يساعدوا في هذا؛ لأن الواجب التعاون على البر والتقوى كما قال الله سبحانه: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2]، وعليك مع ذلك أن تسألي الله له الهداية، احتسبي الأجر، واسألي الله له الهداية في سجودك، وفي آخر صلاتك، وفي غيرها من الأوقات، تقولي: اللهم اهد فلانًا، اللهم أصلح قلبه وعمله، اللهم منَّ عليه بالتوبة النصوح، لعل الله يهديه بأسبابك، وأبشري بالخير والأجر العظيم. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16440/كيفية-التعامل-مع-الزوج-المقصر-في-صلاة-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77501.mp3","categories":["صلاة الجماعة","نصائح وتوجيهات"]},{"id":17589,"question":"يقول: إنني حفظت القرآن الكريم والحمد لله في سنتين وكانت متتالية، يعني: طوال اليوم، وطول السنتين ما فارقت القرآن يومًا واحدًا، هل هذه المدة كافية أم أنني..الشيخ: أعد.المقدم: يقول: أعرفكم بأنني حفظت القرآن في سنتين فقط وكانت متتالية يعني طوال اليوم وطوال السنتين ما فارقت القرآن يومًا واحدًا، هل هذه المدة كافية جزاكم الله خيرًا إلا أنني ألاحظ أنني كثير النسيان، فبماذا تنصحونني؟","title":"نصيحة لمن يتفلت عليه القرآن","answer":"الجواب: حفظ القرآن مطلوب ومشروع، وإذا تيسر له حفظه في وقت قصير كان من نعم الله العظيمة.\nفالحاصل أنه يشرع له أن يتعاطى حفظ القرآن حسب التيسير بشرط ألا يعطله عن واجب ولا يقع في محرم، لابد أن يكون حفظه للقرآن مع مراعاة ما يجب عليه وما يحرم عليه، فيحفظ القرآن في الأوقات المناسبة ولا يعطله عن الصلاة في المسجد مع الجماعة، ولا يعطله عن كسب الحلال الذي يقوم بحاله وحال أهل بيته، ولا يوقعه في الحرام من فعل ما حرم الله عليه من أجل حفظ القرآن مثلًا، بأن يتعاطى ما حرم الله عليه ليحفظ القرآن إما بتعاطي ما يضره من سهر حتى يضيع ما أوجب الله عليه، أو بتعاطي أشياء بزعمه أنها تعينه على الحفظ ولكنها محرمة، من حبوب محرمة أو شراب محرم أو غير ذلك، لابد أن يراعي فعل ما أوجب الله وترك ما حرم الله مع عنايته بحفظ القرآن الكريم. وإذا نسي لا يضره لكن يجتهد أن لا ينسى يتعاهده، كما أمره النبي ﷺ بقوله: تعاهدوا هذا القرآن، فوالذي نفسي بيده إنه لأشد تفلتًا من الإبل في عقلها، فالمؤمن يتعاهده ويحرص على حفظه، ولكن لا يشق على نفسه، ولا يتعاطى عملًا يضيع عليه الواجبات أو يوقعه في المحرمات، بل يتحفظ في الأوقات المناسبة مع قيامه بما أوجب الله من صلاة في الجماعة.. من أداء حقوق أهله وأولاده.. من كسب الحلال.. ومن غير هذا مما يلزمه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16517/نصيحة-لمن-يتفلت-عليه-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84104.mp3","categories":["القرآن وعلومه","نصائح وتوجيهات"]},{"id":17600,"question":"يقول: إنني حفظت القرآن الكريم والحمد لله في سنتين وكانت متتالية، يعني: طوال اليوم، وطول السنتين ما فارقت القرآن يومًا واحدًا، هل هذه المدة كافية أم أنني..الشيخ: أعد.المقدم: يقول: أعرفكم بأنني حفظت القرآن في سنتين فقط وكانت متتالية يعني طوال اليوم وطوال السنتين ما فارقت القرآن يومًا واحدًا، هل هذه المدة كافية جزاكم الله خيرًا إلا أنني ألاحظ أنني كثير النسيان، فبماذا تنصحونني؟","title":"نصيحة لمن يتفلت عليه القرآن","answer":"الجواب: حفظ القرآن مطلوب ومشروع، وإذا تيسر له حفظه في وقت قصير كان من نعم الله العظيمة.\nفالحاصل أنه يشرع له أن يتعاطى حفظ القرآن حسب التيسير بشرط ألا يعطله عن واجب ولا يقع في محرم، لابد أن يكون حفظه للقرآن مع مراعاة ما يجب عليه وما يحرم عليه، فيحفظ القرآن في الأوقات المناسبة ولا يعطله عن الصلاة في المسجد مع الجماعة، ولا يعطله عن كسب الحلال الذي يقوم بحاله وحال أهل بيته، ولا يوقعه في الحرام من فعل ما حرم الله عليه من أجل حفظ القرآن مثلًا، بأن يتعاطى ما حرم الله عليه ليحفظ القرآن إما بتعاطي ما يضره من سهر حتى يضيع ما أوجب الله عليه، أو بتعاطي أشياء بزعمه أنها تعينه على الحفظ ولكنها محرمة، من حبوب محرمة أو شراب محرم أو غير ذلك، لابد أن يراعي فعل ما أوجب الله وترك ما حرم الله مع عنايته بحفظ القرآن الكريم. وإذا نسي لا يضره لكن يجتهد أن لا ينسى يتعاهده، كما أمره النبي ﷺ بقوله: تعاهدوا هذا القرآن، فوالذي نفسي بيده إنه لأشد تفلتًا من الإبل في عقلها، فالمؤمن يتعاهده ويحرص على حفظه، ولكن لا يشق على نفسه، ولا يتعاطى عملًا يضيع عليه الواجبات أو يوقعه في المحرمات، بل يتحفظ في الأوقات المناسبة مع قيامه بما أوجب الله من صلاة في الجماعة.. من أداء حقوق أهله وأولاده.. من كسب الحلال.. ومن غير هذا مما يلزمه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16517/نصيحة-لمن-يتفلت-عليه-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_841/nour_84104.mp3","categories":["القرآن وعلومه","نصائح وتوجيهات"]},{"id":17643,"question":"يقول السائل إبراهيم أبو حامد من أسئلته في العقيدة: ما حكم التبرك بالصالحين وآثارهم سماحة الشيخ؟","title":"حكم التبرك بالصالحين","answer":"الجواب: لا يجوز التبرك بالصالحين ولا بآثارهم، إنما هذا خاص بالنبي ﷺ، التبرك بآثاره وبعرقه وريقه ووضوئه هذا خاص بالنبي ﷺ، أما غيره لا، الصحابة لم يتبركوا بـالصديق ولا بـعمر ولا بـعثمان ولا بـعلي ؛ ولأنه من وسائل الشرك، فالواجب ترك ذلك والحذر منه.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16568/حكم-التبرك-بالصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59419.mp3","categories":["نصائح وتوجيهات","التبرك وأنواعه"]},{"id":17660,"question":"تقول سماحة الشيخ: لي صديقة ارتكبت العديد من الأخطاء، سواءً بينها وبين الله، أو بينها وبين الناس، ولكنها تابت إلى الله توبةً نصوحًا، وليس بيديها الآن أن تصلح الأخطاء التي ارتكبتها مع الناس، فهل الله  يغفر لها الذي بينها وبين الناس؟ أم كيف تنصحونها تتصرف؟ جزاكم الله خيرًا.","title":"كيفية التعامل مع المظالم بعد التوبة","answer":"الجواب: عليها الندم على ما مضى من سيئاتها، والإقلاع عن ذلك، والعزم ألا تعود، وهذه شروط التوبة، شروطها ثلاثة: الندم على الماضي من المعاصي، والإقلاع منها، وتركها خوفًا من الله، وتعظيمًا لله، وإخلاصًا له، وأمرٌ ثالث، وهو العزم الصادق أن لا تعود فيها. وهناك شرطٌ رابع وهو يتعلق بحق المخلوقين، إذا كان عليها حقوق المخلوقين، خصوم، أو سرقات، أو قصاص، عليها أن تؤدي حقوقهم، إلا أن يسمحوا، فإذا كان عندها لأحدٍ حقوق، ظلمتهم، أخذت منهم أموالًا، تردها إليهم، السرقة تردها إليهم بالطرق التي توصلها إليهم، عليها قصاص، تمكن من أخذ القصاص. وهكذا الرجل، كله اللفظ واحد، على الرجل والمرأة جميعًا أداء الحقوق، من شرط التوبة، وتمامها؛ أن تؤدى الحقوق التي للناس، مع الشروط الثلاثة السابقة: الندم على الماضي، والإقلاع من الذنب خوفًا من الله، وتعظيمًا له، وإخلاصًا له، والعزم الصادق أن لا يعود، والشرط الرابع، وهو أداء الحقوق، إذا كان على الرجل، أو المرأة حقوق، على كلٍ منهما أداؤها، إن كانت مالية يؤديها، إن كانت عرض؛ يستحل أخاه، كونه تكلم في عرضه، فإن كان يخشى شيئًا؛ استغفر له، ودعا له في ظهر الغيب، وذكره بالأخلاق الطيبة التي يعرفها عنه، والأعمال الطيبة، بدلًا من تلك الأعمال التي ذمه بها، يعني: هذه بهذا، إذا كان اغتابه؛ فإنه يذكره بالأخلاق الطيبة، والأعمال الطيبة التي يعرفها عنه، في المجالس التي اغتابه فيها، إذا لم يتيسر استحلاله من ذلك. نعم.\nالمقدم: جزاكم الله خيرًا، إذا كانت حقوقًا مالية سماحة الشيخ، هل يقدمها في شكل هدية، أو كيف ترون ذلك؟\nالشيخ: يردها بالطرق الموصلة، يردها الأموال بالطريقة التي توصلها إليهم، بواسطة من يرى من الثقات، يسلمها لهم، ويقول: هذه حقوقكم من شخصٍ يرى أنها لكم عليه، وأنها لازمةٌ له، أرسلني بها، ولا يحب أن يذكر اسمه. نعم.\nالمقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16590/كيفية-التعامل-مع-المظالم-بعد-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72706.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":17669,"question":"سماحة الشيخ! بعض الأمهات هداهن الله، يغفلن عن تنبيه بناتهن إلى مثل هذه الأمور، ما هو توجيهكم للأمهات حيال هذا؟ جزاكم الله خيرًا.","title":"توجيه الأمهات بتعليم بناتهن أحكام العبادة","answer":"الجواب: الواجب على الأمهات تنبيه بناتهن، وهكذا الأخوات الكبيرات، تنبيه أخواتهن، وهكذا العمات، والخالات؛ التعاون على البر والتقوى، كل واحدة تنبه الصغيرة على ما يجب عليها من جهة الصوم في رمضان، من جهة عدم الصلاة في أيام الحيض، من جهة الطمأنينة في الصلاة، والخشوع فيها، في جميع الوجوه، كل واحدة تعلم أختها في الله، أختها، بنتها، بنت أخيها، بنت أختها، جيرانها، جلساءها، تلاميذها، عليها أن تعلم، توضح لهم ما قد يخفى عليهم في أمور الصلاة، أمور الصيام، أمور الزكاة، أمور الحج، أمور بر الوالدين، إلى غير ذلك، على كلٍ من الأخوات، والعمات، والخالات، والأمهات؛ التوجيه للبنات الشابات، والإرشاد لهن إلى ما قد يخفى عليهن من أمور الدين. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16600/توجيه-الامهات-بتعليم-بناتهن-احكام-العبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_727/nour_72711.mp3","categories":["تربية الأولاد","نصائح وتوجيهات"]},{"id":17720,"question":"هذه أخت مستمعة لهذا البرنامج تقول: أود من سماحة الشيخ أن يقدم نصيحة لزوجي، فزوجها تقول: مع أنه ملتزم بشعائر الدين ومؤدي للصلوات ومن الذين يخافون الله، إلا أنه يعاملها بقسوة مع أنها تقول: أنا وإياه نؤدي العبادات في أوقاتها وأولادنا- والحمد لله- على عبادة دائمة، هل من نصيحة سماحة الشيخ؟","title":"وصية للأزواج بحسن العشرة مع زوجاتهم","answer":"الجواب: نعم، نوصي جميع الأزواج بتقوى الله، والرفق بالزوجات، وإحسان العشرة، وعدم الغلظة وعدم سوء الكلام، قال الله تعالى: وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ [النساء:19]، وقال جل وعلا: وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ [البقرة:228]، وقال النبي ﷺ: استوصوا بالنساء خيرًا.\nفالواجب على الأزواج المعاشرة الطيبة والكلام الطيب والأسلوب مع الزوجة الطيب وعدم الشدة وعدم العنف؛ لا في الكلام، ولا في غيره. هذا هو الواجب على الأزواج. والزوجة كذلك عليها أن تعامل زوجها بالكلام الطيب والأسلوب الحسن والسمع والطاعة في المعروف، كل منهما عليه أن يعين الآخر على الخير، الله يقول جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، فعليها وعلى زوجها التعاون على البر والتقوى بالكلام الطيب والأسلوب الحسن والمسارعة إلى كل ما يرضي الآخر مما أباح الله، نسأل الله للجميع الهداية.\nالمقدم: أحسن الله إليكم وبارك فيكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16673/وصية-للازواج-بحسن-العشرة-مع-زوجاتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59527.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17742,"question":"تقول السائلة في آخر أسئلتها: للأم حقوق كثيرة فهل لها الحق بالقول بكلام جارح أو فاسق وشنيع تجاه بناتها، الله يعلم بطهرهن؟","title":"حق الآباء على الأبناء والعكس","answer":"الجواب: الواجب على الأولاد البر بالوالدين، وإحسان المعاشرة لهما، والرفق بهما؛ لأن حقهما عظيم؛ كما قال الله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا[الإسراء:23]، وقال سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ[لقمان:14]، وقال جل وعلا: وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ إِحْسَانًا[الأحقاف:15] ولما سئل النبي عليه الصلاة والسلام قيل: «يا رسول الله! من أحق الناس بحسن الصحبة؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أبوك»، وفي الرواية الأخرى: «يا رسول الله! من أبر؟ قال: أمك، قال: ثم من ؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب»، فبرهما واجب، والإحسان إليهما، والرفق بهما، وحسن المعاشرة لهما، وطيب الكلام معهما؛ هذا واجب الأولاد.\nأما الوالدان فعليهما أن يتقيا الله في أولادهما، وأن يحسنا إلى الأولاد، وأن يجتهدا في تربيتهما التربية الصالحة، وأن لا يسيئا إلى أولادهم بغير حق، لا بالكلام، ولا بالفعال، يجب على الأم وعلى الوالد - الأب - أن يحفظ كل منهما لسانه عما يؤذي الأولاد من الشتم، والكلام السيئ بغير حق.\nعليهما حق، ولهما حق، فعليهما حق بأن يحسنا إلى أولادهما، ويربيان أولادهما التربية الشرعية، وعليهما أن يحذرا سبهما، أو وصفهما بشيء باطل؛ لأن هذا يسبب العداوة، والبغضاء، والقطيعة، فعلى كل من الصنفين أداء الواجب، على الأولاد أداء الحق الذي عليهم من البر، والصلة، والإحسان، وعلى الوالدين تقوى الله، وأن يحسنا إلى أولادهما، وأن يكفا الشر عنهما. نعم.\nالمقدم: أحسن الله إليكم، وجزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16714/حق-الاباء-على-الابناء-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_777/nour_77710.mp3","categories":["تربية الأولاد","نصائح وتوجيهات"]},{"id":17763,"question":"هذا السائل يقول: قراءة الكتب الإسلامية بدون معلم، هل هي مفيدة، وأرجو أن تذكروا بعض الكتب التي تنصحوننا باقتنائها وقراءتها ويعتمد عليها؟","title":"نصيحة حول قراءة الكتب الدينية وبيان أفضلها","answer":"الجواب: قراءة الكتب فيها تفصيل: أما قراءة الكتب للتعلم، فلا بد أن يقرأها الإنسان على أهل العلم؛ حتى يعلموه ويفقهوه، أما قراءتها للحفظ حتى يستفيد منها ويسأل أهل العلم؛ فهذا طيب، ولكن أهم شيء القرآن، كونه يحفظ القرآن هذا أهم شيء، القرآن هو أصل كل خير، وهو أصدق كتاب وأفضل كتاب، إذا تيسر حفظه؛ فهو مقدم على كل شيء، ومن لم يحفظه يستحب له الإكثار من قراءته، يستحب الإكثار من قراءته، للرجل والمرأة في الليل والنهار؛ لما فيه من العلم العظيم والدعوة إلى الخير، فيستحب لكل مؤمن ومؤمنة الإكثار من قراءة القرآن الكريم من المصحف أو عن ظهر قلب.\nأما الكتب الأخرى: فإذا تيسر له حفظ كتاب التوحيد للشيخ محمد بن عبد الوهاب رحمه الله في العقيدة، كشف الشبهات له في العقيدة، ثلاثة الأصول له في العقيدة، والقواعد الأربع، شروط الصلاة كتاب جيد مختصر، العقيدة الواسطية، حفظ هذه جيد ينفع، بلوغ المرام في الحديث للحافظ ابن حجر ، عمدة الحديث للحافظ عبد الغني بن سرور المقدسي كتاب طيب إذا تيسر حفظه، الأربعين النووية وتتمتها لـابن رجب خمسين حديثًا هذه جيدة إذا تيسر حفظها، هذا طيب. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16738/نصيحة-حول-قراءة-الكتب-الدينية-وبيان-افضلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_596/59619.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":17822,"question":"عبد الله خليل من المنطقة الشرقية بعث بسؤال يقول: عندي ابن عم يدخن ثم قطع التدخين، وأراد العودة إلى ذلك فأخبرته بأنه لا يحل له العودة إليه؛ لأنه حلف بالله وفي يده القرآن بأن لا يدخن ولكنه مصمم على أن يعود إلى التدخين، ويقول: بأنه لا يستطيع، ماذا عليه أن يفعل؟ جزاكم الله خيرًا.","title":"حكم الرجوع إلى الدخان بعد تركه","answer":"الجواب: الواجب عليه أن يحذر العودة، وأن يتقي الله في ذلك، وأن يعالج الأمر بما يستطيع من مآكل أو مشارب أو أدوية حتى يترك ذلك، وحتى المؤمن يجاهد نفسه ويصبرها على الحق ويمنعها من الباطل ولو تاقت إليه، يقول الله جل وعلا: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ [العنكبوت:69] لا بد من جهاد.\nولا يجوز له العود إلى التدخين أو شرب المسكر أو غيرهما من المعاصي ولو تاقت نفسه إلى ذلك، ولو أصابه شدة فعليه أن يعالج، وعليه أن يجاهد، وعليه أن يصبر ويتحمل ويأتي بما يستطيع من أنواع العلاج الذي يمنعه من الميل إلى هذا الشراب الخبيث الذي هو مضر به في دينه ودنياه، ضرر الدخان عظيم في الدين والدنيا جميعًا، فالواجب الحذر، الواجب على كل مدخن أن يتقي الله، وأن يحذر هذا البلاء وأن يبتعد عنه، وأن يجاهد نفسه، وأن ينصح لإخوانه في تركه، هذا هو الواجب على الجميع، والله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2]، ويقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71].\nفلا بد من جهاد النفس وتصبيرها عن هذا المحرم، وهكذا جميع المعاصي يجب على المؤمن أن يجاهد نفسه، وأن يمنعها مما حرم الله، وأن يصبر على ما يحصل من المشقة حتى تسلو النفس عن ذلك، وحتى يطمئن قلبه، وحتى تكون الأمور عادية بعد الصبر والاحتساب ينتهي كل شيء مما في قلبه، ويجعل الله في قلبه الإيمان والقوة، ومحبة الخير، وكراهة الشر بسبب جهاده لنفسه وصبره.\nفالكفار كانوا عندهم تشبث بالكفر، وتعلق به، والمحاربة دونه، وجلاد بالسلاح؛ فلما شرح الله صدورهم للإسلام تركوا ذلك، وابتعدوا عنه، وجعل الله في قلوبهم المحبة، والإيمان، والهدى، وتركوا ذلك الذي كانوا يقاتلون عنه بالسلاح، نسأل الله السلامة.\nالمقدم: اللهم آمين، أحسن الله إليكم.\nتوصون هذا السائل يا سماحة الشيخ بالإخلاص في الدعاء له أثر قوي؟\nالشيخ: نعم، نوصيه بالدعاء يسأل ربه يقول: اللهم أجرني من هذا البلاء، اللهم اجعل في قلبي وفي نفسي ما يمنعني منه، اللهم اكفني شره، واكفني شر نفسي، اللهم أعذني من الشيطان .... ، يسأل ربه الإعانة والتوفيق، يسأل ربه التوفيق للصبر عن هذا البلاء وعن غيره من المعاصي.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16825/حكم-الرجوع-الى-الدخان-بعد-تركه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77905.mp3","categories":["نصائح وتوجيهات"]},{"id":17824,"question":"عبد الله خليل من المنطقة الشرقية بعث بسؤال يقول: عندي ابن عم يدخن ثم قطع التدخين، وأراد العودة إلى ذلك فأخبرته بأنه لا يحل له العودة إليه؛ لأنه حلف بالله وفي يده القرآن بأن لا يدخن ولكنه مصمم على أن يعود إلى التدخين، ويقول: بأنه لا يستطيع، ماذا عليه أن يفعل؟ جزاكم الله خيرًا.","title":"حكم الرجوع إلى الدخان بعد تركه","answer":"الجواب: الواجب عليه أن يحذر العودة، وأن يتقي الله في ذلك، وأن يعالج الأمر بما يستطيع من مآكل أو مشارب أو أدوية حتى يترك ذلك، وحتى المؤمن يجاهد نفسه ويصبرها على الحق ويمنعها من الباطل ولو تاقت إليه، يقول الله جل وعلا: وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا وَإِنَّ اللَّهَ لَمَعَ الْمُحْسِنِينَ [العنكبوت:69] لا بد من جهاد.\nولا يجوز له العود إلى التدخين أو شرب المسكر أو غيرهما من المعاصي ولو تاقت نفسه إلى ذلك، ولو أصابه شدة فعليه أن يعالج، وعليه أن يجاهد، وعليه أن يصبر ويتحمل ويأتي بما يستطيع من أنواع العلاج الذي يمنعه من الميل إلى هذا الشراب الخبيث الذي هو مضر به في دينه ودنياه، ضرر الدخان عظيم في الدين والدنيا جميعًا، فالواجب الحذر، الواجب على كل مدخن أن يتقي الله، وأن يحذر هذا البلاء وأن يبتعد عنه، وأن يجاهد نفسه، وأن ينصح لإخوانه في تركه، هذا هو الواجب على الجميع، والله سبحانه يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى[المائدة:2]، ويقول: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71].\nفلا بد من جهاد النفس وتصبيرها عن هذا المحرم، وهكذا جميع المعاصي يجب على المؤمن أن يجاهد نفسه، وأن يمنعها مما حرم الله، وأن يصبر على ما يحصل من المشقة حتى تسلو النفس عن ذلك، وحتى يطمئن قلبه، وحتى تكون الأمور عادية بعد الصبر والاحتساب ينتهي كل شيء مما في قلبه، ويجعل الله في قلبه الإيمان والقوة، ومحبة الخير، وكراهة الشر بسبب جهاده لنفسه وصبره.\nفالكفار كانوا عندهم تشبث بالكفر، وتعلق به، والمحاربة دونه، وجلاد بالسلاح؛ فلما شرح الله صدورهم للإسلام تركوا ذلك، وابتعدوا عنه، وجعل الله في قلوبهم المحبة، والإيمان، والهدى، وتركوا ذلك الذي كانوا يقاتلون عنه بالسلاح، نسأل الله السلامة.\nالمقدم: اللهم آمين، أحسن الله إليكم.\nتوصون هذا السائل يا سماحة الشيخ بالإخلاص في الدعاء له أثر قوي؟\nالشيخ: نعم، نوصيه بالدعاء يسأل ربه يقول: اللهم أجرني من هذا البلاء، اللهم اجعل في قلبي وفي نفسي ما يمنعني منه، اللهم اكفني شره، واكفني شر نفسي، اللهم أعذني من الشيطان .... ، يسأل ربه الإعانة والتوفيق، يسأل ربه التوفيق للصبر عن هذا البلاء وعن غيره من المعاصي.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16825/حكم-الرجوع-الى-الدخان-بعد-تركه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77905.mp3","categories":["نصائح وتوجيهات"]},{"id":17887,"question":"هذا الأخ سوداني مقيم بالسعودية تبوك يقول سماحة الشيخ، كتب هذا السؤال يقول: بأنه لديه بنت عمرها ست سنوات وكان يحبها ويغليها، وتوفاها الله  ورحلت من الدنيا -يقول:- إلى دار الآخرة في العام الماضي، يقول: ما زلت أبكي عليها وأندب، وخيالها معي ليلًا ونهارًا، فما حكم بكائي عليها؟ حيث إنني متعلق بها يا سماحة الشيخ؟","title":"حكم البكاء المستمر على الميت","answer":"الجواب: الواجب عليك الصبر، وسؤال الله أن يعوضك خيرًا منها، الله جل وعلا قال: إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ [الزمر:10].. قال جل وعلا: وَبَشِّرِ الصَّابِرِينَ ۝ الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُوْلَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُوْلَئِكَ هُمُ الْمُهْتَدُونَ [البقرة:155-157]، ويقول ﷺ: ما من عبد يصاب بمصيبة يقول: إنا لله وإنا إليه راجعون، اللهم آجرني في مصيبتي وأخلف لي خيرًا منها، إلا آجره الله في مصيبته وأخلف له خيرًا منها. ولما مات أبو سلمة ، قال النبي لـأم سلمة .. أمرها بالصبر والاحتساب، قال: اللهم اغفر لـأبي سلمة، وارفع درجته في المهديين، وافسح له في قبره ونور له فيه، وأمرهم بالصبر والاحتساب. المؤمن يصبر ويحتسب، أما البكاء بدمع عين فقط لا يضر، أما بصوت فلا يجوز، النياحة لا تجوز، أما مجرد دمع العين فلا يضر، لا حرج في ذلك دمع العين من دون صوت.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16899/حكم-البكاء-المستمر-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59816.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":17890,"question":"سماحة الشيخ! يشكو كثير من الآباء والأمهات من عقوق أولادهم هل من توجيه مبارك؟","title":"وجوب بر الوالدين","answer":"الجواب: نعم. يجب على الأولاد أن يبروا والديهم، وأن يتقوا الله، فالعقوق من أقبح الكبائر، ويقول سبحانه: وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا وَبِالْوَالِدَيْنِ إِحْسَانًا[النساء:36]، ويقول جل وعلا: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ[لقمان:14] الله أمر بشكره، وشكر والديه، فالواجب على جميع الأولاد على الذكور والإناث جميعًا أن يبروا والديهم، وأن يحسنوا إلى والديهم، وأن يحذروا العقوق من الكلام السيئ، أو الفعل السيئ، أو النهر أو رفع الصوت، أو مخالفة الأوامر التي يحتاجون إليها وليست معصية، كل هذا واجب عليهم. فعليه أن يبر والديه، وأن يسمع ويطيع لهما في المعروف، وأن يحذر رفع الصوت عليهما أو سبهما، كل هذا منكر، في الحديث الصحيح يقول ﷺ: لعن الله من لعن والديه وفي الحديث الآخر يقول عليه الصلاة والسلام: من الكبائر شتم الرجل والديه، قيل: «يا رسول الله! وهل يسب الرجل والديه؟!» استنكر الناس، استنكروا هذا؟! كيف يسب والديه؟! «وهل يسب الرجل والديه، قال النبي ﷺ: يسب أبا الرجل فيسب أباه، ويسب أمه فيسب أمه يعني: يتعرض .. يتسبب، فإذا كان من تسبب فقد فعل كبيرة فكيف بالذي يباشر ويسب، إذا كان يسب آباء الناس وأمهات الناس فيسب والديه يكون سابًا لوالديه؛ لأنه هو المتسبب، فكيف بالذي يسب والديه ويلعنهم؟ يكون إثمه أعظم.\nويقول النبي ﷺ: ألا أنبئكم بأكبر الكبائر؟ ألا أنبئكم بأكبر الكبائر؟ ألا أنبئكم بأكبر الكبائر؟ - ثلاث مرات يكررها -؟ قالوا: بلى يا رسول الله، قال: الإشراك بالله، وعقوق الوالدين -جعله مع الشرك، قرين الشرك-، وكان متكئًا فجلس فقال: ألا وقول الزور ألا وشهادة الزور. فالواجب الحذر من هذا البلاء العظيم، يجب على الولد أن يتقي الله، وأن يبر والديه، وأن يحسن إليهما، وأن يسمع ويطيع لهما في المعروف، وأن تكون عنايته بالأم أكثر، وبره لها أكثر، ورعايته لها أكثر؛ لأن حقها أعظم، قال رجل: «يا رسول الله! من أبر؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أباك، ثم الأقرب فالأقرب وفي اللفظ الآخر قال: «يا رسول الله! من أحق الناس بحسن الصحبة؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أمك، قال: ثم من؟ قال: أبوك في الدرجة الرابعة. نعم.\nالمقدم: جزاكم الله خيرًا، سماحة الشيخ على هذا التوجيه المبارك.","link":"https://binbaz.org.sa/fatwas/16911/وجوب-بر-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78009.mp3","categories":["نصائح وتوجيهات"]},{"id":17894,"question":"المستمع (ع. ع. م) من المنطقة الجنوبية يسأل ويقول: مشكلتي في علاقتي بالناس فهناك من أرتاح إليهم وأجالسهم وأجد فيهم الصديق والرفيق وأشعر بالارتياح لوجودي معهم وهؤلاء قلة، وهناك قسم آخر ممن أعرف لا أطيق الجلوس معهم ولا التحدث إليهم ولا أرتاح لهم أبدًا، وأجد بأن طبعي لا يوافق طبعهم، وأحيانًا أضطر إلى البقاء معهم والحديث إليهم والتعامل معهم لارتباطي معهم بقرابة أو في عمل أو غير ذلك مما يضطرني للمجاملة معهم.الشيخ: أعد أعد.المقدم: يقول: مشكلتي في علاقتي بالناس فهناك من أرتاح إليهم وأجالسهم وأجد فيهم الصديق والرفيق وأشعر بالارتياح لوجودي معهم وهؤلاء قلة، وهناك قسم آخر ممن أعرف لا أطيق الجلوس معهم ولا التحدث إليهم ولا أرتاح لهم أبدًا، وأجد بأن طبعي لا يوافق طبعهم، وأحيانًا أضطر إلى البقاء معهم والحديث إليهم والتعامل معهم لارتباطي معهم بقرابة أو في عمل أو غير ذلك، مما يضطرني للمجاملة معهم وإظهار البشاشة والارتياح غصبًا عني، وأحس أثناء وجودي معهم أنني بحاجة إلى التكلف في الكلام والمعاملة، وهذا لا أجيده مما يزيدني نفورًا وبعدًا عنهم وعدم ارتياح نحوهم، ولهذا أصبحت أفضل تجنب كل من لا أرتاح إليه بقدر الإمكان، وهذا يؤدي إلى العزلة نوعًا ما، علمًا بأنني في حالة العزلة وبقائي لوحدي أحس بالراحة وأستفيد من وقتي في تلاوة القرآن وقراءة الكتب النافعة؟","title":"الحث على اختيار الأصدقاء الفضلاء","answer":"الجواب: عليك أن تعمل ما هو أصلح لقلبك وأن تختار الأصحاب والجلساء الطيبين، أما الذين تنفر منهم ولا تلائمك طبائعهم ولا تأنس بالجلوس معهم فابتعد عنهم، واختر لنفسك ما هو أصلح ولو بالجلوس في بيتك لقراءة القرآن والتسبيح والتهليل ونحو ذلك، المؤمن يحاسب نفسه ويجاهدها في صحبة الأخيار والبعد عن الأشرار، وفي اختيار الوقت الفاضل والصاحب الفاضل، أنت تجاهد نفسك فيما تراه أصلح لدينك وأسلم لدينك، فتصحب الأخيار، وتستر عليهم حتى تستفيد منهم، وتبتعد عن الأشرار ولو كانوا من الأقارب حتى لا يضرك الجلوس معهم، ولا تحمل نفسك ما لا تطيق.\nأما إن كنت لا ترغب في الجلوس مع الأخيار فهذا مرض في قلبك إذا كانوا طيبين أهل دين جاهد نفسك حتى تبقى معهم وتستفيد منهم، ولو نفرت نفسك منهم لما فيها من مرض المعصية لا تبال بذلك عليك بصحبة الأخيار والصبر عليهم والاستفادة منهم ولو كنت تحس بشيء من الكلفة والشدة؛ لأن صحبة الأخيار لا تأتي إلا بالخير، أما صحبة الأشرار فإنها وسيلة للشر العظيم.\nفالحاصل أنك تحكم الشرع المطهر فيما هو أصلح لقلبك وأنفع لدينك في الجلساء وغير الجلساء فتجلس مع الطيبين ومع الأخيار ومع من تنفعك مجالستهم وتبتعد عما يضرك الجلوس معهم من أقارب أو غيرهم، وبيتك خير لك من الجلوس مع من يضرك، ومن لا تطيق البقاء معه لسوء أفعاله أو سوء أخلاقه أو سوء تصرفه، نسأل الله للجميع التوفيق.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16934/الحث-على-اختيار-الاصدقاء-الفضلاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84610.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق","نصائح وتوجيهات"]},{"id":17904,"question":"رسالة من أحد الإخوة المستمعين يقول: أنا أعمل في المملكة العربية السعودية في بقالة صغيرة الحجم تكسب في اليوم مبلغًا يتراوح بين مائتين أو ثلاثمائة ريال، ولدي زبائن وأنا متزوج ومقيم هنا ولدي طفلة ومصاريف عائلية أخرى لا أستطيع أن أصرف على الوالد أو الوالدة؛ لأن لدي أخوين بالإضافة إلى أسرتي فأحد إخواني الكبار رفض أن يساعدني لمد الأسرة فما هو رأيكم جزاكم الله خيرًا؟الشيخ: أعد. يقول: أنا أعمل في المملكة في بقالة صغيرة الحجم تكسب في اليوم مكسبًا يتراوح بين مائتين أو ثلاثمائة ريال، ولدي زبائن وأنا متزوج ومقيم هنا ولدي طفلة ومصاريف عائلية أخرى لا أستطيع أن أصرف على الوالد أو الوالدة، ولدي أخوان بالإضافة إلى أسرتي لكن أحد إخوتي رفض أن يساعدني في مصاريف الوالدين فما هو توجيهكم لي ولإخوتي؟ جزاكم الله خيرًا.","title":"وجوب النفقة على الوالدين","answer":"الجواب: عليك أن تصرف على الوالدين والأولاد إذا كان الوالدان عاجزين لا يستطيعان الكسب والنفقة على أنفسهما من مالهما فتقسم ما لديك وما تحصل بين الجميع حسب طاقتك بين أولادك وأبويك ونفسك وزوجتك حسب الطاقة، وعلى أخويك أن يساعدا في ذلك، يلزمهما أن يساعدا في نفقة والديهما إذا كانا يستطيعان ذلك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، ونفقة أولادك وأبويك إذا كانا عاجزين عليك وهكذا زوجتك، وعلى أخويك أن يساعدا إذا كانا يستطيعان من مالهما أو من كسبهما وهذا واجب، هذا من بر الوالدين الواجب على الأولاد، ويكون التوزيع على حسب الطاقة، توزيع ما لديك يصنع به الطعام للجميع وتشتري كسوة للجميع حسب طاقتك، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.\nالمقدم: جزاكم الله خيرًا، يسأل عن أخيه الذي لم يساعده في الصرف على الوالدين؟\nالشيخ: إن شاء رفع أمره إلى الحاكم وإن شاء صبر، إن شاء رفعت أمره إلى الحاكم حتى يُلزمه إذا كان يستطيع، أما إذا كان عاجزًا فليس لك العدوان عليه. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16927/وجوب-النفقة-على-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_846/nour_84606.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17911,"question":"الجانب الآخر: بعض الآباء والأمهات قد يستعجلون يا سماحة الشيخ في حالة غضب ويدعون على أولادهم أو يلعنونهم ثم يندمون على ذلك، هل من توجيه للآباء والأمهات؟","title":"حكم اللعن والدعاء على الأبناء","answer":"الجواب:  نعم. لا يجوز للآباء اللعن ولا الأمهات ولا غيرهم، اللعن لا يجوز، هذا منكر، الرسول ﷺ حذر من هذا وأمر العباد أن يحذروا ذلك، فالإنسان إذا لعن أخاه بغير حق أو دعا عليه إذا كان لا يستحق رجعت لعنته عليه، وفي الحديث الصحيح: من قال لأخيه: يا عدو الله؛ وليس كذلك إلا حار عليه وهكذا من سبه أو دعا عليه وليس كذلك ترجع دعوته ولعنته إليه، فالواجب الحذر، ويقول ﷺ: لعن المؤمن كقتله جعل اللعن كالقتل، فالواجب الحذر من السب، والشتم للوالدين وغيرهما، وعلى الوالدين أن يحذرا ذلك، أن يحذرا سب أولادهم، ولعن أولادهم، بل يدعون لهم بالهداية، اللهم اهد فلانًا، اللهم اهد ذريتي، اللهم أصلح ذريتي، اللهم اهد فلانًا، اللهم اهد فلانة، أما السب لا، لا يجوز. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16917/حكم-اللعن-والدعاء-على-الابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78010.mp3","categories":["نصائح وتوجيهات","الأخلاق المذمومة"]},{"id":17942,"question":"هذا سائل يقول يا فضيلة الشيخ: بالنسبة للرجل الذي ليس عنده علم شرعي كيف يطلب العلم الشرعي؟ وما هو المحدد له من هذا العلم الشرعي؟","title":"كيفية طلب العلم الشرعي","answer":"الجواب: يحضر حلقات العلم عند أهل العلم، أو في دور العلم التي فيها دروس معينة في أوقات معينة، يجتهد، وإذا كان ما يستطيع، في حلقات العلم في المساجد، يحضرها ويستفيد ويسأل، ويعتني بالقرآن ويكثر من تلاوته، لعل الله جل وعلا ينفعه بذلك.","link":"https://binbaz.org.sa/fatwas/16946/كيفية-طلب-العلم-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59826.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":17948,"question":"كيف يكون الإصلاح بين الناس فيما ورد من الأحاديث؟","title":"كيفية الإصلاح بين الناس","answer":"الجواب: إذا تنازعا عندك أو ناس تعرفهم؛ تصلح بينهم، من أهلك أو من جيرانك، إذا علمت ذلك واستطعت، تسعى في الصلح بينهم: فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ [الأنفال:1].. وَالصُّلْحُ خَيْرٌ [النساء:128]، وفي الحديث الصحيح: \"أن الرسول ﷺ نهى عن الكذب إلا في ثلاث -من جملة الثلاث:- الإصلاح بين الناس\"، فالإصلاح بينهم توسط بينهم؛ حتى تعود الحالة الطيبة بينهم، ويزول ما بينهم من الهجر والكراهة، تكون أنت مأجور بذلك، فإصلاح ذات البين من أفضل القربات، من جيرانك أو من أقاربك أو من غيرهم.\nالمقدم: جزاكم الله خيرًا، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16950/كيفية-الاصلاح-بين-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59827.mp3","categories":["الآداب والأخلاق المحمودة","نصائح وتوجيهات"]},{"id":17953,"question":"السائل: محمد (ع. خ) يقول: قريب لي عاق لوالديه كثيرًا، فما هو حق الوالدين على الأبناء؟ وهل من كلمة يا سماحة الشيخ لمن لهم هذه الصفة في والديهم أو أحدهما؟","title":"حق الوالدين على أبنائهم","answer":"الجواب: الواجب على الولد بر والديه، والحذر من العقوق، يقول النبي ﷺ: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله وعقوق الوالدين فجعل عقوق الوالدين من أكبر الكبائر، ويقول ﷺ: من الكبائر شتم الرجل والديه! قيل: يا رسول الله! وهل يسب الرجل والديه؟! قال: يسب أبا الرجل فيسب أباه، ويسب أمه فيسب أمه فعقوقهما والسب في ذلك من الكبائر، فالواجب الحذر. والله يقول جل وعلا: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا  ۝  وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23، 24].. يقول جل وعلا: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14]، فالواجب برهما والإحسان إليهما وشكرهما، والحذر من عقوقهما، نسأل الله العافية. نعم.\nالمقدم: اللهم آمين، أحسن الله إليكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16968/حق-الوالدين-على-ابناىهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59832.mp3","categories":["الأطعمة والأشربة","الآداب والأخلاق","نصائح وتوجيهات"]},{"id":17956,"question":"من مصر السائل (م. أ) يقول سماحة الشيخ: أنا شاب أعيش في مجتمع يفضل الزواج المبكر، وتزوجت منذ تخرجي من الدراسة، وكان ذلك برغبة الوالدين دون اقتناع مني، وعشت مع زوجتي ثلاث سنوات كانت كلها دون أي شعور بالمسئولية، وكنت في سن العشرين إلى ثلاثة وعشرين سنة وأنجبت منها طفلين، ثم لم أستطع إكمال المشوار، وقمت بتطليقها، فغضب علي الوالد، وعانيت من ذلك الشدائد والمضايقات، وظللت على هذه الحال حتى رضي عني والدي بعد ثلاث سنوات، وتزوجت من امرأة أخرى، ولكن لم أجد السعادة أيضًا فطلقتها رغبة منها، وتلبية لطلبها، والآن يا سماحة الشيخ أشعر بأنني أخطأت في حق زوجتي الأولى فأخطأت في حقي الثانية وظلمتني، وأشعر بالمعاتبة لنفسي رغم زواج الأولى من رجل آخر، بماذا تنصحونني مأجورين؟","title":"نصيحة لمن طلق زوجته ويشعر بندم","answer":"الجواب: إذا كنت ترى من نفسك الرغبة، وعندك القدرة على العشرة للنساء، وجماع النساء؛ فتزوج ثالثة والحمد لله، واسأل ربك أن يوفق بينك وبين الثالثة، وأن يجعلها صالحة طيبة، والذي مضى مضى لا تعلق بالماضي، عليك بالمستقبل التمس الزوجة الصالحة الطيبة، واخطبها وتزوجها، وأبشر بالخير إن شاء الله، ما دمت عندك الرغبة في الخير، وعليك التوبة من ذنوبك وسيئاتك، واسأل ربك التوفيق والإعانة، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، والحمد لله.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16989/نصيحة-لمن-طلق-زوجته-ويشعر-بندم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78018.mp3","categories":["الطلاق","نصائح وتوجيهات"]},{"id":17958,"question":"هذه السائلة من جدة أختكم رمزت لاسمها بـ (أ. أ. ع) تقول: سماحة الشيخ! هل يحق للمرأة أن تأخذ من مال زوجها دون أن يعلم؟ علمًا بأن زوجها لا يعطيها ما يكفيها، وهي قد تكون محتاجة لذلك المال كي تشتري لها أشياء، لها ولأطفالها، أو تعطي والدتها، علمًا بأن هذا الزوج لا يشتري لها ولأطفالها إلا في عيد الفطر فقط، وعندما يسأل: من أين لك هذا الشيء؟ تقول له: من أمي، أو من أختي، فهل هذا جائز؟","title":"حكم أخذ المرأة من مال زوجها دون علمه","answer":"الجواب: نعم، إذا كان الزوج لا يقوم بالواجب لها أن تأخذ من ماله بالمعروف ما يكفيها وما يكفي أولادها، في الصحيحين عن عائشة رضي الله عنها أن هند بنت عتبة بن ربيعة زوجة أبي سفيان بن حرب، وأبو سفيان من سادات قريش ومن رؤساء قريش، اشتكت على النبي ﷺ بعد الفتح - بعد فتح مكة - اشتكت عليه وقالت: «يا رسول الله! إن أبا سفيان رجل شحيح لا يعطيني ما يكفيني ويكفي بني إلا ما أخذته من ماله بغير علمه فهل لي ذلك؟ فقال ﷺ: خذي من ماله بالمعروف ما يكفيك ويكفي بنيك يعني: ولو لم يعلم خذي من ماله بالمعروف ما هو بالإسراف والتبذير خذي من ماله بالمعروف ما يكفيك ويكفي بنيك. فإذا كان الزوج بخيلًا أو لا يبالي فللزوجة أن تأخذ من ماله بغير علمه ما يكفيها ويكفي أولادها بالمعروف، هذا لا حرج فيه.\nلكن لا تأخذ ما تعطي ... أمها وأباها لا. تأخذ ما يكفيها هي وأولادها وخدمها اللي في البيت بالمعروف، أما أن تأخذ شيئًا تعطيه الناس إلا برضاه إلا الشيء الذي جرت العادة به فضول الطعام، فضول الشراب، الشيء الذي جرت العادة بالصدقة به لا بأس. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17001/حكم-اخذ-المراة-من-مال-زوجها-دون-علمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_780/nour_78019.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":17961,"question":"السائلة تقول: يتساهل كثير من النساء هداهن الله في دخول الصبيان من أقاربهم عليهم، وهؤلاء الصبيان قد بلغوا، فهل نصيحة لمثل من تساهلوا لمثل هؤلاء؟","title":"حكم دخول الأولاد البالغين على النساء","answer":"الجواب: نعم، الواجب على المرأة الحذر، وأن لا يدخل عليها المكلف، بل يجب أن تحذر ذلك، وأن لا تخلو برجل مكلف، وعليها أن تستتر وأن تصون نفسها وتختمر، ولا يجوز لها الخلوة بأجنبي مطلقًا، سواء أخا زوجها أو عم زوجها أو غيرهم، عليها أن تتقي الله وأن تراقب الله، وأن لا يدخل عليها من ليس محرمًا لها، إلا إذا كان معها غيرها ليس بخلوة ولا تهمة. نعم.","link":"https://binbaz.org.sa/fatwas/16975/حكم-دخول-الاولاد-البالغين-على-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59834.mp3","categories":["النظر والخلوة والاختلاط","قضايا المرأة","نصائح وتوجيهات"]},{"id":17984,"question":"من المستمع (س. م. ص) من الأردن سؤال يقول فيه: أنا في الصلاة أعيد الركن أكثر من مرة وذلك نتيجة للنسيان وعدم التركيز والوسوسة فبماذا تنصحونني؟ جزاكم الله خيرًا.","title":"نصيحة لموسوس يعيد ركن الصلاة أكثر من مرة","answer":"الجواب: ننصحك بالحذر من هذا؛ لأن هذا من طاعة الشيطان، فننصحك بالحذر من الوساوس، وأن تتعوذ بالله من الشيطان عند وجودها، وأن لا تعيد الأركان، متى قرأت أجزم على أنك قرأت واترك العودة، ركعت كذلك، سجدت كذلك، وهكذا، لا تطاوع الشيطان بل استمر في صلاتك على أنك فعلت الركن حسب ما في علمك وفي اجتهادك، ولا تطاوع الشيطان في الشك الذي يجعلك تعيد الركن ظنًا منك أنك لم تفعل، وهذا كله من طاعة الشيطان، ولكن استمر على العمل وأنت تجزم أنك فعلت، وترغم الشيطان حتى تكمل. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17002/نصيحة-لموسوس-يعيد-ركن-الصلاة-اكثر-من-مرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_848/nour_84810.mp3","categories":["نصائح وتوجيهات"," الوسواس بأنواعه"]},{"id":18072,"question":"الواقع أختنا سماحة الشيخ تذكر مأساة يشكو منها كثير من الآباء، تلكم هي ما يعرف بين كثير من الشباب بالانقطاع الكلي للفكر، وتمحيص الآراء حتى أن هذا أدى بالأبناء إلى الانقطاع عن آبائهم وببعض البنات أيضًا، لابد لسماحة الشيخ من كلمة وأعتقد أن هذا غزو دخل إلى شبيبة الإسلام.","title":"حكم الابتعاد عن الوالدين بحجة الانقطاع للفكر","answer":"الجواب: لا حول ولا قوة إلا بالله! لاشك أن هذا أمر خطير، والواجب على الشباب أن يتقي الله  وأن يعرف قدر الوالدين، وحق الوالدين، فحقهما عظيم وواجبهما كبير، ولا ينبغي للشباب من الذكور والإناث أن ينقطعوا للوساوس والأفكار المخالفة المنحرفة، بل يجب على المؤمن شابًا أو شيخًا وعلى المؤمنة فتاة أو كبيرة على الجميع أن يحاسبوا أنفسهم، وأن يتقوا الله في أقاربهم وفي والديهم بوجه أخص، وأن يحرصوا على الاستقامة، وأن يحذروا وساوس الشيطان ونزغات الشيطان. والله جل وعلا قال: قُلْ أَعُوذُ بِرَبِّ النَّاسِ ۝ مَلِكِ النَّاسِ ۝ إِلَهِ النَّاسِ ۝ مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ [الناس:1-4] فهو وسواس عند الغفلة خناس عند الذكر. فالواجب على الشباب جميعًا من الذكور والإناث أن يتقوا الله وأن يستقيموا على دينه، وأن يعرفوا قدر الوالدين وقدر الأقارب، وأن يبروا والديهم، وأن يصلوا أرحامهم، ولو فرضنا أن الوالدين كافران لوجب الإحسان إليهما، قال الله جل وعلا في كتابه الكريم في حق الوالدين الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15] وهما كافران عليه أن يحسن إليهما وأن يصحبهما بالمعروف وأن ينصح لهما، وأن يدعوهما إلى الخير، وأن يحسن إليهما بما يستطيع من مال وجاه ودعوة إلى الله  لعل الله يهديهما بأسبابه. فكيف إذا كان الوالدان مسلمين فالأمر أعظم وأكبر، وهكذا الرحم، وصل الرحم من أهم الواجبات وقطيعتها من أقبح الكبائر، يقول عليه الصلاة والسلام: لا يدخل الجنة قاطع رحم ويقول عليه الصلاة والسلام: ألا أنبئكم بأكبر الكبائر؟ قلنا: بلى يا رسول الله! قال: الإشراك بالله ثم قال: وعقوق الوالدين فجعل العقوق من أكبر الكبائر. فالواجب على الجميع من ذكور وإناث أن يعرفوا قدر الوالدين، وأن يعظموا قدر الوالدين، وأن يحسنوا إليهما، ولو جرى منهما بعض الشيء من التقصير في حق الولدين، أو من الكلام الشديد على الولدين أو من الإساءة إليهما فحقهما عظيم. فالواجب الإحسان إليهما والتلطف بهما واستسماحهما وطلب العفو منهما، وتوسيط الناس الطيبين في الإصلاح بين الإنسان وبين والديه إذا كان هناك شيء من الاختلاف بينهما لا ينفر من والديه ولا يبتعد عن والديه، بل يجتهد في إيجاد الصلح وفي إيجاد التقارب بينه وبين الوالدين حتى ولو أساءا إليه ليتحمل ولينظر إلى حقهما العظيم، وليوسط الأخيار من إخوة كبارًا أو أخوالًا أو أعمامًا أو غيرهم حتى يزول الإشكال وحتى يعود الوئام بين الولد ووالديه وبين البنت ووالديها.. هكذا ينبغي، أما الانقطاع والتباعد عن الوالدين والغفلة عنهما فهذا شره عظيم وعاقبته وخيمةن وهو من أعظم العقوق، نسأل الله للجميع الهداية والعافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17107/حكم-الابتعاد-عن-الوالدين-بحجة-الانقطاع-للفكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_902/nour_90207.mp3","categories":["الأخلاق المذمومة","نصائح وتوجيهات","قضايا المرأة"]},{"id":18135,"question":"هذا السائل (خ. م. م) من الكويت، يقول: سماحة الشيخ! نعلم بأن القلب له إقبال وإدبار فكيف يكون ذلك؟ وكيف يحرص المسلم على أن يكون دائمًا في إقبال دائم؟ جزاكم الله خيرًا.","title":"أسباب الإقبال على الله والإعراض عنه","answer":"الجواب: القلب له إقبال وإدبار لا شك، فعند ذكر الله، وتدبر القرآن، وذكر الآخرة، والجنة والنار، والموت يكون له إقبال، وعند معافسة الأزواج، أو الشهوات، أو التجارة؛ قد يغفل، فينبغي له .. ينبغي للمؤمن أن يحرص على أسباب إقباله على الله، بالحرص على قراءة القرآن، والإكثار من ذكر الله، وذكر الآخرة والجنة والنار حتى يستقر القلب متوجهًا إلى الله جل وعلا، راغبًا فيما عنده . وينبغي أن يحذر أسباب الانصراف والانحراف من الملاهي، ومجالسة السفهاء وغير هذا مما يصده عن الخير والحق، ومما يسبب إعراض قلبه. فالمقصود أن مجالسة الأخيار، والإكثار من ذكر الله، والإكثار من قراءة القرآن، والتفكر في الآخرة، والجنة والنار؛ هذا من أسباب الإقبال، والرغبة فيما عند الله، ومن أسباب صلاح القلب، ومن أسباب خشوعه، وإذا أعرض الإنسان عن ذلك، واشتغل بالدنيا وتجارتها، وأهلها بالتحدث معهم، وأهل القيل والقال؛ فهذا من أسباب انحراف القلب. وأشد من هذا المعاصي والمخالفات، والغفلة عن ذكر الله، نسأل الله العافية والسلامة. نعم. المقدم: اللهم آمين، أحسن الله إليكم، وأثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17169/اسباب-الاقبال-على-الله-والاعراض-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78112.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":18148,"question":"سماحة الشيخ! تساهل كثير من الأسر في أبنائهم، وهم الحقيقة صغار، ثم يصعب عليهم في الكبر، هل من توجيه؟","title":"توجيه لمن يتساهل في تربية أبنائه","answer":"الجواب: هذا من المصائب العظيمة، التساهل من المصائب العظيمة، والواجب على الأب والأم والإخوة أن لا يتساهلوا في هذا، بل عليهم أن يجتهدوا في توجيه الأبناء والشباب إلى الصلاة، وإلى كل خير، وتحذيرهم مما حرم الله من السب والشتم والعقوق وغيرها من الفواحش والتدخين، وشرب المسكر وغير هذا من المنكرات. ومن أهم شيء بل أهم شيء بعد الشهادتين الصلاة، فعليهم أن يلزموا أولادهم بالصلاة، ويضربوا من تخلف عنها إذا كان بلغ عشرًا فأكثر، هذا هو الواجب على الآباء والأمهات، والإخوة الكبار مع الصغار، هذا من التعاون على البر والتقوى، وقد قال الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ[التوبة:71]، وقال النبي ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان. والوالد مأمور بأن يؤدب أولاده، بالضرب إذا بلغوا عشرًا فأكثر، حتى يستقيموا حتى يصلوا مع الناس.نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم على هذا التوجيه الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/17188/توجيه-لمن-يتساهل-في-تربية-ابناىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78116.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":18158,"question":"رسالة وصلت إلى البرنامج من الأخ المستمع يوسف مستور حمدان من السودان النيل الأبيض ويعمل حال كتابة رسالته في العراق، أخونا يسأل عن زواج من أسرة جميع أفرادها يشربون الخمر ولا يعلم عن ذلك إلا بعد أن تقدم للخطبة؟","title":"حكم الزواج من أسرة أفرادها يشربون الخمر","answer":"الجواب: هذا ينبني على معرفة حال البنت المخطوبة، إذا كانت على طريقة أهلها فينبغي تركها، أما إذا كانت معروفة بالاستقامة وترك ما عليه أهلها فلا بأس بأخذها، وإذا كان يجهل ذلك فالحيطة له أن لا يتزوج منهم لئلا تكون مثلهم. نعم. المقدم: جزاكم الله خيرًا! أيضًا عن الصلاة سماحة الشيخ يقول: إنهم لا يصلون. الشيخ: كذلك ينظر ويسأل فإن ثبت أنها مستقيمة وأنها قد خالفت أهلها وتصلي ولا تشرب الخمر فلا بأس، لا يضرها وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164]، أما إن كانت مثل أهلها أو لا يدري عنها فينبغي له تجنب ذلك حتى يحتاط لدينه وحتى يسلم من تزوج امرأة غير دينة. نعم. المقدم: جزاكم الله خيرًا، إذًا يلزم الإنسان والحالة هذه أن يسأل عن الأسرة التي يريد... الشيخ: نعم، ينبغي له التبصر وعدم العجلة، يقول ﷺ: تنكح المرأة لأربع: لمالها، ولجمالها، ولحسبها، ولدينها، فاظفر بذات الدين تربت يداك ولا يمكن أن يعرف ذات الدين إلا بالسؤال، سؤال الثقات العارفين بها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17203/حكم-الزواج-من-اسرة-افرادها-يشربون-الخمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90511.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18163,"question":"بماذا تنصحون من يقول: أشهد أن محمدًا يا رسول الله؟ وهل عبارة يا رسول الله صحيحة أم لا؟ وهل توقع الإنسان في الشرك؟ والبعض أيضًا يقولون عليك بالنبي، هل تعتبر حلف؟","title":"نصيحة لمن يقول: أشهد أن محمدًا يا رسول الله","answer":"الجواب: هذا المقام فيه تفصيل، إذا قال المسلم: السلام عليك يا رسول الله، أو عليك السلام يا رسول الله، أو صلى الله عليك يا رسول الله وسلم، أو جزاك الله يا نبينا خيرًا عما قمت به من البلاغ والبيان والنصح للأمة، فهذا ليس بدعاء للرسول ﷺ إنما هو إخبار بالصلاة والسلام عليه، ودعاء له عليه الصلاة والسلام، مثلما نقرأ في التحيات: السلام عليك أيها النبي ورحمة الله وبركاته، تدعو له بالسلامة والرحمة والبركة، تخصه بهذا وتستحضره في قلبك، تقول: السلام عليك يعني: أدعو لك يا رسول الله بالسلامة والرحمة والبركة. وهكذا كما يقول المسلم عند القبور، عند قبره ﷺ أو غيره: السلام عليك يا رسول الله، السلام عليكم يا أهل القبور معناه استحضارهم وأنه يدعو لهم بالسلامة والرحمة والبركة، هذا ليس من الشرك بل هذا جائز ولا شيء فيه. أما إذا قال: يا رسول الله! انصرنا على أعدائنا، يا رسول الله! أنا في جوارك، الغوث الغوث، المدد المدد. أو قال: عليك بالنبي، يعني: ادعه من دون الله واستغث به، هذا أمر بالشرك. أما إذا قال: بالنبي ما أفعل كذا، أو بالرسول ما أزورك أو بالنبي ما أكلمك، هذا يعتبر حلفًا بغير الله، وهو شرك أصغر، كما لو قال: بالأمانة لا أفعل كذا، أو بجاه النبي أو بحرمة النبي أو بحرمة أبيك لا أفعل كذا، أو ما أشبه ذلك؛ هذا كله يسمى حلف بغير الله، والرسول عليه الصلاة والسلام قال: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، وقال عليه الصلاة والسلام: من كان حالفًا فليحلف بالله أو ليصمت، وقال أيضًا عليه الصلاة والسلام: من كان حالفًا فلا يحلف إلا بالله أو ليصمت وقال أيضًا عليه الصلاة والسلام: من حلف بشيء دون الله فقد أشرك في لفظ: فقد أشرك أو كفر كلها أحاديث صحيحة عن النبي عليه الصلاة والسلام. فالواجب على كل مسلم وعلى كل مسلمة أن يحفظ لسانه عما حرم الله عليه من الحلف بغير الله كائنًا من كان، فالحلف يكون بالله وحده . كما يجب أن يصون لسانه عن دعاء غير الله، من الأموات أو الأصنام أو الكواكب أو الأشجار أو الجن فلا يقول: يا سيدي يا رسول الله! أغثني، أو المدد المدد، أو يا ملائكة الله، أو يا معشر الجن أغيثونا انصرونا، أو يا سيدي البدوي أو يا سيدي علي أو الحسين أو فلان أو فلان أو يا سيدي عبد القادر أغثنا أو انصرنا، كل هذا من الشرك بالله، بإجماع أهل العلم والإيمان، أن هذه أمور شركية كما قال الله : وَأَنَّ الْمَسَاجِدَ لِلَّهِ فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] قال : ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُ لا يُحِبُّ الْمُعْتَدِينَ ۝ وَلا تُفْسِدُوا فِي الأَرْضِ بَعْدَ إِصْلاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا [الأعراف:55-56]، قال سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] قال : وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ [البقرة:186]، قال سبحانه: وَلا تَدْعُ مِنْ دُونِ اللَّهِ مَا لا يَنْفَعُكَ وَلا يَضُرُّكَ فَإِنْ فَعَلْتَ فَإِنَّكَ إِذًا مِنَ الظَّالِمِينَ [يونس:106]، وقال : وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117]، فسمى دعاة غير الله كافرين، وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ وَلا يُنَبِّئُكَ مِثْلُ خَبِيرٍ [فاطر:13، 14] يعني: نفسه . فأخبر سبحانه أن المدعوين من دون الله من الأموات وغيرهم لا يسمعون دعاء داعيهم إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ [فاطر:14] ما بين ميت وجماد ومشغول بما أمره الله به، كالملائكة والجن، أو مشغولين بحاجاتهم كالجن -بعض الجن- أو غائبين لا يسمعون ليسوا عند الداعي ولا يسمعون دعاءه. ثم بين سبحانه أنه لو سمعوا: لو كانوا حاضرين، لم يستجيبوا لم يقدروا على طلبات الطالبين؛ كلهم مربوبون مخلوقون أمرهم بيد الله ، إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ [فاطر:14] ثم قال: وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] هؤلاء المدعوون من دون الله من الأموات والجمادات والأصنام والأشجار والأحجار والملائكة والجن كلهم يوم القيامة يكفرون بشرك المشرك، ويتبرءون منه. فالواجب على جميع المسلمين بل على جميع المكلفين في جميع الأرض الواجب عليهم أن يعبدوا الله وحده ويدعوه وحده  وأن يتبعوا رسوله محمدًا عليه الصلاة والسلام فيما جاء به؛ لأنهم خلقوا لهذا، يقول سبحانه: وَمَا خَلَقْتُ الْجِنَّ وَالإِنسَ إِلَّا لِيَعْبُدُونِ [الذاريات:56] وأمرهم بهذا فقال سبحانه: يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ [البقرة:21]، وقال سبحانه: وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5]. فليس لأحد أن يدعو غير الله من الجن أو الملائكة أو الأموات أو الأصنام أو الكواكب أو غير ذلك، بل يجب أن تكون الدعوة لله وحده، والعبادة لله وحده، كما قال سبحانه: فَاعْبُدِ اللَّهَ مُخْلِصًا لَهُ الدِّينَ [الزمر:2]، وقال : وَاعْبُدُوا اللَّهَ وَلا تُشْرِكُوا بِهِ شَيْئًا [النساء:36]. لكن يجوز دعاء الحي الحاضر القادر فيما يقدر عليه سواء كان هذا مشافهة أو من طريق المكاتبة أو من طريق الإبراق، أو من طريق الهاتف.. أو نحو ذلك من الاتصالات الجديدة التي تمكن الإنسان من الاتصال بمن يريد مشافهة في طلب الحاجة التي يريد كأن يقول: يا أخي فلان! أقرضني كذا وكذا، أو أعني على تعمير بيتي أو على إصلاح سيارتي؛ يخاطبه هذا لا بأس به كما قال الله : فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] في قصة موسى فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15] .... موسى حاضر قادر على أن يغيث هذا الإسرائيلي. وكما قال سبحانه: فَخَرَجَ مِنْهَا خَائِفًا يَتَرَقَّبُ [القصص:21] يعني: خرج موسى من مصر خائفًا يترقب، خائف من شر فرعون، خوف الإنسان من اللصوص حتى يغلق بابه ويتحرز من شرهم، أو من قطاع الطريق حتى يحمل السلاح، هذا جائز لا بأس به؛ لأنه خوف في محله من المؤذيات طبعًا أو المؤذيات بما يستطيعون كإيذاء الظالم وإيذاء السارق، وإيذاء المتعدي عليك، فتحرزوا من شر الناس حتى لا يتعدوا عليك، أو من شر السباع، أو من شر الحيات ونحوها أو اللصوص، كل هذا مما شرع الله التحرز منه، وهو جائز شرعًا وعقلًا. كذلك اقتراضك ممن يسمع كلامك تقول: أقرضني كذا وكذا فلوس أو طعام لحاجتك ثم ترد عليه ما أقرضك إياه هذا جائز من المسلمين ليس فيه شيء، مثلما سمعت في قوله تعالى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]، وهذا جائز بين المسلمين سواءً كان ذلك مشافهة للشخص الحاضر، أو بواسطة الاتصالات المعروفة من هاتف وكتابة وغير ذلك. وإنما الشرك أن تدعو ميتًا أو غائبًا بغير الاتصالات المعروفة، بل تعتقد فيه السر وأنه يسمع كلامك وينفعك وإن غاب عنك، وإن كان ليس بينك وبينه اتصال حسي معروف لا من طريق الكتابة، ولا من طريق الهاتف، ولا من طريق التلكس مثلًا بل تعتقد أن له سرًا كما يعتقد عباد القبور وعباد الأوثان والأصنام هذا هو الشرك الأكبر، وهذا الذي منعه الله ورسوله. أما الأشياء العادية بين الناس في تعاونهم بينهم فالله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] ويقول سبحانه: والله في عون العبد ما كان العبد في عون أخيه، ويقول ﷺ: من كان في حاجة أخيه كان الله في حاجته، فالرسول ﷺ وضح لنا أن التعاون مطلوب كما وضحه الله في قوله : وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2]، والنبي ﷺ وضح ذلك أيضًا فيما تقدم من الحديث: والله في عون العبد ما كان العبد في عون أخيه، من كان في حاجة أخيه كان الله في حاجته. فالتعاون بين المسلمين جائز بشرط أن يكون ذلك مع حاضرين يسمعون أو بالوسائل المعروفة التي توصل كلامك ومرادك كتابة أو إبراقًا أو من طريق الهاتف.. ونحو ذلك. أما دعاء الأموات ودعاء الأصنام ودعاء الغائبين باعتقاد السر فيهم، كدعاء الملائكة أو دعاء الجن فهذا هو الذي نص عليه أهل العلم وبينوا أنه شرك وضلال كما دل عليه كتاب الله ودلت عليه سنة رسول الله عليه الصلاة والسلام، والله ولي التوفيق. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17208/نصيحة-لمن-يقول-اشهد-ان-محمدا-يا-رسول-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_854/nour_85401.mp3","categories":["مسائل متفرقة في العقيدة","نصائح وتوجيهات"]},{"id":18239,"question":"هنالك طرق كثيرة جدًا، مثل الطريقة البرهانية، والطريقة الشاذلية، والطريقة الدسوقية، والطريقة التجانية، إلى آخر هذه الطرق، ومن بينها جماعة أنصار السنة المحمدية وهي جماعة التوحيد، التي تقتدي بسنة المصطفى، أرجو من سماحة الشيخ أن يتفضل بنصيحة مطولة إلى مشايخ وأعوان هذه الطرق، لكي يسيروا في درب المصطفى ﷺ كما جاء في حديث الرسول ﷺ: ستفترق أمتي إلى ثلاث وسبعين فرقة كلها في النار إلا واحدة.","title":"نصيحة للطرق الصوفية باتباع الكتاب والسنة","answer":"الجواب: الطرق الصوفية كثيرة لا تحصى، وهي تزيد على طول الزمان وأكثرها فيه من الشر والفساد والبدع ما لا يحصيه إلا الله  وكل طريقة فيها قسط من الباطل، وقسط من البدع، لكنها متفاوتة بعضها أشر من بعض، وبعضها أخبث من بعض، والواجب على جميع المتصوفة أن يرجعوا إلى الله وأن يتبعوا طريق محمد عليه الصلاة والسلام، وأن يأخذوا بما جاء في الكتاب والسنة، ويسيروا على نهج سلف الأمة من أصحاب النبي ﷺ وأتباعهم بإحسان بطاعة الأوامر وترك النواهي والوقوف عند حدود الله، وعدم إحداث أشياء ما شرعها الله. ليس لهم أن يوجدوا طرقًا يتعبدون بها لم يفعلها الرسول ﷺ ولا أصحابه، بل يجب أن يحاسبوا أنفسهم وأن يدعوا كل ما خالف الشرع المطهر من طقوسهم وأذكارهم الاجتماعية وغير هذا مما أحدثوه في الدين سواء كانوا من القدامى في القرن الثالث والرابع أو من المحدثين. الواجب على جميع المسلمين أن يلتزموا الطريق الذي بعث الله به نبيه عليه الصلاة والسلام وهو توحيد الله والإخلاص له، وطاعة الأوامر وترك النواهي ظاهرًا وباطنًا وأن يلتزموا بذلك، وأن يحذروا البدع والخرافات التي أحدثها الناس، فقد قال عليه الصلاة والسلام في الحديث الصحيح: من عمل عملًا ليس عليه أمرنا فهو رد، وقال في خطبة يوم الجمعة: إن خير الحديث كتاب الله، وإن خير الهدي هدي محمد ﷺ وشر الأمور محدثاتها، وكل بدعة ضلالة، سواء كانت الطرق التي أحدثها الناس قديمة أو جديدة الواجب تركها، واعتناق الطريق الذي سلكه المسلمون في عهده ﷺ إلى يومنا هذا، وهو اتباع الكتاب والسنة والاستقامة على دين الله كما جاء عن الله وعن رسوله من غير زيادة ولا نقصان. وأما إحداث طقوس أو طرائق جديدة لم يفعلها الرسول ﷺ ولا أصحابه هذا لا يجوز، هذا هو اللي يسمى البدعة. وأنصار السنة من خيرة الناس في مصر وفي السودان، أنصار السنة هم الذين يدعون إلى التمسك بكتاب الله وسنة الرسول عليه الصلاة والسلام وليسوا من الفرق الضالة، بل هم من فرقة اتباع الكتاب والسنة، ولهذا قال عليه الصلاة والسلام في الفرق: ستفترق أمتي على ثلاث وسبعين فرقة كلها في النار إلا واحدة، قيل: من هي يا رسول الله؟ قال: الجماعة، يعني: الذين اجتمعوا على الحق وساروا على نهج النبي ﷺ، وهم الصحابة ومن سلك سبيلهم، وفي رواية أخرى: هم من كان على ما أنا عليه وأصحابي، يعني: هم الذين تمسكوا بطريق النبي ﷺ وطريق أصحابه وساروا عليه. فالواجب على المسلمين أن يلزموا هذا الطريق وهو طريق النبي ﷺ باتباع الأوامر وترك النواهي، وعدم إحداث أي شيء من الحوادث لا في الأذكار ولا في الصلوات ولا في الصوم ولا في غير ذلك، بل يجب السير على ما سار عليه الصحابة  وأتباعهم بإحسان، هذا هو الحق. ولما تفرق الناس كثرت بينهم البدع والأهواء، وكل اخترع لنفسه طريقة من كيسه لم يشرعها الله له، ولهذا تعددت الطرق حتى وصلت إلى ثنتين وسبعين فرقة غير الفرقة الناجية، ومنهم الجهمية والمعتزلة والروافض وجماعات أخرى كثيرة كلها داخلة في هذه الفرق الضالة، فيجب على المؤمن أن يحذر كل بدعة أحدثها الناس، وأن يلزم طريق النبي ﷺ وطريق أصحابه وما سار عليه الصحابة  وأرضاهم وأتباعهم بإحسان بطاعة الأوامر وترك النواهي والوقوف عند حدود الله وعدم إحداث شيء ليس له أصل في الشرع، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17286/نصيحة-للطرق-الصوفية-باتباع-الكتاب-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_908/nour_90805.mp3","categories":["مسائل متفرقة في العقيدة","نصائح وتوجيهات"]},{"id":18323,"question":"هذه الأخت تقول: يا سماحة الشيخ! بأن لي زوجة أب لا تخاف الله فينا وتثير أبي دومًا علينا، ونحن دائمًا في شجار معها، فهل آثم في مقاطعتها وعدم السلام عليها؟ ونريد من سماحة الشيخ عبد العزيز توجيه كلمة بهذه المناسبة.","title":"ما حكم هجر زوجة الأب؟","answer":"الجواب: الواجب نصيحتها، وإخبار الوالد ينصحها وألا تقاطعوها، عليكم بالكلام الطيب والصبر ونصيحتها، وطلب الوالد أن ينصحها ويوجهها حتى لا يكون بينكم قطاعة أو خلاف، الوالد ينصحها ويوجهها إلى الخير، وأنتم كذلك عليكم الصبر والكلام الطيب معها، حتى لا يكون في البيت شحناء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17376/ما-حكم-هجر-زوجة-الاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91312.mp3","categories":["نصائح وتوجيهات"]},{"id":18334,"question":"هذه رسالة وصلتنا من الأردن من السائل جاهد ذيب يقول: بماذا ينصح سماحة الشيخ طالب العلم أن يبدأ هل يبدأ -يقول- في المرحلة الأولى والثانية والثالثة في متون الفقه وأصول الفقه، ومصطلح الحديث، وفقه الحديث، والعقيدة، والنحو، والتفسير، بماذا يبدأ طالب العلم في هذه المرحلة؟","title":"نصيحة لطالب علم مبتدئ","answer":"الجواب: يبدأ بالقرآن، يجتهد في القرآن يبدأ، ثم كتب العقيدة، مثل: العقيدة الواسطية يحفظها، كتاب التوحيد للشيخ محمد بن عبدالوهاب، مثل كشف الشبهات، ثلاثة الأصول، يحفظ هذه الكتب المختصرة في العقيدة. ثم كتب الحديث؛ كبلوغ المرام، عمدة الحديث، الأربعين النووية، تتمتها لابن رجب؛ كتب جيدة، ثم الفقه. نعم. المقدم: أحسن الله إليكم وبارك فيكم، بالنسبة يا فضيلة الشيخ للنحو والتفسير يقول؟ الشيخ: ..... بأصول الفقه ومصطلح الحديث والنحو كل هذا طيب، لكن بعد العناية بالقرآن والعناية بكتب العقيدة وكتب الحديث، أما مصطلح الحديث يقرأ مصطلح الحديث مع الحديث، وأصول الفقه مع الفقه، والنحو كذلك يتعلم النحو؛ لأنه يعينه على طلب العلم.","link":"https://binbaz.org.sa/fatwas/17387/نصيحة-لطالب-علم-مبتدى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91317.mp3","categories":["العالم والمتعلم","نصائح وتوجيهات"]},{"id":18377,"question":"سماحة الشيخ! حفظكم الله المرأة المسلمة مستهدفة من أعدائها هل من كلمة توجيهية للأخوات المسلمات؟","title":"كلمة توجيهية إلى النساء","answer":"الجواب: نعم. نوصي أخواتنا المسلمات جميعًا بتقوى الله، والتعاون على البر والتقوى، والحشمة والحجاب، وعدم التبذل وعدم إظهار المحاسن، هذا الواجب على جميع المسلمات، التحفظ والحرص على العفة، والبعد عن أسباب الفتنة كما قال الله جل وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى وَأَقِمْنَ الصَّلاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُ[الأحزاب:33]. وقال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] وقال تعالى: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ[الأحزاب:59]، وقال ﷺ: أيما امرأة أصابت بخورًا فلا تشهد معنا العشاء. فالواجب على النساء التستر، والتحجب، وعدم لبس اللباس الفاتن، أو الطيب الذي يظهر للرجال في الأسواق، كل هذا يجب الحذر منه، بل تكون في ملابس غير فاتنة، وتكون مستورة، وليست متطيبة عند خروجها للسوق، كل هذا مما يلزم المرأة بعدًا عن الفتنة، وحرصًا على أسباب السلامة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17448/كلمة-توجيهية-الى-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78405.mp3","categories":["قضايا المرأة","نصائح وتوجيهات"]},{"id":18379,"question":"سماحة الشيخ! حفظكم الله المرأة المسلمة مستهدفة من أعدائها هل من كلمة توجيهية للأخوات المسلمات؟","title":"كلمة توجيهية إلى النساء","answer":"الجواب: نعم. نوصي أخواتنا المسلمات جميعًا بتقوى الله، والتعاون على البر والتقوى، والحشمة والحجاب، وعدم التبذل وعدم إظهار المحاسن، هذا الواجب على جميع المسلمات، التحفظ والحرص على العفة، والبعد عن أسباب الفتنة كما قال الله جل وعلا: وَقَرْنَ فِي بُيُوتِكُنَّ وَلا تَبَرَّجْنَ تَبَرُّجَ الْجَاهِلِيَّةِ الأُولَى وَأَقِمْنَ الصَّلاةَ وَآتِينَ الزَّكَاةَ وَأَطِعْنَ اللَّهَ وَرَسُولَهُ[الأحزاب:33]. وقال سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ[الأحزاب:53] وقال تعالى: يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلا يُؤْذَيْنَ[الأحزاب:59]، وقال ﷺ: أيما امرأة أصابت بخورًا فلا تشهد معنا العشاء. فالواجب على النساء التستر، والتحجب، وعدم لبس اللباس الفاتن، أو الطيب الذي يظهر للرجال في الأسواق، كل هذا يجب الحذر منه، بل تكون في ملابس غير فاتنة، وتكون مستورة، وليست متطيبة عند خروجها للسوق، كل هذا مما يلزم المرأة بعدًا عن الفتنة، وحرصًا على أسباب السلامة. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17448/كلمة-توجيهية-الى-النساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78405.mp3","categories":["قضايا المرأة","نصائح وتوجيهات"]},{"id":18514,"question":"سؤالها الأخير أم بلال من اليمن تقول: لدي سؤال أنني زوجت أختي، أو بمعنى أصح: كنت واسطة في زواجها في بيت كثر فيه الفساد، وقد كانت أختي تعلم ذلك قبل زواجها بهذا الأمر، وحتى الآن هي مقتنعة بذلك، ولكن ضميري يؤنبني على ذلك، فهل أنا آثمة في توسطي لهذا الزواج لأختي؟أفيدونا سماحة الشيخ.","title":"أعانت على تزويج أختها لأهل بيت كثر فيه الفساد","answer":"الجواب: الواجب على المؤمن أن ينصح لأخيه في الله وأخته في الله ولأخيه في النسب وأخته في النسب، وأن يتقي الله في ذلك، فإذا كنت توسطت في زواجها بإنسان يضرها في دينها، فهذا غلط منك عليك التوبة إلى الله. وأما إذا كنت توسطت لأنك ترين أنه مناسب، ولا حرج فيه، ولكن جاء الفساد بعد ذلك، فلا يضرك، الواجب على الناصح أن يتقي الله، وأن لا ينصح، وأن لا يشير إلا بالشيء الذي يبرئ الذمة، وليس فيه محذور شرعًا، وليس لك أن تشيري بزوج غير مستقيم؛ لأنه يضر الزوجة، فإذا كان هذا الزوج غير مستقيم، وأنت تعلمين أنه غير مستقيم، فقد أخطأت، وعليك التوبة إلى الله ، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17609/اعانت-على-تزويج-اختها-لاهل-بيت-كثر-فيه-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78611.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18565,"question":"هذه الأخت: (ش. ع) من جدة أرسلت بمجموعة من الأسئلة تقول: سماحة الشيخ! كيف أدعو للأشخاص إذا اغتبت مجموعة كبيرة من الناس؟ هل أدعو لهم بالجمع بصيغة الجمع، كأن أقول: اللهم اغفر لهم وارحمهم، أم لا بد من الدعاء لكل واحد منهم باسمه؟","title":"التحذير من الغيبة وما يجب على من اغتاب إنسانًا","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالأمر واسع، إن دعوت لهم بالجمع فلا بأس، أو بالإفراد فلا بأس، والواجب الحذر من الغيبة، الواجب الحذر، وهي ذكرك أخاك بما يكره، كأن يقول فيه: بخيل، سيئ الخلق، كذا كذا، هذا الغيبة، والله يقول: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12]. فإذا اغتاب الإنسان جماعة زيد وعمرو وخالد يقول: اللهم اغفر لهم، اللهم اغفر لهم، اللهم اعف عنهم، ويذكرهم بمحاسن أعمالهم في المواضع التي ذكرهم فيها بسيئ أعمالهم، حتى تكون هذه بهذه يذكرهم بالأعمال الطيبة التي يعرفها منهم في الأماكن التي اغتابهم فيها حتى تكون هذه بهذه، وإذا تيسر استحلالهم طلبهم العفو فهو أكمل. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17679/التحذير-من-الغيبة-وما-يجب-على-من-اغتاب-انسانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91801.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":18591,"question":"سؤاله الثالث في هذه الحلقة، يسأل سماحة الشيخ ويقول: ظهرت في زماننا هذا ظاهرة الهوس الرياضي والأمراض الرياضية بأنواعها المختلفة، وبصورة لهت كثيرًا من المسلمين شيبًا وشبابًا عن التمسك بالأصالة الإسلامية، وبالخلق الإسلامي القويم، فالرياضة الكروية بالذات -وعلى أنواعها- هي حديث المستيقظ والنائم في أحلامه، فنحن نجد الدور التي شيدت لها والأجهزة المختلفة التي ترعاها، وجمعت لها الأموال، وكرم الرياضيون الذين بذلوا الجهد في النهوض بالرياضة، وترقية الأداء كما يقولون، فالناس في تشجيعهم فرقًا وطوائف، فهذا يشجع فريق كذا، وهذا يشجع فريق كذا، وهكذا وهكذا، حتى في أفراد الأسرة الواحدة، وفي التشجيع والانتماء إلى الفرق حساسيات وكراهية وتفرقة، وقلوب مليئة بالحقد، وآراء لا تلتقي حول نقطة واحدة، ولا طائل من وراء ذلك أبدًا، وأسئلتي تدور حول ما يلي:ماذا عن كل ما ذكرت؟ ماذا عن الذين يدفعون نقودهم لمشاهدات المباريات الرياضية؟ وما الحكم على أولئك الذين اتخذوا الرياضة مصدر رزق لهم: كالحكام والمدربين واللاعبين، ثم تخصيص جزء من دخول المباريات لتشييد مسجد، هل يعتبر عملًا من أعمال الخير؟وما هي نصيحتكم لأولئك الفتيات الكاسيات العاريات اللائي يمارسن أنواعًا مختلفة من الرياضة وسط جمهور المشاهدين، وهن بزيهن الرياضي المحزق -فيما يبدو- أرجو من سماحتكم أن تتفضلوا بمعالجة هذه الأمور، جزاكم الله خيرًا.","title":"نصيحة حول انشغال الناس بمنافسات الرياضة","answer":"الجواب: لا شك أن هذا الأمر من المصائب العظيمة التي بلي بها الناس، وصار لهم فيها اهتمام كبير، وعناية عظيمة، وربما ترتب على ذلك إحن وأحقاد وخصومات كثيرة، كما أشار السائل، وربما ترتب على ذلك إضاعة الصلوات، وظهور كثير من العورات، وفساد كبير في المجتمع، فإلى الله المشتكى . ونصيحتي لهؤلاء الذين أشرت إليهم -وهم اللاعبون- نصيحتي لهم أن يتقوا الله، وأن لا تشغلهم هذه الرياضة عما أوجب الله، وأن لا تجرهم إلى الشحناء والعداوة والخصومات، فمن لعبها من غير أن تشغله عن صلاة، ولا عن واجب، ولا أن تجره إلى الشحناء، مع إخوانه والفتن، ولا أن تجره إلى ظهور العورة، أو الاختلاط بالنساء؛ هذا لا حرج فيه في الأصل؛ لأنه لعبة ليس فيها حرج إذا سلمت من هذه الشرور، ولا يكون فيها مال. أما إذا كانت تجر إلى إضاعة الصلوات كما هو الغالب، وإلى ظهور العورات، وإلى مساعدات مالية؛ هذا كله حرام، وكله منكر، وكله لا يجوز، بل يجب القضاء عليه، ويجب على ولاة الأمور منعه، سدًا لباب الفتن، وحماية للقلوب من الفساد، وحماية للعورات، وإعانة لهؤلاء على أداء الصلوات، والمحافظة على الأخلاق الفاضلة، والبعد عن ظهور العورات التي حرم الله ظهورها، وأشد من ذلك وأخبث ما يقع من النساء، كذلك لا يجوز لا بين الرجال -فيما يقع من الاختلاط- ولا فيما يقع منهن من إظهار الزينة والفتنة والتبرج، ولا فيما يقع من أخذ الأموال في ذلك، كل ذلك منكرات يزيد بعضها بعضًا في الشر والفساد. ولا شك أن هذا نشأ عن ضعف الدين، وقلة العلم، وكثرة الفراغ الذي لا يجدون ما يسدون به فراغهم؛ فلهذا شغلوا بهذه الرياضة وأشباهها عما ينفهم في الدين والدنيا، وشغلوا بها عن التفكير في المصالح العامة، وعما ينفع مجتمعهم في دينه ودنياه، حتى وقع ما وقع من الشرور التي بلي بها الكثير منهم؛ فنسأل الله أن يهديهم ويوفقهم، وأن يصلح أحوال المسلمين جميعًا، وأن يوفقهم لما ينفعهم في الدنيا والآخرة، ولما يشغل أوقاتهم بما يرضيه، ويصلح أحوال القلوب والأعمال، وأن يعيذهم من هذه الرياضات الضارة التي تضرهم، وتضر مجتمعهم في دينه ودنياه، ونسأل الله السلامة والعافية من كل سوء. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17727/نصيحة-حول-انشغال-الناس-بمنافسات-الرياضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_871/nour_87103.mp3","categories":["نصائح وتوجيهات"]},{"id":18594,"question":"تقول في آخر أسئلتها: إذا كان مال الزوج يدخل فيه الحرام من رشوة وغيرها، هل تستجاب دعوة الزوجة؟ وهل لها علاقة بدعوة الزوج؟","title":"حكم دعاء المرأة التي يطعمها زوجها من حرام","answer":"الجواب: نرجو أن لا يكون لها علاقة، الإثم عليه هو، لكن المال إذا عرفت أنه رشوة أو أنه حرام لا تأخذه لا تستعمله، تستعمل بقية الأموال التي تدخل عليه من طريق الإباحة، أما إذا علمت أن هذه الدراهم التي سلمها لها جاءته رشوة أو من طريق الربا لا تستعملها، نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17699/حكم-دعاء-المراة-التي-يطعمها-زوجها-من-حرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91812.mp3","categories":["الأدعية والأذكار","قضايا المرأة","نصائح وتوجيهات"]},{"id":18613,"question":"سماحة الشيخ: ما رأيكم فيمن تقدم لها أكثر من خاطب؟","title":"معيار قبول الخاطب وبيان عيوب المخطوبة","answer":"الجواب: عليها أن تختار الأتقى لله، من بلغ عنه أنه أتقى لله، وأحسن دينًا، وأكمل دينًا تختاره، وتبين له حالها؛ لأن الرسول ﷺ قال: من غشنا فليس منا تبين له حالها أن معها عرجة قليلة، أو غيره، إن كانت عندها عيوب أخرى تبين له حالها، تبين حالها، لا تغشه: من غشنا فليس منا وعليها أن تختار الطيب من الخاطبين، الطيب في دينه من الخاطبين، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17720/معيار-قبول-الخاطب-وبيان-عيوب-المخطوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91820.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18640,"question":"السائل( مصطفى .ش.أ) جمهورية مصر العربية محافظة المنيا يقول: لي أخ متزوج منذ أربع سنوات، ولم يرزق بأبناء، فقال له البعض من الناس بأن هناك عمل للجان، أو بأن هذا من عمل الجان، وقال الآخرون: بأنه سحر، وما شابه ذلك، فأرجو من سماحتكم التوضيح بالتفصيل: ما هو العمل في تلك الحالة؟ علمًا بأن تلك المشكلة معقدة، وتمثل شيئًا بالنسبة لأخي وأمي ولي أيضًا، جزاكم الله خيرًا سماحة الشيخ.","title":"توجيه من لم يرزق بالأبناء","answer":"الجواب: الله  بيَّن الأمر، قال -جل وعلا-: يَهَبُ لِمَنْ يَشَاءُ إِنَاثًا وَيَهَبُ لِمَنْ يَشَاءُ الذُّكُورَ ۝ أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَاثًا وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا[الشورى:49-50] فالناس أربعة أقسام: واحد يعطى ذكورًا، واحد يعطى إناثًا، واحد يعطى ذكورًا وإناثًا، وواحد لا يولد له شيء، يكون عقيمًا، ما كتب الله له الذرية. فإذا أحب أن يعرض نفسه على الأطباء المختصين لعل هناك مانعًا يعالج فلا بأس، فإذا لم يتيسر العلاج، فالحمد لله. أما إتيان السحرة والكهان فلا يجوز، لا يجوز سؤالهم ولا إتيانهم لا الكهان ولا السحرة ولا العرافون، إنما الأطباء الخاصون الذين يتعاطون الطب والجراحات، ويتعاطون أسباب العقم ما هي حتى يدرسوها، فإذا وجد من يعالجه من جهة موانع منعت من الحمل غير العقم، يعني: اتضح للطبيب أشياء قد منعت الحمل وعالجها فلا بأس. أما العقيم فلا حيلة فيه، من كتب الله أنه عقيم فلا حيلة فيه، لكن قد يكون هناك أسباب منعت الحمل، فتعالج من جهة الأطباء المختصين. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17757/توجيه-من-لم-يرزق-بالابناء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78719.mp3","categories":["الطب والتداوي","نصائح وتوجيهات"]},{"id":18706,"question":"رسالة وصلت إلى البرنامج من الأخ يحيى السيد عبد الهادي المدني، طالب في معهد التربية الفنية بالرياض له عدد من المسائل، فيسأل في إحدى مسائله ويقول: هل يستطيع الإنسان أن يحافظ على التوازن في هذه الحياة؟","title":"كيفية الحفاظ على التوازن في هذه الحياة","answer":"الجواب: نعم، يستطيع بتوفيق الله، يستطيع بتوفيق الله أن يحفظ نفسه، ويجاهدها حتى يستقيم على طاعة الله، وترك محارمه، والوقوف عند حدوده، وحتى يصحب الأخيار، ويبتعد عن الأشرار، وهذا بتوفيق الله، يسأل الله ويستعين به، ومتى صدق مع الله أعانه الله: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3]، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فمن استقام على التقوى، وجاهد نفسه في الله، وحافظ على ما أوجب الله عليه، وابتعد عما حرم الله عليه، ووقف عند الحدود، وبادر بالتوبة مما قد تزل به قدمه من السيئات، فالله  يعينه ويوفقه، ويكون بذلك متزنًا مستقيمًا، وقد يرتفع أمره بسبب جهاده الصادق، وأعماله الصالحة، حتى يكون من السابقين المقربين. المقدم: الله المستعان. الشيخ: الله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/17812/كيفية-الحفاظ-على-التوازن-في-هذه-الحياة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_920/nour_92009.mp3","categories":["الرقائق","نصائح وتوجيهات"]},{"id":18774,"question":"هذا سائل للبرنامج أرسل بهذه الرسالة، وضمنها مجموعة من الأسئلة، محمد الطيب سوداني، يقول في هذا  ما حكم الذي يحلف بالطلاق في البيع والشراء، وهو يعلم بأنه كاذب ليروج سلعته؟وجزاكم الله خيرًا.","title":"حكم ترويج السلع بالأيمان الكاذبة","answer":"الجواب: حكمه أنه مجرم ظالم لنفسه عاصٍ، سواءً حلف بالطلاق، أو باليمين بالله، أو بغير ذلك، وهو كاذب قد خان الأمانة، فالواجب عليه التوبة إلى الله من ذلك، فالكذب محرم في البيع والشراء، وإن لم يطلق، وإن لم يحلف، فإذا أكد بالحلف والطلاق صار أشد في الإثم، نعوذ بالله. فالواجب عليه التوبة إلى الله من ذلك، والحذر من العود إلى هذا، يقول النبي ﷺ في البيعان: إن صدقا وبينا بورك لهما في بيعهما، وإن كتما وكذبا محقت بركة بيعهما ويقول ﷺ: ثلاث لا يكلمهم الله، ولا ينظر إليهم يوم القيامة، ولا يزكيهم، ولهم عذاب أليم -وذكر منهم- الرجل يبيع السلعة بعد العصر، ويقول: أعطي بها كذا وكذا، وهو كاذب نسأل الله العافية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17902/حكم-ترويج-السلع-بالايمان-الكاذبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79108.mp3","categories":["الأيمان والنذور","البيوع","نصائح وتوجيهات"]},{"id":18793,"question":"ما حكم خلع الحجاب أمام الخطيب؟","title":"حكم خلع المخطوبة حجابها أمام الخاطب","answer":"الجواب: لا حرج في ذلك؛ لأن الرسول ﷺ أمر الخطيب أن ينظر إلى المخطوبة، وأخبر أن ذلك أقرب إلى أن يؤدم بينهما، فإذا طلب النظر إليها فلا حرج أن ينظر إليها، وأن تخلع الحجاب حتى يرى وجهها ورأسها، كل هذا لا بأس به، لكن لا يكون عن خلوة، بل يكون عندها غيرها كأمها وأخيها، ونحو ذلك، حتى لا يحصل خلوة، ينظر إليها من دون خلوة، نعم.","link":"https://binbaz.org.sa/fatwas/17915/حكم-خلع-المخطوبة-حجابها-امام-الخاطب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90608.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18834,"question":"هذه فتاة رمزت لاسمها (مريم . أ. أ) تقول: فتاة ملتزمة تقدم لها رجل لخطبتها، وهو يصلي؛ لكنه يشرب الشيشة، وهي محتارة، وهي ملتزمة أيضًا هل توافق على مثل ذلك أم تنتظر رجلًا صالحًا؟","title":"حكم قبول خطبة شارب الشيشة","answer":"الجواب: الأفضل لها أن تنتظر؛ لأن شرب الشيشة يضرها ويؤذيها، فالأفضل لها أن تنتظر؛ لعل الله ييسر لها زوجًا صالحًا بعيدًا من هذه المعصية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17928/حكم-قبول-خطبة-شارب-الشيشة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79114.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":18844,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من الصومال مقديشو، وباعثها أخونا أحمد إبراهيم علمي -فيما يبدو- أخونا عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: رأيت في بعض الكتب المنتشرة عندنا في الصومال: أن الصحابة  كانوا يزدحمون على ماء وضوء سيدنا ونبينا محمد -عليه الصلاة والسلام- يتبركون به، وإذا تنخم أو بصق يأخذون ذلك ويتمسحون به، وازدحموا على الحلاق عند حلق رأسه ﷺ واقتسموا شعره، يتبركون به، وشرب عبد الله بن الزبير دمه ﷺ لما احتجم، وشربت أم أيمن بوله، فقال لها: \"صحة يا أم أيمن\" فما صحة ذلك؟ أفيدونا جزاكم الله خيرًا، وهل يجوز أن يقيس الناس على مثل هذه الأحوال إن كان ما ورد صحيحًا؟","title":"تبرك الصحابة بالنبي ﷺ وحكم قياس غيره عليه","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أنه قد ثبت عن رسول الله -عليه الصلاة والسلام- أن الصحابة  كانوا يتبركون بماء وضوئه، وبشعره -عليه الصلاة والسلام-، وببصاقه -عليه الصلاة والسلام-، ونخامته، كل هذا ثابت عنه -عليه الصلاة والسلام-، وعن الصحابة. فقد ثبت في حديث أبي جحيفة في الصحيحين في حجة الوداع: \"أنه لما خرج بلال بوضوئه ﷺ كان الصحابة يتناولون منه ما تيسر -هذا يأخذ قليلًا، وهذا يأخذ كثيرًا- من وضوئه -عليه الصلاة والسلام-\". وثبت في صلح الحديبية: أنه كان إذا تنخع نخاعة، أو بصق أخذها، تلقاها الصحابة، وجعلوا يدلكون بها أجسامهم؛ لما جعل الله فيه من البركة، ولما حلق في حجة الوداع قسم نصف الشعر بين الصحابة، والنصف الثاني أعطاه أبا طلحة . كل هذا ثابت عن النبي -عليه الصلاة والسلام-، وليس هناك شك عند أهل العلم في بركة جسمه ﷺ وشعره، وما مس جسمه، ووضوئه وعرقه -عليه الصلاة والسلام-. لكن لا يقاس عليه غيره؛ لأن الصحابة  ما فعلوا هذا مع الصديق، ولا مع عمر، ولا مع عثمان، ولا مع علي، وهم أفضل الصحابة، وخير الصحابة، وهم أفضل الناس بعد الأنبياء، فلو كان هذا مشروعًا أو جائزًا مع غير النبي ﷺ لفعله المسلمون مع هؤلاء الأخيار، ولأن ذلك قد يكون وسيلة إلى الشرك والغلو، فلهذا منعه أهل العلم. فالصحيح من أقوال أهل العلم: أنه لا يقاس على الرسول ﷺ أحد، بل هذا خاص به ﷺ؛ لما قد ثبت وعلم من بركته ﷺ في جسمه وعرقه وشعره وسائر أجزائه -عليه الصلاة والسلام-؛ ولأنه أقر الصحابة على ذلك، فلولا أنه جائز لما أقرهم، فلا يقاس عليه غيره؛ لأمور كثيرة. أما التبرك بالعلماء أو بالعباد الذي يفعله بعض الناس هذا غلط ولا يجوز؛ لأنه خلاف هدي الرسول ﷺ وأصحابه، فلم يفعله المسلمون مع فضلائهم وكبارهم: كالخلفاء الراشدين، ولم يفعلوه مع بقية الصحابة، ولو كان خيرًا لسبقونا إليه؛ ولأن العبادات توقيفية؛ ولأن هذا قد يفضي إلى الشرك والغلو، فلهذا رجح المحققون من أهل العلم منعه مع غير النبي -عليه الصلاة والسلام-. أما شرب ابن الزبير دمه وأم أيمن بوله: فهذا محل نظر، قد ورد هذا، ولكن في صحته نظر، فهو يحتاج إلى تمحيص ونظر، والنظر في أسانيد القصة، والأصل: تحريم الدم وتحريم البول، هذا هو الأصل، أن الله حرم علينا البول؛ لأنه نجس، وحرم الدم؛ لأنه من الخبائث وهو نجس، فإن صح فهذا يستثنى؛ لأن الرسول ﷺ له خصائص، فإذا صح فيكون من خصائصه ﷺ، كما قلنا في مسألة العرق، ومسألة الشعر، ومسألة البصاق، هذا خاص به، فهكذا إذا صح حديث أم أيمن وصح حديث ابن الزبير ؛ صار من الخصائص، وسوف نبحثه -إن شاء الله- ونعتني به، ويكون في حلقة أخرى -إن شاء الله-. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17980/تبرك-الصحابة-بالنبي-ﷺ-وحكم-قياس-غيره-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_878/nour_87801.mp3","categories":["نصائح وتوجيهات","التبرك وأنواعه"]},{"id":18864,"question":"مستمع بعث برسالة يقول فيها: (ع. س. م) يسأل في قضية خاصة به يقول: أنا شخص مريض بأمراض نفسية، وأتعالج من ذلك منذ فترة طويلة، وتنتابني كثير من أوقات الصخب، وأفقد رباطة جأشي في أوقات كثيرة، ويستمر في وصف حاله سماحة الشيخ، ويرجوكم في النهاية التوجيه، جزاكم الله خيرًا.","title":"النصح بالضراعة إلى الله في تفريج الكروب","answer":"الجواب: نوصيك بسؤال الله العافية، تسأل ربك أن الله يمن عليك بالشفاء والعافية، تجتهد في ذكر الله وطاعته ، وأبشر بالخير. المقصود: أن عليك الضراعة إلى الله، سؤال الله -جل وعلا- أبشر بسؤال الله أن يمن عليك بالعافية والسلامة من هذا الذي تشكو منه، والله -جل وعلا- هو الجواد الكريم، القائل سبحانه: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18004/النصح-بالضراعة-الى-الله-في-تفريج-الكروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73610.mp3","categories":["نصائح وتوجيهات"]},{"id":18901,"question":"من العراق رسالة بعثت بها إحدى الأخوات من هناك تقول: (س. س) من العراق، أود فضيلة الشيخ أن أطرح عليكم هذا السؤال، وأرجو أن تجيبوني عليه بأسرع وقت ممكن: هل يحق للرجل أن يخلو بالمرأة بعد أن خطبها، وقد كانت هذه الخطبة بوجود أبيه وأبيها، ووجود رجلين آخرين، وقد قال له أبوها: قد قبلت أن أزوجك ابنتي، وقد حدث هذا بوجود أبيه ورجلين آخرين، وبوجود الشاب أيضًا، فهل يعتبران زوجين حتى لو لم يتم تسجيل هذا العقد في محكمة شرعية؟أفيدونا أفادكم الله.","title":"حكم خلوة الخاطب بمخطوبته","answer":"الجواب: أما مجرد الخطبة، فليس له أن يخلو بها لمجرد الخطبة؛ لأنها أجنبية، وفي خلوته بها خطر، وربما وقع في الفاحشة، والنبي ﷺ قال: لا يخلون رجل بامرأة إلا مع ذي محرم وقال -عليه الصلاة والسلام-: لا يخلون رجل بامرأة؛ فإن الشيطان ثالثهما. ولكن إذا عقد له أبوها بحضرة شاهدين بأن قال: زوجتك، وقال الشاب: قبلت، وهي راضية بذلك، فإنها زوجته، له أن يخلو بها، وله أن يجامعها، لكن إذا كان ذلك قد يخالف عرف أهل البلد، وربما أفضى إلى سوء الظن بها، وأنها ربما تحمل، ويظن أنه من غير زوجها، فهذا لا ينبغي؛ إبعادًا عن سوء الظن وعن التهم. أما إذا خلا بها بإذن أهلها، وبعلم أهلها، واتصل بها بعد الزواج بعد العقد، فلا بأس بذلك، والأفضل أن يؤجل ذلك حتى يأتي الزفاف، حتى يتم الزفاف المعروف بينهما؛ حتى لا تكون هناك تهمة، وحتى لا يقع خطر في سوء الظن، والله المستعان، نعم.","link":"https://binbaz.org.sa/fatwas/18057/حكم-خلوة-الخاطب-بمخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_881/nour_88108.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":19014,"question":"يقول: لي صديق مؤمن بالله الحق، ويعيش مع عائلة يكسب رب أسرتها المال الحرام، أي: من القمار والاختلاس من الناس، علمًا أن هذه العائلة كما يقال: متطورة، أي: في إظهار المفاتن والتزين خارج المنزل، وقد وجه هذا الشخص النصائح الكثيرة الكثيرة إلى والده وإخوته، ولكن دون جدوى، وهو طالب في مدرسة مختلطة من الشبان والبنات، في الصف والمقعد، والبنات يظهرن المفاتن والمغريات أمام الشباب كلهم، ماذا يفعل أيترك البيت وليس له مورد؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الدراسة المختلطة والأكل من كسب الوالد الحرام","answer":"الجواب: الواجب على الناصح وهذا الشاب أن يتقي الله، وأن يغادر البيت ويبتعد عن أسباب الفتنة، وسوف يجعل الله له فرجًا ومخرجًا، إما بالسكن مع الطلبة إذا كان هناك سكن، أو بأسباب أخرى، يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] ، ويقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فعليه أن يتقي الله وأن يبتعد عن أسباب الفتنة، وكذلك المدرسة التي يدرس فيها لا يدرس فيها إذا كان مختلطة يلتمس عملًا يقوم بحاله ولا يدرس في هذه المدرسة، بل يدرس على العلماء في المساجد أو في مدارس أهلية، ليس فيها اختلاط، وليس طلب العلم عذرًا له في أن يجلس مع النساء والبنات ويختلط بهن، هذا مرض لقلبه ومرض لدينه، ومن أسباب هلاكه، فلا يجوز أن يجلس معهن في مقاعد الدراسة، ولا يبقى مع أهله ما داموا على الفساد والشر. أما النصيحة فيبذلها ويجتهد في النصيحة ويتابع النصيحة لعله يستجاب له، ولكن لا يجلس معهم ما دام أكلهم حرام وأعمالهم خبيثة فلا يجلس معهم؛ لأن الأكل ليس بسليم والأسرة غير سليمة، والاختلاط بهم فيه ما فيه من الشر. فالواجب أن يغادر المحل هذا، ويحذر، ولا مانع من الزيارة التي يريد بها النصيحة لوالديه وإخوته وأقاربه، أما الأكل والسكن فلينتقل إلى محل آخر يسلم فيه على دينه، وسوف يعينه الله ويسهل أمره كما قال تعالى: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، رزق الله الجميع التوفيق والهداية. نعم. المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18180/حكم-الدراسة-المختلطة-والاكل-من-كسب-الوالد-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92607.mp3","categories":["النظر والخلوة والاختلاط","نصائح وتوجيهات"]},{"id":19032,"question":"أيضًا تسأل أختنا وتقول: إني لا أحب الغيبة، لكن أحيانًا أكون في مجتمع من النساء يتكلمن في الغيبة، وبدون شعور مني أجد نفسي أشارك معهم، وعندما أراجع نفسي أندم ندمًا شديدًا على كلامي في أعراض إخواني المسلمين، وأستغفر الله، وأقول: لا أعود إلى الغيبة مرة أخرى، لكن أجد نفسي مرة أخرى أقع في الغيبة، ماذا أفعل كي أتخلص من هذه العادة السيئة التي انتشرت في المجتمع؟ وهي فيها من الوعيد والذم ما فيها؟أرجو أن تنصحوني، وتوجهوني وتدعو لي ولجميع المسلمين أن يسلمنا الله من الغيبة، وماذا أقول لمن يغتاب الناس؟ بارك الله فيكم.","title":"حكم مجالسة من يقعون في أعراض المسلمين","answer":"الجواب: نوصيك بعدم حضور المجالس التي فيها الغيبة، والاعتذار، وإذا قدر أنك حضرت فأنكري عليهم ولا تغتابي، قولي: يا عباد الله! هذا لا يجوز، هذا محرم، الله يقول سبحانه: وَلا يَغْتَبْ بَعْضُكُمْ بَعْضًا[الحجرات:12] والرسول ﷺ نهى عن ذلك، وأخبر أن الغيبة ذكرك أخاك بما يكره، قيل: يا رسول الله! فإن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول: فقد اغتبته، وإذا لم يكن فيه فقد بهته. وفي الحديث عنه ﷺ أنه قال: رأيت ليلة أسري بي قومًا لهم أظفار من نحاس يخمشون بها وجوههم وصدورهم، فقلت: يا جبرائيل من هؤلاء؟ قال: هؤلاء الذين يأكلوا لحوم الناس، ويقعون في أعراضهم يعني: هو من الغيبة، وهذا وعيد شديد. وإذا وقعت في ذلك فعليك التوبة إلى الله، واستسماح من وقعت فيه إن أمكن، تقولي: أبحني، سامحني، وقعت في عرضك، فإن لم يتيسر ذلك فأكثري من الاستغفار، والزمي التوبة، واذكري من اغتبت بالكلام الطيب الذي تعرفين عنه، اذكريه بالأخلاق الطيبة التي تعرفينه عنه، والأعمال الطيبة يعني: بدل ما ذكرتيه بالغيبة، والأشياء المكروهة؛ اذكريه في المجالس التي اغتبتيه فيها بالشيء الطيب الذي تعلمينه عنه، والأخلاق الطيبة التي تعرفينها عنه. فيكون هذا بهذا، مع التوبة والندم، والإقلاع والحذر، وهذه وصيتي لك ولجميع المسلمين، الوصية لجميع المسلمين: الحذر من الغيبة، والحذر من سائر المعاصي، وعدم مجالسة أهل الغيبة، وأهل المعاصي؛ لأن المجالسة لهم تجر المجالس إلى أعمالهم. فالمشروع للمؤمن ألا يجالس إلا من يعينه على الخير، وينفعه في دينه ودنياه، أما مجالسة من يجرك إلى الشر، ويدعوك إلى الشر؛ فلا تجوز، فالواجب الحذر دائمًا من مجالسة أهل المعاصي الظاهرة وأهل البدع، ومجالسة كل من يدعوك إلى باطل، وإلى ما يغضب الله عليك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18227/حكم-مجالسة-من-يقعون-في-اعراض-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79607.mp3","categories":["نصائح وتوجيهات"]},{"id":19049,"question":"سماحة الشيخ، يقول السائل: كيف التحرز من شرار الإنس، جزاكم الله خيرًا؟","title":"وسائل التحرز من شرار الإنس","answer":"الجواب: يتحرز منهم بالبعد عن مخالطتهم، لا يخالط الأشرار، يبتعد عنهم؛ حتى يسلم من شرهم، ويحرص على صحبة الأخيار؛ فمن حرص على صحبة الأخيار والبعد عن الأشرار سلمه الله من شرهم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18222/وساىل-التحرز-من-شرار-الانس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88315.mp3","categories":["نصائح وتوجيهات"]},{"id":19126,"question":"أخونا يذكر بعض تأثيرات الفيديو ويقول: إن كثيرًا من أفلام الفيديو تأتي من الغرب، ويمثلها أناس هم من الكفرة، ويمثلون أيضًا ما يقع بين الرجل وزوجته، ويذكر صورًا لا يليق بنا أن نذكرها في هذا المقام، ويرجو من سماحة الشيخ التوجيه: هل يتأثر الناس فيما بينهم فيما يخص الحياة الزوجية بما يكون في تلك الأفلام أم يجتنبوه؟","title":"التحذير من الأفلام الخبيثة الخليعة","answer":"الجواب: الواجب الاجتناب، الواجب الحذر من هذه الأفلام الخبيثة التي تصور النساء العاريات، أو الرجل مع زوجته، أو الزاني مع من زنى بها، أو تذكر اللواط واللائط مع من لاط به أو ما أشبه ذلك، كل هذه أفلام منكرة، وخبيثة وخليعة، يجب أن تحارب، ويجب ألا يسمح لها، ويجب أن يعاقب من يوردها إلى البلاد الإسلامية. ويجب على ولاة الأمور في كل بلد إسلامي أن يحارب هذه الأفلام الخبيثة من طريق الشرطة، ومن طريق مراقبة الكتب، ومن طريق مراقبة الأفلام، ومن طريق الإعلام، من كل طريق، مهما أمكن، يجب على ولاة الأمور أن يحاربوها بكل وسيلة، حتى لا تدخل البلاد، فإنه يترتب عليها فساد الأمة، والجرأة على ما حرم الله . فالواجب الحذر من ذلك ومنع هذا التيار الخبيث، نسأل الله العافية.\nالمقدم: نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/18311/التحذير-من-الافلام-الخبيثة-الخليعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_885/nour_88505.mp3","categories":["نصائح وتوجيهات"]},{"id":19171,"question":"شيخ عبد العزيز ، السؤال الأخير لأخينا في هذه الحلقة يقول: ما هو السبيل للحد من الفتن الكثيرة المنتشرة، ويمثل لها بعدة أمثلة شيخ عبد العزيز .الشيخ: منها؟المقدم: منها الغناء مثلًا، ومنها الفيديو، ومنها الألعاب، وغير ذلك؟","title":"الوسائل المعينة أمام الفتن والفساد","answer":"الجواب: على طالب العلم أن يتقي الله، وعلى المسلم أن يتقي الله، وعلى المسلمة أن تتقي الله، وأن تبتعد عن أسباب.. أن يبتعد كل منهم عن أسباب الهلكة، لا من جهة الأغاني؛ فإنها تصد عن سبيل الله، وتصد عن ذكر الله، وتقسي القلوب، وسماها الله لهو الحديث كما قال جل وعلا: وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ [لقمان:6]، قال أكثر العلماء: إن لهو الحديث هو الغناء وما يصحبه من آلات الملاهي، وقال ابن مسعود : إن الغناء ينبت النفاق في القلب كما ينبت الماء الزرع. فالواجب الحذر من ذلك، والتواصي بترك ذلك، وإذا كانت معه آلة الملاهي من ..... يسمعها الناس أو يراها الناس في الفيديو أو في التلفاز أو غير ذلك، كل هذه الأمور يجب على المؤمن والمؤمنة الحذر منها، وأن لا يسمعا من الإذاعة وأن لا يشاهدا من التلفاز إلا ما ينفعهم في دنياهم وأخراهم، وأن يحذر كل منهم أن يرى في التلفاز أو يسمع في الإذاعة ما يضره، بل يغلق التلفاز إذا رأى ما يضره، ويغلق المذياع إذا سمع ما يضره، فيكون حكيمًا حريصًا على الاستفادة فيأخذ الفائدة إذا جاءت، ويغلق الآلة عن الشر إذا جاء الشر، سواء كان وحده أو مع أهله، في الحضر أو في البر، مهما كان، فكما يسمع الفائدة من الإذاعة، في نور على الدرب أو في إذاعة القرآن أو ما أشبه ذلك يغلق إذا جاء الشيء الذي لا يرضاه في أي إذاعة. وهكذا التلفاز إن رأى ما ينفعه أخذه، وإن رأى ما يضره أغلقه، هذا إذا بلي به، فإن سلم منه وابتعد عنه خوفًا من شره، فهذا أطيب وأحسن. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18371/الوساىل-المعينة-امام-الفتن-والفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88704.mp3","categories":["نصائح وتوجيهات"]},{"id":19185,"question":"المستمع (س. س. ج) من اليمن بعث برسالة يقول فيها: سماحة الشيخ مشكلتي أن أختي تخرج من البيت كل يوم، ولا تبالي وذلك بالذهاب إلى صديقاتها، وأنا أخاف عليها من السوء ولا أستطيع منعها خوفًا من والدتي، ومن قبل كنت أضطر وأمنع أختي من الخروج من البيت بعد أن أتشاجر أنا ووالدتي، ويحصل غضب وخلاف وشجار طويل، وأفقد أعصابي وأضطر إلى التهديد، فماذا أفعل؛ لأني أخاف الله أن يعاقبني بأنني لا أهتم بأهلي ولا بأسرتي وأنا مهمل، وأخاف الله أن يعاقبني بسبب رفع صوتي على والدتي؛ لأني أتشاجر معها أحيانًا بسبب ذلك الموضوع؟ وجهوني جزاكم الله خيرًا.","title":"التوفيق بين بر الولد بأمه وتأديبه لأخته","answer":"الجواب: لا يجوز لك رفع صوتك على أمك، ولا التشاجر معها، بل يجب أن تخضع لبرها والإحسان إليها وعدم رفع الصوت عليها، يقول الله سبحانه: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء: 23-24]. ليس لك أن ترفع صوتك عليهما ولا أن تؤذيهما ولا أن تخاصمهما، بل عليك بالكلام الطيب والأسلوب الحسن، حتى ولو كانا كافرين، كيف بالمسلمين؟! يقول الله في شأن الكافرين: وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]. أما أختك فإن كانت تخرج للريبة تمنعها من دون كلام مع والديك، وأما إذا كانت -بحمد الله- لا ريبة عندها، ولا خطر عليها، فدع عنك الشكوك والأوهام التي توقعك فيما لا ينبغي، ابتعد عن الأوهام القبيحة والشكوك الرديئة، والظن الذي لا وجه له. وأما إذا كان هناك أمر منكر تعرفه من أختك فامنعها، فامنعها بالكلام الطيب والأسلوب الحسن والتعاون مع الوالدين بالأسلوب الحسن. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18405/التوفيق-بين-بر-الولد-بامه-وتاديبه-لاخته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73801.mp3","categories":["نصائح وتوجيهات"]},{"id":19239,"question":"أحد الإخوة المستمعين من جمهورية مصر العربية يسأل مرة أخرى ويقول: توجد قرية بجوارنا حدث فيها أن امرأة صعدت النخلة، وتعيش فوقها ليل نهار، وهذا في فصل الشتاء، والبرد قارس، علمًا بأن النخلة ارتفاعها حوالي خمسة وثلاثين متر تقريبًا، وابن هذه المرأة يتولاها من طعام وشراب، وكل الناس قالوا: إن هذه المرأة من أولياء الله الصالحين، ويقولون لها: ادع لنا بكذا وكذا، ويذهبون إليها للتبرك، أي: لتحفهم البركة، فما رأي الشرع في هذه الاعتقادات، وهل المرأة فعلًا من أولياء الله الصالحين أم لا؟ أفيدونا أفادكم الله وبارك الله فيكم.","title":"حكم التبرك بامرأة تعيش فوق نخلة واعتقاد أنها ولية","answer":"الجواب: هذا العمل إن صح فهو من أعمال الشياطين، والشياطين هم الذين رفعوها إلى هذا المكان، وجعلوا يثبتونها فيه؛ ليضلوا الناس ويوهموا الناس أنها ولية لله حتى تدعى من دون الله، وحتى يستغاث بها وحتى يتبرك بها، فهذا من الباطل الواضح ومن المنكر الفاضح، والواجب على أوليائها أن ينزلوها من هذه الشجرة، وأن يبقوها في البيت، ويحافظوا عليها ويحسنوا إليها، ويرشدوها إلى الحق والصواب، وأن يحضروا من أهل العلم الشرعي المعروفين من أنصار السنة حتى يعظوها ويذكروها ويعلموها. ولا يجوز لأحد أن يغلو فيها أو يعتقد أن هذه كرامة، أو أنها ولية لله، بل هي من أولياء الشيطان بهذا العمل، هي من أولياء الشيطان بهذا العمل، فالواجب على ذوي العقول وعلى ذوي البصيرة أن يحذروا مثل هذه الخرافات وهذه الترهات وهذه الوسائل الشيطانية التي تضل الناس عن الحق، والشياطين لهم نفوذ في إضلال الناس، ولهم أعمال كثيرة في إضلال الناس عن الحق، وكل عاقل يعلم أن هذا العمل ليس عمل امرأة عاقلة مؤمنة، ولكنه عمل امرأة مجنونة قد سلب عقلها أو لعبت بها الشياطين، نسأل الله السلامة، رزق الله الجميع العافية والهداية. نعم. المقدم: أو أنه أسلوب من أساليب أكل الخبز سماحة الشيخ؟ الشيخ: قد يكون مكذوبًا، قد يكون كذبًا، لكن إذا كانت تشاهد، فقد يكون الجن صوروا لهم امرأة، قد تكون معروفة عندهم، فحملها الشياطين، الشياطين قد يحملونها إلى جبال وإلى .. وإلى بلدان كثيرة، قد يفعله الشياطين، نص شيخ الإسلام ابن تيمية على هذا وغيره من أهل العلم، أن الشياطين قد تحمل بعض الناس إلى أماكن كثيرة. نعم. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله العافية. نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/18438/حكم-التبرك-بامراة-تعيش-فوق-نخلة-واعتقاد-انها-ولية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_891/nour_89108.mp3","categories":["نصائح وتوجيهات","التبرك وأنواعه"]},{"id":19274,"question":"هل الدبلة -الخاتم- الذي يقدمه الخاطب لمخطوبته حلال أم حرام مع الدليل؟ وهل صحيح إنه فكرة نصرانية؟","title":"حكم إهداء الخاطب دبلة لمخطوبته","answer":"الجواب: لا أعلم له أصلًا، ولم يكن من عادة المسلمين، والذي سمعنا أنه من عادة النصارى، وأنه ورد إلى الناس من لبنان وغيره، فالذي أرى أن ترك ذلك هو الذي ينبغي، هو أسلم وأبعد عن مشابهة الكفرة، ولم يبلغنا عن سلفنا الصالح أنهم كانوا يفعلون شيئًا من ذلك، وإنما يخطب المرأة، ثم يقدم ما تيسر من المهر، ويكفي هذا؛ أما الدبلة والشبكة فلا لها أصل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18458/حكم-اهداء-الخاطب-دبلة-لمخطوبته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_892/nour_89204.mp3","categories":["الخِطْبَة والاختيار ","نصائح وتوجيهات"]},{"id":19374,"question":"يسألان أيضًا هذا  أب له دكان ويبيع السجاير، وابنه يمتنع من بيعها؛ لأنه يعتقد تحريمها، وحينئذ الأب يدعو على ابنه، ويمنعه من طلب العلم، فهل يقبل دعاء الأب في هذه الحالة؟ وهل يجوز معصية الأب لطلب العلم، علمًا أنه مستغنٍ عن ابنه هذا بغيره من الأولاد يعملون معه؟ أفتونا مأجورين بارك الله فيكم.","title":"حكم طاعة الولد والده في معصية الله عز وجل","answer":"الجواب: يقول النبي ﷺ في الحديث الصحيح: إنما الطاعة في المعروف ويقول عليه الصلاة والسلام: لا طاعة لمخلوق في معصية الخالق فإذا أمر الوالد الولد بشيء منكر لم يلزم الولد السمع والطاعة في ذلك. وعليه أن يعالج الموضوع بالحكمة والكلام الطيب مع الوالد، ويبين له أن هذا الشيء لا يجوز لما فيه من المضرة العظيمة والشر الكثير. ويرجو منه المسامحة في عدم مساعدته على هذا الشيء، ولا يستجيب إلى مساعدته في بيع الدخان أو أنواع الخمور، أو غير هذا مما حرم الله ، ولكن يكون بالكلام الطيب والأسلوب الحسن؛ لأن الوالد له حق عظيم، والله يقول: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ [لقمان:14]، ويقول جل وعلا: وَإِنْ جَاهَدَاكَ عَلى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]. فأمر بمصاحبتهما في الدنيا معروفًا مع كونهما يأمران بالشرك، فدل ذلك على أن حقهما عظيم، وأن الواجب على الولد الرعاية لهذا الحق بكل ما يستطيع من دون أن يطيع والديه في المعصية. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18595/حكم-طاعة-الولد-والده-في-معصية-الله-عز-وجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93404.mp3","categories":["نصائح وتوجيهات"]},{"id":19424,"question":"إذا كنت أقيم بمنطقة جبلية وأريد أن أحج، فأي الكتب تنصحوني بقراءتها كي أحج على بصيرة؟ جزاكم الله خيرًا.","title":"كتب ينصح بقراءتها لمن أراد الحج والعمرة","answer":"الجواب: ننصحك بقراءة الكتب التي بينت أحكام الحج، مثل عمدة الحديث للشيخ عبد الغني المقدسي، مثل بلوغ المرام، مثل المنتقى هذه موجودة، وهناك مناسك فيها كفاية وبركة، إذا قرأتها استفدت منها، منها منسك كتبناه في هذا وسميناه: التحقيق والإيضاح لكثير من مسائل الحج والعمرة والزيارة وهو جيد ونافع ومفيد، وهناك مناسك أخرى لغيري من المشايخ والإخوان، مثل منسك الشيخ عبد الله بن جاسم منسك جيد ومفيد، فإذا استعملت شيئًا منه واستفدت منه طيب. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18659/كتب-ينصح-بقراءتها-لمن-اراد-الحج-والعمرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73614.mp3","categories":["مسائل متفرقة في الحج والعمرة","العالم والمتعلم","نصائح وتوجيهات"]},{"id":19521,"question":"هل من توجيه كريم للآباء والأمهات في توجيه أولادهم في السن المبكرة لتعويدهم على الأمور الشرعية؟","title":"نصيحة للآباء والأمهات بتوجيه الأبناء في الأمور الشرعية","answer":"الجواب: نعم، الواجب على الآباء والأمهات تعليم الأولاد وتوجيههم إلى الخير، تعليم البنين والبنات، وإرشادهم فيما يتعلق بالصوم والصلاة، وما يتعلق بحيض المرأة وغير ذلك، يجب على الأب والأم إرشاد الأولاد يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا [التحريم:6]، الله جل وعلا أمرهم بهذا.\nوقال ﷺ: كلكم راع وكلكم مسئول عن رعيته، فالرجل راع في أهل بيته ومسئول عن رعيته، والمرأة راعية في بيت زوجها ومسئولة عن رعيتها كلهم راع. فالواجب على الأب أن يعتني بالأولاد وأن يرشدهم، وهكذا الأم، كلهم مسئولون فَوَرَبِّكَ لَنَسْأَلَنَّهُمْ أَجْمَعِينَ  ۝ عَمَّا كَانُوا يَعْمَلُونَ [الحجر:92، 93]. فالأب يعلم أولاده الذكور والإناث، والأم كذلك حتى ينشئوا على خير وعلى هدى وعلى بصيرة.\nنسأل الله للجميع الهداية. المقدم: اللهم آمين، أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18768/نصيحة-للاباء-والامهات-بتوجيه-الابناء-في-الامور-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93934.mp3","categories":["تربية الأولاد","نصائح وتوجيهات","الهبة والعطية","فتاوى متنوعة"]},{"id":19628,"question":"يقول في سؤال له يا سماحة الشيخ! هل الأفضل في الشرع الزواج من الأقارب أم من البعيدين، وما توجيهكم حفظكم الله في استقرار الحياة الزوجية، هل هي مع القريب، أم البعيد أفضل مأجورين؟","title":"هل الأفضل الزواج من الأقارب أم من غيرهم؟","answer":"الجواب: الأفضل التماس الزوجة الصالحة، سواء من الأقارب أو من غير الأقارب؛ لأن الرسول عليه الصلاة والسلام قال: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها، فاظفر بذات الدين تربت يداك . فإذا تيسرت ذات الدين سواء كانت من الأقارب أو من غير الأقارب هذا هو المطلوب، وإذا كانت ذات الدين من غير الأقارب فهي أفضل، المهم ذات الدين سواء كانت بنت عمك، أو بنت خالك، أو أبعد من ذلك لا بأس كله طيب، وإذا كان هناك اثنتان إحداهما قريبة، والثانية ما هي بقريبة، لكن القريبة هي ذات الدين فالقريبة أولى، كلما كانت ذات الدين فهي أفضل سواء من الأقارب أو من غيرهم.","link":"https://binbaz.org.sa/fatwas/18897/هل-الافضل-الزواج-من-الاقارب-ام-من-غيرهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94828.mp3","categories":["نصائح وتوجيهات","الزواج وأحكامه"]},{"id":19657,"question":"تقول هذه السائلة يا سماحة الشيخ، امرأة كانت تأخذ من المصروف الذي خصصه لها زوجها، فتشتري حاجات مباحة لأناس لا يرغب فيهم هذا الزوج، ثم حصل الفراق بينها وبينه وهي نادمة الآن، فهل عليها إثم؟ وكيف الخلاص من ذلك إن كان ذنبًا؟","title":"حكم أخذ الزوجة من مال زوجها بغير إذنه","answer":"الجواب: ليس لها ذلك، ليس لها أن تخرج من ماله إلا بإذنه، ما دام نهاها أن تعطيهم ليس لها أن تعطيهم إلا بإذنه إلا من مالها، فإذا طلقها وهي تعرف ما أخرجت، فالأحوط لها أن ترده عليه أو تستأذنه أو تستبيحه تقول له: إني فعلت كذا سامحني، أو ترد عليه ما أخذت. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18941/حكم-اخذ-الزوجة-من-مال-زوجها-بغير-اذنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95011.mp3","categories":["النفقات","الحقوق الزوجية","قضايا المرأة","نصائح وتوجيهات"]},{"id":19699,"question":"ما رأيك يا سماحة الشيخ بالكشَّافة من خلال ما تسمع عنها؟والشق الثاني: قد يكون سؤالًا خاصًّا، ولكن ورد في أكثر من ورقةٍ: ما أُمنيتك يا شيخ؟","title":"الكشافة المدرسية وأمنية الشيخ بن باز رحمه الله","answer":"الجواب: أما الأول: فالذي بلغني عن الكشافة أنهم دالين على الخير، وينفعون الناس، ويُرشدون إلى الخير في الحجِّ، وفي المجتمعات التي يحضرونها، وتُوكل إليهم، فوصيتي لهم أن يكونوا أداةَ خيرٍ، وأداة إصلاحٍ أينما كانوا، فالذي بلغني عنهم هو أنهم يُرشدون إلى الخير، ويُوجّهون إلى إرشاد الناس: إرشاد الطلبة، إرشاد الحجيج، إرشاد المحتفلين في أي حفلةٍ، توجيههم إلى الخير. فوصيتي للكشافة جميعهم أن يكونوا أداة خيرٍ، وأداة توجيهٍ، وأداة إصلاحٍ، يدعون إلى الخير، ويأمرون بالخير، وينهون عن الشر، وينصحون لله ولعباده أينما كانوا، ويُؤدون الأمانة فيما أوكل إليهم من دقيقٍ وجليلٍ، حتى تكون هذه المنة كاملةً، وحتى تكون الأمانة وافيةً، هذه وصيتي لهم: أن يؤدوا الأمانة بكل نصحٍ، وبكل عنايةٍ، وبكل صدقٍ أينما كانوا: في مدرسةٍ، أو معهدٍ، أو حجٍّ، أو حفلةٍ في زواج، أو في غير هذا، في أي مكانٍ وكل إليهم العناية به، وملاحظته، أن يؤدوا الأمانة، وأن يكونوا أداة خيرٍ، وأداة إصلاحٍ، وأداة توجيهٍ فيما يُحبُّه الله ويرضاه. وأما أمنيتي في هذه الحياة: أمنيتي أن الله جلَّ وعلا ينصر دينه، ويُعلي كلمته، ويُصلح أحوال المسلمين، ويُولِّي عليهم خيارهم في كل مكانٍ، وأن يُعيذهم من مكائد الأعداء، وشرِّ أنفسهم والشيطان؛ لأنَّ هذه هي التي يتمناها كل مسلم، وكل صادقٍ، وكل ناصحٍ لله ولعباده: أن يرى إخوانه على الخير والهدى والاستقامة، وأن يراهم مُوفَّقين في أعمالهم، وفي جميع سيرتهم، ويراهم قد تولاهم مَن يقوم بشؤونهم، ويعتني بشؤونهم، ويتَّقي الله فيهم، ويُقيم فيهم أمر الله، هكذا يتمنى كل مسلمٍ لإخوانه المسلمين. وفَّق الله الجميع، وصلَّى الله وسلَّم على نبينا محمدٍ، وعلى آله وأصحابه.","link":"https://binbaz.org.sa/fatwas/20537/الكشافة-المدرسية-وامنية-الشيخ-بن-باز-رحمه-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0504%D9%81%D8%AA%D8%A7%D9%88%D9%89%20%D8%A7%D9%84%D9%85%D8%AD%D8%A7%D8%B6%D8%B1%D8%A7%D8%AA%20%D9%84%D9%84%D8%B4%D9%8A%D8%AE%20%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2%20%D8%A8%D9%86%20%D8%A8%D8%A7%D8%B2%20%D8%B1%D8%AD%D9%85%D9%87%20%D8%A7%D9%84%D9%84%D9%87.mp3","categories":["نصائح وتوجيهات"]}]
